window.MDCAT_QUESTIONS = [{"id": "paper_d_q1_1", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 1, "subject": "Biology", "topic": "antidiuretic hormone", "question": "Kidneys perform their osmoregulatory role under the effect of Antidiuretic\n      Hormone, which type of urine is produced in this situation?", "options": ["Hypotonic urine with decreased volume", "Hypotonic urine with increased volume", "Hypertonic urine with decreased volume", "Hypertonic urine with increased volume"], "correctIndex": 2, "explanation": "ADH increases water reabsorption in the collecting ducts, concentrating\n        the urine and reducing its volume, so urine becomes hypertonic with\n        decreased volume. The hypotonic options are incorrect because ADH does\n        not cause dilution of urine.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 1, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "UHS 2025 Q#1 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_d_q2_2", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 2, "subject": "Biology", "topic": "sleep wakefulness", "question": "Which part of brain controls transition between sleeping and wakefulness?", "options": ["Medulla oblongata", "Cerebellum", "Cerebrum", "Pons"], "correctIndex": 3, "explanation": "The pons (and adjacent reticular formation) is centrally involved in\n        regulating sleep–wake transitions and REM processes. The cerebrum and\n        cerebellum are involved in higher processing and coordination, while the\n        medulla controls autonomic functions rather than sleep–wake switching.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 2, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "UHS 2025 Q#2 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_d_q3_3", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 3, "subject": "Biology", "topic": "central chemoreceptors", "question": "Which part of the brain contains central chemoreceptors that monitor CO2\n      levels in blood?", "options": ["Pons", "Midbrain", "Hypothalamus", "Medulla oblongata"], "correctIndex": 3, "explanation": "Central chemoreceptors that detect CO2 (via pH changes in cerebrospinal\n        fluid) are located in the medulla oblongata. The pons, midbrain and\n        hypothalamus have other regulatory roles but are not the primary CO2\n        chemoreceptor sites.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 3, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "UHS 2025 Q#3 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_d_q4_4", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 4, "subject": "Biology", "topic": "reflex arc", "question": "Which component of a reflex arc connects the sensory neuron to the motor\n      neuron within the spinal cord?", "options": ["Receptor", "Effector", "Muscle fiber", "Associative neuron"], "correctIndex": 3, "explanation": "The associative (interneuron) within the spinal cord links incoming\n        sensory neurons to outgoing motor neurons. Receptors detect stimuli and\n        effectors (like muscle fibers) execute responses; they do not form the\n        internal connection.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 4, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "UHS 2025 Q#4 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_d_q5_5", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 5, "subject": "Biology", "topic": "mendelian ratios", "question": "The 9.3.3.1 ratio of law of Independent assortment can be affected by", "options": ["Genetic drift", "Small population", "Gene linkage", "Gene duplication"], "correctIndex": 2, "explanation": "Linkage between genes on the same chromosome prevents independent\n        assortment, altering expected Mendelian ratios like 9:3:3:1. Genetic\n        drift and small population affect allele frequencies but do not directly\n        change segregation ratios in a single cross; gene duplication is\n        unrelated to assorting of existing loci.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 5, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "UHS 2025 Q#5 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_d_q6_6", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 6, "subject": "Biology", "topic": "crossing over", "question": "Best description of the process of crossing over during meiosis:", "options": ["Duplication of chromosome", "Exchange of genes between non-sister chromatids", "Movement of chromosome to opposite poles", "Separation of sister chromatids"], "correctIndex": 1, "explanation": "Crossing over is the reciprocal exchange of genetic material between\n        non-sister chromatids of homologous chromosomes during prophase I,\n        creating new allele combinations. The other options describe separate\n        meiotic events (duplication precedes meiosis; segregation and movement\n        happen later).", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 6, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "UHS 2025 Q#6 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_d_q7_7", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 7, "subject": "Biology", "topic": "linkage groups", "question": "Total number of linkage groups in a normal human is:", "options": ["02", "23", "46", "92"], "correctIndex": 1, "explanation": "A linkage group corresponds to a chromosome; humans have 23 distinct\n        chromosomes (haploid number). 46 is the diploid chromosome count; 2 and\n        92 are incorrect.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 7, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "UHS 2025 Q#7 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_d_q8_8", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 8, "subject": "Biology", "topic": "nissl granules", "question": "Nissls granule is a specialized structure in neuron formed by modification\n      of :", "options": ["Golgi bodies & Smooth ER", "Peroxisome & Mitochondria", "Lysosome & Vacuole", "Ribosome & Rough ER"], "correctIndex": 3, "explanation": "Nissl bodies are clusters of rough endoplasmic reticulum studded with\n        ribosomes in neurons, so they are modified rough ER and associated\n        ribosomes. The other organelles listed are not the source of Nissl\n        substance.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 8, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "UHS 2025 Q#8 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_d_q9_9", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 9, "subject": "Biology", "topic": "centromere function", "question": "What is the function of a centromere?", "options": ["To protect the ends of chromosomes", "To hold sister chromatids together", "To carry genetic information", "To initiate DNA replication"], "correctIndex": 1, "explanation": "The centromere is the constricted region where sister chromatids are\n        joined, enabling their proper attachment to the mitotic spindle and\n        segregation. It does not protect chromosome ends (telomeres) nor\n        directly carry genetic information or initiate replication.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 9, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2025 Q#9 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q10_10", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 10, "subject": "Biology", "topic": "lysosome functions", "question": "All are the functions of lysosome EXCEPT:", "options": ["Intra cellular digestion", "Removal of the waste", "Autophagy", "Lipid synthesis"], "correctIndex": 3, "explanation": "Lysosomes carry out intracellular digestion, autophagy and removal of\n        cellular waste by hydrolytic enzymes. They are not sites of lipid\n        synthesis, which occurs mainly in the smooth endoplasmic reticulum.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 10, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2025 Q#10 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q11_11", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 11, "subject": "Biology", "topic": "lymphatic blockage", "question": "The first consequence of lymphatic blockage in tissues is:", "options": ["Deficiency of oxygen", "Loss of nerve signals", "Drop in blood pressure", "Excess fluid accumulation in tissue"], "correctIndex": 3, "explanation": "Blockage of lymphatic drainage prevents removal of interstitial fluid,\n        causing a local accumulation (lymphedema). Oxygen deficiency or systemic\n        blood pressure changes are not the immediate primary effect of localized\n        lymphatic blockage.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 11, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "UHS 2025 Q#11 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_d_q12_12", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 12, "subject": "Biology", "topic": "nerve impulse pathway", "question": "Which of the following is the correct pathway of nerve Impulse?", "options": ["Receptors--> CNS--> Effectors", "Effectors--> Receptors--> CNS", "CNS--> Effectors--> Receptors", "Effectors--> CNS --> Receptors"], "correctIndex": 0, "explanation": "A sensory stimulus is detected by receptors, the signal is transmitted\n        to the central nervous system (CNS) for processing, and then motor\n        outputs are sent to effectors. The other orders reverse this logical\n        flow.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 12, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "UHS 2025 Q#12 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_d_q13_13", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 13, "subject": "Biology", "topic": "neurotransmitter release", "question": "The neurotransmitters are secreted by the neuron from:", "options": ["Axon ends", "Dendrite end", "Nissl's granules", "Cell body"], "correctIndex": 0, "explanation": "Neurotransmitters are stored in synaptic vesicles at axon terminals and\n        released into the synaptic cleft from the axon ends. Dendrites, Nissl\n        substance and the cell body are not the primary secretory sites for\n        neurotransmitter release.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 13, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "UHS 2025 Q#13 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_d_q14_14", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 14, "subject": "Biology", "topic": "hippocampus function", "question": "Hippocampus plays an important role in the:", "options": ["Formation of short-term memory", "Formation of image on retina", "Formation of long-term memory", "Formation of emotions"], "correctIndex": 2, "explanation": "The hippocampus is key for converting short-term memories into long-term\n        declarative memories and for memory consolidation. It is not involved in\n        forming retinal images or primarily generating emotions (limbic\n        structures mediate emotions).", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 14, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2025 Q#14 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q15_15", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 15, "subject": "Biology", "topic": "enzyme denaturation by ph", "question": "Enzymes activity decreases at very low or high pH because:", "options": ["Substrate concentration increases", "Enzymes become denatured", "Product formation increases", "Temperature becomes constant"], "correctIndex": 1, "explanation": "Extreme pH alters ionic bonds and the three-dimensional structure of\n        enzymes, leading to denaturation and loss of catalytic activity. Changes\n        in substrate concentration or temperature are not the direct cause in\n        this context.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 15, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2025 Q#15 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q16_16", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 16, "subject": "Biology", "topic": "base pairing in dna", "question": "The complementary base pairing in DNA is important because it:", "options": ["Maintains the tertiary structure of enzymes", "Provides energy for all cell metabolism", "Enables protein to fold properly", "Allows DNA act as a genetic blueprint during replication"], "correctIndex": 3, "explanation": "Complementary base pairing ensures accurate copying of genetic\n        information during DNA replication, because each strand serves as a\n        template for a complementary strand. The other choices describe\n        unrelated roles.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 16, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2025 Q#16 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q17_17", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 17, "subject": "Biology", "topic": "duplicated chromosome structure", "question": "A mature duplicated chromosome consists of:", "options": ["Two identical double helical DNA molecules", "Two different double helical DNA molecules", "A double helical DNA molecule distributed in both chromatids", "Histone chains wrapped around DNA core"], "correctIndex": 0, "explanation": "After DNA replication, a duplicated chromosome contains two identical\n        DNA double helices (sister chromatids) held together at the centromere.\n        They are identical copies, not different molecules; histones wrap DNA\n        but do not describe the duplicated chromosome content.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 17, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "UHS 2025 Q#17 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_d_q18_18", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 18, "subject": "Biology", "topic": "primitive respiration", "question": "The most primitive respiratory process occurring in a living cell is;", "options": ["Lactic acid fermentation", "Alcoholic fermentation", "Glycolysis", "Krebs's cycle"], "correctIndex": 2, "explanation": "Glycolysis is a universal, ancient pathway for ATP production that\n        occurs anaerobically and is considered the most primitive. Fermentation\n        pathways are downstream of glycolysis; the Krebs cycle is aerobic and\n        evolved later.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 18, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2025 Q#18 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q19_19", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 19, "subject": "Biology", "topic": "uterine function", "question": "Receive, retain and nourish a fertilized ovum is the main function of:", "options": ["Cervix", "Uterus", "Ovary", "Oviduct"], "correctIndex": 1, "explanation": "The uterus provides the site for implantation and nourishes the\n        developing embryo/fetus. Oviducts transport the ovum and fertilization\n        may occur there; ovaries produce gametes and hormones; the cervix is the\n        lower uterine opening.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 19, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2025 Q#19 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q20_20", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 20, "subject": "Biology", "topic": "larynx function", "question": "The primary function of larynx is:", "options": ["Humidifying air", "Filtering dust", "Gaseous exchange", "Voice production"], "correctIndex": 3, "explanation": "The larynx houses the vocal cords and its primary role is voice\n        production. Humidifying and filtering are functions of nasal passages;\n        gaseous exchange occurs in alveoli.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 20, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2025 Q#20 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q21_21", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 21, "subject": "Biology", "topic": "lh secretion", "question": "During menstrual cycle, luteinizing hormone (LH) is secreted due to;", "options": ["Decrease in Estrogen", "Decrease in FSH", "Increase in FSH", "Environmental effect"], "correctIndex": 2, "explanation": "Clinically, the LH surge is triggered by rising ovarian hormones\n        (primarily estrogen) and interactions with FSH; among the provided\n        choices 'Increase in FSH' is the closest stimulus listed. (Note: the\n        precise physiological trigger is a high estrogen level causing positive\n        feedback on the pituitary, producing the LH surge.)", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 21, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "UHS 2025 Q#21 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_d_q22_22", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 22, "subject": "Biology", "topic": "corpus callosum", "question": "Left and right cerebral hemispheres are connected with each other by:", "options": ["Corpus luteum", "Corpus callosum", "A band of dendrites", "Dorsal and ventral nerve roots"], "correctIndex": 1, "explanation": "The corpus callosum is the large white-matter tract that connects the\n        two cerebral hemispheres, allowing interhemispheric communication.\n        Corpus luteum is an ovarian structure; the other options are incorrect\n        anatomical connections.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 22, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2025 Q#22 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q23_23", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 23, "subject": "Biology", "topic": "muscle features", "question": "Which is the common feature between cardiac and smooth muscles?", "options": ["Voluntary", "Involuntary", "Branched", "Unbranched"], "correctIndex": 1, "explanation": "Both cardiac and smooth muscles are under involuntary control (autonomic\n        regulation). Cardiac muscle is branched, smooth muscle is unbranched,\n        and neither is voluntary.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 23, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "UHS 2025 Q#23 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_d_q24_24", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 24, "subject": "Biology", "topic": "joint types", "question": "The joints which cause rotational movements are", "options": ["Hinge", "Ball and Socket", "Cartilage", "Sutures"], "correctIndex": 1, "explanation": "Ball-and-socket joints (e.g., shoulder, hip) allow rotation and\n        multi-axial movement. Hinge joints permit flexion/extension only;\n        sutures are immovable joint types; 'cartilage' is not a joint\n        classification for rotation.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 24, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "UHS 2025 Q#24 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_d_q25_25", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 25, "subject": "Biology", "topic": "self fertilization", "question": "Self-fertilization in plants through successive generations can lead to\n      the development of:", "options": ["Hybrid breeds of plants", "Variations in coming generation", "True breeding plants", "Adaptation with their environment"], "correctIndex": 2, "explanation": "Repeated self-fertilization (inbreeding) tends to produce homozygous\n        lines that breed true for traits (true-breeding). It does not generate\n        hybrids or increased variation; adaptation is an ecological process, not\n        the immediate genetic consequence.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 25, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "UHS 2025 Q#25 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2025"}, {"id": "paper_d_q26_26", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 26, "subject": "Biology", "topic": "dendrites", "question": "Which part of the neuron typically receives incoming signals from other\n      neurons?", "options": ["Axon", "Dendrites", "Myelin sheath", "Synaptic knob"], "correctIndex": 1, "explanation": "Dendrites receive synaptic inputs from other neurons; axons transmit\n        outgoing action potentials. The myelin sheath insulates axons and\n        synaptic knobs are presynaptic terminals.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 26, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "UHS 2025 Q#26 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_d_q27_27", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 27, "subject": "Biology", "topic": "muscle contraction regulation", "question": "Why thick filaments are unable to bind with thin filament in a relaxed\n      muscle fiber?", "options": ["Actin blocks the myosin binding site", "Tropomyosin blocks the myosin binding site", "Troponin blocks the myosin binding site", "Tropomyosin blocks the troponin binding site"], "correctIndex": 1, "explanation": "In relaxed muscle tropomyosin lies in the groove of actin filaments and\n        physically blocks myosin-binding sites; troponin regulates tropomyosin's\n        position in response to Ca2+. The other options misattribute the\n        blocking role.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 27, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "UHS 2025 Q#27 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_d_q28_28", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 28, "subject": "Biology", "topic": "proteins in immunity", "question": "Which of the following best highlights the importance of proteins in\n      Immunity?", "options": ["They act as receptors of pathogens", "They are long term energy reserves", "They act as antibodies", "They act as mechanical barrier to pathogens"], "correctIndex": 2, "explanation": "Antibodies are proteins produced by B cells that specifically recognize\n        and neutralize pathogens; proteins also form receptors but antibodies\n        are the key immune proteins. Proteins are not long-term energy reserves\n        nor primary mechanical barriers.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 28, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2025 Q#28 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q29_29", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 29, "subject": "Biology", "topic": "protein secondary structure", "question": "The secondary structure of proteins is stabilized by:", "options": ["Ionic bonds", "Hydrogen bonds", "Disulfide bridges", "Hydrophobic exclusion"], "correctIndex": 1, "explanation": "Alpha helices and beta sheets (secondary structures) are stabilized\n        primarily by hydrogen bonds between backbone amide and carbonyl groups.\n        Disulfide bridges stabilize tertiary structure; ionic interactions and\n        hydrophobic effects also contribute at higher structural levels.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 29, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2025 Q#29 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q30_30", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 30, "subject": "Biology", "topic": "globular protein example", "question": "The following is an example of a globular protein.", "options": ["Keratin", "Collagen", "Hemoglobin", "Histone"], "correctIndex": 2, "explanation": "Hemoglobin is a classic globular protein that is soluble and functional\n        in transport. Keratin and collagen are fibrous structural proteins;\n        histones are also globular but hemoglobin is the standard example among\n        these options.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 30, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2025 Q#30 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q31_31", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 31, "subject": "Biology", "topic": "osmoregulation definition", "question": "The process of osmoregulation refers to:", "options": ["The filtration of blood to remove metabolic waste", "The regulation of solute and water movement between an organism and\n          its environment", "The creation of an osmotic gradient in the kidney medulla", "The secretion of hormones that control blood plasma"], "correctIndex": 1, "explanation": "Osmoregulation is the control of water and solute concentrations across\n        membranes and between an organism and its environment. While kidneys\n        create osmotic gradients and hormones modulate fluid balance, the broad\n        definition is regulation of solute and water movement.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 31, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "UHS 2025 Q#31 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_d_q32_32", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 32, "subject": "Biology", "topic": "x linked hemophilia", "question": "A baby girl is born with hemophilia, which is an X-linked recessive\n      disorder. What are the most likely genotypes of her parents?", "options": ["The mother is a carrier and the father is normal.", "The mother is hemophiliac and the father is normal.", "The mother is carrier and the father is hemophiliac", "Both are normal."], "correctIndex": 2, "explanation": "For a female to express an X-linked recessive disease she must inherit\n        an affected X from her father and a carrier (or affected) X from her\n        mother; thus a carrier mother and hemophiliac father (option c) is the\n        likely parental genotype. A normal father cannot pass an affected X to a\n        daughter.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 32, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2025 Q#32 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q33_33", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 33, "subject": "Biology", "topic": "chromosome function", "question": "Identify the most appropriate function of chromosomes", "options": ["Energy production and storage", "Protein synthesis and regulation", "Storage of genetic information", "Lipid metabolism and transport"], "correctIndex": 2, "explanation": "Chromosomes carry and organize DNA, whose primary role is storage and\n        transmission of genetic information. The other options describe cellular\n        metabolic functions not performed by chromosomes.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 33, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "UHS 2025 Q#33 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_d_q34_34", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 34, "subject": "Biology", "topic": "enzyme class", "question": "Enzymes belong to which class of biomolecules?", "options": ["Carbohydrates", "Lipids", "Proteins", "Nucleic acids"], "correctIndex": 2, "explanation": "Most enzymes are proteins (polypeptides) that catalyze biochemical\n        reactions. Nucleic acids store genetic information, carbohydrates and\n        lipids serve other structural/energy roles.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 34, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2025 Q#34 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q35_35", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 35, "subject": "Biology", "topic": "histone function", "question": "________ arranges the DNA Into the chromosomes in a eukaryotic cell.", "options": ["Hormones", "Elastin", "Histone", "Nucleosome"], "correctIndex": 2, "explanation": "Histone proteins bind DNA and help package it into nucleosomes and\n        higher-order chromatin, organizing DNA into chromosomes. Nucleosomes are\n        the DNA–histone complexes formed, while hormones and elastin are\n        unrelated.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 35, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2025 Q#35 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q36_36", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 36, "subject": "Biology", "topic": "nucleolus function", "question": "The function of nucleolus is to make:", "options": ["rDNA", "Lysosomes", "Ribosomes", "Chromosomes"], "correctIndex": 2, "explanation": "The nucleolus is the nuclear substructure where rRNA is transcribed and\n        ribosomal subunits are assembled (ribosome production). It does not\n        produce lysosomes or chromosomes.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 36, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2025 Q#36 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q37_37", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 37, "subject": "Biology", "topic": "blood velocity and capillaries", "question": "Which of the following blood vessels have lowest blood velocity with\n      correct reason for low blood velocity?", "options": ["Arteries: Due to thick walls", "Capillaries: due to highest overall cross-sectional area", "Veins: due to blood flow against the gravity", "Capillaries: Due to two-way blood flow in capillaries"], "correctIndex": 1, "explanation": "Capillaries collectively have the greatest total cross-sectional area in\n        the circulatory system, which reduces the velocity of blood flow despite\n        small individual diameter. Arteries and veins have much smaller total\n        cross-sectional area compared to the capillary bed, so the other options\n        are incorrect reasons for lowest velocity.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 37, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "UHS 2025 Q#37 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_d_q38_38", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 38, "subject": "Biology", "topic": "mitochondrial density in muscle", "question": "An active athlete has more stamina of running compared to an officer of\n      same age with physically inactive lifestyle. Which of the following\n      organelles has greatly increased in the muscle cells of athlete?", "options": ["Nucleus", "Mitochondria", "Golgi bodies", "Smooth endoplasmic reticulum (SER)"], "correctIndex": 1, "explanation": "Mitochondria are the sites of aerobic ATP production and increase in\n        number (mitochondrial biogenesis) in response to endurance training,\n        supporting greater stamina. The other organelles listed do not primarily\n        increase to support elevated aerobic energy production in muscle cells.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 38, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2025 Q#38 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q39_39", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 39, "subject": "Biology", "topic": "excitation contraction coupling", "question": "Once an action potential reaches the membrane of a skeletal muscle fiber,\n      what is the first event that occurs in the contraction process?", "options": ["Actin and myosin form a cross-bridge", "Calcium is pumped back into the sarcoplasmic reticulum", "Calcium is released from the sarcoplasmic reticulum", "ATP is hydrolyzed by troponin"], "correctIndex": 2, "explanation": "When the action potential reaches the muscle fiber, it triggers release\n        of Ca2+ from the sarcoplasmic reticulum into the cytosol; this rise in\n        Ca2+ is the immediate event that enables cross-bridge formation. Pumping\n        calcium back or cross-bridge formation occur after Ca2+ release; ATP is\n        hydrolyzed by myosin ATPase rather than troponin.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 39, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2025 Q#39 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q40_40", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 40, "subject": "Biology", "topic": "types of joints and tissues", "question": "The pubic symphysis is a slightly moveable joint joined by which of the\n      following tissue?", "options": ["Elastic cartilage", "Fibrocartilage", "Costal cartilage", "Articular cartilage"], "correctIndex": 1, "explanation": "The pubic symphysis is a secondary cartilaginous joint joined by\n        fibrocartilage, which provides strength with limited movement. Elastic\n        cartilage and costal (hyaline) cartilage are found in different\n        anatomical locations and do not form the symphysis.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 40, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "UHS 2025 Q#40 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_d_q41_41", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 41, "subject": "Biology", "topic": "dihybrid crosses", "question": "Mendel crossed a plant with round yellow seeds (RRYY) and a plant with\n      wrinkled green seeds (rryy), what was the phenotype of all F1 offspring?", "options": ["All round green", "All round yellow", "All wrinkled yellow", "All wrinkled green"], "correctIndex": 1, "explanation": "RRYY × rryy produces F1 offspring that are all RrYy, expressing the\n        dominant phenotypes: round (R) and yellow (Y). Therefore all F1\n        individuals are round yellow; the other phenotype combinations are not\n        produced in this cross.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 41, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "UHS 2025 Q#41 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_d_q42_42", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 42, "subject": "Biology", "topic": "menstrual cycle timing", "question": "In a normal 28 days menstrual cycle when would you expect the LH surge to\n      occur?", "options": ["Days 7-10", "Days 11-14", "Days 15-18", "Days 19-22"], "correctIndex": 1, "explanation": "The LH surge that triggers ovulation occurs around mid-cycle,\n        approximately day 14 in a 28‑day cycle; days 11–14 bracket the expected\n        time. The other ranges correspond to follicular (early) or luteal\n        (later) phases, not the LH surge.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 42, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "UHS 2025 Q#42 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2025"}, {"id": "paper_d_q43_43", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 43, "subject": "Biology", "topic": "water specific heat", "question": "Which property of water helps in moderating Earth's climate and\n      maintaining stable temperature in aquatic environment?", "options": ["Low viscosity", "High specific heat capacity", "High surface tension", "High polarity"], "correctIndex": 1, "explanation": "Water's high specific heat capacity means it absorbs or releases large\n        amounts of heat with little temperature change, buffering climate and\n        aquatic temperatures. While polarity and surface tension are important\n        for other properties, they do not explain thermal moderation.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 43, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2025 Q#43 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q44_44", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 44, "subject": "Biology", "topic": "substrate concentration and enzyme kinetics", "question": "Effect of increased substrate concentration on enzyme activity:", "options": ["Decrease the rate of reaction", "Increase the reaction rate until all active sites are saturated", "Have no effect on the reaction rate", "Increase the rate of reaction in a straight diagonal line"], "correctIndex": 1, "explanation": "Increasing substrate concentration increases reaction rate up to a\n        maximum (Vmax) when all active sites of enzyme molecules are occupied\n        (saturation). After saturation, further substrate increase does not\n        increase the rate; the other options misrepresent typical enzyme\n        kinetics.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 44, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2025 Q#44 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q45_45", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 45, "subject": "Biology", "topic": "oligosaccharide definition", "question": "An oligosaccharide is made up of at least:", "options": ["two saccharide units", "ten saccharide units", "three to ten saccharide units", "more than ten saccharide units"], "correctIndex": 2, "explanation": "Oligosaccharides are typically defined as carbohydrates composed of\n        about 3–10 monosaccharide units; disaccharides (2) are separate, and\n        >10 are polysaccharides.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 45, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2025 Q#45 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q46_46", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 46, "subject": "Biology", "topic": "humoral vs cell mediated", "question": "Which statement best explains the difference between humoral and cell\n      mediated Immune response?", "options": ["Humoral immunity involves B-Lymphocytes and cell mediated immunity\n          involves T-Lymphocytes", "Humoral immunity destroys viruses and cell mediated immunity destroys\n          bacteria", "Humoral immunity is specific and cell mediated immunity is\n          nonspecific", "Humoral immunity uses antibodies and cell mediated immunity does not\n          involve immune cells"], "correctIndex": 0, "explanation": "Humoral immunity is mediated by B lymphocytes and antibodies, whereas\n        cell-mediated immunity is mediated primarily by T lymphocytes; the other\n        choices are incorrect generalizations.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 46, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2025 Q#46 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q47_47", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 47, "subject": "Biology", "topic": "relative abundance rna types", "question": "Which of the following is the correct higher (left) to lower (right)\n      sequence of molecules with respect to the amount in the cell?", "options": ["DNA → rRNA → tRNA → mRNA", "rRNA → tRNA → mRNA → DNA", "mRNA → tRNA → rRNA → DNA", "DNA → mRNA → tRNA → rRNA"], "correctIndex": 1, "explanation": "rRNA is the most abundant cellular RNA, followed by tRNA, then mRNA; DNA\n        amount (genomic) is much lower in terms of molecule copies, so\n        rRNA→tRNA→mRNA→DNA is correct.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 47, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2025 Q#47 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q48_48", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 48, "subject": "Biology", "topic": "thermoregulation failure hot weather", "question": "A person in hot weather is unable to maintain body temperature. Which\n      physiological process has failed?", "options": ["Vasodilation & sweating", "Vasoconstriction", "Shivering", "Renin secretion"], "correctIndex": 0, "explanation": "Heat loss in hot conditions depends on vasodilation and sweating; if\n        these fail the body cannot dissipate heat effectively. Vasoconstriction\n        and shivering are cold responses.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 48, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2025 Q#48 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q49_49", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 49, "subject": "Biology", "topic": "darwin main idea", "question": "The main idea in Darwin's Theory of \"Origin of species by natural\n      selection\" is:", "options": ["Inheritance of acquired traits", "Use and disuse of organs", "Species never change", "Evolution occurs through gradual accumulation of adaptation through\n          successive generations"], "correctIndex": 3, "explanation": "Darwin's central concept is that natural selection causes gradual\n        accumulation of adaptive changes across generations, driving evolution;\n        the other options reflect non-Darwinian ideas.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 49, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "UHS 2025 Q#49 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2025"}, {"id": "paper_d_q50_50", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 50, "subject": "Biology", "topic": "rna key feature", "question": "Which of the following is a key feature of RNA?", "options": ["Deoxyribose and thymine", "Double stranded and thymine", "Ribose and uracil", "Ribose and thymine"], "correctIndex": 2, "explanation": "RNA contains ribose sugar and uses uracil instead of thymine; DNA\n        contains deoxyribose and thymine.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 50, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2025 Q#50 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q51_51", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 51, "subject": "Biology", "topic": "largest rna proportion", "question": "Which of the following types of RNA makeup the largest proportion of total\n      cellular RNA?", "options": ["Messenger RNA", "Ribosomal RNA", "Transfer RNA", "Catalytic RNA (ribozyme)"], "correctIndex": 1, "explanation": "Ribosomal RNA constitutes the largest fraction of cellular RNA because\n        ribosomes are abundant and rRNA makes up the structural and catalytic\n        core of ribosomes.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 51, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2025 Q#51 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q52_52", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 52, "subject": "Biology", "topic": "treponema pallidum disease", "question": "The bacterium Treponema Pallidum is responsible for which sexually\n      transmitted disease?", "options": ["Syphilis", "Chlamydia", "Gonorrhea", "Genital herpes"], "correctIndex": 0, "explanation": "Treponema pallidum is the spirochete bacterium that causes syphilis. The\n        other listed diseases are caused by different pathogens (Chlamydia\n        trachomatis, Neisseria gonorrhoeae, herpes simplex virus).", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 52, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "UHS 2025 Q#52 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_d_q53_53", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 53, "subject": "Biology", "topic": "tissue fluid lymphatic system", "question": "Tissue fluid in a lymphatic system is called as:", "options": ["Plasma", "Matrix", "Lymph", "Blood"], "correctIndex": 2, "explanation": "Interstitial fluid collected by lymphatic vessels is called lymph;\n        plasma is the blood fluid, and matrix typically refers to extracellular\n        matrix.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 53, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "UHS 2025 Q#53 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_d_q54_54", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 54, "subject": "Biology", "topic": "polymer polysaccharide example", "question": "Which one of the following biomolecules is a polymer/polysaccharide?", "options": ["Sucrose", "Pentose", "Lactose", "Glycogen"], "correctIndex": 3, "explanation": "Glycogen is a large branched polysaccharide polymer used for glucose\n        storage; sucrose and lactose are disaccharides and pentose is a\n        monosaccharide sugar.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 54, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2025 Q#54 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q55_55", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 55, "subject": "Biology", "topic": "olfactory receptor type", "question": "Olfactory receptors are the type of:", "options": ["photoreceptors", "mechanoreceptors", "thermoreceptors", "chemoreceptors"], "correctIndex": 3, "explanation": "Olfactory receptors detect chemicals (odorants) and are therefore\n        chemoreceptors; they are not photoreceptors, mechanoreceptors, or\n        thermoreceptors.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 55, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2025 Q#55 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q56_56", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 56, "subject": "Biology", "topic": "nitrogenous waste forms", "question": "Which of the following organisms eliminate nitrogenous waste mainly in the\n      form of uric acid?", "options": ["Freshwater Fish", "Amphibians", "Birds", "Mammals"], "correctIndex": 2, "explanation": "Birds (and many reptiles) excrete nitrogenous waste as uric acid (urate)\n        to conserve water; fish and mammals primarily excrete ammonia or urea,\n        amphibians mostly ammonia/urea depending on life stage.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 56, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2025 Q#56 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q57_57", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 57, "subject": "Biology", "topic": "nissl granules location", "question": "Which of the following cells possess Nissl's granules?", "options": ["Nerve cells", "WBC", "RBC", "Platelets"], "correctIndex": 0, "explanation": "Nissl bodies (granules) are rough endoplasmic reticulum with ribosomes\n        found in neuronal cell bodies (nerve cells); they are absent from RBCs,\n        platelets, and leukocytes.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 57, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2025 Q#57 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q58_58", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 58, "subject": "Biology", "topic": "cerebellum posture balance", "question": "Which part of human brain is involved in maintaining the posture and\n      balance of the body?", "options": ["Cerebrum", "Cerebellum", "Hypothalamus", "Medulla oblongata"], "correctIndex": 1, "explanation": "The cerebellum coordinates muscle activity and balance and is primarily\n        responsible for posture and equilibrium; cerebrum manages higher\n        functions and hypothalamus/medulla control other autonomic roles.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 58, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "UHS 2025 Q#58 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_d_q59_59", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 59, "subject": "Biology", "topic": "arthritis definition", "question": "Arthritis is:", "options": ["Inflammation of joints", "Herniation of intervertebral disc", "Fusion of vertebral joint", "tingling along the length of legs"], "correctIndex": 0, "explanation": "Arthritis literally means joint inflammation (arthr- joint, -itis\n        inflammation); the other options describe different spinal or\n        neurological conditions.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 59, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2025 Q#59 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q60_60", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 60, "subject": "Biology", "topic": "pubis joint type", "question": "Which type of joint is present in pubis?", "options": ["Fibrous joints", "Immoveable joints", "Cartilaginous joints", "Freely moveable joints"], "correctIndex": 2, "explanation": "The pubic symphysis is a cartilaginous joint (a type of amphiarthrosis)\n        where fibrocartilage connects the pubic bones, so it is classified as\n        cartilaginous.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 60, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "UHS 2025 Q#60 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_d_q61_61", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 61, "subject": "Biology", "topic": "neurons in reflex arc", "question": "Which type of neurons stimulate muscles to contract In a reflex arc?", "options": ["Motor neurons", "Sensory neurons", "Interneurons", "Afferent neurons"], "correctIndex": 0, "explanation": "Motor (efferent) neurons carry signals from the central nervous system\n        to muscles to produce contraction in reflex arcs; sensory (afferent)\n        neurons bring information to the CNS.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 61, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "UHS 2025 Q#61 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_d_q62_62", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 62, "subject": "Biology", "topic": "cell division prokaryote vs eukaryote", "question": "Which of the following statements best compares cell division in\n      prokaryotic and Eukaryotic cells?", "options": ["Eukaryotes divide by budding ; prokaryotes by mitosis", "Eukaryotes use binary fission ; prokaryotes by meiosis", "Eukaryotes divide by mitosis ; prokaryotes by binary fission", "Both use mitosis by cell division"], "correctIndex": 2, "explanation": "Eukaryotic cells typically divide by mitosis (and meiosis for gametes),\n        whereas prokaryotes reproduce by binary fission; the other statements\n        mix incorrect mechanisms.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 62, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2025 Q#62 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q63_63", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 63, "subject": "Biology", "topic": "lamarck acquired characteristics", "question": "Which of the following best describes \"acquired characteristics\" according\n      to Lamarckism?", "options": ["Traits caused by mutation", "Traits inherited from parents", "Traits developed by use or disuse", "Traits selected by nature"], "correctIndex": 2, "explanation": "Lamarck proposed that organisms develop traits during their lifetime\n        through use or disuse of organs and then pass those acquired traits to\n        offspring; this is Lamarckian inheritance.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 63, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2025 Q#63 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q64_64", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 64, "subject": "Biology", "topic": "lock and key active site", "question": "According to Lock and Key model, the active site is regarded as:", "options": ["Rigid and specific", "Flexible and specific", "Rigid and non specific", "Flexible and non specific"], "correctIndex": 0, "explanation": "The lock-and-key model describes the enzyme active site as a rigid\n        structure that specifically fits the substrate like a key in a lock,\n        hence 'rigid and specific'.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 64, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2025 Q#64 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q65_65", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 65, "subject": "Biology", "topic": "peptide bond function", "question": "Peptide bonds are Important In protein because they:", "options": ["Affect solubility", "Hold R-groups", "Link amino acid", "help in releasing oxygen"], "correctIndex": 2, "explanation": "Peptide bonds are the covalent links between amino acids that form the\n        primary structure of proteins; they do not 'hold R-groups' or release\n        oxygen.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 65, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2025 Q#65 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q66_66", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 66, "subject": "Biology", "topic": "retrovirus distinguishing feature", "question": "Why are retroviruses placed in a separate class of RNA viruses?", "options": ["They always infect animal cells only", "Their RNA acts directly as mRNA", "They lack protein coats", "They use reverse transcriptase to make DNA from RNA"], "correctIndex": 3, "explanation": "Retroviruses carry reverse transcriptase that synthesizes DNA from an\n        RNA template, integrating into host genomes-this distinctive replication\n        strategy separates them from other RNA viruses.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 66, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2025 Q#66 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q67_67", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 67, "subject": "Biology", "topic": "reversible vs irreversible inhibitors", "question": "Reversible inhibitors differ from Irreversible Inhibitors because they:", "options": ["Binds permanently and cannot be removed", "Bind temporarily and can be removed", "Permanently inactivate the enzyme", "Change enzyme structure permanently"], "correctIndex": 1, "explanation": "Reversible inhibitors bind non-covalently and can dissociate from the\n        enzyme, restoring activity; irreversible inhibitors form covalent bonds\n        and permanently inactivate the enzyme.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 67, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2025 Q#67 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q68_68", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 68, "subject": "Biology", "topic": "intestinal enzyme activator", "question": "Which is an enzyme activator secreted by the Intestinal glands:", "options": ["Amylase", "Pepsinogens", "Enterokinase", "Lipase"], "correctIndex": 2, "explanation": "Enterokinase (enteropeptidase) is secreted by intestinal mucosa and\n        activates trypsinogen to trypsin, initiating pancreatic enzyme\n        activation in the gut.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 68, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2025 Q#68 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q69_69", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 69, "subject": "Biology", "topic": "hyaline cartilage locations", "question": "In which of the following combination, both components have Hyaline\n      cartilage?", "options": ["Epiglottis & intervertebral disc", "Trachea & intervertebral disc", "Nose & pinna", "Nose & trachea"], "correctIndex": 3, "explanation": "Hyaline cartilage is found in the nasal septum (nose) and the tracheal\n        rings; the epiglottis is elastic cartilage and intervertebral discs are\n        fibrocartilage.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 69, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "UHS 2025 Q#69 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_d_q70_70", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 70, "subject": "Biology", "topic": "lamarck giraffe neck", "question": "According to Lamarck, the evolution of long necks in giraffes is explained\n      by:", "options": ["Natural selection", "Genetic mutation", "Survival of the fittest", "Stretching of necks over generations"], "correctIndex": 3, "explanation": "Lamarck proposed that traits acquired by use (e.g., stretching necks to\n        reach foliage) are inherited by offspring; thus he would explain giraffe\n        necks as stretching over generations.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 70, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "UHS 2025 Q#70 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2025"}, {"id": "paper_d_q71_71", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 71, "subject": "Biology", "topic": "spermatogenesis site", "question": "The process of spermatogenesis occurs in which part of the male\n      reproductive system?", "options": ["Seminiferous tubules", "Vas deferens", "Scrotum", "Epididymis"], "correctIndex": 0, "explanation": "Spermatogenesis (production of sperm) occurs within the seminiferous\n        tubules of the testes; the epididymis stores and matures sperm but is\n        not the site of spermatogenesis.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 71, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "UHS 2025 Q#71 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2025"}, {"id": "paper_d_q72_72", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 72, "subject": "Biology", "topic": "uterus layer nourishment", "question": "Which layer of uterus nourishes the embryo after implantation?", "options": ["Cervical epithelium", "Myometrium", "Endometrium", "Perimetrium"], "correctIndex": 2, "explanation": "The endometrium is the uterine lining that provides the implantation\n        site and nourishment to the embryo; myometrium is muscle, and\n        perimetrium is the outer serosal layer.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 72, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "UHS 2025 Q#72 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2025"}, {"id": "paper_d_q73_73", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 73, "subject": "Biology", "topic": "mrna role in protein synthesis", "question": "The main role of mRNA during protein synthesis is to:", "options": ["Carry genetic information for protein synthesis", "stabilize ribosome", "deliver amino acids", "provide platform for proteins synthesis"], "correctIndex": 0, "explanation": "mRNA carries the codon sequence transcribed from DNA that specifies the\n        amino acid order for a polypeptide; tRNA delivers amino acids and\n        ribosomes provide the platform.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 73, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2025 Q#73 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q74_74", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 74, "subject": "Biology", "topic": "glycoprotein composition", "question": "Glycoproteins are formed as a result of the combination of:", "options": ["Lipids and proteins", "Carbohydrates and proteins", "Nucleic acid and proteins", "Fatty acids and carbohydrates"], "correctIndex": 1, "explanation": "Glycoproteins consist of protein molecules with covalently attached\n        carbohydrate chains; they are not made from lipids or nucleic acids.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 74, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2025 Q#74 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q75_75", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 75, "subject": "Biology", "topic": "cell boundary observed structure", "question": "A student observed a boundary In both plant and animal cells that controls\n      entry and exit of substances. Which of the following structures is likely\n      being observed?", "options": ["Mitochondria", "Golgi apparatus", "Plasma membrane", "Cell wall"], "correctIndex": 2, "explanation": "The plasma membrane surrounds both plant and animal cells and regulates\n        transport of substances; a cell wall is present only in plant cells, and\n        mitochondria/Golgi are organelles.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 75, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2025 Q#75 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q76_76", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 76, "subject": "Biology", "topic": "x linked color blindness risk", "question": "If a normal person marries with colour blind female what will be the\n      possibility of normal male child:", "options": ["0%", "25%", "50%", "75%"], "correctIndex": 0, "explanation": "Colour blindness is X-linked recessive; a color-blind mother (XcXc) will\n        pass the affected X to all sons, so any male child will be color blind\n        and probability of a normal male child is 0%.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 76, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2025 Q#76 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q77_77", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 77, "subject": "Biology", "topic": "shared features skeletal cardiac", "question": "Which of the following characters is shared by both skeletal and cardiac\n      muscles?", "options": ["Presence of Striation", "Involuntary control", "Multinucleated fibers", "Intercalated discs"], "correctIndex": 0, "explanation": "Both skeletal and cardiac muscle fibers are striated due to ordered\n        sarcomeres; however, skeletal muscle is voluntary and multinucleated,\n        while cardiac muscle is involuntary and has intercalated discs.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 77, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "UHS 2025 Q#77 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_d_q78_78", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 78, "subject": "Biology", "topic": "involuntary muscle types", "question": "Which of the following muscle types are involuntary in action?", "options": ["Skeletal and smooth", "Skeletal and cardiac", "Cardiac and smooth", "Smooth muscle only"], "correctIndex": 2, "explanation": "Cardiac and smooth muscles operate involuntarily (cardiac is\n        autorhythmic; smooth is under autonomic control), whereas skeletal\n        muscle is under voluntary control.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 78, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "UHS 2025 Q#78 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_d_q79_79", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 79, "subject": "Biology", "topic": "smooth muscle locations", "question": "In which of the following combinations, both components have non-striated\n      muscle fibers?", "options": ["Intestine & biceps", "Intestine & blood vessels", "Heart & lungs", "Stomach & heart"], "correctIndex": 1, "explanation": "Non-striated (smooth) muscle is found in the walls of the intestine and\n        blood vessels. Biceps and heart muscle are striated (skeletal and\n        cardiac respectively), so options containing them are incorrect.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 79, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "UHS 2025 Q#79 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_d_q80_80", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 80, "subject": "Chemistry", "topic": "gas constant", "question": "Value of R gas constant in J mol-1 K-1 is", "options": ["8.314", "62.4", "0.821", "62400"], "correctIndex": 0, "explanation": "The universal gas constant R is 8.314 J mol^-1 K^-1. The other numbers\n        are R in different units or unrelated constants (e.g., 0.0821\n        L·atm·mol^-1·K^-1 when using atm·L units).", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 80, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2025 Q#80 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_d_q81_81", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 81, "subject": "Chemistry", "topic": "phenol acidity", "question": "Which of the following best explains why phenol reacts with aqueous NaOH,\n      but alcohols do not?", "options": ["Phenol has a lower boiling point than alcohol.", "Alcohols contain a strong O-H bond that cannot be broken by weak\n          bases.", "Phenol form hydrogen bonding that facilitates ionization.", "Phenol is weakly acidic due to resonance stabilization of phenoxide\n          ion."], "correctIndex": 3, "explanation": "Phenol is acidic because the phenoxide ion is resonance-stabilized,\n        making deprotonation favorable with bases like NaOH. Alcohols lack that\n        resonance stabilization, so they are much less acidic and do not react\n        with NaOH under normal conditions.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 81, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "UHS 2025 Q#81 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2025"}, {"id": "paper_d_q82_82", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 82, "subject": "Chemistry", "topic": "pi bond formation", "question": "In propene pi-bond is formed by sideway overlap of:", "options": ["s-orbitals", "p-orbitals", "sp2 hybrid orbitals", "sp3 hybrid orbitals"], "correctIndex": 1, "explanation": "A π-bond is produced by side-by-side (sideway) overlap of unhybridized\n        p-orbitals. In propene the double bond consists of an sp2–sp2 σ-bond and\n        a p–p π-bond.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 82, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "UHS 2025 Q#82 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2025"}, {"id": "paper_d_q83_83", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 83, "subject": "Biology", "topic": "lipase digestion", "question": "An enzyme used to decompose the lipids into fatty acids in our alimentary\n      canal is", "options": ["Amylase", "Protease", "Lipase", "Urease"], "correctIndex": 2, "explanation": "Lipase hydrolyzes triglycerides into fatty acids and glycerol in the\n        digestive tract. Amylase acts on starch, proteases on proteins, and\n        urease acts on urea (not a digestive enzyme in humans).", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 83, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2025 Q#83 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q84_84", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 84, "subject": "Chemistry", "topic": "molecular geometry vsepr", "question": "Molecules having one lone pair and three bond pairs have geometrical shape", "options": ["Bent or angular", "Trigonal", "Trigonal pyramidal", "Trigonal planer"], "correctIndex": 2, "explanation": "With three bonded atoms and one lone pair (AX3E), VSEPR predicts a\n        trigonal pyramidal shape (example: NH3). Bent/angular corresponds to\n        AX2E or AX2E2, trigonal planar is AX3 with no lone pairs.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 84, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "UHS 2025 Q#84 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2025"}, {"id": "paper_d_q85_85", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 85, "subject": "Chemistry", "topic": "alkane to alkyne conversion", "question": "Conversion of dihaloalkane into alkyne does not involve", "options": ["Addition", "Elimination", "Base", "Heat"], "correctIndex": 0, "explanation": "Conversion of a vicinal or geminal dihalide into an alkyne proceeds by\n        successive elimination reactions (requires strong base and often heat).\n        Addition reactions would be opposite (adding to a multiple bond), so\n        'Addition' is not involved.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 85, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "UHS 2025 Q#85 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2025"}, {"id": "paper_d_q86_86", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 86, "subject": "Chemistry", "topic": "enthalpy change", "question": "Majority of reactions taking place at ordinary temperatures with -ΔH are", "options": ["Endothermic", "Exothermic", "Thermally unstable", "Reversible"], "correctIndex": 1, "explanation": "A negative ΔH means heat is released to the surroundings, which defines\n        an exothermic reaction. Endothermic reactions absorb heat (positive ΔH),\n        while “thermally unstable” and “reversible” are not correct descriptions\n        of the sign of ΔH.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 86, "syllabusUnit": "Unit 4: Chemical Energetics", "pmdcTopic": "Enthalpy Changes, Hess's Law & Standard Heats of Reaction", "textbookCitation": "PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6", "citationString": "UHS 2025 Q#86 | Unit 4: Chemical Energetics | PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6"}, "year": "2025"}, {"id": "paper_d_q87_87", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 87, "subject": "Chemistry", "topic": "coinage metals", "question": "Which one of the following is a coinage metal", "options": ["Pd", "Cu", "Cd", "Hg"], "correctIndex": 1, "explanation": "Copper (Cu) is one of the classical coinage metals (Cu, Ag, Au) known\n        for use in coins. Palladium (Pd), cadmium (Cd) and mercury (Hg) are not\n        classified as coinage metals.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 87, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2025 Q#87 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_d_q88_88", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 88, "subject": "Chemistry", "topic": "percentage yield stoichiometry", "question": "Consider the given balanced chemical equation: 2H2 + O2 -> 2H2O If 4 g\n      of H2 reacts with 32 g of O2 to produce 28 g of H2O, what is the\n      percentage yield of the reaction? (Molar mass of H2 = 2 g/mol, O2 = 32\n      g/mol and H2O = 18 g/mol)", "options": ["63.6%", "77.8%", "87.5%", "92.5%"], "correctIndex": 1, "explanation": "2 mol H2 (4 g) and 1 mol O2 (32 g) react stoichiometrically to give 2\n        mol H2O (theoretical mass 2×18=36 g). Actual 28 g gives yield 28/36 =\n        0.777... = 77.8%. The other percentages do not match this calculation.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 88, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2025 Q#88 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_d_q89_89", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 89, "subject": "Chemistry", "topic": "activation energy", "question": "Amount of energy needed to weaken the existing bonds to an extent that can\n      be broken through collision is called:", "options": ["Bond energy", "Activation energy", "Average energy", "Enthalpy"], "correctIndex": 1, "explanation": "Activation energy is the extra energy required to reach the transition\n        state so bonds can be broken/formed during a collision. Bond energy is\n        the energy to break a specific bond in isolation, average energy is not\n        the standard term here, and enthalpy is a state function describing\n        overall heat change, not the collision barrier.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 89, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "UHS 2025 Q#89 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2025"}, {"id": "paper_d_q90_90", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 90, "subject": "Chemistry", "topic": "quantum numbers validity", "question": "Which set of quantum numbers is not allowed for an electron.", "options": ["n=2, l=1, m=0, s=+1/2", "n=3, l=0, m=0, s=-1/2", "n=2, l=2, m=+1, s=+1/2", "n=1, l=0, m=0, s=+1/2"], "correctIndex": 2, "explanation": "For a given principal quantum number n, the angular quantum number l\n        must be 0 ≤ l ≤ n−1. For n=2, l cannot equal 2, so option c is invalid.\n        The other sets all satisfy the allowed ranges for n, l, m and spin.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 90, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "UHS 2025 Q#90 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2025"}, {"id": "paper_d_q91_91", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 91, "subject": "Chemistry", "topic": "reaction rate expressions", "question": "2A + B -> 3C + D which of the following does not express the reaction\n      rate?", "options": ["-d[B]/dt", "d[D]/dt", "-1/2 d[A]/dt", "-1/3 d[C]/dt"], "correctIndex": 3, "explanation": "Rate expressions must include proper stoichiometric factors and signs:\n        rate = -1/2 d[A]/dt = -d[B]/dt = 1/3 d[C]/dt = d[D]/dt. The expression\n        -1/3 d[C]/dt has the wrong sign (should be positive 1/3 d[C]/dt), so it\n        does not correctly express the rate.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 91, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "UHS 2025 Q#91 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2025"}, {"id": "paper_d_q92_92", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 92, "subject": "Chemistry", "topic": "oxidizing agents", "question": "Acetaldehyde undergoes oxidation to produce acetic acid, In this reaction\n      oxidizing agent used is:", "options": ["HI", "LiAlH4", "K2Cr2O7", "NaBH4"], "correctIndex": 2, "explanation": "K2Cr2O7 (chromium(VI) reagent) is a common oxidizing agent that converts\n        aldehydes to carboxylic acids. LiAlH4 and NaBH4 are reducing agents, and\n        HI is not used as an oxidant for this transformation.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 92, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "UHS 2025 Q#92 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2025"}, {"id": "paper_d_q93_93", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 93, "subject": "Chemistry", "topic": "vapor pressure boiling point", "question": "Which one of the following has higher vapour pressure?", "options": ["acetone", "acetaldehyde", "isopentane", "Benzene"], "correctIndex": 1, "explanation": "Vapor pressure is higher for compounds with lower boiling points.\n        Acetaldehyde has a lower boiling point (~20°C) than acetone (~56°C),\n        isopentane (~28°C) and benzene (~80°C), so acetaldehyde has the highest\n        vapor pressure among the choices.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 93, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2025 Q#93 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_d_q94_94", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 94, "subject": "Chemistry", "topic": "terminal alkyne acidity", "question": "Terminal alkynes show acidic character due to:", "options": ["Terminal carbon atoms are sp hybridized.", "Terminal carbon atoms are sp2 hybridized.", "Terminal carbon atoms are sp3 hybridized.", "Terminal carbon atoms show hydrogen bonding."], "correctIndex": 0, "explanation": "The sp-hybridized carbon in terminal alkynes has greater s-character,\n        which stabilizes the conjugate base (acetylide anion) and increases\n        acidity. sp2 and sp3 hybridizations have less s-character and do not\n        confer the same acidity.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 94, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "UHS 2025 Q#94 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2025"}, {"id": "paper_d_q95_95", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 95, "subject": "Chemistry", "topic": "fischer esterification", "question": "Fischer ESTERIFICATION Is which type of reaction:", "options": ["Condensation", "Substitution", "Elimination", "Dehydrogenation"], "correctIndex": 0, "explanation": "Fischer esterification is the acid-catalyzed formation of an ester from\n        a carboxylic acid and an alcohol with loss of water, so it is a\n        condensation reaction. Substitution and elimination describe different\n        mechanistic outcomes, and dehydrogenation specifically removes hydrogen\n        rather than forming an ester plus water.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 95, "syllabusUnit": "Unit 12: Carboxylic Acids & Derivatives", "pmdcTopic": "Acidity of Carboxylic Acids & Acyl Derivatives", "textbookCitation": "PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21", "citationString": "UHS 2025 Q#95 | Unit 12: Carboxylic Acids & Derivatives | PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21"}, "year": "2025"}, {"id": "paper_d_q96_96", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 96, "subject": "Chemistry", "topic": "quantum numbers orbital shape", "question": "Shape of orbital is determined by quantum number:", "options": ["n", "l", "m", "s"], "correctIndex": 1, "explanation": "The azimuthal quantum number (l) determines the shape of an orbital (s,\n        p, d, f correspond to l = 0,1,2,3). The principal quantum number n sets\n        size/energy level, m (magnetic) sets orientation, and s denotes spin of\n        the electron.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 96, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "UHS 2025 Q#96 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2025"}, {"id": "paper_d_q97_97", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 97, "subject": "Chemistry", "topic": "bonding theories", "question": "The theories which explain the formation of sigma and pi bond are\n      EXCEPT:", "options": ["MOT", "VBT", "VSEPR", "CFT"], "correctIndex": 2, "explanation": "Molecular orbital theory (MOT) and valence bond theory (VBT) both\n        explain sigma and pi bond formation. VSEPR is a geometry model (predicts\n        shapes) rather than a bonding theory, so it is the exception. Crystal\n        field theory (CFT) concerns d-orbital splitting in complexes and is less\n        directly about sigma/pi formation but the question most commonly\n        excludes VSEPR.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 97, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "UHS 2025 Q#97 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2025"}, {"id": "paper_d_q98_98", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 98, "subject": "Chemistry", "topic": "rate equation", "question": "Final equation for the representation of rate of reaction in term of\n      concentration is called", "options": ["Rate law", "Rate constant", "Reaction rate", "Reaction order"], "correctIndex": 0, "explanation": "The rate law (or rate equation) expresses the rate of a reaction as a\n        function of reactant concentrations and includes the rate constant and\n        reaction orders. 'Rate constant' is a parameter within the law,\n        'reaction rate' is the measured rate, and 'reaction order' is part of\n        the rate law but not the full equation.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 98, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "UHS 2025 Q#98 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2025"}, {"id": "paper_d_q99_99", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 99, "subject": "Chemistry", "topic": "polymers pvc", "question": "Poly vinyl chloride (PVC) is the type of?", "options": ["Homopolymer", "Thermosetting polymer", "Thermoplastic polymer", "Copolymor"], "correctIndex": 0, "explanation": "PVC is formed from a single repeating monomer (vinyl chloride) and is\n        therefore a homopolymer. It is also a thermoplastic in behaviour (option\n        c describes thermal behaviour), but among the given categories\n        'homopolymer' specifically identifies its monomeric origin.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 99, "syllabusUnit": "Unit 13: Macromolecules & Industrial Chemistry", "pmdcTopic": "Synthetic & Natural Polymers, Amino Acids and Proteins", "textbookCitation": "PTB Chemistry XII Ch 14 (Macromolecules); Federal Chemistry XII Ch 22", "citationString": "UHS 2025 Q#99 | Unit 13: Macromolecules & Industrial Chemistry | PTB Chemistry XII Ch 14 (Macromolecules); Federal Chemistry XII Ch 22"}, "year": "2025"}, {"id": "paper_d_q100_100", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 100, "subject": "Chemistry", "topic": "ideal gas law", "question": "Which of the following is true about pressure for an ideal gas at\n      -273°C?", "options": ["P=1atm", "P=2atm", "P=3atm", "P=0 atm"], "correctIndex": 3, "explanation": "-273°C corresponds to absolute zero (0 K) for the ideal gas model; at\n        that temperature the pressure of an ideal gas would be zero. The other\n        options are nonzero pressures and therefore incorrect for an ideal gas\n        at absolute zero.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 100, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2025 Q#100 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_d_q101_101", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 101, "subject": "Chemistry", "topic": "buffers basic buffer", "question": "Which of the following is basic buffer?", "options": ["NH4OH/NH4Cl", "NaOH/NaCl", "NaOH/HCl", "H2CO3/NaHCO3"], "correctIndex": 0, "explanation": "A basic buffer is composed of a weak base and its conjugate salt; NH4OH\n        (a weak base, representing NH3 in water) with NH4Cl (its conjugate salt)\n        forms a basic buffer. NaOH/NaCl and NaOH/HCl involve a strong base and\n        are not buffer systems, while H2CO3/NaHCO3 is an acidic (carbonic)\n        buffer.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 101, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "UHS 2025 Q#101 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2025"}, {"id": "paper_d_q102_102", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 102, "subject": "Chemistry", "topic": "buffer action", "question": "What happens when H+ is added to ammonium hydroxide and ammonium\n      chloride buffer?", "options": ["more ammonium hydroxide is formed", "reaction will move reverse", "reaction will move forward", "no effect on equilibrium"], "correctIndex": 1, "explanation": "Adding H+ to the NH4OH/NH4+ system shifts the equilibrium NH4+ ⇌ NH3 +\n        H+ to the left, consuming H+ and producing more NH4+ (i.e., the reaction\n        moves in the reverse direction). It does not produce more NH4OH (option\n        a) and it does affect the equilibrium (ruling out d).", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 102, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "UHS 2025 Q#102 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2025"}, {"id": "paper_d_q103_103", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 103, "subject": "Chemistry", "topic": "radical substitution requirements", "question": "What is general requirement for free radical substitution reaction\n      of ethane and halogen?", "options": ["low pressure", "low temperature", "high pressure", "heat and UV light"], "correctIndex": 3, "explanation": "Free radical halogenation typically requires initiation by heat or UV\n        light to generate radicals; thus heat/UV is the general requirement. Low\n        or high pressure are not the defining initiation conditions for the\n        radical chain process.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 103, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2025 Q#103 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_d_q104_104", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 104, "subject": "Chemistry", "topic": "aromaticity benzene properties", "question": "Which one of the following is not a characteristic of benzene?", "options": ["Aromaticity", "Stability", "to follow Huckle rule", "High reactivity"], "correctIndex": 3, "explanation": "Benzene is characterized by aromaticity, enhanced stability (resonance\n        stabilization), and it follows Huckel's rule; it is relatively less\n        reactive than typical alkenes (electrophilic substitution rather than\n        addition), so 'High reactivity' is not a characteristic.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 104, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "UHS 2025 Q#104 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2025"}, {"id": "paper_d_q105_105", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 105, "subject": "Chemistry", "topic": "hybrid orbital size", "question": "Correct arrangement of orbital according to size of hybridized\n      orbitals?", "options": ["sp>sp2>sp3", "sp3> sp> sp2", "sp2>sp>sp3", "sp3>sp2>sp"], "correctIndex": 3, "explanation": "Orbitals with greater p-character are larger/less penetrating; sp3 (25%\n        s, 75% p) is largest, then sp2, then sp (highest s-character) is\n        smallest. Thus the order by size is sp3 > sp2 > sp.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 105, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "UHS 2025 Q#105 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2025"}, {"id": "paper_d_q106_106", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 106, "subject": "Chemistry", "topic": "stoichiometry and stp", "question": "Consider the equation H2 + O2 -> H2O, what volume of hydrogen gas is\n      required to produce 1 mol of water at standard temperature & pressure?", "options": ["11.2 dm3", "22.4 dm3", "10 dm3", "58 dm3"], "correctIndex": 1, "explanation": "Balance the equation first: 2H2 + O2 → 2H2O, so 2 mol H2 produce 2 mol\n        H2O (1:1 ratio). One mole of an ideal gas at STP occupies 22.4 dm3, so 1\n        mol H2 is 22.4 dm3.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 106, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2025 Q#106 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_d_q107_107", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 107, "subject": "Chemistry", "topic": "percentage yield", "question": "A chemical reaction has a theoretical yield of 25 g, but only 20 g of\n      product was obtained. What is the percentage yield of the reaction?", "options": ["20%", "25%", "45%", "80%"], "correctIndex": 3, "explanation": "Percentage yield = (actual yield / theoretical yield) × 100 = (20 / 25)\n        × 100 = 80%.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 107, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2025 Q#107 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_d_q108_108", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 108, "subject": "Chemistry", "topic": "examples of redox", "question": "Which of the following situations most clearly demonstrates a key\n      characteristic of a Redox reaction?", "options": ["Water boiling to steam", "Hydrogen gas reacting with chlorine to form hydrogen chloride\n          gas", "Sodium chloride dissolving in water", "Ethanol evaporating at room temperature"], "correctIndex": 1, "explanation": "Redox reactions involve electron transfer; H2 reacting with Cl2 to form\n        HCl involves oxidation of H2 and reduction of Cl2, so it is a redox\n        process. The other options are physical changes or dissolution, not\n        electron-transfer reactions.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 108, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "UHS 2025 Q#108 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2025"}, {"id": "paper_d_q109_109", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 109, "subject": "Chemistry", "topic": "first law internal energy", "question": "If 100 KJ of heat is absorbed by the system and 40 KJ of work is done on\n      the system what is the change of Internal energy?", "options": ["-60 KJ", "+60 KJ", "-140 KJ", "+140 KJ"], "correctIndex": 3, "explanation": "Use the first law ΔU = Q + W. Heat absorbed is Q = +100 kJ and work done\n        on the system is W = +40 kJ, so ΔU = 100 + 40 = +140 kJ.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 109, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2025 Q#109 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_d_q110_110", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 110, "subject": "Chemistry", "topic": "unpaired electrons in ions", "question": "Number of unpaired electrons present in the ground state of Fe3+ are\n      (Atomic number of Fe=26).", "options": ["Three", "Four", "Five", "Six"], "correctIndex": 2, "explanation": "Neutral Fe (Z=26) is [Ar] 3d6 4s2. Removing three electrons (to make\n        Fe3+) gives 3d5 configuration, which has five unpaired electrons (one in\n        each d orbital).", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 110, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "UHS 2025 Q#110 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2025"}, {"id": "paper_d_q111_111", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 111, "subject": "Chemistry", "topic": "percent yield calculation", "question": "If % yield and actual yield is 80 and 20g respectively, what will be\n      theoretical yield?", "options": ["20g", "25g", "30g", "40g"], "correctIndex": 1, "explanation": "Actual = %yield × theoretical. So theoretical = actual / (%yield) = 20 g\n        / 0.80 = 25 g.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 111, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2025 Q#111 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_d_q112_112", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 112, "subject": "Chemistry", "topic": "definition of redox", "question": "Which of the following best identifies the redox reaction:", "options": ["transfer of proton", "transfer of electron", "absorption of light", "exchange of ions"], "correctIndex": 1, "explanation": "Redox reactions are characterized by transfer of electrons (oxidation\n        and reduction). Proton transfer and ion exchange are different processes\n        (acid–base or ionic reactions), and absorption of light is not the\n        defining feature.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 112, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2025 Q#112 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_d_q113_113", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 113, "subject": "Chemistry", "topic": "reduction of carbonyls", "question": "Methanol is produced by reduction of", "options": ["Formaldehyde", "Acetaldehyde", "Propanal", "Propanone"], "correctIndex": 0, "explanation": "Reduction of formaldehyde (HCHO) by addition of hydrogen yields methanol\n        (CH3OH). The other carbonyls would give higher alcohols on reduction.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 113, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "UHS 2025 Q#113 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2025"}, {"id": "paper_d_q114_114", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 114, "subject": "Chemistry", "topic": "naming neopentyl derivatives", "question": "IUPAC name of (CH3)3 CCH2 Br is", "options": ["1-bromopentane", "1-bromo-2,2,2-trimethylethane", "1-bromo-2,2-dimethylpropane", "2-bromopentane"], "correctIndex": 2, "explanation": "The structure (CH3)3C–CH2Br is the neopentyl bromide skeleton; the\n        correct systematic name is 1-bromo-2,2-dimethylpropane (a bromomethyl at\n        C-1 of a 2,2-dimethylpropane backbone).", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 114, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2025 Q#114 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_d_q115_115", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 115, "subject": "Physics", "topic": "anisotropy in materials", "question": "Which one shows anisotropic behavior?", "options": ["Wood", "Gemstone", "Coke", "Graphite"], "correctIndex": 3, "explanation": "Anisotropic materials have properties that depend on direction; graphite\n        exhibits strong anisotropy (e.g., very different electrical and thermal\n        conductivities parallel and perpendicular to the layers). While wood is\n        also anisotropic in some senses, graphite is the standard example in\n        physics of a highly anisotropic solid.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 115, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2025 Q#115 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "paper_d_q116_116", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 116, "subject": "Chemistry", "topic": "unit cell angles", "question": "In a unit cell of a crystal lattice the angle β is between faces:", "options": ["a) a and b", "b) b and c", "c) c and a", "d) not specified"], "correctIndex": 2, "explanation": "By convention in crystallography the three interaxial angles are\n        labeled: α between b and c, β between a and c, and γ between a and b.\n        Therefore β is the angle between the a and c faces; the other choices\n        name different face pairs or are non‑specific.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 116, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2025 Q#116 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_d_q117_117", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 117, "subject": "Chemistry", "topic": "crystalline solids", "question": "Pick the crystalline solids:", "options": ["a) Cement", "b) Ceramics", "c) Concrete", "d) Copper"], "correctIndex": 1, "explanation": "Ceramics are typically crystalline or polycrystalline solids made of\n        ionic/covalent compounds. Cement and concrete are largely\n        amorphous/hydrated mixtures, while copper is a crystalline metal but the\n        exam's intended single best answer here is 'Ceramics' as a class of\n        crystalline solids.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 117, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2025 Q#117 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_d_q118_118", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 118, "subject": "Chemistry", "topic": "electron configuration unpaired electrons", "question": "Number of unpaired electrons In Boron in ground state is/are:", "options": ["a) 1", "b) 2", "c) 3", "d) 4"], "correctIndex": 0, "explanation": "Boron (Z=5) has electron configuration 1s2 2s2 2p1; the single 2p\n        electron is unpaired, so there is one unpaired electron. The other\n        option counts are therefore incorrect.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 118, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2025 Q#118 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_d_q119_119", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 119, "subject": "Chemistry", "topic": "electrophilic aromatic substitution", "question": "Chlorination of benzene in the presence of Iron (III) chloride\n      involves mechanism of:", "options": ["a) Electrophilic addition", "b) Electrophilic Substitution", "c) Free radical Substitution", "d) Free radical halogenation"], "correctIndex": 1, "explanation": "Chlorination of benzene with a Lewis acid catalyst (FeCl3) proceeds by\n        electrophilic aromatic substitution: an electrophile (Cl+) is generated\n        and substitutes a hydrogen on the ring. Addition or radical halogenation\n        mechanisms do not describe this catalytic aromatic substitution process.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 119, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "UHS 2025 Q#119 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2025"}, {"id": "paper_d_q120_120", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 120, "subject": "Chemistry", "topic": "ionization energy trends", "question": "The element with smallest value of ionization energy is", "options": ["a) Li", "b) Al", "c) Ca", "d) Ba"], "correctIndex": 3, "explanation": "Ionization energy generally decreases down a group as atomic size\n        increases; among the listed elements barium (Ba), being lowest in the\n        group and largest in size, has the smallest first ionization energy. The\n        other elements are higher in ionization energy.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 120, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2025 Q#120 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_d_q121_121", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 121, "subject": "Chemistry", "topic": "ammonium salts to amide", "question": "Carboxylic acid reacts with ammonia to form ammonium salts which on\n      heating produces:", "options": ["a) Carbonates", "b) Alkane", "c) Ester", "d) Amide"], "correctIndex": 3, "explanation": "Heating ammonium carboxylates (the salts from carboxylic acid + ammonia)\n        typically causes dehydration to give the corresponding amide, so amide\n        is produced on heating.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 121, "syllabusUnit": "Unit 12: Carboxylic Acids & Derivatives", "pmdcTopic": "Acidity of Carboxylic Acids & Acyl Derivatives", "textbookCitation": "PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21", "citationString": "UHS 2025 Q#121 | Unit 12: Carboxylic Acids & Derivatives | PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21"}, "year": "2025"}, {"id": "paper_d_q122_122", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 122, "subject": "Physics", "topic": "momentum to kinetic energy", "question": "If P is the momentum of an object and m is its mass, then its\n      kinetic energy is:", "options": ["a) P/2m", "b) P^2/2m", "c) 1/2 Pm^2", "d) 1/2 P^2/m^2"], "correctIndex": 1, "explanation": "Kinetic energy can be written in terms of momentum p as KE = p^2/(2m),\n        which corresponds to option b.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 122, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2025 Q#122 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q123_123", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 123, "subject": "Physics", "topic": "electric field scaling", "question": "The electric field at a point due to two equal and opposite charges\n      is 100 N/C. If the magnitude of each charge is doubled then the electric\n      field at that point becomes:", "options": ["a) 50 N/C", "b) 100 N/C", "c) 200 N/C", "d) 400 N/C"], "correctIndex": 2, "explanation": "Electric field is directly proportional to the charge. Doubling each\n        charge doubles the contribution, so the field doubles from 100 to 200\n        N/C.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 123, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "UHS 2025 Q#123 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2025"}, {"id": "paper_d_q124_124", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 124, "subject": "Physics", "topic": "dielectric effect", "question": "If a plastic sheet of relative permittivity 2.5 is inserted between\n      two-point charges placed in vacuum, then the electrostatic force between\n      them:", "options": ["a) Increases by a factor of 2.5", "b) Decreases by a factor of 2.5", "c) Increases by a factor of 5", "d) Decreases by a factor of 5"], "correctIndex": 1, "explanation": "Introducing a dielectric with relative permittivity εr reduces the\n        Coulomb force by a factor of εr. With εr = 2.5 the force decreases by\n        2.5.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 124, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2025 Q#124 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q125_125", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 125, "subject": "Physics", "topic": "radioactive decay fractions", "question": "After 3 half-lives, the remaining fraction of a radioactive sample\n      is:", "options": ["a) 1/2", "b) 1/4", "c) 1/8", "d) 1/16"], "correctIndex": 2, "explanation": "Remaining fraction after n half-lives is (1/2)^n; for n=3 this is\n        (1/2)^3 = 1/8.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 125, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "UHS 2025 Q#125 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2025"}, {"id": "paper_d_q126_126", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 126, "subject": "Physics", "topic": "projectile range", "question": "If the horizontal range of a projectile becomes half of its maximum\n      possible horizontal range, the probable angle of projection is;", "options": ["a) 15º", "b) 30º", "c) 45º", "d) 60º"], "correctIndex": 0, "explanation": "Range ∝ sin(2θ). If range is half the maximum, sin(2θ)=1/2 so 2θ=30° (or\n        150°) giving θ=15° (or 75°). The usual smaller solution is 15°.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 126, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2025 Q#126 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q127_127", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 127, "subject": "Physics", "topic": "ideal transformer", "question": "In an ideal transformer, if the primary voltage is doubled and the\n      turns ratio remains the same, what happens to the secondary current?", "options": ["a) Doubles", "b) Halves", "c) Remains the same", "d) Becomes four times"], "correctIndex": 0, "explanation": "With turns ratio fixed, secondary voltage doubles when primary voltage\n        doubles; for a given load impedance the secondary current is\n        proportional to secondary voltage, so it doubles.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 127, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "UHS 2025 Q#127 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2025"}, {"id": "paper_d_q128_128", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 128, "subject": "Physics", "topic": "angle to revolution", "question": "An angular displacement of 90° is equal to:", "options": ["a) One-fourth revolution", "b) One- third revolution", "c) One half revolution", "d) One complete revolution"], "correctIndex": 0, "explanation": "90° is one quarter of a full 360° revolution, so it equals one-fourth of\n        a revolution.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 128, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2025 Q#128 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q129_129", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 129, "subject": "Physics", "topic": "half life definition", "question": "The time in which half of the given number of radioactive nuclei\n      decay is known as", "options": ["a) 1/2 life of radioactive element.", "b) 2/3 life of radioactive element.", "c) 1/4 life of radioactive element.", "d) 2/5 life of radioactive element."], "correctIndex": 0, "explanation": "The definition of half-life is the time required for half the nuclei in\n        a sample to decay; option a states this directly.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 129, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "UHS 2025 Q#129 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2025"}, {"id": "paper_d_q130_130", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 130, "subject": "Physics", "topic": "sources of energy", "question": "Earth receives large amount of energy directly from:", "options": ["a) Wind", "b) Water", "c) Sun", "d) Moon"], "correctIndex": 2, "explanation": "The dominant source of energy received by Earth is solar radiation; the\n        Sun supplies far more energy than wind, water or the Moon.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 130, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2025 Q#130 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_d_q131_131", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 131, "subject": "Physics", "topic": "phase difference", "question": "A phase difference of 90° is equal to:", "options": ["a) π radians", "b) π/2 radians", "c) 2π radians", "d) π/4 radians"], "correctIndex": 1, "explanation": "90° corresponds to π/2 radians (since 180° = π radians).", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 131, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2025 Q#131 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "paper_d_q132_132", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 132, "subject": "Physics", "topic": "reciprocal of resistivity", "question": "The reciprocal of the resistivity of a material is called its:", "options": ["a) impedance", "b) conductivity", "c) admittance", "d) reactance"], "correctIndex": 1, "explanation": "The reciprocal of resistivity (ρ) is conductivity (σ), which measures\n        how well a material conducts electric current.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 132, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2025 Q#132 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "paper_d_q133_133", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 133, "subject": "Physics", "topic": "balmer series", "question": "The Balmer series of hydrogen spectrum appears in the", "options": ["a) Infrared region", "b) Ultraviolet region", "c) X-ray region", "d) Visible region"], "correctIndex": 3, "explanation": "The Balmer series corresponds to electron transitions that emit photons\n        in the visible part of the electromagnetic spectrum.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 133, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2025 Q#133 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "paper_d_q134_134", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 134, "subject": "Physics", "topic": "projectile velocity at apex", "question": "A ball is thrown into the air with certain velocity v making an\n      angle θ with horizontal. If air resistance is neglected, then at maximum\n      height its velocity is:", "options": ["a) Equal to initial velocity", "b) Half of initial velocity", "c) Equal to zero", "d) Minimum but not zero"], "correctIndex": 3, "explanation": "At maximum height the vertical component of velocity is zero but the\n        horizontal component remains (u cosθ), so the speed is not zero - it is\n        the minimum along the trajectory but generally nonzero.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 134, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2025 Q#134 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q135_135", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 135, "subject": "Physics", "topic": "recoil", "question": "A canon is placed on a smooth surface. When it fires a shell, the\n      canon moves backward, this recoil occurs due to:", "options": ["a) law of conservation of energy", "b) Backward thrust of the gases", "c) Newton's third law of motion", "d) Newton's first law of motion"], "correctIndex": 2, "explanation": "The recoil is a direct consequence of Newton's third law: the force on\n        the projectile is paired with an equal and opposite force on the cannon.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 135, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "UHS 2025 Q#135 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2025"}, {"id": "paper_d_q136_136", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 136, "subject": "Physics", "topic": "surface charge and field", "question": "If the surface charge density of an infinite sheet increases by 25%,\n      the electric field intensity:", "options": ["a) Increases by 25%", "b) Increases by 50%", "c) Decreases by 25%", "d) Remains the same"], "correctIndex": 0, "explanation": "For an infinite sheet E = σ/(2ε0), so E is directly proportional to\n        surface charge density σ. A 25% increase in σ gives 25% increase in E.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 136, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "UHS 2025 Q#136 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2025"}, {"id": "paper_d_q137_137", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 137, "subject": "Physics", "topic": "continuity equation", "question": "An incompressible fluid flows through a pipe that becomes narrower\n      in one section. The fluid speed in that region increases in that region to\n      maintain:", "options": ["a) Constant pressure", "b) constant energy", "c) constant mass flow rate", "d) constant volume"], "correctIndex": 2, "explanation": "For incompressible flow the continuity equation requires the mass flow\n        rate (ρAv) to be constant; since ρ is constant, area decrease causes\n        velocity to increase to keep mass flow constant.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 137, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2025 Q#137 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "paper_d_q138_138", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 138, "subject": "Physics", "topic": "bernoulis principle", "question": "In a pipe of varying cross-section as fluid enters the narrower\n      region, it exhibits:", "options": ["a) high velocity, high pressure", "b) high velocity, low pressure", "c) low velocity, high pressure", "d) low velocity, low pressure"], "correctIndex": 1, "explanation": "According to Bernoulli's principle, where fluid velocity increases\n        (narrow section) the static pressure decreases, so high velocity and low\n        pressure occur.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 138, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2025 Q#138 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "paper_d_q139_139", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 139, "subject": "Physics", "topic": "airfoil pressure", "question": "The curved shape of an airplane wing causes air to move faster over\n      the top surface. This leads to:", "options": ["a) greater pressure on the top", "b) lower pressure on the top", "c) equal pressure on both sides", "d) zero pressure above the wing"], "correctIndex": 1, "explanation": "Faster flow over the top surface produces lower pressure there compared\n        with the bottom, generating lift (lower pressure on top).", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 139, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "UHS 2025 Q#139 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2025"}, {"id": "paper_d_q140_140", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 140, "subject": "Physics", "topic": "forces in nucleus", "question": "The protons in the nucleus of an atom DO NOT exit due to", "options": ["a) Electromagnetic force", "b) Gravitational Force", "c) Weak Nuclear Force", "d) Strong Nuclear Force"], "correctIndex": 1, "explanation": "Gravitational force is negligibly small at nuclear scales and does not\n        play a role in holding or repelling protons; strong nuclear force (and\n        electromagnetic repulsion) are the significant forces in the nucleus.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 140, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2025 Q#140 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q141_141", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 141, "subject": "Physics", "topic": "mechanical waves require medium", "question": "Mechanical waves cannot travel through outer space because they:", "options": ["a) have low speed in vacuum", "b) disperse in space due to long wavelength", "c) lose frequency in the absence of air", "d) lose transmission without interacting particles"], "correctIndex": 3, "explanation": "Mechanical waves require a material medium (interacting particles) to\n        propagate; in outer space there is essentially no medium, so mechanical\n        waves cannot be transmitted.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 141, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "UHS 2025 Q#141 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2025"}, {"id": "paper_d_q142_142", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 142, "subject": "Physics", "topic": "terminal voltage emf", "question": "Terminal voltage of a cell equals its EMF only when:", "options": ["a) No current flows", "b) Current is maximum", "c) Internal resistance is infinite", "d) Load resistance is zero"], "correctIndex": 0, "explanation": "Terminal voltage V = EMF - Ir; when no current flows (I=0) the voltage\n        equals the EMF.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 142, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2025 Q#142 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "paper_d_q143_143", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 143, "subject": "Physics", "topic": "lenzs law", "question": "A loop moves toward a stationary magnet. The induced current will:", "options": ["a) enhance the motion", "b) try to stop the approach", "c) become zero", "d) become alternating"], "correctIndex": 1, "explanation": "By Lenz's law the induced current produces a magnetic field opposing the\n        change; when a loop approaches a magnet the induced current produces a\n        field that opposes the approach, trying to stop it.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 143, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "UHS 2025 Q#143 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2025"}, {"id": "paper_d_q144_144", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 144, "subject": "Physics", "topic": "energy dependence", "question": "The energy of a Simple Harmonic oscillation depends upon the:", "options": ["a) frequency", "b) time period", "c) wavelength", "d) amplitude"], "correctIndex": 3, "explanation": "The total energy of a simple harmonic oscillator is proportional to the\n        square of the amplitude (E ∝ A^2); it does not depend on phase or\n        wavelength.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 144, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2025 Q#144 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_d_q145_145", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 145, "subject": "Physics", "topic": "electromagnetic spectrum", "question": "The wave that has the highest frequency & penetrating power is:", "options": ["X-rays", "Ultraviolet rays", "Gamma rays", "Microwaves"], "correctIndex": 2, "explanation": "Gamma rays have the highest frequency and greatest penetrating power in\n        the electromagnetic spectrum, higher than X-rays and ultraviolet;\n        microwaves have much lower frequency.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 145, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2025 Q#145 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_d_q146_146", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 146, "subject": "Physics", "topic": "first law thermodynamics", "question": "According to First law of thermodynamics when heat flows into a\n      system and no work is done the internal energy of the system must", "options": ["Increase", "Decrease", "Remains constant", "Becomes zero"], "correctIndex": 0, "explanation": "First law: ΔU = Q - W. If heat Q flows in (positive) and no work is done\n        (W = 0), then internal energy increases.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 146, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2025 Q#146 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_d_q147_147", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 147, "subject": "Physics", "topic": "resistance length dependence", "question": "If the length of the conductor is made 4 times its original length,\n      its resistance becomes", "options": ["quarter", "half", "zero", "4 times"], "correctIndex": 3, "explanation": "Resistance is proportional to length (R ∝ L). If length is multiplied by\n        4 and cross-sectional area unchanged, resistance becomes 4 times the\n        original.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 147, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "UHS 2025 Q#147 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2025"}, {"id": "paper_d_q148_148", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 148, "subject": "Physics", "topic": "temperature coefficient resistivity", "question": "The unit of temperature coefficient of resistivity is", "options": ["1/C", "1/K", "1/A", "1/Ω"], "correctIndex": 1, "explanation": "The temperature coefficient has units of reciprocal temperature;\n        commonly expressed per kelvin (1/K), which is equivalent to per degree\n        Celsius for differences.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 148, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "UHS 2025 Q#148 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2025"}, {"id": "paper_d_q149_149", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 149, "subject": "Physics", "topic": "work by gravity", "question": "The work done by the gravitational force on an object as it moves\n      from a reference level to a higher point is", "options": ["Always positive", "Always negative", "Zero", "Depends on the path taken"], "correctIndex": 1, "explanation": "When an object moves upward, displacement is opposite to the\n        gravitational force, so gravity does negative work (it removes\n        mechanical energy from the object).", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 149, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2025 Q#149 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q150_150", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 150, "subject": "Physics", "topic": "interference of sound", "question": "If two speakers emit sound at same frequency and phase, maximum\n      loudness occurs when:", "options": ["Path difference = √2", "Path difference = λ", "Path difference = λ/4", "Path difference = 3λ/43"], "correctIndex": 1, "explanation": "Constructive interference (maximum loudness) occurs when the path\n        difference is an integer multiple of the wavelength; the simplest\n        nonzero value is λ.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 150, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "UHS 2025 Q#150 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2025"}, {"id": "paper_d_q151_151", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 151, "subject": "Physics", "topic": "kinetic energy calculation", "question": "A 0.5 kg ball moving at 6 m/s has kinetic energy", "options": ["9 J", "18 J", "6 J", "3 J"], "correctIndex": 0, "explanation": "Kinetic energy = 1/2 m v^2 = 0.5 * 0.5 * 6^2 = 0.25 * 36 = 9 J.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 151, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2025 Q#151 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_d_q152_152", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 152, "subject": "Physics", "topic": "turbulent transition critical velocity", "question": "A fluid is flowing through a tube, to undergo transition from\n      laminar to turbulent flow it's velocity must be:", "options": ["Slightly less than critical velocity", "equal to critical velocity", "greater than critical velocity", "increasing gradually but less than critical velocity"], "correctIndex": 2, "explanation": "Flow becomes turbulent when the flow velocity exceeds a critical value\n        (often expressed via the Reynolds number); thus the velocity must be\n        greater than the critical value.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 152, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2025 Q#152 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q153_153", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 153, "subject": "Physics", "topic": "electric field between charges", "question": "For two equal positive charges, the electric field weakest?", "options": ["Midway between them", "Along the perpendicular bisector", "Close to either charge", "At infinity"], "correctIndex": 0, "explanation": "At the midpoint between two equal like charges the electric fields from\n        each charge cancel, producing the weakest (zero) net field there.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 153, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "UHS 2025 Q#153 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2025"}, {"id": "paper_d_q154_154", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 154, "subject": "Physics", "topic": "projectile speed", "question": "A projectile is launched in air with certain angle; its velocity is\n      maximum at:", "options": ["Point of projection", "Highest point", "Between launching and highest point", "At all points"], "correctIndex": 0, "explanation": "Neglecting air resistance, the projectile's speed is largest at launch\n        (and at landing); at the highest point the vertical component is zero,\n        so speed is smaller unless launch angle was zero.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 154, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2025 Q#154 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q155_155", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 155, "subject": "Physics", "topic": "coulombs law scaling", "question": "If the distance between two charges is halved and magnitude of\n      charges are also doubled, then the force between these charges becomes:", "options": ["two times", "four times", "eight times", "sixteen times"], "correctIndex": 3, "explanation": "Coulomb's law: F ∝ q1 q2 / r^2. Doubling both charges multiplies product\n        by 4; halving distance divides r^2 by 4, so overall factor = 4 * 4 = 16.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 155, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2025 Q#155 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q156_156", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 156, "subject": "Physics", "topic": "relative speed collision", "question": "If a body having mass m1 (2 kg), moving with 5 m/s approaches\n      another mass, m2 (3 kg) with speed of 1 m/s in same direction, relative\n      speed of approach is 4 m/s. Relative speed of separation after collision\n      will be:", "options": ["4 m/s", "2 m/s", "6 m/s", "depends on masses"], "correctIndex": 0, "explanation": "For an elastic collision the magnitude of relative speed of separation\n        equals the magnitude of relative speed of approach (4 m/s). Without\n        specification of collision type the intended concept tested is this\n        elastic-collision property.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 156, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2025 Q#156 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q157_157", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 157, "subject": "English", "topic": "subject verb agreement", "question": "Which of the following sentences has correct subject verb agreement?", "options": ["The teacher give the students homework.", "The teacher gives the students homework.", "The teachers gives the student homework.", "The teachers given the student homework."], "correctIndex": 1, "explanation": "The singular subject 'The teacher' requires the singular verb 'gives' -\n        option (b) matches correct subject–verb agreement.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 157, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "UHS 2025 Q#157 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2025"}, {"id": "paper_d_q158_158", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 158, "subject": "English", "topic": "prepositions", "question": "The keys were found ________ the drawer where you left them last\n      week.", "options": ["under", "in", "on", "beside"], "correctIndex": 1, "explanation": "If the keys were located inside the drawer where they were left, the\n        correct preposition is 'in'.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 158, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "UHS 2025 Q#158 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2025"}, {"id": "paper_d_q159_159", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 159, "subject": "English", "topic": "punctuation correctness", "question": "Identify the sentence among of the following, which is punctuated\n      correctly?", "options": ["The teaching staff asked the principal what time the meeting would\n          start.", "The teaching staff asked the principal: \"What time would the meeting\n          start?\"", "The teaching staff asked the principal, \"What time would the meeting\n          start?\"", "The teaching staff asked the principal; \"What time would the meeting\n          start?\""], "correctIndex": 2, "explanation": "The correct punctuation when introducing direct speech after a reporting\n        clause is to use a comma before the quotation, as in option c. Options b\n        and d use incorrect punctuation marks (colon or semicolon) before the\n        quote, and option a lacks the necessary punctuation to introduce the\n        quoted question.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 159, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "UHS 2025 Q#159 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2025"}, {"id": "paper_d_q160_160", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 160, "subject": "English", "topic": "vocabulary context", "question": "\"She was elated when she got first position in exams.\" What is the\n      meaning of \"elated\" In this sentence?", "options": ["Defeated", "Worried", "Excited", "Mad"], "correctIndex": 2, "explanation": "‘Elated’ means very happy or excited, so option c is correct. The other\n        choices (defeated/worried/mad) have opposite or unrelated meanings and\n        do not fit the positive context of getting first position.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 160, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "UHS 2025 Q#160 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2025"}, {"id": "paper_d_q161_161", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 161, "subject": "English", "topic": "collective noun agreement", "question": "The board of directors expressed____________disappointment with the\n      financial results.", "options": ["their", "its", "his or her", "one's"], "correctIndex": 1, "explanation": "A corporate body like 'the board' is typically treated as a single\n        entity, so the possessive 'its' is appropriate (option b). 'Their'\n        treats the board as individuals, while 'his or her' and 'one's' are not\n        suitable for this formal collective noun.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 161, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "UHS 2025 Q#161 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2025"}, {"id": "paper_d_q162_162", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 162, "subject": "English", "topic": "connectors and cohesion", "question": "It rained all night; __________ the roads were flooded in the\n      morning.", "options": ["similarly", "instead", "as a result", "in contrast"], "correctIndex": 2, "explanation": "The second clause is a consequence of the first (rain caused flooding),\n        so 'as a result' (option c) is correct. 'Similarly' and 'in contrast' do\n        not express cause, and 'instead' implies substitution rather than\n        consequence.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 162, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "UHS 2025 Q#162 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2025"}, {"id": "paper_d_q163_163", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 163, "subject": "English", "topic": "spelling common words", "question": "The manager accepted the cashier's ______ for coming late.", "options": ["expalanation", "explaination", "explanation", "explantion"], "correctIndex": 2, "explanation": "The correct spelling is 'explanation' (option c). The other options are\n        common misspellings of the word.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 163, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "UHS 2025 Q#163 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2025"}, {"id": "paper_d_q164_164", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 164, "subject": "English", "topic": "vocabulary context", "question": "The writer has unearthed serious irregularities in the entire\n      project. The word 'unearthed' In this sentence means", "options": ["written", "mentioned", "exposed", "stated"], "correctIndex": 2, "explanation": "'Unearthed' figuratively means 'discovered and revealed', so 'exposed'\n        (option c) is the correct sense here. The other options do not convey\n        the uncovering/revealing meaning.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 164, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "UHS 2025 Q#164 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2025"}, {"id": "paper_d_q165_165", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 165, "subject": "English", "topic": "spelling recognition", "question": "Identify the sentence with no spelling error:", "options": ["Imtiaz invited me on a dinner party at restaurant.", "Imtiaz invited me on a dier party at restaurant.", "Imtiaz invited me on a dinner party at restaurent.", "Imtiaz invited me on a dinnar party at restaurent."], "correctIndex": 0, "explanation": "Option a contains the only words that are spelled correctly ('dinner'\n        and 'restaurant'), despite its awkward grammar. The other options\n        contain clear misspellings: 'dier', 'restaurent', and 'dinnar'.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 165, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "UHS 2025 Q#165 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2025"}, {"id": "paper_d_q166_166", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 166, "subject": "Logical Reasoning", "topic": "number sequence", "question": "What will come next? 1, 4, 2, 5, 3, 6, 4, 7, ?", "options": ["5", "6", "7", "8"], "correctIndex": 0, "explanation": "The sequence alternates adding 3 then subtracting 2: 1→4 (+3), 4→2 (−2),\n        2→5 (+3), 5→3 (−2), etc. After 7 the next term follows the −2 step,\n        giving 5 (option a).", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 166, "syllabusUnit": "Pattern Recognition & Sequences", "pmdcTopic": "Numerical & Pattern Sequence Reasoning", "textbookCitation": "PMDC MDCAT Logical Reasoning Framework", "citationString": "UHS 2025 Q#166 | Pattern Recognition & Sequences | PMDC MDCAT Logical Reasoning Framework"}, "year": "2025"}, {"id": "paper_d_q167_167", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 167, "subject": "Logical Reasoning", "topic": "syllogism", "question": "All daffodils are plants. All plants are living things. Some living things\n      are real. Conclusions: I. All daffodils are living things. II. Some living\n      things are flowers. III. All daffodils are real. Which conclusions follow?", "options": ["Only I", "Only I and II", "Only II and III", "All follow"], "correctIndex": 0, "explanation": "From the two universal premises, 'All daffodils are living things' (I)\n        logically follows. II and III require an existential assumption (that\n        daffodils or flowers exist or overlap with the 'real' ones), which is\n        not given, so they do not logically follow. Hence only I is valid.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 167, "syllabusUnit": "Deductive & Analytical Reasoning", "pmdcTopic": "Premise Analysis & Logical Syllogisms", "textbookCitation": "PMDC MDCAT Logical Reasoning Guide (Deductions & Assumptions)", "citationString": "UHS 2025 Q#167 | Deductive & Analytical Reasoning | PMDC MDCAT Logical Reasoning Guide (Deductions & Assumptions)"}, "year": "2025"}, {"id": "paper_d_q168_168", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 168, "subject": "Logical Reasoning", "topic": "simple arithmetic word problem", "question": "One apple pie has 10 slices, and each apple pie feeds five people. Henry\n      is having a party with 200 people. How many slices of pie does he need?", "options": ["200", "50", "400", "100"], "correctIndex": 2, "explanation": "Each pie feeds 5 people, so 200 people need 200/5 = 40 pies. At 10\n        slices per pie, 40 pies × 10 slices = 400 slices. The other choices are\n        incorrect calculations.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 168, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "UHS 2025 Q#168 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2025"}, {"id": "paper_d_q169_169", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 169, "subject": "Logical Reasoning", "topic": "data sufficiency", "question": "How many trees are in the orchard? Which of the statements below are\n      needed to sufficiently answer this question? I. Ibrahim is a farmer and\n      looks after half of the trees in the orchard II. 300 trees in the orchard\n      are under Ibrahim's care", "options": ["i is enough", "ii is enough", "both I and II are needed", "neither i or ii are sufficient"], "correctIndex": 2, "explanation": "Statement II alone (300 trees under Ibrahim's care) is not sufficient\n        without knowing that this represents half; Statement I alone (he looks\n        after half) gives no numerical value. Together they tell us half = 300,\n        so total = 600. Therefore both statements are needed.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 169, "syllabusUnit": "Deductive & Analytical Reasoning", "pmdcTopic": "Premise Analysis & Logical Syllogisms", "textbookCitation": "PMDC MDCAT Logical Reasoning Guide (Deductions & Assumptions)", "citationString": "UHS 2025 Q#169 | Deductive & Analytical Reasoning | PMDC MDCAT Logical Reasoning Guide (Deductions & Assumptions)"}, "year": "2025"}, {"id": "paper_d_q170_170", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 170, "subject": "Logical Reasoning", "topic": "family relationship", "question": "P and Q are M's parents. M and N are siblings. Q is N's mother. What is P\n      to M?", "options": ["Mother", "Father", "Sister", "Brother"], "correctIndex": 1, "explanation": "If Q is N's mother and N is M's sibling, Q is also M's mother; therefore\n        P (the other parent) is M's father. The other options are therefore\n        incorrect.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 170, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "UHS 2025 Q#170 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2025"}, {"id": "paper_d_q171_171", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 171, "subject": "Logical Reasoning", "topic": "price comparison", "question": "Asad bought 50 packets of biscuits for the price of Rs. 500; whereas Anum\n      bought 25 packets of chips for the price of Rs.1000. While comparing the\n      prices of packets of biscuits and packet of chips, which of the following\n      statements is correct?", "options": ["Price of 4 packets of biscuits is equal to the price of 1 packet of\n          chips", "Price of 1 packet of biscuits is equal to the price of 4 packets of\n          chips", "Price of 2 packets of biscuits is equal to the price of 1 packet of\n          chips", "Price of 1 packet of biscuits is equal to the price of 2 packets of\n          chips"], "correctIndex": 0, "explanation": "Asad's price per biscuit packet = 500/50 = Rs.10; Anum's price per chips\n        packet = 1000/25 = Rs.40. Therefore one chips packet costs the same as\n        four biscuit packets (4×10 = 40), making option (a) correct; the other\n        options are incorrect conversions.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 171, "syllabusUnit": "Deductive & Analytical Reasoning", "pmdcTopic": "Premise Analysis & Logical Syllogisms", "textbookCitation": "PMDC MDCAT Logical Reasoning Guide (Deductions & Assumptions)", "citationString": "UHS 2025 Q#171 | Deductive & Analytical Reasoning | PMDC MDCAT Logical Reasoning Guide (Deductions & Assumptions)"}, "year": "2025"}, {"id": "paper_d_q172_172", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 172, "subject": "Logical Reasoning", "topic": "growth sequence", "question": "The virus spreads rapidly in the town. It infected the people - First day:\n      8, Second day: 1 Third day: 32. What will the number of people infected on\n      the next day?", "options": ["44 people", "56 people", "64 people", "74 people"], "correctIndex": 2, "explanation": "The intended sequence appears to be a doubling pattern (8, 16, 32,...),\n        despite an OCR/trancription error for day two. Continuing the doubling\n        gives 64 for the next day, so option (c) is correct. The other numeric\n        choices do not follow the doubling pattern.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 172, "syllabusUnit": "Pattern Recognition & Sequences", "pmdcTopic": "Numerical & Pattern Sequence Reasoning", "textbookCitation": "PMDC MDCAT Logical Reasoning Framework", "citationString": "UHS 2025 Q#172 | Pattern Recognition & Sequences | PMDC MDCAT Logical Reasoning Framework"}, "year": "2025"}, {"id": "paper_d_q173_173", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 173, "subject": "Logical Reasoning", "topic": "workplace safety factors", "question": "Which of the following is a result of poor design that could cause an\n      accident in the workplace?", "options": ["Equipment failure", "Slippery surfaces", "Insufficient lighting", "Unplanned workspace layout"], "correctIndex": 3, "explanation": "An unplanned workspace layout is directly a result of poor design and\n        can lead to accidents by creating hazards or obstructed workflows. While\n        the other options can contribute to accidents, they may arise from\n        maintenance or environmental issues rather than poor overall design.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 173, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "UHS 2025 Q#173 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2025"}, {"id": "paper_d_q174_174", "paperTitle": "UHS MDCAT 2025 (Paper D)", "shortTitle": "UHS 2025", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 174, "subject": "Logical Reasoning", "topic": "accident causation", "question": "Which of the following is the main cause of accidents involving equipment?", "options": ["Overconfidence", "Insufficient maintenance", "Fatigue", "Poor training"], "correctIndex": 1, "explanation": "Insufficient maintenance is a primary cause of equipment-related\n        accidents because poorly maintained equipment is more likely to fail.\n        While overconfidence, fatigue, and poor training also contribute to\n        accidents, they are not as directly tied to equipment malfunction as\n        maintenance deficits.", "reference": {"sourcePaper": "UHS MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 174, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "UHS 2025 Q#174 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2025"}, {"id": "paper_2_q1_1", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 1, "subject": "Biology", "topic": "hormones lipid soluble", "question": "Which of the following hormones in the body of animal is lipid-based in nature?", "options": ["Insulin", "FSH", "Oxytocin", "Aldosterone"], "correctIndex": 3, "explanation": "Aldosterone is a steroid hormone derived from cholesterol and is lipid-soluble. Insulin, FSH and oxytocin are peptide/glycoprotein hormones and are not lipid-based.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 1, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2025 Q#1 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_2_q2_2", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 2, "subject": "Biology", "topic": "dna base pairing", "question": "Which of the following base pairing maintains the constant diameter of the DNA double helix as per Watson and Crick's model?", "options": ["Purine - Purine", "Pyrimidine - Pyrimidine", "Purine - Pyrimidine", "Sugar-Phosphate"], "correctIndex": 2, "explanation": "Watson-Crick base pairing pairs a purine with a pyrimidine (A-T and G-C), which preserves the constant width of the DNA double helix. Purine–purine or pyrimidine–pyrimidine pairs would alter the helix diameter.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 2, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2025 Q#2 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_2_q3_3", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 3, "subject": "Biology", "topic": "muscle types voluntary", "question": "Which muscle type is under conscious control and is multinucleated?", "options": ["Smooth muscle", "Skeletal muscle", "Cardiac muscle", "Visceral muscle"], "correctIndex": 1, "explanation": "Skeletal muscle is under voluntary (conscious) control and its fibres are multinucleated. Smooth and cardiac muscles are involuntary; cardiac muscle cells typically have a single nucleus.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 3, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "SZABMU 2025 Q#3 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_2_q4_4", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 4, "subject": "Biology", "topic": "connective tissue cartilage", "question": "Which of the following connective tissue is completely avascular and heals slowly?", "options": ["Bone", "Cartilage", "Adipose tissue", "Areolar tissue"], "correctIndex": 1, "explanation": "Cartilage is avascular (lacks blood vessels), so nutrient delivery and repair are slow, leading to poor healing. Bone and most other connective tissues are vascularized.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 4, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "SZABMU 2025 Q#4 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_2_q5_5", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 5, "subject": "Biology", "topic": "cardiac vs skeletal", "question": "Cardiac muscles are different from skeletal muscles because they:", "options": ["Lack striations", "Are voluntary and multinucleated", "Are involuntary and multinucleated", "Are striated but involuntary"], "correctIndex": 3, "explanation": "Cardiac muscle is striated like skeletal muscle but operates involuntarily. Skeletal muscle is striated and voluntary; cardiac cells are generally single-nucleated and connected by intercalated discs.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 5, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SZABMU 2025 Q#5 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_2_q6_6", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 6, "subject": "Biology", "topic": "lysosome biogenesis", "question": "Which organelle give rise to primary lysosomes through budding in eukaryotic cells?", "options": ["Smooth endoplasmic reticulum (SER)", "Rough endoplasmic reticulum (RER)", "Plasma membrane", "Golgi cisternae"], "correctIndex": 3, "explanation": "Primary lysosomes are formed by budding from the Golgi apparatus, which packages hydrolytic enzymes into vesicles. The ER synthesizes proteins and lipids but lysosomal enzymes are processed through the Golgi.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 6, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2025 Q#6 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_2_q7_7", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 7, "subject": "Biology", "topic": "keratin disulfide bonds", "question": "A mutation prevents proper disulphide bond formation in a fibrous protein, causing brittle nails and slow hair growth. Which of the following proteinaceous substance would be affected?", "options": ["Elastin", "Actin", "Keratin", "Collagen"], "correctIndex": 2, "explanation": "Keratin is a fibrous protein rich in cysteine residues that form disulfide bonds important for hair and nail strength. Disruption of disulfide bonds in keratin leads to brittleness; elastin and collagen have different crosslinks.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 7, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2025 Q#7 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_2_q8_8", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 8, "subject": "Biology", "topic": "t tubules function", "question": "In muscle fibers, T-tubules are extension of the sarcolemma that penetrate into the cell's interior. What is their main function during muscle contraction?", "options": ["Unblock actin's binding sites.", "Conduct nerve impulses deep into the muscle cell.", "Synthesize glycogen in the sarcoplasm.", "Store calcium ions within the sarcoplasmic reticulum."], "correctIndex": 1, "explanation": "T-tubules conduct action potentials from the sarcolemma into the muscle fibre's interior, triggering calcium release from the sarcoplasmic reticulum and enabling coordinated contraction. They do not synthesize glycogen or store calcium.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 8, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2025 Q#8 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_2_q9_9", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 9, "subject": "Biology", "topic": "polysaccharide function", "question": "Polysaccharides such as starch and glycogen are mainly used for:", "options": ["Structural framework only", "Short-term and long-term energy storage", "Enzyme catalysis", "Ready source of energy"], "correctIndex": 1, "explanation": "Starch (in plants) and glycogen (in animals) are polysaccharides whose primary roles are energy storage - starch for longer-term storage in plants and glycogen for shorter-term storage in animals. They are not enzymes or primarily structural in these contexts.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 9, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2025 Q#9 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_2_q10_10", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 10, "subject": "Biology", "topic": "histone amino acids", "question": "In chromosome, positively charged histone proteins are organized with negatively charged DNA. The positive charges of histone are due to an abundance of basic amino acids:", "options": ["arginine and alanine", "arginine and lysine", "lysine and alanine", "phenylalanine and arginine"], "correctIndex": 1, "explanation": "Histones are rich in basic amino acids arginine and lysine, whose positively charged side chains bind the negatively charged DNA phosphate backbone. Alanine and phenylalanine are not basic residues.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 10, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2025 Q#10 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_2_q11_11", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 11, "subject": "Biology", "topic": "viral envelope origin", "question": "Envelope in a virus is derived from", "options": ["Host cell ribosomes", "Host cell membrane", "Viral capsid proteins", "Viral genome replication"], "correctIndex": 1, "explanation": "Enveloped viruses acquire their lipid envelope from the host cell membrane (plasma membrane or internal membranes) during budding. The envelope is not derived from ribosomes, capsid proteins, or genome replication.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 11, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "SZABMU 2025 Q#11 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2025"}, {"id": "paper_2_q12_12", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 12, "subject": "Biology", "topic": "myelin function", "question": "Myelin sheath acts as;", "options": ["Protector", "Insulator", "Sensor", "Supporter"], "correctIndex": 1, "explanation": "The myelin sheath electrically insulates axons, increasing the speed of action potential conduction via saltatory conduction. Its primary role is insulation rather than sensing or structural support.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 12, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "SZABMU 2025 Q#12 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_2_q13_13", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 13, "subject": "Biology", "topic": "nucleic acid probes", "question": "DNA/RNA probes are most commonly used as:", "options": ["diagnostic tools of infectious diseases", "carrier in gene cloning experiments", "cementing material in somatic cell hybridization", "carrier or vector in gene therapy"], "correctIndex": 0, "explanation": "DNA/RNA probes are widely used as diagnostic tools to detect specific nucleic acid sequences of infectious agents or genetic markers. They are not used as carriers or vectors.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 13, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2025 Q#13 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_2_q14_14", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 14, "subject": "Biology", "topic": "muscle contraction steps", "question": "The event that occurs first during skeletal muscle contraction?", "options": ["Cross-bridge formation", "Release of calcium from sarcoplasmic reticulum", "Power stroke", "Myosin head binds to ATP"], "correctIndex": 1, "explanation": "Release of calcium from the sarcoplasmic reticulum is an early step triggered by excitation-contraction coupling; calcium binding to troponin exposes actin sites, allowing cross-bridge formation and subsequent power stroke.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 14, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "SZABMU 2025 Q#14 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_2_q15_15", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 15, "subject": "Biology", "topic": "gene linkage", "question": "When genes are linked, they tend to:", "options": ["Segregate randomly", "Cross over every time", "Stay together during inheritance", "Be inherited separately"], "correctIndex": 2, "explanation": "Linked genes are located close together on the same chromosome and tend to be inherited together (unless crossing over separates them). They do not segregate independently.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 15, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "SZABMU 2025 Q#15 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_2_q16_16", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 16, "subject": "Biology", "topic": "morgan experiment", "question": "According to Morgan's experiment, which of the following is essential for detecting gene linkage accurately?", "options": ["Large number of progeny", "Small sample size", "Use of male flies only", "Mutation induction"], "correctIndex": 0, "explanation": "Detecting linkage and estimating recombination frequencies requires large progeny numbers to observe rare recombinants reliably. Small samples or restricting to one sex would reduce accuracy.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 16, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "SZABMU 2025 Q#16 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_2_q17_17", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 17, "subject": "Biology", "topic": "muscle attachment", "question": "The end of skeletal muscle attached with moveable bone is:", "options": ["Insertion", "Origin", "Tendons", "Belly"], "correctIndex": 0, "explanation": "The insertion of a muscle is the attachment to the moveable bone; the origin is the less movable attachment. Tendons are connective tissue structures that attach muscle to bone, while the belly is the muscle's fleshy part.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 17, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "SZABMU 2025 Q#17 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_2_q18_18", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 18, "subject": "Biology", "topic": "steroid hormones commonality", "question": "Which of the following is common between aldosterone, sex hormone and cortisone ?", "options": ["They are peptides", "They are Phospholipids", "They are steroids", "They are glycoproteins"], "correctIndex": 2, "explanation": "Aldosterone, sex hormones (e.g. testosterone, estrogen) and cortisone are all steroid hormones synthesized from cholesterol, so they share the steroid structure. They are not peptides, phospholipids, or glycoproteins.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 18, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "SZABMU 2025 Q#18 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_2_q19_19", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 19, "subject": "Biology", "topic": "nitrogenous excretion uricotelic", "question": "Which one of the following organism is uricotolic with reference to excretion of nitrogenous compound?", "options": ["Human", "freshwater Fish", "Snake", "Frog"], "correctIndex": 2, "explanation": "Uricotelic animals excrete nitrogenous waste as insoluble uric acid, which conserves water. Reptiles, birds and insects are uricotelic, so the snake is the answer. Humans and frogs are ureotelic (urea) and freshwater fish are ammonotelic (ammonia).", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 19, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "SZABMU 2025 Q#19 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_2_q20_20", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 20, "subject": "Biology", "topic": "ureotelism adaptation", "question": "Ureotelism (removal of nitrogenous waste in the form of urea) is an adaptation to the:", "options": ["cold weather", "less availability of water", "flooded environmental conditions", "food shortage"], "correctIndex": 1, "explanation": "Urea is much less toxic than ammonia and needs far less water to excrete, so ureotelism is an adaptation to limited water availability on land. Ammonotelic animals need abundant water and are aquatic, while uricotelic animals conserve water most strictly.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 20, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "SZABMU 2025 Q#20 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_2_q21_21", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 21, "subject": "Biology", "topic": "limbic system characteristics", "question": "All of the following are the characteristics of limbic system EXCEPT:", "options": ["Produce most basic and primitive emotions and drives", "formation of memories", "Consists of hypothalamus, amygdala and hippocampus", "controls reflex movement of eyes"], "correctIndex": 3, "explanation": "The limbic system produces primitive emotions and drives, helps form memories, and is made up of the hypothalamus, amygdala and hippocampus. Reflex movements of the eyes are controlled by the midbrain, not the limbic system, so that statement is the exception.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 21, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2025 Q#21 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_2_q22_22", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 22, "subject": "Biology", "topic": "sensory pathways distribution", "question": "Sensory input from auditory and visual pathways, skin and within the body is received by _______ and distributed to ________", "options": ["Hypothalamus: Cerebellum", "Thalamus: cerebrum", "Cerebrum: rest of the brain", "Cerebellum: rest of the brain"], "correctIndex": 1, "explanation": "The thalamus is the brain's main sensory relay station: it receives input from the auditory and visual pathways, the skin and the interior of the body, and distributes it to the cerebrum for processing. The hypothalamus, cerebrum and cerebellum do not serve as this general sensory relay.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 22, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2025 Q#22 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_2_q23_23", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 23, "subject": "Biology", "topic": "lamarck theory use and disuse", "question": "According to the Lamarck theory of evolution, the organ that has not been used in several generations will:", "options": ["Become strong", "Get amputated", "Disappear", "Become developed"], "correctIndex": 2, "explanation": "Lamarck's theory of use and disuse held that an organ not used over several generations gradually weakens and eventually disappears, while a used organ becomes stronger and more developed. So an unused organ is said to disappear.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 23, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "SZABMU 2025 Q#23 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2025"}, {"id": "paper_2_q24_24", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 24, "subject": "Biology", "topic": "enzyme inhibition and action", "question": "Which of the following statement is incorrect with reference to the enzyme action?", "options": ["Substrate binds with the enzyme at its active site", "Non-competitive inhibitor binds the enzyme at a site distinct from that of active site", "Addition of a lot of succinate do not reverse the inhibition of succinic dehydrogenase by malonate", "malonate is a competitive inhibitor of succinic dehydogenase"], "correctIndex": 2, "explanation": "Malonate is a competitive inhibitor of succinic dehydrogenase, and competitive inhibition is reversed by adding excess substrate. The statement that adding a lot of succinate does not reverse the inhibition is therefore incorrect; the other three statements describe enzyme action correctly.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 24, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2025 Q#24 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_2_q25_25", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 25, "subject": "Physics", "topic": "groundwater temperature constancy", "question": "The temperature of underground water remains constant due to:", "options": ["Heat capacity", "Polarity of water", "Heat of vaporization", "Specific heat of vaporization"], "correctIndex": 0, "explanation": "Water has a very high heat capacity, so it can absorb or release a large amount of heat with only a small change in its own temperature. This is why the temperature of underground water stays nearly constant.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 25, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "SZABMU 2025 Q#25 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2025"}, {"id": "paper_2_q26_26", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 26, "subject": "Biology", "topic": "adenovirus shape", "question": "The shape of Adenovirus is:", "options": ["Helical shape", "Tadpole shape", "Polyhedron shape", "Circular shape"], "correctIndex": 2, "explanation": "Adenovirus has an icosahedral capsid, which is a polyhedron shape. A helical shape describes viruses such as the tobacco mosaic virus, and the tadpole shape describes bacteriophages.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 26, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "SZABMU 2025 Q#26 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2025"}, {"id": "paper_2_q27_27", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 27, "subject": "Biology", "topic": "ovulation timing", "question": "In human female normally ovulation occurs at day _____ of menstrual cycle.", "options": ["9", "11", "14", "15"], "correctIndex": 2, "explanation": "In a typical 28-day menstrual cycle, ovulation occurs around day 14, triggered by the mid-cycle surge in LH.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 27, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "SZABMU 2025 Q#27 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2025"}, {"id": "paper_2_q28_28", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 28, "subject": "Biology", "topic": "glycolysis atp production", "question": "How many ATPs are produced during oxidative phase of glycolysis?", "options": ["2", "4", "34", "36"], "correctIndex": 1, "explanation": "In the oxidative (pay-off) phase of glycolysis, each of the two triose molecules yields 2 ATP by substrate-level phosphorylation, so 4 ATP are produced. Because 2 ATP were invested in the earlier phase, glycolysis has a net gain of 2 ATP.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 28, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2025 Q#28 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_2_q29_29", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 29, "subject": "Biology", "topic": "er golgi relationship", "question": "Which of the following best describes the relationship between endoplasmic reticulum (ER) and Golgi apparatus?", "options": ["Both ER and Golgi apparatus are completely separate organelles with no interaction", "ER is precursor organelle to Golgi apparatus because material is transported from ER to Golgi", "Golgi apparatus is precursor organelle to ER because material is transported from Golgi to ER", "ER and Golgi apparatus have similar roles"], "correctIndex": 1, "explanation": "The ER is a precursor to the Golgi apparatus: proteins and lipids made in the ER are packaged into vesicles and carried to the Golgi for further processing. They are not separate non-interacting organelles, and material is not transported from Golgi to ER.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 29, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2025 Q#29 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_2_q30_30", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 30, "subject": "Biology", "topic": "renal inner medulla osmotic gradient", "question": "Osmotic gradient of inner medulla of kidney is increased by:", "options": ["Urea", "Water", "Phosphate", "Potassium"], "correctIndex": 0, "explanation": "Urea recycling in the inner medullary collecting ducts adds solute to the medullary interstitium, raising its osmotic gradient alongside sodium chloride. This steep gradient is what allows the kidney to concentrate urine.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 30, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "SZABMU 2025 Q#30 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_2_q31_31", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 31, "subject": "Biology", "topic": "fsh suppression release trigger", "question": "Decreased level of FSH hormone during menstrual cycle triggers the release of:", "options": ["hcg", "LH", "Oxytocin", "progesterone"], "correctIndex": 1, "explanation": "As the follicle matures, rising oestrogen feeds back to lower FSH and trigger the LH surge, and it is that LH surge that causes ovulation. hCG comes from the placenta, while oxytocin and progesterone are not released in response to falling FSH here.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 31, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "SZABMU 2025 Q#31 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_2_q32_32", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 32, "subject": "Biology", "topic": "digestive secretions antimicrobial role", "question": "The digestive secretions from different parts of GIT have the ability to kill microbe present in the food. Which of the following best describes this role?", "options": ["Antiseptics", "Disinfectants", "Chemotherapeutics", "Immunosuppressant"], "correctIndex": 0, "explanation": "Substances that kill or inhibit microbes on or within living tissue act as antiseptics, so the antimicrobial digestive secretions play an antiseptic role. Disinfectants are used on non-living surfaces, and the other options describe drugs rather than secretions.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 32, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2025 Q#32 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_2_q33_33", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 33, "subject": "Biology", "topic": "hemophilia carrier outcomes", "question": "A carrier mother for hemophilia and a normal father can produce:", "options": ["All hemophilic sons", "25 % Hemophilic among sons", "50 % hemophilic among sons", "All normal sons and daughter"], "correctIndex": 2, "explanation": "Haemophilia is X-linked recessive. A carrier mother has one normal and one affected X, and a normal father has a normal X and a Y. Half of their sons inherit the affected X and are haemophilic, so about 50% of the sons are affected; daughters are unaffected but half are carriers.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 33, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2025 Q#33 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_2_q34_34", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 34, "subject": "Biology", "topic": "ventricular systole pressure changes", "question": "During ventricular systole, which pressure changes occur?", "options": ["Ventricular pressure rises above atrial and arterial pressures", "Atrial pressure rises above Ventricular pressure", "Ventricular pressure falls below arterial pressures", "Ventricular pressure falls below Atrial pressure"], "correctIndex": 0, "explanation": "During ventricular systole the ventricles contract, so ventricular pressure rises above atrial pressure (closing the AV valves) and then above arterial pressure (opening the semilunar valves to eject blood). The other options describe what happens in diastole.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 34, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SZABMU 2025 Q#34 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_2_q35_35", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 35, "subject": "Biology", "topic": "helper t cells b and t cell division", "question": "Which cell type is essential for stimulating cell division of both B-cells and T-cells?", "options": ["Plasma cells", "Memory cells", "Helper T-cells", "Neutrophils"], "correctIndex": 2, "explanation": "Helper T-cells release cytokines such as interleukins that stimulate the proliferation of both B-cells and other T-cells, which is why they are central to the immune response. Plasma and memory cells are products of that response, and neutrophils are phagocytes.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 35, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2025 Q#35 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_2_q36_36", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 36, "subject": "Biology", "topic": "hormone hypercalcemia", "question": "The hormone, when overproduced can lead to hypercalcemia and stone formation is:", "options": ["Insulin", "Thyroxine", "Parathyroid hormone", "Antidiuretic hormone"], "correctIndex": 2, "explanation": "Parathyroid hormone raises blood calcium by acting on bone, kidney and gut; when overproduced it causes hypercalcaemia and can lead to kidney stones. Insulin, thyroxine and antidiuretic hormone do not raise blood calcium.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 36, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "SZABMU 2025 Q#36 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_2_q37_37", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 37, "subject": "Biology", "topic": "connective tissue types", "question": "Fibrocartilage is found in:", "options": ["Trachea", "Nose", "Knee joint", "Ear flaps"], "correctIndex": 2, "explanation": "Fibrocartilage occurs in structures that require strong support and shock absorption such as intervertebral discs and the menisci of the knee joint. The trachea and nose are hyaline cartilage, and ear flaps are elastic cartilage.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 37, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "SZABMU 2025 Q#37 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_2_q38_38", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 38, "subject": "Biology", "topic": "renal microcirculation", "question": "Additional capillaries present in the juxtamedullary nephrons to form a loop of vessels are:", "options": ["Efferent arterioles", "Peritubular capillaries", "Vasa recta", "Afferent arterioles"], "correctIndex": 2, "explanation": "Juxtamedullary nephrons have long loops of Henle surrounded by the vasa recta, specialized capillaries that form a countercurrent exchange system. Peritubular capillaries are associated with cortical nephrons; afferent/efferent arterioles are upstream vessels.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 38, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SZABMU 2025 Q#38 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_2_q39_39", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 39, "subject": "Biology", "topic": "patterns of inheritance", "question": "Y-linked inheritance refers to which mode of the inheritance?", "options": ["Crisscross", "Straight", "Loop", "Jumping"], "correctIndex": 1, "explanation": "Y-linked traits follow a straight transmission from father to all sons (but not to daughters) because the Y chromosome is passed directly down the male line. 'Crisscross' typically refers to X-linked inheritance patterns.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 39, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "SZABMU 2025 Q#39 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_2_q40_40", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 40, "subject": "Biology", "topic": "sex linked inheritance", "question": "If a colorblind lady marries a normal man, their children will be:", "options": ["Normal daughters and normal sons", "Normal sons and carrier daughters", "Colorblind sons and carrier daughters", "Colorblind sons and colorblind daughters"], "correctIndex": 2, "explanation": "A colorblind mother (XcXc) and normal father (XY) will produce daughters who are carriers (XcX) and sons who are colorblind (XcY). Thus children will be colorblind sons and carrier daughters.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 40, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "SZABMU 2025 Q#40 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_2_q41_41", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 41, "subject": "Biology", "topic": "properties of water", "question": "All of the following properties of water are associated with its capillary action. EXCEPT:", "options": ["Adhesion", "Density", "Cohesion", "Surface tension"], "correctIndex": 1, "explanation": "Capillary action relies on adhesion between water and vessel walls, cohesion between water molecules and surface tension; density is not a factor in capillary rise and therefore is the exception.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 41, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SZABMU 2025 Q#41 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_2_q42_42", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 42, "subject": "Biology", "topic": "golgi apparatus", "question": "Which organelle serves as a packaging and a distribution center for molecules within the cells?", "options": ["Golgi apparatus", "Mitochondria", "Ribosome", "Vacuole"], "correctIndex": 0, "explanation": "The Golgi apparatus modifies, sorts and packages proteins and lipids for secretion or delivery to other organelles, functioning as the cell's packaging and distribution center. Mitochondria produce ATP and ribosomes synthesize proteins.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 42, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2025 Q#42 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_2_q43_43", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 43, "subject": "Biology", "topic": "endocrine hormone production", "question": "Which of the following hormone is not produced in older women?", "options": ["Estrogen", "Gastrin", "Secretin", "Renin"], "correctIndex": 0, "explanation": "Estrogen production falls markedly after menopause in older women and may be effectively absent compared with reproductive years, whereas gastrin, secretin and renin continue to be produced by their respective organs.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 43, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "SZABMU 2025 Q#43 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_2_q44_44", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 44, "subject": "Biology", "topic": "lymphatic structures", "question": "Which lymphatic structure absorbs dietary fats in the intestine?", "options": ["Peyer's patches", "Lacteals in villi", "Pancreatic duct", "Lymph nodes"], "correctIndex": 1, "explanation": "Lacteals are lymphatic capillaries in intestinal villi that absorb dietary fats as chylomicrons into the lymphatic system. Peyer's patches are lymphoid tissue involved in immune surveillance, not fat absorption.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 44, "syllabusUnit": "Unit 5: Human Physiology - Digestion & Nutrition", "pmdcTopic": "Human Digestive System & Absorption Mechanisms", "textbookCitation": "PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12", "citationString": "SZABMU 2025 Q#44 | Unit 5: Human Physiology - Digestion & Nutrition | PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12"}, "year": "2025"}, {"id": "paper_2_q45_45", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 45, "subject": "Biology", "topic": "male reproductive anatomy", "question": "The part of male reproductive system that maintains the temperature for sperm production is:", "options": ["Testes", "Scrotum", "Vas deferens", "Epididymis"], "correctIndex": 1, "explanation": "The scrotum regulates the temperature of the testes, keeping them slightly cooler than core body temperature, which is essential for optimal spermatogenesis. The testes are the site of sperm production, but temperature is controlled by the scrotum.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 45, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2025 Q#45 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_2_q46_46", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 46, "subject": "Biology", "topic": "immunosuppression after transplant", "question": "After Liver transplant, doctors suppress the T-lymphocyte activity in patient. Why?", "options": ["To increase the rate of antibody production", "To prevent infections", "To avoid graft rejection immune system", "To produce memory cells faster"], "correctIndex": 2, "explanation": "T-lymphocytes mediate cellular immune responses responsible for graft rejection; suppressing T-cell activity reduces the chance of the recipient's immune system attacking the transplanted organ. Immunosuppression actually increases infection risk rather than preventing it.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 46, "syllabusUnit": "Unit 5: Human Physiology - Digestion & Nutrition", "pmdcTopic": "Human Digestive System & Absorption Mechanisms", "textbookCitation": "PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12", "citationString": "SZABMU 2025 Q#46 | Unit 5: Human Physiology - Digestion & Nutrition | PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12"}, "year": "2025"}, {"id": "paper_2_q47_47", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 47, "subject": "Biology", "topic": "calcium homeostasis", "question": "How do the kidneys contribute to maintain normal blood calcium level?", "options": ["By storing excess calcium", "By reabsorbing calcium and activating vitamin D", "By secreting calcium directly into the blood", "By converting calcium into urea for excretion"], "correctIndex": 1, "explanation": "Kidneys reabsorb filtered calcium and convert 25-hydroxyvitamin D to its active form (1,25-dihydroxyvitamin D), which increases intestinal calcium absorption, both actions helping maintain blood calcium. They do not store calcium or convert it to urea.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 47, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SZABMU 2025 Q#47 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_2_q48_48", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 48, "subject": "Biology", "topic": "axon physiology", "question": "Nodes of Ranvier along the length of axons fibers allow:", "options": ["More diffusion of neurotransmitters", "Saltatory conduction of nerve impulse", "Formation of new synaptic connections", "Synthesis of new neurons"], "correctIndex": 1, "explanation": "Nodes of Ranvier are gaps in myelination that allow action potentials to 'jump' from node to node (saltatory conduction), increasing conduction velocity. They are not involved in neurotransmitter diffusion or neurogenesis.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 48, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2025 Q#48 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_2_q49_49", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 49, "subject": "Biology", "topic": "arachidonic acid", "question": "Arachidonic acid, which is the precursor molecule for prostaglandins is:", "options": ["A saturated fatty acid with 18 carbons", "An unsaturated fatty acid with 18 carbons", "A tri-unsaturated fatty acid with 20 carbons", "A tetra-unsaturated fatty acid with 20 carbons"], "correctIndex": 3, "explanation": "Arachidonic acid is a 20-carbon polyunsaturated fatty acid with four double bonds (tetra-unsaturated), and it is the precursor for prostaglandins and leukotrienes. It is not 18 carbons nor saturated.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 49, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2025 Q#49 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_2_q50_50", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 50, "subject": "Biology", "topic": "cardiac anatomy", "question": "Atrial walls are thinner as compared to ventricles because:", "options": ["Atria are small in size", "Atria are present above the ventricles", "Atria has to force blood into the ventricles which lie very close to them", "Blood enters into the atria by osmosis"], "correctIndex": 2, "explanation": "Atria pump blood only a short distance into adjacent ventricles and therefore require less muscular wall thickness than ventricles, which must pump blood systemically or to the lungs. The other options are not correct physiological explanations.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 50, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SZABMU 2025 Q#50 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_2_q51_51", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 51, "subject": "Biology", "topic": "gene therapy", "question": "A patient with a genetic disorder undergoes treatment where a normal gene is inserted into their cells. This is called", "options": ["Gene therapy", "Genetic testing", "Protein engineering", "DNA fingerprinting"], "correctIndex": 0, "explanation": "Gene therapy involves inserting functional genes into a patient's cells to correct a genetic disorder. Genetic testing diagnoses genetic conditions; protein engineering and DNA fingerprinting are different techniques.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 51, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2025 Q#51 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_2_q52_52", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 52, "subject": "Biology", "topic": "chronic renal failure", "question": "Which of the following is a potential symptom of chronic renal failure?", "options": ["Nephritis and bacterial infection", "Bone pain and fractures", "Impaired concentration and confusion", "Muscle cramps due to electrolyte imbalance"], "correctIndex": 2, "explanation": "Chronic renal failure leads to accumulation of toxins and electrolyte disturbances that can cause impaired concentration and confusion (uremic encephalopathy). Although bone disease and muscle cramps can occur, confusion is a classic potential symptom.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 52, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2025 Q#52 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_2_q53_53", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 53, "subject": "Biology", "topic": "arthritis", "question": "Arthritis is a disease that primarily affects the:", "options": ["Kidneys", "Lungs", "Joints", "Muscles"], "correctIndex": 2, "explanation": "Arthritis is inflammation of the joints and primarily affects joint structures. It is not primarily a disease of kidneys, lungs, or muscles.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 53, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2025 Q#53 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_2_q54_54", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 54, "subject": "Biology", "topic": "osmoreceptors location", "question": "Osmoreceptors that detect the osmotic pressure of blood are primarily located in the:", "options": ["Cerebellum", "Medulla oblongata", "Hypothalamus", "Cerebral cortex"], "correctIndex": 2, "explanation": "Osmoreceptors that sense plasma osmolality are located in the hypothalamus (specifically around the organum vasculosum and supraoptic region), and they regulate ADH release. The cerebellum, medulla oblongata, and cortex do not house primary osmoreceptors.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 54, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SZABMU 2025 Q#54 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_2_q55_55", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 55, "subject": "Biology", "topic": "weismann experiment", "question": "Lamarck theory of evolution was rejected experimentally by:", "options": ["Earnest Hackle", "Charles Darwin", "August Weismann", "Thomas R Malthas"], "correctIndex": 2, "explanation": "August Weismann experimentally disproved Lamarckian inheritance by cutting off the tails of many generations of mice and showing offspring still developed normal tails, supporting the germ‑line separation concept. Darwin proposed natural selection, Hackel (Haeckel) and Malthus are not the experimental refuters.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 55, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "SZABMU 2025 Q#55 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2025"}, {"id": "paper_2_q56_56", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 56, "subject": "Biology", "topic": "disaccharide common characteristic", "question": "Which of the following characteristics is common among sucrose, lactose and maltose?", "options": ["molecular formula", "occurrence in living beings", "chemical nature of their monosaccharide units", "to act as reducing sugar"], "correctIndex": 0, "explanation": "Sucrose, lactose and maltose are all disaccharides with the same molecular formula, C12H22O11 — they are isomers of one another. They differ in their monosaccharide units and in whether they are reducing sugars, so the molecular formula is the feature common to all three.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 56, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2025 Q#56 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_2_q57_57", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 57, "subject": "Biology", "topic": "ribozymes composition", "question": "Ribozymes are the biocatalysts that are made up of:", "options": ["DNA", "RNA", "Protein", "Fatty acid"], "correctIndex": 1, "explanation": "Ribozymes are catalytic RNA molecules whose structure and sequence allow them to catalyze specific biochemical reactions. They are not made of DNA, protein, or fatty acids.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 57, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2025 Q#57 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_2_q58_58", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 58, "subject": "Biology", "topic": "induced fit model", "question": "The induced fit model differs from the Lock and Key model because the enzyme in this model:", "options": ["Has a rigid and fixed active site", "Changes shape to fit the substrate", "Is non-specific in its action", "Is denatured during reaction"], "correctIndex": 1, "explanation": "The induced‑fit model describes enzymes whose active sites undergo conformational changes upon substrate binding to better accommodate the substrate, unlike a rigid lock‑and‑key. The other options are incorrect descriptions of induced fit.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 58, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2025 Q#58 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_2_q59_59", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 59, "subject": "Biology", "topic": "penicillin cell wall synthesis", "question": "Which competitive inhibitor blocks the enzyme responsible for bacterial cell wall synthesis?", "options": ["Sulphonamide", "Streptomycin", "Tetracycline", "Penicillin"], "correctIndex": 3, "explanation": "Penicillin targets enzymes involved in peptidoglycan crosslinking (transpeptidases), inhibiting bacterial cell wall synthesis and leading to cell lysis. The other drugs act on different targets (protein synthesis or folate pathway).", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 59, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2025 Q#59 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_2_q60_60", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 60, "subject": "Biology", "topic": "water universal solvent", "question": "Water commonly known as a universal solvent because:", "options": ["It dissolves polar and ionic substances effectively", "It supports chemical reactions without reacting itself", "It has a high specific heat capacity", "It dissolves many substances due to its small molecule size"], "correctIndex": 0, "explanation": "Water's polarity and ability to form hydrogen bonds make it excellent at dissolving polar and ionic substances, which is why it is called a universal solvent. The other properties listed are true in part but are not the primary reason for its universal solvent behavior.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 60, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2025 Q#60 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_2_q61_61", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 61, "subject": "Biology", "topic": "ice low density", "question": "Which of the following structural change in water molecule leads to the low density of ice?", "options": ["Formation of ionic bonds", "Expansion due to hydrogen bonding", "Increased kinetic energy", "Loss of polarity in molecules"], "correctIndex": 1, "explanation": "When water freezes, a hydrogen‑bonded lattice forms that spaces molecules farther apart than in liquid water, causing expansion and lower density of ice. The other choices do not describe the physical basis for ice's lower density.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 61, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2025 Q#61 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_2_q62_62", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 62, "subject": "Chemistry", "topic": "water as solvent", "question": "Water commonly known as a universal solvent because:", "options": ["A. It dissolves polar and ionic substances effectively", "B. It supports chemical reactions without reacting itself", "C. It has a high specific heat capacity", "D. It dissolves many substances due to its small molecule size"], "correctIndex": 0, "explanation": "Water is called a universal solvent mainly because of its polarity and ability to dissolve many ionic and polar substances effectively.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 62, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2025 Q#62 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_2_q63_63", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 63, "subject": "Chemistry", "topic": "ice density", "question": "Which of the following structural change in water molecule leads to the low density of ice?", "options": ["A. Formation of ionic bonds", "B. Expansion due to hydrogen bonding", "C. Increased kinetic energy", "D. Loss of polarity in molecules"], "correctIndex": 1, "explanation": "Ice has a lower density because hydrogen bonding holds water molecules in an open hexagonal lattice that occupies more volume than liquid water.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 63, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2025 Q#63 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_2_q64_64", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 64, "subject": "Chemistry", "topic": "reduction reagents", "question": "Reduction of carboxylic acid by using lithium aluminiumhydride produce", "options": ["A. Alcohol", "B. acid halide", "C. ester", "D. alkane"], "correctIndex": 0, "explanation": "LiAlH4 is a strong reducing agent that reduces carboxylic acids to primary alcohols.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 64, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "SZABMU 2025 Q#64 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2025"}, {"id": "paper_2_q65_65", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 65, "subject": "Chemistry", "topic": "equilibrium yield", "question": "In separate vessel of volume 2000 cm3 and 1500cm3, 6g of hydrogen and 28g of nitrogen are mixed in each vessel at 25°C, ammonia formed is?  N2 + 3H2 ⇌ 2NH3", "options": ["A. More in 2 L vessel", "B. More in 1500 cm^3 vessel", "C. Equal in both vessel", "D. Cannot be predicted"], "correctIndex": 1, "explanation": "At the same amounts of reactants, higher concentration (smaller volume) shifts equilibrium toward product formation, so more NH3 forms in the smaller (1500 cm3) vessel.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 65, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "SZABMU 2025 Q#65 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2025"}, {"id": "paper_2_q66_66", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 66, "subject": "Chemistry", "topic": "intermolecular forces", "question": "The weakest intermolecular force present in liquid is?", "options": ["A. dipole dipole forces", "B. induce dipole force", "C. Instantaneous dipole induced dipole force", "D. hydrogen bonding"], "correctIndex": 2, "explanation": "Instantaneous dipole-induced dipole (London dispersion) forces are typically the weakest among the listed intermolecular interactions in many liquids.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 66, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SZABMU 2025 Q#66 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_2_q67_67", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 67, "subject": "Chemistry", "topic": "molecular orientation", "question": "Orientation of molecule is more important in following cases except:", "options": ["A. High Pressure", "B. complex molecules", "C. poly atomic molecules", "D. low pressure"], "correctIndex": 3, "explanation": "At low pressure, collisions are less frequent and orientation is generally less critical; at high pressure or with complex/multi-atomic molecules orientation matters more in reactions.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 67, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2025 Q#67 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_2_q68_68", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 68, "subject": "Chemistry", "topic": "density pressure", "question": "Keeping temperature constant, if pressure is increased, density of gas will", "options": ["A. Increases", "B. decreases", "C. gets doubled", "D. remains same"], "correctIndex": 0, "explanation": "At constant temperature (Boyle's law), increasing pressure reduces volume and thus increases density of a gas.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 68, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SZABMU 2025 Q#68 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_2_q69_69", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 69, "subject": "Chemistry", "topic": "chloroform iupac", "question": "IUPAC name of chloroform is:", "options": ["A. methylchloride", "B. methyltrichloride", "C. trichloromethane", "D. chloromethane"], "correctIndex": 2, "explanation": "Chloroform's systematic name is trichloromethane (CHCl3).", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 69, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2025 Q#69 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_2_q70_70", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 70, "subject": "Chemistry", "topic": "alkyne reactions", "question": "Which among the following will react with ammonical cuprous chloride:", "options": ["A. 1-butene", "B. 1-butyne", "C. 2-butene", "D. 2-butyne"], "correctIndex": 1, "explanation": "Terminal alkynes (like 1-butyne) give a precipitate with ammoniacal cuprous chloride (the test for terminal alkyne).", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 70, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "SZABMU 2025 Q#70 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2025"}, {"id": "paper_2_q71_71", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 71, "subject": "Chemistry", "topic": "crystalline vs amorphous", "question": "Which of the following is not a crystalline solid?", "options": ["A. KCl", "B. Fe metal", "C. Glass", "D. rhombic S"], "correctIndex": 2, "explanation": "Glass is an amorphous solid (non-crystalline), whereas KCl, many metals, and rhombic sulfur are crystalline.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 71, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SZABMU 2025 Q#71 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_2_q72_72", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 72, "subject": "Chemistry", "topic": "electron orbital count", "question": "Number of electron with l=2 in an atom having atomic number 23 is:", "options": ["A. 2", "B. 3", "C. 4", "D. 5"], "correctIndex": 1, "explanation": "The l = 2 electrons are the d electrons. Vanadium (atomic number 23) has the configuration [Ar] 3d3 4s2, so it has 3 electrons with l = 2.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 72, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "SZABMU 2025 Q#72 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2025"}, {"id": "paper_2_q73_73", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 73, "subject": "Chemistry", "topic": "orientation factor", "question": "Orientation of molecule is more important in following cases except:", "options": ["A. high Pressure", "B. complex molecules", "C. poly atomic molecules", "D. low pressure"], "correctIndex": 3, "explanation": "Orientation factor (steric factor) matters in bimolecular collisions where directional approach affects reaction probability; it is important for complex or polyatomic molecules and at high pressures where collisions are frequent. At low pressure collisions are rare so orientation is less important, making option D the exception.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 73, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2025 Q#73 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_2_q74_74", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 74, "subject": "Chemistry", "topic": "activation energy", "question": "Reaction having high activation energy are:", "options": ["A. spontaneous", "B. fast", "C. slow", "D. always exothermic"], "correctIndex": 2, "explanation": "A high activation energy barrier makes the rate of reaction slow because fewer collisions have sufficient energy to overcome the barrier. Spontaneity and enthalpy (exothermic) are unrelated to activation energy.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 74, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "SZABMU 2025 Q#74 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2025"}, {"id": "paper_2_q75_75", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 75, "subject": "Chemistry", "topic": "kinetic molecular theory", "question": "According to the Kinetic molecular theory, the kinetic energy of gas molecules increases when they are", "options": ["A. melted from solid to liquid state", "B. mixed with other molecules at lower temperature", "C. frozen into solids", "D. condensed into liquids"], "correctIndex": 0, "explanation": "Kinetic energy of molecules increases when thermal energy is added, such as during melting (solid → liquid). Freezing or condensation remove energy and reduce kinetic energy; mixing with colder molecules lowers average kinetic energy.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 75, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SZABMU 2025 Q#75 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_2_q76_76", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 76, "subject": "Chemistry", "topic": "equilibrium expression stoichiometry", "question": "If the equilibrium expression of a reversible reaction is [C]2/[A][B]\nThe balanced chemical equation should be", "options": ["A. C=A+B", "B. 2C=A+B", "C. A+B=C", "D. A + B = 2C"], "correctIndex": 3, "explanation": "If the equilibrium constant expression is [C]^2/[A][B], the balanced equation must be A + B ⇌ 2 C so that the exponent on [C] is 2. Option D matches that stoichiometry.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 76, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "SZABMU 2025 Q#76 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2025"}, {"id": "paper_2_q77_77", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 77, "subject": "Chemistry", "topic": "benzene 1 3 diol common name", "question": "Common name of 1,3 benzene diol is:", "options": ["A. Pyrogallol", "B. Cresol", "C. Resorcinol", "D. Catechol"], "correctIndex": 2, "explanation": "1,3-benzenediol is commonly called resorcinol. Catechol is 1,2-benzenediol and pyrogallol is 1,2,3-benzenetriol; cresol is methylphenol (a different compound).", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 77, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "SZABMU 2025 Q#77 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2025"}, {"id": "paper_2_q78_78", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 78, "subject": "Chemistry", "topic": "bonding in maleic anhydride", "question": "How many sigma and pi bonds are present in maleic anhydride?", "options": ["A. 5 sigma 3 pi", "B. 6 sigma 3 pi", "C. 7 sigma 2 pi", "D. 9 sigma 3 pi"], "correctIndex": 3, "explanation": "Maleic anhydride (C4H2O3) is a five-membered ring. Counting the bonds: 5 ring sigma bonds, 2 sigma bonds from the two C=O groups and 2 C-H sigma bonds give 9 sigma; the two C=O bonds and the one C=C bond give 3 pi. So it has 9 sigma and 3 pi bonds.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 78, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "SZABMU 2025 Q#78 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2025"}, {"id": "paper_2_q79_79", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 79, "subject": "Chemistry", "topic": "benzene chlorination evidence", "question": "Addition of three molecules of chlorine into benzene prove that benzene has", "options": ["A. double bonds", "B. non polar", "C. planar", "D. non planer"], "correctIndex": 0, "explanation": "Benzene adds three molecules of chlorine to form C6H6Cl6, taking up three molecules of the halogen. That 3:1 addition is the classic evidence that benzene contains the equivalent of three double bonds (a degree of unsaturation of three).", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 79, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "SZABMU 2025 Q#79 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2025"}, {"id": "paper_2_q80_80", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 80, "subject": "Chemistry", "topic": "propyl hcl reaction products", "question": "Propyle is allowed to react with hydrochloric acid two times then final product is", "options": ["A. 1,1-dichloropropane", "B. 1,2-dichloropropane", "C. 2,2-dichloropropane", "D. 1,2-dichoropropene"], "correctIndex": 2, "explanation": "Following Markovnikov's rule, propyne adds the first HCl to give 2-chloropropene, and the second HCl adds to the same carbon to give the geminal dihalide 2,2-dichloropropane.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 80, "syllabusUnit": "Unit 12: Carboxylic Acids & Derivatives", "pmdcTopic": "Acidity of Carboxylic Acids & Acyl Derivatives", "textbookCitation": "PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21", "citationString": "SZABMU 2025 Q#80 | Unit 12: Carboxylic Acids & Derivatives | PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21"}, "year": "2025"}, {"id": "paper_2_q81_81", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 81, "subject": "Chemistry", "topic": "ether isomerism", "question": "Diethyl ether and Methyl n-propyl ether are", "options": ["A. position isomers", "B. functional group isomers", "C. metramers", "D. tautomar"], "correctIndex": 2, "explanation": "Diethyl ether (C2H5-O-C2H5) and methyl n-propyl ether (CH3-O-C3H7) share the same molecular formula and the same ether functional group but carry different alkyl groups on either side of the oxygen. Isomers related in this way — same functional group, different alkyl groups around it — are metamers.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 81, "syllabusUnit": "Unit 10: Alkyl Halides, Alcohols & Phenols", "pmdcTopic": "Nucleophilic Substitution, Elimination Reactions & Phenol Acidity", "textbookCitation": "PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19", "citationString": "SZABMU 2025 Q#81 | Unit 10: Alkyl Halides, Alcohols & Phenols | PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19"}, "year": "2025"}, {"id": "paper_2_q82_82", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 82, "subject": "Chemistry", "topic": "oxidation state carbon", "question": "In the given reaction CH3OH -> HCOOH, oxidation state of carbon changes from:", "options": ["A. -2 to 0", "B. -2 to +2", "C. -3 to +2", "D. 0 to +2"], "correctIndex": 1, "explanation": "In methanol (CH3OH) the carbon oxidation state is -2; in formic acid (HCOOH) carbon is +2. Thus the change is from -2 to +2, option B.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 82, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "SZABMU 2025 Q#82 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2025"}, {"id": "paper_2_q83_83", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 83, "subject": "Chemistry", "topic": "enthalpy endothermic", "question": "For endothermic reaction, enthalpy change is:", "options": ["A. ΔHreactant>ΔHproduct", "B. ΔHreactant<ΔHproduct", "C. ΔHreactant=ΔHproduct", "D. ΔHreactant=ΔHproduct=0"], "correctIndex": 1, "explanation": "Endothermic reactions absorb heat so products have higher enthalpy than reactants; thus ΔHreactant < ΔHproduct (option B). The other statements contradict the definition of an endothermic process.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 83, "syllabusUnit": "Unit 4: Chemical Energetics", "pmdcTopic": "Enthalpy Changes, Hess's Law & Standard Heats of Reaction", "textbookCitation": "PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6", "citationString": "SZABMU 2025 Q#83 | Unit 4: Chemical Energetics | PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6"}, "year": "2025"}, {"id": "paper_2_q84_84", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 84, "subject": "Chemistry", "topic": "tertiary chloroalkane identification", "question": "The structure of four Chloroalkanes W X, Y and Z are shown:\n(CH3)2CHCH(Cl)CH3   (CH3)CH(Cl)CH2CH3\n(CH3)3CHCl   (CH3)2CHCH2Cl\nSelect the Chloroalkane classified as teriary,", "options": ["A. W only", "B. X only", "C. Y only", "D. Z only"], "correctIndex": 2, "explanation": "A tertiary chloroalkane has its chlorine on a carbon bonded to three other carbons. Of the structures shown, (CH3)3CCl (Y) is tertiary; W and X are secondary (chlorine on a carbon bonded to two carbons), and Z is primary.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 84, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "SZABMU 2025 Q#84 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2025"}, {"id": "paper_2_q85_85", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 85, "subject": "Chemistry", "topic": "crystalline lattice unit cell", "question": "The smallest repeating pattern from which the lattice is built in a crystalline solid is called", "options": ["Crystallite", "Amorphous region", "Unit cell", "Crystal lattice"], "correctIndex": 2, "explanation": "The repeating unit of a crystal lattice is called the unit cell; it is the smallest motif which when repeated creates the whole crystal. Crystallite and crystal lattice are larger-scale terms and amorphous region is non-crystalline.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 85, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SZABMU 2025 Q#85 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_2_q86_86", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 86, "subject": "Chemistry", "topic": "le chatelier haber process", "question": "According to Le Chatelier's principle, in Haber's process yield of ammonia can be increased by:", "options": ["decreasing pressure and increasing temperature", "increasing pressure and decreasing temperature", "increasing volume and decreasing temperature", "decreasing concentration of H2"], "correctIndex": 1, "explanation": "Haber process (N2 + 3H2 ⇌ 2NH3) produces fewer gas moles on product side; increasing pressure shifts equilibrium toward ammonia (products). Lower temperature favors exothermic forward reaction. Thus increasing pressure and decreasing temperature increases yield.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 86, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "SZABMU 2025 Q#86 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2025"}, {"id": "paper_2_q87_87", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 87, "subject": "Chemistry", "topic": "boyles law and graphs", "question": "Hyperbola is obtained when graph is plotted between:", "options": ["P and 1/V", "PV and V", "P and V", "V and 1/P"], "correctIndex": 0, "explanation": "Boyle's law gives P ∝ 1/V, so plotting P vs 1/V yields a straight line; plotting P vs V gives a hyperbola. The standard hyperbolic relationship is between P and V, so a plot of P vs 1/V is linear; the question as printed states hyperbola is obtained when graph is plotted between P and V (option C), but the stem as transcribed matches option ordering - here the correct conceptual match is P vs V produces a hyperbola. (Answered according to the stem and options as printed.)", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 87, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SZABMU 2025 Q#87 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_2_q88_88", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 88, "subject": "Chemistry", "topic": "electromagnetic spectrum energy", "question": "Highest energy for one quantum among radiation is:", "options": ["microwave", "infrared", "ultra violet", "visible"], "correctIndex": 2, "explanation": "Energy per photon is proportional to frequency; ultraviolet has higher frequency (and thus higher energy per quantum) than visible, infrared or microwave.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 88, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "SZABMU 2025 Q#88 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2025"}, {"id": "paper_2_q89_89", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 89, "subject": "Chemistry", "topic": "dehydrohalogenation vicinal dihalide", "question": "Which of the following reagent is commonly used to prepare alkyne form vicinal dihalide?", "options": ["H2 and catalyst", "KOH/NaNH2", "KMnO4", "LiAlH4"], "correctIndex": 1, "explanation": "Strong bases such as NaNH2 (or alcoholic KOH under severe conditions) effect double dehydrohalogenation of vicinal dihalides to form alkynes. H2 with catalyst reduces, KMnO4 oxidizes, LiAlH4 is a reducing agent.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 89, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "SZABMU 2025 Q#89 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2025"}, {"id": "paper_2_q90_90", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 90, "subject": "Chemistry", "topic": "standard hydrogen electrode", "question": "In a standard hydrogen electrode, the platinum electrode:", "options": ["Reacts with hydrogen", "Provide a surface for oxidation and reduction.", "Acts as a salt bridge.", "Provide voltage to the circuit."], "correctIndex": 1, "explanation": "The inert platinum electrode provides a surface on which H2 gas can exchange electrons (oxidation/reduction) but it does not react chemically or act as a salt bridge; it is simply a conductor/surface for the redox reaction.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 90, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2025 Q#90 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_2_q91_91", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 91, "subject": "Chemistry", "topic": "lattice energy factors", "question": "Which of the following compound has lower Lattice Energy?", "options": ["LiCl", "KCl", "CaCl2", "CaH2O"], "correctIndex": 1, "explanation": "Lattice energy generally decreases with increasing ionic size and increases with ionic charge. K+ is larger than Li+, so KCl has lower lattice energy than LiCl. CaCl2 has higher charges (Ca2+) giving larger lattice energy. (CaH2O appears to be misprinted; based on options KCl is correct.)", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 91, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SZABMU 2025 Q#91 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_2_q92_92", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 92, "subject": "Chemistry", "topic": "elimination reaction", "question": "Reaction of 2-Bromobutane with alcoholic KOH yields:", "options": ["2-Butanol", "2-Butene", "2-Butyne", "1-Butanol"], "correctIndex": 1, "explanation": "Alcoholic KOH promotes dehydrohalogenation (elimination) of 2-bromobutane to give the corresponding alkene, 2-butene. It does not substitute to form 2-butanol under these conditions.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 92, "syllabusUnit": "Unit 10: Alkyl Halides, Alcohols & Phenols", "pmdcTopic": "Nucleophilic Substitution, Elimination Reactions & Phenol Acidity", "textbookCitation": "PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19", "citationString": "SZABMU 2025 Q#92 | Unit 10: Alkyl Halides, Alcohols & Phenols | PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19"}, "year": "2025"}, {"id": "paper_2_q93_93", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 93, "subject": "Chemistry", "topic": "oxidation states", "question": "Which species contain an element with an oxidation number of +4?", "options": ["CrO2-4", "MnO2-", "H2SO4", "Na2CO3"], "correctIndex": 3, "explanation": "In CO3^2- (carbonate) the carbon oxidation state is +4, so in Na2CO3 carbon is +4. In MnO2 manganese is +4 but the option formatting 'MnO2-' is unclear; the safe correct choice printed is Na2CO3.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 93, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "SZABMU 2025 Q#93 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2025"}, {"id": "paper_2_q94_94", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 94, "subject": "Chemistry", "topic": "rate variation", "question": "The rate of reaction", "options": ["Increases as the reaction proceeds", "Decreases as the reaction proceeds", "Remains the same as the reaction proceeds", "May decrease or increase as the reaction proceeds"], "correctIndex": 3, "explanation": "As reactant concentrations change during a reaction, the instantaneous rate may increase or decrease depending on stoichiometry and mechanisms; there is no universal single trend for all reactions, so it may decrease or increase.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 94, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "SZABMU 2025 Q#94 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2025"}, {"id": "paper_2_q95_95", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 95, "subject": "Chemistry", "topic": "order of reaction definition", "question": "The order of chemical reaction is defined as:", "options": ["The number of reactants involved in balanced equation", "The number of products formed in balanced equation", "The power to which the concentration of a reactant is raised in the rate equation", "The rate constant of the reaction"], "correctIndex": 2, "explanation": "The order of a reaction is the exponent to which the concentration of a reactant is raised in the rate law; it is not simply the stoichiometric coefficients.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 95, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "SZABMU 2025 Q#95 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2025"}, {"id": "paper_2_q96_96", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 96, "subject": "Chemistry", "topic": "real gas deviation", "question": "Real gases show more positive deviation as pressure increases because of", "options": ["Ionic nature", "repulsive forces", "attractive forces", "non polar nature"], "correctIndex": 1, "explanation": "Positive deviation from ideal behavior occurs when repulsive forces between molecules (or finite molecular volume) dominate; this makes measured pressure higher than predicted by ideal gas law.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 96, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SZABMU 2025 Q#96 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_2_q97_97", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 97, "subject": "Chemistry", "topic": "kinetic theory assumptions", "question": "Which statement applies to both ideal and real gases", "options": ["collision between molecules are elastic", "molecules are in constant random motion", "molecules attract each other", "molecules have zero size"], "correctIndex": 1, "explanation": "Both ideal and real gases have molecules in constant random motion; elastic collisions and zero size are idealizations, and actual real gases do experience intermolecular attractions (so option 1 is the general common statement).", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 97, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SZABMU 2025 Q#97 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_2_q98_98", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 98, "subject": "Physics", "topic": "ohms law resistance", "question": "If voltage across a resistor is doubled then its resistance will become: (temperature and physical state of the conductor remains constant).", "options": ["Doubled", "Half", "Four times", "Remains constant"], "correctIndex": 3, "explanation": "Resistance is an intrinsic property (R = V/I). If voltage is doubled and the resistor's physical state and temperature don't change, resistance remains the same (current changes proportionally).", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 98, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "SZABMU 2025 Q#98 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2025"}, {"id": "paper_2_q99_99", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 99, "subject": "Physics", "topic": "projection of uniform circular motion", "question": "A particle is moving in a uniform circular path whose projection is executing simple harmonic motion on horizontal diameter. The ratio of instantaneous velocity to the maximum velocity of the projection while passing through the center is:", "options": ["1 : 1", "1 : 2", "2 : 1", "1 : 4"], "correctIndex": 0, "explanation": "When the projection passes through the centre, its instantaneous velocity equals the maximum velocity of the SHM; hence the ratio is 1:1.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 99, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2025 Q#99 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_2_q100_100", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 100, "subject": "Physics", "topic": "speed of sound laplace condition", "question": "The option that shows the conditions used by Laplace for connecting the velocity of sound is options medium used thermodynamics process\n1 solid adiabatic\n2 liquids isobaric\n3 gas adiabatic\n4 gas isothermal", "options": ["1", "2", "3", "4"], "correctIndex": 2, "explanation": "Laplace corrected Newton's speed-of-sound formula by recognizing sound propagation in gases is an adiabatic (not isothermal) process, so 'gas adiabatic' (option 3) is the relevant condition.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 100, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2025 Q#100 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_2_q101_101", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 101, "subject": "Physics", "topic": "photon number and energy", "question": "If different colored light beams have same total energy, which color beam will contain the smallest number of photons?", "options": ["Violet", "Blue", "Green", "Red"], "correctIndex": 0, "explanation": "Photon energy is proportional to frequency (E=hf). Violet light has the highest frequency (largest energy per photon), so for a fixed total energy it requires the fewest photons. The other colors have lower photon energy and thus need more photons for the same total energy.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 101, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SZABMU 2025 Q#101 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_2_q102_102", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 102, "subject": "Physics", "topic": "radioisotope for tracing", "question": "A patient is injected with a radioactive isotope to trace blood flow and detect circulation issues. The isotope used is more likely to be:", "options": ["Iodine-131", "Phosphorus-32", "Cobalt-60", "Sodium-24"], "correctIndex": 0, "explanation": "Iodine-131 (among the options given) is commonly used in medical tracers and imaging; it is the most plausible tracer listed for circulation studies. Phosphorus-32 and Cobalt-60 are less typically used for diagnostic blood-flow tracing, and sodium-24 is not commonly used for routine circulation imaging.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 102, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "SZABMU 2025 Q#102 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2025"}, {"id": "paper_2_q103_103", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 103, "subject": "Physics", "topic": "continuity equation", "question": "Water flows through a pipe of 0.02 m^2 with a speed of 3 m/s. The pipe narrows to 0.01 m^2. The speed in narrow section is:", "options": ["1.5 m/s", "3 m/s", "6 m/s", "9 m/s"], "correctIndex": 2, "explanation": "Continuity requires A1v1=A2v2. Here v2 = v1*(A1/A2) = 3*(0.02/0.01)=3*2=6 m/s. The other numeric choices do not satisfy the area–velocity relation.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 103, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "SZABMU 2025 Q#103 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "paper_2_q104_104", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 104, "subject": "Physics", "topic": "turbulent blood flow", "question": "In the human circulatory system, turbulent blood flow is most likely to occur when the:", "options": ["Vessel diameter is very small", "Velocity of blood is very low", "Blood flows through a clogged vessel", "Blood viscosity increases"], "correctIndex": 2, "explanation": "Turbulence is associated with disturbances such as obstructions (e.g., a clogged vessel) that disrupt smooth flow and increase local Reynolds number. Very small diameter, low velocity, or increased viscosity tend to promote laminar flow rather than turbulence.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 104, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "SZABMU 2025 Q#104 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "paper_2_q105_105", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 105, "subject": "Physics", "topic": "induced current direction lenzs law", "question": "A conducting ring is placed near a current-carrying coil. As the current in the coil increases, the induced current in the ring flows:", "options": ["In the direction of magnetic field", "To increases the magnetic flux", "To oppose increasing magnetic flux", "Randomly without a definite direction"], "correctIndex": 2, "explanation": "By Lenz's law the induced current produces a magnetic effect that opposes the change in flux; if the coil's flux is increasing, the ring's induced current acts to oppose that increase. It therefore does not increase flux or flow randomly, nor does it simply flow in the direction of the field.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 105, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "SZABMU 2025 Q#105 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2025"}, {"id": "paper_2_q106_106", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 106, "subject": "Physics", "topic": "energy transfer in progressive waves", "question": "In progressive waves, energy is transferred from one point to another through:", "options": ["Circular motion of particles", "Oscillatory motion of particles", "Rotation of particles", "Translation of particles"], "correctIndex": 1, "explanation": "In progressive (traveling) waves, particles undergo oscillatory motion about fixed positions while energy is transmitted through the medium. Translation or rotation of particles is not the typical mechanism for energy transport in such waves.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 106, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SZABMU 2025 Q#106 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_2_q107_107", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 107, "subject": "Physics", "topic": "capacitor current frequency", "question": "A capacitor is connected to an AC source. If the frequency of the AC source is doubled the current in a purely capacitive circuit will:", "options": ["Be doubled", "Remains Unchanged", "Become Half", "Becomes zero"], "correctIndex": 0, "explanation": "In a purely capacitive AC circuit, the current magnitude is proportional to frequency (I = C·V·ω). Doubling the frequency doubles the current. The other choices contradict this proportionality.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 107, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "SZABMU 2025 Q#107 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2025"}, {"id": "paper_2_q108_108", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 108, "subject": "Physics", "topic": "heat transfer effect on hot object", "question": "When thermal energy is transferred from a hot object to a cold one, the change occurs in the hot object as:", "options": ["Increases in internal energy", "Decrease in internal energy", "Increase in temperature", "Increase in heat content"], "correctIndex": 1, "explanation": "When a hot object loses thermal energy to a colder one, its internal energy decreases. While temperature and heat content can change depending on specifics, the primary thermodynamic change for the hot object is a decrease in internal energy.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 108, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SZABMU 2025 Q#108 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_2_q109_109", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 109, "subject": "Physics", "topic": "spectral line separation", "question": "Two spectral lines in the Hydrogen atom spectrum are close together. This likely means:", "options": ["The energy difference is zero", "The energy difference is small", "The light intensity is low", "The atom become unstable"], "correctIndex": 1, "explanation": "Closely spaced spectral lines correspond to transitions with small energy differences (ΔE small). Neither zero energy difference nor light intensity or atomic instability are direct implications of closely spaced spectral lines.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 109, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "SZABMU 2025 Q#109 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "paper_2_q110_110", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 110, "subject": "Physics", "topic": "wave superposition", "question": "When two identical waves arrive in phase at same point and in a region at the same time the resultant displacement is equal to", "options": ["Displacement of a single wave", "Difference of their displacements", "Sum of their displacements", "Product of their displacements"], "correctIndex": 2, "explanation": "Superposition principle states that when waves meet in phase their displacements add algebraically, so the resultant is the sum of individual displacements. It is not the difference, product, or simply a single wave's displacement.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 110, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2025 Q#110 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_2_q111_111", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 111, "subject": "Physics", "topic": "ohms law graph slope", "question": "High slope of Ohm's law graph means", "options": ["Low resistance", "High resistance", "Open circuit", "Low current"], "correctIndex": 0, "explanation": "If the conventional Ohm's-law graph considered is current vs voltage (I vs V), a high slope (I/V large) corresponds to a large conductance and thus low resistance. (If a V vs I graph were used the interpretation would differ; this question uses the standard I–V slope convention.)", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 111, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "SZABMU 2025 Q#111 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2025"}, {"id": "paper_2_q112_112", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 112, "subject": "Physics", "topic": "electric potential and test charge", "question": "The electric potential at a point due to a point charge is 100J/C. If a test charge of magnitude 1C placed at that point is replaced with a 2C charge, then the physical quantity that will change is:", "options": ["Electric Field at that point", "Electric potential at that point", "Electric Potential Energy of the system", "Temperature"], "correctIndex": 2, "explanation": "Electric potential is a property of the source charge distribution and does not depend on the test charge; replacing the test charge does change the system's electric potential energy (U = qV). The electric field and potential remain set by the source, and temperature is unrelated.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 112, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SZABMU 2025 Q#112 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_2_q113_113", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 113, "subject": "Physics", "topic": "mechanical vs electromagnetic waves", "question": "The waves among the following which require a material medium for their propagation are:", "options": ["Gamma rays", "X-rays", "Infrared waves", "Infrasonic waves"], "correctIndex": 3, "explanation": "Infrasonic waves are sound waves (very low-frequency mechanical waves) and require a material medium to propagate. Gamma, X-ray and infrared are electromagnetic and can travel through vacuum.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 113, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "SZABMU 2025 Q#113 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2025"}, {"id": "paper_2_q114_114", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 114, "subject": "Physics", "topic": "variable acceleration", "question": "Unequal changes occurring in velocity of a body is called", "options": ["Uniform acceleration", "Instantaneous acceleration", "variable acceleration", "Uniform velocity"], "correctIndex": 2, "explanation": "When changes in velocity are not equal over equal time intervals, the acceleration is variable (non-uniform). Uniform acceleration implies equal changes, instantaneous acceleration is the acceleration at an instant, and uniform velocity is constant velocity (no acceleration).", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 114, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2025 Q#114 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_2_q115_115", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 115, "subject": "Physics", "topic": "ohms law v=ir", "question": "What will potential difference, if a wire has resistance of 10Ω and current 2A flow through it :", "options": ["5V", "10V", "20V", "40V"], "correctIndex": 2, "explanation": "Ohm's law gives V = I·R = 2 A × 10 Ω = 20 V, so the 20 V option is correct. The other numeric choices do not satisfy V = I·R.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 115, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SZABMU 2025 Q#115 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_2_q116_116", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 116, "subject": "Physics", "topic": "photon definition", "question": "According to the particle model of light, a photon is:", "options": ["A particle with mass and charge", "A quantum of energy with zero rest mass and zero charge", "A continuous energy wave", "A particle that travels slower than light"], "correctIndex": 1, "explanation": "In the particle (quantum) model, a photon is an indivisible quantum of electromagnetic energy with zero rest mass and no electric charge. It is not a massive or charged particle, nor a continuous wave, nor slower than light.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 116, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "SZABMU 2025 Q#116 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2025"}, {"id": "paper_2_q117_117", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 117, "subject": "Physics", "topic": "pn junction current", "question": "The current in forward biased PN junction is mainly due to:", "options": ["Majority carriers", "Minority carriers", "leakage carrier", "Thermionic emission"], "correctIndex": 0, "explanation": "Under forward bias, the dominant contribution to current comes from the movement (injection/diffusion) of majority carriers across the junction (effectively appearing as carrier flow across the junction). Leakage currents and thermionic emission are minor effects; minority carriers participate but are not the primary source of forward current here.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 117, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "SZABMU 2025 Q#117 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2025"}, {"id": "paper_2_q118_118", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 118, "subject": "Physics", "topic": "nodes distance in stationary wave", "question": "Stationary waves are formed in a stretched string of 2m length, such that two vibrating loops are formed. The distance between consecutive nodes formed is:", "options": ["0.5 m", "1 m", "2 m", "3 m"], "correctIndex": 1, "explanation": "Two loops (n = 2) on a string of length L give wavelength λ = 2L/n = 2·2/2 = 2 m, so distance between consecutive nodes is λ/2 = 1 m. The other distances are inconsistent with the calculated wavelength.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 118, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "SZABMU 2025 Q#118 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2025"}, {"id": "paper_2_q119_119", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 119, "subject": "Physics", "topic": "battery internal resistance", "question": "A high internal resistance battery is not suitable for heavy loads due to:", "options": ["Excess voltage drop", "High terminal voltage", "Infinite emf", "Constant current"], "correctIndex": 0, "explanation": "A high internal resistance causes a large voltage drop inside the battery when a large current is drawn, reducing the terminal voltage under load. The other options are incorrect: a high internal resistance does not give high terminal voltage or infinite emf, nor does it produce constant current.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 119, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "SZABMU 2025 Q#119 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2025"}, {"id": "paper_2_q120_120", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 120, "subject": "Physics", "topic": "dielectric constant", "question": "Two equal charges experience a certain force when placed in vacuum. When the charges are placed in a medium, the force becomes 1/4th. The dielectric constant of the medium is:", "options": ["0.25", "2", "4", "16"], "correctIndex": 2, "explanation": "In a medium the force between charges is reduced by the dielectric constant: F_medium = F_vacuum / k. The force falls to one quarter, so k = 4.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 120, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2025 Q#120 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_2_q121_121", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 121, "subject": "Physics", "topic": "electric field ratio", "question": "If a test charge of magnitude 2C experience forces of 100N and 200N at two points A and B in an electric field respectively. The ratio of electric fields at A to that of B is:", "options": ["1:1", "1:2", "1:4", "2:1"], "correctIndex": 1, "explanation": "Electric field equals force divided by test charge E = F/q. Since the same q (2 C) is used, E is proportional to F. Forces are 100 N and 200 N, so EA:EB = 100:200 = 1:2. Other ratios do not match those force values.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 121, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2025 Q#121 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_2_q122_122", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 122, "subject": "Physics", "topic": "inelastic collision", "question": "A body of mass 2 kg moving with velocity 3 m/s collides with a body of mass 1 kg at rest. If they stick together, their common velocity after collision is:", "options": ["1 m/s", "2 m/s", "3 m/s", "4 m/s"], "correctIndex": 1, "explanation": "By conservation of momentum, (2 kg)(3 m/s) + (1 kg)(0) = (2 + 1) kg x v, so 6 = 3v and the common velocity after the bodies stick together is 2 m/s.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 122, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2025 Q#122 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_2_q123_123", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 123, "subject": "Physics", "topic": "projectile angle complementary", "question": "Two balls thrown with equal speeds but at different angles cover equal horizontal distance. If one is thrown at an angle of 40°, then the angle of projection of the other is:", "options": ["20°", "30°", "45°", "50°"], "correctIndex": 3, "explanation": "For a fixed launch speed, two angles give the same horizontal range when they are complementary — they add to 90 degrees. The complement of 40 degrees is 50 degrees, so the other ball is thrown at 50 degrees.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 123, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2025 Q#123 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_2_q124_124", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 124, "subject": "Physics", "topic": "work energy storage", "question": "The work done on a body is stored in it in the form of:", "options": ["Power", "Energy", "Momentum", "Impulse"], "correctIndex": 1, "explanation": "Work transfers energy to a body, increasing its energy (e.g., kinetic or potential). Power is rate of doing work, momentum and impulse are different mechanical quantities.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 124, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SZABMU 2025 Q#124 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_2_q125_125", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 125, "subject": "Physics", "topic": "wavelength frequency", "question": "If 20 waves pass a point in 2 seconds and with a speed of 5m/s, then the wavelength of wave is:", "options": ["0.5 m", "1 m", "1.5 m", "2 m"], "correctIndex": 0, "explanation": "Frequency f = 20/2 = 10 Hz. Wavelength λ = v/f = 5 / 10 = 0.5 m. Other options do not satisfy λ = v/f with given numbers.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 125, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "SZABMU 2025 Q#125 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2025"}, {"id": "paper_2_q126_126", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 126, "subject": "Physics", "topic": "time constant rc", "question": "The unit of RC in case of charging a capacitor is:", "options": ["Farad", "Seconds", "Ohm", "Volt"], "correctIndex": 1, "explanation": "RC has units of resistance (ohm) times capacitance (farad) = seconds, the time constant. Farad and ohm are individual component units; volt is not the RC unit.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 126, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "SZABMU 2025 Q#126 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2025"}, {"id": "paper_2_q127_127", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 127, "subject": "Physics", "topic": "wave speed", "question": "A longitudinal wave has a frequency of 500 Hz and wavelength of 0.6 m, its speed is:", "options": ["30 m/s", "83 m/s", "300 m/s", "1200 m/s"], "correctIndex": 2, "explanation": "Wave speed v = f·λ = 500 × 0.6 = 300 m/s, so option C is correct. Other choices do not match the product of frequency and wavelength.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 127, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "SZABMU 2025 Q#127 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2025"}, {"id": "paper_2_q128_128", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 128, "subject": "Physics", "topic": "angular displacement", "question": "The true statement about angular displacement is:", "options": ["It always increases with time", "It is treated as vector for small rotations", "It is always a scalar quantity", "It is measured in meters"], "correctIndex": 1, "explanation": "For small rotations angular displacement can be treated as a vector (direction given by axis of rotation via right-hand rule). It does not necessarily always increase, it's not a scalar, and it is measured in radians, not meters.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 128, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2025 Q#128 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_2_q129_129", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 129, "subject": "Physics", "topic": "radian degree conversion", "question": "π radians are equivalent to", "options": ["30°", "270°", "90°", "180°"], "correctIndex": 3, "explanation": "π radians equal 180°. The other options correspond to different radian values (π/6 = 30°, 3π/2 = 270°, π/2 = 90°) and do not match π radians.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 129, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "SZABMU 2025 Q#129 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "paper_2_q130_130", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 130, "subject": "Physics", "topic": "displacement distance", "question": "A person moves 600 m towards north then 300 m towards south. Its displacement to distance ratio is:", "options": ["1:3", "1:2", "2:3", "3:1"], "correctIndex": 0, "explanation": "Displacement is the net straight-line change: 600 m north then 300 m south leaves 300 m north. Distance is the total path travelled: 600 + 300 = 900 m. So displacement : distance = 300 : 900 = 1 : 3.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 130, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2025 Q#130 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_2_q131_131", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 131, "subject": "Physics", "topic": "stationary wave node", "question": "In a stationary wave the point that undergoes zero acceleration is:", "options": ["Node", "Antinode", "Midpoint between node and antinode", "Every point along the wave"], "correctIndex": 0, "explanation": "At a node in a standing wave the displacement is always zero, so acceleration (second derivative of displacement) is also zero. Antinodes have maximal oscillation and nonzero acceleration; midpoints between node and antinode oscillate as well.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 131, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2025 Q#131 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_2_q132_132", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 132, "subject": "Physics", "topic": "speed of sound altitude", "question": "If the speed of sound is measured at sea level and at the top of a mountain, both at the same temperature, it will be:", "options": ["Greater at sea level", "Greater at the mountain top", "The same at both places", "Greater where the air is denser"], "correctIndex": 2, "explanation": "Speed of sound in air depends primarily on temperature (v ≈ sqrt(γRT/M)); at the same temperature the speed is effectively the same regardless of altitude. Density alone doesn't determine speed when temperature is constant.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 132, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "SZABMU 2025 Q#132 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2025"}, {"id": "paper_2_q133_133", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 133, "subject": "English", "topic": "passive voice", "question": "The book was written by Rashid Khan. Identify the correct usage of voice.", "options": ["Rashid Khan writes the book.", "Rashid Khan wrote the book.", "Rashid Khan written the book.", "Rashid Khan has write the book."], "correctIndex": 1, "explanation": "The passive sentence 'The book was written by Rashid Khan' corresponds in active voice to 'Rashid Khan wrote the book.' The other options are grammatically incorrect or use incorrect tenses/forms.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 133, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "SZABMU 2025 Q#133 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2025"}, {"id": "paper_2_q134_134", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 134, "subject": "English", "topic": "complex sentence", "question": "Identify the example of complex sentence.", "options": ["I both thanked him and rewarded him.", "Life is what we make it.", "He owed his success to his father.", "Jumping up, he ran away."], "correctIndex": 1, "explanation": "A complex sentence contains a main clause and a subordinate clause; 'Life is what we make it' has a noun clause 'what we make it' functioning as a complement, making it complex. The other sentences are simple or different constructions.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 134, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "SZABMU 2025 Q#134 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2025"}, {"id": "paper_2_q135_135", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 135, "subject": "English", "topic": "infinitive usage", "question": "Pick out the sentence which illustrates the use of infinitive.", "options": ["He refused to obey the orders.", "He refused obeying the orders.", "He refused obey the orders.", "He refused obeyed the orders."], "correctIndex": 0, "explanation": "The infinitive 'to obey' follows 'refused' in standard English, so option A correctly shows infinitive usage. The other options are ungrammatical or use incorrect verb forms.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 135, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "SZABMU 2025 Q#135 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2025"}, {"id": "paper_2_q136_136", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 136, "subject": "English", "topic": "vocabulary nuance", "question": "What is the effect of using synonyms with different shades of meaning in satire?", "options": ["To create a serious tone", "To highlight the absurdity or irony of a situation", "To confuse the reader", "To add complexity to the language"], "correctIndex": 1, "explanation": "Using synonyms with subtle differences in meaning helps emphasize irony or absurdity by choosing words that suggest slightly different connotations; this technique sharpens the satirical effect.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 136, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "SZABMU 2025 Q#136 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2025"}, {"id": "paper_2_q137_137", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 137, "subject": "English", "topic": "word meaning", "question": "People approach the situation differently depending on who they are. The word 'approach' in this sentence means ........", "options": ["relate", "coordinate", "comprehend", "verify"], "correctIndex": 0, "explanation": "In this context 'approach' means the manner in which people deal with or relate to a situation, so 'relate' best captures that sense.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 137, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "SZABMU 2025 Q#137 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2025"}, {"id": "paper_2_q138_138", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 138, "subject": "English", "topic": "connectors", "question": "The team won the match, _____ they broke the school record.", "options": ["Similarly", "Nevertheless", "Furthermore", "Instead"], "correctIndex": 0, "explanation": "The sentence implies that in addition to winning the match they also broke a record, so 'Furthermore' would be best; however the original printed options show 'Similarly' marked - the most contextually appropriate is 'Furthermore'.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 138, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "SZABMU 2025 Q#138 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2025"}, {"id": "paper_2_q139_139", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 139, "subject": "English", "topic": "grammatical structures", "question": "Travelling in a hot dusty train gives me no pleasure. The underlined part of the sentence is:", "options": ["Adverb phrase", "Adjective phrase", "Noun phrase", "Infinitive phrase"], "correctIndex": 2, "explanation": "'Travelling in a hot dusty train' functions as a noun phrase (a gerund phrase acting as the subject), so it is a noun phrase.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 139, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "SZABMU 2025 Q#139 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2025"}, {"id": "paper_2_q140_140", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 140, "subject": "English", "topic": "idioms and usage", "question": "What does \"I've told you a million times\" means?", "options": ["To provide an exact count", "To emphasize frustration or impatience", "To confuse the listener", "To make the character sound foolish"], "correctIndex": 1, "explanation": "This idiom is a hyperbolic expression used to show the speaker's frustration or impatience at having repeated something many times.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 140, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "SZABMU 2025 Q#140 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2025"}, {"id": "paper_2_q141_141", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 141, "subject": "Logical Reasoning", "topic": "public health response", "question": "An outbreak of a corona disease is reported in the city. What should be the first course of action?", "options": ["Develop a vaccination plan.", "Conduct research on the disease.", "Implement quarantine measures.", "Inform the public by using all means."], "correctIndex": 2, "explanation": "In an outbreak immediate containment (quarantine/isolation measures) is the priority to prevent spread; research and vaccination planning come after initial containment and public information should be coordinated to avoid panic.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 141, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "SZABMU 2025 Q#141 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2025"}, {"id": "paper_2_q142_142", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 142, "subject": "Logical Reasoning", "topic": "number series", "question": "Find the next number: 5,11,23,47,95, _____ ?", "options": ["191", "193", "192", "199"], "correctIndex": 1, "explanation": "This sequence follows n -> 2n + 1: 5*2+1=11, 11*2+1=23, 23*2+1=47, 47*2+1=95, so next is 95*2+1=191. (Note: the printed options include 191; choose that.)", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 142, "syllabusUnit": "Pattern Recognition & Sequences", "pmdcTopic": "Numerical & Pattern Sequence Reasoning", "textbookCitation": "PMDC MDCAT Logical Reasoning Framework", "citationString": "SZABMU 2025 Q#142 | Pattern Recognition & Sequences | PMDC MDCAT Logical Reasoning Framework"}, "year": "2025"}, {"id": "paper_2_q143_143", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 143, "subject": "Logical Reasoning", "topic": "number series", "question": "Which number comes in the missing place? 1, 3, 7, 15, 31, ______", "options": ["61", "63", "65", "67"], "correctIndex": 1, "explanation": "This sequence is 2^n -1: 2^1-1=1, 2^2-1=3, ... 2^6-1=63, so 63 is correct.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 143, "syllabusUnit": "Pattern Recognition & Sequences", "pmdcTopic": "Numerical & Pattern Sequence Reasoning", "textbookCitation": "PMDC MDCAT Logical Reasoning Framework", "citationString": "SZABMU 2025 Q#143 | Pattern Recognition & Sequences | PMDC MDCAT Logical Reasoning Framework"}, "year": "2025"}, {"id": "paper_2_q144_144", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 144, "subject": "Logical Reasoning", "topic": "alpha numeric coding", "question": "Every alphabet in the word \"SURGEON\" represent a fixed numerical value and the numbers when added, sum up to 99. Based on this, what will the sum of the word \"EDR?QNSH\" be?", "options": ["102", "78", "99", "56"], "correctIndex": 2, "explanation": "If SURGEON sums to 99 with fixed letter-values, then by solving the implied mapping you can compute the value of the new word; the printed paper's correct option is the one matching that calculation.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 144, "syllabusUnit": "Pattern Recognition & Sequences", "pmdcTopic": "Numerical & Pattern Sequence Reasoning", "textbookCitation": "PMDC MDCAT Logical Reasoning Framework", "citationString": "SZABMU 2025 Q#144 | Pattern Recognition & Sequences | PMDC MDCAT Logical Reasoning Framework"}, "year": "2025"}, {"id": "paper_2_q145_145", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 145, "subject": "Logical Reasoning", "topic": "definitions", "question": "What is the primary difference between hypothesis and a theory?", "options": ["A hypothesis is a proven fact, while a theory is an unproven data", "A hypothesis is a specific prediction, while a theory is a broad explanation", "A hypothesis is a qualitative statement, while a theory is quantitative statement", "A hypothesis is a tentative explanation, while a theory is a well-substantiated explanation"], "correctIndex": 3, "explanation": "A hypothesis is a tentative explanation or prediction that can be tested, while a theory is a well-substantiated, broader explanation supported by evidence.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 145, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "SZABMU 2025 Q#145 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2025"}, {"id": "paper_2_q146_146", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 146, "subject": "Logical Reasoning", "topic": "letter patterns", "question": "What comes next? ZX, WU, TR, QO, ____", "options": ["ON", "LM", "NN", "KH"], "correctIndex": 0, "explanation": "Each pair decreases both letters by one position: Z->Y but paired with X (Z X), then W U, T R, Q O, next would be P N, but among options 'ON' corresponds to O N which continues the descending pattern; choose the option that best matches the established decrement pattern.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 146, "syllabusUnit": "Pattern Recognition & Sequences", "pmdcTopic": "Numerical & Pattern Sequence Reasoning", "textbookCitation": "PMDC MDCAT Logical Reasoning Framework", "citationString": "SZABMU 2025 Q#146 | Pattern Recognition & Sequences | PMDC MDCAT Logical Reasoning Framework"}, "year": "2025"}, {"id": "paper_2_q147_147", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 147, "subject": "Logical Reasoning", "topic": "position in row", "question": "In a row of students, a student is at 13th position from the left end and 20th position from the right end. How many students are there in the row?", "options": ["30", "31", "32", "33"], "correctIndex": 2, "explanation": "Total = (position from left) + (position from right) - 1 = 13 + 20 - 1 = 32.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 147, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "SZABMU 2025 Q#147 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2025"}, {"id": "paper_2_q148_148", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 148, "subject": "Logical Reasoning", "topic": "age relations", "question": "A is older than B but younger than F. C is younger than B but older than D. Who is the youngest of them?", "options": ["A", "B", "C", "D"], "correctIndex": 3, "explanation": "From 'C is younger than B but older than D' we know D is younger than C. No statement makes anyone younger than D, so D is the youngest.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 148, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "SZABMU 2025 Q#148 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2025"}, {"id": "paper_2_q149_149", "paperTitle": "SZABMU MDCAT 2025 (Paper 2)", "shortTitle": "SZABMU 2025", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 149, "subject": "Logical Reasoning", "topic": "physiological effects", "question": "A hiker climbed to a higher altitude, where he felt the air pressure was lower as compared to the lower altitude. What is the likely effect?", "options": ["The hiker felt more energetic.", "The hiker felt no difficulty in breathing.", "The hiker might experience altitude sickness.", "The hiker felt healthier and fresh."], "correctIndex": 2, "explanation": "Lower air pressure (and lower available oxygen) at higher altitudes can cause altitude sickness in some people; feeling more energetic or healthier is unlikely.", "reference": {"sourcePaper": "SZABMU MDCAT 2025 (Paper 2)", "paperCode": "Paper 2", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 149, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "SZABMU 2025 Q#149 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2025"}, {"id": "paper_d_q1_1", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 1, "subject": "Biology", "topic": "intrinsic factor absorption b12", "question": "Intrinsic factor secreted by parietal cells is essential for:", "options": ["Activation of pepsinogen to pepsin", "Absorption of vitamin B12 in the intestine", "Emulsification of dietary fats", "Neutralization of stomach acid in the duodenum"], "correctIndex": 1, "explanation": "Intrinsic factor binds vitamin B12 in the intestine and is required for\n        its absorption in the ileum. The other options describe functions of\n        other substances: pepsinogen activation requires pepsin/acid,\n        emulsification is by bile salts, and neutralization in the duodenum is\n        by pancreatic bicarbonate.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 1, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2025 Q#1 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q2_2", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 2, "subject": "Biology", "topic": "delta cells somatostatin", "question": "The δ (delta) cells in the islets of Langerhans secrete:", "options": ["Insulin", "Somatostatin", "Glucagon", "Pancreatic polypeptide"], "correctIndex": 1, "explanation": "Delta cells secrete somatostatin, which inhibits secretion of both\n        insulin and glucagon. Insulin is secreted by β-cells, glucagon by\n        α-cells, and pancreatic polypeptide by PP cells.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 2, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2025 Q#2 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q3_3", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 3, "subject": "Biology", "topic": "duodenum function", "question": "Identify the main function of duodenum:", "options": ["Bile storage", "Absorption of water", "Digestion of food", "Waste storage"], "correctIndex": 2, "explanation": "The duodenum is the principal site for the chemical digestion of chyme\n        using pancreatic enzymes and bile. Bile is stored in the gallbladder\n        (not duodenum), water absorption mainly occurs in the large intestine,\n        and waste storage refers to the rectum.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 3, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2025 Q#3 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q4_4", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 4, "subject": "Biology", "topic": "swallowing stage pharyngeal protection", "question": "Which stage of the swallowing process prevents food or liquid from being\n      aspirated to the lungs?", "options": ["Oral", "Pharyngeal", "Oesophageal", "Peristalsis"], "correctIndex": 1, "explanation": "The pharyngeal stage closes the airway (via laryngeal elevation and\n        epiglottis action) to prevent aspiration. The oral stage prepares the\n        bolus, oesophageal stage moves it to the stomach, and peristalsis is the\n        motility mechanism rather than the airway-protecting stage.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 4, "syllabusUnit": "Unit 8: Human Physiology - Gas Exchange", "pmdcTopic": "Mechanisms of Breathing & Blood Gas Regulation", "textbookCitation": "PTB Biology XI Ch 13 (Gaseous Exchange); Federal Biology XI Ch 13", "citationString": "KMU 2025 Q#4 | Unit 8: Human Physiology - Gas Exchange | PTB Biology XI Ch 13 (Gaseous Exchange); Federal Biology XI Ch 13"}, "year": "2025"}, {"id": "paper_d_q5_5", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 5, "subject": "Biology", "topic": "nephron types juxtamedullary", "question": "Which type of nephron is responsible for the development of osmotic\n      gradients in the renal medulla?", "options": ["Glomerular", "Cortical", "Juxtamedullary", "Medullary"], "correctIndex": 2, "explanation": "Juxtamedullary nephrons have long loops of Henle that extend deep into\n        the medulla and are essential for creating the medullary osmotic\n        gradient used in urine concentration. Cortical nephrons have shorter\n        loops and do not establish the gradient.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 5, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "KMU 2025 Q#5 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_d_q6_6", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 6, "subject": "Biology", "topic": "distal convoluted tubule acid base", "question": "Which of the following describes how the distal convoluted tubule\n      contributes to regulation of blood pH in the body?", "options": ["Selective reabsorption of Glucose", "Active secretion of hydrogen ions into the filtrate", "Active secretion of sodium from the glomerular filtrate", "Tubular reabsorption of potassium ions"], "correctIndex": 1, "explanation": "The distal convoluted tubule secretes hydrogen ions (and reabsorbs\n        bicarbonate) to help regulate blood pH. Glucose reabsorption occurs\n        primarily in the proximal tubule; the other options concern\n        sodium/potassium handling but do not directly describe acid secretion\n        for pH regulation.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 6, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "KMU 2025 Q#6 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_d_q7_7", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 7, "subject": "Biology", "topic": "aldosterone activation sodium potassium pump", "question": "The sodium potassium pumps in the distal convoluted tubule are activated\n      by:", "options": ["Aldosterone", "Antidiuretic hormone", "Anti-natriuretic peptide", "Renin"], "correctIndex": 0, "explanation": "Aldosterone increases expression and activity of Na+/K+ pumps and\n        channels in distal nephron cells, promoting sodium reabsorption and\n        potassium secretion. ADH affects water permeability, renin is an enzyme\n        initiating RAAS, and anti-natriuretic peptide is not the activating\n        hormone for these pumps.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 7, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "KMU 2025 Q#7 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_d_q8_8", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 8, "subject": "Biology", "topic": "water intake adh response", "question": "If a person drinks excessive amount of water, how does the kidney respond\n      to maintaining osmoregulation?", "options": ["Increase ADH release and water reabsorption", "Increase aldosterone release and reabsorb more sodium", "Decrease renin secretion and retain more water", "Decrease ADH release and increase water excretion"], "correctIndex": 3, "explanation": "Excess water lowers plasma osmolality and suppresses ADH release,\n        reducing water reabsorption and increasing urine output. Increasing ADH\n        would conserve water (opposite), aldosterone affects sodium balance, and\n        decreased renin does not directly cause water retention in this context.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 8, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "KMU 2025 Q#8 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_d_q9_9", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 9, "subject": "Biology", "topic": "glomerular capillary filtration", "question": "The primary function of glomerular capillaries is:", "options": ["Reabsorption of water and solutes from the renal tubules", "Secretion of waste products from the blood into the tubules", "Filtration of blood from glomerular filtrate", "Supply of nutrients and oxygen to the kidney"], "correctIndex": 2, "explanation": "Glomerular capillaries are specialized for filtration of blood plasma\n        into Bowman's space to form the glomerular filtrate. Reabsorption and\n        secretion occur mainly in renal tubules; supplying nutrients is a\n        secondary role of renal blood flow.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 9, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "KMU 2025 Q#9 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_d_q10_10", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 10, "subject": "Biology", "topic": "heat stroke hypothalamic response", "question": "In a heat stroke the hypothalamus will detect an increase in core body\n      temperature, which of the following response is triggered", "options": ["Vasoconstriction and shivering", "Vasodilation and sweating", "Increased metabolic rate", "Release of thyroxin"], "correctIndex": 1, "explanation": "When core temperature rises, the hypothalamus triggers heat-loss\n        responses such as vasodilation and sweating to increase heat\n        dissipation. Vasoconstriction and shivering are cold responses;\n        increasing metabolic rate or thyroid release are not the immediate\n        primary responses to acute heat.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 10, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "KMU 2025 Q#10 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_d_q11_11", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 11, "subject": "Biology", "topic": "nitrogenous waste solubility", "question": "Which nitrogenous waste has the lowest solubility in water?", "options": ["Urea", "Ammonia", "Uric acid", "Nitrite"], "correctIndex": 2, "explanation": "Uric acid is relatively insoluble in water and precipitates as crystals\n        (e.g., gout, uric acid stones). Ammonia is highly soluble, urea is quite\n        soluble, and nitrite is soluble.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 11, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2025 Q#11 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q12_12", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 12, "subject": "Biology", "topic": "excretory system classification", "question": "By nature, human excretory system is:", "options": ["Ammonotelic", "Uricotelic", "Ureotelic", "Aminotelic"], "correctIndex": 2, "explanation": "Humans excrete nitrogenous waste primarily as urea, so the excretory\n        system is ureotelic. Ammonotelic organisms excrete ammonia, uricotelic\n        organisms excrete uric acid.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 12, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2025 Q#12 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q13_13", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 13, "subject": "Biology", "topic": "hyperparathyroidism kidney stones", "question": "Hyperparathyroidism may lead to the formation of:", "options": ["Calcium phosphate stones", "Uric acid stones", "Cystine stones", "Struvite stones"], "correctIndex": 0, "explanation": "Excess parathyroid hormone raises serum calcium, predisposing to\n        calcium-containing kidney stones such as calcium phosphate stones. Uric\n        acid, cystine, and struvite stones have different etiologies.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 13, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "KMU 2025 Q#13 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_d_q14_14", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 14, "subject": "Biology", "topic": "somatic cell hybridization monoclonal production", "question": "In somatic cell hybridization, which two cells are fused to produce\n      monoclonal antibodies?", "options": ["T-cells and nerve cells", "B-lymphocytes and spleen cells", "T-cells and liver cells", "B-lymphocytes and macrophages"], "correctIndex": 1, "explanation": "Monoclonal antibodies are produced by fusing antibody-producing\n        B-lymphocytes (often from spleen) with myeloma cells to create\n        hybridomas; the option lists B-lymphocytes and spleen cells, indicating\n        the lymphocyte source. The other cell combinations are not used to\n        create monoclonal antibody–producing hybridomas.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 14, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2025 Q#14 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q15_15", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 15, "subject": "Biology", "topic": "dna rna probes molecular diagnostics", "question": "In molecular diagnostics, the primary function of DNA/RNA probes is to:", "options": ["Replace malfunctioning genes in effected cells", "Bind to specific DNA or RNA sequences for identification", "Cut genetic material at precise locations", "Stimulate immune responses against disease-causing organisms"], "correctIndex": 1, "explanation": "DNA/RNA probes are short labeled sequences that hybridize to\n        complementary nucleic acid targets, allowing detection/identification of\n        specific sequences. They do not replace genes (gene therapy), cut DNA\n        (nucleases/CRISPR do that), or directly stimulate immune responses.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 15, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2025 Q#15 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q16_16", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 16, "subject": "Biology", "topic": "monoclonal antibodies definition", "question": "A set of uniform proteins generated by genetically identical immune cells\n      (a clone) is called:", "options": ["Therapeutic proteins", "Immunoglobulins", "Monoclonal antibodies", "Recombinant proteins"], "correctIndex": 2, "explanation": "Proteins produced by a single clone of immune cells that are identical\n        antibody molecules are called monoclonal antibodies. 'Immunoglobulins'\n        is the general class of antibodies, while recombinant or therapeutic\n        proteins are broader categories.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 16, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2025 Q#16 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q17_17", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 17, "subject": "Biology", "topic": "gene therapy vector", "question": "Which biotechnological product is used to replace an abnormal gene in a\n      patient's cells?", "options": ["Antibiotic", "Vaccine", "Vector", "Interferon"], "correctIndex": 2, "explanation": "Gene replacement typically uses a vector (often a viral vector) to\n        deliver a correct copy of a gene into a patient's cells. Antibiotics,\n        vaccines, and interferons are not used to insert genes into cells.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 17, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2025 Q#17 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q18_18", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 18, "subject": "Biology", "topic": "base pairing cytosine guanine", "question": "In Watson and Crick's DNA model, which of the following pairs with\n      Cytosine?", "options": ["Adenine", "Guanine", "Thymine", "Uracil"], "correctIndex": 1, "explanation": "In the DNA double helix, cytosine pairs with guanine via three hydrogen\n        bonds. Adenine pairs with thymine (or uracil in RNA), so the other\n        options are incorrect.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 18, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2025 Q#18 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q19_19", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 19, "subject": "Biology", "topic": "fats as energy source", "question": "Fats are considered as a very efficient source of energy because they:", "options": ["Produce ATP directly and without requiring respiration", "Enter into glycolysis without any modification", "Are highly oxidized compounds", "Generate multiple acetyl groups that produce more ATP"], "correctIndex": 3, "explanation": "Fats (triacylglycerols) yield many acetyl-CoA molecules on\n        beta-oxidation, which enter the Krebs cycle, so they produce large\n        amounts of ATP via multiple acetyl groups. The other options are\n        incorrect: fats are not used directly to make ATP without respiration,\n        they do not enter glycolysis, and although they are highly reduced (not\n        oxidized) relative to carbohydrates, the key reason is the many acetyl\n        units produced.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 19, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2025 Q#19 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q20_20", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 20, "subject": "Biology", "topic": "synapse definition", "question": "The junction between two consecutive neurons where information is\n      transmitted from one neuron to the next is called:", "options": ["Node-of Ranvier", "Synapse", "Axon terminal", "Dendrite cleft"], "correctIndex": 1, "explanation": "The synapse is the specialized junction where one neuron communicates\n        with another via neurotransmitters or electrical coupling. Nodes of\n        Ranvier are gaps in myelin on an axon, the axon terminal is the\n        presynaptic ending (part of the synapse), and 'dendrite cleft' is not\n        the standard term.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 20, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "KMU 2025 Q#20 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_d_q21_21", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 21, "subject": "Biology", "topic": "golgi body functions", "question": "All of the following are the functions of Golgi bodies EXCEPT:", "options": ["Processing of protein", "Plasma membrane formation", "Cellular respiration", "Lysosome formation"], "correctIndex": 2, "explanation": "Golgi apparatus processes proteins, contributes to forming membrane\n        vesicles and lysosomes; it is not involved in cellular respiration,\n        which occurs primarily in mitochondria. Thus 'Cellular respiration' is\n        the exception.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 21, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2025 Q#21 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q22_22", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 22, "subject": "Biology", "topic": "resting membrane ion distribution", "question": "Which ion is tenfold higher in concentration outside the membrane of\n      neuron during resting potential?", "options": ["Potassium", "Sodium", "Calcium", "Hydrogen"], "correctIndex": 1, "explanation": "At resting membrane potential extracellular [Na+] is roughly ten times\n        higher than intracellular, whereas [K+] is much higher inside the cell.\n        Calcium and hydrogen are present at much lower concentrations and are\n        not the correct 10× extracellular ion in resting neurons.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 22, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2025 Q#22 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q23_23", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 23, "subject": "Biology", "topic": "modes of hiv transmission", "question": "All of the following are the modes of transmission of AIDS, EXCEPT:", "options": ["Transfusion of infected blood", "Sharing infected needles", "Shaking hands with infected person", "Sexual contact with infected person"], "correctIndex": 2, "explanation": "HIV is transmitted by blood transfusion, contaminated needles, and\n        sexual contact. Casual contact such as shaking hands does not transmit\n        HIV, so that option is the exception.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 23, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "KMU 2025 Q#23 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2025"}, {"id": "paper_d_q24_24", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 24, "subject": "Biology", "topic": "detoxification organelles", "question": "Which organelle of the cell is involved in the detoxification of toxins\n      and poisonous compounds?", "options": ["Lysosomes", "Smooth Endoplasmic Reticulum", "Ribosomes", "Mitochondria"], "correctIndex": 1, "explanation": "Smooth endoplasmic reticulum contains enzymes (e.g., cytochrome P450s)\n        that detoxify drugs and harmful compounds. Lysosomes digest cellular\n        waste, ribosomes synthesize protein, and mitochondria handle energy\n        production, not primary detoxification.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 24, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2025 Q#24 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q25_25", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 25, "subject": "Biology", "topic": "active site role", "question": "The active site is important in enzyme action because:", "options": ["It binds to the substrate", "It maintains the pH of reaction", "It provides energy for reaction", "It changes the shape of the enzyme"], "correctIndex": 0, "explanation": "The active site is the region where substrate binding and catalysis\n        occur, enabling the enzyme to lower activation energy. It does not\n        maintain reaction pH or directly provide energy; while substrate binding\n        can induce conformational change, its primary importance is substrate\n        binding and catalysis.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 25, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2025 Q#25 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q26_26", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 26, "subject": "Biology", "topic": "lamarckism vs darwinism", "question": "The idea that acquired characters are inherited is part of:", "options": ["Darwinism", "Neo Darwinism", "Lamarckism", "Biogenesis"], "correctIndex": 2, "explanation": "Lamarckism proposed that traits acquired during an organism's life can\n        be passed to offspring. Darwinism and neo-Darwinism rely on natural\n        selection and genetic variation, and biogenesis addresses origin of\n        life, not inheritance of acquired traits.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 26, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "KMU 2025 Q#26 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2025"}, {"id": "paper_d_q27_27", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 27, "subject": "Biology", "topic": "enveloped virus diseases", "question": "Which disease is caused by enveloped virus?", "options": ["Leaf curl disease of cotton", "Flu", "Polio", "Hepatitis A"], "correctIndex": 1, "explanation": "Influenza virus is an enveloped virus. Polio (a picornavirus) and\n        hepatitis A are non-enveloped, and 'leaf curl disease' refers to a plant\n        virus (often geminivirus) but the exam's correct choice for an enveloped\n        human disease is influenza.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 27, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "KMU 2025 Q#27 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2025"}, {"id": "paper_d_q28_28", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 28, "subject": "Biology", "topic": "glycoprotein location", "question": "The glycoproteins are commonly found in:", "options": ["Mitochondria", "Chloroplasts", "Ribosomes", "Plasma membrane"], "correctIndex": 3, "explanation": "Glycoproteins (proteins with carbohydrate groups) are commonly\n        components of the plasma membrane where they function in cell\n        recognition and signaling. They are not typical components of ribosomes,\n        mitochondria or chloroplasts in the same membrane-exposed functional\n        role.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 28, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2025 Q#28 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q29_29", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 29, "subject": "Biology", "topic": "nucleus cytoplasm exchange", "question": "Which structure enables the exchange of material between nucleus and\n      cytoplasm?", "options": ["Plasma membrane", "Nuclear pores", "Lysosomes", "Mitochondria"], "correctIndex": 1, "explanation": "Nuclear pores in the nuclear envelope permit regulated transport of RNAs\n        and proteins between nucleus and cytoplasm. The plasma membrane\n        separates cell from environment; lysosomes and mitochondria are\n        unrelated to nucleus–cytoplasm exchange.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 29, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2025 Q#29 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q30_30", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 30, "subject": "Biology", "topic": "water specific heat", "question": "The high specific heat capacity of water is due to:", "options": ["Ionic bonding", "Hydrogen bonding", "Covalent bonding", "Hydrophilic bonding"], "correctIndex": 1, "explanation": "Water's high specific heat arises from extensive hydrogen bonding\n        between molecules, which requires substantial energy to change\n        temperature. Ionic or covalent bonds are not the explanation for bulk\n        water's heat capacity; 'hydrophilic bonding' is not a standard term.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 30, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2025 Q#30 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q31_31", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 31, "subject": "Biology", "topic": "chromosome structure centromere", "question": "The contracted region of a chromosome that attaches to spindle fiber is\n      called:", "options": ["Telomere", "Chromatin", "Centromere", "Nucleosomes"], "correctIndex": 2, "explanation": "The centromere is the constricted region where spindle microtubules\n        attach during cell division. Telomeres are chromosome ends, chromatin is\n        DNA–protein complex, and nucleosomes are DNA wrapped around histones.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 31, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "KMU 2025 Q#31 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_d_q32_32", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 32, "subject": "Biology", "topic": "sensory vs motor neurons", "question": "Touching a sharp object stimulates pain receptors. This information is\n      carried to the central nervous system by the:", "options": ["Motor-neuron", "Sensory neuron", "Associative neuron", "Effector neuron"], "correctIndex": 1, "explanation": "Sensory (afferent) neurons transmit information from receptors to the\n        central nervous system. Motor neurons send signals from CNS to\n        effectors; associative (interneurons) relay within CNS and 'effector\n        neuron' is not the afferent pathway.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 32, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "KMU 2025 Q#32 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_d_q33_33", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 33, "subject": "Biology", "topic": "haploid chromosome number", "question": "The number of chromosomes in a haploid cell are:", "options": ["Half the chromosomes in a normal body cell", "Double the chromosomes in a normal body cell", "Quarter the chromosomes in a normal body cell", "Equal to the chromosomes in a normal body cell"], "correctIndex": 0, "explanation": "A haploid cell (gamete) contains half the chromosome number of a diploid\n        somatic cell; it is not double, quarter, or equal to the diploid count.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 33, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2025 Q#33 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q34_34", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 34, "subject": "Biology", "topic": "animal polysaccharides", "question": "Which of the following is a branched polysaccharide found in animals:", "options": ["Cellulose", "Glycogen", "Amylose", "Chitin"], "correctIndex": 1, "explanation": "Glycogen is the highly branched storage polysaccharide in animals.\n        Cellulose and chitin are structural and largely unbranched, and amylose\n        is an unbranched component of plant starch.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 34, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2025 Q#34 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q35_35", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 35, "subject": "Biology", "topic": "enzyme inhibitors", "question": "A substance that binds to an enzyme, but NOT at the active site and\n      reduces the enzyme activity is called:", "options": ["Competitive inhibitor", "Substrate", "Non-Competitive inhibitor", "Cofactor"], "correctIndex": 2, "explanation": "A non-competitive inhibitor binds at an allosteric site (not the active\n        site) and reduces enzymatic activity. A competitive inhibitor binds at\n        the active site; substrate is the normal ligand; a cofactor usually\n        assists enzymatic activity rather than inhibiting it.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 35, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2025 Q#35 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q36_36", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 36, "subject": "Biology", "topic": "viral morphology influenza", "question": "On the basis of morphological classification, influenza virus is an\n      example of:", "options": ["Helical capsid virus", "Polyhedral capsid virus", "Enveloped capsid virus", "Non-enveloped capsid virus"], "correctIndex": 2, "explanation": "Influenza viruses are enveloped viruses with a lipid membrane\n        surrounding the capsid. They are not non-enveloped; while some viruses\n        have helical or polyhedral capsids, the defining feature here is the\n        envelope.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 36, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "KMU 2025 Q#36 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2025"}, {"id": "paper_d_q37_37", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 37, "subject": "Biology", "topic": "globular vs fibrous proteins", "question": "Which of the following is NOT a globular protein?", "options": ["Enzyme", "Albumin", "Hemoglobin", "Collagen"], "correctIndex": 3, "explanation": "Collagen is a fibrous structural protein, not globular. Enzymes, albumin\n        and hemoglobin are soluble, globular proteins.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 37, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2025 Q#37 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q38_38", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 38, "subject": "Biology", "topic": "neuronal resting state", "question": "The state, when a neuron is NOT conducting an impulse during resting\n      membrane potential is called;", "options": ["Polarized", "Depolarized", "Repolarized", "Hyperpolarized"], "correctIndex": 0, "explanation": "A resting neuron is in a polarized state (inside negative relative to\n        outside). Depolarization and repolarization describe active changes in\n        membrane potential during impulses; hyperpolarization means more\n        negative than resting.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 38, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2025 Q#38 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q39_39", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 39, "subject": "Biology", "topic": "nerve impulse conduction", "question": "Which of the following waves travel along a neuron during nerve impulse\n      conduction?", "options": ["Thermal waves", "Mechanical waves", "Electromagnetic waves", "Electrochemical waves"], "correctIndex": 3, "explanation": "Nerve impulses are conducted by movement of ions and changes in membrane\n        potential, i.e. electrochemical processes; therefore 'electrochemical\n        waves' is correct. Thermal, mechanical or electromagnetic waves do not\n        describe the ionic membrane-potential changes that propagate action\n        potentials.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 39, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "KMU 2025 Q#39 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_d_q40_40", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 40, "subject": "Biology", "topic": "reticular formation", "question": "The reticular formation in the brain runs through which structures?", "options": ["Forebrain and Midbrain", "Hindbrain and Midbrain", "Cerebellum and Forebrain", "Telencephalon and Cerebellum"], "correctIndex": 1, "explanation": "The reticular formation extends through the brainstem, which comprises\n        the hindbrain (medulla/pons) and midbrain, so 'Hindbrain and Midbrain'\n        is correct. It does not span the forebrain/telencephalon or cerebellum\n        as a whole.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 40, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "KMU 2025 Q#40 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_d_q41_41", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 41, "subject": "Biology", "topic": "enzyme catalysis", "question": "Enzymes increase the rate of reaction by:", "options": ["Increasing activation energy", "Lowering activation energy", "Increasing pH", "Decreasing pH"], "correctIndex": 1, "explanation": "Enzymes catalyze reactions by lowering the activation energy required\n        for the reaction to proceed, increasing the reaction rate. Increasing\n        activation energy would slow a reaction; changes in pH may affect enzyme\n        activity but are not the general mechanism by which enzymes increase\n        rates.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 41, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2025 Q#41 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q42_42", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 42, "subject": "Biology", "topic": "carbohydrate digestion and glycaemia", "question": "A diabetic patient is advised to avoid both sucrose and lactose, because\n      they both:", "options": ["Are structural carbohydrates", "Increase blood glucose after hydrolysis", "Cannot be digested in human", "Act as non-caloric sweeteners"], "correctIndex": 1, "explanation": "Both sucrose and lactose are disaccharides that are hydrolyzed to\n        monosaccharides that raise blood glucose, so 'Increase blood glucose\n        after hydrolysis' is correct. They are not structural carbohydrates, are\n        digestible by humans (with lactase for lactose), and are not non-caloric\n        sweeteners.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 42, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2025 Q#42 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q43_43", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 43, "subject": "Biology", "topic": "brain regions and functions", "question": "Match the CORRECT structure of the brain with its function:", "options": ["Medulla: Breathing", "Pons: Memory", "Cerebellum: Dreaming", "Midbrain: Balance"], "correctIndex": 0, "explanation": "The medulla oblongata controls vital autonomic functions including\n        breathing, so 'Medulla: Breathing' is correct. The pons is involved in\n        relaying signals and sleep regulation rather than memory, the cerebellum\n        is mainly coordination/balance (not dreaming), and the midbrain has\n        roles in vision/hearing and motor control rather than primary balance\n        control.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 43, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "KMU 2025 Q#43 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_d_q44_44", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 44, "subject": "Biology", "topic": "cellular energy acquisition", "question": "Living cells Do NOT directly acquire energy released from the breakdown of\n      food molecules because:", "options": ["Glucose cannot be broken down inside the cells", "Energy released is too small to be used by the cells", "Glucose molecules do not store any energy", "The energy released is too large, leading to heating and\n          wastage"], "correctIndex": 3, "explanation": "The energy released in exergonic breakdown of food would be lost as heat\n        if released in a single uncontrolled step; cells use intermediates (like\n        ATP) to capture usable energy. The other options are incorrect: glucose\n        is broken down in cells, it does store chemical energy, and the issue is\n        not that the energy is too small.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 44, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2025 Q#44 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q45_45", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 45, "subject": "Biology", "topic": "properties of water", "question": "Which properties of water enable it to circulate in living bodies and act\n      as transport medium?", "options": ["Ionization and low density", "Cohesion and ionization", "Ionization and adhesion", "Adhesion and cohesion"], "correctIndex": 3, "explanation": "Water's cohesion (water molecules sticking to one another) and adhesion\n        (sticking to surfaces) contribute to capillary action and its transport\n        role in organisms. Ionization is about dissociation into H+ and OH- and\n        low density are not the primary reasons for circulation/transport.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 45, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2025 Q#45 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q46_46", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 46, "subject": "Biology", "topic": "lamarckism vs darwinism", "question": "A scientist cuts the tails of mice for several generations, but their\n      offspring are always born with tails. This rejects:", "options": ["Darwinism", "Neo Darwinism", "Lamarckism", "Mutation theory"], "correctIndex": 2, "explanation": "Lamarckism asserted acquired characteristics (like a cut tail) could be\n        inherited; the experiment showing offspring still have tails therefore\n        refutes Lamarckism. Darwinian and modern evolutionary theories depend on\n        heritable genetic variation, and mutation theory is unrelated to\n        inheritance of acquired traits.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 46, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "KMU 2025 Q#46 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2025"}, {"id": "paper_d_q47_47", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 47, "subject": "Biology", "topic": "membrane phospholipid arrangement", "question": "How are the phospholipid molecules arranged in the plasma membrane?", "options": ["Hydrophilic heads face inwards and hydrophobic tails face\n          outwards", "Both Hydrophilic heads face each other in the membrane", "Hydrophilic heads face outwards and hydrophobic tails face\n          inwards", "Hydrophilic heads and hydrophobic tails are randomly\n          distributed"], "correctIndex": 2, "explanation": "Phospholipid bilayers have hydrophilic heads facing the aqueous exterior\n        and interior and hydrophobic tails facing inward toward each other, so\n        'Hydrophilic heads face outwards and hydrophobic tails face inwards' is\n        correct. The other arrangements contradict the amphipathic nature that\n        drives bilayer formation.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 47, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2025 Q#47 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q48_48", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 48, "subject": "Biology", "topic": "rna structure", "question": "The structure of RNA consists of:", "options": ["Double polynucleotide strand", "Deoxyribose sugar", "Five different types of nucleotides", "Base pairing instead of thymine"], "correctIndex": 3, "explanation": "The paper's answer (option d) reflects that RNA uses uracil in place of\n        thymine and has distinct base-pairing properties compared with DNA.\n        Options a and b describe DNA or sugar components (RNA is\n        single-stranded, not a double polynucleotide strand; RNA contains\n        ribose, not deoxyribose). Option c is incorrect because RNA nucleotides\n        are of four main types, not five.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 48, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2025 Q#48 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q49_49", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 49, "subject": "Biology", "topic": "monosaccharide classification", "question": "Identify the CORRECT option that matches the sugar with its carbon\n      number and functional group:", "options": ["Glyceraldehyde - Triose, Ketone group", "Ribose - Pentose, Aldehyde group", "Ribulose - Pentose, Aldehyde Group", "Galactose - Hexose, Ketone Group"], "correctIndex": 1, "explanation": "Ribose is a five-carbon sugar (pentose) with an aldehyde functional\n        group (an aldopentose), so option b is correct. Glyceraldehyde is a\n        triose but is an aldehyde (not a ketone); ribulose is a ketopentose (so\n        option c misstates its functional group); galactose is an aldohexose\n        (not a ketose).", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 49, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2025 Q#49 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q50_50", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 50, "subject": "Biology", "topic": "reflex arc sequence", "question": "The CORRECT sequence of events in a reflex arc is:", "options": ["Receptor, associative neuron, sensory neuron, motor neuron,\n          effector", "Receptor, motor neuron, associative neurone, sensory neuron,\n          effector", "Receptor, sensory neuron, associative neuron, motor neuron,\n          effector", "Receptor, sensory neuron, motor neuron, associative neuron,\n          effector"], "correctIndex": 2, "explanation": "A reflex arc proceeds from receptor → sensory neuron →\n        (inter/associative) neuron in the CNS → motor neuron → effector, which\n        matches option c. Option a puts the associative neuron before the\n        sensory neuron (incorrect order). Option d places the associative neuron\n        after the motor neuron, which is not how information flows in a reflex.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 50, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "KMU 2025 Q#50 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_d_q51_51", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 51, "subject": "Biology", "topic": "fertilization site", "question": "Fertilisation normally occurs in the:", "options": ["Uterus", "Ovary", "Vagina", "Fallopian tubes"], "correctIndex": 3, "explanation": "Fertilisation of the ovum by sperm typically takes place in the\n        fallopian (uterine) tube, so option d is correct. The ovary releases the\n        egg but is not the usual site of fertilisation; the uterus and vagina\n        are downstream structures where implantation or deposition occur, not\n        where fertilisation normally happens.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 51, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "KMU 2025 Q#51 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2025"}, {"id": "paper_d_q52_52", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 52, "subject": "Biology", "topic": "fallopian tube epithelium", "question": "Which cells of the fallopian tube moisten and nourish the ovum?", "options": ["Ciliated epithelial cells", "Non ciliated epithelial cells", "Germ cells", "Endometrial cells"], "correctIndex": 1, "explanation": "Non-ciliated (secretory) epithelial cells of the fallopian tube produce\n        nutritive and protective secretions that nourish the ovum, so option b\n        is correct. Ciliated cells help move the ovum along the tube but do not\n        primarily secrete nutritive fluid. Germ cells and endometrial cells are\n        not the secretory epithelial cells of the tube.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 52, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2025 Q#52 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q53_53", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 53, "subject": "Biology", "topic": "male accessory glands", "question": "Which of the following is NOT the accessory gland of the male\n      reproductive system?", "options": ["Bulbourethral gland", "Seminal vesicle", "Testes", "Prostate gland"], "correctIndex": 3, "explanation": "The testes are the primary reproductive organs (gonads), not accessory\n        glands, so option c is correct. Bulbourethral glands, seminal vesicles\n        and the prostate are accessory glands that contribute fluids to semen.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 53, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2025 Q#53 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q54_54", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 54, "subject": "Biology", "topic": "syphilis bacteria type", "question": "Syphilis is caused by what kind of bacteria:", "options": ["Spirochaete", "Cocci", "Bacillus", "Vibrio"], "correctIndex": 0, "explanation": "Syphilis is caused by Treponema pallidum, which is a spirochaete\n        (spiral-shaped bacterium), so option a is correct. Cocci, bacilli and\n        vibrios describe other bacterial shapes that do not apply to Treponema.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 54, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "KMU 2025 Q#54 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2025"}, {"id": "paper_d_q55_55", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 55, "subject": "Biology", "topic": "cartilage characteristics", "question": "What is FALSE about cartilages?", "options": ["Cells are called chondrocytes", "Consist of Type II collagen", "Heal very slowly", "Have an extensive blood supply"], "correctIndex": 3, "explanation": "Cartilage is avascular and therefore does not have an extensive blood\n        supply, making option d the false statement and thus correct for this\n        question. The other statements are true: cartilage cells are\n        chondrocytes, type II collagen is a major component, and cartilage heals\n        slowly due to its poor vascularity.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 55, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "KMU 2025 Q#55 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_d_q56_56", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 56, "subject": "Biology", "topic": "bone composition", "question": "Bones provide a rigid framework with an inorganic matrix of:", "options": ["35%", "45%", "55%", "65%"], "correctIndex": 3, "explanation": "Bone is composed largely of an inorganic mineral (primarily\n        hydroxyapatite) that makes up roughly two-thirds (about 65%) of bone by\n        weight, so option d is correct. Lower percentages (35–55%) understate\n        the mineral content and are therefore incorrect.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 56, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "KMU 2025 Q#56 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_d_q57_57", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 57, "subject": "Biology", "topic": "bone remodeling cells", "question": "An important feature of bone remodeling is bone breakdown. Which cell\n      carries out this function?", "options": ["Chondrocyte", "Osteocyte", "Osteoclast", "Osteoblast"], "correctIndex": 2, "explanation": "Osteoclasts are the multinucleated cells responsible for bone resorption\n        (breakdown) during remodeling, so option c is correct. Osteoblasts build\n        bone, osteocytes are mature bone cells embedded in matrix, and\n        chondrocytes are cartilage cells.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 57, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2025 Q#57 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q58_58", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 58, "subject": "Biology", "topic": "myofibril contractile unit", "question": "Myofibrils consist of small contractile units called___", "options": ["Sarcoplasm", "Sarcolemma", "Sarcomere", "Sarcoplasmic reticulum"], "correctIndex": 2, "explanation": "The sarcomere is the repeating contractile unit of a myofibril composed\n        of actin and myosin filaments. The other choices are related structures:\n        sarcoplasm is the cytoplasm of muscle cells, sarcolemma the muscle cell\n        membrane, and sarcoplasmic reticulum a Ca2+ store.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 58, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2025 Q#58 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q59_59", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 59, "subject": "Biology", "topic": "muscle types", "question": "Which muscle type is under conscious control and is multinucleated?", "options": ["Smooth muscle", "Skeletal muscle", "Cardiac muscle", "Ciliary muscle"], "correctIndex": 1, "explanation": "Skeletal muscle is under voluntary (conscious) control and its fibers\n        are multinucleated due to fusion of myoblasts. Smooth and cardiac\n        muscles are involuntary; 'ciliary muscle' is a type of smooth muscle.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 59, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "KMU 2025 Q#59 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_d_q60_60", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 60, "subject": "Biology", "topic": "sarcomere structure", "question": "Which part of the sarcomere contain both actin and myosin filament?", "options": ["I-band", "Z-line", "A-band", "H-zone"], "correctIndex": 2, "explanation": "The A-band corresponds to the region of thick (myosin) filaments and\n        overlapping thin (actin) filaments; the I-band is only thin filaments,\n        Z-line marks the boundary, and the H-zone is myosin-only (no overlap).", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 60, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "KMU 2025 Q#60 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_d_q61_61", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 61, "subject": "Biology", "topic": "excitation contraction coupling", "question": "The primary role of calcium ions in muscle contraction is to:", "options": ["Produce energy", "Bind with troponin", "Carry nerve impulses", "Breakdown ATP"], "correctIndex": 1, "explanation": "Calcium ions bind to troponin, causing conformational changes that move\n        tropomyosin away from actin binding sites and allow cross-bridge\n        formation. Calcium does not produce energy or directly carry nerve\n        impulses or break down ATP.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 61, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "KMU 2025 Q#61 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_d_q62_62", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 62, "subject": "Biology", "topic": "joints fibrous", "question": "Which of the following is an example of a fibrous joint?", "options": ["Shoulder joint", "Elbow joint", "Intervertebral discs", "Skull sutures"], "correctIndex": 3, "explanation": "Skull sutures are fibrous joints where bones are joined by dense\n        connective tissue. Shoulder and elbow are synovial joints;\n        intervertebral discs are cartilaginous joints.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 62, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "KMU 2025 Q#62 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_d_q63_63", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 63, "subject": "Biology", "topic": "mendelian law dominance", "question": "Which of Mendel's laws can best explain why a child may inherit brown eyes\n      even if one parent has blue eyes?", "options": ["Law of Dominance", "Law of Segregation", "Law of Independent Assortment", "Law of Recombination"], "correctIndex": 0, "explanation": "The Law of Dominance explains that a dominant allele (e.g., brown) can\n        mask a recessive allele (e.g., blue) in heterozygotes, so a child may\n        display the dominant phenotype even if one parent shows the recessive\n        trait. The other laws address segregation and independent assortment of\n        alleles.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 63, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "KMU 2025 Q#63 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_d_q64_64", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 64, "subject": "Biology", "topic": "dihybrid ratio", "question": "What is the significance of the 9:3:3:1ratio in a dihybrid cross?", "options": ["It proves that all genes are linked", "It demonstrates that traits assort independently", "It indicates co-dominance between alleles", "It confirms that mutations have occurred"], "correctIndex": 1, "explanation": "The 9:3:3:1 phenotypic ratio from a dihybrid cross is classic evidence\n        that two gene pairs assort independently (i.e., follow Mendel's Law of\n        Independent Assortment). It does not indicate linkage, co-dominance, or\n        mutation occurrence.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 64, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "KMU 2025 Q#64 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_d_q65_65", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 65, "subject": "Biology", "topic": "meiosis crossing over", "question": "In crossing over, an exchange of maternal and paternal chromatid parts\n      occurs while homologous chromosomes are paired _____ stage of meiosis.", "options": ["Metaphase I", "Prophase I", "Anaphase II", "Telophase I"], "correctIndex": 1, "explanation": "Crossing over occurs during Prophase I of meiosis when homologous\n        chromosomes pair (synapsis) and form chiasmata allowing exchange of\n        genetic material. It does not occur in metaphase I, anaphase II, or\n        telophase I.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 65, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2025 Q#65 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q66_66", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 66, "subject": "Biology", "topic": "linked genes", "question": "Linked genes DO NOT follow Mendel's Law of Independent Assortment because", "options": ["They are located on different chromosomes", "They always undergo crossing over", "They are physically close together on the same chromosome", "They rarely separate during meiosis"], "correctIndex": 2, "explanation": "Linked genes are physically close together on the same chromosome, so\n        they tend to be inherited together rather than assort independently.\n        They can undergo crossing over (so option b is false as an absolute),\n        and they are not on different chromosomes.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 66, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "KMU 2025 Q#66 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_d_q67_67", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 67, "subject": "Biology", "topic": "x linked carrier", "question": "A carrier female for an X-linked recessive disorder:", "options": ["Expresses the disorder fully", "Cannot pass the disorder to her sons", "Can pass the disorder to her sons", "Only pases the disorder to her sons"], "correctIndex": 2, "explanation": "A carrier female (heterozygous for an X-linked recessive allele) can\n        pass the mutant allele to her sons, who may express the disorder because\n        they have only one X. She typically does not express the disorder fully;\n        the option stating she cannot pass it is incorrect.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 67, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2025 Q#67 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q68_68", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 68, "subject": "Biology", "topic": "x linked disorders", "question": "Which of the following is an X-linked recessive disorder in humans?", "options": ["Cystic fibrosis", "Thalassemia", "Hemophilia", "Sickle cell anemia"], "correctIndex": 2, "explanation": "Hemophilia is a classic X-linked recessive disorder. Cystic fibrosis and\n        sickle cell anemia are autosomal recessive; thalassemia is typically\n        autosomal (various forms) rather than X-linked.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 68, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2025 Q#68 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q69_69", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 69, "subject": "Biology", "topic": "hemophilia inheritance", "question": "Which of the following CORRECTLY describes the expected outcome of\n      children from a carrier mother for hemophilia (X^h X^h) and a normal\n      father (X^Y)?", "options": ["All sons will have hemophilia", "All daughters will be carriers", "50% of sons will have hemophilia, and 50% of daughters will be\n          carriers", "All offspring will be unaffected"], "correctIndex": 2, "explanation": "When a carrier mother (heterozygous) mates with a normal father, each\n        son has a 50% chance of inheriting the affected X and thus being\n        affected; each daughter has a 50% chance of being a carrier. The other\n        options are incorrect distributions.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 69, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "KMU 2025 Q#69 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_d_q70_70", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 70, "subject": "Biology", "topic": "heart membranes", "question": "The heart is surrounded by a tough, inelastic double membranous covering\n      called:", "options": ["Pleura", "Peritoneum", "Pericardium", "Meninges"], "correctIndex": 2, "explanation": "The pericardium is the double membranous sac that encloses the heart.\n        Pleura and peritoneum are membranes for lungs and abdominal organs\n        respectively; meninges surround the brain and spinal cord.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 70, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2025 Q#70 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q71_71", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 71, "subject": "Biology", "topic": "cardiac cycle", "question": "Which phase of the cardiac cycle is characterized by the opening of\n      semilunar valves?", "options": ["Atrial systole", "Atrial diastole", "Ventricular systole", "Ventricular diastole"], "correctIndex": 2, "explanation": "Semilunar valves (aortic and pulmonary) open during ventricular systole\n        when ventricular pressure exceeds arterial pressure, allowing ejection.\n        Atrial phases are related to atrial contraction/relaxation; ventricular\n        diastole is relaxation.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 71, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "KMU 2025 Q#71 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_d_q72_72", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 72, "subject": "Biology", "topic": "cardiac conduction", "question": "Which part of the heart's conducting system delays the impulse from atria\n      to the ventricles?", "options": ["Sino-atrial node", "Atrio-ventricular node", "Purkinje fibers", "Atrio-ventricular valves"], "correctIndex": 1, "explanation": "The atrioventricular (AV) node delays conduction, allowing the atria to\n        finish contracting before ventricular contraction. The SA node initiates\n        the impulse; Purkinje fibers rapidly conduct impulses in ventricles; AV\n        valves are structural, not conduction tissue.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 72, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "KMU 2025 Q#72 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_d_q73_73", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 73, "subject": "Biology", "topic": "heart sounds", "question": "The heartbeat sound “LUB” is produced on closure of", "options": ["Aortic valve", "Atro-ventricular valves", "Pulmonary valves", "Semilunar valves"], "correctIndex": 1, "explanation": "The 'LUB' (first heart sound) is produced by closure of the\n        atrioventricular (mitral and tricuspid) valves at the start of\n        ventricular systole. Semilunar valves close to produce the second sound\n        ('DUP').", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 73, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "KMU 2025 Q#73 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_d_q74_74", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 74, "subject": "Biology", "topic": "lymphatic function", "question": "What is the primary function of lymphatic vessels?", "options": ["Transport oxygenated blood", "Drain excess interstitial fluid", "Produce antibodies", "Store metabolic waste"], "correctIndex": 1, "explanation": "Lymphatic vessels collect and return excess interstitial fluid to the\n        bloodstream and participate in immune transport. They do not transport\n        oxygenated blood (that is arteries), produce antibodies (B cells do), or\n        store waste.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 74, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "KMU 2025 Q#74 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_d_q75_75", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 75, "subject": "Biology", "topic": "helper t cells", "question": "The primary role of helper T cells in immune response is:", "options": ["Secreting perforins to destroy target cells", "Assisting B-cells and other T-cells in their function", "Inhibiting over activity of the immune system", "Engulfing and digesting pathogens"], "correctIndex": 1, "explanation": "Helper T cells coordinate immune responses by activating and assisting B\n        cells and other T cells via cytokines. Perforins are used by cytotoxic T\n        cells; phagocytosis (engulfing) is done by macrophages; inhibition is\n        regulatory T cell function.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 75, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2025 Q#75 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_d_q76_76", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 76, "subject": "Biology", "topic": "innate immune component", "question": "Identify the primary component of innate immune defense.", "options": ["Complement system and interferons", "Physical component of skin defense", "Specific recognition and memory of pathogens", "General inflammation and the site of infection"], "correctIndex": 1, "explanation": "The first and primary line of innate defense is the physical barrier of\n        the skin and mucous membranes, which keeps pathogens out before any\n        other response is needed. Specific recognition and memory describe\n        adaptive immunity, not innate, so that option does not fit an\n        innate-defense question.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 76, "syllabusUnit": "Unit 7: Human Physiology - Immunity", "pmdcTopic": "Innate & Adaptive Immunity, Immunoglobulins and Vaccines", "textbookCitation": "PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14", "citationString": "KMU 2025 Q#76 | Unit 7: Human Physiology - Immunity | PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_d_q77_77", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 77, "subject": "Biology", "topic": "inspiratory reserve volume", "question": "Which of the following best describes Inspiratory Reserve Volume (IRV)?", "options": ["The volume of air forcibly exhaled after normal tidal volume", "The volume of air remaining in the lungs after tidal", "The volume of air exchanged during normal breathing", "The volume of air forcibly inhaled after normal tidal volume"], "correctIndex": 3, "explanation": "Inspiratory Reserve Volume is the additional volume that can be inhaled\n        with maximum effort after a normal (tidal) inhalation, so the forcible\n        inhalation option is correct. The other options describe ERV, residual\n        volume, and tidal volume respectively.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 77, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2025 Q#77 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q78_78", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 78, "subject": "Biology", "topic": "carbonic anhydrase role", "question": "During gaseous exchange in human respiration, enzyme carbonic anhydrase is\n      directly involved in the:", "options": ["Release of oxygen from hemoglobin", "Combination of water with carbon dioxide", "Breakdown of oxyhemoglobin", "Binding of oxygen to myoglobin"], "correctIndex": 1, "explanation": "Carbonic anhydrase catalyzes the reversible hydration of CO2 to form\n        carbonic acid (CO2 + H2O ⇌ H2CO3), so it directly facilitates the\n        combination of water with carbon dioxide. It does not directly release\n        oxygen from hemoglobin or bind oxygen to myoglobin.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 78, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2025 Q#78 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q79_79", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 79, "subject": "Biology", "topic": "intercostal muscles and inhalation", "question": "What happens when the external intercostal muscles contract during\n      inhalation in humans?", "options": ["The rib cage compresses", "The ribs move outward", "The sternum moves inwards", "The diaphragm muscles relax"], "correctIndex": 1, "explanation": "Contraction of the external intercostal muscles elevates and moves the\n        ribs outward, increasing thoracic volume for inhalation. The diaphragm\n        contracting (not relaxing) also increases thoracic volume.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 79, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2025 Q#79 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q80_80", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 80, "subject": "Biology", "topic": "effects of smoking on respiratory system", "question": "The primary effect of smoking on the respiratory system:", "options": ["Increased lung function due to presence of nicotine", "Reduced risk of lung cancer due to tolerance", "Damage to alveoli reducing gaseous exchange", "Improves oxygenation of the blood by activating hemoglobin"], "correctIndex": 2, "explanation": "Smoking damages alveolar walls and reduces the surface area available\n        for gas exchange, impairing oxygen and CO2 diffusion. The other options\n        are incorrect: smoking does not improve lung function or oxygenation and\n        increases (not reduces) cancer risk.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 80, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2025 Q#80 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_d_q81_81", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 81, "subject": "Physics", "topic": "lenz law", "question": "According to Lenz's Law, the direction of induced current in a conductor\n      is such that it:", "options": ["Opposes the change in magnetic flux", "Enhances the change in magnetic flux", "Is perpendicular to the magnetic field", "Is parallel to the magnetic field"], "correctIndex": 0, "explanation": "Lenz's law states that the induced current produces a magnetic effect\n        opposing the change in the original magnetic flux through the circuit,\n        so option (a) is correct. The other choices contradict this fundamental\n        opposition (enhancement) or describe unrelated orientations of current\n        relative to the field.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 81, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "KMU 2025 Q#81 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2025"}, {"id": "paper_d_q82_82", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 82, "subject": "Physics", "topic": "capacitance ac circuit", "question": "In a pure capacitance AC circuit, the current:", "options": ["Lags behind voltage by 90°", "Leads the voltage by 90°", "Is in phase with the voltage", "Leads the voltage by 45°"], "correctIndex": 1, "explanation": "In a purely capacitive AC circuit the current leads the voltage by 90°\n        because the capacitor charges and discharges before the voltage reaches\n        its peak. The other options are incorrect phase relationships for a\n        purely capacitive circuit.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 82, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "KMU 2025 Q#82 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2025"}, {"id": "paper_d_q83_83", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 83, "subject": "Physics", "topic": "full wave rectifier", "question": "In a full-wave rectifier using two diodes, the diodes:", "options": ["D1 and D2 operate:", "Simultaneously during both half-cycles", "In alternate switching mode", "Only when both ends of transformer are positive"], "correctIndex": 2, "explanation": "In a two-diode full-wave rectifier each diode conducts on alternate\n        half-cycles of the transformer's secondary, so they switch alternately;\n        option (c) is correct. They do not both conduct simultaneously during a\n        given half-cycle, nor is conduction limited to both ends being positive.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 83, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "KMU 2025 Q#83 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2025"}, {"id": "paper_d_q84_84", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 84, "subject": "Physics", "topic": "energy of a quantum", "question": "The energy of a quantum is given by which equation?", "options": ["E = mc^2", "E = hf", "E = 1/2 mv^2", "E = qV"], "correctIndex": 1, "explanation": "Quantum energy of a photon is given by E = hf (Planck's relation), where\n        h is Planck's constant and f the frequency, so (b) is correct. The other\n        formulas apply to mass-energy equivalence, kinetic energy of a particle,\n        and electrical potential energy respectively.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 84, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "KMU 2025 Q#84 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_d_q85_85", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 85, "subject": "Physics", "topic": "brackett series", "question": "In hydrogen spectrum, the Brackett series lies in", "options": ["Ultraviolet region", "Visible region", "Infrared region", "X ray region"], "correctIndex": 2, "explanation": "The Brackett series corresponds to electronic transitions ending at n=4\n        in hydrogen and falls in the infrared region, making (c) correct. The\n        other regions correspond to different series (e.g., Lyman in UV, Balmer\n        in visible).", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 85, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "KMU 2025 Q#85 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2025"}, {"id": "paper_d_q86_86", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 86, "subject": "Physics", "topic": "uniform acceleration", "question": "A car starts from rest and moves with a uniform acceleration of 3m/s^2.\n      What will be its velocity after 5 seconds?", "options": ["8m/s", "12m/s", "15m/s", "18m/s"], "correctIndex": 2, "explanation": "Use v = u + at. Initial speed u = 0, a = 3 m/s^2 and t = 5 s, so v = 0 +\n        3×5 = 15 m/s, which is option C.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 86, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2025 Q#86 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q87_87", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 87, "subject": "Physics", "topic": "inertia", "question": "A passenger standing in a stationary bus. When the bus suddenly starts\n      moving forward, the passenger falls backward. Which phenomenon best\n      explains this observation?", "options": ["Friction", "Gravity", "Inertia", "Deceleration"], "correctIndex": 2, "explanation": "The passenger tends to remain in the initial state of rest when the bus\n        accelerates forward; this resistance to change in motion is inertia, so\n        option C is correct.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 87, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "KMU 2025 Q#87 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2025"}, {"id": "paper_d_q88_88", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 88, "subject": "Physics", "topic": "momentum conservation", "question": "A 0.02kg bullet moving at 300m/s embeds itself in a 2 kg block at rest on\n      a smooth surface. What is the velocity of the block-bullet system just\n      after impact?", "options": ["2m/s", "3m/s", "4m/s", "5m/s"], "correctIndex": 1, "explanation": "Conserve linear momentum: (0.02×300) / (2 + 0.02) = 6 / 2.02 ≈ 2.97 m/s,\n        which rounds to 3 m/s (option B).", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 88, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2025 Q#88 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q89_89", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 89, "subject": "Physics", "topic": "projectile motion", "question": "Which of the following statement about projectile motion is CORRECT?", "options": ["The horizontal velocity of a projectile changes constantly due to\n          gravity", "The vertical velocity of a projectile remains constant throughout the\n          flight", "At the highest point, the vertical velocity of the projectile is\n          zero, but the horizontal velocity remains unchanged", "The acceleration of the projectile is zero at the peak of its\n          trajectory"], "correctIndex": 2, "explanation": "Gravity acts vertically, so at the highest point the vertical component\n        of velocity is zero while the horizontal component is unaffected\n        (neglecting air resistance). Thus option C is correct.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 89, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2025 Q#89 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q90_90", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 90, "subject": "Physics", "topic": "instantaneous power", "question": "The rate of doing work at any instant of time is called:", "options": ["Work done", "Instantaneous power", "Average power", "Mechanical energy"], "correctIndex": 1, "explanation": "The rate at which work is done at a particular instant is defined as\n        instantaneous power, so option (b) is correct. Average power would refer\n        to work over a time interval, and the other choices are not rates.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 90, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "KMU 2025 Q#90 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_d_q91_91", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 91, "subject": "Physics", "topic": "potential energy conversion", "question": "A 5kg body falls from the height of 30m towards the ground. All its\n      potential energy is converted into heat on impact. What is the heat energy\n      produced?", "options": ["1270J", "1370J", "1470J", "1570J"], "correctIndex": 2, "explanation": "Gravitational potential energy mgh = 5*9.8*30 ≈ 1470 J, so (c) is\n        correct. The other numeric options do not match the mgh calculation\n        using g ≈ 9.8 m/s².", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 91, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "KMU 2025 Q#91 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_d_q92_92", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 92, "subject": "Physics", "topic": "work and power", "question": "Two students, A and B, each carry a 20kg load to the top of a long\n      staircase. Student A takes 10sec, while student B takes 20sec. Which\n      statement is CORRECT?", "options": ["Student A does more work than student B", "Student B uses more power than student A", "Both students do the same amount of work, but student A uses more\n          power", "Student A and B use the same power since they lifted the same\n          weight"], "correctIndex": 2, "explanation": "Both perform the same work (same weight lifted through same height), but\n        power = work/time; student A completes it faster so uses more power.\n        Thus option (c) is correct. The other statements misstate work or power\n        relationships.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 92, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "KMU 2025 Q#92 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_d_q93_93", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 93, "subject": "Physics", "topic": "angular velocity direction", "question": "If an object is moving anticlockwise along a circular path, in a\n      horizontal plane on a page then the direction of its angular velocity is:", "options": ["Tangential to any point on the circle", "Towards centre of the circle", "Perpendicular to the plane and pointing out of the page", "Perpendicular to the plane and pointing into the page"], "correctIndex": 2, "explanation": "For counterclockwise rotation viewed from above, the angular velocity\n        vector follows the right-hand rule and points out of the page\n        (perpendicular to the plane), so option (c) is correct. Tangential or\n        radial directions describe linear velocity or position, not the angular\n        velocity vector orientation.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 93, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2025 Q#93 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q94_94", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 94, "subject": "Physics", "topic": "arc length formula", "question": "If a particle moves along a circular path of radius r with angular\n      displacement θ (in radians), then the arc length s is given by:", "options": ["rθ", "r/θ", "θ/r", "2πrθ"], "correctIndex": 0, "explanation": "The arc length for an angle in radians is s = rθ, so (a) is correct. The\n        other algebraic forms are incorrect manipulations of the relation.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 94, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2025 Q#94 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q95_95", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 95, "subject": "Physics", "topic": "drag net force", "question": "A ball of weight Fg is falling vertically downward through air. If the\n      drag force acting on it at some instant is Fd, what is the Fnet (net\n      force) on the ball?", "options": ["Fg + Fd", "Fg - Fd", "Fd - Fg", "Fd/Fg"], "correctIndex": 1, "explanation": "Net force acting downward is gravity minus upward drag, i.e. Fnet = Fg −\n        Fd, so (b) is correct. The other algebraic combinations do not represent\n        the correct vector sum of forces.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 95, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2025 Q#95 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q96_96", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 96, "subject": "Physics", "topic": "turbulent flow", "question": "Most kinds of fluid flow are turbulent rather than laminar because of:", "options": ["Zero viscosity", "Very low velocities", "High velocities", "No resistance"], "correctIndex": 2, "explanation": "Turbulence is associated with high flow velocities (and/or large\n        Reynolds number) that overwhelm viscous damping, so (c) is correct. Zero\n        viscosity or no resistance would be unphysical and low velocities favor\n        laminar flow.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 96, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "KMU 2025 Q#96 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "paper_d_q97_97", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 97, "subject": "Physics", "topic": "continuity equation", "question": "According to law of continuity, when the cross-sectional area of a pipe\n      decreases, the fluid velocity:", "options": ["Increases", "Decreases", "Remains the same", "Becomes zero"], "correctIndex": 0, "explanation": "Continuity (A·v = constant for incompressible flow) implies that if area\n        decreases, velocity increases, so (a) is correct. The other choices\n        contradict conservation of mass for steady incompressible flow.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 97, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2025 Q#97 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q98_98", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 98, "subject": "Physics", "topic": "bernoulli pressure", "question": "Water flows steadily through a pipe that gradually narrows. At the wider\n      end, the velocity of water is 1m/s, at the narrower end, the velocity is\n      3m/s. Which statement is CORRECT about the pressure in the narrower end\n      compared to the wider end?", "options": ["Pressure is lower at the narrow end because velocity is higher", "Pressure is higher at the narrow end because velocity is higher", "Pressure is the same at both ends since flow is continuous", "Pressure is independent of velocity of water"], "correctIndex": 0, "explanation": "Bernoulli's principle relates higher fluid speed to lower static\n        pressure (for horizontal flow), so pressure is lower at the narrow\n        (faster) section; option (a) is correct. The other options contradict\n        Bernoulli or continuity relations.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 98, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2025 Q#98 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q99_99", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 99, "subject": "Physics", "topic": "wave motion condition", "question": "What is the necessary condition of a wave motion?", "options": ["The medium must be elastic", "The medium must be inelastic", "The particles of the medium must be independent of each other", "The particles of the medium must not be dependent on each other"], "correctIndex": 0, "explanation": "A medium that supports wave propagation must be able to restore\n        displaced particles to equilibrium (elastic response); hence (a) is\n        correct. ‘‘Inelastic’’ or complete independence of particles would\n        prevent restoring forces needed for wave motion.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 99, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "KMU 2025 Q#99 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2025"}, {"id": "paper_d_q100_100", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 100, "subject": "Physics", "topic": "progressive wave", "question": "A progressive wave is one which:", "options": ["Does not vibrate the medium", "Carries energy across the medium", "Propagates only through air", "Requires a denser medium for propagation"], "correctIndex": 1, "explanation": "A progressive (traveling) wave transports energy from one place to\n        another through the medium, so (b) is correct. It does involve vibration\n        of the medium and can propagate in various media, not only air or\n        necessarily denser media.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 100, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "KMU 2025 Q#100 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2025"}, {"id": "paper_d_q101_101", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 101, "subject": "Physics", "topic": "speed of sound dependence", "question": "Speed of sound in air increases with:", "options": ["Higher temperature, higher humidity", "Lower temperature, lower humidity", "Higher pressure at constant temperature", "Higher density at constant elasticity"], "correctIndex": 0, "explanation": "Sound speed in air increases primarily with temperature and slightly\n        with humidity; (a) is therefore correct. At constant temperature\n        pressure or density changes alone (without elasticity changes) do not\n        increase sound speed as directly.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 101, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "KMU 2025 Q#101 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2025"}, {"id": "paper_d_q102_102", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 102, "subject": "Physics", "topic": "wavelength change", "question": "A wave has velocity 300m/s and frequency 100Hz. If the medium is changed\n      so that velocity doubles but frequency remains constant, the new\n      wavelength will be:", "options": ["Halved", "Doubled", "Same", "Zero"], "correctIndex": 1, "explanation": "Wavelength λ = v/f. If v doubles while f is unchanged, λ doubles as\n        well; option (b) is correct. The other choices contradict the linear\n        relation between v and λ.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 102, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2025 Q#102 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_d_q103_103", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 103, "subject": "Physics", "topic": "shm kinetic energy", "question": "When a particle executing simple harmonic motion moves from the mean\n      position to the extreme position, its kinetic energy:", "options": ["Increases continuously", "Decreases continuously and becomes zero at the extreme position", "Remains constant throughout the motion", "Becomes maximum at the extreme position"], "correctIndex": 1, "explanation": "In SHM kinetic energy is maximum at the mean and decreases continuously\n        to zero at the extremity where velocity is zero, so (b) is correct. It\n        cannot increase toward the extreme or be constant; kinetic energy is\n        zero at the extreme, not maximum.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 103, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "KMU 2025 Q#103 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_d_q104_104", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 104, "subject": "Physics", "topic": "heat flow direction", "question": "Heat will spontaneously flow from:", "options": ["Lower to higher internal energy only", "High pressure to low pressure", "High to low temperature", "Low temperature to high temperature"], "correctIndex": 2, "explanation": "Heat naturally flows from regions of higher temperature to lower\n        temperature, so option (c) is correct. The other statements either\n        reverse the direction or confuse pressure with thermal flow.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 104, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "KMU 2025 Q#104 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2025"}, {"id": "paper_d_q105_105", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 105, "subject": "Chemistry", "topic": "cp minus cv", "question": "At a constant Pressure (Cp) and Volume (Cv), an ideal gas has C p - C v =\n      R Then Cp will be?", "options": ["R/2", "3/2 R", "5/2 R", "7/2 R"], "correctIndex": 2, "explanation": "For a monatomic ideal gas the molar heat capacity at constant volume Cv\n        = 3/2 R, and since Cp − Cv = R for an ideal gas, Cp = Cv + R = 3/2 R + R\n        = 5/2 R. Thus option '5/2 R' is correct.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 105, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "KMU 2025 Q#105 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_d_q106_106", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 106, "subject": "Physics", "topic": "definition of electric field", "question": "The electric field at a point is defined as:", "options": ["Potential per unit charge", "Work done per unit time", "Charge per unit area", "Force per unit positive test charge"], "correctIndex": 3, "explanation": "Electric field is defined as the force experienced per unit positive\n        test charge placed at that point (E = F/q). The other choices describe\n        different physical quantities (potential, power, surface charge\n        density).", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 106, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "KMU 2025 Q#106 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2025"}, {"id": "paper_d_q107_107", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 107, "subject": "Physics", "topic": "coulombs law relation", "question": "Coulomb's law fits well into:", "options": ["Newton's 1st law", "Newton's 2nd law", "Newton's 3rd law", "Gauss's law"], "correctIndex": 2, "explanation": "Coulomb's law expresses the mutual electrostatic force between two\n        charges and embodies the action–reaction pair, so it aligns with\n        Newton's third law. The other Newton laws and Gauss's law describe\n        different aspects of mechanics or field theory.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 107, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "KMU 2025 Q#107 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2025"}, {"id": "paper_d_q108_108", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 108, "subject": "Physics", "topic": "electric potential difference", "question": "The work done in moving a unit positive charge from one point to another\n      while keeping the charge in electrostatic equilibrium is called:", "options": ["Kinetic energy", "Potential energy", "Elastic potential energy", "Potential difference"], "correctIndex": 3, "explanation": "The work required to move a unit positive charge between two points in\n        an electrostatic field is by definition the potential difference\n        (voltage) between those points. Potential energy is work for a given\n        charge, while potential difference is per unit charge.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 108, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "KMU 2025 Q#108 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_d_q109_109", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 109, "subject": "Physics", "topic": "power dependence on voltage", "question": "If the potential difference (V) across a conductor is doubled, keeping\n      resistance (R) constant, the power dissipated (P) becomes:", "options": ["Doubled", "Halved", "Four times", "Remains unchanged"], "correctIndex": 2, "explanation": "Power dissipated in a resistor is P = V^2/R, so if V is doubled P\n        becomes (2V)^2/R = 4V^2/R - four times the original. The other options\n        misstate this quadratic dependence on voltage.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 109, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "KMU 2025 Q#109 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_d_q110_110", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 110, "subject": "Chemistry", "topic": "free radical chlorination", "question": "Consider the chlorination of methane to methyl chloride, the attack of\n      chlorine free radical on methane, occurs in which phase?", "options": ["Before initiation", "Initiation", "Propagation", "Termination"], "correctIndex": 2, "explanation": "In a radical chain mechanism the step where a chlorine radical abstracts\n        a hydrogen from methane and forms a methyl radical is a propagation\n        step. Initiation produces radicals (e.g., Cl2 → 2Cl•) and termination\n        removes radicals.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 110, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "KMU 2025 Q#110 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2025"}, {"id": "paper_d_q111_111", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 111, "subject": "Biology", "topic": "pancreatic carboxypeptidase", "question": "A patient with pancreatic insufficiency shows reduced activity of an\n      enzyme that hydrolyzes the first peptide bond at the carboxyl end of\n      proteins and peptides. Which enzyme is deficient?", "options": ["Elastase", "Pepsin", "Carboxypeptidase", "Collagenase"], "correctIndex": 2, "explanation": "Carboxypeptidase removes amino acids from the carboxyl (C-) terminus of\n        peptides and is produced by the pancreas. Pepsin acts at the N-terminal\n        side in the stomach, elastase and collagenase have different substrate\n        specificities.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 111, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2025 Q#111 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q112_112", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 112, "subject": "Chemistry", "topic": "electrolytic cell anode", "question": "In an electrolytic cell when the current passes through a solution, the\n      anode is:", "options": ["a positive electrode where oxidation occurs", "a negative electrode where oxidation occurs", "a negative electrode where reduction occurs", "a positive electrode where reduction occurs"], "correctIndex": 0, "explanation": "In an electrolytic cell the anode is the positive electrode and\n        oxidation occurs at the anode. The cathode is the negative electrode\n        where reduction occurs, so options stating negative/reduction for the\n        anode are incorrect.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 112, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2025 Q#112 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_d_q113_113", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 113, "subject": "Chemistry", "topic": "internal energy effects", "question": "An increase in the internal energy of a chemical system can lead to all\n      EXCEPT:", "options": ["An increase in temperature due to rise in kinetic energy of\n          molecules", "A phase change such as melting or evaporation", "A chemical reaction if energy supplied is sufficient to break\n          bonds", "An increase in temperature due to drop in kinetic energy of\n          molecules"], "correctIndex": 3, "explanation": "An increase in internal energy raises kinetic energy and can cause\n        temperature rise, phase changes or enable reactions if bond energies are\n        supplied. It cannot cause a temperature rise by a drop in kinetic\n        energy, so option 4 is contradictory and incorrect.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 113, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2025 Q#113 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_d_q114_114", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 114, "subject": "Chemistry", "topic": "sp2 hybridization in ethene", "question": "In ethene molecule, each carbon atom has three hybridized sp2 orbitals\n      which are:", "options": ["Coplanar", "Tetrahedral", "Linear", "Pyramidal"], "correctIndex": 0, "explanation": "In ethene each carbon is sp2 hybridized giving three coplanar orbitals\n        (sigma framework) and one unhybridized p orbital for the pi bond.\n        Tetrahedral and linear geometries correspond to sp3 and sp hybridization\n        respectively.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 114, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "KMU 2025 Q#114 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2025"}, {"id": "paper_d_q115_115", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 115, "subject": "Chemistry", "topic": "beryllium oxidation beo layer", "question": "Which of the following best explains the reaction between Beryllium (Be)\n      and Oxygen (O)?", "options": ["Be burns vigorously with oxygen forming a layer of BeO, which\n          accelerates the oxidation of remaining metal", "Be reacts with oxygen forming a layer of BeO, which protects the\n          metal from further oxidation", "Be reacts slowly with oxygen to form a volatile oxide BeO, which\n          evaporates quickly", "Be is the only alkaline earth metal that doesn't react with\n          oxygen"], "correctIndex": 1, "explanation": "Beryllium becomes passivated by a thin BeO layer that protects the\n        underlying metal from further oxidation (passivation). Options claiming\n        the oxide accelerates oxidation or evaporates, or that Be doesn't react\n        at all, are incorrect.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 115, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "KMU 2025 Q#115 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2025"}, {"id": "paper_d_q116_116", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 116, "subject": "Chemistry", "topic": "gas constant value", "question": "The value of R in atm.dm3.mol-1.K-1 is:", "options": ["0.0821", "0.821", "62.4", "8.314"], "correctIndex": 0, "explanation": "The gas constant R expressed in units atm·dm3·mol−1·K−1 (or\n        L·atm·mol−1·K−1) is 0.0821. 8.314 is R in J·mol−1·K−1 (or\n        L·kPa·mol−1·K−1 when converted).", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 116, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "KMU 2025 Q#116 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_d_q117_117", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 117, "subject": "Chemistry", "topic": "factors affecting rate", "question": "The rate of a chemical reaction changes with:", "options": ["Concentration of reactant molecules", "Concentration of product molecules", "Concentration of both reactant and product", "Rate constant"], "correctIndex": 0, "explanation": "Reaction rate depends primarily on reactant concentrations (and\n        conditions); product concentration does not generally determine the\n        forward rate. The rate constant is a parameter of the rate law, not a\n        variable that changes the rate in the same way concentrations do.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 117, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "KMU 2025 Q#117 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2025"}, {"id": "paper_d_q118_118", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 118, "subject": "Chemistry", "topic": "planck hf dependence", "question": "According to Planck's quantum theory, if the frequency of photon is\n      doubled, the value of hf will be:", "options": ["Doubled", "Increased 3 times", "Increased 4 times", "Unchanged"], "correctIndex": 0, "explanation": "Planck's relation is E = hf, so energy is directly proportional to\n        frequency. Doubling frequency doubles hf. The other choices imply\n        nonlinear dependence or no change, which are incorrect.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 118, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "KMU 2025 Q#118 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2025"}, {"id": "paper_d_q119_119", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 119, "subject": "Chemistry", "topic": "rate constant dependence", "question": "The specific rate constant (k) of a reaction is related to the\n      concentration of reactants:", "options": ["Directly", "Inversely", "Exponentially", "Independently"], "correctIndex": 3, "explanation": "The rate constant k is independent of reactant concentrations; it\n        depends on temperature and activation parameters. It does not vary\n        directly or inversely with the concentrations themselves.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 119, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "KMU 2025 Q#119 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2025"}, {"id": "paper_d_q120_120", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 120, "subject": "Biology", "topic": "protein secondary structure", "question": "An experiment shows that heating a 'protein' disrupts the alpha helix\n      structure. Which protein structure is mainly affected?", "options": ["Primary structure", "Secondary structure", "Tertiary structure", "Quaternary structure"], "correctIndex": 1, "explanation": "The alpha helix is a type of secondary structure formed by hydrogen\n        bonding along the backbone; heating disrupts these hydrogen bonds and so\n        affects secondary structure. Primary structure (peptide sequence)\n        remains intact unless covalent bonds break.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 120, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2025 Q#120 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_d_q121_121", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 121, "subject": "Chemistry", "topic": "kinetic molecular theory", "question": "Which of the following is NOT a postulate of kinetic molecular theory of\n      gases?", "options": ["Gas molecules undergo elastic collision", "Gas molecules are in continuous random motion", "Gas molecules do not exert pressure when molecules collide with wall\n          of container", "Gas molecules are far away from each other"], "correctIndex": 2, "explanation": "Kinetic molecular theory states gas molecules collide elastically, move\n        randomly, are far apart, and collisions with container walls cause\n        pressure. The statement that collisions do not exert pressure\n        contradicts the theory, so it's not a postulate.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 121, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "KMU 2025 Q#121 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_d_q122_122", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 122, "subject": "Chemistry", "topic": "spectral series hydrogen", "question": "Spectral series for hydrogen spectrum are :", "options": ["2", "3", "4", "5"], "correctIndex": 2, "explanation": "Hydrogen has several spectral series (e.g., Lyman, Balmer, Paschen,\n        Brackett) corresponding to transitions ending at n=1,2,3,4 etc. The\n        number 4 corresponds to the Brackett series being one of the named\n        series; the printed correct choice corresponds to 4 per the exam key.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 122, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "KMU 2025 Q#122 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2025"}, {"id": "paper_d_q123_123", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 123, "subject": "Chemistry", "topic": "most electronegative element", "question": "The most electronegative element in periodic table is:", "options": ["F", "Cl", "N", "O"], "correctIndex": 0, "explanation": "Fluorine is the most electronegative element (highest tendency to\n        attract electrons). Chlorine, oxygen and nitrogen are less\n        electronegative than fluorine.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 123, "syllabusUnit": "Unit 8: Inorganic Chemistry & Periodicity", "pmdcTopic": "Periodic Trends, Group Chemistry & Transition Elements", "textbookCitation": "PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16", "citationString": "KMU 2025 Q#123 | Unit 8: Inorganic Chemistry & Periodicity | PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16"}, "year": "2025"}, {"id": "paper_d_q124_124", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 124, "subject": "Chemistry", "topic": "effect of temperature on ΔH positive reaction", "question": "If ΔH for a reaction is positive, then by decreasing temperature, the\n      reaction will", "options": ["Move forward", "Move in reverse", "Have no effect", "Be both forward and reverse"], "correctIndex": 1, "explanation": "For an endothermic reaction (ΔH positive) lowering temperature favors\n        the exothermic direction (the reverse), according to Le Chatelier's\n        principle. Thus the equilibrium shifts to the reverse reaction.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 124, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2025 Q#124 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_d_q125_125", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 125, "subject": "Chemistry", "topic": "hydration of propene", "question": "The addition of water to propene in the presence of sulfuric acid\n      produces:", "options": ["Propane", "Propan-2-ol", "Butanol", "Ethanol"], "correctIndex": 1, "explanation": "Acid-catalyzed hydration of propene adds OH to the more substituted\n        carbon (Markovnikov), giving propan-2-ol. Propane and ethanol are\n        incorrect products, and butanol would require a different carbon\n        skeleton.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 125, "syllabusUnit": "Unit 12: Carboxylic Acids & Derivatives", "pmdcTopic": "Acidity of Carboxylic Acids & Acyl Derivatives", "textbookCitation": "PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21", "citationString": "KMU 2025 Q#125 | Unit 12: Carboxylic Acids & Derivatives | PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21"}, "year": "2025"}, {"id": "paper_d_q126_126", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 126, "subject": "Chemistry", "topic": "sp2 hybridization examples", "question": "In which of the following molecules does the central atom use sp2\n      hybridization?", "options": ["PH3", "NH3", "BH3", "SbH3"], "correctIndex": 2, "explanation": "In BH3 the boron central atom is sp2 hybridized giving a trigonal planar\n        geometry. PH3, NH3 and SbH3 have pyramidal geometries corresponding to\n        different hybridization (or near pure p for PH3 and SbH3).", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 126, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "KMU 2025 Q#126 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2025"}, {"id": "paper_d_q127_127", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 127, "subject": "Chemistry", "topic": "phenol carbon hybridization", "question": "In a molecule of phenol, the carbon atom which is attached to -OH group\n      is:", "options": ["sp hybridized", "sp2 hybridized", "sp3 hybridized", "unhybridized"], "correctIndex": 1, "explanation": "The carbon of the aromatic ring bonded to the OH in phenol is part of\n        the benzene ring and is sp2 hybridized. It participates in the aromatic\n        pi system; it is not sp3 or unhybridized.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 127, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "KMU 2025 Q#127 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2025"}, {"id": "paper_d_q128_128", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 128, "subject": "Chemistry", "topic": "planar molecule example", "question": "Which one of the following is a planar molecule?", "options": ["NH3", "H2O", "BF3", "CH4"], "correctIndex": 2, "explanation": "BF3 is trigonal planar with sp2 hybridization on boron, so the molecule\n        is planar. NH3 and H2O are pyramidal/bent and CH4 is tetrahedral, none\n        of which are planar.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 128, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2025 Q#128 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_d_q129_129", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 129, "subject": "Chemistry", "topic": "bond energy comparison", "question": "Which of the following has highest bond energy?", "options": ["HCl", "HI", "HF", "HBr"], "correctIndex": 2, "explanation": "HF has the strongest H–X bond among these due to the small size of\n        fluorine and strong bond strength and partial ionic character; heavier\n        halides (HI, HBr) have weaker bonds, and HCl is intermediate.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 129, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "KMU 2025 Q#129 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2025"}, {"id": "paper_d_q130_130", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 130, "subject": "English", "topic": "gerund phrase function", "question": "In the sentence \"Jogging every morning improves my mood,\" what role does\n      the gerund phrase play?", "options": ["Object of a verb", "Direct object", "Predicative noun", "Subject"], "correctIndex": 3, "explanation": "The gerund phrase \"Jogging every morning\" is performing the action of\n        the verb (it is what the sentence is about), so it functions as the\n        subject. It is not an object or predicative noun, which would occur in\n        constructions like 'I enjoy jogging' (object) or 'My hobby is jogging'\n        (predicative noun).", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 130, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "KMU 2025 Q#130 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2025"}, {"id": "paper_d_q131_131", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 131, "subject": "English", "topic": "prepositions time expressions", "question": "The meeting has been scheduled ___ 3 p.m. sharp.", "options": ["on", "at", "in", "to"], "correctIndex": 1, "explanation": "The preposition 'at' is used for specific clock times (e.g. at 3 p.m.).\n        'On' is used for days/dates, 'in' for months/years/longer periods, and\n        'to' is not used here.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 131, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "KMU 2025 Q#131 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2025"}, {"id": "paper_d_q132_132", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 132, "subject": "English", "topic": "transitional device", "question": "\"She studied hard; ______, she passed the exam with distinction.\" Choose\n      the CORRECT transitional device:", "options": ["however", "for instance", "consequently", "in contrast"], "correctIndex": 2, "explanation": "\"Consequently\" correctly expresses a result (she studied hard and, as a\n        result, she passed). \"However\" and \"in contrast\" indicate contrast, and\n        \"for instance\" introduces an example, so they are not appropriate here.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 132, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "KMU 2025 Q#132 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2025"}, {"id": "paper_d_q133_133", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 133, "subject": "English", "topic": "passive voice usage", "question": "She completed the task with great difficulty. Identify the CORRECT usage\n      of passive voice.", "options": ["The task was completed with great difficulty by her.", "The task has been completed with great difficulty by her.", "The task was been completed with great difficulty by her.", "The task was being completed with great difficulty by her."], "correctIndex": 0, "explanation": "The original sentence is simple past active; the correct passive\n        equivalent is simple past passive: \"The task was completed with great\n        difficulty by her.\" Option b is present perfect, c is ungrammatical, and\n        d expresses a past continuous passive which changes the meaning.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 133, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "KMU 2025 Q#133 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2025"}, {"id": "paper_d_q134_134", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 134, "subject": "English", "topic": "subject verb agreement", "question": "Each of the boys ______ ambitious to lead the team.", "options": ["have", "has", "is", "are"], "correctIndex": 2, "explanation": "The correct choice is \"is\" because the predicate adjective \"ambitious\"\n        follows a linking verb; \"Each of the boys\" is the subject and takes a\n        singular verb form (is). Options \"have\" and \"are\" are plural and \"has\"\n        would require an object, not an adjective complement.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 134, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "KMU 2025 Q#134 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2025"}, {"id": "paper_d_q135_135", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 135, "subject": "English", "topic": "figurative language", "question": "\"Revenge is a kind of wild justice.\" The sentence illustrates the use of:", "options": ["Personification", "Pun", "Metaphor", "Hyperbole"], "correctIndex": 2, "explanation": "The sentence compares \"revenge\" to \"wild justice\" directly, which is a\n        metaphor. It is not personification (giving human traits), a pun\n        (wordplay), or hyperbole (exaggeration).", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 135, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "KMU 2025 Q#135 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2025"}, {"id": "paper_d_q136_136", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 136, "subject": "English", "topic": "vocabulary meaning", "question": "The old man was feeble, barely able to walk. The word 'feeble' means:", "options": ["Healthy", "Weak", "Strong", "Fat"], "correctIndex": 1, "explanation": "\"Feeble\" means weak or frail, especially physically. The other options\n        are antonyms or unrelated.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 136, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "KMU 2025 Q#136 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2025"}, {"id": "paper_d_q137_137", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 137, "subject": "English", "topic": "literary devices", "question": "Which literary device involves using words or phrases that convey the\n      opposite of their literal meaning?", "options": ["Irony", "Parody", "Satire", "Sarcasm"], "correctIndex": 0, "explanation": "Irony involves expressions where the intended meaning is opposite the\n        literal meaning. Parody imitates for comic effect, satire criticizes,\n        and sarcasm is a biting form of irony but the broader correct term is\n        irony.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 137, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "KMU 2025 Q#137 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2025"}, {"id": "paper_d_q138_138", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 138, "subject": "English", "topic": "possessive pronoun", "question": "All of the players forgot ____ jerseys.", "options": ["his", "her", "them", "their"], "correctIndex": 3, "explanation": "When referring collectively to \"players\" of mixed or unspecified gender,\n        the plural possessive \"their\" correctly agrees with the plural noun and\n        fits naturally. \"His\" or \"her\" are singular and \"them\" is an object\n        pronoun, not possessive.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 138, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "KMU 2025 Q#138 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2025"}, {"id": "paper_d_q139_139", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 139, "subject": "Logical Reasoning", "topic": "halving dosing", "question": "A medication dose starts at 100mg and halves each day. What will be the\n      dose on day 4?", "options": ["12.5mg", "25mg", "30mg", "50mg"], "correctIndex": 0, "explanation": "Halving each day: Day1 100 mg, Day2 50 mg, Day3 25 mg, Day4 12.5 mg. The\n        other choices do not follow this halving sequence.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 139, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "KMU 2025 Q#139 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2025"}, {"id": "paper_d_q140_140", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 140, "subject": "Logical Reasoning", "topic": "equalizing books shelf", "question": "A library has 4 books on Shelf A, and 8 books on Shelf B. Some books are\n      removed from Shelf B such that both shelves now have exactly the same\n      number of books. How many books were removed from Shelf B?", "options": ["1", "2", "3", "4"], "correctIndex": 3, "explanation": "For the shelves to hold equal numbers, Shelf B must drop from 8 books to\n        4 to match Shelf A, so 4 books were removed.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 140, "syllabusUnit": "Pattern Recognition & Sequences", "pmdcTopic": "Numerical & Pattern Sequence Reasoning", "textbookCitation": "PMDC MDCAT Logical Reasoning Framework", "citationString": "KMU 2025 Q#140 | Pattern Recognition & Sequences | PMDC MDCAT Logical Reasoning Framework"}, "year": "2025"}, {"id": "paper_d_q141_141", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 141, "subject": "Logical Reasoning", "topic": "rank problem", "question": "Ahmed ranks 10th in the class of 46 students. There are only 7 students\n      below Bilal rank wise. How many students are there between Ahmed and\n      Bilal?", "options": ["27", "28", "30", "32"], "correctIndex": 1, "explanation": "Bilal has 7 students below him, so his rank is 46 - 7 = 39. Ahmed is\n        10th, so students between them = 39 - 10 - 1 = 28. The other counts are\n        incorrect.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 141, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "KMU 2025 Q#141 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2025"}, {"id": "paper_d_q142_142", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 142, "subject": "Logical Reasoning", "topic": "family relationship", "question": "How is Ali related to Mustafa? If Ali says, \"Mustafa's mother is the only\n      child of my grandmother.\"", "options": ["Brother", "Cousin", "Uncle", "Father"], "correctIndex": 0, "explanation": "If Mustafa's mother is the only child of Ali's grandmother, that child\n        is Ali's parent. Therefore Mustafa's mother is Ali's parent, making\n        Mustafa Ali's brother. The other relations do not fit this family\n        description.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 142, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "KMU 2025 Q#142 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2025"}, {"id": "paper_d_q143_143", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 143, "subject": "Logical Reasoning", "topic": "data privacy moral argument", "question": "A mobile company is deciding whether to collect personal user data for\n      improving advertisement. Which of the following is a moral argument\n      against collecting the data?", "options": ["Users may lose trust in the company, which could hurt profits.", "It is wrong to collect data without users' clear and informed\n          consent.", "Competitors already collect more data, and we need to stay\n          competitive.", "More data means more accurate advertising, which boosts sales."], "correctIndex": 1, "explanation": "Option b states a moral objection (collecting data without clear,\n        informed consent is ethically wrong). The other options are pragmatic or\n        business considerations, not moral arguments.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 143, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "KMU 2025 Q#143 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2025"}, {"id": "paper_d_q144_144", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 144, "subject": "Logical Reasoning", "topic": "age algebra", "question": "A father is 5 years older than twice his son's age. If the son is 12, what\n      is the father's age?", "options": ["28 years", "29 years", "30 years", "32 years"], "correctIndex": 1, "explanation": "Twice the son's age: 2 × 12 = 24; add 5 gives 29 years. The other\n        options are arithmetically incorrect.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 144, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "KMU 2025 Q#144 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2025"}, {"id": "paper_d_q145_145", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 145, "subject": "Logical Reasoning", "topic": "missing number sequence", "question": "Which number comes in the missing place? 200, 180, 162, 146, 132, _____", "options": ["118", "120", "122", "126"], "correctIndex": 1, "explanation": "The differences decrease by 2 each time: -20, -18, -16, -14, so next is\n        -12: 132 - 12 = 120. The other choices do not follow this pattern.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 145, "syllabusUnit": "Pattern Recognition & Sequences", "pmdcTopic": "Numerical & Pattern Sequence Reasoning", "textbookCitation": "PMDC MDCAT Logical Reasoning Framework", "citationString": "KMU 2025 Q#145 | Pattern Recognition & Sequences | PMDC MDCAT Logical Reasoning Framework"}, "year": "2025"}, {"id": "paper_d_q146_146", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 146, "subject": "Logical Reasoning", "topic": "weight empty boxes", "question": "If 5 boxes of soap weigh 75 kilos and each box when empty weighs 3 kilos.\n      What is total weight of the soaps?", "options": ["15", "30", "45", "60"], "correctIndex": 3, "explanation": "Total empty-box weight = 5 × 3 = 15 kg. Soap weight = total 75 − boxes\n        15 = 60 kg. The other options are incorrect results.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 146, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "KMU 2025 Q#146 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2025"}, {"id": "paper_d_q147_147", "paperTitle": "KMU MDCAT 2025 (Paper D)", "shortTitle": "KMU 2025", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 147, "subject": "Logical Reasoning", "topic": "geometric sequence halving", "question": "Consider the sequence: 64, 32, 16, 8, ... What is the 10th term of this\n      sequence?", "options": ["2", "4", "1/4", "1/8"], "correctIndex": 3, "explanation": "The sequence halves each term: terms are 64,32,16,8,4,2,1,1/2,1/4,1/8.\n        The 10th term is 1/8; the other options correspond to different term\n        positions.", "reference": {"sourcePaper": "KMU MDCAT 2025 (Paper D)", "paperCode": "Paper D", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 147, "syllabusUnit": "Pattern Recognition & Sequences", "pmdcTopic": "Numerical & Pattern Sequence Reasoning", "textbookCitation": "PMDC MDCAT Logical Reasoning Framework", "citationString": "KMU 2025 Q#147 | Pattern Recognition & Sequences | PMDC MDCAT Logical Reasoning Framework"}, "year": "2025"}, {"id": "official_paper_q1_1", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 1, "subject": "Physics", "topic": "motion of charged particle in uniform magnetic field", "question": "The path of a charged particle in a plane perpendicular to a uniform\n      magnetic field is:", "options": ["Circular", "Helical", "Parabola", "Elliptical"], "correctIndex": 0, "explanation": "When a charged particle moves perpendicular to a uniform magnetic field\n        the magnetic force is always perpendicular to the velocity and provides\n        a centripetal force. That constant perpendicular force makes the\n        particle move in a circle at constant speed, so the path is circular.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 1, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "NUMS 2025 Q#1 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2025"}, {"id": "official_paper_q2_2", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 2, "subject": "Physics", "topic": "magnetic force on stationary charge", "question": "Magnetic force acting on a charge at rest is:", "options": ["Zero", "Positive", "Negative", "Infinite"], "correctIndex": 0, "explanation": "Magnetic force on a charge is F = q(v × B), so if the charge is at rest\n        (v = 0) the cross product is zero and no magnetic force acts. Therefore\n        the magnetic force on a stationary charge is zero.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 2, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2025 Q#2 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "official_paper_q3_3", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 3, "subject": "Physics", "topic": "cyclotron frequency dependence", "question": "If mass of a charged particle is doubled, cyclotron frequency becomes:", "options": ["Doubled", "Halved", "Quadrupled", "One fourth"], "correctIndex": 1, "explanation": "Cyclotron frequency is ω = qB/m (or f = qB/2πm), so frequency is\n        inversely proportional to mass. Doubling the particle's mass halves the\n        cyclotron frequency.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 3, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2025 Q#3 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "official_paper_q4_4", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 4, "subject": "Physics", "topic": "field of infinite sheet of charge", "question": "Electric field intensity of infinite charge sheet:", "options": ["E = 2σ/ε0", "E = 1/ε0", "E = σ/ε0", "σ/(2ε0)"], "correctIndex": 3, "explanation": "An infinite charged plane produces a constant electric field on each\n        side with magnitude E = σ/(2ε0), independent of distance, because\n        Gauss's law gives equal flux through two faces of a Gaussian pillbox.\n        Thus the correct expression is σ/(2ε0).", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 4, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "NUMS 2025 Q#4 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2025"}, {"id": "official_paper_q5_5", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 5, "subject": "Physics", "topic": "radioactive stability and decay constant", "question": "Stability of radioactivity element is determined by:", "options": ["Decay constant", "Rate of the radioactive decay", "Time of decay", "Number of radioactive nuclei"], "correctIndex": 0, "explanation": "The decay constant (λ) quantifies how quickly nuclei decay: a larger λ\n        means faster decay and less stability, while a small λ indicates greater\n        stability. Therefore the stability of a radioactive element is\n        characterized by its decay constant.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 5, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "NUMS 2025 Q#5 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2025"}, {"id": "official_paper_q6_6", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 6, "subject": "Physics", "topic": "energy unit conversion kwh to joules", "question": "kWh is equal to:", "options": ["3.6 MW", "3.6 MJ", "3.6 kJ", "3.6 GJ"], "correctIndex": 1, "explanation": "1 kilowatt-hour is 1 kW × 3600 s = 1000 J/s × 3600 s = 3.6×10^6 J, which\n        is 3.6 MJ. So 1 kWh equals 3.6 megajoules.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 6, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2025 Q#6 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "official_paper_q7_7", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 7, "subject": "Physics", "topic": "faradays law change in magnetic flux", "question": "Basic requirement for induced emf is:", "options": ["Flux linked to coil", "No flux linked to coil", "Coil should be circular", "Change in flux links to the coil"], "correctIndex": 3, "explanation": "Faraday's law states that an emf is induced when the magnetic flux\n        through a coil changes with time. Simply having flux is not enough; a\n        change in the flux linkage is the necessary condition for an induced\n        emf.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 7, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "NUMS 2025 Q#7 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2025"}, {"id": "official_paper_q8_8", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 8, "subject": "Physics", "topic": "impulse and change in momentum", "question": "Product of force and time is equal to:", "options": ["Change in displacement", "Change in momentum", "Change in velocity", "Change in acceleration"], "correctIndex": 1, "explanation": "The product of force and time is impulse (J = FΔt), and impulse equals\n        the change in momentum (Δp) of a body. Therefore force×time corresponds\n        to change in momentum.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 8, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2025 Q#8 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "official_paper_q9_9", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 9, "subject": "Physics", "topic": "rapid expansion adiabatic process", "question": "Bursting of tire is an example of which process?", "options": ["Adiabatic", "Isochoric", "Isothermal", "Isobaric"], "correctIndex": 0, "explanation": "A tire burst is a very fast expansion of gas with negligible time for\n        heat exchange with surroundings, so the process is effectively\n        adiabatic. Rapid decompression processes are commonly approximated as\n        adiabatic.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 9, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "NUMS 2025 Q#9 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2025"}, {"id": "official_paper_q10_10", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 10, "subject": "Physics", "topic": "right hand rule for angular velocity direction", "question": "Direction of angular velocity can be found by:", "options": ["Right-hand rule", "Fleming's left-hand rule", "Lenz's law", "Faraday's law"], "correctIndex": 0, "explanation": "The direction of angular velocity (and angular momentum) for a rotating\n        object is given by the right-hand rule: curl the fingers in the rotation\n        sense and the thumb points along the angular velocity vector. Fleming's\n        left-hand rule and Lenz's/Faraday's laws refer to different phenomena.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 10, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2025 Q#10 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "official_paper_q11_11", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 11, "subject": "Physics", "topic": "doppler shift for approaching source", "question": "When star moves towards the earth, the shift is known as:", "options": ["Blue shift", "Red shift", "Compton shift", "None"], "correctIndex": 0, "explanation": "When a star moves toward the observer the wavelengths are shifted to\n        shorter values (higher frequency), which is called a blue shift. Red\n        shift corresponds to the source moving away.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 11, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "NUMS 2025 Q#11 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2025"}, {"id": "official_paper_q12_12", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 12, "subject": "Physics", "topic": "projectile range optimal angle", "question": "Angle at which maximum range of projectile is achieved?", "options": ["0°", "45°", "90°", "76°"], "correctIndex": 1, "explanation": "For projectile motion on level ground (neglecting air resistance) the\n        horizontal range is maximized when the launch angle is 45°, because the\n        product of horizontal and vertical components of velocity is maximized\n        at that angle.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 12, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2025 Q#12 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "official_paper_q13_13", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 13, "subject": "Physics", "topic": "emission line spectrum of gaseous atoms", "question": "Which of the following spectrum is produced when atoms are in the gaseous\n      state?", "options": ["Continuous spectrum", "Band spectrum", "Line spectrum", "Absorption spectrum"], "correctIndex": 2, "explanation": "Atoms in the gaseous state emit radiation at discrete energies\n        corresponding to electronic transitions, producing line spectra (sharp\n        spectral lines). Continuous and band spectra arise from solids/liquids\n        or molecules, not isolated gaseous atoms.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 13, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2025 Q#13 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "official_paper_q14_14", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 14, "subject": "Physics", "topic": "unit of conductance siemens", "question": "Conductance is reciprocal of resistance, its unit is:", "options": ["Siemen", "Ohm", "Ampere", "Watt"], "correctIndex": 0, "explanation": "Conductance is the reciprocal of resistance and its SI unit is the\n        siemens (S), formerly called the mho. Ohm is the unit of resistance, so\n        conductance is measured in siemens.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 14, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "NUMS 2025 Q#14 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2025"}, {"id": "official_paper_q15_15", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 15, "subject": "Physics", "topic": "frictional heating and internal energy", "question": "During rubbing of hands, internal energy:", "options": ["Increases", "Decreases", "Zero", "Remains same"], "correctIndex": 0, "explanation": "Rubbing hands converts macroscopic mechanical work into microscopic\n        thermal energy, raising the internal energy (and temperature) of the\n        hands. Thus internal energy increases during rubbing.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 15, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2025 Q#15 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "official_paper_q16_16", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 16, "subject": "Physics", "topic": "kinetic energy dependence on velocity", "question": "If velocity is doubled, what happens to kinetic energy:", "options": ["Remains same", "Doubles", "Quadruples", "Halves"], "correctIndex": 2, "explanation": "Kinetic energy is proportional to the square of speed (KE = 1/2 mv^2),\n        so doubling the velocity multiplies kinetic energy by 2^2 = 4. Therefore\n        the kinetic energy quadruples.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 16, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2025 Q#16 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "official_paper_q17_17", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 17, "subject": "Physics", "topic": "solar constant typical value", "question": "On a clear day at noon, intensity of solar energy is:", "options": ["1.4 kW/m2", "1.2 kW/m2", "1 kW/m2", "1.3 kW/m2"], "correctIndex": 0, "explanation": "The solar irradiance at Earth's orbit (often called the solar constant)\n        is about 1.36 kW/m^2 and is commonly approximated as 1.4 kW/m^2 on a\n        clear noon day. So 1.4 kW/m^2 is the appropriate rounded value.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 17, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2025 Q#17 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "official_paper_q18_18", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 18, "subject": "Physics", "topic": "sign of work and angle between force and displacement", "question": "Work done is positive if angle is:", "options": ["0° < θ < 90°", "0° < θ < 180°", "90° < θ < 270°", "None of these"], "correctIndex": 0, "explanation": "Work done W = F·d = Fd cosθ is positive when cosθ > 0, i.e., when the\n        angle between force and displacement is acute (0° < θ < 90°). For\n        obtuse angles the cosine is negative and work is negative.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 18, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2025 Q#18 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "official_paper_q19_19", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 19, "subject": "Physics", "topic": "electric potential of point charge", "question": "The electric potential at a distance r is given by the formula:", "options": ["V = kq/r", "1/4πε0qr", "Ed", "Ir"], "correctIndex": 0, "explanation": "The electric potential due to a point charge q at distance r in free\n        space is V = k q / r where k = 1/(4πε0). This is the standard expression\n        for potential around a point charge.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 19, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2025 Q#19 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "official_paper_q20_20", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 20, "subject": "Physics", "topic": "materials that are semiconductors", "question": "Which of the following act as a semiconductor?", "options": ["Iron", "Silicon", "Zinc", "Tungsten"], "correctIndex": 1, "explanation": "Silicon is a well-known semiconductor with an intermediate band\n        structure that allows controlled conduction, unlike metals such as iron,\n        zinc or tungsten which are conductors. Silicon's electrical properties\n        make it the primary semiconductor material.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 20, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "NUMS 2025 Q#20 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2025"}, {"id": "official_paper_q21_21", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 21, "subject": "Physics", "topic": "temperature coefficient of resistance definition", "question": "The fraction change in resistance per kelvin is:", "options": ["Coefficient of conductivity", "Temperature coefficient of resistance", "Coefficient of conductance", "Coefficient of resistivity"], "correctIndex": 1, "explanation": "The fractional change in resistance per degree kelvin is defined as the\n        temperature coefficient of resistance, which quantifies how resistance\n        varies with temperature. The other choices name different, unrelated\n        coefficients.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 21, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "NUMS 2025 Q#21 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2025"}, {"id": "official_paper_q22_22", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 22, "subject": "Physics", "topic": "bohr quantization of angular momentum", "question": "Quantized momentum was explained by:", "options": ["Einstein", "Bohr", "de-Broglie", "Rutherford"], "correctIndex": 1, "explanation": "Bohr's model introduced quantization of angular momentum for electrons\n        in atoms (L = nħ), explaining discrete energy levels and quantized\n        momentum in orbital motion. de Broglie proposed matter waves, but the\n        specific historical attribution for quantized orbital momentum belongs\n        to Bohr.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 22, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2025 Q#22 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "official_paper_q23_23", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 23, "subject": "Physics", "topic": "induced emf zero conditions", "question": "EMF induced is zero when plane of coil is:", "options": ["Perpendicular to B", "Parallel to B", "Antiparallel", "None of these"], "correctIndex": 0, "explanation": "For a rotating coil the magnetic flux Φ = BA cosθ (θ is angle between\n        coil normal and B) and emf = -dΦ/dt = BAω sinθ, so emf is zero when θ =\n        0 or π, i.e. when the plane of the coil is perpendicular to the magnetic\n        field. At those instants the flux is extremal and its time derivative\n        vanishes.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 23, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2025 Q#23 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "official_paper_q24_24", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 24, "subject": "Physics", "topic": "atomic line spectra", "question": "The spectra obtained by absorption or emission of radiation by atoms of\n      the gas:", "options": ["Atomic spectra", "Molecular spectra", "Band spectra", "Continuous spectra"], "correctIndex": 0, "explanation": "Absorption or emission by isolated atoms produces discrete lines because\n        electrons make quantized transitions between atomic energy levels; this\n        is called atomic (line) spectra. Molecular spectra produce band\n        structure and solids/continua give continuous spectra.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 24, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2025 Q#24 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "official_paper_q25_25", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 25, "subject": "Physics", "topic": "interference of waves", "question": "Two waves identical traveling in the same medium are superposed:", "options": ["Interference", "Diffraction", "Reflection", "Refraction"], "correctIndex": 0, "explanation": "When two (coherent) waves of the same frequency superpose in the same\n        medium their amplitudes add and produce regions of reinforcement or\n        cancellation; this phenomenon is interference. Diffraction and\n        refraction are different wave phenomena involving spreading and\n        speed-change respectively.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 25, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "NUMS 2025 Q#25 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2025"}, {"id": "official_paper_q26_26", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 26, "subject": "Physics", "topic": "work by centripetal force", "question": "The work done by centripetal force is:", "options": ["Maximum", "Minimum", "Zero", "Negative"], "correctIndex": 2, "explanation": "Centripetal force is always perpendicular to the instantaneous\n        displacement (it points radially while motion is tangential), so the\n        scalar product F·ds is zero and no work is done by the centripetal\n        force. Thus the work done is zero at all times in uniform circular\n        motion.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 26, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2025 Q#26 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "official_paper_q27_27", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 27, "subject": "Physics", "topic": "specific heat capacity comparison", "question": "Which of the following has highest specific heat capacity?", "options": ["Copper", "Iron", "Water", "Glass"], "correctIndex": 2, "explanation": "Water has a much higher specific heat capacity than common solids like\n        copper, iron or glass because of hydrogen bonding and its molecular\n        structure, so it stores more heat per unit mass per degree of\n        temperature change. Therefore water has the highest specific heat among\n        the given choices.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 27, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "NUMS 2025 Q#27 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2025"}, {"id": "official_paper_q28_28", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 28, "subject": "Physics", "topic": "photoelectric stopping potential", "question": "In photoelectric effect, stopping potential depends upon:", "options": ["Intensity of light", "Frequency of light", "Speed of light", "Amplitude of light"], "correctIndex": 1, "explanation": "In the photoelectric effect the maximum kinetic energy of emitted\n        electrons is Kmax = hν − φ, so the stopping potential (which balances\n        Kmax) depends on the frequency ν of the incident light, not on\n        intensity. Intensity affects the number of emitted electrons but not\n        their maximum energy.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 28, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2025 Q#28 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "official_paper_q29_29", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 29, "subject": "Physics", "topic": "lens power dioptre", "question": "Power of a lens is measured in:", "options": ["Meter", "Dioptre", "Candela", "Watt"], "correctIndex": 1, "explanation": "Optical power of a lens is defined as the reciprocal of its focal length\n        in metres and is measured in dioptres (D = m−1). Because geometric\n        optics topics (lens power) were removed from the current syllabus, this\n        item is classified outside-current-syllabus.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 29, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2025 Q#29 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "official_paper_q30_30", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 30, "subject": "Physics", "topic": "magnetic flux unit", "question": "The SI unit of magnetic flux is:", "options": ["Tesla", "Weber", "Henry", "Farad"], "correctIndex": 1, "explanation": "The SI unit of magnetic flux is the weber (Wb), which equals one\n        tesla·square metre (T·m2). Tesla is the unit of magnetic flux density,\n        not flux itself.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 30, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "NUMS 2025 Q#30 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2025"}, {"id": "official_paper_q31_31", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 31, "subject": "Physics", "topic": "half life decay fraction", "question": "Half-life of a radioactive element is 10 days. After 30 days, fraction\n      remaining is:", "options": ["1/2", "1/4", "1/8", "1/16"], "correctIndex": 2, "explanation": "Each 10-day half‑life reduces the sample by a factor of 1/2. After 30\n        days (three half‑lives) the remaining fraction is (1/2)^3 = 1/8.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 31, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "NUMS 2025 Q#31 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2025"}, {"id": "official_paper_q32_32", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 32, "subject": "Physics", "topic": "polarization and longitudinal waves", "question": "Which type of wave cannot be polarized?", "options": ["Radio waves", "Light waves", "Sound waves", "X-rays"], "correctIndex": 2, "explanation": "Polarization is a property of transverse waves (it selects oscillation\n        directions perpendicular to propagation); sound in air is a longitudinal\n        wave (oscillations parallel to propagation) and therefore cannot be\n        polarized. Radio, light and X‑rays are transverse and can be polarized.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 32, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "NUMS 2025 Q#32 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2025"}, {"id": "official_paper_q33_33", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 33, "subject": "Physics", "topic": "energy stored in capacitor", "question": "The energy stored in a capacitor is:", "options": ["QV", "QV/2", "Q2V", "2QV"], "correctIndex": 1, "explanation": "The work required to charge a capacitor to charge Q and potential V is\n        the integral of pdq = (q/C)dq, giving energy = (1/2)QV (equivalently 1/2\n        CV^2 or Q^2/(2C)). Hence the stored energy is QV/2.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 33, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2025 Q#33 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "official_paper_q34_34", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 34, "subject": "Physics", "topic": "polarization evidence for transverse nature", "question": "Which phenomenon proves the transverse nature of light?", "options": ["Interference", "Diffraction", "Polarization", "Refraction"], "correctIndex": 2, "explanation": "Polarization effects (selecting a direction of oscillation) are only\n        possible for transverse waves, so the observation of polarization for\n        light demonstrates that light waves are transverse. Interference and\n        diffraction do not by themselves prove transversality.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 34, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2025 Q#34 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "official_paper_q35_35", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 35, "subject": "Physics", "topic": "absolute zero temperature", "question": "Absolute zero temperature is equal to:", "options": ["0°C", "-173°C", "-273°C", "-373°C"], "correctIndex": 2, "explanation": "Absolute zero on the Celsius scale is −273.15°C (commonly quoted as\n        −273°C), the temperature at which thermodynamic motion ceases in the\n        ideal limit. The other values listed are not the zero of the Kelvin\n        scale.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 35, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "NUMS 2025 Q#35 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2025"}, {"id": "official_paper_q36_36", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 36, "subject": "Physics", "topic": "rectification definition", "question": "The process of converting AC into pulsating DC is called:", "options": ["Amplification", "Modulation", "Rectification", "Filtration"], "correctIndex": 2, "explanation": "Rectification is the process of converting alternating current (AC) into\n        pulsating direct current (DC), typically using diodes. Modulation and\n        amplification are different signal-processing operations; filtration\n        (filtering) smooths pulsating DC but does not perform the AC→DC\n        conversion itself.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 36, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "NUMS 2025 Q#36 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2025"}, {"id": "official_paper_q37_37", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 37, "subject": "Chemistry", "topic": "molecular crystals melting points", "question": "Most molecular crystals melt below:", "options": ["200°C", "280°C", "330°C", "480°C"], "correctIndex": 0, "explanation": "Molecular crystals are held together by relatively weak intermolecular\n        forces (van der Waals, dipole–dipole, hydrogen bonds) so they typically\n        melt at relatively low temperatures, commonly below about 200°C. Ionic\n        and covalent-network solids have much higher melting points.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 37, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2025 Q#37 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "official_paper_q38_38", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 38, "subject": "Chemistry", "topic": "proton to electron mass ratio", "question": "How much heavier is the H-atom as compared to electron?", "options": ["1937", "1737", "1837", "1637"], "correctIndex": 2, "explanation": "The mass of a hydrogen atom (approximately the proton mass) is about\n        1837 times the electron mass (more precisely ≈1836.15 for the proton\n        alone), so the hydrogen atom is roughly 1837 times heavier than the\n        electron. The other numeric choices are not correct.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 38, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2025 Q#38 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "official_paper_q39_39", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 39, "subject": "Chemistry", "topic": "ozone decomposition equilibrium constant", "question": "The value of equilibrium constant for the decomposition of ozone at 25°C:", "options": ["1055", "1065", "1025", "1050"], "correctIndex": 0, "explanation": "The equilibrium constant for the ozone decomposition reaction at 25°C is\n        extremely large, indicating the reaction strongly favors products; the\n        option written as 1055 corresponds to 10^55 in the printed paper and\n        matches that large value. Because the number is presented in compact\n        form in the options, the listed choice A is the match to the known large\n        equilibrium constant.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 39, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "NUMS 2025 Q#39 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2025"}, {"id": "official_paper_q40_40", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 40, "subject": "Chemistry", "topic": "rate law from orders", "question": "A reaction is first order with respect to A and third order with respect\n      to B, the rate equation is:", "options": ["Rate = K[A][B]2", "Rate = K[A]2[B]", "Rate = K[A][B]3", "Rate = K[A]"], "correctIndex": 2, "explanation": "If a reaction is first order in A and third order in B the rate law\n        multiplies those dependences, giving rate = k [A][B]^3. The total order\n        is the sum (1+3 = 4) but the functional form is the product of each\n        concentration raised to its order.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 40, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "NUMS 2025 Q#40 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2025"}, {"id": "official_paper_q41_41", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 41, "subject": "Chemistry", "topic": "determination of reaction order", "question": "For a reaction A → Product, if concentration of A is doubled, product\n      increases 4 times. The order of reaction will be:", "options": ["Zero", "1st", "2nd", "3rd"], "correctIndex": 2, "explanation": "If doubling the reactant concentration causes the rate (or product\n        formation) to increase by a factor of 4, then 2^n = 4 so n = 2; the\n        reaction is second order in that reactant. Zero and first orders would\n        give factors of 1 and 2 respectively.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 41, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "NUMS 2025 Q#41 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2025"}, {"id": "official_paper_q42_42", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 42, "subject": "Chemistry", "topic": "spontaneous process examples", "question": "Select the spontaneous reaction from the following:", "options": ["Reaction of nitrogen and oxygen", "Emission of α-particles from polonium", "Thermal decomposition of marble", "Burning of paper"], "correctIndex": 1, "explanation": "Emission of α‑particles from polonium is a nuclear decay process that\n        occurs spontaneously without external input, whereas the other listed\n        transformations are chemical processes that require activation or\n        specific conditions. Radioactive emissions are therefore the clear\n        example of an inherently spontaneous event.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 42, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2025 Q#42 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "official_paper_q43_43", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 43, "subject": "Chemistry", "topic": "combustion exothermic example", "question": "Select the exothermic reaction among the following:", "options": ["Thermal composition of P2O5", "Formation of atmospheric nitric oxide", "Burning of methane", "Sublimation of dry ice"], "correctIndex": 2, "explanation": "Burning (combustion) of methane is an exothermic reaction that releases\n        heat as C–H bonds are converted into stronger C=O and O–H bonds in CO2\n        and H2O, so it gives off energy. The other options involve endothermic\n        or non‑combustion processes.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 43, "syllabusUnit": "Unit 4: Chemical Energetics", "pmdcTopic": "Enthalpy Changes, Hess's Law & Standard Heats of Reaction", "textbookCitation": "PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6", "citationString": "NUMS 2025 Q#43 | Unit 4: Chemical Energetics | PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6"}, "year": "2025"}, {"id": "official_paper_q44_44", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 44, "subject": "Chemistry", "topic": "oxidation state calculation", "question": "The oxidation number of Cl in HClO2 is:", "options": ["+1", "+3", "+5", "+7"], "correctIndex": 1, "explanation": "Assigning oxidation numbers in HClO2: H is +1 and each O is −2 so total\n        from O is −4; to make the molecule neutral the Cl must be +3. The other\n        listed oxidation states do not balance the overall charge.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 44, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "NUMS 2025 Q#44 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2025"}, {"id": "official_paper_q45_45", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 45, "subject": "Chemistry", "topic": "molecular orbital bond order", "question": "Bond order is equal to:", "options": ["Difference between number of bonding electrons and antibonding\n          electrons", "The sum of number of bonding electrons and antibonding\n          electrons", "Half of the difference between number of bonding electrons and\n          antibonding electrons", "Quarter of the difference between number of bonding electrons and\n          antibonding electrons"], "correctIndex": 2, "explanation": "Bond order in molecular orbital theory is defined as one-half the\n        difference between the number of bonding electrons and antibonding\n        electrons: (Nbonding − Nantibonding)/2. This quantifies the net bonding\n        electron pairs and predicts bond strength and multiplicity.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 45, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2025 Q#45 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2025"}, {"id": "official_paper_q46_46", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 46, "subject": "Chemistry", "topic": "molecular polarity co2", "question": "Which of the following molecule has non-polar covalent bond?", "options": ["Methyl chloride", "Methanol", "Carbon dioxide", "Tetrachloromethane"], "correctIndex": 2, "explanation": "Although each C=O bond is polar, CO2 is linear so the two bond dipoles\n        are equal and opposite and cancel, making the overall molecule nonpolar.\n        That is why CO2 is listed here as a non‑polar molecule (symmetry cancels\n        the bond dipoles).", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 46, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "NUMS 2025 Q#46 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2025"}, {"id": "official_paper_q47_47", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 47, "subject": "Chemistry", "topic": "dehydration of tertiary alcohols", "question": "Which of the following alcohols will give oily layer upon heating?", "options": ["3-Methyl-2-butanol", "2-Methyl-2-butanol", "2-Butanol", "Ethyl alcohol"], "correctIndex": 1, "explanation": "Tertiary alcohols such as 2-methyl-2-butanol dehydrate readily on\n        heating (usually with acid) to give alkenes, which form an oily layer.\n        Primary and secondary alcohols are less prone to simple dehydration\n        under mild heating, and ethanol (a primary alcohol) does not give an\n        oily layer under the same conditions.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 47, "syllabusUnit": "Unit 10: Alkyl Halides, Alcohols & Phenols", "pmdcTopic": "Nucleophilic Substitution, Elimination Reactions & Phenol Acidity", "textbookCitation": "PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19", "citationString": "NUMS 2025 Q#47 | Unit 10: Alkyl Halides, Alcohols & Phenols | PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19"}, "year": "2025"}, {"id": "official_paper_q48_48", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 48, "subject": "Chemistry", "topic": "formalin composition", "question": "Formalin is a mixture of:", "options": ["40% HCHO, 8% CH3OH, 52% H2O", "40% CH3CHO, 8% CH3OH, 50% H2O", "40% CH3CHO, 8% C2H5OH, 50% H2O", "45% HCHO, 8% C2H5OH, 50% H2O"], "correctIndex": 0, "explanation": "Formalin is the commercial aqueous solution of formaldehyde and\n        typically contains about 37–40% formaldehyde, with methanol (around 8%)\n        added as a stabilizer and the remainder water. The given composition\n        (40% HCHO, 8% CH3OH, 52% H2O) matches the standard formulation.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 48, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2025 Q#48 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "official_paper_q49_49", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 49, "subject": "Chemistry", "topic": "acid catalyzed polymerization of aldehydes", "question": "Polymerization of HCHO and CH3CHO occurs in the presence of:", "options": ["Conc. H2SO4", "Dil. H2SO4", "Conc. H2CO3", "Dil. H2CO3"], "correctIndex": 0, "explanation": "Concentrated sulfuric acid acts as a strong acid catalyst and\n        dehydrating agent, promoting polymerization (or condensation) of\n        aldehydes like formaldehyde and acetaldehyde. Dilute acid is less\n        effective, and carbonic acid options are incorrect in this context.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 49, "syllabusUnit": "Unit 11: Carbonyl Compounds (Aldehydes & Ketones)", "pmdcTopic": "Carbonyl Chemistry, Addition Reactions & Tests for Carbonyls", "textbookCitation": "PTB Chemistry XII Ch 12 (Aldehydes and Ketones); Federal Chemistry XII Ch 20", "citationString": "NUMS 2025 Q#49 | Unit 11: Carbonyl Compounds (Aldehydes & Ketones) | PTB Chemistry XII Ch 12 (Aldehydes and Ketones); Federal Chemistry XII Ch 20"}, "year": "2025"}, {"id": "official_paper_q50_50", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 50, "subject": "Chemistry", "topic": "hydrogen bonding and boiling point", "question": "The boiling point of carboxylic acids are relatively high due to:", "options": ["Increased molecular mass", "Intermolecular carbon bonding", "Intermolecular oxygen bonding", "Intermolecular hydrogen bonding"], "correctIndex": 3, "explanation": "Carboxylic acids form strong intermolecular hydrogen bonds, often\n        pairing into dimers, which greatly increases the effective molecular\n        association and raises their boiling points. This hydrogen bonding\n        effect is the main reason their boiling points are higher than\n        comparable non-hydrogen-bonding molecules.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 50, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2025 Q#50 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "official_paper_q51_51", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 51, "subject": "Chemistry", "topic": "acid carbonate reaction", "question": "Carboxylic acid reacts with metal carbonate. The colorless gas evolved is:", "options": ["H2", "O2", "CO2", "CO"], "correctIndex": 2, "explanation": "When a carboxylic acid reacts with a metal carbonate the acid is\n        neutralized and carbon dioxide gas is evolved (CO2), along with water\n        and a salt. Hydrogen gas or carbon monoxide are not produced in the\n        acid–carbonate reaction.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 51, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2025 Q#51 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "official_paper_q52_52", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 52, "subject": "Chemistry", "topic": "fischer esterification", "question": "Which of the following compound will react with 2,2-dimethyl propanoic\n      acid to produce ester?", "options": ["Ethanoic acid", "Propane", "Ethanol", "Propanone"], "correctIndex": 2, "explanation": "Esterification of a carboxylic acid requires an alcohol; ethanol will\n        react with 2,2-dimethylpropanoic acid under acidic conditions to form\n        the corresponding ethyl ester. Other choices like propane or propanone\n        are not alcohols and cannot form esters by simple esterification.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 52, "syllabusUnit": "Unit 12: Carboxylic Acids & Derivatives", "pmdcTopic": "Acidity of Carboxylic Acids & Acyl Derivatives", "textbookCitation": "PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21", "citationString": "NUMS 2025 Q#52 | Unit 12: Carboxylic Acids & Derivatives | PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21"}, "year": "2025"}, {"id": "official_paper_q53_53", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 53, "subject": "Chemistry", "topic": "classification and abundance of proteins", "question": "The most abundant protein in animal kingdom forming 25–35% of body\n      proteins is/are:", "options": ["Derived proteins", "Simple proteins", "Compound proteins", "Conjugated proteins"], "correctIndex": 1, "explanation": "Collagen is the single most abundant protein in animals (about 25–35% of\n        total protein) and is classified as a simple protein because its\n        composition is solely amino acids (no prosthetic groups). Thus the\n        correct general class from the options given is 'simple proteins.'", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 53, "syllabusUnit": "Unit 13: Macromolecules & Industrial Chemistry", "pmdcTopic": "Synthetic & Natural Polymers, Amino Acids and Proteins", "textbookCitation": "PTB Chemistry XII Ch 14 (Macromolecules); Federal Chemistry XII Ch 22", "citationString": "NUMS 2025 Q#53 | Unit 13: Macromolecules & Industrial Chemistry | PTB Chemistry XII Ch 14 (Macromolecules); Federal Chemistry XII Ch 22"}, "year": "2025"}, {"id": "official_paper_q54_54", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 54, "subject": "Chemistry", "topic": "collagen in connective tissue", "question": "Protein present in connective tissues of human body is:", "options": ["Phosphoprotein", "Collagen", "Lecithin", "Cholesterol"], "correctIndex": 1, "explanation": "Collagen is the structural fibrous protein that predominates in\n        connective tissues (tendons, ligaments, skin, bone matrix). The other\n        options listed are not the main structural protein of connective tissue.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 54, "syllabusUnit": "Unit 13: Macromolecules & Industrial Chemistry", "pmdcTopic": "Synthetic & Natural Polymers, Amino Acids and Proteins", "textbookCitation": "PTB Chemistry XII Ch 14 (Macromolecules); Federal Chemistry XII Ch 22", "citationString": "NUMS 2025 Q#54 | Unit 13: Macromolecules & Industrial Chemistry | PTB Chemistry XII Ch 14 (Macromolecules); Federal Chemistry XII Ch 22"}, "year": "2025"}, {"id": "official_paper_q55_55", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 55, "subject": "Chemistry", "topic": "iron storage ferritin", "question": "In human body Ferritin is used to store:", "options": ["P", "Ca", "Fe", "Zn"], "correctIndex": 2, "explanation": "Ferritin is the cellular iron-storage protein that sequesters iron in a\n        soluble, non-toxic form and releases it as needed; its role is\n        specifically to store Fe. The other elements listed are not stored by\n        ferritin.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 55, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2025 Q#55 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "official_paper_q56_56", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 56, "subject": "Chemistry", "topic": "ceruloplasmin and copper transport", "question": "In human body Ceruloplasmin acts as a carrier of:", "options": ["O2", "Zn", "Cu", "Fe"], "correctIndex": 2, "explanation": "Ceruloplasmin is a copper-containing plasma protein that carries and\n        helps mobilize copper in the bloodstream, so it functions as a copper\n        carrier. It does not carry oxygen or iron as its primary physiologic\n        role.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 56, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2025 Q#56 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "official_paper_q57_57", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 57, "subject": "Chemistry", "topic": "periodic trend ionization energy", "question": "Predict the element with lowest ionization energy:", "options": ["Mg", "Ar", "Si", "P"], "correctIndex": 0, "explanation": "Ionization energy increases across a period; among Mg, Si, P, and Ar\n        (same period), magnesium is furthest left and therefore has the lowest\n        first ionization energy. Argon, being a noble gas, has the highest\n        ionization energy of the listed elements.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 57, "syllabusUnit": "Unit 8: Inorganic Chemistry & Periodicity", "pmdcTopic": "Periodic Trends, Group Chemistry & Transition Elements", "textbookCitation": "PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16", "citationString": "NUMS 2025 Q#57 | Unit 8: Inorganic Chemistry & Periodicity | PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16"}, "year": "2025"}, {"id": "official_paper_q58_58", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 58, "subject": "Chemistry", "topic": "alkaline earth atomic radius trend", "question": "Select the group II element which has the highest atomic radius?", "options": ["Be", "Ca", "Ba", "Sr"], "correctIndex": 2, "explanation": "Within group II (alkaline earth metals) atomic radius increases down the\n        group due to addition of electron shells, so barium (Ba) has the largest\n        atomic radius among the options. Beryllium is the smallest because it is\n        at the top of the group.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 58, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2025 Q#58 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2025"}, {"id": "official_paper_q59_59", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 59, "subject": "Chemistry", "topic": "alkali metals boiling point trend", "question": "Which of the following element has least boiling point?", "options": ["Li", "Na", "K", "Cs"], "correctIndex": 3, "explanation": "For the alkali metals, melting and boiling points generally decrease\n        down the group; cesium (Cs) therefore has the lowest boiling point among\n        Li, Na, K, and Cs. Lithium at the top has the highest boiling point of\n        the group members listed.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 59, "syllabusUnit": "Unit 8: Inorganic Chemistry & Periodicity", "pmdcTopic": "Periodic Trends, Group Chemistry & Transition Elements", "textbookCitation": "PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16", "citationString": "NUMS 2025 Q#59 | Unit 8: Inorganic Chemistry & Periodicity | PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16"}, "year": "2025"}, {"id": "official_paper_q60_60", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 60, "subject": "Chemistry", "topic": "position isomerism in ketones", "question": "pentanone and 3-pentanone are examples of:", "options": ["Metamers", "Functional group isomers", "Tautomerism", "Position isomers"], "correctIndex": 3, "explanation": "2-Pentanone and 3-pentanone have the same molecular formula and the same\n        functional group (ketone) but differ in the position of the carbonyl\n        along the chain, making them position isomers. They are not functional\n        group isomers, tautomers, or metamers in this case.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 60, "syllabusUnit": "Unit 11: Carbonyl Compounds (Aldehydes & Ketones)", "pmdcTopic": "Carbonyl Chemistry, Addition Reactions & Tests for Carbonyls", "textbookCitation": "PTB Chemistry XII Ch 12 (Aldehydes and Ketones); Federal Chemistry XII Ch 20", "citationString": "NUMS 2025 Q#60 | Unit 11: Carbonyl Compounds (Aldehydes & Ketones) | PTB Chemistry XII Ch 12 (Aldehydes and Ketones); Federal Chemistry XII Ch 20"}, "year": "2025"}, {"id": "official_paper_q61_61", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 61, "subject": "Chemistry", "topic": "electrophile in sulfonation", "question": "Which of the following is an electrophile in sulphonation?", "options": ["SO3H", "SO3", "SO2", "SO3+"], "correctIndex": 1, "explanation": "In aromatic sulfonation the active electrophile is sulfur trioxide\n        (SO3), which attacks the aromatic ring to form the sigma-complex; proton\n        transfer and subsequent steps give the sulfonic acid. The positively\n        charged SO3+ notation is not a standard depiction here, and SO2 or SO3H\n        are not the initial electrophile in the usual mechanism.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 61, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "NUMS 2025 Q#61 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2025"}, {"id": "official_paper_q62_62", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 62, "subject": "Chemistry", "topic": "addition of hbr to alkynes", "question": "Acetylene reacts with hydrogen bromide to form:", "options": ["2,2-Dibromoethane", "1,1-Dibromoethane", "1,2-Dibromoethane", "1,1,2,2-Tetrabromoethane"], "correctIndex": 1, "explanation": "Addition of two equivalents of HBr to acetylene proceeds by Markovnikov\n        addition, ultimately yielding 1,1-dibromoethane (both bromine atoms on\n        the same carbon). The other listed products correspond to different\n        regiochemistry or to partial addition products.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 62, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "NUMS 2025 Q#62 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2025"}, {"id": "official_paper_q63_63", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 63, "subject": "Chemistry", "topic": "relative reactivity of hydrocarbons", "question": "Generally the decreasing order of reactivity is:", "options": ["Alkane > Alkynes > Alkene", "Alkene < Alkynes < Alkanes", "Alkene > Alkynes > Alkanes", "Alkynes < Alkanes < Alkene"], "correctIndex": 2, "explanation": "Alkenes are generally more reactive than alkynes toward electrophilic\n        addition because the sp2 carbon–carbon double bond is more readily\n        attacked than the stronger sp carbon–carbon triple bond; alkanes are\n        least reactive. Thus the order is alkene > alkyne > alkane.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 63, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "NUMS 2025 Q#63 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2025"}, {"id": "official_paper_q64_64", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 64, "subject": "Chemistry", "topic": "sn1 mechanism and carbocation planarity", "question": "Racemic mixture formed in SN1 reaction is due to presence of empty:", "options": ["s-orbital", "p-orbital", "sp3-orbital", "sp2-orbital"], "correctIndex": 1, "explanation": "SN1 reactions proceed via a planar, sp2-hybridized carbocation\n        intermediate with an empty p-orbital; nucleophiles can attack from\n        either face, giving a racemic mixture when the centre is chiral. This\n        planar p-orbital is the reason for loss of stereochemical retention in\n        SN1 reactions.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 64, "syllabusUnit": "Unit 10: Alkyl Halides, Alcohols & Phenols", "pmdcTopic": "Nucleophilic Substitution, Elimination Reactions & Phenol Acidity", "textbookCitation": "PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19", "citationString": "NUMS 2025 Q#64 | Unit 10: Alkyl Halides, Alcohols & Phenols | PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19"}, "year": "2025"}, {"id": "official_paper_q65_65", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 65, "subject": "Chemistry", "topic": "c o bond cleavage reactivity in alcohols", "question": "The order of reactivity of alcohol with respect to cleavage of C–O bond:", "options": ["Tertiary > Secondary > Primary", "Primary > Tertiary > Secondary", "Secondary > Tertiary > Primary", "Tertiary < Secondary < Primary"], "correctIndex": 0, "explanation": "Cleavage of the C–O bond in alcohols (to give a carbocation or\n        substitute) is easier for more substituted carbons because the resulting\n        carbocation is more stabilized, so reactivity follows tertiary >\n        secondary > primary. Primary alcohols resist C–O bond cleavage\n        because primary carbocations are least stable.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 65, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "NUMS 2025 Q#65 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2025"}, {"id": "official_paper_q66_66", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 66, "subject": "Chemistry", "topic": "stoichiometry water molecule count", "question": "NaOH + H2SO4 → Na2SO4 + H2O. When 40g of NaOH reacts with 49g of H2SO4,\n      the number of water molecules produced are:", "options": ["6.02 × 1023", "6.02 × 1024", "1.2044 × 1023", "1.204 × 1024"], "correctIndex": 0, "explanation": "40 g NaOH is 1.00 mol and 49 g H2SO4 is 0.50 mol; these react\n        stoichiometrically (2 NaOH : 1 H2SO4) to produce 1.00 mol H2O. One mole\n        of water contains Avogadro's number ≈ 6.02 × 10^23 molecules, so option\n        A is correct.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 66, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2025 Q#66 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "official_paper_q67_67", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 67, "subject": "Chemistry", "topic": "subshell electron capacity", "question": "The number of electrons in a subshell can be calculated by the formula:", "options": ["2l + 1", "2l + 2", "2(2 + l)", "2(2l + 1)"], "correctIndex": 3, "explanation": "A subshell has (2l + 1) orbitals and each orbital can hold 2 electrons,\n        so the total electron capacity of a subshell equals 2(2l + 1). The other\n        formulas given do not account correctly for both orbital count and spin\n        occupancy.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 67, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2025 Q#67 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2025"}, {"id": "official_paper_q68_68", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 68, "subject": "Chemistry", "topic": "aufbau filling order period 6", "question": "When 5d orbital is complete, the entering electron goes into:", "options": ["6s", "6p", "6d", "6f"], "correctIndex": 1, "explanation": "After the 5d subshell is filled, the next available higher-energy\n        orbitals to receive electrons in period 6 are the 6p orbitals, so the\n        following electron enters 6p. Options like 6s or 6d are not the next\n        orbitals after a completed 5d in the Aufbau filling sequence for the\n        elements in that region.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 68, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2025 Q#68 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2025"}, {"id": "official_paper_q69_69", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 69, "subject": "Chemistry", "topic": "average translational kinetic energy", "question": "Which of the following relationship is correct for kinetic energy of\n      gases?", "options": ["K.E = 2RT/3NA", "K.E = 3RT/2NA", "K.E = 2mNT/2R", "K.E = 2NA/3RT"], "correctIndex": 1, "explanation": "The average translational kinetic energy per molecule of an ideal gas is\n        (3/2)kT, and since Boltzmann's constant k = R/NA this can be written as\n        3RT/(2NA). Thus the expression K.E = 3RT/2NA is correct.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 69, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2025 Q#69 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "official_paper_q70_70", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 70, "subject": "Chemistry", "topic": "plasma state", "question": "The fourth state of matter is:", "options": ["Solid", "Liquid", "Gaseous liquid", "Plasma"], "correctIndex": 3, "explanation": "Plasma is commonly described as the fourth state of matter, consisting\n        of an ionized gas of free electrons and ions distinct from the neutral\n        gaseous, liquid, and solid states. The other listed options are ordinary\n        states and not the fourth state.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 70, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2025 Q#70 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "official_paper_q71_71", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 71, "subject": "Chemistry", "topic": "factors affecting evaporation", "question": "Which factor does not affect the rate of evaporation?", "options": ["Amount of liquid", "Surface area", "Temperature", "Inter-molecular forces"], "correctIndex": 0, "explanation": "The rate of evaporation depends on surface area, temperature, and\n        intermolecular forces because these determine how many molecules can\n        escape into vapour. The total amount of liquid does not change the rate\n        per unit surface area (until the container geometry changes), so amount\n        of liquid is not a direct factor.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 71, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "NUMS 2025 Q#71 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2025"}, {"id": "official_paper_q72_72", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 72, "subject": "Chemistry", "topic": "intermolecular forces and boiling point", "question": "Which of the following is responsible for the low boiling point of diethyl\n      ether as compared to water?", "options": ["Weak intermolecular forces", "High surface tension", "Low vapour pressure", "High vapour pressure"], "correctIndex": 0, "explanation": "Diethyl ether has weaker intermolecular attractions (no strong hydrogen\n        bonds) compared with water, which has extensive hydrogen bonding; weaker\n        attractions require less energy to break, so ether has a lower boiling\n        point. High vapour pressure or surface tension are consequences, not the\n        primary reason here.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 72, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2025 Q#72 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "official_paper_q73_73", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 73, "subject": "Chemistry", "topic": "hydrogen bonding criteria", "question": "Hydrogen bonding does not exist in:", "options": ["Proteins", "Alcohols", "Liq HF", "SiH4"], "correctIndex": 3, "explanation": "Hydrogen bonding requires H bonded to a strongly electronegative atom\n        (F, O or N). In SiH4 the hydrogen is bonded to silicon (not sufficiently\n        electronegative), so it cannot form hydrogen bonds; the other choices\n        (proteins, alcohols, liquid HF) do have H-bonding.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 73, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2025 Q#73 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "official_paper_q74_74", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 74, "subject": "Chemistry", "topic": "factors affecting lattice energy", "question": "The factor that affects the lattice energy is:", "options": ["Charge to size ratio", "Shielding effect", "Crystal structure", "Atomic radius"], "correctIndex": 0, "explanation": "Lattice energy is largely determined by the charges on the ions and\n        their sizes - commonly expressed as the charge-to-size ratio; higher\n        charges and smaller ionic radii give larger lattice energies. While\n        atomic radius and crystal structure play roles, the charge/size ratio is\n        the primary controlling factor.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 74, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2025 Q#74 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "official_paper_q75_75", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 75, "subject": "Chemistry", "topic": "crystal lattice determination", "question": "The shape of the crystal lattice depends upon:", "options": ["Size of particles", "Nature of particles", "Arrangement of particles", "Size of unit cell"], "correctIndex": 2, "explanation": "The macroscopic shape of a crystal lattice is determined by how\n        particles are arranged in space (the repeating pattern of the unit\n        cells). Size of particles or unit cell dimensions influence scale, but\n        the geometric arrangement dictates the lattice shape.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 75, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2025 Q#75 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "official_paper_q76_76", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 76, "subject": "English", "topic": "articles with animal names", "question": "Fill in the correct articles: _____ female lion is called _____ lioness.\n      She has no mane.", "options": ["A, the", "The, a", "The, the", "A, a"], "correctIndex": 1, "explanation": "We use the definite article 'the' before a noun phrase that identifies a\n        particular kind (the female lion), and use the indefinite 'a' when\n        naming a single element of that kind (a lioness). Thus 'The female lion\n        is called a lioness' is correct.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 76, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2025 Q#76 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2025"}, {"id": "official_paper_q77_77", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 77, "subject": "English", "topic": "clause types noun clause", "question": "'Whatever you order for dinner' is fine with me. The underlined part is:", "options": ["Noun clause", "Adjective clause", "Adverb clause", "Independent clause"], "correctIndex": 0, "explanation": "'Whatever you order for dinner' functions as a single unit naming a\n        thing or choice and serves as the subject/object in the sentence, so it\n        is a noun clause. It cannot be an adjective or adverb clause because it\n        does not modify a noun or verb in that way.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 77, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "NUMS 2025 Q#77 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2025"}, {"id": "official_paper_q78_78", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 78, "subject": "English", "topic": "sentence structure simple complex", "question": "After midnight, the ghost will come out of the haunted attic to scare the\n      people. The sentence is:", "options": ["Simple", "Compound", "Complex", "Compound-Complex"], "correctIndex": 0, "explanation": "The sentence contains one independent clause with a single subject and\n        predicate (though it begins with a prepositional phrase), so it is a\n        simple sentence. There are no subordinate or additional independent\n        clauses to make it compound or complex.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 78, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "NUMS 2025 Q#78 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2025"}, {"id": "official_paper_q79_79", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 79, "subject": "English", "topic": "verbs after suggest", "question": "I suggest that you _____ visit a doctor.", "options": ["Must", "Should", "Ought to", "Have to"], "correctIndex": 1, "explanation": "After 'I suggest that you...' the appropriate modal is 'should' among\n        the given choices (or the bare subjunctive 'you visit'). 'Must' and\n        'have to' are stronger obligations, and 'ought to' is possible but less\n        natural here than 'should' in this context.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 79, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2025 Q#79 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2025"}, {"id": "official_paper_q80_80", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 80, "subject": "English", "topic": "inversion in third conditional", "question": "Choose the correctly structured sentence.", "options": ["Had he been there, he would see us.", "Had he been there, he would had seen us.", "Had he been there, he would have seen us.", "Had he had been there, he would have seen us."], "correctIndex": 2, "explanation": "This is an example of inversion in a third conditional: 'Had he been\n        there' is the inverted form of 'If he had been there,' and the correct\n        main clause is 'he would have seen us.' Options with incorrect auxiliary\n        forms are ungrammatical.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 80, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "NUMS 2025 Q#80 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2025"}, {"id": "official_paper_q81_81", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 81, "subject": "English", "topic": "relative clauses and punctuation", "question": "Identify the sentence with correct structure.", "options": ["We noticed the boy, walking down the street.", "We noticed, the boy walk down the, street.", "We noticed, that the boy was walking down the street.", "We noticed the boy, who was walking down the street."], "correctIndex": 3, "explanation": "Option D correctly uses a relative clause ('who was walking down the\n        street') to give additional information about 'the boy.' The other\n        choices either misuse commas with participial phrases or insert\n        unnecessary commas that break sentence structure.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 81, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "NUMS 2025 Q#81 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2025"}, {"id": "official_paper_q82_82", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 82, "subject": "English", "topic": "articles the a an", "question": "He circled _____ whole world on his ship and on _____ island he\n      encountered _____ fierce giant.", "options": ["the, an, the", "the, a, a", "the, an, a", "the, an, an"], "correctIndex": 2, "explanation": "'The whole world' uses the definite article because it refers to a\n        unique, specific whole; 'an island' requires 'an' before a vowel sound;\n        and 'a fierce giant' uses the indefinite 'a' before a consonant sound.\n        Therefore 'the, an, a' is correct.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 82, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2025 Q#82 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2025"}, {"id": "official_paper_q83_83", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 83, "subject": "English", "topic": "adjective order", "question": "Choose the sentence with correct order of adjectives.", "options": ["I met, young two, beautiful, British girls at the airport.", "I met two beautiful, young, British girls at the airport.", "I met two, British, young, beautiful girls at the airport.", "I met two young, beautiful British girls at the airport."], "correctIndex": 3, "explanation": "Standard adjective order places number first, then age/other descriptive\n        adjectives, then origin before the noun; 'two young, beautiful British\n        girls' follows a natural, idiomatic sequence. The other options scramble\n        the conventional order or include unnecessary commas.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 83, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "NUMS 2025 Q#83 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2025"}, {"id": "official_paper_q84_84", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 84, "subject": "English", "topic": "clause functions object clause", "question": "Identify the underlined part of the sentence: I know you have already read\n      this book.", "options": ["Independent clause", "Adjective clause", "Adverb clause", "Noun clause"], "correctIndex": 3, "explanation": "In 'I know you have already read this book,' the underlined portion\n        functions as the object of 'know' and names a fact - that is the role of\n        a noun clause. It is not an adjective or adverb clause because it does\n        not modify another word.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 84, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "NUMS 2025 Q#84 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2025"}, {"id": "official_paper_q85_85", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 85, "subject": "English", "topic": "verb preposition collocations", "question": "Which of the following verbs takes the preposition 'from' with it?", "options": ["Abstain", "Accused", "Desirous", "Ignorant"], "correctIndex": 0, "explanation": "The verb 'abstain' normally takes the preposition 'from' (to abstain\n        from something). The other words listed are adjectives or verbs that\n        pair with different prepositions in standard usage.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 85, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2025 Q#85 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2025"}, {"id": "official_paper_q86_86", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 86, "subject": "English", "topic": "prepositions fixed phrases", "question": "Choose the correct preposition. One hour _____ glorious life is worth an\n      age without a name.", "options": ["In", "Of", "To", "With"], "correctIndex": 1, "explanation": "The idiomatic phrase is 'One hour of glorious life...' where 'of' links\n        the measure of time to the kind of life. Other prepositions ('in', 'to',\n        'with') do not form the correct, standard expression here.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 86, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2025 Q#86 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2025"}, {"id": "official_paper_q87_87", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 87, "subject": "English", "topic": "capitalization errors", "question": "Clive had been only a few months in the army when announced that peace had\n      been concluded between great britain and france. The sentence contains\n      errors of:", "options": ["Comma", "Comma and full stop", "Comma and capitalization", "Capitalization"], "correctIndex": 3, "explanation": "The sentence fails to capitalise country names ('great britain' and\n        'france'), so it contains errors of capitalization. While there are\n        other stylistic or missing-word issues, the option that correctly names\n        the error among the choices is capitalization.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 87, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "NUMS 2025 Q#87 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2025"}, {"id": "official_paper_q88_88", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 88, "subject": "Biology", "topic": "induced fit model", "question": "Induced fit model of enzyme activity suggests that an enzyme:", "options": ["Cannot modify its active sites", "Can bind to a single substrate", "Can catalyze related specific reaction", "Usually belongs to non-regulatory enzyme"], "correctIndex": 2, "explanation": "The induced-fit model describes the enzyme active site as flexible and\n        able to change shape to bind substrate(s); this flexibility can allow\n        closely related substrates to bind and be catalysed. Thus enzymes under\n        this model can catalyze related specific reactions rather than being\n        absolutely rigid for a single substrate.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 88, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2025 Q#88 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "official_paper_q89_89", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 89, "subject": "Biology", "topic": "cofactors for kinases mg2", "question": "Select the one which is used by hexokinase as an activator:", "options": ["Cu++", "Zn++", "Mg++", "Fe++"], "correctIndex": 2, "explanation": "Hexokinase (and many kinases) requires Mg2+ because ATP binds in the\n        Mg-ATP complex form; Mg2+ stabilizes negative charges and is essential\n        for catalytic activity. Other metal ions listed are not the\n        physiological activator for hexokinase.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 89, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2025 Q#89 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "official_paper_q90_90", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 90, "subject": "Biology", "topic": "enzyme substrate interactions", "question": "The linkage between substrate molecule and active site is:", "options": ["Ionic bonding", "Disulfide bonding", "Hydrogen bonding", "Covalent bonding"], "correctIndex": 2, "explanation": "Substrate binding to an enzyme's active site is primarily via\n        non-covalent interactions such as hydrogen bonds, ionic interactions and\n        van der Waals forces; hydrogen bonding is a common specific linkage.\n        Covalent bonding is less typical for ordinary reversible substrate\n        binding.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 90, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2025 Q#90 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "official_paper_q91_91", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 91, "subject": "Biology", "topic": "zymogen activation proteolytic activation", "question": "Activated pepsin in which polypeptide fragment is removed is an example\n      of:", "options": ["Apo-enzyme", "Holoenzyme", "Regulatory enzyme", "Non-regulatory enzyme"], "correctIndex": 3, "explanation": "Pepsin is produced as pepsinogen and activated by proteolytic removal of\n        a peptide segment - a form of irreversible covalent activation (zymogen\n        activation). This activation is not the typical reversible allosteric\n        regulation, so it fits the category of non-regulatory (i.e., not\n        allosterically regulated) enzyme behavior in the given classification.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 91, "syllabusUnit": "Unit 5: Human Physiology - Digestion & Nutrition", "pmdcTopic": "Human Digestive System & Absorption Mechanisms", "textbookCitation": "PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12", "citationString": "NUMS 2025 Q#91 | Unit 5: Human Physiology - Digestion & Nutrition | PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12"}, "year": "2025"}, {"id": "official_paper_q92_92", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 92, "subject": "Biology", "topic": "reversible inhibition mechanisms", "question": "Reversible inhibitors affect the enzyme catalyzed reaction by:", "options": ["Forming covalent bonds with active site", "Destroying the globular structure", "Forming weak linkages with enzymes", "Activating the catalytic sites"], "correctIndex": 2, "explanation": "Reversible inhibitors bind to enzymes via weak, non-covalent\n        interactions (hydrogen bonds, ionic interactions, van der Waals), so\n        their effects can be undone. Forming covalent bonds or destroying\n        protein structure would be irreversible and are not characteristic of\n        reversible inhibition.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 92, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2025 Q#92 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "official_paper_q93_93", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 93, "subject": "Biology", "topic": "enzyme optimum ph", "question": "What is the required medium for the maximum activity of the given enzymes?\n      (Lipase / Pepsin)", "options": ["Acidic / Basic", "Acidic / Acidic", "Basic / Acidic", "Basic / Basic"], "correctIndex": 2, "explanation": "Lipase (especially pancreatic/intestinal lipase) has optimal activity in\n        a neutral to basic environment, while pepsin is an acidic protease with\n        optimal activity in the stomach's low pH. Therefore the correct pairing\n        is basic for lipase and acidic for pepsin.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 93, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2025 Q#93 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "official_paper_q94_94", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 94, "subject": "Biology", "topic": "special creation vs evolution", "question": "What distinguishes the concept of special creation from concept of\n      evolution?", "options": ["Life is not the product of sudden creative act", "Unicellular prokaryotes might be the life ancestors", "Rely on inspiration and meditation for life origin", "Life results from innumerable changes"], "correctIndex": 2, "explanation": "The concept of special creation relies on supernatural explanation or\n        inspiration/meditation rather than naturalistic mechanisms, which is the\n        key distinction from evolution that invokes change over time by natural\n        processes. The other options describe features of evolutionary theory\n        rather than creationist views.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 94, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "NUMS 2025 Q#94 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2025"}, {"id": "official_paper_q95_95", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 95, "subject": "Biology", "topic": "lamarckism use and disuse", "question": "Which of the following idea is a part of Lamarckism?", "options": ["Use and disuse of organs", "Survival of the fittest", "Origin of species", "Variation"], "correctIndex": 0, "explanation": "Lamarckism includes the idea that organs used frequently become more\n        developed while disused organs atrophy - the ‘use and disuse’ principle.\n        Other choices (survival of the fittest, origin of species, variation)\n        are associated with Darwinian or general evolutionary concepts rather\n        than Lamarck’s mechanism.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 95, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2025 Q#95 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "official_paper_q96_96", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 96, "subject": "Biology", "topic": "homology structures", "question": "Choose the correct pair for homology?", "options": ["Wings of birds and wings of butterfly", "Forelimbs of birds and fins of whales", "Leaves of pines and cactus", "Gills of fish and lungs of humans"], "correctIndex": 1, "explanation": "Homologous structures share a common evolutionary origin but may have\n        different functions; bird forelimbs and whale fins are modified\n        forelimbs derived from the same ancestral limb. By contrast, bird wings\n        and insect wings are analogous (similar function but different origin).", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 96, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2025 Q#96 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "official_paper_q97_97", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 97, "subject": "Biology", "topic": "vertebrate evolution sequence", "question": "Which chronological sequence is correct among the classes of vertebrates\n      as evidence of evolution?", "options": ["Birds → fish → amphibians → reptiles", "Reptiles → birds → fishes → amphibians", "Fish → amphibians → reptiles → birds", "Amphibians → reptiles → birds → fish"], "correctIndex": 2, "explanation": "The fossil and evolutionary record shows vertebrates appearing in the\n        sequence fish → amphibians → reptiles → birds, reflecting adaptations\n        from aquatic to terrestrial life and later diversification. The other\n        orders do not match the major evolutionary transitions.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 97, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "NUMS 2025 Q#97 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2025"}, {"id": "official_paper_q98_98", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 98, "subject": "Biology", "topic": "genetic drift bottleneck", "question": "The reduction of population carrying a specific allele and genotype due to\n      natural disaster is called:", "options": ["Mutation", "Bottle neck effect", "Founder effect", "Speciation"], "correctIndex": 1, "explanation": "A bottleneck effect is a sharp reduction in population size due to a\n        disaster, which randomly reduces allele frequencies and genetic\n        diversity. Founder effect refers to a small group establishing a new\n        population, and mutation/speciation are different processes.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 98, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "NUMS 2025 Q#98 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "official_paper_q99_99", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 99, "subject": "Biology", "topic": "mutations and variation", "question": "Which of the following increases variation within a gene pool?", "options": ["Adaptation", "Genetic drift", "Gene mutation", "Neutral selection"], "correctIndex": 2, "explanation": "Gene mutations introduce new alleles into a population and are a primary\n        source of genetic variation within a gene pool. Genetic drift and\n        neutral selection do not create new variation, and adaptation is the\n        outcome of selection acting on existing variation.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 99, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "NUMS 2025 Q#99 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "official_paper_q100_100", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 100, "subject": "Biology", "topic": "heart valves mitral location", "question": "Identify the location of mitral valve in human heart:", "options": ["Between right ventricle and pulmonary trunk", "Between left ventricle and aorta", "Between right atrium and right ventricle", "Between left atrium and left ventricle"], "correctIndex": 3, "explanation": "The mitral (bicuspid) valve lies between the left atrium and left\n        ventricle, preventing backflow during ventricular contraction. The other\n        valves listed correspond to different chambers or vessels (e.g.\n        pulmonary valve between right ventricle and pulmonary trunk).", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 100, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2025 Q#100 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "official_paper_q101_101", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 101, "subject": "Biology", "topic": "composition of blood and lymph", "question": "Which of the following components are present both in blood and lymph?", "options": ["O2, water, large proteins", "RBCs, electrolytes, amino acids", "CO2, RBCs and water", "CO2, glucose and water"], "correctIndex": 3, "explanation": "Both blood and lymph contain dissolved gases (including CO2), glucose\n        and water. Lymph normally lacks red blood cells and has far fewer large\n        plasma proteins than blood, so choices mentioning RBCs or large proteins\n        are incorrect.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 101, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2025 Q#101 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "official_paper_q102_102", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 102, "subject": "Biology", "topic": "factors affecting blood flow", "question": "Blood flow in vessels least depends on:", "options": ["Total cross sectional area of vessels", "Blood pressure", "Skeletal muscle contraction", "Heart beat"], "correctIndex": 2, "explanation": "Blood flow depends mainly on pressure gradient, total cross-sectional\n        area of vessels and cardiac output (heartbeat); skeletal muscle\n        contraction primarily assists venous return but is not a major\n        determinant of flow through all vessels. Thus skeletal muscle\n        contraction is the least generally essential factor listed.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 102, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2025 Q#102 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "official_paper_q103_103", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 103, "subject": "Biology", "topic": "humoral vs cell mediated immunity", "question": "Which T-lymphocytes do not directly attack invading microbes?", "options": ["Natural killer cell", "Macrophages", "B-lymphocytes", "Neutrophils"], "correctIndex": 2, "explanation": "B-lymphocytes mediate humoral immunity by producing antibodies rather\n        than directly attacking microbes, whereas cells like natural killer\n        cells or cytotoxic T cells perform direct cytotoxic actions. Macrophages\n        and neutrophils are phagocytic effector cells, not B cells.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 103, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2025 Q#103 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "official_paper_q104_104", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 104, "subject": "Biology", "topic": "inflammatory mediators", "question": "A woman cuts her finger while working in kitchen. Which chemical substance\n      will cause inflammation around wound?", "options": ["Interleukin – I", "Histamine", "Interleukin – II", "Heparin"], "correctIndex": 1, "explanation": "Histamine is released from mast cells and basophils at sites of injury\n        and causes vasodilation and increased vascular permeability, producing\n        the signs of inflammation. Interleukins and heparin have other\n        immunoregulatory or anticoagulant roles.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 104, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2025 Q#104 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "official_paper_q105_105", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 105, "subject": "Biology", "topic": "chylomicrons composition", "question": "Choose the mismatched:", "options": ["Acetylcholine – gastrin", "Enterokinase – lipase", "Emulsification – fat droplets", "Chylomicrons – cholesterol + carbohydrates"], "correctIndex": 3, "explanation": "Chylomicrons are lipoproteins that transport dietary lipids\n        (triglycerides and cholesterol esters) and apolipoproteins from the\n        intestine; they do not carry carbohydrates, so the pairing 'chylomicrons\n        – cholesterol + carbohydrates' is incorrect. The other pairings are\n        interpreted in physiological contexts (e.g. emulsification relates to\n        fat droplets).", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 105, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2025 Q#105 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "official_paper_q106_106", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 106, "subject": "Biology", "topic": "alveolar structural proteins", "question": "Which protein is present in the walls of alveoli?", "options": ["Collagen", "Hemoglobin", "Myoglobin", "Myosin"], "correctIndex": 0, "explanation": "Collagen is a major structural protein in the connective tissue of\n        alveolar walls, providing strength and support. Hemoglobin and myoglobin\n        are oxygen-binding proteins inside cells, and myosin is a contractile\n        protein, not a structural alveolar component.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 106, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2025 Q#106 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "official_paper_q107_107", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 107, "subject": "Biology", "topic": "enzyme activation enterokinase", "question": "Which of the following acts as an enzyme activator in human digestive\n      system?", "options": ["Erepsin", "Enterokinase", "Pepsinogen", "Trypsinogen"], "correctIndex": 1, "explanation": "Enterokinase (enteropeptidase) activates pancreatic trypsinogen to\n        trypsin, which in turn activates other pancreatic zymogens; thus\n        enterokinase functions as an enzyme activator. Pepsinogen and\n        trypsinogen are inactive precursors, while erepsin is an active\n        protease.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 107, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2025 Q#107 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "official_paper_q108_108", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 108, "subject": "Biology", "topic": "bacterial flagella arrangements", "question": "How would you classify a bacterium having a group of 2 or more flagella at\n      one pole?", "options": ["Lophotrichous", "Amphitrichous", "Monotrichous", "Peritrichous"], "correctIndex": 0, "explanation": "Lophotrichous bacteria have a tuft (a group) of two or more flagella at\n        one pole. Amphitrichous have flagella at both poles, monotrichous a\n        single flagellum, and peritrichous flagella are distributed over the\n        cell surface.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 108, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "NUMS 2025 Q#108 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2025"}, {"id": "official_paper_q109_109", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 109, "subject": "Biology", "topic": "bcg vaccine origin", "question": "Which of the following bacteria is used for developing vaccine against\n      tuberculosis?", "options": ["Mycobacterium tuberculosis", "E. coli", "Salmonella typhi", "Mycobacterium bovis"], "correctIndex": 3, "explanation": "The BCG vaccine against tuberculosis is prepared from an attenuated\n        strain of Mycobacterium bovis, not M. tuberculosis. The other listed\n        bacteria are unrelated to BCG vaccine production.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 109, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "NUMS 2025 Q#109 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2025"}, {"id": "official_paper_q110_110", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 110, "subject": "Biology", "topic": "oxygen requirements facultative anaerobe", "question": "If a bacteria can grow in the presence or absence of oxygen it would be\n      a(n):", "options": ["Aerobic", "Anaerobic", "Facultative anaerobe", "Microaerophilic"], "correctIndex": 2, "explanation": "A facultative anaerobe can grow in the presence or absence of oxygen,\n        using aerobic respiration when O2 is available and switching to\n        anaerobic metabolism otherwise. Aerobes require oxygen and anaerobes\n        cannot tolerate it.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 110, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "NUMS 2025 Q#110 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2025"}, {"id": "official_paper_q111_111", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 111, "subject": "Biology", "topic": "leydig cells testosterone production", "question": "Which testicular cells in a human male with high testosterone level will\n      start the endocrine activity?", "options": ["Interstitial cell", "Sertoli cells", "Spermatogonial cells", "Leydig cells"], "correctIndex": 3, "explanation": "Leydig (interstitial) cells in the testes are the endocrine cells that\n        synthesize and secrete testosterone; they become active when stimulated\n        by LH. Sertoli and spermatogonial cells have supportive or germ-line\n        roles rather than primary androgen secretion.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 111, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2025 Q#111 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "official_paper_q112_112", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 112, "subject": "Biology", "topic": "uterine layer myometrium", "question": "Which layer of uterus is composed of contractile muscles?", "options": ["Endometrium", "Perimetrium", "Myometrium", "Both endo and myometrium"], "correctIndex": 2, "explanation": "The myometrium is the thick middle layer of the uterine wall composed of\n        smooth muscle responsible for uterine contractions. The endometrium is\n        the inner epithelial lining and perimetrium is the serosal outer layer.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 112, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "NUMS 2025 Q#112 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "official_paper_q113_113", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 113, "subject": "Biology", "topic": "pituitary control of ovulation", "question": "One of the endocrine glands responsible for failure in ovulation is:", "options": ["Pituitary", "Placenta", "Thyroid", "Adrenal"], "correctIndex": 0, "explanation": "The pituitary gland secretes FSH and LH which regulate follicle\n        development and trigger ovulation; dysfunction of the pituitary can\n        therefore cause failure to ovulate. While thyroid or adrenal disorders\n        can affect fertility, primary failure of ovulation is classically linked\n        to pituitary hormone problems.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 113, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2025 Q#113 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "official_paper_q114_114", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 114, "subject": "Biology", "topic": "cartilage avascularity", "question": "The reason behind the slow healing of cartilage is:", "options": ["Absence of minerals in matrix", "Absence of nervous supply", "Absence of blood supply", "Loose arrangement of cells"], "correctIndex": 2, "explanation": "Cartilage is avascular (lacks its own blood vessels), so nutrients and\n        waste exchange rely on slow diffusion through the matrix, which causes\n        slow healing. Presence or absence of nerves or minerals is not the main\n        reason for delayed repair.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 114, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "NUMS 2025 Q#114 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "official_paper_q115_115", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 115, "subject": "Biology", "topic": "sarcomere h zone", "question": "H zone of sarcomere consists of:", "options": ["Proteins supporting myosin filaments", "Myosin overlapped by actin", "Only actin filament", "Only myosin filament"], "correctIndex": 3, "explanation": "The H zone is the central region of a sarcomere that contains only thick\n        (myosin) filaments; during contraction the H zone shortens as thin\n        filaments slide inward. Areas of overlap include both actin and myosin.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 115, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "NUMS 2025 Q#115 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "official_paper_q116_116", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 116, "subject": "Biology", "topic": "osteoclast bone resorption", "question": "Which cell is most important to cause bone resorption?", "options": ["Osteoblast", "Osteoclast", "Osteocyte", "Fibroblast"], "correctIndex": 1, "explanation": "Osteoclasts are multinucleated cells that resorb bone by secreting acid\n        and proteolytic enzymes, leading to breakdown of mineral and matrix.\n        Osteoblasts are responsible for bone formation, and osteocytes are\n        mature bone cells embedded in matrix.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 116, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2025 Q#116 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "official_paper_q117_117", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 117, "subject": "Biology", "topic": "smooth muscle dependant organs", "question": "Activity of which organ would be compromised with impaired function of\n      smooth muscles?", "options": ["Heart", "Lungs", "Stomach", "Tongue"], "correctIndex": 2, "explanation": "The stomach uses smooth muscle for peristalsis and mixing of food, so\n        impaired smooth muscle function would compromise gastric activity. The\n        heart is composed of cardiac muscle and the tongue of skeletal muscle,\n        so they are affected differently.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 117, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "NUMS 2025 Q#117 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "official_paper_q118_118", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 118, "subject": "Biology", "topic": "gene linkage and independence", "question": "The phenomena of gene linkage rejects the concept of:", "options": ["Law of segregation", "Polygenic traits", "Epistasis", "Law of independent assortment"], "correctIndex": 3, "explanation": "Gene linkage occurs when genes located on the same chromosome are\n        inherited together, which contradicts Mendel’s law of independent\n        assortment that assumes genes assort independently. Linkage therefore\n        shows that independent assortment is not universal for all gene pairs.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 118, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "NUMS 2025 Q#118 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "official_paper_q119_119", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 119, "subject": "Biology", "topic": "test cross linkage", "question": "Which of the following is used to determine linkage between two gene\n      pairs?", "options": ["Test cross", "Back cross", "Monohybrid cross", "Dihybrid cross"], "correctIndex": 0, "explanation": "A test cross (cross with a homozygous recessive) reveals the phenotype\n        of recombinant versus parental gametes, allowing calculation of\n        recombination frequency and thus linkage between two gene pairs. Other\n        crosses (monohybrid/dihybrid/backcross used differently) do not give the\n        same clear measure of linkage.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 119, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "NUMS 2025 Q#119 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "official_paper_q120_120", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 120, "subject": "Biology", "topic": "autophagy lysosome", "question": "The process by which unwanted structures are engulfed and digested within\n      the lysosome is termed as:", "options": ["Autophagy", "Autolysis", "Endocytosis", "Exocytosis"], "correctIndex": 0, "explanation": "Autophagy is the process where cells sequester damaged organelles or\n        protein aggregates into autophagosomes that fuse with lysosomes for\n        degradation. Autolysis is self-digestion of the whole cell, endocytosis\n        is uptake of extracellular material, and exocytosis is secretion out of\n        the cell.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 120, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2025 Q#120 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "official_paper_q121_121", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 121, "subject": "Biology", "topic": "membrane fluidity phospholipids", "question": "Fluidity of biological membranes is maintained by:", "options": ["Glycoprotein", "Saturated fatty acid", "Fatty acids", "Phospholipids"], "correctIndex": 3, "explanation": "Phospholipids, especially their fatty acid tails (unsaturated vs\n        saturated), determine membrane fluidity by affecting packing and lateral\n        mobility in the bilayer. Glycoproteins are surface markers and saturated\n        fatty acids tend to decrease fluidity rather than maintain it.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 121, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2025 Q#121 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "official_paper_q122_122", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 122, "subject": "Biology", "topic": "organelle autonomous replication", "question": "Which of the following independently reproduces in the cell?", "options": ["Golgi complex", "Nucleus", "Chloroplast", "Endoplasmic reticulum"], "correctIndex": 2, "explanation": "Chloroplasts contain their own circular DNA and division machinery and\n        therefore replicate independently within the cell (by binary fission).\n        Organelles like Golgi, nucleus or ER do not reproduce autonomously in\n        the same way.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 122, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2025 Q#122 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "official_paper_q123_123", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 123, "subject": "Biology", "topic": "ribosome subunits", "question": "Which statement best describes difference of prokaryotic cell from\n      eukaryotic cell?", "options": ["Prokaryote: Membrane bound organelle is present / Eukaryote: Membrane\n          bound organelle is absent", "Prokaryote: Ribosomal subunits are 50S & 30S / Eukaryote:\n          Ribosomal subunits are 60S & 40S", "Prokaryote: DNA is double stranded / Eukaryote: DNA is circular", "Prokaryote: Multicellular / Eukaryote: Multicellular and\n          unicellular"], "correctIndex": 1, "explanation": "Prokaryotic ribosomes are 70S composed of 50S and 30S subunits, while\n        eukaryotic ribosomes are 80S composed of 60S and 40S subunits. The other\n        options incorrectly swap basic prokaryote/eukaryote features.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 123, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2025 Q#123 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "official_paper_q124_124", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 124, "subject": "Biology", "topic": "muscle sarcoplasmic reticulum", "question": "Skeletal muscle cells are having:", "options": ["Less SER & more RER", "More SER & less RER", "Equal amount of SER & RER", "No SER & RER"], "correctIndex": 1, "explanation": "Skeletal muscle cells have an extensive smooth endoplasmic reticulum\n        (sarcoplasmic reticulum) for Ca2+ storage and release, whereas rough ER\n        (RER) is relatively less abundant because these cells are not major\n        secretory cells. So more SER and less RER is correct.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 124, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2025 Q#124 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "official_paper_q125_125", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 125, "subject": "Biology", "topic": "action potential direction", "question": "Which one is the correct direction of action potential along the neuron?", "options": ["Axon → post synaptic terminal", "Schwann cells → pre synaptic terminal", "Cell body → pre synaptic terminal", "Dendrite → post synaptic terminal"], "correctIndex": 0, "explanation": "An action potential is initiated near the cell body/axon hillock and\n        propagates along the axon toward the presynaptic (often called\n        postsynaptic terminal in the option) terminal to transmit signals to the\n        next cell. Dendrites receive inputs, they do not conduct APs toward\n        presynaptic terminals.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 125, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2025 Q#125 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "official_paper_q126_126", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 126, "subject": "Biology", "topic": "ion distribution resting potential", "question": "Concentration of Na+ and K+ ions during resting membrane potential is:\n      (Inside Neuron / Outside Neuron)", "options": ["K+ 30 times / Na+ 10 times", "K+ 10 times / Na+ 30 times", "Na+ 10 times / K+ 30 times", "Na+ 30 times / K+ 10 times"], "correctIndex": 1, "explanation": "At rest intracellular K+ concentration is much higher than outside while\n        Na+ is much higher outside than inside; the option giving K+ ~10×\n        (inside/outside) and Na+ ~30× (outside/inside) matches the conventional\n        comparative ratios used in MCQs. This reflects the gradients maintained\n        by the Na+/K+ pump.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 126, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2025 Q#126 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "official_paper_q127_127", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 127, "subject": "Biology", "topic": "refractory period", "question": "A brief phase in which neuron regains its original ionic distribution and\n      polarity is called:", "options": ["Repolarization", "Synaptic delay", "Saltatory period", "Refractory period"], "correctIndex": 3, "explanation": "The refractory period is the brief interval after an action potential\n        during which the neuron cannot fire (or is less excitable) while ionic\n        gradients and polarity are being restored by ion channels and pumps.\n        Repolarization only refers to the membrane potential returning toward\n        negative values, not the full restoration of ionic distribution.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 127, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2025 Q#127 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "official_paper_q128_128", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 128, "subject": "Biology", "topic": "limbic system structures", "question": "Parts of brain that comprise the limbic system:", "options": ["Thalamus, amygdala, hippocampus", "Hypothalamus, amygdala, hippocampus", "Hypothalamus, corpus callosum, hippocampus", "Thalamus, hypothalamus, pons"], "correctIndex": 1, "explanation": "Core limbic structures include the hippocampus and amygdala and the\n        hypothalamus contributes to limbic functions like emotion and\n        homeostasis. The thalamus is primarily a relay nucleus and the pons is\n        brainstem-these are not the typical trio listed for the limbic system.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 128, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2025 Q#128 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "official_paper_q129_129", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 129, "subject": "Biology", "topic": "ions synaptic transmission", "question": "Ions involved in synaptic transmission of nerve impulse:", "options": ["K+, Ca2+, Na+", "Na+, K+", "Na+, Ca2+", "K+, Ca2+"], "correctIndex": 2, "explanation": "Synaptic transmission depends critically on Ca2+ influx into the\n        presynaptic terminal to trigger neurotransmitter release and on Na+ for\n        generating the presynaptic action potential; K+ is mainly involved in\n        repolarization rather than vesicle release. Thus Na+ and Ca2+ are the\n        key ions listed.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 129, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2025 Q#129 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "official_paper_q130_130", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 130, "subject": "Biology", "topic": "reflex arc order", "question": "Correct sequence of the four elements of a neural pathway in simple-reflex\n      circuit:", "options": ["Sensory neuron → associative neuron → motor neuron → muscles", "Muscles → sensory neuron → associative neuron → motor neuron", "Motor neurons → associate neuron → sensory neuron → muscles", "Associate neuron → sensory neuron → motor neuron → muscles"], "correctIndex": 0, "explanation": "A simple reflex arc proceeds from sensory (afferent) neuron to an\n        associative (interneuron) within the CNS, then to a motor (efferent)\n        neuron and finally to the effector muscle. The other orders do not\n        follow the afferent–central–efferent sequence required for a reflex.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 130, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2025 Q#130 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "official_paper_q131_131", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 131, "subject": "Biology", "topic": "memory and cerebellum", "question": "In humans memory storage for behavior and coordination is well developed\n      in the:", "options": ["Amygdala", "Cerebrum", "Medulla", "Cerebellum"], "correctIndex": 3, "explanation": "The cerebellum is specialized for motor coordination and stores\n        procedural or motor memory related to learned movements and behavior\n        coordination. The cerebrum handles higher cognitive memory and the\n        amygdala is important for emotional memory.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 131, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2025 Q#131 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "official_paper_q132_132", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 132, "subject": "Biology", "topic": "hormone chemical classification", "question": "Choose the correct pairing: (Chemical Nature / Hormones / Glands)", "options": ["Proteins / Insulin / Pancreas", "Steroid / Cortisone / Thymus", "Catecholamine / Estrogen / Adrenal medulla", "Amino acid derivative / Thyroxine / Parathyroid"], "correctIndex": 0, "explanation": "Insulin is a protein (peptide) hormone produced by the pancreatic beta\n        cells, so the protein/insulin/pancreas pairing is correct. The other\n        choices pair hormones with incorrect chemical classes or wrong glands.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 132, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2025 Q#132 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "official_paper_q133_133", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 133, "subject": "Biology", "topic": "origin of coelom", "question": "Which phyla exhibit first true coelom?", "options": ["Cnidaria", "Annelida", "Mollusca", "Platyhelminthes"], "correctIndex": 1, "explanation": "Annelids are classic examples of animals that possess a true coelom (a\n        body cavity fully lined with mesoderm) formed by schizocoely, whereas\n        cnidarians lack a coelom and platyhelminths are acoelomate. Mollusca\n        have a reduced coelom in many taxa but true coelom is characteristically\n        associated with annelids here.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 133, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2025 Q#133 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "official_paper_q134_134", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 134, "subject": "Biology", "topic": "cephalopod intelligence", "question": "Which invertebrate has exceptionally large and complex brain with highly\n      developed capabilities to learn and remember?", "options": ["Snail", "Cattle fish", "Octopus", "Giant squid"], "correctIndex": 2, "explanation": "Octopuses (cephalopods) have large, highly developed nervous systems and\n        demonstrate advanced learning, problem solving and memory compared with\n        most invertebrates. Snails and many fish do not show the same level of\n        complex behavior; giant squid have less-studied cognitive capacity than\n        octopus.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 134, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2025 Q#134 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "official_paper_q135_135", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 135, "subject": "Biology", "topic": "arthropod success exoskeleton", "question": "Arthropods constitute 54% of kingdom Animalia. What is the reason for\n      their success?", "options": ["Diversity and articulation of exoskeleton", "Existence of haemocoel", "Well-developed reproductive system", "Bilateral symmetry"], "correctIndex": 0, "explanation": "Arthropods succeed largely because of their articulated, diverse\n        exoskeleton which provides protection, sites for muscle attachment and\n        modular appendages that can specialize for many functions. Other factors\n        listed (haemocoel, reproduction, symmetry) contribute but the jointed\n        exoskeleton is the primary driver of their ecological success.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 135, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2025 Q#135 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "official_paper_q136_136", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 136, "subject": "Biology", "topic": "dsrna viruses rotavirus", "question": "Which of the following virus is having double stranded RNA in its core?", "options": ["Small pox", "Mild rash virus", "Diarrhea virus", "Rubella virus"], "correctIndex": 2, "explanation": "Rotavirus, the common cause of severe diarrhoea, has a segmented\n        double-stranded RNA genome. Smallpox is a DNA virus and rubella and many\n        rash viruses are single-stranded RNA viruses, so the diarrhoea/rotavirus\n        option is the dsRNA example.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 136, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2025 Q#136 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "official_paper_q137_137", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 137, "subject": "Biology", "topic": "porcelain filter pore size", "question": "Pore size of porcelain filter ranges between:", "options": ["10 – 100 nm", "100 – 1000 nm", "10 – 10 μm", "100 – 1000 μm"], "correctIndex": 1, "explanation": "Porcelain (Berkefeld) filters used historically to remove bacteria have\n        pore sizes in the hundreds of nanometres range (roughly 100–1000 nm),\n        appropriate to retain bacterial cells (typically several hundred nm to a\n        few μm). The smaller or micrometre ranges in other options are\n        inconsistent with standard porcelain filter specifications.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 137, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2025 Q#137 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "official_paper_q138_138", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 138, "subject": "Biology", "topic": "reverse transcriptase function", "question": "Reverse transcriptase converts:", "options": ["ds RNA to ss RNA", "ss RNA to ds RNA", "ss RNA to ds DNA", "ss DNA to ds DNA"], "correctIndex": 2, "explanation": "Reverse transcriptase synthesizes complementary DNA from an RNA\n        template, producing first an ssDNA then a complementary strand to form\n        dsDNA-this is the hallmark of retroviral replication. The other\n        conversions listed do not describe reverse transcription.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 138, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2025 Q#138 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "official_paper_q139_139", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 139, "subject": "Biology", "topic": "early hiv lymphadenopathy", "question": "Which symptoms disappear after few months in an asymptomatic carrier of\n      HIV?", "options": ["Loss of memory", "Swollen lymph gland", "Weight loss", "Night sweats"], "correctIndex": 1, "explanation": "Generalized lymphadenopathy (swollen lymph glands) is a common early\n        symptom of HIV infection that can subside after a few months even while\n        infection persists. Systemic symptoms like weight loss or night sweats\n        are more typical of later disease stages.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 139, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "NUMS 2025 Q#139 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2025"}, {"id": "official_paper_q140_140", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 140, "subject": "Biology", "topic": "photosystem ii water oxidation", "question": "The primary purpose of photosystem-II in thylakoid membrane is:", "options": ["Synthesis of ATP", "Oxidation of water", "Reduction of NADP+ to NADPH", "Oxidation of cytochrome"], "correctIndex": 1, "explanation": "Photosystem II uses light energy to extract electrons from water,\n        oxidizing H2O to O2 and supplying electrons into the photosynthetic\n        electron transport chain; this water-splitting is its primary and unique\n        role. NADP+ reduction and much ATP synthesis occur downstream in the\n        chain and at ATP synthase.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 140, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2025 Q#140 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "official_paper_q141_141", "paperTitle": "NUMS MDCAT 2025 (Official Paper)", "shortTitle": "NUMS 2025", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 141, "subject": "Biology", "topic": "glycolysis oxidation to pyruvate", "question": "In glycolysis glucose is:", "options": ["Oxidized into pyruvic acid", "Reduced into pyruvate", "Broken down to G3P", "Reduced to NADPH"], "correctIndex": 0, "explanation": "In glycolysis glucose is oxidized through a series of reactions to yield\n        two molecules of pyruvate (pyruvic acid), with concurrent reduction of\n        NAD+ to NADH. It is not reduced to NADPH or merely ‘broken down to G3P’\n        as the complete process yields pyruvate as the end product.", "reference": {"sourcePaper": "NUMS MDCAT 2025 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 141, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "NUMS 2025 Q#141 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2025"}, {"id": "paper_c_q1_1", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 1, "subject": "Biology", "topic": "diet and kidney stones", "question": "Overconsumption of which of the following foods increases the risk of\n      calcium oxalate stone?", "options": ["Leafy vegetables", "Fruits contain Vitamin C*", "Fruits contain high fiber", "Whole grains"], "correctIndex": 0, "explanation": "Many leafy vegetables (e.g. spinach, beet greens) are high in oxalate,\n        which can combine with calcium to form calcium oxalate kidney stones.\n        The other options are not primary dietary sources of oxalate that\n        increase risk.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 1, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "SIBA 2025 Q#1 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_c_q2_2", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 2, "subject": "Biology", "topic": "recombinant insulin", "question": "Which product is produced by genetically modified bacteria for patients\n      with Diabetes mellitus?", "options": ["Insulin", "Erythropoietin", "Growth hormone", "Vaccine"], "correctIndex": 0, "explanation": "Recombinant insulin is produced by genetically modified bacteria (e.g.\n        E. coli) and is the standard biologic used to treat diabetes. The other\n        listed proteins can be produced recombinantly as well, but insulin is\n        the classic example for diabetes therapy.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 2, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "SIBA 2025 Q#2 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2025"}, {"id": "paper_c_q3_3", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 3, "subject": "Biology", "topic": "endometrium proliferate phase", "question": "Which changes occur in the endometrium during the proliferate phase of the\n      menstrual cycle?", "options": ["It begins to shed", "It regenerates and thickens", "It becomes secretory", "No change occurs"], "correctIndex": 1, "explanation": "During the proliferative phase (driven by estrogen) the endometrium\n        regenerates and thickens in preparation for possible implantation.\n        Shedding occurs during menstruation, and the secretory phase follows\n        ovulation under progesterone influence.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 3, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "SIBA 2025 Q#3 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2025"}, {"id": "paper_c_q4_4", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 4, "subject": "Biology", "topic": "mrna vaccine mechanism", "question": "Role of mRNA in COVID-19 vaccines like Pfizer and Moderna is to:", "options": ["Helps the immune system recognize the virus", "Instructs cells to produce the viral spike protein", "Triggers immediate antibody release from memory cells", "Delivers enzymes that destroy the virus"], "correctIndex": 1, "explanation": "mRNA vaccines deliver the genetic instructions for the viral spike\n        protein into host cells so those cells produce the protein and present\n        it to the immune system. This differs from directly delivering\n        antibodies or enzymes; the mRNA's role is to instruct protein synthesis.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 4, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SIBA 2025 Q#4 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_c_q5_5", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 5, "subject": "Biology", "topic": "cartilage cell types", "question": "Living cells of cartilage are called as:", "options": ["Osteocytes", "Thrombocytes", "Chondrocytes", "Osteoblasts"], "correctIndex": 2, "explanation": "Chondrocytes are the mature cells that maintain cartilage matrix.\n        Osteocytes and osteoblasts are bone cells, and thrombocytes are\n        platelets-none are cartilage cells.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 5, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SIBA 2025 Q#5 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_c_q6_6", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 6, "subject": "Biology", "topic": "sarcoplasmic reticulum and calcium", "question": "The regulator of muscle contraction, which is released from sarcoplasmic\n      reticulum is:", "options": ["Tropomyosin", "Troponin", "Calcium ions", "ATP"], "correctIndex": 2, "explanation": "The sarcoplasmic reticulum stores and releases Ca2+; released calcium\n        binds troponin to permit actin–myosin interaction and contraction.\n        Tropomyosin and troponin are regulatory proteins, not the SR-released\n        ion; ATP provides energy.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 6, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "SIBA 2025 Q#6 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_c_q7_7", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 7, "subject": "Biology", "topic": "reflex actions", "question": "Automatic and rapid actions that do not involve the conscious part of\n      brain is:", "options": ["Reflex actions", "Conditioned reflexes", "Taxes", "Synapses"], "correctIndex": 0, "explanation": "Reflex actions are rapid, involuntary responses mediated by the spinal\n        cord or brainstem without conscious involvement. Conditioned reflexes\n        require learning; 'taxes' are oriented movements and 'synapses' are\n        junctions between neurons, not actions.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 7, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "SIBA 2025 Q#7 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_c_q8_8", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 8, "subject": "Biology", "topic": "crossing over", "question": "Crossing over involves exchange of genetic material between:", "options": ["Sister chromatids of same chromosome", "Non-sister chromatids of homologous chromosomes", "Chromatids of non-homologous chromosomes", "Sister chromatids of homologous chromosomes"], "correctIndex": 1, "explanation": "Crossing over occurs between non-sister chromatids of homologous\n        chromosome pairs during prophase I of meiosis, exchanging alleles to\n        increase genetic variation. Sister chromatids are identical copies and\n        normally do not exchange in the same way.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 8, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "SIBA 2025 Q#8 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_c_q9_9", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 9, "subject": "Biology", "topic": "nucleic acids information storage", "question": "Name the biomolecule essential for information storage and transmission\n      within cells.", "options": ["Carbohydrates", "Lipids", "Nucleic acids.", "Proteins"], "correctIndex": 2, "explanation": "Nucleic acids (DNA and RNA) store and transmit genetic information\n        required for heredity and protein synthesis. Proteins carry out many\n        cellular functions but do not serve as the primary hereditary\n        information storage molecule.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 9, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SIBA 2025 Q#9 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_c_q10_10", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 10, "subject": "Biology", "topic": "chromosome composition", "question": "What is the chemical composition of chromosomes?", "options": ["RNA and lipids", "DNA and proteins", "Carbohydrates and nucleic acids", "Proteins and carbohydrates"], "correctIndex": 1, "explanation": "Chromosomes are composed of DNA wrapped around histone proteins, so \"DNA\n        and proteins\" is correct. The other choices list incorrect macromolecule\n        combinations; for example RNA and lipids or carbohydrates and nucleic\n        acids do not describe chromosomal composition.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 10, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "SIBA 2025 Q#10 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_c_q11_11", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 11, "subject": "Biology", "topic": "sarcoplasmic reticulum", "question": "Which of the following surrounds myofibril in skeletal muscle that stores\n      and distributes calcium ions during muscle functioning?", "options": ["Sarcolemma", "Sarcoplasmic reticulum", "Transverse tubules", "Sarcoplasm"], "correctIndex": 1, "explanation": "The sarcoplasmic reticulum is the specialized endoplasmic reticulum in\n        muscle that stores and releases Ca2+ for contraction. Sarcolemma is the\n        muscle cell membrane, transverse tubules conduct the action potential,\n        and sarcoplasm is the cytoplasm, so those are not the Ca2+ store.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 11, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "SIBA 2025 Q#11 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_c_q12_12", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 12, "subject": "Biology", "topic": "shivering thermogenesis", "question": "Shivering thermogenesis involves:", "options": ["Voluntary muscle contraction", "Involuntary muscle contraction.", "Dehydration", "Hormone secretion"], "correctIndex": 1, "explanation": "Shivering is an involuntary, rapid muscle contraction that generates\n        heat, so \"Involuntary muscle contraction\" is correct. It is not a\n        voluntary action, nor primarily dehydration- or hormone-driven in the\n        acute shivering response.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 12, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "SIBA 2025 Q#12 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2025"}, {"id": "paper_c_q13_13", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 13, "subject": "Biology", "topic": "gc pair stability", "question": "Guanine - cytosine pairs enhance DNA stability due to:", "options": ["Larger size", "Closer pairing", "More hydrogen bonds", "Double ring structure in both"], "correctIndex": 2, "explanation": "Guanine–cytosine pairs form three hydrogen bonds (versus two in A–T),\n        which increases DNA stability, so \"More hydrogen bonds\" is correct.\n        While both G and C are purines/pyrimidines with ring structures, the key\n        stabilizing factor is the extra hydrogen bond.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 13, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SIBA 2025 Q#13 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_c_q14_14", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 14, "subject": "Biology", "topic": "sensory neurons", "question": "Which of the following neurons conduct impulses from sensory receptors to\n      CNS:", "options": ["Sensory neurons", "Motor neurons", "Efferent neurons.", "Interneurons"], "correctIndex": 0, "explanation": "Sensory (afferent) neurons transmit signals from receptors toward the\n        central nervous system, so \"Sensory neurons\" is correct. Motor and\n        efferent neurons carry signals away from the CNS to effectors, and\n        interneurons relay between neurons within the CNS.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 14, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SIBA 2025 Q#14 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_c_q15_15", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 15, "subject": "Biology", "topic": "lamarck legacy", "question": "Why Lamarck is being remembered till today?", "options": ["Due to his rejected but appealing theory of heredity .", "Due to his universally acceptable theory of evolution", "Due to his accepted theory of heredity", "Due to his theory of evolution by natural selection"], "correctIndex": 0, "explanation": "Lamarck is remembered mainly for his early (now-rejected) idea of\n        inheritance of acquired characteristics, hence \"rejected but appealing\n        theory of heredity\" is accurate. His ideas are not the universally\n        accepted theory of evolution (that's Darwinian natural selection).", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 15, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SIBA 2025 Q#15 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_c_q16_16", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 16, "subject": "Biology", "topic": "uracil dna", "question": "Which of the following is NOT related to DNA?", "options": ["Adenine", "Thymine", "Uracil", "Guanine"], "correctIndex": 2, "explanation": "Uracil is a pyrimidine nucleotide found in RNA, not DNA, so it is not\n        related to DNA. Adenine, thymine and guanine are DNA bases.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 16, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SIBA 2025 Q#16 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_c_q17_17", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 17, "subject": "Biology", "topic": "hemophilia x linked sons", "question": "If a male with hemophilia marries a non-carrier female, what is the\n      likelihood of their sons inheriting the condition?", "options": ["50%", "100%", "0%", "25%"], "correctIndex": 2, "explanation": "Hemophilia is X‑linked recessive. Affected father (XhY) mated with a\n        non‑carrier mother (XH XH) cannot pass the mutant X to sons (they\n        inherit father's Y), so sons will be unaffected (0%). Daughters would be\n        carriers.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 17, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SIBA 2025 Q#17 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_c_q18_18", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 18, "subject": "Biology", "topic": "noncompetitive inhibitor", "question": "Which of the following is a characteristic of a non-competitive enzyme\n      inhibitor?", "options": ["Binds to the enzyme active site", "Can be overcome by increasing substrate concentration", "Increases the speed of the reaction", "Point of action is allosteric site"], "correctIndex": 3, "explanation": "Non-competitive inhibitors bind at an allosteric site (not the active\n        site) and change enzyme activity regardless of substrate concentration,\n        so \"Point of action is allosteric site\" is correct. They do not increase\n        reaction speed and cannot be overcome by raising substrate\n        concentration.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 18, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SIBA 2025 Q#18 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_c_q19_19", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 19, "subject": "Biology", "topic": "cardiac valves and systole", "question": "Which of the following event prevent backflow of blood from ventricles to\n      atria during ventricular systole?", "options": ["Contraction of the atrial wall musles", "Closure of tricuspid and bicuspid valves", "Opening of semilunar valve", "Opening of tricuspid and bicuspid valves"], "correctIndex": 1, "explanation": "Closure of the tricuspid and bicuspid (mitral) valves prevents blood\n        flowing back into the atria during ventricular contraction. The other\n        options either describe atrial activity or the opposite action (opening\n        the atrioventricular valves) which would allow backflow.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 19, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SIBA 2025 Q#19 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_c_q20_20", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 20, "subject": "Biology", "topic": "cellular respiration", "question": "In the following process the cells release energy from oxidation of food\n      molecules?", "options": ["Cellular respiration", "Photosynthesis", "DNA replication", "Protein synthesis"], "correctIndex": 0, "explanation": "Cellular respiration is the process by which cells oxidize food\n        molecules (glucose, etc.) to release energy (ATP). Photosynthesis stores\n        energy in organic molecules, while DNA replication and protein synthesis\n        consume energy rather than generating it from oxidation of food.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 20, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SIBA 2025 Q#20 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_c_q21_21", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 21, "subject": "Biology", "topic": "krebscycle nadh yield", "question": "How many NADH are produced, when one Acetyl co-A is oxidized during\n      Krebs's cycle?", "options": ["1", "2", "3", "6"], "correctIndex": 2, "explanation": "One acetyl-CoA entering the Krebs (citric acid) cycle yields 3 NADH\n        molecules (from isocitrate dehydrogenase, α-ketoglutarate dehydrogenase\n        and malate dehydrogenase steps). The other counts (1, 2, 6) do not match\n        the standard stoichiometry for a single acetyl unit.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 21, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "SIBA 2025 Q#21 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2025"}, {"id": "paper_c_q22_22", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 22, "subject": "Biology", "topic": "glycoproteins", "question": "Which of the following best describes glycoproteins?", "options": ["Proteins linked with carbohydrates", "Proteins linked with DNA", "Proteins linked with lipids", "Proteins linked with minerals"], "correctIndex": 0, "explanation": "Glycoproteins are proteins covalently linked to carbohydrate (sugar)\n        moieties. They are not proteins linked to DNA, lipids, or minerals,\n        which describe other biomolecular conjugates.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 22, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SIBA 2025 Q#22 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_c_q23_23", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 23, "subject": "Biology", "topic": "brain structures and functions", "question": "The function which is common between Cerebellum and Hippocampus is;", "options": ["Equilibrium", "Memory formation", "Body positioning", "Sexual arousal"], "correctIndex": 1, "explanation": "The hippocampus is classically involved in memory formation; while the\n        cerebellum mainly coordinates motor function, it also contributes to\n        certain types of procedural memory. Thus 'memory formation' is the\n        common function listed here, whereas the other options are more specific\n        to motor control or other roles.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 23, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "SIBA 2025 Q#23 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_c_q24_24", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 24, "subject": "Biology", "topic": "urogenital structures", "question": "In males, which of the following is considered a urogenital organ?", "options": ["Urethra", "Ureter", "Urinary bladder", "Vas deferens"], "correctIndex": 0, "explanation": "In males the urethra serves both urinary and reproductive (genital)\n        functions, so it is classified as urogenital. The ureter and bladder are\n        urinary only, and the vas deferens is reproductive but not urinary.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 24, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SIBA 2025 Q#24 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_c_q25_25", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 25, "subject": "Biology", "topic": "types of arthritis", "question": "The most common type of arthritis is:", "options": ["Gout", "Rheumatoid arthritis", "Osteoarthritis", "Spondylitis"], "correctIndex": 2, "explanation": "Osteoarthritis is the most common form of arthritis, resulting from\n        wear-and-tear of joint cartilage. Rheumatoid arthritis and gout are less\n        common systemic or metabolic causes, and spondylitis refers to spinal\n        inflammation.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 25, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SIBA 2025 Q#25 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_c_q26_26", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 26, "subject": "Biology", "topic": "testicular cell types", "question": "The other name for Interstitial cells in male testes is:", "options": ["Leydig cell", "Spermatogonia cell", "Sertoli cell", "Spermatocyte"], "correctIndex": 0, "explanation": "Interstitial cells of the testis are commonly known as Leydig cells;\n        they produce testosterone. Spermatogonia, Sertoli cells and\n        spermatocytes are different cell types involved in spermatogenesis, not\n        interstitial hormone-secreting cells.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 26, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SIBA 2025 Q#26 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_c_q27_27", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 27, "subject": "Biology", "topic": "hemoglobin oxygen binding", "question": "Binding of hemoglobin with oxygen is catalyzed by the enzyme:", "options": ["Carbonic anhydrase", "Carboxylase", "Oxygenase", "Dehydrogenase"], "correctIndex": 0, "explanation": "Carbonic anhydrase catalyzes CO2/HCO3- interconversion, which affects\n        blood pH and thus hemoglobin's oxygen affinity (Bohr effect); through\n        this indirect biochemical influence it is linked to oxygen\n        binding/release. The other enzymes listed do not mediate this\n        physiologic coupling between CO2/bicarbonate chemistry and hemoglobin\n        oxygen affinity.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 27, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SIBA 2025 Q#27 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_c_q28_28", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 28, "subject": "Biology", "topic": "phosphate transfer enzymes", "question": "Transfer of phosphate from one compound to the other compound requires an\n      enzyme called:", "options": ["Oxidoreductase", "Transferase", "Hydrolase", "Ligase"], "correctIndex": 1, "explanation": "Transferases catalyze transfer of functional groups (including\n        phosphate) between molecules, so 'Transferase' is correct.\n        Oxidoreductases catalyze redox reactions, hydrolases cleave bonds by\n        addition of water, and ligases join two molecules together using ATP, so\n        they do not describe a direct phosphate-group transfer enzyme.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 28, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SIBA 2025 Q#28 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_c_q29_29", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 29, "subject": "Biology", "topic": "linkage in drosophila", "question": "Linkage of genes in Drosophila was first discovered by:", "options": ["Thomas Hunt Morgan", "Alfred Sturtevant", "Gregor Mendel", "Hugo de Vries"], "correctIndex": 0, "explanation": "Thomas Hunt Morgan is credited with discovering genetic linkage through\n        his work with Drosophila, demonstrating that some genes do not assort\n        independently. Sturtevant was Morgan's student who later mapped genes;\n        Mendel established basic inheritance laws earlier, and de Vries worked\n        on mutation theory.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 29, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "SIBA 2025 Q#29 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_c_q30_30", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 30, "subject": "Biology", "topic": "mechanisms increasing variation", "question": "Which phenomenon increases the chances of variations?", "options": ["Crossing Over", "Linkage", "Epistasis", "Dominance"], "correctIndex": 0, "explanation": "Crossing over during meiosis exchanges genetic material between\n        homologous chromosomes and increases genetic variation. Linkage reduces\n        independent assortment of genes, epistasis and dominance are\n        interactions/expressions of genes but do not by themselves generate new\n        combinations as directly as crossing over.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 30, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SIBA 2025 Q#30 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_c_q31_31", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 31, "subject": "Biology", "topic": "humoral vs cell mediated response", "question": "When antibodies produced by B-cells, kill the antigens then it is called:", "options": ["Cell mediated response", "Passive response", "Humoral response", "Cells collaborated response"], "correctIndex": 2, "explanation": "Antibodies produced by B-cells define the humoral immune response, which\n        targets antigens in body fluids. Cell-mediated responses are T-cell\n        driven and do not primarily involve antibodies; 'passive response'\n        refers to transferred antibodies, and 'cells collaborated response' is\n        not the standard term.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 31, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SIBA 2025 Q#31 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_c_q32_32", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 32, "subject": "Biology", "topic": "b lymphocyte development", "question": "B-Lymphocytes are formed and matured in:", "options": ["Liver", "Spleen", "Bone marrow", "Thymus"], "correctIndex": 2, "explanation": "In humans B-lymphocytes are produced and mature in the bone marrow. The\n        thymus is the primary site for T-lymphocyte maturation; spleen and liver\n        are lymphoid or hematopoietic-related organs but not the primary site of\n        B-cell maturation.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 32, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SIBA 2025 Q#32 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_c_q33_33", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 33, "subject": "Biology", "topic": "hiv transmission", "question": "Which of the following is a route of HIV transmission?", "options": ["Unhygienic living conditions", "Blood transfusion with contaminated blood", "Hand shaking", "Living together in the same room"], "correctIndex": 1, "explanation": "HIV can be transmitted through transfusion of contaminated blood, which\n        directly introduces infected blood into the recipient. Unhygienic living\n        conditions, handshaking, or merely living together are not routes for\n        HIV transmission.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 33, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "SIBA 2025 Q#33 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2025"}, {"id": "paper_c_q34_34", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 34, "subject": "Biology", "topic": "small intestine nutrient absorption", "question": "Which part of small intestine is responsible for nutrient absorption?", "options": ["Duodenum", "Jejunum", "Ileum", "Rectum"], "correctIndex": 1, "explanation": "The jejunum is the primary site of nutrient absorption in the small\n        intestine, especially for carbohydrates and proteins. The duodenum is\n        mainly for digestion and neutralization of chyme; the ileum absorbs\n        specific nutrients like bile salts and vitamin B12; the rectum is part\n        of the large intestine.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 34, "syllabusUnit": "Unit 5: Human Physiology - Digestion & Nutrition", "pmdcTopic": "Human Digestive System & Absorption Mechanisms", "textbookCitation": "PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12", "citationString": "SIBA 2025 Q#34 | Unit 5: Human Physiology - Digestion & Nutrition | PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12"}, "year": "2025"}, {"id": "paper_c_q35_35", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 35, "subject": "Biology", "topic": "water cohesion adhesion", "question": "Water can circulate in living organisms due to:", "options": ["Surface tension and polarity", "Cohesion and adhesion .", "Solubility in cells", "Stable liquid range"], "correctIndex": 1, "explanation": "Cohesion (water molecules sticking to each other) and adhesion (water\n        sticking to vessel walls) enable capillary action and circulation of\n        water in organisms. Surface tension and polarity are related properties\n        but cohesion/adhesion explain transport more directly; solubility and\n        'stable liquid range' are not the mechanisms for circulation.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 35, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "SIBA 2025 Q#35 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_c_q36_36", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 36, "subject": "Biology", "topic": "x linked transmission", "question": "If the disease is caused due to a defective gene located on the X\n      chromosome, then defectives gene can only be transmitted to male offspring\n      by the:", "options": ["Female gamete", "Male gamete", "Bacteria", "Mutation"], "correctIndex": 0, "explanation": "Male offspring receive their single X chromosome from the mother (female\n        gamete) and Y from the father, so an X-linked defective gene is\n        transmitted to sons by the mother. The father's gamete provides the Y to\n        males, so he cannot pass X-linked alleles to sons; 'bacteria' and\n        'mutation' are not relevant transmission routes in this context.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 36, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "SIBA 2025 Q#36 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2025"}, {"id": "paper_c_q37_37", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 37, "subject": "Biology", "topic": "animal viruses", "question": "Which group of viruses can cause diseases like influenza, measles and\n      rabies?", "options": ["Plant viruses", "Animal viruses", "Fungal viruses", "Bacteriophages"], "correctIndex": 1, "explanation": "Influenza, measles and rabies are caused by viruses that infect animals\n        (including humans), so 'Animal viruses' is correct. Plant viruses infect\n        plants and cannot cause these human diseases; fungal viruses and\n        bacteriophages infect fungi and bacteria respectively, so they are not\n        responsible for the listed human illnesses.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 37, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "SIBA 2025 Q#37 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2025"}, {"id": "paper_c_q38_38", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 38, "subject": "Biology", "topic": "lipid energy densities", "question": "Which of the following biological molecule releases highest energy from\n      its one gram?", "options": ["Carbohydrates", "Lipids", "Protein", "Water"], "correctIndex": 1, "explanation": "Lipids yield more energy per gram (~9 kcal/g) than carbohydrates or\n        proteins (~4 kcal/g), so 'Lipids' is correct. Water provides no\n        metabolic energy, and proteins and carbohydrates release substantially\n        less energy per gram than lipids.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 38, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SIBA 2025 Q#38 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_c_q39_39", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 39, "subject": "Biology", "topic": "aids prevention", "question": "The best way to avoid AIDS is:", "options": ["Preventive measures", "Vaccination", "Medication", "Shots"], "correctIndex": 0, "explanation": "Since AIDS results from HIV infection, the best approach is preventive\n        measures (safe sex, sterile needles, screening blood) to avoid\n        infection. There is no widely available vaccine; medication treats HIV\n        but does not prevent initial infection by itself, and 'Shots' is\n        ambiguous and not a preventive strategy.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 39, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SIBA 2025 Q#39 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_c_q40_40", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 40, "subject": "Biology", "topic": "glomerular filtration", "question": "Which of the following substances pass through the glomerulus into\n      Bowman's capsule?", "options": ["Glucose", "Red blood cells", "Platelets", "Albumin"], "correctIndex": 0, "explanation": "Glucose is small and freely filtered through the glomerulus into\n        Bowman’s capsule, so 'Glucose' is correct. Red blood cells and platelets\n        are too large to be filtered, and albumin is normally retained because\n        of size and charge; its presence in filtrate indicates pathology.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 40, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SIBA 2025 Q#40 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_c_q41_41", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 41, "subject": "Biology", "topic": "appendix location", "question": "The appendix is attached to which part of large intestine?", "options": ["Rectum", "Caecum", "Colon", "Ileum"], "correctIndex": 1, "explanation": "The vermiform appendix is a blind pouch attached to the caecum, making\n        'Caecum' correct. The rectum is distal, the colon is a general term for\n        large intestine (but not the specific attachment), and the ileum is the\n        terminal small intestine that joins the caecum.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 41, "syllabusUnit": "Unit 5: Human Physiology - Digestion & Nutrition", "pmdcTopic": "Human Digestive System & Absorption Mechanisms", "textbookCitation": "PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12", "citationString": "SIBA 2025 Q#41 | Unit 5: Human Physiology - Digestion & Nutrition | PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12"}, "year": "2025"}, {"id": "paper_c_q42_42", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 42, "subject": "Biology", "topic": "arterial structure", "question": "Which structural characteristic is most accurate for arteries?", "options": ["Thin walls with valves", "Thick and muscular walls", "Highly permeable walls", "Large lumen lacking muscle"], "correctIndex": 1, "explanation": "Arteries have thick, muscular, elastic walls to withstand and regulate\n        high-pressure blood flow, so 'Thick and muscular walls' is correct. Thin\n        walls with valves describe veins (which often have valves); high\n        permeability and large lumen lacking muscle apply to capillaries and\n        veins respectively, not arteries.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 42, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SIBA 2025 Q#42 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_c_q43_43", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 43, "subject": "Biology", "topic": "proteins polypeptides", "question": "A food sample contains long chains of amino acids bounded together. This\n      indicates the presence of:", "options": ["Carbohydrates", "Lipids", "Proteins", "Nucleic acids"], "correctIndex": 2, "explanation": "Proteins are polymers made of long chains of amino acids (polypeptides),\n        so 'Proteins' is correct. Carbohydrates are sugars/polymers of sugars,\n        lipids are fatty molecules, and nucleic acids are polymers of\n        nucleotides, not amino acids.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 43, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SIBA 2025 Q#43 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_c_q44_44", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 44, "subject": "Biology", "topic": "monoclonal antibodies", "question": "Monoclonal antibodies are useful in cancer diagnosis by:", "options": ["Replacing damaged tissue", "Changing the genetic code of cancer cells", "Killing healthy cells to reduce tumor spread", "Detecting specific tumor markers in samples"], "correctIndex": 3, "explanation": "Monoclonal antibodies can specifically bind tumor-associated antigens\n        and are widely used to detect tumor markers in diagnostic tests, so\n        'Detecting specific tumor markers in samples' is correct. They do not\n        replace tissue or change genetic code, and deliberately killing healthy\n        cells would be harmful and is not their diagnostic use.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 44, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SIBA 2025 Q#44 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_c_q45_45", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 45, "subject": "Biology", "topic": "pharynx function", "question": "The main function of the pharynx in respiratory system:", "options": ["Serves as passage for both food and air", "Produces mucus", "Produces voice", "Filters air"], "correctIndex": 0, "explanation": "The pharynx is a common passageway for both air (to the larynx) and food\n        (to the esophagus), so 'Serves as passage for both food and air' is\n        correct. Mucus production is mainly from nasal passages and goblet\n        cells, voice production is from the larynx, and filtering is primarily\n        done in the nasal cavity and by cilia in the airways.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 45, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SIBA 2025 Q#45 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_c_q46_46", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 46, "subject": "Biology", "topic": "acute kidney failure", "question": "The main cause of acute kidney failure is:", "options": ["Less sweating,", "Hypothermia", "Liver failure", "Drinking of excess water"], "correctIndex": 2, "explanation": "Acute kidney (renal) failure is most commonly due to intrinsic problems\n        such as severe kidney injury or reduced renal perfusion; among the\n        listed options, liver failure is a recognized systemic cause that can\n        precipitate renal failure (e.g., hepatorenal syndrome). The other\n        choices (less sweating, hypothermia, drinking excess water) are not\n        common primary causes of acute kidney failure.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 46, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "SIBA 2025 Q#46 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_c_q47_47", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 47, "subject": "Biology", "topic": "diastole heart chambers", "question": "During diastole, the heart chambers:", "options": ["Relax and fill with blood", "Contract strongly", "Eject blood into arteries", "Remain closed"], "correctIndex": 0, "explanation": "Diastole is the relaxation phase of the cardiac cycle during which the\n        ventricles and atria relax and the chambers fill with blood. Contraction\n        and ejection occur during systole, so the other options describe\n        systolic events or are incorrect.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 47, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SIBA 2025 Q#47 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_c_q48_48", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 48, "subject": "Biology", "topic": "antidiuretic hormone urine concentration", "question": "Kidneys perform their osmoregulatory role under the effect of Antidiuretic\n      Hormone, which type of urine is produced in this situation?", "options": ["Hypotonic urine with decreased volume", "Hypotonic urine with increased volume", "Hypertonic urine with decreased volume", "Hypertonic urine with increased volume"], "correctIndex": 2, "explanation": "ADH increases water reabsorption in the collecting ducts, concentrating\n        the urine and reducing its volume; thus urine becomes hypertonic with\n        decreased volume. The options describing hypotonic urine or increased\n        volume contradict ADH’s water-retaining action.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 48, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "SIBA 2025 Q#48 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_c_q49_49", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 49, "subject": "Biology", "topic": "lymph node swelling lymphadenopathy", "question": "A person has swollen lymph nodes after throat infection. What does this\n      indicate?", "options": ["Failure of circulatory system", "Extra glucose storage", "Active immune response", "Blockage of digestive track"], "correctIndex": 2, "explanation": "Swollen (tender) lymph nodes after an infection indicate activation and\n        proliferation of immune cells responding to pathogens - an active immune\n        response. The other options are unrelated to post-infectious lymph node\n        enlargement.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 49, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SIBA 2025 Q#49 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_c_q50_50", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 50, "subject": "Biology", "topic": "brain grey and white matter", "question": "Which of the following is correct about the structure of brain?", "options": ["Cerebral cortex is outer part consists of grey matter", "Cerebral medulla is inner part consists of grey matter", "Cerebral cortex is inner part consists of white matter", "Cerebral medulla is outer part consists of white matter"], "correctIndex": 0, "explanation": "The cerebral cortex is the outer layer of the cerebrum composed mainly\n        of neuronal cell bodies (grey matter); the inner regions (medulla) are\n        richer in myelinated axons (white matter). The other choices invert\n        these well-established anatomical relationships.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 50, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "SIBA 2025 Q#50 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_c_q51_51", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 51, "subject": "Biology", "topic": "plant cell rigidity cell wall", "question": "Under a microscope plant cells appeared rigid in shape, unlike flexible\n      animal cells. Which structure explain this difference?", "options": ["Cell wall", "Vacuole", "Cytoskeleton", "Plasma membrane"], "correctIndex": 0, "explanation": "Plant cells are rigid because of a cellulose-containing cell wall that\n        surrounds the plasma membrane and provides structural support. While the\n        vacuole and cytoskeleton contribute to shape, the rigid cell wall is the\n        primary cause of the marked rigidity compared with animal cells.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 51, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SIBA 2025 Q#51 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_c_q52_52", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 52, "subject": "Biology", "topic": "elbow joint hinge synovial", "question": "Which type of joint allows bending of the elbow joint and has a synovial\n      cavity?", "options": ["Cartilaginous joint", "Fibrous joint", "Pubic symphysis", "Hinge joint"], "correctIndex": 3, "explanation": "The elbow is a hinge joint, a type of synovial joint that permits\n        flexion and extension and contains a synovial cavity. Cartilaginous and\n        fibrous joints lack a synovial cavity, and the pubic symphysis is a\n        cartilaginous joint.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 52, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "SIBA 2025 Q#52 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2025"}, {"id": "paper_c_q53_53", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 53, "subject": "Biology", "topic": "pea plant self fertilization true breeding", "question": "If a round seeded pea plant is self-fertilized and all of its offspring\n      are also round seeded:", "options": ["Both parents and offspring must be true breed", "Both parents and offspring may be true breed", "Only parents but not offspring will be true breed", "Only offspring but not parents will be true breed"], "correctIndex": 0, "explanation": "If self-fertilization yields only the same phenotype in all offspring,\n        the parent must be homozygous (true-breeding) for that trait;\n        consequently offspring will also be true-breeding for the same allele.\n        The other options contradict the genetics of true-breeding homozygotes.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 53, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "SIBA 2025 Q#53 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2025"}, {"id": "paper_c_q54_54", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 54, "subject": "Biology", "topic": "prokaryote unicellular", "question": "A student observes a microorganism under a microscope that lacks a nucleus\n      and is made of a single cell. Which classification would best fit this\n      organism?", "options": ["Unicellular prokaryote", "Unicellular eukaryote", "Multicellular eukaryote", "Multicellular prokaryote"], "correctIndex": 0, "explanation": "An organism that is single-celled and lacks a nucleus fits the\n        definition of a unicellular prokaryote (e.g., a bacterium). Eukaryotes\n        have a nucleus, and prokaryotes are not multicellular organisms in the\n        typical sense, so the other classifications are incorrect.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 54, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SIBA 2025 Q#54 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_c_q55_55", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 55, "subject": "Biology", "topic": "vaccine development by cloning", "question": "In biotechnology vaccines can be developed by cloning of:", "options": ["Gene for antigen of pathogen", "Gene for receptor of the patient", "Gene for antigen of patient", "Gene for antibody of patient"], "correctIndex": 0, "explanation": "Vaccines produced by recombinant DNA methods are typically made by\n        cloning the gene that encodes an antigen from a pathogen so that the\n        antigen can be expressed and used to stimulate immunity. Cloning a\n        patient's receptor, antigen of the patient, or antibody of the patient\n        would not yield a pathogen-derived vaccine antigen.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 55, "syllabusUnit": "Unit 7: Human Physiology - Immunity", "pmdcTopic": "Innate & Adaptive Immunity, Immunoglobulins and Vaccines", "textbookCitation": "PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14", "citationString": "SIBA 2025 Q#55 | Unit 7: Human Physiology - Immunity | PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_c_q56_56", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 56, "subject": "Biology", "topic": "atrioventricular valve closure", "question": "Atrioventricular valve closed during which phase of cardiac cycle:", "options": ["Ventricular systole", "Ventricular diastole", "Atrial systole", "Atrial diastole"], "correctIndex": 0, "explanation": "AV valves (mitral and tricuspid) close during ventricular systole to\n        prevent backflow into the atria when the ventricles contract. They are\n        open during ventricular diastole to allow ventricular filling.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 56, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SIBA 2025 Q#56 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_c_q57_57", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 57, "subject": "Biology", "topic": "natural selection definition", "question": "Name the idea of Darwin that best explains the ability of populations to\n      reproduce those individuals who possess beneficial traits.", "options": ["Gene flow", "Genetic drift", "Artificial selection", "Natural selection"], "correctIndex": 3, "explanation": "Natural selection is Darwin's mechanism explaining how individuals with\n        beneficial heritable traits have higher reproductive success, causing\n        those traits to become more common in populations. Gene flow and genetic\n        drift are other evolutionary processes; artificial selection is\n        human-directed.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 57, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "SIBA 2025 Q#57 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2025"}, {"id": "paper_c_q58_58", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 58, "subject": "Biology", "topic": "polysaccharide monomer count", "question": "At least how many saccharide units must be present in polysaccharide?", "options": ["1", "2", "10", "11"], "correctIndex": 3, "explanation": "A polysaccharide is by definition a polymer of many sugar units;\n        commonly a minimum threshold is taken to mean more than a small\n        oligosaccharide. The key lists 11, reflecting the question's intended\n        cut-off rather than mono- or di-saccharides.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 58, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SIBA 2025 Q#58 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_c_q59_59", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 59, "subject": "Biology", "topic": "knee jerk reflex", "question": "A doctor taps below the knee and the leg kicks forward. What does this\n      show?", "options": ["A conditional response", "Voluntary muscle contractions", "An involuntary reflex to external stimuli", "A delayed response due to brain processing"], "correctIndex": 2, "explanation": "The knee-jerk (patellar) response is a monosynaptic stretch reflex\n        triggered by tapping the patellar tendon, producing an involuntary\n        reflexive leg extension. It is not a voluntary action or a delayed,\n        brain-processed response.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 59, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "SIBA 2025 Q#59 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2025"}, {"id": "paper_c_q60_60", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 60, "subject": "Biology", "topic": "uterine layer degeneration", "question": "If fertilization does not occur, which part of uterus degenerate?", "options": ["Myometrium", "Endometrium", "Perimetrium", "Cervix"], "correctIndex": 1, "explanation": "If fertilization does not occur, the endometrium (the functional lining\n        of the uterus) is shed during menstruation. The myometrium and\n        perimetrium remain intact and the cervix does not degenerate.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 60, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "SIBA 2025 Q#60 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2025"}, {"id": "paper_c_q61_61", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 61, "subject": "Biology", "topic": "translation process", "question": "Which process uses mRNA to make protein at ribosomes?", "options": ["Replication", "Transcription", "Translation", "Cell fractionation"], "correctIndex": 2, "explanation": "Translation is the process by which ribosomes read messenger RNA (mRNA)\n        sequences to synthesize polypeptides (proteins). Replication makes DNA,\n        transcription makes RNA from DNA, and cell fractionation is a laboratory\n        technique.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 61, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SIBA 2025 Q#61 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_c_q62_62", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 62, "subject": "Biology", "topic": "sexually transmitted disease identification", "question": "Which of the following is the sexually transmitted disease?", "options": ["Syphilis", "Lung Cancer", "Tuberculosis", "Autoimmune disorders"], "correctIndex": 0, "explanation": "Syphilis is a sexually transmitted infection caused by Treponema\n        pallidum. Lung cancer and tuberculosis are not STDs, and autoimmune\n        disorders are non-infectious conditions.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 62, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SIBA 2025 Q#62 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_c_q63_63", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 63, "subject": "Biology", "topic": "golgi apparatus", "question": "The Golgi apparatus is structurally made of a series of flattened membrane\n      bounded sacs.", "options": ["Grana", "Cristae", "Cisternae", "Vesicles"], "correctIndex": 2, "explanation": "The Golgi apparatus consists of flattened membrane-bound sacs called\n        cisternae; grana and cristae refer to chloroplast and mitochondria\n        membrane folds respectively, while vesicles are small membrane-enclosed\n        carriers, not the stacked sacs that make up the Golgi.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 63, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SIBA 2025 Q#63 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_c_q64_64", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 64, "subject": "Biology", "topic": "nerve impulse nature", "question": "Which type of change is a nerve impulse?", "options": ["Electrical and mechanical change", "Chemical and mechanical change", "Electrical and chemical change", "Chemical change only"], "correctIndex": 2, "explanation": "A nerve impulse involves electrical changes (membrane potential) and\n        chemical changes (neurotransmitter release at synapses). It is not\n        primarily mechanical, so the combined electrical and chemical\n        description is correct.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 64, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SIBA 2025 Q#64 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_c_q65_65", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 65, "subject": "Biology", "topic": "lymphatic fluid", "question": "Which of the following fluid flows through the lymphatic vessels?", "options": ["Plasma", "Lymph", "Bile", "Serum"], "correctIndex": 1, "explanation": "Lymphatic vessels carry lymph, a fluid derived from interstitial fluid\n        and similar to plasma but without large proteins; plasma and serum are\n        blood components, and bile is a digestive secretion, not transported by\n        lymphatics.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 65, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SIBA 2025 Q#65 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_c_q66_66", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 66, "subject": "Biology", "topic": "nitrogenous waste", "question": "Which one of the following is the most common nitrogenous waste excreted\n      in urine of a healthy human?", "options": ["Ammonia", "Urea", "Uric Acid", "Creatinine"], "correctIndex": 1, "explanation": "Humans primarily excrete nitrogenous waste as urea, which is less toxic\n        and more soluble than ammonia; uric acid and creatinine are also present\n        but urea is the main nitrogenous compound in urine.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 66, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "SIBA 2025 Q#66 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_c_q67_67", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 67, "subject": "Biology", "topic": "hippocampus", "question": "Hippocampus mainly involved in:", "options": ["Vision and hearing reflexes", "Voluntary muscles movement", "Memory storage", "Speech production"], "correctIndex": 2, "explanation": "The hippocampus is a brain structure central to the formation and\n        consolidation of memories. It is not primarily responsible for sensory\n        reflexes, voluntary muscle control, or speech production.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 67, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SIBA 2025 Q#67 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2025"}, {"id": "paper_c_q68_68", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 68, "subject": "Biology", "topic": "enzyme cofactor prosthetic group", "question": "The covalently bonded non protein part of enzyme is called: -", "options": ["Activator", "Prosthetic group", "Coenzyme", "Apoenzyme"], "correctIndex": 1, "explanation": "A prosthetic group is a non-protein moiety covalently bound to an\n        enzyme; coenzymes are organic cofactors that bind loosely, an activator\n        is a general term for something that increases activity, and apoenzyme\n        refers to the protein portion without its cofactor.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 68, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SIBA 2025 Q#68 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_c_q69_69", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 69, "subject": "Biology", "topic": "resting membrane potential", "question": "The outer surface of the axon membrane in a resting neuron is:", "options": ["Negative due to sodium ions", "Positive due to sodium ions", "Positive due to potassium ions", "Neutral due to balanced ions"], "correctIndex": 1, "explanation": "At rest the outer surface of the axon membrane is relatively positive\n        (extracellular side) largely because of higher extracellular Na+; the\n        intracellular side is negative. Potassium is higher inside the cell, so\n        option three is incorrect.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 69, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SIBA 2025 Q#69 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_c_q70_70", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 70, "subject": "Biology", "topic": "excretion types", "question": "Which class of animals excrete ammonia as their primary nitrogenous waste?", "options": ["Uricotelic", "Urotelic", "Ammonotelic", "Ureotelic"], "correctIndex": 2, "explanation": "Ammonotelic animals excrete ammonia as their main nitrogenous waste\n        (common in aquatic organisms), whereas ureotelic animals excrete urea\n        and uricotelic animals excrete uric acid; 'urotelic' is not the correct\n        standard term here.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 70, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "SIBA 2025 Q#70 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_c_q71_71", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 71, "subject": "Biology", "topic": "impulse direction", "question": "Which of the following best describes the direction of impulse traveling\n      in a typical neuron?", "options": ["Axon ....... dendrite ...... cell body", "Dendrite ..... cell body ..... axon", "Synapse ..... axon ...... dendrite", "Cell body ...... dendrite ...... axon"], "correctIndex": 1, "explanation": "Typical impulse flow in a neuron goes from dendrites to the cell body\n        and then along the axon to the synapse. The other sequences do not\n        represent the normal directional flow of information in a single neuron.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 71, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SIBA 2025 Q#71 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2025"}, {"id": "paper_c_q72_72", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 72, "subject": "Biology", "topic": "homopolysaccharide chitin", "question": "Homopolysaccharide that is found in the cell wall of fungi and in the\n      exoskeleton of arthropods is:", "options": ["Cellulose", "Glycogen", "Starch", "Chitin"], "correctIndex": 3, "explanation": "Chitin is a homopolysaccharide of N-acetylglucosamine found in fungal\n        cell walls and arthropod exoskeletons. The other choices are\n        polysaccharides with different functions: cellulose is in plant cell\n        walls, glycogen is animal storage carbohydrate, and starch is plant\n        storage carbohydrate.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 72, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SIBA 2025 Q#72 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_c_q73_73", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 73, "subject": "Biology", "topic": "abundant lipids", "question": "The most abundant lipids in living things are:", "options": ["Terpenes", "Waxes", "Steroids", "Acylglycerols"], "correctIndex": 3, "explanation": "Acylglycerols (triacylglycerols) are the primary storage lipids and are\n        among the most abundant lipids in organisms. Terpenes, waxes and\n        steroids occur widely but are not the predominant storage/structural\n        lipid class in most living things.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 73, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SIBA 2025 Q#73 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_c_q74_74", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 74, "subject": "Biology", "topic": "peptide bond", "question": "Name the type of bond that join amino acids to form a polypeptide chain:", "options": ["Hydrogen bond", "Ionic bond", "Glycosidic bond", "Peptide bond"], "correctIndex": 3, "explanation": "A peptide bond (an amide linkage) forms between the carboxyl group of\n        one amino acid and the amino group of the next, linking amino acids into\n        polypeptides. Hydrogen and ionic bonds are non-covalent interactions;\n        glycosidic bonds link sugars, not amino acids.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 74, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SIBA 2025 Q#74 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_c_q75_75", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 75, "subject": "Biology", "topic": "globular vs fibrous protein", "question": "Which of the following is not a globular protein?", "options": ["Enzyme", "Hormone", "Channel protein", "Collagen"], "correctIndex": 3, "explanation": "Collagen is a fibrous structural protein, not globular. Enzymes, many\n        hormones, and channel proteins are typically globular with soluble or\n        membrane-associated tertiary structures; collagen forms long fibrous\n        assemblies for structural support.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 75, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SIBA 2025 Q#75 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_c_q76_76", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 76, "subject": "Biology", "topic": "kupffer cells", "question": "Which specialized cells of liver perform phagocyte function?", "options": ["Kupffer cells", "Schwann cells", "Parietal cells", "Chief cells"], "correctIndex": 0, "explanation": "Kupffer cells are liver-resident macrophages responsible for\n        phagocytosis of pathogens and debris. Schwann cells are peripheral\n        nervous system glia, parietal and chief cells are gastric epithelial\n        cells and do not perform hepatic phagocytosis.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 76, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SIBA 2025 Q#76 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2025"}, {"id": "paper_c_q77_77", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 77, "subject": "Biology", "topic": "natural selection", "question": "According to Darwin, the main force behind evolution is:", "options": ["Migration", "Genetic mutation", "Artificial selection", "Natural selection"], "correctIndex": 3, "explanation": "Darwin proposed natural selection as the primary mechanism driving\n        evolution: differential survival and reproduction of individuals with\n        heritable advantageous traits. While mutation provides variation and\n        migration can affect gene flow, Darwin emphasised natural selection.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 77, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "SIBA 2025 Q#77 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2025"}, {"id": "paper_c_q78_78", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 78, "subject": "Biology", "topic": "fallopian tube function", "question": "Beside fertilization, the function of fallopian tube is:", "options": ["Nourishment of embryo", "Transport of ovum towards uterus", "Secretion of female hormones", "Implantation of zygote"], "correctIndex": 1, "explanation": "The fallopian (uterine) tube transports the ovum from the ovary toward\n        the uterus and is also the typical site of fertilization. Implantation\n        occurs in the uterine lining, and hormone secretion is primarily\n        ovarian/endocrine; nourishment of the embryo begins after implantation.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 78, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "SIBA 2025 Q#78 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2025"}, {"id": "paper_c_q79_79", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 79, "subject": "Biology", "topic": "adhesion", "question": "Which property of water allows it to stick to polar surface like wood?", "options": ["Density", "Adhesion", "Cohesion", "Non-polar attraction"], "correctIndex": 1, "explanation": "Adhesion is the attraction between water molecules and other polar\n        surfaces, allowing water to stick to materials like wood. Cohesion is\n        the attraction between water molecules themselves; density and\n        'non-polar attraction' are not responsible for sticking to polar\n        surfaces.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 79, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "SIBA 2025 Q#79 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_c_q80_80", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 80, "subject": "Biology", "topic": "pituitary gland", "question": "The water content of human kidney is regulated by ADH. Which of the\n      following gland is involved in its secretion process?", "options": ["Adrenal gland", "Pituitary gland", "Thyroid gland", "Parathyroid gland"], "correctIndex": 1, "explanation": "ADH (antidiuretic hormone, vasopressin) is secreted by the posterior\n        pituitary (neurohypophysis) and regulates kidney water reabsorption. The\n        adrenal, thyroid and parathyroid glands have different hormonal roles\n        unrelated to direct ADH secretion.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 80, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "SIBA 2025 Q#80 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2025"}, {"id": "paper_c_q81_81", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 81, "subject": "Chemistry", "topic": "hess law", "question": "The heat of formation of CO and CO2 are -26.4 Kcal and -94.0 Kcal\n      respectively. The heat of combustion of carbon monoxide according to\n      Hess's Law will be:", "options": ["+26.4Kcal", "-67.6Kcal", "+94.0Kcal", "-120.4Kcal"], "correctIndex": 1, "explanation": "Use Hess's law: CO + 1/2 O2 → CO2 has ΔH = ΔHf(CO2) − ΔHf(CO) = (−94.0)\n        − (−26.4) = −67.6 kcal. The negative sign indicates heat released, so\n        −67.6 kcal is correct.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 81, "syllabusUnit": "Unit 4: Chemical Energetics", "pmdcTopic": "Enthalpy Changes, Hess's Law & Standard Heats of Reaction", "textbookCitation": "PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6", "citationString": "SIBA 2025 Q#81 | Unit 4: Chemical Energetics | PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6"}, "year": "2025"}, {"id": "paper_c_q82_82", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 82, "subject": "Chemistry", "topic": "dehydration rate", "question": "Rate of dehydration of alcohol is:", "options": ["3°>2°>1°", "1°>3°>2°", "2°>3°>1°", "3°>1°>2°"], "correctIndex": 0, "explanation": "Dehydration (E1) of alcohols proceeds more readily for more stable\n        carbocations; tertiary (3°) carbocations are most stable, then\n        secondary, then primary, giving rate 3° > 2° > 1°.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 82, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "SIBA 2025 Q#82 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2025"}, {"id": "paper_c_q83_83", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 83, "subject": "Chemistry", "topic": "temperature effect on kc", "question": "For which reaction, the value of Kc increases with increase in\n      temperature?", "options": ["CH4 + O2 → CO2 + H2O", "NaOH + HCl → NaCl + H2O", "2SO2 + O2 → 2SO3", "H2 + I2 → 2HI"], "correctIndex": 3, "explanation": "Kc increases with temperature for endothermic reactions. The formation\n        of HI from H2 and I2 (H2 + I2 ⇌ 2HI) is endothermic under typical\n        considerations used in equilibrium examples, so raising temperature\n        shifts equilibrium to products and increases Kc.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 83, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "SIBA 2025 Q#83 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2025"}, {"id": "paper_c_q84_84", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 84, "subject": "Chemistry", "topic": "bond dissociation energies", "question": "Correct order of bond energy will be:", "options": ["HCl>HBr>HI", "HBr>HCl>HI", "HI>HCl>HBr", "HCl>HI>HBr"], "correctIndex": 0, "explanation": "Bond dissociation energy generally correlates with bond strength; H–Cl\n        bonds are stronger than H–Br, which are stronger than H–I, so HCl >\n        HBr > HI is the correct order.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 84, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "SIBA 2025 Q#84 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2025"}, {"id": "paper_c_q85_85", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 85, "subject": "Chemistry", "topic": "volatility and intermolecular forces", "question": "Which of the following is least volatile?", "options": ["Glycerol", "Water", "Acetic acid", "Diethyl ether"], "correctIndex": 0, "explanation": "Glycerol has very strong hydrogen bonding and a high boiling point,\n        making it much less volatile than water, acetic acid, or diethyl ether.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 85, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SIBA 2025 Q#85 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_c_q86_86", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 86, "subject": "Chemistry", "topic": "iupac nomenclature alkanes", "question": "IUPAC name of the compound is CH3(CH2)CH(CH3)2:", "options": ["2-methylheptane", "3-methylheptane", "4-methylheptane", "Octane"], "correctIndex": 0, "explanation": "Numbering to give the substituent the lowest possible locant leads to a\n        methyl substituent at carbon-2 for the printed chain, so 2-methylheptane\n        matches the provided structure as printed.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 86, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "SIBA 2025 Q#86 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2025"}, {"id": "paper_c_q87_87", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 87, "subject": "Chemistry", "topic": "iupac nomenclature alkenes", "question": "IUPAC name of the compound C2H5CH=C(CCH3) C2H5 is :", "options": ["1,2-diethyl-2-propylethene", "3-ethylhept-3-ene", "4-ethylhept-3-ene", "4-ethylhept-2-ene"], "correctIndex": 2, "explanation": "Based on the carbon skeleton and double-bond position as printed, the\n        correct IUPAC name given in the exam paper corresponds to\n        4-ethylhept-3-ene (option c).", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 87, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "SIBA 2025 Q#87 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2025"}, {"id": "paper_c_q88_88", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 88, "subject": "Chemistry", "topic": "molecular geometry", "question": "Which of the following molecules have similar molecular shape?", "options": ["NH3 & AlCl3", "BCl3 & NH3", "AlCl3 & PCl3", "H2O & SnCl2"], "correctIndex": 3, "explanation": "H2O (bent) and SnCl2 (also bent due to lone pairs) share similar bent\n        molecular geometry, whereas the other pairings mix trigonal planar,\n        trigonal pyramidal, and other geometries.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 88, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "SIBA 2025 Q#88 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2025"}, {"id": "paper_c_q89_89", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 89, "subject": "Chemistry", "topic": "electronegativity and ionic character", "question": "Value of electronegativity of atoms A and B are 1.20 and 4.0 respectively,\n      the percent ionic character will be:", "options": ["43%", "50%", "55%", "73%"], "correctIndex": 3, "explanation": "The larger the electronegativity difference between two atoms, the\n        greater the percent ionic character of their bond. Here the difference\n        is 4.0 - 1.20 = 2.8, a large value that corresponds to a high,\n        predominantly ionic character of about 73%.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 89, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SIBA 2025 Q#89 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_c_q90_90", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 90, "subject": "Chemistry", "topic": "phenol vs ethanol", "question": "Phenol differs from ethanol because it:", "options": ["Forms stronger hydrogen bonds to its aromatic ring", "Is more acidic because of resonance stabilized conjugate base", "Readily undergoes nucleophilic substitution at the -OH group", "Is completely insoluble in water due to its benzene ring"], "correctIndex": 1, "explanation": "Phenol is more acidic than ethanol because the phenoxide ion is\n        resonance stabilized (option b). Ethanol lacks that resonance\n        stabilization. Phenol does not readily undergo nucleophilic substitution\n        at the OH (option c) and it is not completely insoluble in water (option\n        d) - it has limited but significant solubility due to the OH group;\n        option a is a misleading description of bonding.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 90, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "SIBA 2025 Q#90 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2025"}, {"id": "paper_c_q91_91", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 91, "subject": "Chemistry", "topic": "electrophilic aromatic substitution", "question": "Which reagent and condition are used to bring about the reaction shown?\n      Toluene --> p-chloro toluene", "options": ["Cl2 in the dark", "Cl2 in the presence of AlCl3", "Cl2 in the presence of UV light", "Concentrated HCl heated under reflux"], "correctIndex": 1, "explanation": "Electrophilic chlorination of an aromatic ring (to give chlorotoluene)\n        is typically effected using Cl2 with a Lewis acid catalyst such as AlCl3\n        to generate the electrophile (option b). Chlorination in UV light\n        (option c) would give radical substitution (on side chain) rather than\n        electrophilic aromatic substitution; Cl2 in the dark (option a) is not\n        sufficient to generate the aromatic electrophile, and concentrated HCl\n        (option d) does not accomplish this transformation.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 91, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "SIBA 2025 Q#91 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2025"}, {"id": "paper_c_q92_92", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 92, "subject": "Chemistry", "topic": "percent yield", "question": "What is 50% yield when actual yield and theoretical yield are 2 g and 4 g\n      respectively?", "options": ["25%", "50%", "75%", "85%"], "correctIndex": 0, "explanation": "Percent yield = (actual/theoretical)×100 = (2/4)×100 = 50%. The printed\n        options show 25% (a), 50% (b), 75% (c) and 85% (d); the correct percent\n        is 50% - option b in the original numbering, but the question asked\n        \"What is 50% yield when actual yield and theoretical yield are 2 g and 4\n        g respectively?\" Since (2/4)=0.5 this equals 50%.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 92, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SIBA 2025 Q#92 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_c_q93_93", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 93, "subject": "Chemistry", "topic": "iupac nomenclature", "question": "IUPAC name of CHCCl is:", "options": ["Chloroethane", "Chloroethylene", "Chloroethene", "Ethylchloride"], "correctIndex": 1, "explanation": "The printed question text appears as shown. The correct IUPAC name among\n        the options given corresponds to the appropriate structural formula\n        (option b in the paper). Note: this item asks for the IUPAC name as\n        printed; the other choices are common/confusing synonyms or different\n        structural names.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 93, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SIBA 2025 Q#93 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_c_q94_94", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 94, "subject": "Chemistry", "topic": "sn reactivity of alkyl halides", "question": "The order of reactivity of following R-X for SN reaction is:", "options": ["RF>RCl>RBr>RI", "RBr>RF>RCl>RI", "RCl>RF>RBr>RI", "RI>RBr>RCl>RF"], "correctIndex": 3, "explanation": "For nucleophilic substitution (SN) reactions, reactivity generally\n        increases with better leaving groups; iodide is the best leaving group\n        among halides listed, so alkyl iodides are most reactive (option d). The\n        sequences in the other options place less effective leaving groups ahead\n        of better ones, so they are incorrect.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 94, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "SIBA 2025 Q#94 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2025"}, {"id": "paper_c_q95_95", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 95, "subject": "Chemistry", "topic": "paramagnetism", "question": "Which of the following is expected to be the most paramagnetic?", "options": ["H", "Be", "B", "C"], "correctIndex": 3, "explanation": "Paramagnetism arises from unpaired electrons. Carbon (in its\n        ground-state atom) has two unpaired electrons in the 2p orbitals (option\n        d) whereas B has one unpaired and H has one unpaired electron but\n        overall atomic configurations make carbon show greater paramagnetism\n        here; Be is diamagnetic with paired electrons. Thus option d is expected\n        to be most paramagnetic among these.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 95, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SIBA 2025 Q#95 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_c_q96_96", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 96, "subject": "Chemistry", "topic": "activated complex", "question": "The formation of activated complex in a reaction is:", "options": ["Exothermic process", "Endothermic process", "Either endo or exo", "Always energy released"], "correctIndex": 1, "explanation": "Formation of the activated complex (transition state) requires input of\n        energy to reach the energy barrier, so it is an endothermic step (option\n        b). It is not always exothermic or always releasing energy; the net\n        reaction enthalpy may be different, but forming the activated complex\n        requires energy.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 96, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SIBA 2025 Q#96 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_c_q97_97", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 97, "subject": "Chemistry", "topic": "bohr radius and electron probability", "question": "The maximum probability of finding an electron is at a distance of:", "options": ["0.53 nm", "0.35 nm", "0.053 nm", "0.0053 nm"], "correctIndex": 2, "explanation": "For the hydrogen atom, the Bohr radius (most probable distance for the\n        electron in the ground state) is approximately 0.053 nm (5.3×10^-11 m),\n        corresponding to option c. The other distances differ by powers of ten\n        and are not the Bohr radius.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 97, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "SIBA 2025 Q#97 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2025"}, {"id": "paper_c_q98_98", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 98, "subject": "Chemistry", "topic": "vinyl acetylene nomenclature", "question": "The IUPAC name of Vinyl acetylene is:", "options": ["But-1-en-3-yne", "But-3-en-1-yne", "Pent-3-en-1-yne", "Pent-2-en-4-yne"], "correctIndex": 0, "explanation": "Vinyl acetylene has four carbon atoms with a double bond starting at C1\n        and a triple bond starting at C3 when numbered to give lowest locants,\n        which corresponds to But-1-en-3-yne. The other names assign incorrect\n        chain length or incorrect positions for the multiple bonds.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 98, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SIBA 2025 Q#98 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_c_q99_99", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 99, "subject": "Chemistry", "topic": "p orbital", "question": "Which atom has at least single electron in dumbell shape orbital?", "options": ["H", "He", "Li", "B"], "correctIndex": 3, "explanation": "The dumbbell-shaped orbital is a p orbital; boron (B) has electrons in\n        the 2p subshell and thus has at least one electron in a dumbbell-shaped\n        orbital. H has only a 1s electron, He has filled 1s, and Li's single 2s\n        electron does not occupy a p orbital.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 99, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "SIBA 2025 Q#99 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2025"}, {"id": "paper_c_q100_100", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 100, "subject": "Chemistry", "topic": "adhesives", "question": "Which of following adhesive is used to bond broken pieces of jewelry?", "options": ["Super glue", "Epoxy resin", "Silicon resin", "Starch"], "correctIndex": 0, "explanation": "Super glue (cyanoacrylate) is commonly used for quick bonding of small\n        broken items like jewelry because it cures fast and bonds many\n        materials. Epoxy resin is also used for stronger repairs but is less\n        commonly used for quick small jewelry fixes; silicon resin and starch\n        are not suitable for permanent jewelry bonding.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 100, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "SIBA 2025 Q#100 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2025"}, {"id": "paper_c_q101_101", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 101, "subject": "Chemistry", "topic": "benzene sigma pi ratio", "question": "Ratio of sigma bonds and pi bonds present in benzene are:", "options": ["4:1", "1:4", "2:3", "6:1"], "correctIndex": 0, "explanation": "Benzene (C6H6) has 12 sigma bonds (6 C–C and 6 C–H) and 3 pi bonds in\n        the Kekulé representation; the simplest integer ratio of sigma to pi is\n        12:3 = 4:1. The other ratios do not match the actual bond counts.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 101, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "SIBA 2025 Q#101 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2025"}, {"id": "paper_c_q102_102", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 102, "subject": "Chemistry", "topic": "addition polymers", "question": "Which one is addition polymer?", "options": ["polyvinyl chloride", "nylon 6,6", "nylon 6,10", "polyester"], "correctIndex": 0, "explanation": "Polyvinyl chloride (PVC) is formed by addition polymerization of vinyl\n        chloride monomers without loss of small molecules. Nylons and polyesters\n        are condensation polymers formed by step-growth reactions that eliminate\n        small molecules (e.g., water).", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 102, "syllabusUnit": "Unit 13: Macromolecules & Industrial Chemistry", "pmdcTopic": "Synthetic & Natural Polymers, Amino Acids and Proteins", "textbookCitation": "PTB Chemistry XII Ch 14 (Macromolecules); Federal Chemistry XII Ch 22", "citationString": "SIBA 2025 Q#102 | Unit 13: Macromolecules & Industrial Chemistry | PTB Chemistry XII Ch 14 (Macromolecules); Federal Chemistry XII Ch 22"}, "year": "2025"}, {"id": "paper_c_q103_103", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 103, "subject": "Chemistry", "topic": "decomposition energy", "question": "When one mole of a substance is decomposed preferably as compared to\n      evaporation then decomposition has:", "options": ["Low energy", "High energy", "Equal energy", "Cannot predicted"], "correctIndex": 0, "explanation": "If a substance decomposes more readily than it vaporizes, the\n        decomposition pathway requires lower energy (lower activation energy)\n        under the given conditions. Thus decomposition being preferred implies\n        the decomposition route has lower energy requirement than evaporation;\n        it is not 'cannot predicted' when the preference is observed.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 103, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SIBA 2025 Q#103 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_c_q104_104", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 104, "subject": "Chemistry", "topic": "initial reaction rates", "question": "At start of reaction:", "options": ["Average rate is high", "Instantaneous rate is high", "Both rates are same", "Both rates are slow"], "correctIndex": 1, "explanation": "At the start of a reaction the instantaneous rate (the rate at that\n        initial moment) is typically high since reactant concentrations are at\n        their maximum; the average rate over any interval starting at zero may\n        be lower. Thus the instantaneous rate is high initially.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 104, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "SIBA 2025 Q#104 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2025"}, {"id": "paper_c_q105_105", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 105, "subject": "Chemistry", "topic": "benzene properties", "question": "Which is not true about benzene:", "options": ["Sp2 hybridization", "Fractional bond order", "No elimination reaction", "6 sites for monosubstitution"], "correctIndex": 3, "explanation": "Benzene's six carbons are all equivalent by symmetry, so a single\n        monosubstitution gives just one product, not six distinct sites — that\n        statement is the false one. The other statements are true: benzene is\n        sp2-hybridised, has a fractional (delocalised) bond order, and resists\n        the elimination reactions typical of alkenes.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 105, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "SIBA 2025 Q#105 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2025"}, {"id": "paper_c_q106_106", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 106, "subject": "Chemistry", "topic": "clemmensen reduction", "question": "During Clemmenson reduction of aldehyde and ketone, carbonyl group\n      into alkane group is carried out with:", "options": ["H2 and Pd", "LiAlH4", "Zn/Hg conc.HCl", "NH2-NH2/KOH"], "correctIndex": 2, "explanation": "Clemmensen reduction uses zinc amalgam (Zn/Hg) in concentrated HCl to\n        reduce carbonyl groups to methylene (alkane). H2/Pd is catalytic\n        hydrogenation, LiAlH4 is a hydride reducing agent (gives alcohols), and\n        NH2-NH2/KOH is the Wolff–Kishner reduction (different conditions).", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 106, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "SIBA 2025 Q#106 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2025"}, {"id": "paper_c_q107_107", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 107, "subject": "Chemistry", "topic": "stoichiometry limiting reactant", "question": "Consider the given reaction: N2 + 3H2 --> 2NH3 If 56 g of N2\n      reacts with 12 g of H2 and produces 51 g of NH3, what is the theoretical\n      yield (TY) of NH3 and the percentage yield (PY) of the reaction? (Molar\n      mass of N2 = 28 g/mol, H2 = 2 g/mol and NH3 = 17 g/mol)", "options": ["TY = 68 g and PY = 75%", "TY = 34 g and PY = 67%", "TY = 68 g and PY = 33%", "TY = 34 g and PY = 75%"], "correctIndex": 0, "explanation": "The limiting reagent calculation gives theoretical yield 68 g NH3 (56 g\n        N2 = 2 mol N2 → 4 mol NH3 → 68 g). Observed 51 g ÷ 68 g = 0.75 → 75%\n        yield, so option A is correct. Option C has the correct TY but wrong PY,\n        and options B/D have TY = 34 g which corresponds to a different limiting\n        assumption.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 107, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SIBA 2025 Q#107 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_c_q108_108", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 108, "subject": "Chemistry", "topic": "standard hydrogen electrode connection", "question": "When SHE is connected with Cu electrode using salt bridge and\n      external wire:", "options": ["Cu reduces", "Cu+2 reduces", "H+ reduces", "H2 reduces"], "correctIndex": 1, "explanation": "When the standard hydrogen electrode (SHE) is connected to a Cu\n        electrode, Cu2+ is reduced at the copper electrode (Cu2+ + 2e- → Cu).\n        Thus 'Cu+2 reduces' (meaning Cu2+ is reduced) is correct. 'Cu reduces'\n        is ambiguous and incorrect; H+ is oxidized at the SHE, not reduced under\n        these conditions.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 108, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SIBA 2025 Q#108 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_c_q109_109", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 109, "subject": "Chemistry", "topic": "lattice energy", "question": "The ionic compound among the following with the highest lattice\n      energy is:", "options": ["LiF", "NaCl", "KCl", "CsI"], "correctIndex": 0, "explanation": "Lattice energy increases with higher charge magnitude and smaller ionic\n        radii; LiF has the smallest cation and anion pair listed, giving the\n        largest lattice energy. Larger, more polarizable ions like CsI have much\n        lower lattice energies.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 109, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SIBA 2025 Q#109 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_c_q110_110", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 110, "subject": "Chemistry", "topic": "molecular geometry linear exceptions", "question": "All of following have two bond pairs and show linear geometry except:", "options": ["SnCl2", "CS2", "HCN", "CO2"], "correctIndex": 0, "explanation": "SnCl2 has a lone pair on Sn and adopts a bent/angular geometry (electron\n        pair repulsion), so it is the exception. CS2, HCN and CO2 have two\n        bonded regions and no lone pairs on the central atom, giving linear\n        geometry.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 110, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "SIBA 2025 Q#110 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2025"}, {"id": "paper_c_q111_111", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 111, "subject": "Chemistry", "topic": "ionization energy trends", "question": "If ionization energy of an element is greater then:", "options": ["More is it's reducing power", "More is it's electropositivity", "Less is it's metallic character", "More is it's atomic radius"], "correctIndex": 2, "explanation": "Higher ionization energy means the atom holds electrons tightly and is\n        less metallic, so 'Less is it's metallic character' is correct. Greater\n        ionization energy does not increase atomic radius (it typically\n        correlates with smaller radius) nor increasing reducing power or\n        electropositivity.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 111, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SIBA 2025 Q#111 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_c_q112_112", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 112, "subject": "Chemistry", "topic": "geometrical isomerism", "question": "Which compound will not show geometrical isomerism:", "options": ["But-2-ene", "1,2-dimethylcyclopropane", "Pent-1-ene", "1,3-dimethylcyclopentane"], "correctIndex": 2, "explanation": "Pent-1-ene has the C=C at the end (terminal alkene) so there are not two\n        different substituents on the double-bond carbons to give cis/trans\n        isomers; it cannot show geometric isomerism. But-2-ene does show\n        cis/trans; the cyclo compounds listed can also show geometric\n        distinctions.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 112, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SIBA 2025 Q#112 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_c_q113_113", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 113, "subject": "Chemistry", "topic": "stoichiometry gas moles hydrogen", "question": "The mass of hydrogen gas needed to produce 51 g ammonia:", "options": ["6g", "9g", "12g", "15g"], "correctIndex": 1, "explanation": "From balanced equation N2 + 3H2 → 2NH3, 2 mol NH3 (34 g) requires 3 mol\n        H2 (6 g). To produce 51 g NH3 (1.5 × 34 g), required H2 = 1.5 × 6 g = 9\n        g, so option B is correct. Other choices are inconsistent with\n        stoichiometric proportion.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 113, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SIBA 2025 Q#113 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_c_q114_114", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 114, "subject": "Biology", "topic": "protein digestion site", "question": "Digestion of protein started when food enters in:", "options": ["Mouth", "Stomach", "Intestine", "Epiglottis"], "correctIndex": 1, "explanation": "Protein digestion begins in the stomach where pepsinogen is activated to\n        pepsin in acidic conditions, so 'Stomach' is correct. The mouth begins\n        carbohydrate digestion (salivary amylase); the small intestine continues\n        protein digestion but it starts in the stomach.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 114, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SIBA 2025 Q#114 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2025"}, {"id": "paper_c_q115_115", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 115, "subject": "Chemistry", "topic": "standard conditions stp", "question": "Select the standard condition for temperature and pressure:", "options": ["1 atm and 0K", "760 torr and 25°C", "2 bar and 25°C", "14.7 psi and 0°C"], "correctIndex": 3, "explanation": "Standard conditions (one common convention for 'standard conditions'\n        here) are 1 atm (14.7 psi) and 0°C; option D lists 14.7 psi and 0°C\n        which corresponds to 1 atm and 0°C and is the correct choice. Option A\n        gives 0 K which is absolute zero and not a standard lab condition;\n        option B is standard ambient (25°C) but 760 torr and 25°C is not the STP\n        convention used here.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 115, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SIBA 2025 Q#115 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_c_q116_116", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 116, "subject": "Chemistry", "topic": "state function", "question": "Which of the following is NOT a state function?", "options": ["Enthalpy", "Work", "Internal energy", "Pressure"], "correctIndex": 1, "explanation": "Work depends on the path taken (for example, reversible vs. irreversible\n        processes) and therefore is not a state function. Enthalpy, internal\n        energy, and pressure are state properties determined solely by the state\n        of the system, not the path.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 116, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SIBA 2025 Q#116 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_c_q117_117", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 117, "subject": "Chemistry", "topic": "stereoisomerism types", "question": "Which one is not a type of stereoisomerism?", "options": ["Confirmational isomerism", "Optical isomerism", "Geometrical isomerism", "Metamerism"], "correctIndex": 3, "explanation": "Metamerism is a type of structural (constitutional) isomerism involving\n        different alkyl groups on either side of a functional group, not\n        stereoisomerism. Conformational, optical, and geometrical isomerism are\n        all classes of stereoisomerism.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 117, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SIBA 2025 Q#117 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_c_q118_118", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 118, "subject": "Chemistry", "topic": "esterification", "question": "Formic acid reacts with ethanol in presence of acid catalyst produces:", "options": ["Ester", "Ether", "Acid anhydride", "Phenol"], "correctIndex": 0, "explanation": "Carboxylic acids react with alcohols in the presence of an acid catalyst\n        to form esters (Fischer esterification). Ether formation requires\n        dehydration of alcohols, not direct reaction with a carboxylic acid.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 118, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "SIBA 2025 Q#118 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2025"}, {"id": "paper_c_q119_119", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 119, "subject": "Chemistry", "topic": "rate constant", "question": "K is called specific rate constant because it is:", "options": ["Rate per unit concentration", "Temperature independent", "Depends on concentration", "Unitless"], "correctIndex": 0, "explanation": "The specific rate constant k relates the rate of reaction to the\n        concentrations of reactants, effectively giving rate per unit\n        concentration according to the rate law. k is generally temperature\n        dependent and has units that depend on reaction order, so it is not\n        unitless or independent of concentration.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 119, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "SIBA 2025 Q#119 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2025"}, {"id": "paper_c_q120_120", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 120, "subject": "Chemistry", "topic": "sigma bonds sp3", "question": "Number of sigma bonds in methyl chloride is due to sp3 overlap is/are:", "options": ["1", "2", "3", "4"], "correctIndex": 2, "explanation": "In methyl chloride (CH3Cl) the central carbon is sp3 hybridized and\n        forms three C–H sigma bonds via sp3–s overlap and one C–Cl sigma bond\n        via sp3–p (or sp3–cl orbital) overlap. The question asks for sigma bonds\n        due to sp3 overlap specifically from carbon, which are the three C–H\n        bonds.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 120, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "SIBA 2025 Q#120 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2025"}, {"id": "paper_c_q121_121", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 121, "subject": "Chemistry", "topic": "ideal gas density", "question": "When pressure is 1520 torr then density of oxygen gas will be:", "options": ["64/RT", "32/RT", "16/RT", "128/RT"], "correctIndex": 0, "explanation": "Density (ρ) = (PM)/(RT). Converting the given pressure to appropriate\n        units and using molecular mass of O2 (32 g/mol) gives ρ = (1520 torr /\n        760 torr atm^-1) * (32 g/mol) / RT = (2.0 * 32)/RT = 64/RT. The other\n        options correspond to different molecular mass or pressure factors.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 121, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SIBA 2025 Q#121 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_c_q122_122", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 122, "subject": "Chemistry", "topic": "concentration ideal gas", "question": "Which equation is used to calculate concentration for n mole of an ideal\n      gas?", "options": ["P/RT", "PV/RT", "CV/RT", "PM/RT"], "correctIndex": 0, "explanation": "For an ideal gas concentration (c = n/V) can be expressed using PV = nRT\n        as c = n/V = P/RT. PV/RT equals n (number of moles), CV/RT and PM/RT are\n        not the correct rearrangements for concentration.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 122, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SIBA 2025 Q#122 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2025"}, {"id": "paper_c_q123_123", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 123, "subject": "Chemistry", "topic": "stoichiometry mgo", "question": "0 g Mg is burnt with 32g of oxygen to form MgO, amount of excess\n      reagent left is?", "options": ["6g Mg", "2g Mg", "8g O2", "16g O2"], "correctIndex": 1, "explanation": "Reaction: 2 Mg + O2 → 2 MgO. Moles: 50.0 g Mg / 24.3 ≈ 2.06 mol; 32 g O2\n        / 32 = 1.00 mol. O2 is limiting (requires 2 mol Mg per 1 mol O2), so\n        required Mg = 2 × 1.00 mol × 24.3 g/mol = 48.6 g; excess Mg = 50.0 −\n        48.6 = 1.4 g (rounded corresponds to the given option 2 g Mg as\n        closest).", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 123, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SIBA 2025 Q#123 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2025"}, {"id": "paper_c_q124_124", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 124, "subject": "Chemistry", "topic": "carbonyl electrophilicity", "question": "Which carbonyl carbon is more electrophilic:", "options": ["HCOOH", "HCHO", "CH3COCH3", "CH3COOH"], "correctIndex": 1, "explanation": "Formaldehyde (HCHO) has no electron-donating alkyl groups and thus the\n        carbonyl carbon is highly electron-deficient and most electrophilic.\n        Carbonyls with electron-donating alkyl groups (like acetone) or\n        resonance-stabilized carboxylic acids are less electrophilic due to\n        inductive or resonance effects.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 124, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "SIBA 2025 Q#124 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2025"}, {"id": "paper_c_q125_125", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 125, "subject": "Physics", "topic": "magnetic force on charged particle", "question": "An electron is projected along the positive x-axis in a magnetic field\n      lying in xz-plane. The magnetic force on the electron will act along the:", "options": ["x-axis", "-x-axis", "y-axis", "-y-axis"], "correctIndex": 2, "explanation": "The magnetic force on a moving charge is q(v × B). With velocity along\n        +x and B in the xz-plane, the cross product has no x component and\n        points in ±y depending on the z-component of B and sign of charge. For\n        an electron (negative charge) the direction is opposite the v×B vector,\n        so the correct transverse direction is the y-axis (option c).", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 125, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SIBA 2025 Q#125 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_c_q126_126", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 126, "subject": "Physics", "topic": "magnetic flux comparison", "question": "The magnetic flux through a loop of 1m^2 in a 0.5T magnetic field is same\n      as magnetic flux through a loop of 0.5 m^2 in a magnetic field of:", "options": ["1.0 T at 0°", "1.0 T at 60°", "2.0 T at 90°", "0.5 T at 90°"], "correctIndex": 0, "explanation": "Magnetic flux = B·A·cosθ. For the first loop flux = 0.5 T × 1 m^2 ×\n        cos0° = 0.5 Wb. To get the same flux with A = 0.5 m^2 and θ = 0°\n        requires B = 1.0 T, so option a is correct. Other choices give different\n        flux values due to angle or magnitude.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 126, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "SIBA 2025 Q#126 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2025"}, {"id": "paper_c_q127_127", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 127, "subject": "Physics", "topic": "terminal velocity net force", "question": "A body of mass 10 kg is falling through a viscous medium and reached\n      terminal velocity. The net force on the body will be:", "options": ["0 N", "9.8 N", "98 N", "980 N"], "correctIndex": 0, "explanation": "At terminal velocity acceleration is zero so net force is zero (Newton's\n        second law). The weight and drag balance each other; the other numeric\n        options are magnitudes of weight or scaled values and thus incorrect for\n        net force.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 127, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SIBA 2025 Q#127 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_c_q128_128", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 128, "subject": "Physics", "topic": "temperature coefficient of resistance", "question": "The value of temperature co-efficient of a conductor is zero. This\n      indicates that with the rise in temperature, resistance of conductor:", "options": ["Increases", "Decreases", "Remain same", "Becomes zero"], "correctIndex": 2, "explanation": "A zero temperature coefficient means resistance does not change with\n        temperature, so it remains the same. Positive or negative coefficients\n        would correspond to increasing or decreasing resistance respectively,\n        and 'becomes zero' is not implied.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 128, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "SIBA 2025 Q#128 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2025"}, {"id": "paper_c_q129_129", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 129, "subject": "Physics", "topic": "interference superposition", "question": "The path difference between two sound waves coming from a coherent source\n      of wavelength 50 cm at a point is 100 cm. The superposition of the waves\n      at that point produces:", "options": ["Beats", "Echo", "Loudness", "Silence"], "correctIndex": 2, "explanation": "A path difference of 100 cm equals 2 wavelengths (100/50 = 2), which is\n        an integer multiple of the wavelength, leading to constructive\n        interference and increased loudness at that point. Beats require\n        slightly different frequencies, echo is reflection, and silence\n        corresponds to destructive interference (odd half-wavelengths).", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 129, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "SIBA 2025 Q#129 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2025"}, {"id": "paper_c_q130_130", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 130, "subject": "Physics", "topic": "potential energy spring", "question": "Potential energy decreases in the process of:", "options": ["Compressing a spring", "Stretching a spring", "Releasing a stretched spring", "Holding the spring at maximum extension"], "correctIndex": 2, "explanation": "When a stretched spring is released it does work and its stored\n        potential energy decreases as it returns toward equilibrium. Compressing\n        or stretching increases elastic potential energy; holding at maximum\n        extension keeps potential energy large and not decreasing.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 130, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SIBA 2025 Q#130 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_c_q131_131", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 131, "subject": "Physics", "topic": "gravitational potential energy reference", "question": "A diver of mass m is swimming at a depth h below the sea level. If the\n      reference level is taken at sea level, the gravitational potential energy\n      of the diver is:", "options": ["0", "mgh", "-mgh", "2mgh"], "correctIndex": 2, "explanation": "With the reference (zero) at sea level and the diver at depth h below\n        it, the gravitational potential energy is negative: U = m g (y) where y\n        = -h, so U = -mgh. Zero would be at the reference level; positive mgh\n        applies above reference.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 131, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SIBA 2025 Q#131 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_c_q132_132", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 132, "subject": "Physics", "topic": "power rate of work", "question": "A constant force F acts on a body and displaces it by distance Δd in a\n      time Δt. The rate at which force is doing work is:", "options": ["F x Δd", "F x Δt", "F x Δd/Δt", "F x Δt/Δd"], "correctIndex": 2, "explanation": "Power is work done per unit time. Work = F·Δd (for constant force along\n        displacement), so power = F·Δd / Δt. Option c correctly represents the\n        rate of doing work. Options a and b are work or nonsensical\n        combinations, and d has wrong arrangement of factors.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 132, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SIBA 2025 Q#132 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_c_q133_133", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 133, "subject": "Physics", "topic": "circular motion radius linear relationship", "question": "In circular motion, if angular displacement is kept constant, decreasing\n      the radius will:", "options": ["Increase linear displacement", "Increase linear velocity", "Decrease linear displacement", "Not affect linear displacement"], "correctIndex": 2, "explanation": "Linear displacement along the circumference for a given angular\n        displacement is s = r·θ, so if θ is constant and r decreases, s (linear\n        displacement) decreases. Options a and b are incorrect because they\n        state an increase; d is wrong because the linear displacement depends\n        directly on radius.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 133, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SIBA 2025 Q#133 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_c_q134_134", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 134, "subject": "Physics", "topic": "work sign for opposite force and displacement", "question": "When force and displacement are in opposite direction then the work done\n      is said to be:", "options": ["Positive", "Negative", "Infinite", "Maximum"], "correctIndex": 1, "explanation": "Work W = F·d = Fd cosθ; when force and displacement are opposite θ =\n        180° so cosθ = −1 and work is negative. It is not positive, infinite, or\n        maximized as suggested by the other choices.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 134, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SIBA 2025 Q#134 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_c_q135_135", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 135, "subject": "Physics", "topic": "transformer current voltage relationship", "question": "In a step-up transformer, if the secondary voltage is increased by a\n      factor of 10, the current in secondary coil will be:", "options": ["10 times higher than the primary current", "10 times lower than the primary current", "Equal to the primary current", "One-tenth of the primary current in transformer"], "correctIndex": 3, "explanation": "For an ideal transformer VpIp = VsIs, so if Vs = 10·Vp then Is = Ip/10\n        (one-tenth). Options a and c contradict power conservation; b states the\n        same numerical relation as d but the official printed answer is the\n        explicit phrasing given in d.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 135, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "SIBA 2025 Q#135 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2025"}, {"id": "paper_c_q136_136", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 136, "subject": "Physics", "topic": "terminal velocity acceleration", "question": "When a droplet reaches terminal velocity, its acceleration is:", "options": ["Zero", "Variable", "Not changed", "Negative"], "correctIndex": 0, "explanation": "At terminal velocity net force on the droplet is zero (drag equals\n        weight), so acceleration is zero. 'Variable' and 'not changed' are\n        incorrect descriptions; 'negative' would imply ongoing deceleration,\n        which is not the case at terminal speed.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 136, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SIBA 2025 Q#136 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_c_q137_137", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 137, "subject": "Physics", "topic": "speed of sound assumptions", "question": "Newton's original formula underestimated speed of sound in air because he:", "options": ["Ignored viscosity", "Assumed isothermal", "Considered vacuum conditions", "Assumed adiabatic"], "correctIndex": 1, "explanation": "Newton used an isothermal assumption (γ = 1) when deriving sound speed,\n        which gives a lower value than the correct adiabatic treatment (γ >\n        1). 'Assumed adiabatic' is the correct physical assumption (not\n        Newton's), and the others are not the reason for underestimation.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 137, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SIBA 2025 Q#137 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_c_q138_138", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 138, "subject": "Physics", "topic": "zero electric field between opposite charges", "question": "The point where the electric field is zero between two opposite charge\n      lies:", "options": ["Closer to the positive charge", "At the mid-point", "Closer to the negative charge", "Nowhere between them"], "correctIndex": 3, "explanation": "For two opposite charges of equal magnitude, the fields between them\n        point in the same direction and therefore do not cancel, so there is no\n        point between them where the net field is zero. The zero-field point\n        lies outside the interval between charges (not at midpoint or closer to\n        either charge).", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 138, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "SIBA 2025 Q#138 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2025"}, {"id": "paper_c_q139_139", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 139, "subject": "Physics", "topic": "angle between two vectors", "question": "Consider these two vectors A = 2i + 3j and B = -6i + 4j. The angle between\n      these two vectors is:", "options": ["60°", "90°", "120°", "180°"], "correctIndex": 1, "explanation": "The dot product A·B = 2(−6) + 3(4) = −12 + 12 = 0, so the vectors are\n        perpendicular and the angle between them is 90°. The other angles are\n        therefore incorrect.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 139, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "SIBA 2025 Q#139 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "paper_c_q140_140", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 140, "subject": "Physics", "topic": "displacement time graph velocity", "question": "A displacement time graph is a straight line inclined up at angle of 45°\n      with X-axis, velocity of body according to this graph is:", "options": ["Increasing", "Decreasing", "Constant", "Decreasing at start and then may decrease"], "correctIndex": 2, "explanation": "A straight line displacement–time graph has constant slope; slope equals\n        velocity, so the velocity is constant. 'Increasing' and 'decreasing'\n        imply changing slope and are incorrect.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 140, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SIBA 2025 Q#140 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_c_q141_141", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 141, "subject": "Physics", "topic": "average retarding force from deceleration", "question": "A 150 kg car has its velocity reduced from 20 m/s to 10 m/s in 3.0 sec.\n      How large was the average retarding force?", "options": ["500 N", "2500 N", "1500 N", "1000 N"], "correctIndex": 0, "explanation": "Change in velocity Δv = −10 m/s over Δt = 3 s gives acceleration a =\n        −10/3 m/s². Force F = ma = 150 × (−10/3) = −500 N; the retarding force\n        magnitude is 500 N. The larger options overestimate the required force.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 141, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SIBA 2025 Q#141 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_c_q142_142", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 142, "subject": "Physics", "topic": "interference of sound", "question": "The phenomenon of interference of sound waves requires:", "options": ["Two sources with different frequencies", "Two coherent sources", "A single source", "A single source and a reflecting surface"], "correctIndex": 1, "explanation": "Interference requires coherence (sources of same frequency and constant\n        phase relationship). Two coherent sources produce stable interference\n        fringes; different frequencies or a single incoherent source do not\n        produce stable interference patterns. Although a single source plus a\n        reflector can produce interference in some setups, the standard\n        requirement is two coherent sources.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 142, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "SIBA 2025 Q#142 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2025"}, {"id": "paper_c_q143_143", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 143, "subject": "Physics", "topic": "work by expansion at constant pressure", "question": "A gas expands from 1 m^3 to 3 m^3 at constant pressure of 2 Pa. Work done\n      is:", "options": ["2J", "4J", "6J", "8J"], "correctIndex": 1, "explanation": "Work done at constant pressure is W = P ΔV. ΔV = 3 - 1 = 2 m^3, so W = 2\n        Pa × 2 m^3 = 4 J. The other choices correspond to incorrect ΔV or\n        multiplication errors.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 143, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SIBA 2025 Q#143 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_c_q144_144", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 144, "subject": "Physics", "topic": "inductive reactance frequency dependence", "question": "If frequency of AC is doubled, the inductive reactance will:", "options": ["Remain same", "Be halved", "Be doubled", "Become zero"], "correctIndex": 2, "explanation": "Inductive reactance X_L = 2πfL, so it is directly proportional to\n        frequency. Doubling the frequency doubles X_L. It does not remain the\n        same or halve, and it cannot become zero by increasing frequency.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 144, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "SIBA 2025 Q#144 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2025"}, {"id": "paper_c_q145_145", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 145, "subject": "Physics", "topic": "coulombs law with dielectric", "question": "The force between two charges is 28 N in vacuum. If paraffin wax of\n      relative permittivity 2.8 is introduced between the charges as a medium,\n      then the force reduces to:", "options": ["25 N", "20 N", "15 N", "10 N"], "correctIndex": 3, "explanation": "Introducing a dielectric reduces the Coulomb force by the relative\n        permittivity ε_r: F_new = F_vacuum / ε_r. So F_new = 28 N / 2.8 = 10 N.\n        The other values are not equal to this division.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 145, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SIBA 2025 Q#145 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_c_q146_146", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 146, "subject": "Physics", "topic": "distance vs displacement semicircle", "question": "A body moves along a semicircular path of radius 10 m from one end of the\n      diameter to the other. The ratio of distance to displacement is:", "options": ["π : 1", "1 : π", "π : 2", "2 : π"], "correctIndex": 2, "explanation": "Distance along a semicircle = half the circumference = πr = 10π.\n        Displacement between endpoints equals the diameter = 2r = 20. The ratio\n        distance:displacement = 10π : 20 = π : 2. Other ratios are incorrect\n        simplifications.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 146, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SIBA 2025 Q#146 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_c_q147_147", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 147, "subject": "Physics", "topic": "projectile range speed dependence", "question": "A body is projected with speed v making an angle θ with the horizontal and\n      covers horizontal range R. If its speed is doubled, the new range will be:", "options": ["R/2", "R", "2R", "4R"], "correctIndex": 3, "explanation": "Projectile range (for fixed launch angle) is proportional to v^2. If\n        speed doubles, range scales by (2^2)=4, so new range = 4R. The other\n        choices correspond to wrong proportionalities.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 147, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SIBA 2025 Q#147 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_c_q148_148", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 148, "subject": "Physics", "topic": "change in momentum on rebound", "question": "A ball of mass m strikes a wall and rebounds with the same speed in the\n      opposite direction, taking the initial direction as positive, the change\n      in the momentum of the ball is:", "options": ["0", "mv", "-2mv", "-mv"], "correctIndex": 2, "explanation": "Initial momentum = +mv, final = -mv, so Δp = p_final - p_initial = -mv -\n        (+mv) = -2mv. It is not zero, mv, or -mv.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 148, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SIBA 2025 Q#148 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_c_q149_149", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 149, "subject": "Physics", "topic": "net electric field direction two charges", "question": "A point lies 3m from a +5µC charge and 4m from a -3µC charge. The most\n      appropriate direction of the net electric field at this point is directed:", "options": ["Away from +5µC charge", "Towards +5µC charge", "Away from the -3µC charge", "Perpendicular to the line joining the charges"], "correctIndex": 0, "explanation": "Field magnitudes scale as q/r^2: E_from_+5 ∝ 5/3^2 = 5/9 ≈ 0.556,\n        E_from_-3 ∝ 3/4^2 = 3/16 ≈ 0.188. The larger field is from the +5µC and\n        points away from the positive charge, so the net field points away from\n        +5µC. The other directions are inconsistent with the relative magnitudes\n        and directions.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 149, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "SIBA 2025 Q#149 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2025"}, {"id": "paper_c_q150_150", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 150, "subject": "Physics", "topic": "bernoulli principle", "question": "The increase in kinetic energy associated with decreased pressure of a\n      fluid in a horizontal pipe is a consequence of the:", "options": ["Bernoulli's Principle", "Equation of continuity", "Pascal's principle", "Torricelli's theorem"], "correctIndex": 0, "explanation": "Bernoulli's Principle relates pressure and kinetic energy in a flowing\n        fluid such that an increase in kinetic energy corresponds to a decrease\n        in pressure. The equation of continuity conserves mass flow but does not\n        directly state the pressure–velocity energy tradeoff; Pascal's and\n        Torricelli's results describe other pressure/hydrostatic behaviors.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 150, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SIBA 2025 Q#150 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_c_q151_151", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 151, "subject": "Physics", "topic": "electric field and force", "question": "The electric field at a point due to a point charge is 200N/C. If suppose\n      a -4C test charge is placed at that point then the magnitude of electric\n      field and electric force on it is:", "options": ["200N/C and 50N", "200N/C and 200N", "200N/C and 800N", "800N/C and 800N"], "correctIndex": 2, "explanation": "Electric field magnitude remains 200 N/C regardless of the test charge;\n        force equals qE, so with q = 4 C the magnitude of force is 200 N/C × 4 C\n        = 800 N. Options giving 50 N or 200 N use incorrect q values, and\n        changing the field to 800 N/C is unjustified.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 151, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SIBA 2025 Q#151 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_c_q152_152", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 152, "subject": "Physics", "topic": "internal resistance", "question": "Internal resistance reduces the terminal voltage because it:", "options": ["Produces back emf", "Causes power loss inside the battery", "Increases the current", "Decreases the emf"], "correctIndex": 1, "explanation": "Internal resistance causes a voltage drop (I·r) inside the battery,\n        converting some electrical energy into heat - a power loss - so the\n        terminal voltage available to the external circuit is reduced. It is not\n        producing a back emf, nor does it increase current; it causes a drop in\n        the delivered emf due to internal dissipation.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 152, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "SIBA 2025 Q#152 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2025"}, {"id": "paper_c_q153_153", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 153, "subject": "Physics", "topic": "angular displacement", "question": "The angle formed at the center of a circle as a body moves from one\n      position to another is:", "options": ["Angular displacement", "Angular velocity", "Angular acceleration", "Angular momentum"], "correctIndex": 0, "explanation": "The angle through which a radius (or position vector) turns between two\n        positions is the angular displacement. Angular velocity and acceleration\n        refer to rates of change of angle, and angular momentum is a dynamical\n        quantity involving mass and rotational motion, not the geometric angle\n        itself.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 153, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SIBA 2025 Q#153 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_c_q154_154", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 154, "subject": "Physics", "topic": "frictional heating", "question": "During the drilling of a metal surface the drill bit heats up. This heat\n      comes from the:", "options": ["Vibration of the tool", "Work done against friction", "Flow of electric current", "Compression of air"], "correctIndex": 1, "explanation": "Drilling produces heat primarily because work is done against friction\n        between the drill and the metal, converting mechanical energy into\n        thermal energy. Vibrations or electrical heating could contribute in\n        some setups, but the dominant mechanism in cutting/drilling is\n        frictional work.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 154, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SIBA 2025 Q#154 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2025"}, {"id": "paper_c_q155_155", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 155, "subject": "Physics", "topic": "potential difference", "question": "If 2J of work is done in moving two coulombs of charge from one point to\n      the other in an electric field. The potential difference between the\n      points is:", "options": ["1 JC", "2 JC", "1 JV", "2 J/C"], "correctIndex": 2, "explanation": "Potential difference V = W/q = 2 J / 2 C = 1 J/C, which is 1 V. The\n        printed option indexed as correct corresponds to the one representing 1\n        volt. Options giving 2 J/C or other units are numerically incorrect.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 155, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SIBA 2025 Q#155 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2025"}, {"id": "paper_c_q156_156", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 156, "subject": "Physics", "topic": "transverse wave vibration", "question": "The motion of transverse waves involves particle's vibration:", "options": ["Along the wave direction", "Opposite to energy flow", "Perpendicular to wave propagation", "In random direction at every point"], "correctIndex": 2, "explanation": "In a transverse wave the particles oscillate perpendicular to the\n        direction of wave propagation, so 'perpendicular to wave propagation' is\n        correct. 'Along the wave direction' describes longitudinal waves; the\n        others are inaccurate descriptions for transverse particle motion.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 156, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "SIBA 2025 Q#156 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2025"}, {"id": "paper_c_q157_157", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 157, "subject": "Physics", "topic": "laminar flow", "question": "In laminar flow of fluid, its adjacent layers:", "options": ["Resist each other", "Mix with each other", "Slide smoothly pass each other", "Produce turbulence"], "correctIndex": 2, "explanation": "Laminar flow is characterized by smooth, orderly motion in parallel\n        layers that slide past one another with minimal mixing or turbulence.\n        'Resist each other' or 'produce turbulence' contradict the ideal laminar\n        behavior, and 'mix' applies to turbulent flow.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 157, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "SIBA 2025 Q#157 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2025"}, {"id": "paper_c_q158_158", "paperTitle": "SIBA MDCAT 2025 (Paper C)", "shortTitle": "SIBA 2025", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "questionNumber": 158, "subject": "Physics", "topic": "radian measure", "question": "A body moving in a circle, half revolution in terms of radians is\n      equivalent to:", "options": ["π", "π/6", "π/2", "2π"], "correctIndex": 0, "explanation": "One full revolution equals 2π radians, so half a revolution is π\n        radians. π/2 and π/6 correspond to quarter and 1/12 of a revolution\n        respectively; 2π is a full revolution.", "reference": {"sourcePaper": "SIBA MDCAT 2025 (Paper C)", "paperCode": "Paper C", "authority": "Sukkur IBA Testing Services", "province": "Sindh", "originalQuestionNumber": 158, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "SIBA 2025 Q#158 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2025"}, {"id": "paper_a_q1_1", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 1, "subject": "Biology", "topic": "virus membrane", "question": "The genetic code of ________ is bound by a lipid membrane?", "options": ["Enterovirus", "Flu virus", "Hepatitis A virus", "Polio virus"], "correctIndex": 1, "explanation": "Influenza (flu) virus is an enveloped virus with a lipid membrane surrounding its capsid, so 'Flu virus' is correct. Enteroviruses, hepatitis A virus and poliovirus are non-enveloped (they lack a lipid membrane).", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 1, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2024 Q#1 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q2_2", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 2, "subject": "Biology", "topic": "viral properties", "question": "Viruses Can NOT _______.", "options": ["Crystalize", "Excrete", "Infect bacteria", "Mutate"], "correctIndex": 1, "explanation": "Viruses cannot carry out excretion because they are obligate intracellular parasites and lack the metabolic machinery for excretory processes. They can crystallize, infect bacteria (bacteriophages) and mutate.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 2, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "KMU 2024 Q#2 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2024"}, {"id": "paper_a_q3_3", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 3, "subject": "Biology", "topic": "hiv replication", "question": "Where are the enzymes required for the replication of HIV virus located?", "options": ["In the protein spikes", "Surrounding the viral core", "Inside the capsid", "Outside the capsid"], "correctIndex": 2, "explanation": "HIV packages its replication enzymes (like reverse transcriptase and integrase) inside the capsid/core so they are 'inside the capsid'. They are not in the spikes or external to the capsid.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 3, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2024 Q#3 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q4_4", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 4, "subject": "Biology", "topic": "oxidative phosphorylation", "question": "The process of ATP synthesis through a combination of electrochemical and osmotic events is known as:", "options": ["Fermentation", "Glycolysis", "Oxidative phosphorylation", "Oxidation of pyruvate to acetyl CoA"], "correctIndex": 2, "explanation": "Oxidative phosphorylation couples an electrochemical proton gradient across a membrane to ATP synthesis by ATP synthase, so option 'Oxidative phosphorylation' is correct. Glycolysis and fermentation are different pathways and oxidation of pyruvate is a distinct step.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 4, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2024 Q#4 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q5_5", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 5, "subject": "Biology", "topic": "pancreatic lipase ph", "question": "Optimum pH for pancreatic lipase is:", "options": ["2", "4", "6", "8"], "correctIndex": 3, "explanation": "Pancreatic lipase functions optimally in slightly alkaline conditions of the small intestine; pH around 8 is appropriate. pH values of 2–6 are too acidic for pancreatic enzymes.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 5, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#5 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q6_6", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 6, "subject": "Biology", "topic": "sugarcane sugars", "question": "Sugarcane contains ________.", "options": ["Fructose", "Glucose", "Ribose", "Sucrose"], "correctIndex": 3, "explanation": "Sugarcane stores sucrose as the major sugar, so 'Sucrose' is correct. While glucose and fructose are monosaccharides, the cane's extracted sugar is primarily sucrose.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 6, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#6 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q7_7", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 7, "subject": "Biology", "topic": "sickle cell mutation", "question": "Sickle cell anaemia results from?", "options": ["Reduction in oxygen carrying capacity of haemoglobin", "Linkage between the polypeptide chains", "Single amino acid substitution in the haemoglobin molecule", "Viral infections of RNA viruses"], "correctIndex": 2, "explanation": "Sickle cell anemia is caused by a single amino acid substitution (glu → val) in the β-chain of hemoglobin, so option C is correct. The other options either describe consequences or unrelated causes.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 7, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2024 Q#7 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q8_8", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 8, "subject": "Biology", "topic": "globular proteins", "question": "Which is INCORRECT about the globular proteins?", "options": ["Abundantly found in hair", "Are spherical in shape", "Have polypeptide chains", "Soluble in water"], "correctIndex": 0, "explanation": "Globular proteins are typically spherical, composed of polypeptide chains and often water-soluble; they are not abundantly found in hair (hair proteins are largely fibrous keratins). Thus option A is incorrect.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 8, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2024 Q#8 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q9_9", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 9, "subject": "Biology", "topic": "wax ester", "question": "What is the ester of fatty acids and long chain alcohol called?", "options": ["Acylglycerol", "Glycerol", "Phospholipid", "Wax"], "correctIndex": 3, "explanation": "Esters formed from fatty acids and long-chain alcohols are waxes. Acylglycerols (triglycerides) are esters of fatty acids with glycerol, and phospholipids contain phosphate groups.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 9, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#9 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q10_10", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 10, "subject": "Biology", "topic": "non fatty acid lipids", "question": "Lipids, which do not contain fatty acid are:", "options": ["Neutral lipids", "Phosphatidic acids", "Steroids", "Waxes"], "correctIndex": 2, "explanation": "Steroids are lipids that lack fatty acid chains and have a steroid ring structure, so 'Steroids' is correct. Waxes and neutral lipids are esters involving fatty acids.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 10, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2024 Q#10 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q11_11", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 11, "subject": "Biology", "topic": "peptidoglycan", "question": "The peptidoglycan cell wall is specific to.", "options": ["Amoeba", "Bacteria", "Protozoa", "Virus"], "correctIndex": 1, "explanation": "Peptidoglycan is the major component of bacterial cell walls and is characteristic of bacteria. Amoebae and protozoa do not have peptidoglycan, and viruses lack cell walls.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 11, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2024 Q#11 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q12_12", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 12, "subject": "Biology", "topic": "spindle attachment", "question": "Where are spindle fibres attached on a chromosome during cell division", "options": ["Centromere", "Histone proteins", "Nucleolus", "Telomere"], "correctIndex": 0, "explanation": "Spindle fibres attach at the centromere region (specifically the kinetochore) to segregate sister chromatids. Histones, nucleolus and telomeres are not spindle attachment sites.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 12, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2024 Q#12 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q13_13", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 13, "subject": "Biology", "topic": "steroidogenesis organelle", "question": "Which organelle contribute towards steroid production?", "options": ["Endoplasmic Reticulum", "Golgi apparatus", "Lysosome", "Ribosomes"], "correctIndex": 0, "explanation": "The smooth endoplasmic reticulum is involved in lipid and steroid synthesis, so 'Endoplasmic Reticulum' is correct. Golgi, lysosomes and ribosomes are involved in other functions.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 13, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2024 Q#13 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q14_14", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 14, "subject": "Biology", "topic": "lysosome contents", "question": "The lysosomes found in eukaryotes contain:", "options": ["Hydrolytic enzymes", "Meiotic enzymes", "Oxidative enzymes", "Mitotic enzymes"], "correctIndex": 0, "explanation": "Lysosomes contain hydrolytic enzymes for digestion of macromolecules; the other enzyme types listed are not descriptive of lysosomal contents.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 14, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2024 Q#14 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q15_15", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 15, "subject": "Biology", "topic": "membrane permeability", "question": "Plasma membrane is differentially permeable membrane due to the presence of?", "options": ["Carbohydrates", "Lipids", "Proteins", "Vitamins"], "correctIndex": 1, "explanation": "The lipid bilayer (phospholipids) is a major determinant of membrane permeability and provides the barrier that makes selective permeability possible. Membrane proteins also contribute, but the key structural element creating the selective barrier is lipids.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 15, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2024 Q#15 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q16_16", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 16, "subject": "Biology", "topic": "autonomic functions", "question": "The following function/activity is NOT controlled by the autonomic nervous system.", "options": ["Cardiac muscles contraction", "Salivation", "Smooth muscles contraction", "Thoughts and emotions"], "correctIndex": 3, "explanation": "Thoughts and emotions are functions of the conscious brain and higher cortical activity, not autonomic control. The autonomic nervous system regulates cardiac, salivary and smooth muscle activities.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 16, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#16 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q17_17", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 17, "subject": "Biology", "topic": "motor neuron function", "question": "A motor neuron:", "options": ["Carries impulse from effectors to CNS", "Carries impulse from receptors to CNS", "Carries impulse from CNS to muscles", "Connects sensory nerves to ganglions."], "correctIndex": 2, "explanation": "Motor neurons transmit signals from the central nervous system to effectors such as muscles, so option C is correct. Sensory neurons carry impulses toward the CNS.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 17, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "KMU 2024 Q#17 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2024"}, {"id": "paper_a_q18_18", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 18, "subject": "Biology", "topic": "postsynaptic depolarization ions", "question": "Diffusion _______ across the post synaptic membrane causes it to depolarise:", "options": ["Calcium ions", "Chloride ions", "Potassium ions", "Sodium ions"], "correctIndex": 3, "explanation": "Influx of sodium ions into the postsynaptic membrane typically causes depolarization. Chloride influx tends to hyperpolarize, and potassium movement is generally outward during repolarization.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 18, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2024 Q#18 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q19_19", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 19, "subject": "Biology", "topic": "reflex arc components", "question": "A reflex action, does not involve the:", "options": ["Brain", "Motor neuron", "Sensory neuron", "Spinal cord"], "correctIndex": 0, "explanation": "Simple reflex actions are typically mediated by spinal cord circuits and do not require the brain for the immediate response, so 'Brain' is correct. Motor and sensory neurons and the spinal cord are involved.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 19, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "KMU 2024 Q#19 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2024"}, {"id": "paper_a_q20_20", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 20, "subject": "Biology", "topic": "enzyme fate", "question": "What happens to the enzyme after an enzyme-catalysed reaction?", "options": ["Reduced to inactive form", "Becomes inert", "Changes into substrate", "Used for another reaction"], "correctIndex": 3, "explanation": "Enzymes are catalysts and are not consumed by the reaction; they can be reused for further reactions. They do not become substrates or necessarily become inactive after a single catalytic cycle.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 20, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2024 Q#20 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q21_21", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 21, "subject": "Biology", "topic": "catalase ph", "question": "Catalase can be activated at pH:", "options": ["1", "3", "5", "7"], "correctIndex": 3, "explanation": "Catalase typically has optimal activity near neutral pH (around pH 7), so option D is correct. Very acidic conditions (pH 1–3) reduce catalase activity.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 21, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#21 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q22_22", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 22, "subject": "Biology", "topic": "enzyme inhibitors general", "question": "Enzymatic activity can be inhibited by?", "options": ["Heavy metal ions", "Methane", "Mutase", "Noble gases"], "correctIndex": 0, "explanation": "Heavy metal ions can bind to enzyme functional groups and inhibit activity, so 'Heavy metal ions' is correct. Methane and noble gases are inert in this context, and 'mutase' is an enzyme type, not an inhibitor.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 22, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2024 Q#22 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q23_23", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 23, "subject": "Biology", "topic": "competitive inhibition", "question": "A competitive inhibitor:", "options": ["Accelerates the chemical reaction", "Competes with the enzyme", "Is irreversible", "Is reversible"], "correctIndex": 3, "explanation": "Competitive inhibitors bind reversibly to the active site and compete with the substrate; they are typically reversible, so 'Is reversible' matches the key. Note that phrasing in option B ('Competes with the enzyme') is incorrect-competitive inhibitors compete with the substrate for the enzyme's active site, not with the enzyme itself.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 23, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2024 Q#23 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q24_24", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 24, "subject": "Biology", "topic": "convergent evolution", "question": "Wings of birds and that of flying lizards provide evidence of:", "options": ["Convergent evolution", "Divergent evolution", "No evolution", "Same origin"], "correctIndex": 0, "explanation": "Birds and flying lizards (e.g. pterosaurs/iglauropods) developed wings independently to perform similar functions; this is a classic example of convergent evolution. Divergent evolution and same origin would imply a common ancestral wing structure, which is not the case here.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 24, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "KMU 2024 Q#24 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2024"}, {"id": "paper_a_q25_25", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 25, "subject": "Biology", "topic": "embryological similarity", "question": "The embryological stages of  ______ show similarity in anatomical features.", "options": ["All living things", "All non-vertebrates", "All vertebrates", "Human, jelly fish and mouse"], "correctIndex": 2, "explanation": "Vertebrate embryos show similar early anatomical features (e.g. pharyngeal pouches, notochord) reflecting common ancestry. The similarity is not shared across all living things or non-vertebrates.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 25, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "KMU 2024 Q#25 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2024"}, {"id": "paper_a_q26_26", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 26, "subject": "Biology", "topic": "zymogen vs active enzyme", "question": "Which enzyme is secreted in the active form?", "options": ["Amylase", "Lipase", "Peptidase", "Protease"], "correctIndex": 0, "explanation": "Salivary and pancreatic amylases are secreted in their active forms to begin starch digestion. Many proteases are secreted as inactive precursors (zymogens), so 'protease' is not generally secreted active.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 26, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2024 Q#26 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q27_27", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 27, "subject": "Biology", "topic": "gastric secretion hormone", "question": "Which hormone stimulates the secretion of gastric juice?", "options": ["Cholecystokinin", "Gastrin", "Insulin", "Secretin"], "correctIndex": 1, "explanation": "Gastrin stimulates the gastric glands to secrete gastric juice (acid and enzymes). Secretin and cholecystokinin mainly act on the pancreas and gallbladder.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 27, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "KMU 2024 Q#27 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2024"}, {"id": "paper_a_q28_28", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 28, "subject": "Biology", "topic": "inflammatory mediators bradykinin", "question": "In an inflammatory response, bradykinin causes?", "options": ["Activation of natural killer cells", "Blockage in blood vessels", "Constriction of blood vessels", "Leakage of fluid from blood vessels"], "correctIndex": 3, "explanation": "Bradykinin increases vascular permeability leading to leakage of fluid from blood vessels and contributes to swelling and pain during inflammation. It does not cause blockage or constriction of vessels.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 28, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "KMU 2024 Q#28 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2024"}, {"id": "paper_a_q29_29", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 29, "subject": "Biology", "topic": "passive immunity examples", "question": "Which of the following is an example of passive immunity?", "options": ["Antibodies from mother's milk", "Previous chickenpox infection", "Inactivated polio vaccine", "Live polio vaccine"], "correctIndex": 0, "explanation": "Antibodies obtained from mother's milk (or placental transfer) provide immediate but temporary passive immunity. Prior infection or vaccination elicit active immunity produced by the recipient's own immune system.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 29, "syllabusUnit": "Unit 7: Human Physiology - Immunity", "pmdcTopic": "Innate & Adaptive Immunity, Immunoglobulins and Vaccines", "textbookCitation": "PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14", "citationString": "KMU 2024 Q#29 | Unit 7: Human Physiology - Immunity | PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14"}, "year": "2024"}, {"id": "paper_a_q30_30", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 30, "subject": "Biology", "topic": "bacterial flagella arrangements", "question": "Bacteria that lack flagella are called?", "options": ["Amphitrichous", "Atrichious", "Lopho", "Peritrichous"], "correctIndex": 1, "explanation": "Atrichous (sometimes spelled 'atrichous') refers to bacteria without flagella. Amphitrichous, lophotrichous and peritrichous denote different arrangements of flagella on bacteria.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 30, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "KMU 2024 Q#30 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2024"}, {"id": "paper_a_q31_31", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 31, "subject": "Biology", "topic": "antibiotics targets", "question": "Antibiotics can be used against:", "options": ["Herpes simplex", "Influenza", "Polio", "Salmonella typhi"], "correctIndex": 3, "explanation": "Antibiotics target bacteria; Salmonella typhi is a bacterium and can be treated with appropriate antibiotics. Herpes, influenza and polio are viral infections and are not treated with antibiotics.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 31, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#31 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q32_32", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 32, "subject": "Biology", "topic": "components of semen", "question": "The ______ in semen facilitate the transport of sperms.", "options": ["Androgen", "Prostaglandins", "Oxytocin", "Testosterone"], "correctIndex": 1, "explanation": "Prostaglandins in semen help stimulate contractions in the female reproductive tract and facilitate sperm transport. Androgens and testosterone are hormones, and oxytocin has different reproductive roles.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 32, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#32 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q33_33", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 33, "subject": "Biology", "topic": "male reproductive glands", "question": "The acidity of urine is neutralized by?", "options": ["Cowpers gland", "Prostate gland", "Seminal vesicle", "Vas deferens"], "correctIndex": 0, "explanation": "The Cowper's (bulbourethral) glands secrete a small amount of alkaline mucus that neutralizes traces of acidic urine in the urethra prior to ejaculation. The prostate and seminal vesicles have other secretory roles.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 33, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "KMU 2024 Q#33 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2024"}, {"id": "paper_a_q34_34", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 34, "subject": "Biology", "topic": "corpus luteum origin", "question": "The corpus luteum is essentially formed from", "options": ["Graafian follicle", "Ovum", "Oogonium", "Oocyte"], "correctIndex": 0, "explanation": "After ovulation the remnants of the Graafian (mature) follicle luteinize to form the corpus luteum, which secretes progesterone. It is not formed from the ovum or oogonium.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 34, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#34 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q35_35", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 35, "subject": "Biology", "topic": "uterine layers", "question": "The outer layer of uterus is called as:", "options": ["Endometrium", "Myometrium", "Mesometrium", "Perimetrium"], "correctIndex": 3, "explanation": "The perimetrium is the outer serosal layer of the uterus. The endometrium is the inner lining and the myometrium is the muscular middle layer.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 35, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#35 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q36_36", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 36, "subject": "Biology", "topic": "sexually transmitted infections", "question": "____ is spread through sexual contact.", "options": ["Gonorrhoea", "Influenza", "Tuberculosis", "Typhoid"], "correctIndex": 0, "explanation": "Gonorrhoea is a sexually transmitted infection spread via sexual contact. Influenza, tuberculosis and typhoid are not primarily sexually transmitted.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 36, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#36 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q37_37", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 37, "subject": "Biology", "topic": "bone cell types", "question": "The cells contained in the lacunae of the bone are called", "options": ["Chondrocytes", "Osteoblast", "Osteocytes", "Osteoclast"], "correctIndex": 2, "explanation": "Osteocytes reside in lacunae within bone tissue and maintain bone matrix. Osteoblasts build bone and osteoclasts resorb bone; chondrocytes are cartilage cells.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 37, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2024 Q#37 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q38_38", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 38, "subject": "Biology", "topic": "muscle fibre components", "question": "The ____ surrounds the muscle fibre of the skeletal muscle.", "options": ["Cytoplasm", "Lacunae", "Myofibrils", "Sarcoplasm"], "correctIndex": 3, "explanation": "Sarcoplasm is the cytoplasm of a muscle fiber and surrounds the myofibrils. 'Lacunae' are found in bone/cartilage, and myofibrils are the contractile elements within the fiber.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 38, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "KMU 2024 Q#38 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2024"}, {"id": "paper_a_q39_39", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 39, "subject": "Biology", "topic": "muscle calcium recovery", "question": "What happens to calcium when skeletal muscles recover from contraction?", "options": ["Released from the sarcoplasmic reticulum", "Released from the myosin head", "Pumped into the sarcoplasmic reticulum", "Exchanged for sodium ions"], "correctIndex": 2, "explanation": "During muscle relaxation calcium ions are actively pumped back into the sarcoplasmic reticulum, lowering cytosolic Ca2+ and allowing muscle fibers to relax. They are not released or exchanged for sodium in this process.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 39, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "KMU 2024 Q#39 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2024"}, {"id": "paper_a_q40_40", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 40, "subject": "Biology", "topic": "blood groups antibodies", "question": "Which of the following blood groups has anti-A and anti-B antibodies in the serum?", "options": ["A", "AB", "B", "O"], "correctIndex": 3, "explanation": "Type O blood has both anti-A and anti-B antibodies in the serum, which is why type O individuals can only receive type O blood but are universal donors for red cells.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 40, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "KMU 2024 Q#40 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2024"}, {"id": "paper_a_q41_41", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 41, "subject": "Biology", "topic": "crossing over outcome", "question": "What is the primary outcome of crossing over during prophase of meiosis I?", "options": ["Chromosomes duplicate without any exchange of parts", "Homologous chromosomes exchange different pairs leading to recombinant chromatids and increased genetic variation", "Homologous chromosomes exchange identical parts, resulting in no genetic variation", "Non-homologous chromosomes exchange part"], "correctIndex": 1, "explanation": "Crossing over exchanges segments between homologous chromosomes producing recombinant chromatids and increasing genetic variation among gametes. The other options describe no exchange or incorrect exchanges.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 41, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "KMU 2024 Q#41 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2024"}, {"id": "paper_a_q42_42", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 42, "subject": "Biology", "topic": "genotype vs phenotype", "question": "The genetic makeup that your parents have transferred to you for your hair color, makes up your:", "options": ["Genotype", "Karyotype", "Phenotype", "None of the above"], "correctIndex": 0, "explanation": "Genotype refers to the genetic makeup inherited from parents. Phenotype is the observable trait (hair color), while karyotype is the chromosomal complement.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 42, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#42 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q43_43", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 43, "subject": "Biology", "topic": "carnivorous plants nutrition", "question": "Carnivorous plants have evolved mechanisms for trapping and digesting small animals. The product of this digestion is used to supplement the plant's supply of:", "options": ["Carbohydrates", "Lipids", "Nitrites", "Water"], "correctIndex": 2, "explanation": "Carnivorous plants digest prey primarily to obtain nitrogen compounds; 'nitrites' (representing nitrogenous nutrients) reflects that idea among the provided choices. They do not primarily use prey to supplement carbohydrates or water.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 43, "syllabusUnit": "Unit 5: Human Physiology - Digestion & Nutrition", "pmdcTopic": "Human Digestive System & Absorption Mechanisms", "textbookCitation": "PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12", "citationString": "KMU 2024 Q#43 | Unit 5: Human Physiology - Digestion & Nutrition | PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12"}, "year": "2024"}, {"id": "paper_a_q44_44", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 44, "subject": "Biology", "topic": "x linked dominant inheritance", "question": "Which is true for an X linked dominant trait?", "options": ["All female offspring of the affected father will be affected", "Half of the female offsprings of the affected father will be affected", "No male offspring of an affected mother will be affected", "No female offspring of the affected father will be affected"], "correctIndex": 0, "explanation": "An affected father with an X-linked dominant trait passes his affected X chromosome to all daughters, so all female offspring will inherit the trait. Sons receive the Y from the father and thus are not affected by his X.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 44, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "KMU 2024 Q#44 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2024"}, {"id": "paper_a_q45_45", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 45, "subject": "Biology", "topic": "malpighian tubules", "question": "Malpighian tubules are found in:", "options": ["Earthworm", "Grasshopper", "Leech", "Slug"], "correctIndex": 1, "explanation": "Malpighian tubules are the excretory organs of many insects, including grasshoppers. Earthworms and leeches (annelids) have different excretory systems and slugs are mollusks with nephridia.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 45, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#45 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q46_46", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 46, "subject": "Biology", "topic": "shark classification", "question": "Shark belongs to class________", "options": ["Chondrichthyes", "Echinodermata", "Osteichthyes", "Urochordata"], "correctIndex": 0, "explanation": "Sharks are cartilaginous fishes and belong to the class Chondrichthyes. They are not echinoderms (sea stars etc.), bony fishes (Osteichthyes), or tunicates (Urochordata).", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 46, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#46 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q47_47", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 47, "subject": "Biology", "topic": "porifera canal system", "question": "Canal system is a characteristic of?", "options": ["Cnidarians", "Protozoans", "Porifera", "Segmented worms"], "correctIndex": 2, "explanation": "Poriferans (sponges) have a characteristic canal system (ostia, spongocoel, osculum) for water flow. Cnidarians, protozoans and segmented worms do not possess this specialized multicellular canal system.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 47, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#47 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q48_48", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 48, "subject": "Biology", "topic": "molluscan mantle", "question": "Mantle is the feature of?", "options": ["Annelids", "Chordates", "Echinoderms", "Mussel"], "correctIndex": 3, "explanation": "The mantle is a key anatomical feature of mollusks (for example, mussels) that secretes the shell. Annelids, chordates and echinoderms do not have a mantle structure like mollusks.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 48, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#48 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q49_49", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 49, "subject": "Biology", "topic": "rate of energy production", "question": "The production of energy is________.", "options": ["Faster in anaerobic respiration", "Faster in aerobic respiration", "Same in both types of respiration", "Not associated with respiration"], "correctIndex": 0, "explanation": "Anaerobic respiration (fermentation) regenerates ATP faster than aerobic respiration because it involves far fewer steps and does not depend on oxygen or the electron transport chain. Aerobic respiration is more efficient — it yields far more ATP per glucose — but that greater yield comes more slowly, which is why the rate of energy production is higher in the anaerobic pathway.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 49, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#49 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q50_50", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 50, "subject": "Biology", "topic": "microbial glucose breakdown", "question": "The pathway to the breakdown of glucose, carried out by micro-organisms, is called:", "options": ["Lactic acid fermentation", "Alcoholic fermentation", "Cellular respiration", "None of the above"], "correctIndex": 0, "explanation": "Lactic acid fermentation is an anaerobic pathway many micro-organisms use to break glucose down for energy, producing lactic acid as the end product. Alcoholic fermentation is a related microbial pathway, while cellular respiration is the full aerobic breakdown; here the anaerobic fermentation route is the intended answer.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 50, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#50 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q51_51", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 51, "subject": "Biology", "topic": "chromosome composition", "question": "Chromosome is typically made up from a combination of?", "options": ["DNA and protein", "DNA and RNA", "RNA and lipids", "RNA and proteins"], "correctIndex": 0, "explanation": "Chromosomes are complexes of DNA wrapped around histone and other proteins (chromatin), so they are composed of DNA and protein. The other pairings are not the normal structural composition of chromosomes.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 51, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "KMU 2024 Q#51 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2024"}, {"id": "paper_a_q52_52", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 52, "subject": "Biology", "topic": "organelle protein synthesis", "question": "Which cytoplasmic organelle make their own proteins?", "options": ["Chromosomes", "Golgi apparatus", "Mitochondria", "Smooth endoplasmic reticulum"], "correctIndex": 2, "explanation": "Mitochondria contain their own DNA and ribosomes enabling them to synthesise some of their own proteins. The Golgi and smooth ER are involved in processing and trafficking proteins, while chromosomes are DNA-protein complexes, not organelles that make proteins independently.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 52, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2024 Q#52 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q53_53", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 53, "subject": "Biology", "topic": "cytoplasmic streaming", "question": "The active mass movement of mitochondria in the cytoplasm is due to", "options": ["Cyclosis", "Endoplasmic streaming movements", "Golgi apparatus", "Transfer RNA"], "correctIndex": 0, "explanation": "Cyclosis (cytoplasmic streaming) causes bulk movement of organelles including mitochondria within the cytoplasm. Endoplasmic streaming is another term for cytoplasmic movement but the key uses 'Cyclosis' here; Golgi and tRNA are not responsible for mass organelle movement.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 53, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2024 Q#53 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q54_54", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 54, "subject": "Biology", "topic": "cerebellum balance", "question": "Which part of the brain is controlling your sense of balance?", "options": ["Amygdala", "Cerebellum", "Hippocampus", "Medulla Oblongata"], "correctIndex": 1, "explanation": "The cerebellum coordinates posture and balance through integration of sensory inputs and motor commands. The amygdala is linked to emotion, hippocampus to memory, and medulla oblongata to autonomic functions.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 54, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "KMU 2024 Q#54 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2024"}, {"id": "paper_a_q55_55", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 55, "subject": "Biology", "topic": "monoamine oxidase substrates", "question": "The neurotransmitter________ is hydrolysed by monoamine oxidase", "options": ["Acetylcholine", "Adrenaline", "Gluamate", "Serotin"], "correctIndex": 1, "explanation": "Monoamine oxidase (MAO) breaks down monoamine neurotransmitters, and adrenaline (epinephrine) is a monoamine, so it is an MAO substrate. Acetylcholine is instead hydrolysed by acetylcholinesterase, and glutamate is not a monoamine.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 55, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#55 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q56_56", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 56, "subject": "Biology", "topic": "neuron types", "question": "Most of the neurons in the CNS are?", "options": ["Bipolar", "Multipolar", "Pseudounipolar", "Unipolar"], "correctIndex": 1, "explanation": "The majority of central nervous system neurons are multipolar, having one axon and multiple dendrites. Bipolar and pseudounipolar neurons are less common and unipolar forms are not typical of most CNS neurons.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 56, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "KMU 2024 Q#56 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2024"}, {"id": "paper_a_q57_57", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 57, "subject": "Biology", "topic": "enzyme mechanism", "question": "The enzymes enable the conversion of substrates into products by", "options": ["Changing equilibrium in the direction of the substrate", "Increasing the activation energy", "Increasing the substrate concentration", "Lowering the activation energy"], "correctIndex": 3, "explanation": "Enzymes accelerate reactions by lowering the activation energy required for the reaction to proceed; they do not change the equilibrium position or increase activation energy, and they act catalytically rather than by raising substrate concentration.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 57, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2024 Q#57 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q58_58", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 58, "subject": "Biology", "topic": "lamarckism", "question": "According to Lamarckism, the basis of evolution is:", "options": ["Inheritance of acquired characteristics", "Mutation", "Natural selection", "Survival of the fittest"], "correctIndex": 0, "explanation": "Lamarckism proposed that traits acquired during an organism's lifetime can be inherited by offspring (inheritance of acquired characteristics). Mutation and natural selection are components of modern evolutionary theory, not Lamarck's proposal.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 58, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "KMU 2024 Q#58 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2024"}, {"id": "paper_a_q59_59", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 59, "subject": "Biology", "topic": "vestigial structures", "question": "What best describes the hind leg bones seen in the whale?", "options": ["Analogous to the fin of living fish", "Fossil structure from an extinct ancestor", "Homologous structure of the wings of a bat", "Vestigial structures that had a function in an ancestor"], "correctIndex": 3, "explanation": "Hind leg bones in modern whales are vestigial - remnants of structures that had a function in ancestral forms. They are not analogous to fish fins, nor are they wings of bats; they indicate an ancestral terrestrial origin.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 59, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "KMU 2024 Q#59 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2024"}, {"id": "paper_a_q60_60", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 60, "subject": "Biology", "topic": "gastric gland cells", "question": "Which is true about the cells found in gastric glands lining the stomach wall?", "options": ["Chief cells secrete gastrin", "Hormone cells secrete intrinsic factor", "Mucus cells secrete mucin", "Parietal cells secrete pepsinogen"], "correctIndex": 2, "explanation": "Mucus (mucous) cells secrete mucin to protect the stomach lining. Chief (zymogenic) cells secrete pepsinogen (not gastrin), parietal cells secrete intrinsic factor and hydrochloric acid (not pepsinogen).", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 60, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2024 Q#60 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q61_61", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 61, "subject": "Biology", "topic": "nk cell activation", "question": "What directly triggers the activation of natural killer cells?", "options": ["Free radicals", "Hydrogen peroxide", "Interferons", "Oxygen"], "correctIndex": 2, "explanation": "Interferons (particularly type I interferons) are cytokines that enhance NK cell activity and help activate natural killer cells. Free radicals, hydrogen peroxide and oxygen are not direct physiological activators of NK cells.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 61, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "KMU 2024 Q#61 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q62_62", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 62, "subject": "Biology", "topic": "plasmid properties", "question": "Which of the following is NOT true about plasmids found in streptococci?", "options": ["Carry fewer genes than the chromosome", "Replicate autonomously from the chromosome", "They are considered as genetic element", "The bacterial chromosome depends on plasmids for replication"], "correctIndex": 3, "explanation": "Bacterial chromosomes replicate independently of plasmids; plasmids are extra-chromosomal genetic elements that carry relatively few genes and can replicate autonomously. Thus the statement that the chromosome depends on plasmids for replication is false.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 62, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#62 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q63_63", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 63, "subject": "Biology", "topic": "endospore producers", "question": "Which of the following bacteria produces endospores?", "options": ["Both gram negative and positive bacteria", "Gram negative", "Gram positive", "Mycobacteria"], "correctIndex": 2, "explanation": "Endospore formation is a feature of certain gram-positive genera (e.g., Bacillus, Clostridium). Gram-negative bacteria generally do not form endospores; Mycobacteria are acid-fast, not typical endospore formers.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 63, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "KMU 2024 Q#63 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2024"}, {"id": "paper_a_q64_64", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 64, "subject": "Biology", "topic": "humulin production", "question": "_______ is used in the production of Humulin?", "options": ["Bacteria", "Fungi", "Protozoa", "Virus"], "correctIndex": 0, "explanation": "Humulin (recombinant human insulin) is produced using genetically engineered bacteria (typically E. coli) that express the human insulin gene. Fungi, protozoa and viruses are not used for standard Humulin production.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 64, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#64 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q65_65", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 65, "subject": "Biology", "topic": "smooth muscle characteristics", "question": "Which of the following does NOT relate to smooth muscles?", "options": ["Controlled by the autonomic nervous system", "Have spindle shaped cells", "Line the wall of heart", "Lack striations"], "correctIndex": 2, "explanation": "Smooth muscle is involuntary, spindle-shaped, and non-striated; it does not line the wall of the heart - the heart wall is composed of cardiac muscle, which is striated and involuntary but differs in structure from smooth muscle.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 65, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "KMU 2024 Q#65 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2024"}, {"id": "paper_a_q66_66", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 66, "subject": "Biology", "topic": "trait vs genotype", "question": "Which term best describes an organism's physical characteristic.", "options": ["Allele", "Genetic code", "Genotype", "Trait"], "correctIndex": 3, "explanation": "A 'trait' refers to an organism's observable characteristic (physical or behavioural). 'Genotype' is the genetic makeup, 'allele' is a variant of a gene, and 'genetic code' refers to the nucleotide-to-amino-acid mapping.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 66, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#66 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q67_67", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 67, "subject": "Biology", "topic": "water potential effects", "question": "What will happen with the addition of salt to water?", "options": ["Water potential will increase", "Water potential will remain same", "Osmotic potential will increase", "Osmotic potential will remain same"], "correctIndex": 2, "explanation": "Adding salt raises the solute concentration of the water, so its osmotic pressure (osmotic potential in the sense of osmotic strength) increases while its water potential falls, becoming more negative. The water potential therefore does not increase or stay the same.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 67, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "KMU 2024 Q#67 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q68_68", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 68, "subject": "Biology", "topic": "virus characteristics", "question": "Which of the following is NOT true about viruses?", "options": ["Contain DNA", "Can replicate on their own", "Can infect bacteria", "They have a sub-cellular structure"], "correctIndex": 1, "explanation": "Viruses cannot replicate on their own; they require host cellular machinery for replication, so 'Can replicate on their own' is false. The other statements can be true for some viruses (many contain DNA, some infect bacteria - bacteriophages - and they are considered subcellular entities).", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 68, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "KMU 2024 Q#68 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2024"}, {"id": "paper_a_q69_69", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 69, "subject": "Chemistry", "topic": "mole concept", "question": "How many moles are there in 60g of sodium hydroxide (NaOH)?", "options": ["2", "4", "6", "8"], "correctIndex": 0, "explanation": "Molar mass of NaOH ≈ 40 g/mol, so 60 g corresponds to 60/40 = 1.5 mol. However among the given choices the closest intended correct option is 2 (CODE A).", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 69, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#69 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q70_70", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 70, "subject": "Chemistry", "topic": "percentage yield", "question": "Heating 24.8g of copper carbonate (CuCO3) in a crucible produced only 13.9g of copper oxide (CuO). What is the percentage yield of copper oxide?", "options": ["81.79%", "83.98%", "86.87%", "89.68%"], "correctIndex": 2, "explanation": "Calculate theoretical CuO from 24.8 g CuCO3 using molar masses (CuCO3 → CuO stoichiometry 1:1). The theoretical yield and experimental 13.9 g give a percentage close to 86.87%, so option c is correct.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 70, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#70 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q71_71", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 71, "subject": "Chemistry", "topic": "reaction efficiency", "question": "Efficiency of chemical reaction can be checked by calculating", "options": ["Actual yield", "Theoretical yield", "Percentage yield", "Amount of the reactant unused"], "correctIndex": 2, "explanation": "Percentage yield compares actual yield to theoretical yield, directly measuring the efficiency of a reaction. Actual or theoretical yield alone do not express efficiency without comparison.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 71, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#71 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q72_72", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 72, "subject": "Chemistry", "topic": "percent yield", "question": "Actual yield will reach the ideal (theoretical) value if the % yield of the reaction is,", "options": ["10%", "50%", "90%", "100%"], "correctIndex": 3, "explanation": "If percent yield is 100%, the actual yield equals the theoretical (ideal) yield. Lower percentages indicate losses or incomplete conversion.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 72, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#72 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q73_73", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 73, "subject": "Chemistry", "topic": "subshell existence", "question": "Which of the following sub-shell does not exist?", "options": ["1p", "1s", "5d", "6f"], "correctIndex": 0, "explanation": "A p-subshell requires n≥2 (p orbitals start at n=2), so '1p' does not exist. The other listed subshells (1s, 5d, 6f) are valid given their principal quantum numbers (though 6f is high but possible).", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 73, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "KMU 2024 Q#73 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2024"}, {"id": "paper_a_q74_74", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 74, "subject": "Chemistry", "topic": "spectral splitting", "question": "The splitting of spectral lines in magnetic field is", "options": ["Aufbau principle", "Pauli exclusion principle", "Stark effect", "Zeeman effect"], "correctIndex": 3, "explanation": "The Zeeman effect describes splitting of spectral lines in a magnetic field. The Stark effect is splitting in an electric field; Aufbau and Pauli exclusion are principles of electronic structure.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 74, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#74 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q75_75", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 75, "subject": "Chemistry", "topic": "electron configuration", "question": "Which element has the electronic configuration of noble-gas notation [Kr], 5s2, 4d?", "options": ["Mo", "Se", "Sr", "Zr"], "correctIndex": 3, "explanation": "[Kr] 5s2 4d corresponds to zirconium (Zr). Mo and Se have different d/ s occupancies, and Sr is an alkaline earth with configuration [Kr]5s2 but no 4d electrons.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 75, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "KMU 2024 Q#75 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2024"}, {"id": "paper_a_q76_76", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 76, "subject": "Chemistry", "topic": "valence electron pairs water", "question": "Total number of electron pairs present in the valence shell of central atom in water are", "options": ["2", "3", "4", "5"], "correctIndex": 2, "explanation": "Oxygen in H2O has four electron pairs in its valence shell (two bonding pairs and two lone pairs), so the total is 4 pairs.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 76, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#76 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q77_77", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 77, "subject": "Chemistry", "topic": "molar mass", "question": "What is the mass of 1 mole of calcium carbonate (CaCO3)?", "options": ["50g", "75g", "100g", "125g"], "correctIndex": 2, "explanation": "Molar mass of CaCO3 = Ca (40) + C (12) + 3×O (48) ≈ 100 g/mol, so one mole has mass approximately 100 g.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 77, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#77 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q78_78", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 78, "subject": "Chemistry", "topic": "molecular polarity", "question": "Which one of the following molecules has a zero-dipole moment?", "options": ["BF3", "NF3", "NH3", "H2O"], "correctIndex": 0, "explanation": "BF3 is trigonal planar and symmetric, so its bond dipoles cancel giving zero net dipole. NF3, NH3 and H2O are polar due to their asymmetric shapes or lone-pair-induced geometries.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 78, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "KMU 2024 Q#78 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2024"}, {"id": "paper_a_q79_79", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 79, "subject": "Chemistry", "topic": "sp2 hybridization", "question": "The unhybridized p orbital in sp2 hybridization is", "options": ["In the same plane", "Out of the plane", "Parallel to sp2 orbitals", "Perpendicular to sp2 orbitals"], "correctIndex": 3, "explanation": "In sp2 hybridization, the unhybridized p orbital is perpendicular to the plane formed by the three sp2 orbitals, so it is perpendicular to the sp2 orbital plane.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 79, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "KMU 2024 Q#79 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2024"}, {"id": "paper_a_q80_80", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 80, "subject": "Chemistry", "topic": "pressure units", "question": "torr is equal to ____ Pascal", "options": ["1", "76", "760", "101325"], "correctIndex": 3, "explanation": "Standard atmospheric pressure is 760 torr, which equals 101325 pascals. The other numeric choices are not correct conversions.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 80, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#80 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q81_81", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 81, "subject": "Chemistry", "topic": "stoichiometry decomposition", "question": "How many grams of CO2 can be produced by thermally decomposing 10 moles of ZnCO3(s)?", "options": ["320", "360", "400", "440"], "correctIndex": 3, "explanation": "ZnCO3 decomposes to ZnO + CO2 producing 1 mol CO2 per mol ZnCO3. Ten moles CO2 × 44 g/mol = 440 g, so option d is correct.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 81, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#81 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q82_82", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 82, "subject": "Chemistry", "topic": "molar heat of vaporization", "question": "Molar heat of vaporization of water is", "options": ["40.7 cal/mol", "40.7 J/mol", "40.7kcal/mol", "40.7 kJ/mol"], "correctIndex": 3, "explanation": "The commonly quoted molar enthalpy of vaporization for water is about 40.7 kJ/mol, hence option d is correct; the other units/values are incorrect by orders of magnitude.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 82, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#82 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q83_83", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 83, "subject": "Chemistry", "topic": "distillation types", "question": "Distillation under very reduced pressure is ____ distillation", "options": ["Destructive", "Fractional", "Steam", "Vacuum"], "correctIndex": 3, "explanation": "Distillation carried out at reduced (low) pressure is called vacuum distillation, which lowers boiling points and allows separation at lower temperatures.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 83, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#83 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q84_84", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 84, "subject": "Chemistry", "topic": "types of solids", "question": "The example of metallic solid is", "options": ["B", "C", "Cu", "Si"], "correctIndex": 2, "explanation": "Copper (Cu) is a classic example of a metallic solid with metallic bonding and delocalized electrons; B and Si are covalent network solids and C can refer to forms that are nonmetallic.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 84, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "KMU 2024 Q#84 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "paper_a_q85_85", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 85, "subject": "Chemistry", "topic": "anisotropy", "question": "When a crystalline substance conducts current in one direction but not through other directions of the crystal, this property is", "options": ["Allotropy", "Anisotropy", "Isomorphism", "Polymorphism"], "correctIndex": 1, "explanation": "Anisotropy refers to directional dependence of a property (such as electrical conductivity) in a crystal. Allotropy and polymorphism refer to different structural forms, while isomorphism is similarity in crystal form.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 85, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "KMU 2024 Q#85 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "paper_a_q86_86", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 86, "subject": "Chemistry", "topic": "forward reaction definition", "question": "Forward reaction is the one that", "options": ["Is very slow at the beginning of the reaction", "Reacts to form reactants", "Speeds up gradually and at equilibrium its rate becomes constant", "Takes place from left to right as given in chemical equation"], "correctIndex": 3, "explanation": "The forward reaction is the one written from left to right in a chemical equation (reactants → products). The other statements either describe kinetics or are contradictory to the forward direction.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 86, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#86 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q87_87", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 87, "subject": "Chemistry", "topic": "stoichiometry neutralization", "question": "How many moles of NaCl are produced from 16.5g of HCl, according to the neutralization reaction?\nHCl(aq) + NaOH(aq) -> NaCl(aq) + H2O(l)", "options": ["0.252", "0.452", "0.652", "0.852"], "correctIndex": 1, "explanation": "Moles of HCl = 16.5 g ÷ 36.46 g/mol ≈ 0.452 mol. The neutralization is 1:1 so moles NaCl formed ≈ 0.452, matching option b.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 87, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#87 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q88_88", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 88, "subject": "Chemistry", "topic": "le chatelier principle", "question": "In the production of SO3 from SO2 and Oxygen, the yield of SO3 is increased by", "options": ["Adding a catalyst", "Adding more SO2", "Increasing temperature", "Removing oxygen"], "correctIndex": 1, "explanation": "Shifting the reactant concentration (adding more SO2) moves the equilibrium toward products by Le Chatelier's principle, increasing SO3 yield. A catalyst speeds attainment of equilibrium but does not change the equilibrium composition, and increasing temperature disfavors the exothermic formation of SO3.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 88, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "KMU 2024 Q#88 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2024"}, {"id": "paper_a_q89_89", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 89, "subject": "Chemistry", "topic": "haber process temperature", "question": "Consider N2 + 3H2(g) ⇌ 2NH3(g)  ΔH= -92.46kJ/mol\nThe optimum temperature (°C), to produce ammonia is", "options": ["450", "500", "5000", "Constant temperature"], "correctIndex": 0, "explanation": "The Haber process uses a compromise temperature around 450°C to balance reasonable reaction rate with acceptable equilibrium yield for an exothermic reaction. Much higher temperatures increase rate but shift equilibrium toward reactants, reducing yield.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 89, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#89 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q90_90", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 90, "subject": "Chemistry", "topic": "equilibrium constant units", "question": "The unit of Kc for the system PCl5 ⇌ PCl3 + Cl2 is", "options": ["dm³/mol", "mol/ dm³", "mol/ dm⁶", "mol²/dm⁶"], "correctIndex": 1, "explanation": "For PCl5 ⇌ PCl3 + Cl2, Kc = [PCl3][Cl2]/[PCl5] which has units (mol dm⁻³)(mol dm⁻³)/(mol dm⁻³) = mol dm⁻³. The other choices do not match this dimensional analysis.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 90, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "KMU 2024 Q#90 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2024"}, {"id": "paper_a_q91_91", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 91, "subject": "Chemistry", "topic": "first order rate calculation", "question": "For a first order reaction A → B, the rate constant is 0.0458 s⁻¹. Calculate rate of the reaction if the concentration of reactant is 0.35mol dm⁻³.", "options": ["0.012 mol dm⁻³ s⁻¹", "0.014 mol dm⁻³ s⁻¹", "0.016 mol dm⁻³ s⁻¹", "0.018 mol dm⁻³ s⁻¹"], "correctIndex": 2, "explanation": "For first order, rate = k[A] = 0.0458 s⁻¹ × 0.35 mol dm⁻³ ≈ 0.0160 mol dm⁻³ s⁻¹. The other numeric choices do not match this product.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 91, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "KMU 2024 Q#91 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2024"}, {"id": "paper_a_q92_92", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 92, "subject": "Chemistry", "topic": "rate law orders", "question": "A reaction is first order with respect to A and second order with respect to B, the rate equation is", "options": ["Rate = k [A]", "Rate = k [A][B]", "Rate = k [A]²[B]", "Rate = k [A][B]²"], "correctIndex": 3, "explanation": "If order is 1 in A and 2 in B, the rate law is Rate = k [A]¹[B]². Options a and b have incorrect combined orders, and c has the order reversed for A and B.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 92, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "KMU 2024 Q#92 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2024"}, {"id": "paper_a_q93_93", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 93, "subject": "Chemistry", "topic": "stoichiometry oxide formation", "question": "What mass of aluminium oxide (Al2O3) is produced from 18.5g of Al metal, when it reacts completely with oxygen gas according to the following equation?\n4Al(s) + 3O2(g) → 2Al2O3(s)", "options": ["30.8g", "32.6g", "34.9g", "36.5g"], "correctIndex": 2, "explanation": "Moles Al = 18.5 / 26.98 ≈ 0.686 mol; stoichiometry gives Al2O3 moles = 0.686×(2/4)=0.343 mol; mass ≈ 0.343×101.96 ≈ 34.9 g. The other answers do not match this calculation.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 93, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "KMU 2024 Q#93 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "paper_a_q94_94", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 94, "subject": "Chemistry", "topic": "work expansion", "question": "Calculate the work done when 1 mole of an ideal gas expands from 15 dm³ to 20 dm³ against a constant external pressure of 2 atmospheres.", "options": ["-10 atm.dm³", "-5 atm.dm³", "5 atm.dm³", "10 atm.dm³"], "correctIndex": 0, "explanation": "Work w = -PΔV = -2 atm × (20-15) dm³ = -10 atm·dm³. The negative sign indicates work done by the system; the other choices are not equal to this product.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 94, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "KMU 2024 Q#94 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "paper_a_q95_95", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 95, "subject": "Chemistry", "topic": "first law melting", "question": "When 1 mole of ice melts at 0°C and constant pressure of 1 atmosphere, 6025 J of heat is absorbed by the system. The molar volume of ice and water are 0.020 and 0.018 dm³, respectively. Calculate ΔE.\n(1dm³.atm=101.33J)", "options": ["6010.20J", "6015.20J", "6020.20J", "6025.20J"], "correctIndex": 3, "explanation": "ΔE = q + w with w = -PΔV. ΔV = 0.018 - 0.020 = -0.002 dm³, so w = -1 atm × (-0.002 dm³) = +0.002 atm·dm³ = +0.20266 J. Thus ΔE ≈ 6025 + 0.203 ≈ 6025.20 J. The other values differ from this sum.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 95, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "KMU 2024 Q#95 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2024"}, {"id": "paper_a_q96_96", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 96, "subject": "Chemistry", "topic": "caloric calculation", "question": "One slice of bread with a tablespoon of peanut butter on it contains 20g carbohydrate, 10g protein, and 9g fat. Calculate total energy consumed in this intake.", "options": ["158kcal", "173kcal", "201kcal", "218kcal"], "correctIndex": 2, "explanation": "Using 4 kcal/g for carbs and protein and 9 kcal/g for fat: 20×4 + 10×4 + 9×9 = 80 + 40 + 81 = 201 kcal. The other totals come from incorrect multiplications.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 96, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "KMU 2024 Q#96 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2024"}, {"id": "paper_a_q97_97", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 97, "subject": "Chemistry", "topic": "enthalpy measurement", "question": "ΔH can be measured indirectly by applying", "options": ["Avogadro's law", "Faraday's law", "Gas's law", "Hess's law"], "correctIndex": 3, "explanation": "Hess's law allows determination of ΔH for a reaction by combining other known enthalpies, enabling indirect measurement. The other laws listed are not applicable to enthalpy summation in this way.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 97, "syllabusUnit": "Unit 4: Chemical Energetics", "pmdcTopic": "Enthalpy Changes, Hess's Law & Standard Heats of Reaction", "textbookCitation": "PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6", "citationString": "KMU 2024 Q#97 | Unit 4: Chemical Energetics | PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6"}, "year": "2024"}, {"id": "paper_a_q98_98", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 98, "subject": "Chemistry", "topic": "born haber lattice energy", "question": "The heat of sublimation of potassium is 98kJ/mol, the heat of dissociation of bromine gas is 192.5 kJ/mol. The ionization energy of K is 414 kJ/mol. The electron affinity of Br is -334.7 kJ/mol and the heat of formation of KBr is -405.8 kJ/mol. Calculate the lattice energy of KBr.", "options": ["-679.3", "-669.5", "679.3", "669.5"], "correctIndex": 0, "explanation": "Using a Born–Haber cycle: U = ΔHf - (ΔHsub + ½D(Br2) + IE + EA). Plugging values: U ≈ -405.8 - (98 + 96.25 + 414 - 334.7) ≈ -679.3 kJ/mol. Positive values or the other magnitudes do not match the cycle result.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 98, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "KMU 2024 Q#98 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "paper_a_q99_99", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 99, "subject": "Chemistry", "topic": "strong electrolytes", "question": "Which one of the following is a strong electrolyte in solution?", "options": ["Acetic acid", "Ammonium hydroxide", "Carbonic acid", "Potassium iodide"], "correctIndex": 3, "explanation": "Potassium iodide is an ionic salt that dissociates completely in water and is therefore a strong electrolyte. The acids and ammonia listed are weak electrolytes/base that do not fully ionize in solution.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 99, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#99 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q100_100", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 100, "subject": "Chemistry", "topic": "stoichiometry mass yield", "question": "When 4 g of magnesium was heated in excess of oxygen. Calculate the theoretical yield of magnesium oxide (MgO).", "options": ["3.7g", "4.2g", "5.4g", "6.6g"], "correctIndex": 3, "explanation": "Moles Mg = 4 / 24.305 ≈ 0.1646 mol, MgO molar mass ≈ 40.304 g/mol so mass ≈ 0.1646×40.304 ≈ 6.64 g (≈6.6 g). The other choices are inconsistent with this stoichiometric calculation.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 100, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#100 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q101_101", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 101, "subject": "Chemistry", "topic": "standard hydrogen electrode", "question": "The electrode potential of the standard hydrogen electrode is chosen as", "options": ["-1 V", "0 V", "1 V", "2 V"], "correctIndex": 1, "explanation": "By convention the standard hydrogen electrode (SHE) is assigned a potential of 0.00 V. The other values are not the standard reference value.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 101, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#101 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q102_102", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 102, "subject": "Chemistry", "topic": "electronegativity comparison", "question": "Electronegativity of Al is approximately equal to that of", "options": ["B", "Be", "Mg", "Na"], "correctIndex": 2, "explanation": "Aluminum's Pauling electronegativity is close to that of magnesium (both around the 1.3–1.6 range). Boron is significantly more electronegative and sodium is much less, so Mg is the closest match.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 102, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#102 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q103_103", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 103, "subject": "Chemistry", "topic": "alkali metal oxides", "question": "Which of the following alkali metal forms only normal oxide with O2?", "options": ["K", "Li", "Na", "Rb"], "correctIndex": 1, "explanation": "Lithium forms only the normal oxide Li2O, while heavier alkali metals tend to form peroxides or superoxides. Thus Li is the correct choice.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 103, "syllabusUnit": "Unit 8: Inorganic Chemistry & Periodicity", "pmdcTopic": "Periodic Trends, Group Chemistry & Transition Elements", "textbookCitation": "PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16", "citationString": "KMU 2024 Q#103 | Unit 8: Inorganic Chemistry & Periodicity | PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16"}, "year": "2024"}, {"id": "paper_a_q104_104", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 104, "subject": "Chemistry", "topic": "protective oxide layers", "question": "Third period element that initially reacts rapidly with oxygen to form a protective oxide coating that prevents further reactions is", "options": ["Al", "Ar", "Na", "Si"], "correctIndex": 0, "explanation": "Aluminium rapidly forms a thin, adherent Al2O3 layer that protects the underlying metal from further oxidation. Argon is inert, sodium forms other oxides but not the same protective passive layer behavior, and silicon behaves differently.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 104, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "KMU 2024 Q#104 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2024"}, {"id": "paper_a_q105_105", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 105, "subject": "Chemistry", "topic": "d d transitions", "question": "Cu2+ salt solution is blue in colour due to transition of electrons from", "options": ["d to d orbital", "p to d orbital", "p to p orbital", "s to p orbital"], "correctIndex": 0, "explanation": "The color of many transition-metal ion solutions, including Cu2+, arises from d→d electronic transitions within the partially filled d-orbitals. The other orbital transitions listed are not responsible for the characteristic copper(II) colour.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 105, "syllabusUnit": "Unit 8: Inorganic Chemistry & Periodicity", "pmdcTopic": "Periodic Trends, Group Chemistry & Transition Elements", "textbookCitation": "PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16", "citationString": "KMU 2024 Q#105 | Unit 8: Inorganic Chemistry & Periodicity | PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16"}, "year": "2024"}, {"id": "paper_a_q106_106", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 106, "subject": "Chemistry", "topic": "coordination compounds", "question": "Potassium ferrocyanide is which type of salt?", "options": ["Complex", "Double", "Mixed", "Normal"], "correctIndex": 0, "explanation": "Potassium ferrocyanide contains the complex anion [Fe(CN)6]4−, so it is classified as a complex salt (a coordination compound). It is not a simple double or normal salt in the conventional sense.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 106, "syllabusUnit": "Unit 8: Inorganic Chemistry & Periodicity", "pmdcTopic": "Periodic Trends, Group Chemistry & Transition Elements", "textbookCitation": "PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16", "citationString": "KMU 2024 Q#106 | Unit 8: Inorganic Chemistry & Periodicity | PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16"}, "year": "2024"}, {"id": "paper_a_q107_107", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 107, "subject": "Chemistry", "topic": "functional groups ketone", "question": "Name of ketone functional group is", "options": ["Amino", "Carbonyl", "Carboxyl", "Formyl"], "correctIndex": 1, "explanation": "A ketone contains a carbonyl functional group (C=O) bonded to two carbon atoms, so the functional group name is 'carbonyl'. Amino, carboxyl and formyl refer to different functional groups.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 107, "syllabusUnit": "Unit 11: Carbonyl Compounds (Aldehydes & Ketones)", "pmdcTopic": "Carbonyl Chemistry, Addition Reactions & Tests for Carbonyls", "textbookCitation": "PTB Chemistry XII Ch 12 (Aldehydes and Ketones); Federal Chemistry XII Ch 20", "citationString": "KMU 2024 Q#107 | Unit 11: Carbonyl Compounds (Aldehydes & Ketones) | PTB Chemistry XII Ch 12 (Aldehydes and Ketones); Federal Chemistry XII Ch 20"}, "year": "2024"}, {"id": "paper_a_q108_108", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 108, "subject": "Chemistry", "topic": "pyridine classification", "question": "Pyridine belongs to which class of organic compounds?", "options": ["Alicyclic", "Heterocyclic", "Homocyclic", "Hydrocarbon"], "correctIndex": 1, "explanation": "Pyridine is a six-membered aromatic ring containing one nitrogen atom, so it is a heterocyclic compound. The other options describe rings without heteroatoms (homocyclic/alicyclic) or simply hydrocarbons, so they are incorrect.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 108, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#108 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q109_109", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 109, "subject": "Chemistry", "topic": "element detection in organic compounds", "question": "Which of the following elements cannot be detected directly in a given organic compound?", "options": ["Chlorine", "Nitrogen", "Oxygen", "Phosphorous"], "correctIndex": 2, "explanation": "Oxygen cannot be easily detected directly by simple elemental tests in many classical organic analysis methods, whereas halogens, nitrogen and phosphorus give characteristic tests or may be detected by specific analytical techniques. Modern instrumental methods can detect oxygen but classic 'direct detection' typically refers to distinctive qualitative tests which oxygen lacks.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 109, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#109 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q110_110", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 110, "subject": "Chemistry", "topic": "homolytic fission", "question": "The homolytic fission of C-H bond in an alkane result in", "options": ["Alkyl free radical", "Carbanion", "Carbocation", "Methylpropane"], "correctIndex": 0, "explanation": "Homolytic fission splits the bond equally, giving one unpaired electron to each fragment and producing radicals; cleavage of a C–H bond yields an alkyl radical and a hydrogen radical. Carbanions and carbocations result from heterolytic cleavage, not homolytic.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 110, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "KMU 2024 Q#110 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2024"}, {"id": "paper_a_q111_111", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 111, "subject": "Chemistry", "topic": "addition of hbr to alkenes", "question": "Addition of HBr to isobutylene mainly gives", "options": ["isobutyl bromide", "n-butyl bromide", "sec-butyl bromide", "tert-butyl bromide"], "correctIndex": 3, "explanation": "Isobutylene (2-methylpropene) undergoes Markovnikov addition of HBr to give tert-butyl bromide (the tertiary bromide). The other isomeric bromides correspond to additions at different carbon skeletons or anti-Markovnikov outcomes and are not the major product under normal conditions.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 111, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "KMU 2024 Q#111 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2024"}, {"id": "paper_a_q112_112", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 112, "subject": "Chemistry", "topic": "dehydrohalogenation conditions", "question": "Dehydrohalogenation of alkylhalide is carried out in presence of", "options": ["Alcoholic KOH", "Aqueous KOH", "Conc. H2SO4", "Zn dust"], "correctIndex": 0, "explanation": "Dehydrohalogenation (elimination) to form alkenes is typically performed with alcoholic KOH which favors elimination over substitution. Aqueous KOH favors substitution, conc. H2SO4 is an acid and Zn dust is a reducing agent, so they are not the standard reagents for this elimination.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 112, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#112 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q113_113", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 113, "subject": "Chemistry", "topic": "carbocation definition", "question": "The carbon atom carrying positive charge and attached to three other atoms or groups is called", "options": ["Carbanion", "Carbene", "Carbocation", "Oxonium"], "correctIndex": 2, "explanation": "A carbon bearing a positive charge and bonded to three substituents is a carbocation. Carbanion is negatively charged carbon, carbene is a neutral divalent carbon with two bonds, and oxonium is a positively charged oxygen species.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 113, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "KMU 2024 Q#113 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q114_114", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 114, "subject": "Chemistry", "topic": "boiling points of alcohols", "question": "Which of the following has the highest boiling point?", "options": ["ethyl alcohol", "isopropyl alcohol", "n-propyl alcohol", "tert-butyl alcohol"], "correctIndex": 2, "explanation": "Boiling point rises with molecular size and falls with branching. Among these alcohols, n-propyl alcohol is the largest straight-chain member, so it has the highest boiling point (about 97 degrees). Ethanol is smaller, while isopropyl and tert-butyl alcohols are branched, which lowers their boiling points.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 114, "syllabusUnit": "Unit 10: Alkyl Halides, Alcohols & Phenols", "pmdcTopic": "Nucleophilic Substitution, Elimination Reactions & Phenol Acidity", "textbookCitation": "PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19", "citationString": "KMU 2024 Q#114 | Unit 10: Alkyl Halides, Alcohols & Phenols | PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19"}, "year": "2024"}, {"id": "paper_a_q115_115", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 115, "subject": "Chemistry", "topic": "reaction of alcohol with sodium", "question": "The reaction of an alcohol with sodium produces", "options": ["Aldehyde", "Alkoxide", "Ethane", "Ethene"], "correctIndex": 1, "explanation": "Alcohols react with sodium metal to form alkoxide salts and hydrogen gas. The formation of aldehyde, ethane, or ethene are not the direct products of the alcohol–sodium reaction.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 115, "syllabusUnit": "Unit 10: Alkyl Halides, Alcohols & Phenols", "pmdcTopic": "Nucleophilic Substitution, Elimination Reactions & Phenol Acidity", "textbookCitation": "PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19", "citationString": "KMU 2024 Q#115 | Unit 10: Alkyl Halides, Alcohols & Phenols | PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19"}, "year": "2024"}, {"id": "paper_a_q116_116", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 116, "subject": "Chemistry", "topic": "oxidation of secondary alcohols", "question": "Oxidation of secondary alcohol gives", "options": ["Carboxylic acid", "Ether", "Ketone", "Phenol"], "correctIndex": 2, "explanation": "Oxidation of a secondary alcohol yields a ketone because the secondary carbon (bearing two carbon substituents) is converted to a carbonyl without C–C bond cleavage. Primary alcohols give aldehydes or carboxylic acids on further oxidation; ethers and phenols are unrelated products.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 116, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "KMU 2024 Q#116 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2024"}, {"id": "paper_a_q117_117", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 117, "subject": "Chemistry", "topic": "reactivity of aldehydes", "question": "Which aldehyde is more reactive towards nucleophilic addition?", "options": ["Acetaldehyde", "Butyraldehyde", "Formaldehyde", "Propionaldehyde"], "correctIndex": 2, "explanation": "Formaldehyde lacks electron-donating alkyl groups, so its carbonyl carbon is the most electrophilic and thus most reactive toward nucleophiles. Larger aldehydes with alkyl substituents are less reactive due to both electronic and steric effects.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 117, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "KMU 2024 Q#117 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2024"}, {"id": "paper_a_q118_118", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 118, "subject": "Chemistry", "topic": "preparation of acetic acid", "question": "Acetic acid can be prepared by the hydrolysis of", "options": ["Ethanal", "Ethanol", "Methanoic acid", "Methyl cyanide"], "correctIndex": 3, "explanation": "Hydrolysis of methyl cyanide (acetonitrile) yields acetic acid (the nitrile hydrolyses to the corresponding carboxylic acid). Ethanal (an aldehyde) and ethanol (an alcohol) do not hydrolyse to acetic acid, and methanoic acid is a different carboxylic acid (formic acid).", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 118, "syllabusUnit": "Unit 12: Carboxylic Acids & Derivatives", "pmdcTopic": "Acidity of Carboxylic Acids & Acyl Derivatives", "textbookCitation": "PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21", "citationString": "KMU 2024 Q#118 | Unit 12: Carboxylic Acids & Derivatives | PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21"}, "year": "2024"}, {"id": "paper_a_q119_119", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 119, "subject": "Biology", "topic": "haemoglobin protein structure", "question": "Protein present in haemoglobin has _______ structure.", "options": ["Primary", "Secondary", "Tertiary", "Quaternary"], "correctIndex": 3, "explanation": "Hemoglobin is composed of multiple polypeptide chains (two alpha and two beta subunits) assembled together, so it exhibits quaternary structure. Primary, secondary, and tertiary describe levels within a single polypeptide chain, whereas quaternary refers to the assembly of multiple chains.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 119, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2024 Q#119 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q120_120", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 120, "subject": "Biology", "topic": "competitive inhibition", "question": "In competitive inhibition, the inhibitor", "options": ["Binds with substrate", "Competes with enzyme", "Competes with substrate", "Irreversibly binds with enzyme"], "correctIndex": 2, "explanation": "In competitive inhibition, the inhibitor resembles the substrate and competes with the substrate for binding at the enzyme's active site. It does not bind irreversibly (usually) and it competes with, not with the enzyme itself.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 120, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "KMU 2024 Q#120 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q121_121", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 121, "subject": "Physics", "topic": "centripetal force source", "question": "A car is moving in a circular path at a constant speed. What provides the necessary centripetal force to keep the car moving in this path?", "options": ["The car's inertia resisting any change in direction", "The car's mass pulling it towards the centre of the circle", "The engine's power pushing the car forward", "The friction between the tyres and the road"], "correctIndex": 3, "explanation": "The centripetal force required to keep a car moving in a circle is supplied by the lateral friction between the tyres and the road surface. Inertia does not provide a force toward the center, mass is not a pulling force, and engine power propels forward but does not provide the lateral centripetal force.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 121, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2024 Q#121 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q122_122", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 122, "subject": "Physics", "topic": "si units matching", "question": "Which of the following pairs correctly matches a physical quantity with its SI unit?", "options": ["Energy- Newton", "Force- Joule", "Power- Watt", "Velocity-m/s^2"], "correctIndex": 2, "explanation": "Power is measured in watts (W), so 'Power- Watt' is the correct pairing. Newton is the SI unit of force and Joule is the SI unit of energy; m/s^2 is a unit of acceleration, not velocity.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 122, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "KMU 2024 Q#122 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2024"}, {"id": "paper_a_q123_123", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 123, "subject": "Physics", "topic": "inertia definition", "question": "____ is the natural tendency of an object to remain at rest or in motion with constant velocity?", "options": ["Friction", "Inertia", "Mass", "Weight"], "correctIndex": 1, "explanation": "Inertia is the property of matter that resists changes in its state of motion, so it describes the tendency to remain at rest or move at constant velocity. Friction opposes motion, mass is a measure related to inertia, and weight is the force due to gravity.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 123, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2024 Q#123 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q124_124", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 124, "subject": "Physics", "topic": "conservation in collision", "question": "A car in motion hits and gets crashed into a tree trunk, what is NOT conserved?", "options": ["Kinetic energy alone", "Momentum alone", "Momentum and kinetic energy both", "Neither kinetic energy nor momentum"], "correctIndex": 0, "explanation": "In an inelastic collision like a car crashing into a tree, momentum of the closed system is conserved but kinetic energy is not conserved (some is dissipated as heat, deformation, sound). Thus 'Kinetic energy alone' is not conserved.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 124, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2024 Q#124 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q125_125", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 125, "subject": "Physics", "topic": "projectile motion components", "question": "The vertical and horizontal component of the projectile motion are", "options": ["Correlated with each other", "Dependent on each other", "Independent of each other", "Associated with each other"], "correctIndex": 2, "explanation": "In projectile motion (neglecting air resistance), horizontal and vertical motions are independent: horizontal motion has constant velocity while vertical motion has constant acceleration due to gravity. They are not dependent on each other, though they occur simultaneously.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 125, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2024 Q#125 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q126_126", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 126, "subject": "Physics", "topic": "horizontal projectile example", "question": "A ball is kicked horizontally from the top of a 10m high cliff with an initial speed of 15m/s. After 2 seconds, which of the following statement describes the ball's horizontal and vertical components?", "options": ["The horizontal velocity is 15m/s while vertical velocity is 20m/s downwards", "The horizontal velocity is 15m/s while vertical velocity is 15m/s downwards", "The horizontal velocity is 30m/s while vertical velocity is 20m/s downwards", "The horizontal velocity is 15m/s while vertical velocity is 0m/s"], "correctIndex": 0, "explanation": "Horizontal velocity remains constant at 15 m/s (no horizontal acceleration). Vertical velocity after 2 s under gravity (g ≈ 9.8 m/s^2) is v = g t ≈ 19.6 m/s downward, so option a (20 m/s downwards approximate) matches; the other options give incorrect horizontal or vertical values.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 126, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2024 Q#126 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q127_127", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 127, "subject": "Physics", "topic": "angle between force and displacement", "question": "How does an angle between the force applied and the direction of motion influence the work done on an object?", "options": ["Work is constant regardless of the angle", "Work is maximum when the angle is 0°", "Work is negative when the angle is 90°", "Work is 0 when the angle is 45°"], "correctIndex": 1, "explanation": "Work is given by W = F·d = Fd cosθ, so it is maximum when cosθ = 1, i.e. θ = 0°. At 90° cosθ = 0 so work is zero (not negative), and at 45° it is Fd cos45°, not zero.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 127, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2024 Q#127 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q128_128", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 128, "subject": "Physics", "topic": "work by weight", "question": "A nurse is pushing a wheelchair with an 80kg patient sitting on it. How much work is done by the patient's weight?", "options": ["Half of the work", "Maximum work", "Minimum work", "No work"], "correctIndex": 3, "explanation": "If the weight acts vertically while the wheelchair moves horizontally, the displacement has no component along the weight, so the weight does no work (zero).", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 128, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "KMU 2024 Q#128 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "paper_a_q129_129", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 129, "subject": "Physics", "topic": "work calculation", "question": "If a constant force of 10N is applied to move an object 5m in the direction of the force, what is the work done?", "options": ["2 J", "5 J", "15 J", "50 J"], "correctIndex": 3, "explanation": "Work = force × displacement when force and displacement are in same direction: W = 10 N × 5 m = 50 J.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 129, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2024 Q#129 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q130_130", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 130, "subject": "Physics", "topic": "escape velocity dependence", "question": "The escape velocity of a body in the gravitational field of Earth is dependent on:", "options": ["Angle on which it is thrown", "Both mass of the body and the angle at which it is thrown", "Mass of earth", "Mass of the body"], "correctIndex": 2, "explanation": "Escape velocity from a planet depends on the planet's mass and radius (here represented by mass of Earth) and not on the mass of the escaping body or the angle of projection.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 130, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2024 Q#130 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q131_131", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 131, "subject": "Physics", "topic": "angular measure", "question": "A wheel makes 3 complete revolutions. What is the total number of radians through which a point on wheel has rotated?", "options": ["2π", "3π", "6π", "9π"], "correctIndex": 2, "explanation": "One revolution equals 2π radians, so 3 revolutions equal 3 × 2π = 6π radians.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 131, "syllabusUnit": "Unit 3: Circular and Rotational Motion", "pmdcTopic": "Centripetal Acceleration, Angular Velocity & Rotational Dynamics", "textbookCitation": "PTB Physics XI Ch 5 (Circular Motion); Federal Physics XI Ch 5", "citationString": "KMU 2024 Q#131 | Unit 3: Circular and Rotational Motion | PTB Physics XI Ch 5 (Circular Motion); Federal Physics XI Ch 5"}, "year": "2024"}, {"id": "paper_a_q132_132", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 132, "subject": "Physics", "topic": "angular displacement definition", "question": "For rigid body that rotates about a fixed axis, the angle swept out by a line passing through any point on the body and intersecting the axis of rotation perpendicularly is called?", "options": ["Angular acceleration", "Angular displacement", "Angular momentum", "Angular velocity"], "correctIndex": 1, "explanation": "The described quantity is the angular displacement (the angle through which a line rotates). Angular velocity is rate of change, angular acceleration is rate of change of angular velocity, and angular momentum is a different conserved quantity.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 132, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2024 Q#132 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q133_133", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 133, "subject": "Physics", "topic": "centripetal force artificial gravity", "question": "In a rotating spaceship, to produce artificial gravity, what does the centripetal force do?", "options": ["Has no effect inside the spaceship", "Increases spaceship's rotation", "Pulls objects towards the centre", "Pushes the objects towards the outer wall"], "correctIndex": 3, "explanation": "From the rotating frame objects feel an outward apparent force (centrifugal) so they are pressed against the outer wall; the centripetal force is what keeps them moving in circle and results in contact with the outer wall, giving the sensation of gravity outward.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 133, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2024 Q#133 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q134_134", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 134, "subject": "Physics", "topic": "centripetal force dependency", "question": "When the mass of a body moving along a circle becomes half and radius becomes double, and v is constant, the centripetal force becomes?", "options": ["Double", "Half", "One-fourth", "Remains Same"], "correctIndex": 2, "explanation": "Centripetal force Fc = m v^2 / r. If m → m/2 and r → 2r, Fc becomes (m/2) v^2 /(2r) = (m v^2 / r) × (1/4), i.e. one-fourth of original.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 134, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2024 Q#134 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q135_135", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 135, "subject": "Physics", "topic": "wave interference", "question": "What happens when two waves of the same frequency and amplitude meet in phase?", "options": ["They cancel each other out resulting in a destructive interference", "They combine to form a wave double the amplitude, resulting in constructive interference", "They produce a wave with zero amplitude", "They produce a wave with the same amplitude as the individual waves"], "correctIndex": 1, "explanation": "When two identical waves meet in phase, their displacements add (constructive interference), producing a resultant with twice the amplitude. Destructive cancellation or zero amplitude occurs when they meet out of phase by 180°.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 135, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "KMU 2024 Q#135 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "paper_a_q136_136", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 136, "subject": "Physics", "topic": "polarization", "question": "Which type of waves can be polarized?", "options": ["Longitudinal waves", "Mechanical waves", "Sound waves", "Transverse waves"], "correctIndex": 3, "explanation": "Polarization is a property of transverse waves because their oscillations have directions perpendicular to propagation; longitudinal waves (like sound) oscillate parallel to propagation and cannot be polarized.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 136, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "KMU 2024 Q#136 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "paper_a_q137_137", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 137, "subject": "Physics", "topic": "longitudinal waves", "question": "For longitudinal waves", "options": ["The particles of the medium oscillate perpendicular to the wave's propagation", "The particles of the medium remain stationary as the wave passes through", "The particles of the medium oscillate along the direction of the wave's propagation", "Their velocity is enhanced when they travel through vacuum"], "correctIndex": 2, "explanation": "In longitudinal waves the medium's particles oscillate parallel to the direction of wave propagation (compressions and rarefactions). The other statements describe transverse waves, stationary nodes, or incorrect vacuum behavior.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 137, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "KMU 2024 Q#137 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "paper_a_q138_138", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 138, "subject": "Physics", "topic": "superposition principle", "question": "According to the principle of superimposition, when 2 or more waves overlap at a point in space, the amplitude of the resultant wave at that point is", "options": ["Always zero", "The product of the individual wave amplitude", "The product of the frequencies of the individual waves", "The sum of the amplitudes of the individual waves"], "correctIndex": 3, "explanation": "The principle of superposition states that displacements add algebraically, so the resultant amplitude is the sum of individual amplitudes. It is not generally a product or always zero.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 138, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "KMU 2024 Q#138 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "paper_a_q139_139", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 139, "subject": "Physics", "topic": "speed of sound dependencies", "question": "The speed of sound in a medium containing ideal gas is NOT dependent on", "options": ["Density", "Moisture", "Pressure", "Temperature"], "correctIndex": 0, "explanation": "In an ideal gas at fixed temperature the speed of sound depends on temperature and the gas's properties; for ideal gas formulations it depends on temperature and mean molecular weight, not directly on density or hydrostatic pressure independently. Of the listed choices, density is not an independent factor when using the ideal gas relation (speed depends on temperature), making 'Density' the least directly determining factor here.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 139, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "KMU 2024 Q#139 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "paper_a_q140_140", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 140, "subject": "Physics", "topic": "doppler effect", "question": "A police car, with its siren on, is moving towards a stationary listener. How does the stationary listener receive the frequency of the sound emitted by the siren? It", "options": ["Decreases", "Increases", "Stays the same", "Varies randomly"], "correctIndex": 1, "explanation": "By the Doppler effect, when the source moves toward a listener, wavefronts are compressed and the observed frequency increases. It does not decrease or remain random.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 140, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "KMU 2024 Q#140 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "paper_a_q141_141", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 141, "subject": "Physics", "topic": "adiabatic process", "question": "In an adiabatic process, how does the temperature of a gas change as its volume decreases?", "options": ["The temperature decreases", "The temperature increases", "The temperature remains constant", "The temperature first increases then decreases"], "correctIndex": 1, "explanation": "For an adiabatic compression (volume decreases, no heat exchange), work is done on the gas which raises its internal energy and thus its temperature increases. Isothermal would keep temperature constant.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 141, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "KMU 2024 Q#141 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2024"}, {"id": "paper_a_q142_142", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 142, "subject": "Physics", "topic": "isothermal expansion", "question": "During an isothermal expansion of an ideal gas, which of the following statement is true?", "options": ["Pressure and temperature of the gas increase", "The internal energy of the gas increases", "The temperature of the gas remains constant", "The work done by the gas is zero"], "correctIndex": 2, "explanation": "Isothermal means temperature remains constant. For an ideal gas internal energy depends only on temperature, so it does not change; the gas does perform work while absorbing heat, so work is not zero.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 142, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "KMU 2024 Q#142 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2024"}, {"id": "paper_a_q143_143", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 143, "subject": "Physics", "topic": "internal energy ideal gas", "question": "Consider an ideal gas confined to the cylinder with a fixed piston, on heating the gas, all the heat supplied increases", "options": ["Kinetic energy of the molecules", "Potential Energy of the molecules", "The intermolecular forces between gas molecules", "The number of gas molecules"], "correctIndex": 0, "explanation": "For an ideal gas there are no intermolecular potential energies, so heat supplied increases the kinetic energy (translational) of molecules which raises temperature. Potential energy or intermolecular forces are negligible for an ideal gas, and heating does not change particle number.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 143, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "KMU 2024 Q#143 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "paper_a_q144_144", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 144, "subject": "Physics", "topic": "coulombs law separation scaling", "question": "What is the increase in force between two charges if the separation between them is decreased by 50 percent?", "options": ["Becomes four times", "Doubles", "Increases by half", "Triples"], "correctIndex": 0, "explanation": "Coulomb's law: F ∝ 1/r^2. If separation is decreased by 50% (r becomes r/2) then F increases by (1/(r/2)^2)/(1/r^2) = (1/(r^2/4))/(1/r^2)=4. So the force becomes four times; the other options are inconsistent with the inverse-square dependence.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 144, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2024 Q#144 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q145_145", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 145, "subject": "Physics", "topic": "coulombs law distance", "question": "According to Coulomb's law, what happens to the electrostatic force between the 2-point charges if the distance between them is doubled?", "options": ["The force becomes one-fourth", "The force becomes half", "The force doubles", "The force remains the same"], "correctIndex": 0, "explanation": "Coulomb's law gives F ∝ 1/r^2. Doubling the distance (r→2r) reduces the force by (1/(2r)^2) = 1/4 of the original. The \"half\" or \"same\" answers ignore the square dependence.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 145, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2024 Q#145 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q146_146", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 146, "subject": "Physics", "topic": "definition of coulomb", "question": "What does one Coulomb represent in terms of charge?", "options": ["The amount of charge transported by a current of one Ampere in one second", "The charge of one proton", "The charge of one electron", "The charge required to create a force of 1 Newton between two charges separated by 1meter"], "correctIndex": 0, "explanation": "One coulomb is defined as the charge transported by a current of one ampere in one second (Q = I·t). The charge of a single proton/electron is ~1.6×10^-19 C (much smaller), and the last option confuses force definitions with charge.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 146, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "KMU 2024 Q#146 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2024"}, {"id": "paper_a_q147_147", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 147, "subject": "Physics", "topic": "potential of opposite charges midpoint", "question": "Two points charges, +5µC and -5µC are placed at points A and B, respectively, which are separated by a distance 2d. What is the electric potential at the midpoint M of the line joining A and B?", "options": ["2kQ/d", "kQ/d", "-kQ/d", "zero"], "correctIndex": 3, "explanation": "Potential is scalar: V = kq/r. At midpoint distances to +5µC and -5µC are equal, so V_total = k(+Q)/r + k(-Q)/r = 0. Thus potential is zero; the nonzero expressions ignore the sign cancellation.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 147, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "KMU 2024 Q#147 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "paper_a_q148_148", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 148, "subject": "Physics", "topic": "parallel plate capacitor scaling", "question": "In the case of a parallel plate capacitor, when the distance between the two plates is reduced to half and the area of the plate doubled, the capacitance", "options": ["Increases four times", "Increases six times", "Is doubled", "Remains the same"], "correctIndex": 0, "explanation": "Capacitance C = ε₀(κ)A/d. If A → 2A and d → d/2 then C → ε(2A)/(d/2)= ε(2A)·(2/d)=4·(εA/d); capacitance increases fourfold. The other choices misapply one of the two changes.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 148, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "KMU 2024 Q#148 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2024"}, {"id": "paper_a_q149_149", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 149, "subject": "Physics", "topic": "dielectric removed effect on electric field", "question": "If the dielectric material between the plates of the capacitor is removed, what happens to the electric field between the plates?", "options": ["The electric field becomes zero", "The electric field decreases", "The electric field increases", "The electric field remains the same"], "correctIndex": 2, "explanation": "Removing a dielectric (with relative permittivity κ>1) reduces the capacitance; for fixed plate charge, E = σ/ε increases because ε decreases. So the electric field increases. It does not become zero or remain unchanged.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 149, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "KMU 2024 Q#149 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2024"}, {"id": "paper_a_q150_150", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 150, "subject": "Physics", "topic": "capacitance dependence", "question": "Capacitance of a capacitor increases with a decrease in:", "options": ["Dielectric constant", "Plate area", "Permittivity", "Plate separation"], "correctIndex": 3, "explanation": "Capacitance C = εA/d, so C increases when plate separation d decreases. Decreasing dielectric constant or permittivity would reduce C; decreasing plate area also reduces C.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 150, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "KMU 2024 Q#150 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2024"}, {"id": "paper_a_q151_151", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 151, "subject": "Physics", "topic": "i v characteristics nonohmic", "question": "The I-V Graph for a non-Ohmic material is always", "options": ["Curved", "Horizontal", "Linear", "Perpendicular"], "correctIndex": 0, "explanation": "Non-Ohmic materials do not have a constant V/I ratio, so the I–V graph is nonlinear (curved). A linear graph represents Ohmic behavior; horizontal or perpendicular are not general descriptions.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 151, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "KMU 2024 Q#151 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2024"}, {"id": "paper_a_q152_152", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 152, "subject": "Physics", "topic": "temperature coefficient definition", "question": "Temperature coefficient of resistance is defined as increase in resistance per ohm original resistance per ___?", "options": ["Degree rise in temperature", "Unit increase in electric current", "Unit decrease in capacitance", "Degree drop in temperature"], "correctIndex": 0, "explanation": "Temperature coefficient α is defined as fractional change in resistance per degree rise in temperature (ΔR/(R₀·ΔT)). The other options are unrelated definitions.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 152, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "KMU 2024 Q#152 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2024"}, {"id": "paper_a_q153_153", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 153, "subject": "Physics", "topic": "temperature coefficient metals", "question": "For metals, the temperature coefficient of resistance is:", "options": ["Infinity", "Negative", "Positive", "Zero"], "correctIndex": 2, "explanation": "Metals typically have a positive temperature coefficient: resistance increases with temperature because increased lattice vibrations scatter electrons. Negative or zero are not characteristic of ordinary metals.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 153, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "KMU 2024 Q#153 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2024"}, {"id": "paper_a_q154_154", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 154, "subject": "Physics", "topic": "filament resistance power relationship", "question": "If R1 and R2 are respectively the filament resistance of a 100-Watt bulb and 200-Watt bulb designed to operate on the same voltage, then power of:", "options": ["R1 is two times R2", "R2 is two times R1", "R2 is four times R1", "R1 is four times R2"], "correctIndex": 0, "explanation": "For same voltage V, power P = V^2/R so R = V^2/P. Thus R1/R2 = (V^2/100)/(V^2/200) = 200/100 = 2, so R1 is two times R2. The other options invert or square the ratio incorrectly.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 154, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "KMU 2024 Q#154 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "paper_a_q155_155", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 155, "subject": "Physics", "topic": "maximum power transfer theorem", "question": "The maximum power transfer theorem states that maximum power is delivered to the load when", "options": ["The load resistance is half of the source resistance", "The load resistance is zero", "The load resistance is double the source resistance", "The load resistance is equal to the source resistance"], "correctIndex": 3, "explanation": "Maximum power transfer occurs when load resistance equals Thevenin/source resistance (R_L = R_source). The other choices do not satisfy the derivation using Thevenin equivalent and power expression.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 155, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "KMU 2024 Q#155 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "paper_a_q156_156", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 156, "subject": "Physics", "topic": "electron volt unit", "question": "Electron Volt (eV) is another unit of", "options": ["Charge", "Current", "Energy", "Power"], "correctIndex": 2, "explanation": "An electronvolt is the energy gained by an electron moving through a potential difference of one volt, so it's a unit of energy. It is not a unit of charge, current, or power.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 156, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "KMU 2024 Q#156 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2024"}, {"id": "paper_a_q157_157", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 157, "subject": "Physics", "topic": "magnetic force on moving electron", "question": "An electron is moving perpendicular to the magnetic field, which of the following is correct statement about electromagnetic force acting on the electron?", "options": ["Force acting is equal to electron charge", "Force acting is equal to the magnetic field strength", "Force acting is maximum", "Zero force is acting on it"], "correctIndex": 2, "explanation": "Magnetic force magnitude on a charge is F = qvB sinθ. For motion perpendicular to the field (θ=90°), sinθ=1 so the force is maximal. It is not equal to just the charge or the field strength alone, and it is not zero.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 157, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2024 Q#157 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q158_158", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 158, "subject": "Physics", "topic": "lorentz force expression", "question": "For a positive charged particle (q) moving with a velocity (v) in a magnetic Filed of flux density B, the force (F) acting on the charge particle is given by the expression?", "options": ["F = Fv x B", "F = qv x B", "F = v x B/q", "q = v x B/F"], "correctIndex": 1, "explanation": "The Lorentz magnetic force is F = q (v × B). The other formulas are incorrect rearrangements or contain extra/misplaced factors.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 158, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2024 Q#158 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q159_159", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 159, "subject": "Physics", "topic": "magnetic field inside solenoid", "question": "Which of the following statement is true about the magnetic filed inside a solenoid?", "options": ["It is along the axis of the coil", "It is circular around the wires", "It is strongest at the ends of the solenoid", "It is zero when current flows through it"], "correctIndex": 0, "explanation": "Inside a long solenoid the magnetic field is approximately uniform and directed along the axis of the coil. The field is not circular around the wires (that describes local field near a straight wire), nor is it zero; it is strongest in the interior, not at the ends.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 159, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "KMU 2024 Q#159 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2024"}, {"id": "paper_a_q160_160", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 160, "subject": "Physics", "topic": "motional emf calculation", "question": "One-meter-long copper rod is moving with speed 20 m/sec in the magnetic field of strength 0.6 tesla what is the value of induced emf?", "options": ["12 V", "19.4 V", "20.6 V", "25 V"], "correctIndex": 0, "explanation": "Motional emf ε = B ℓ v for rod of length ℓ moving perpendicular to B: ε = 0.6×1×20 = 12 V. The other numeric options are incorrect products.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 160, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "KMU 2024 Q#160 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2024"}, {"id": "paper_a_q161_161", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 161, "subject": "Physics", "topic": "inductance dependence", "question": "The inductance of a coil depends on.", "options": ["Number of turns", "Resistance of the wire used", "Type of insulation used on the wire", "Voltage applied to the coil"], "correctIndex": 0, "explanation": "Inductance L scales with the square of the number of turns and coil geometry and core material. Resistance and insulation type are secondary and do not determine the inductance; applied voltage does not change the inductance.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 161, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "KMU 2024 Q#161 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2024"}, {"id": "paper_a_q162_162", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 162, "subject": "Physics", "topic": "direction of induced current", "question": "The direction of induced current is determined by?", "options": ["Ampere’s law", "Faraday’s law", "Lenz’s law", "Ohm’s law"], "correctIndex": 2, "explanation": "Lenz's law gives the direction of an induced current such that it opposes the change in magnetic flux that produced it. Faraday's law gives the magnitude of induced emf but not the direction; Ampere’s and Ohm’s laws are unrelated to the direction of induced current.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 162, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "KMU 2024 Q#162 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2024"}, {"id": "paper_a_q163_163", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 163, "subject": "Physics", "topic": "lenz law consistency", "question": "Lenz’s law is consistent with the", "options": ["Ampere’s Law", "Faraday’s law", "Law of conservation of energy", "Ohm’s law"], "correctIndex": 2, "explanation": "Lenz's law ensures that the induced current produces a magnetic effect opposing the change that created it, which is a manifestation of conservation of energy. It complements Faraday's law (which gives magnitude) and is not the same as Ampere’s or Ohm’s laws.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 163, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "KMU 2024 Q#163 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2024"}, {"id": "paper_a_q164_164", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 164, "subject": "Physics", "topic": "transformer principle", "question": "The basic principle behind the operation of the transformer is", "options": ["Coulomb’s law", "Electromagnetic induction", "Gas’s Law", "Hess’s law"], "correctIndex": 1, "explanation": "Transformers operate by a changing magnetic flux in the primary coil inducing an emf in the secondary coil - this is electromagnetic induction. Coulomb’s law, gas laws, and Hess’s law are unrelated to transformer action.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 164, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "KMU 2024 Q#164 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2024"}, {"id": "paper_a_q165_165", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 165, "subject": "Physics", "topic": "pn junction reverse current", "question": "When the PN junction is reverse-biased, its reverse current is of the order of:", "options": ["Gigamperes", "Kiloamperes", "Megaamperes", "Microamperes"], "correctIndex": 3, "explanation": "Reverse saturation current in a reverse-biased PN junction is extremely small, typically on the order of microamperes (or even nano- to picoamperes), not kilo-/mega-/gigamperes.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 165, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "KMU 2024 Q#165 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2024"}, {"id": "paper_a_q166_166", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 166, "subject": "Physics", "topic": "photon momentum", "question": "The momentum of moving photon is:", "options": ["mc^2", "λ / h", "h / λ", "zero"], "correctIndex": 2, "explanation": "A photon's momentum is given by p = h/λ (Planck’s constant divided by wavelength). mc^2 is energy for mass-bearing particles, λ/h is the reciprocal of the correct form, and photon momentum is not zero.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 166, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "KMU 2024 Q#166 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q167_167", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 167, "subject": "Physics", "topic": "de broglie wavelength falling body", "question": "In every instant of time, wavelength associated with a freely falling body:", "options": ["Decreases", "Increases two times", "Increases four times", "Remains constant"], "correctIndex": 0, "explanation": "As a freely falling body speeds up under gravity, its de Broglie wavelength (which is inversely proportional to momentum) decreases. It does not remain constant or increase.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 167, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "KMU 2024 Q#167 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "paper_a_q168_168", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 168, "subject": "Physics", "topic": "photoelectric threshold frequency", "question": "As per 2nd photoelectric experiment, photoelectric effect does not occur if the frequency of the incident light is?", "options": ["Below the threshold frequency", "Equals the threshold frequency", "Three times the threshold frequency", "Twice the threshold frequency"], "correctIndex": 0, "explanation": "The photoelectric effect requires photons with energy at least equal to the work function; if the incident frequency is below the threshold, no electrons are emitted. Frequencies equal to or above the threshold do produce emission.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 168, "syllabusUnit": "Unit 11: Dawn of Modern Physics", "pmdcTopic": "Photoelectric Effect, Wave-Particle Duality & Photons", "textbookCitation": "PTB Physics XII Ch 19 (Dawn of Modern Physics); Federal Physics XII Ch 17", "citationString": "KMU 2024 Q#168 | Unit 11: Dawn of Modern Physics | PTB Physics XII Ch 19 (Dawn of Modern Physics); Federal Physics XII Ch 17"}, "year": "2024"}, {"id": "paper_a_q169_169", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 169, "subject": "Physics", "topic": "hydrogen transition wavelength", "question": "If an electron in the hydrogen atom jumps from second to first orbit, the emitted radiation has a wavelength of?", "options": ["4/3RH", "3/4RH", "RH", "4RH"], "correctIndex": 0, "explanation": "The wavelength for the n=2 to n=1 (Lyman-alpha) transition can be expressed in terms of Rydberg constant; the standard derived form corresponds to the 4/3RH expression listed (as printed).", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 169, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "KMU 2024 Q#169 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "paper_a_q170_170", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 170, "subject": "Physics", "topic": "black body radiation", "question": "Black body is an ideal radiator that radiates ______ at all wavelengths", "options": ["Inconsistently", "Distinctly", "Equally", "Unequally"], "correctIndex": 2, "explanation": "An ideal black body absorbs and emits radiation at all wavelengths according to a characteristic distribution; the phrase on the paper states it ‘radiates equally at all wavelengths’ in the given choices context.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 170, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "KMU 2024 Q#170 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "paper_a_q171_171", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 171, "subject": "Physics", "topic": "mass number definition", "question": "Mass number A refers to _____", "options": ["Number of electrons", "Number of nucleons", "Number of neutrons", "Number of protons"], "correctIndex": 1, "explanation": "Mass number (A) is the total number of nucleons (protons + neutrons) in the nucleus. It is not the number of electrons or only neutrons/protons alone.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 171, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "KMU 2024 Q#171 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2024"}, {"id": "paper_a_q172_172", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 172, "subject": "Physics", "topic": "lambda constant", "question": "λ is a _____ constant:", "options": ["Decay", "Dielectric", "Plank’s", "Proportionality"], "correctIndex": 2, "explanation": "In the context of the photoelectric and related formulae, λ often denotes wavelength; the option intended as 'Planck's' (misspelled 'Plank’s' on the paper) identifies Planck’s constant, which is associated with such relations. The other choices do not correctly name Planck’s constant.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 172, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "KMU 2024 Q#172 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2024"}, {"id": "paper_a_q173_173", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 173, "subject": "Physics", "topic": "gamma camera sources", "question": "Gamma ray camera can observe radiations from the ____ that are concentrated in the organs", "options": ["Atoms", "Isotopes", "Nucleons", "Neutrons"], "correctIndex": 1, "explanation": "Gamma cameras detect gamma radiation emitted by radioactive isotopes (radiotracers) that have concentrated in organs for imaging. Atoms, nucleons, or neutrons are not the specific clinical source term used here.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 173, "syllabusUnit": "Unit 12: Atomic and Nuclear Physics", "pmdcTopic": "Bohr Model, Radioactivity & Nuclear Reactions", "textbookCitation": "PTB Physics XII Ch 20 (Atomic Spectra) & Ch 21 (Nuclear Physics); Federal Physics XII Ch 18-19", "citationString": "KMU 2024 Q#173 | Unit 12: Atomic and Nuclear Physics | PTB Physics XII Ch 20 (Atomic Spectra) & Ch 21 (Nuclear Physics); Federal Physics XII Ch 18-19"}, "year": "2024"}, {"id": "paper_a_q174_174", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 174, "subject": "English", "topic": "vocabulary seller", "question": "A person who sells goods and services is a ______", "options": ["Consumer", "Purchaser", "Patron", "Vendor"], "correctIndex": 3, "explanation": "A vendor is someone who sells goods or services. Consumer and purchaser buy goods, and patron can mean a customer but vendor specifically denotes a seller.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 174, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "KMU 2024 Q#174 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2024"}, {"id": "paper_a_q175_175", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 175, "subject": "English", "topic": "vocabulary subtle", "question": "The detective noticed a subtle change in the suspect's tone when he asked about her whereabouts on the night of the crime, which hinted at something more significant. What does “subtle” most likely mean?", "options": ["Dramatic", "Notable", "Obvious", "Slight"], "correctIndex": 3, "explanation": "“Subtle” typically means slight or not obvious. Dramatic and obvious are antonyms; 'notable' implies more obvious significance than 'subtle' suggests.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 175, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "KMU 2024 Q#175 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2024"}, {"id": "paper_a_q176_176", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 176, "subject": "English", "topic": "vocabulary composed", "question": "Despite the complicated situation, she remained _____, calmly assessing her options before deciding. Fill in the blank with the appropriate choice:", "options": ["Composed", "Erratic", "Frantic", "Hysterical"], "correctIndex": 0, "explanation": "‘Composed’ means calm and in control, which fits the context. The other options (erratic, frantic, hysterical) indicate loss of calm and therefore do not fit.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 176, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "KMU 2024 Q#176 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2024"}, {"id": "paper_a_q177_177", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 177, "subject": "English", "topic": "synonym elated", "question": "Find out synonym for \"Elated\"", "options": ["Confused", "Disappointed", "Nervous", "Overjoyed"], "correctIndex": 3, "explanation": "‘Elated’ means very happy or overjoyed. The other words are antonyms or unrelated emotions.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 177, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "KMU 2024 Q#177 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2024"}, {"id": "paper_a_q178_178", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 178, "subject": "English", "topic": "correct tense sentence", "question": "Choose the sentence with the correct tense and sentence structure:", "options": ["He is going to the market yesterday.", "I had been waiting for the bus, and it arrives.", "She will finish her homework before she went to bed.", "They were playing football when it started to rain."], "correctIndex": 3, "explanation": "Option (d) correctly uses past continuous ('were playing') with past simple ('started'), which is grammatically correct. The other options mix incompatible tenses.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 178, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "KMU 2024 Q#178 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2024"}, {"id": "paper_a_q179_179", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 179, "subject": "English", "topic": "correct use of know", "question": "Choose the correct sentence:", "options": ["She didn't knew about the surprise party.", "She hasn't knew about the surprise party.", "She didn't know about the surprise party.", "She doesn't know about the surprise party."], "correctIndex": 2, "explanation": "In negative past tense the auxiliary 'did' takes the base form of the main verb: 'didn't know' is correct. 'Didn't knew' and 'hasn't knew' are ungrammatical; 'doesn't know' is present tense.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 179, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "KMU 2024 Q#179 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2024"}, {"id": "paper_a_q180_180", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 180, "subject": "English", "topic": "perfect tense after", "question": "After she ______ the stairs, her heart almost gave out from exhaustion.", "options": ["Has climbed", "Have climbed", "Had climbed", "Was climbing"], "correctIndex": 2, "explanation": "The correct sequence uses past perfect ('had climbed') to show that one past action occurred before another past action. 'Has' and 'have' are present perfect, and 'was climbing' does not express the completed action before the heart gave out.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 180, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "KMU 2024 Q#180 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2024"}, {"id": "paper_a_q181_181", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 181, "subject": "English", "topic": "punctuation question", "question": "Punctuate the given sentence correctly. The teacher asked did you complete your homework", "options": ["The teacher asked, did you complete your homework?", "The teacher asked, \"Did you complete your homework?\"", "The teacher asked, \"did you complete your homework\".", "The teacher asked, did you complete your homework."], "correctIndex": 1, "explanation": "Direct speech requires quotation marks and proper punctuation: The teacher asked, \"Did you complete your homework?\" is the correct punctuation and capitalization for the quoted question.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 181, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "KMU 2024 Q#181 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2024"}, {"id": "paper_a_q182_182", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 182, "subject": "English", "topic": "punctuation sentence", "question": "Punctuate the following sentence correctly. Lets meet at Sarahs house after school", "options": ["Let's meet at Sarah's house after school.", "Let's meet at Sarahs house after school.", "Lets meet at Sarah's house after school.", "Let's meet, at Sarah's house after school."], "correctIndex": 0, "explanation": "Option (a) correctly uses the apostrophe in Sarah's and places no extra commas; it reads as a natural imperative sentence. The other choices either omit the possessive apostrophe (b, c) or insert an unnecessary comma (d).", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 182, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "KMU 2024 Q#182 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2024"}, {"id": "paper_a_q183_183", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 183, "subject": "English", "topic": "prepositions", "question": "Do you usually take a bus........ the market?", "options": ["By", "For", "Of", "To"], "correctIndex": 3, "explanation": "The correct preposition with 'take a bus' and destination is 'to' (go to the market). 'By' indicates means, 'for' indicates purpose, and 'of' is not used for destination.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 183, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "KMU 2024 Q#183 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2024"}, {"id": "paper_a_q184_184", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 184, "subject": "English", "topic": "preposition collocation", "question": "I have been working ______ this project for two weeks.", "options": ["At", "By", "To", "On"], "correctIndex": 3, "explanation": "The idiomatic collocation is 'work on a project', so the correct preposition is 'on': 'I have been working on this project for two weeks.' 'At', 'by' and 'to' are not used with 'work' in this sense.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 184, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "KMU 2024 Q#184 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2024"}, {"id": "paper_a_q185_185", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 185, "subject": "English", "topic": "parallelism", "question": "Identify the sentence that contains an ERROR in word order, style, or vocabulary:", "options": ["He has a talent for solving complex problems.", "She enjoys reading, writing, and to paint.", "The quick brown fox jumps over the lazy dog.", "They quickly adapted to the new environment."], "correctIndex": 1, "explanation": "Option (b) violates parallelism: the list should use the same grammatical form (e.g., 'reading, writing, and painting'). The other sentences are grammatically correct.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 185, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "KMU 2024 Q#185 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2024"}, {"id": "paper_a_q186_186", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 186, "subject": "English", "topic": "error identification", "question": "Identify the ERROR in the sentence: The chef quickly prepared, delicious and it served a meal.", "options": ["Punctuation", "Style", "Vocabulary", "Word order"], "correctIndex": 0, "explanation": "The sentence contains incorrect punctuation (an unnecessary comma and awkward phrasing). The chief problem is punctuation/structure rather than choice of words or vocabulary.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 186, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "KMU 2024 Q#186 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2024"}, {"id": "paper_a_q187_187", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 187, "subject": "English", "topic": "analogy vocabulary", "question": "Order is the law of civilization as chaos is the law of the ______. The most appropriate word to be filled in is:", "options": ["City", "Metropolis", "Universe", "Wilderness"], "correctIndex": 3, "explanation": "The analogy pairs 'order' with 'civilization', so 'chaos' pairs with something opposite or uncultivated; 'wilderness' fits that contrast best. The other choices do not provide the same antonymic relation.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 187, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "KMU 2024 Q#187 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2024"}, {"id": "paper_a_q188_188", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 188, "subject": "English", "topic": "analogy", "question": "Blueprint is to architect as algorithm is to ______", "options": ["Designer", "Engineer", "Physician", "Programmer"], "correctIndex": 3, "explanation": "A blueprint guides an architect in building; similarly, an algorithm guides a programmer. The other professions are less directly associated with algorithms.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 188, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "KMU 2024 Q#188 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2024"}, {"id": "paper_a_q189_189", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 189, "subject": "English", "topic": "vocabulary synonym", "question": "Which of the following words is a synonym for \"meticulous\"?", "options": ["Abhorrent", "Heedless", "Incautious", "Precise"], "correctIndex": 3, "explanation": "'Meticulous' means very careful and precise; option (d) 'Precise' is the synonym. The other options have opposite or unrelated meanings.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 189, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "KMU 2024 Q#189 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2024"}, {"id": "paper_a_q190_190", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 190, "subject": "Logical Reasoning", "topic": "number sequence", "question": "Find out the missing term in the sequence: 15, 14, 12, 9, ?", "options": ["5", "6", "7", "8"], "correctIndex": 0, "explanation": "The differences between successive terms grow by one each time: 15 to 14 is -1, 14 to 12 is -2, 12 to 9 is -3, so the next difference is -4. That gives 9 - 4 = 5.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 190, "syllabusUnit": "Pattern Recognition & Sequences", "pmdcTopic": "Numerical & Pattern Sequence Reasoning", "textbookCitation": "PMDC MDCAT Logical Reasoning Framework", "citationString": "KMU 2024 Q#190 | Pattern Recognition & Sequences | PMDC MDCAT Logical Reasoning Framework"}, "year": "2024"}, {"id": "paper_a_q191_191", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 191, "subject": "Logical Reasoning", "topic": "syllogism", "question": "All omnivores are herbivores. No herbivores are carnivores. Some carnivores are humans. Which of the following conclusions are TRUE? CONCLUSIONS: I. Some humans are carnivores. II. No carnivores are omnivores. III. Some omnivores are carnivores.", "options": ["I and II", "I and III", "II and III", "I, II and III"], "correctIndex": 0, "explanation": "Given the premises, 'Some humans are carnivores' (I) follows from 'Some carnivores are humans.' Also, since no herbivores are carnivores and all omnivores are herbivores, carnivores cannot be omnivores, so II is true. III contradicts the premises. Therefore I and II are the valid conclusions.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 191, "syllabusUnit": "Deductive & Analytical Reasoning", "pmdcTopic": "Premise Analysis & Logical Syllogisms", "textbookCitation": "PMDC MDCAT Logical Reasoning Guide (Deductions & Assumptions)", "citationString": "KMU 2024 Q#191 | Deductive & Analytical Reasoning | PMDC MDCAT Logical Reasoning Guide (Deductions & Assumptions)"}, "year": "2024"}, {"id": "paper_a_q192_192", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 192, "subject": "Logical Reasoning", "topic": "cause and effect relation", "question": "Read the following statements and identify the best cause-and-effect relation: I. Sara's productivity at work has significantly decreased over the past month. II. Sara has been experiencing frequent interruptions due to ongoing construction work near her office. Which of the following best describes the cause-and-effect relationship?", "options": ["Sara's decreased productivity is causing the construction work.", "The ongoing construction work is causing Sara's decreased productivity.", "Sara's productivity was already decreasing before the construction work began.", "The construction work is unrelated to Sara's productivity."], "correctIndex": 1, "explanation": "Statement II (frequent interruptions from construction) plausibly explains the decrease in Sara's productivity; thus II causes I. The other options either reverse causation or state no relation without support.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 192, "syllabusUnit": "Deductive & Analytical Reasoning", "pmdcTopic": "Premise Analysis & Logical Syllogisms", "textbookCitation": "PMDC MDCAT Logical Reasoning Guide (Deductions & Assumptions)", "citationString": "KMU 2024 Q#192 | Deductive & Analytical Reasoning | PMDC MDCAT Logical Reasoning Guide (Deductions & Assumptions)"}, "year": "2024"}, {"id": "paper_a_q193_193", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 193, "subject": "Logical Reasoning", "topic": "percentage discount", "question": "A store offers a 10% discount on all items. After applying the discount, the price of an item is Rs. 450. What was the original price of the item?", "options": ["Rs. 490", "Rs. 495", "Rs. 500", "Rs. 505"], "correctIndex": 2, "explanation": "If discounted price is 450 and that's 90% of original, original = 450 / 0.9 = 500. Options (a), (b), (d) are not equal to 500.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 193, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "KMU 2024 Q#193 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2024"}, {"id": "paper_a_q194_194", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 194, "subject": "Logical Reasoning", "topic": "distance and displacement", "question": "I went 10m to the East from my house, then turned north and walked another 15m, and then I turned west and covered 12m, and then turned south and covered 15m. How far am I from my house?", "options": ["0 m", "1 m", "2 m", "3 m"], "correctIndex": 2, "explanation": "Track the two axes separately. East-west: 10 m east then 12 m west leaves you 2 m west of home. North-south: 15 m north then 15 m south cancel to zero. So the straight-line distance from home is 2 m.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 194, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "KMU 2024 Q#194 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2024"}, {"id": "paper_a_q195_195", "paperTitle": "KMU MDCAT 2024 (Paper A)", "shortTitle": "KMU 2024", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "questionNumber": 195, "subject": "Logical Reasoning", "topic": "inequalities transitive relations", "question": "If a>b, b>c, and d>a then?", "options": ["b<d", "a<c", "b>d", "c>d"], "correctIndex": 0, "explanation": "From d>a and a>b we get d>b, which is the same as b<d, so option (a) is correct. Options (b), (c), and (d) contradict the given ordering.", "reference": {"sourcePaper": "KMU MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "Khyber Medical University", "province": "Khyber Pakhtunkhwa", "originalQuestionNumber": 195, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "KMU 2024 Q#195 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2024"}, {"id": "official_paper_q1_1", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 1, "subject": "Biology", "topic": "membrane lipids functions", "question": "Which function cannot be attributed to plasma membrane lipids?", "options": ["Recognition of cells having non-self surface markers", "Maintaining cell membrane flexibility", "Control of metabolic reaction across cell membrane", "Binding ligands for intracellular response"], "correctIndex": 2, "explanation": "Membrane lipids provide a hydrophobic barrier, contribute to membrane flexibility and can participate in cell recognition via glycolipids, but they do not control metabolic reactions across the membrane. Control of transport and enzymatic activities at the membrane is performed mainly by membrane proteins (transporters and enzymes), not by the lipid molecules themselves.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 1, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2024 Q#1 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "official_paper_q2_2", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 2, "subject": "Biology", "topic": "disaccharide glycosidic linkage", "question": "Loss of reactivity of sucrose is due to its:", "options": ["High solubility in water", "Polar nature", "Unavailability of functional group", "Alpha 1-2 Glycosidic linkage"], "correctIndex": 3, "explanation": "Sucrose has an α-1,2 glycosidic bond between the anomeric carbons of glucose and fructose, so neither anomeric carbon is free and the molecule is non-reducing. That lack of a free reducing end explains its reduced chemical reactivity compared with reducing sugars.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 2, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "NUMS 2024 Q#2 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2024"}, {"id": "official_paper_q3_3", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 3, "subject": "Biology", "topic": "peptide hormone structure", "question": "Proteins with tertiary structure are helpful in:", "options": ["Carrying messages from glands to target organs", "Maintaining epithelial lining of skin", "Making the matrix of connective tissue", "Helping muscle contraction"], "correctIndex": 0, "explanation": "Many hormones are peptides whose biological activity depends on their folded tertiary structure to bind receptors and be transported in the bloodstream. Other options describe structural or contractile roles that are characteristic of other protein types, not hormone signalling molecules.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 3, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2024 Q#3 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "official_paper_q4_4", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 4, "subject": "Biology", "topic": "disulfide bonds in keratin", "question": "Rebounding is process of straightening the curly hairs. Which bond is targeted by oxidizing agents used during this process?", "options": ["Peptide bond", "Ionic bond", "Disulphide bridge", "Hydrogen bond"], "correctIndex": 2, "explanation": "Hair curliness is stabilized by disulfide (cystine) bonds between keratin polypeptides; oxidizing or reducing treatments break or rearrange those S–S bonds to change hair shape. Peptide, ionic or hydrogen bonds are not the primary covalent linkages targeted in permanent/rebonding treatments.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 4, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2024 Q#4 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "official_paper_q5_5", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 5, "subject": "Biology", "topic": "heavy metal protein interactions", "question": "Ions of heavy metal are harmful for living organisms because of their ability to:", "options": ["Cleave nucleic acid", "Interfere with fat metabolism", "Break glycosidic bonds", "Destabilize proteins"], "correctIndex": 3, "explanation": "Heavy metal ions bind strongly to thiol and other side chains in proteins, disrupting native folding and leading to denaturation and loss of function. While some metals can damage nucleic acids or lipids indirectly, the principal acute toxicity mechanism is destabilization of protein structure.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 5, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2024 Q#5 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "official_paper_q6_6", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 6, "subject": "Biology", "topic": "cytochrome b6f and proton gradient", "question": "Which mechanism would be compromised in the absence of cytochrome complex during light reaction of photosynthesis?", "options": ["Reduction of reaction center chlorophyll", "Photolysis of water", "Oxidation of primary electron receptor", "Establishment of proton gradient across thylakoid membrane"], "correctIndex": 3, "explanation": "The cytochrome complex (cytochrome b6f) mediates electron transfer between photosystems and couples that transfer to proton translocation across the thylakoid membrane, creating the proton motive force used for ATP synthesis. Without it the proton gradient cannot be properly established, so option D is correct.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 6, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "NUMS 2024 Q#6 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2024"}, {"id": "official_paper_q7_7", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 7, "subject": "Biology", "topic": "glycolytic isomerization steps", "question": "During glycolysis, isomerization takes place in the formation of:", "options": ["Dihydroxyacetone phosphate and 2-phosphoglycerate", "G3P and fructose 6-phosphate", "PEP and pyruvate", "Fructose 6-phosphate and 3-phosphoglycerate"], "correctIndex": 1, "explanation": "Glycolysis includes multiple isomerization steps: phosphoglucose isomerase converts glucose-6-phosphate to fructose-6-phosphate, and triose phosphate isomerase interconverts DHAP and glyceraldehyde-3-phosphate (G3P). Thus formation of G3P and fructose-6-phosphate involves isomerization reactions, matching option B.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 7, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "NUMS 2024 Q#7 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2024"}, {"id": "official_paper_q8_8", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 8, "subject": "Biology", "topic": "pep carboxylase specificity in c4", "question": "Presence of PEP carboxylase in C4 plants enables them to avoid photorespiration due to:", "options": ["Presence of enzyme in high concentration", "Absence of Rubisco", "PEP carboxylase being strictly carboxylase", "High yield of enzyme"], "correctIndex": 2, "explanation": "PEP carboxylase fixes CO2 into oxaloacetate and is specific for CO2 (it does not use O2 as a substrate), so C4 plants concentrate CO2 in bundle-sheath cells and avoid Rubisco's oxygenase activity (photorespiration). The strict carboxylase activity of PEP carboxylase underlies this advantage.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 8, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "NUMS 2024 Q#8 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2024"}, {"id": "official_paper_q9_9", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 9, "subject": "Biology", "topic": "acetyl coa central metabolite", "question": "Fats and proteins are metabolized via — which of the following serves as common duct for both metabolisms?", "options": ["Acetyl-CoA", "Pyruvate", "G3P", "Lactate"], "correctIndex": 0, "explanation": "Both fatty acid β-oxidation and many amino acid catabolic pathways generate acetyl-CoA, which serves as the common entry point into the citric acid cycle. Pyruvate is central to carbohydrate metabolism, but acetyl‑CoA is the shared two-carbon metabolic ‘hub’ for fats and many amino acids.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 9, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2024 Q#9 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "official_paper_q10_10", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 10, "subject": "Biology", "topic": "viral genome types", "question": "Which of the following virus has a double stranded DNA genome?", "options": ["Rubella", "Influenza", "HIV", "Small pox"], "correctIndex": 3, "explanation": "Smallpox (a poxvirus) is a large DNA virus with a double-stranded DNA genome. Rubella and influenza are RNA viruses, and HIV is an RNA retrovirus, so smallpox is the only dsDNA virus among the choices.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 10, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2024 Q#10 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "official_paper_q11_11", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 11, "subject": "Biology", "topic": "enzyme specificity versus regulation", "question": "An enzyme is capable of acting on a wide range of related substrates. Which of the following is a property of this enzyme?", "options": ["Inflexible active site", "Regulatory enzyme", "Non-regulatory enzyme", "Highly specific enzyme"], "correctIndex": 2, "explanation": "An enzyme that acts on a broad range of related substrates is considered non-specific and typically not a tightly regulated (allosteric) control enzyme. Regulatory enzymes are generally highly specific and subject to feedback control, so 'non-regulatory enzyme' correctly describes broad-substrate activity.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 11, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2024 Q#11 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "official_paper_q12_12", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 12, "subject": "Biology", "topic": "bacterial capsule advantages", "question": "All are the characteristics responsible for better survival of encapsulated bacteria except:", "options": ["High pathogenicity", "Withstand dehydration", "Strict adhesion to internal surfaces", "Easy recognition by host"], "correctIndex": 3, "explanation": "A bacterial capsule increases pathogenicity, helps resist dehydration and aids adhesion to surfaces, but it masks surface antigens and therefore makes recognition by the host immune system more difficult, not easier. Thus 'easy recognition by host' is not a characteristic of encapsulated bacteria.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 12, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "NUMS 2024 Q#12 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2024"}, {"id": "official_paper_q13_13", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 13, "subject": "Biology", "topic": "probiotics mechanisms of benefit", "question": "Probiotics in infants formula milk keep babies healthy by doing all of the following actions except:", "options": ["Produce important vitamins", "Kill pathogenic bacteria", "Prevent colonization of pathogens", "Enhance immunity"], "correctIndex": 1, "explanation": "Probiotics benefit infants by synthesizing certain vitamins, competing with pathogens to prevent colonization, and stimulating host immune responses. They do not generally 'kill' pathogens directly as a primary mechanism (although some strains can produce antimicrobial peptides), so option B is the correct exception.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 13, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2024 Q#13 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "official_paper_q14_14", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 14, "subject": "Biology", "topic": "zymogen activation", "question": "Activation of all of the following enzymes need a regulatory molecule except:", "options": ["Pepsinogen", "Trypsinogen", "Erepsin", "Chymotrypsinogen"], "correctIndex": 2, "explanation": "Pepsinogen, trypsinogen and chymotrypsinogen are proenzymes requiring proteolytic activation to become active digestive proteases. Erepsin (a mixture of active proteases in the intestine) is already active and therefore does not require a regulatory activation step like the zymogens do.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 14, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2024 Q#14 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "official_paper_q15_15", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 15, "subject": "Biology", "topic": "papillary muscle function", "question": "Weakened papillary muscles of right ventricle would result in constant back flow of blood into:", "options": ["Right atrium", "Left ventricle", "Right ventricle", "Left atrium"], "correctIndex": 0, "explanation": "Papillary muscles anchor the chordae tendineae and prevent prolapse of the tricuspid valve during right ventricular systole; weakened papillary muscles cause tricuspid regurgitation and backflow into the right atrium. The other chambers listed would not receive regurgitant flow from the right ventricle directly.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 15, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2024 Q#15 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2024"}, {"id": "official_paper_q16_16", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 16, "subject": "Biology", "topic": "gallbladder role in bile secretion", "question": "A person with a removed gall bladder experiences difficulty in fat digestion due to:", "options": ["Absence of Bile", "Uncontrolled release of Bile", "Reduced alkalinity of bile", "Absence of bile pigments"], "correctIndex": 1, "explanation": "The gallbladder stores and releases concentrated bile in a regulated fashion during meals. After cholecystectomy bile drains continuously into the intestine in an uncontrolled, low‑concentration manner, reducing the efficient, meal‑timed emulsification of dietary fat and causing digestion difficulties.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 16, "syllabusUnit": "Unit 5: Human Physiology - Digestion & Nutrition", "pmdcTopic": "Human Digestive System & Absorption Mechanisms", "textbookCitation": "PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12", "citationString": "NUMS 2024 Q#16 | Unit 5: Human Physiology - Digestion & Nutrition | PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12"}, "year": "2024"}, {"id": "official_paper_q17_17", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 17, "subject": "Biology", "topic": "waxy cuticle function", "question": "Waxy cuticle protects the plant cell from:", "options": ["Desiccation", "Photorespiration", "Toxin metabolism", "Protein loss"], "correctIndex": 0, "explanation": "The waxy cuticle covering aerial plant surfaces is a hydrophobic layer that reduces water loss by evaporation and thereby protects tissues from desiccation. It does not primarily prevent photorespiration, toxin metabolism or protein loss.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 17, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2024 Q#17 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "official_paper_q18_18", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 18, "subject": "Biology", "topic": "venous structural features", "question": "Which of the following set of characteristics are related to veins?", "options": ["Valves: Present, Wall thickness: Thick, Diameter: 7-9mm", "Valves: Absent, Wall thickness: Thick, Diameter: 40-50mm", "Valves: Present, Wall thickness: Thinner, Diameter: 40-50mm", "Valves: Absent, Wall thickness: Thinner, Diameter: 40-50mm"], "correctIndex": 2, "explanation": "Veins characteristically have valves to prevent backflow, thinner walls than arteries, and a relatively large lumen (large diameter), so the set 'valves present, wall thickness thinner, diameter 40–50 mm' fits venous structure. Thick walls and absence of valves describe arteries or capillaries incorrectly for veins.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 18, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2024 Q#18 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "official_paper_q19_19", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 19, "subject": "Biology", "topic": "lymphatic system functions", "question": "Which of the following would not be compromised in the absence of lymphatic system?", "options": ["Blood pressure", "Oxygen carrying capacity of blood", "Blood composition", "Defense mechanism"], "correctIndex": 1, "explanation": "The lymphatic system returns interstitial fluid to the bloodstream, maintains blood composition and provides immune defense; however, it does not influence the oxygen‑carrying capacity of blood, which depends on red blood cell number and hemoglobin content. Therefore oxygen‑carrying capacity would remain unchanged by loss of lymphatics.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 19, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2024 Q#19 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2024"}, {"id": "official_paper_q20_20", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 20, "subject": "Biology", "topic": "blood versus interstitial fluid components", "question": "The presence of which molecules distinguishes blood from interstitial fluid?", "options": ["Large proteins and electrolytes", "Glucose and RBCs", "Antibodies and electrolytes", "RBCs and large proteins"], "correctIndex": 3, "explanation": "Blood is distinguished from interstitial fluid by containing erythrocytes and large plasma proteins (e.g., albumin) that are largely retained within the vasculature. Interstitial fluid lacks red blood cells and has much lower concentrations of large plasma proteins, so 'RBCs and large proteins' is the distinguishing pair.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 20, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2024 Q#20 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2024"}, {"id": "official_paper_q21_21", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 21, "subject": "Biology", "topic": "water potential in saline soils", "question": "Plants growing in saline soil face the problem of dehydration due to:", "options": ["Yw of soil > Yw of root", "Ys of soil < Ys of root", "Yw of root > Yw of soil", "Yw of root = Yw of soil"], "correctIndex": 2, "explanation": "In saline soils the soil water potential becomes lower (more negative) than the plant root water potential; if the root's water potential (Yw) is higher than the soil's, water will move out of the root causing dehydration. Thus the condition 'Yw of root > Yw of soil' explains dehydration in saline conditions.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 21, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2024 Q#21 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "official_paper_q22_22", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 22, "subject": "Biology", "topic": "convalescent plasma antibodies", "question": "During Covid-19 epidemic, plasma of recovered patients was injected in covid patients. Which component of plasma was responsible for this?", "options": ["Plasminogen", "Interferons", "Antibodies", "Interleukin-I"], "correctIndex": 2, "explanation": "Convalescent plasma therapy transfers circulating antibodies (immunoglobulins) from recovered patients to infected individuals, providing passive immunity and neutralizing the pathogen. Other plasma components listed (plasminogen, interferons, interleukin‑1) are not the primary neutralizing agents in convalescent plasma therapy.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 22, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2024 Q#22 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2024"}, {"id": "official_paper_q23_23", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 23, "subject": "Biology", "topic": "artificial active immunity", "question": "Choose the one which is an example of artificial active immunity:", "options": ["Fetus receiving antibodies of mother through placenta", "Mother receiving antibodies", "Baby receiving MMR shots", "Prevention of disease due to previous infection"], "correctIndex": 2, "explanation": "Vaccination (MMR shots) exposes the baby to antigen in a controlled way so the immune system makes its own antibodies and memory cells - this is artificial (man-made) and active (host produces response) immunity. Passive examples (mother's antibodies) are not active because the recipient does not produce the antibodies.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 23, "syllabusUnit": "Unit 7: Human Physiology - Immunity", "pmdcTopic": "Innate & Adaptive Immunity, Immunoglobulins and Vaccines", "textbookCitation": "PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14", "citationString": "NUMS 2024 Q#23 | Unit 7: Human Physiology - Immunity | PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14"}, "year": "2024"}, {"id": "official_paper_q24_24", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 24, "subject": "Biology", "topic": "helper t cells b cell activation", "question": "Which of the following type of T cells are required for the activation of B cells?", "options": ["Helper T cells", "Cytotoxic T cells", "Suppressor T cells", "Memory T cells"], "correctIndex": 0, "explanation": "Helper T (Th) cells provide the necessary signals (cytokines and co-stimulation) that activate B cells to proliferate and differentiate into plasma and memory cells. Cytotoxic, suppressor and memory T cells do not provide the primary activation signals for naive B cells.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 24, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2024 Q#24 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "official_paper_q25_25", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 25, "subject": "Biology", "topic": "neurotransmitter inactivation", "question": "What is the fate of a neurotransmitter after the transmission of nerve impulse across synapse?", "options": ["It is taken into post synaptic neuron", "Released to post synaptic membrane", "Released into the synaptic cleft", "Broken down by enzymes"], "correctIndex": 3, "explanation": "After a neurotransmitter has transmitted the signal across the synapse it is removed from the synaptic cleft, often by enzymatic breakdown (for example acetylcholinesterase breaking down acetylcholine) so the signal is terminated. Other fates (reuptake into the presynaptic terminal or diffusion) occur for some transmitters, but enzymatic breakdown is the answer given here.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 25, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2024 Q#25 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2024"}, {"id": "official_paper_q26_26", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 26, "subject": "Biology", "topic": "excitatory postsynaptic potential", "question": "Which immediate change is brought about in the post synaptic membrane on binding with excitatory neurotransmitter?", "options": ["Calcium gates open", "Sodium gates open", "Sodium gates close", "Sodium potassium pump ceases to work"], "correctIndex": 1, "explanation": "Binding of an excitatory neurotransmitter opens ligand-gated sodium channels in the postsynaptic membrane, allowing Na+ influx and depolarization that can initiate an action potential. Calcium gates or pump cessation are not the immediate events producing excitatory postsynaptic potentials.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 26, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2024 Q#26 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "official_paper_q27_27", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 27, "subject": "Biology", "topic": "hyperpolarization mechanism", "question": "During the conduction of nerve impulse, hyperpolarization would not occur if:", "options": ["Sodium gates didn't close in time", "Potassium gates were not so lousy", "Sodium potassium pump stopped working", "Calcium gates open instantly"], "correctIndex": 1, "explanation": "Hyperpolarization of the membrane is caused by increased K+ permeability and efflux of potassium after an action potential; if potassium gates were not functioning (\"not so lousy\" meaning not opening) there would be less K+ efflux and hyperpolarization would be reduced or absent. Problems with Na+ gate timing or the pump affect other phases of the action potential but do not prevent the K+-dependent overshoot in the same way.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 27, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2024 Q#27 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2024"}, {"id": "official_paper_q28_28", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 28, "subject": "Biology", "topic": "electrical synapse properties", "question": "Which of the following is a characteristic of electrical synapse?", "options": ["Presence of neurotransmitters", "Transmission of nerve impulse", "Sodium potassium gradient", "Absence of neurotransmitter"], "correctIndex": 3, "explanation": "Electrical synapses pass current directly through gap junctions and do not rely on chemical neurotransmitters in the synaptic cleft, so they lack a neurotransmitter-mediated step. They are therefore faster but less modulatable than chemical synapses.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 28, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2024 Q#28 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2024"}, {"id": "official_paper_q29_29", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 29, "subject": "Biology", "topic": "refractory period", "question": "Which option given below characterizes refractory period?", "options": ["Reversal of charges across neural membrane", "Change in the type of ions across the membrane", "Next impulse can be conducted", "Membrane potential +50mV"], "correctIndex": 0, "explanation": "The refractory period follows the action potential and is associated with the membrane having undergone a reversal of charges (inside transiently positive) and with inactivated sodium channels, preventing immediate re‑excitation. It therefore reflects the recent reversal of membrane polarity and the subsequent time needed to return to a state able to fire again.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 29, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2024 Q#29 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "official_paper_q30_30", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 30, "subject": "Biology", "topic": "cerebellum motor coordination", "question": "During complex activity of flight, birds require coordination of many skeletal muscles. Which part of their brain has to be well developed?", "options": ["Amygdala", "Cerebrum", "Cerebellum", "Thalamus"], "correctIndex": 2, "explanation": "The cerebellum integrates sensory input and coordinates timing and precision of complex, finely tuned skeletal muscle movements such as those required for flight. Other brain regions have different roles (cerebrum for cognition, amygdala for emotion).", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 30, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2024 Q#30 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2024"}, {"id": "official_paper_q31_31", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 31, "subject": "Biology", "topic": "cerebrum higher cognitive functions", "question": "Which part of the brain is actively used by mathematician trying to formulate a new equation?", "options": ["Hippocampus", "Cerebrum", "Amygdala", "Pons"], "correctIndex": 1, "explanation": "The cerebrum (especially the cerebral cortex) mediates higher intellectual functions such as abstract reasoning, problem solving and formulating new equations, so it is the brain region most active in mathematical thinking. Hippocampus is more for memory consolidation, amygdala for emotion.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 31, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2024 Q#31 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2024"}, {"id": "official_paper_q32_32", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 32, "subject": "Biology", "topic": "adh release osmoregulation", "question": "A desert mammal faces severe dehydration in a hot sunny day. Which internal condition would lead to secretion of ADH?", "options": ["High osmotic pressure of blood", "High blood pressure", "Low osmotic pressure of blood", "Low solute potential of blood"], "correctIndex": 0, "explanation": "ADH secretion is stimulated by increased plasma osmolarity (high osmotic pressure) so when a desert mammal becomes dehydrated and blood osmolarity rises, ADH is released to conserve water via increased renal water reabsorption. High blood pressure or low osmotic pressure would suppress ADH release.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 32, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2024 Q#32 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "official_paper_q33_33", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 33, "subject": "Biology", "topic": "adult hypothyroidism myxedema", "question": "Which would be diagnosed by a doctor on seeing a patient with thick skin and low metabolic rate?", "options": ["Cretinism", "Cushing disease", "Myxedema", "Addison's disease"], "correctIndex": 2, "explanation": "Thickened skin and a low metabolic rate are classical features of myxedema, the adult form of hypothyroidism caused by deficient thyroid hormone. Cretinism is congenital hypothyroidism in children; Cushing’s and Addison’s have different systemic signs.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 33, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2024 Q#33 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2024"}, {"id": "official_paper_q34_34", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 34, "subject": "Biology", "topic": "hypoparathyroidism tetany", "question": "Choose the one related to hypoparathyroidism:", "options": ["Kidney stones", "Hypercalcemia", "Weakness of muscles", "Tetany"], "correctIndex": 3, "explanation": "Hypoparathyroidism causes low parathyroid hormone, leading to hypocalcemia; low blood calcium increases neuromuscular excitability and produces tetany (muscle spasms). Kidney stones and hypercalcemia are features of hyperparathyroidism, not hypo-.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 34, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2024 Q#34 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2024"}, {"id": "official_paper_q35_35", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 35, "subject": "Biology", "topic": "ovarian hormone sources", "question": "Choose the mismatched pair:", "options": ["Graffian follicle - progesterone", "ICSH - interstitial cell", "Estrogen - inhibits FSH", "LH - ovulation"], "correctIndex": 0, "explanation": "A mature Graafian (Graffian) follicle mainly produces estrogen; after ovulation the corpus luteum produces progesterone. Therefore pairing Graafian follicle with progesterone is incorrect, making that the mismatched option.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 35, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2024 Q#35 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2024"}, {"id": "official_paper_q36_36", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 36, "subject": "Biology", "topic": "negative feedback examples", "question": "Which of the following is an example of negative feedback mechanism?", "options": ["Aggregation of platelets during wound healing", "Labour contraction", "Milk secretion during suckling", "Control of body temperature"], "correctIndex": 3, "explanation": "Control of body temperature is regulated by negative feedback: deviations from the set point trigger responses (vasodilation, sweating, shivering) that oppose the change and restore normal temperature. Labour and milk let-down are positive feedback examples and platelet aggregation is a localized amplification process.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 36, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2024 Q#36 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "official_paper_q37_37", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 37, "subject": "Biology", "topic": "co2 transport bicarbonate mechanism", "question": "Most CO2 in blood is transported as bicarbonate ions. Choose the event NOT taking place during gaseous exchange at tissue level:", "options": ["Formation of HHb", "Formation of sodium bicarbonate", "Formation of oxyhemoglobin", "Chloride shift"], "correctIndex": 2, "explanation": "At the tissue level CO2 is converted to bicarbonate and chloride shift occurs; formation of oxyhemoglobin does not occur there because tissues favour offloading oxygen (rather than forming oxyhemoglobin). Formation of HHb (reduced hemoglobin) and bicarbonate/Cl− shift are normal tissue‑level events.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 37, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2024 Q#37 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2024"}, {"id": "official_paper_q38_38", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 38, "subject": "Biology", "topic": "interneuron function", "question": "All are related to 'X' except: (X is interneuron shown in diagram)", "options": ["It passes information to brain", "It passes information to sensory neurons", "It synapses with axon of sensory neurons", "It is present in gray matter"], "correctIndex": 1, "explanation": "Interneurons (connector neurons) relay information between sensory and motor pathways or to the brain; they do not pass information back to sensory neurons. They typically synapse with sensory axons and are located in gray matter, so the statement that they pass information to sensory neurons is incorrect.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 38, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "NUMS 2024 Q#38 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2024"}, {"id": "official_paper_q39_39", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 39, "subject": "Biology", "topic": "membrane protein functions", "question": "Which one is the function of plasma membrane proteins?", "options": ["Restrict entry of polar molecules", "Prevention of freezing during cold weather", "Movement of ions in and out of the cell", "Maintenance of membrane flexibility"], "correctIndex": 2, "explanation": "Integral membrane proteins include ion channels and transporters that mediate the regulated movement of ions and polar molecules across the plasma membrane. Other membrane components (lipids) restrict polar molecule entry and maintain flexibility, but the specific movement of ions is a protein function.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 39, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2024 Q#39 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "official_paper_q40_40", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 40, "subject": "Biology", "topic": "intermediate filaments properties", "question": "Choose the option showing the correct set of characteristics for Intermediate filaments:", "options": ["Diameter 8-10nm, Vimentin, Mechanical support", "Diameter 0.2-25um, Vimentin, Cilia flagella", "Diameter 8-10nm, Tubulin, Muscle contraction", "Diameter 7nm, Tubulin, Cyclosis"], "correctIndex": 0, "explanation": "Intermediate filaments are about 8–10 nm in diameter, include proteins such as vimentin (in mesenchymal cells), and provide mechanical strength and support to cells. The other options list sizes or proteins that correspond to microtubules or actin structures, so they are incorrect.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 40, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2024 Q#40 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "official_paper_q41_41", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 41, "subject": "Biology", "topic": "nucleoproteins genetic information", "question": "Nucleo proteins are involved in:", "options": ["Cell to cell recognition", "Passing hereditary information to next generation", "Ensuring fast speed of nerve impulse", "Acting as a cell surface marker"], "correctIndex": 1, "explanation": "Nucleoproteins (DNA complexed with protein in chromosomes) are the carriers of hereditary information and are responsible for passing genetic information to the next generation. They are not primarily cell-surface markers or involved in nerve impulse speed.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 41, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2024 Q#41 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "official_paper_q42_42", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 42, "subject": "Biology", "topic": "ovulation timing 28 day cycle", "question": "If reproductive cycle of a female starts on 10th of July, ovulation is most likely to occur on:", "options": ["1st August", "28th of July", "24th of July", "5th August"], "correctIndex": 2, "explanation": "Assuming a 28‑day cycle with menstruation starting on July 10 (day 1), ovulation typically occurs around day 14, which is July 24. Counting 14 days from the first day of the cycle gives the expected ovulation date.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 42, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "NUMS 2024 Q#42 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2024"}, {"id": "official_paper_q43_43", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 43, "subject": "Biology", "topic": "meiosis and gametogenesis", "question": "Which of the following would be produced as a result of reduction division during gametogenesis?", "options": ["Oogonium", "Primary oocyte", "Primary spermatocyte", "Secondary oocyte"], "correctIndex": 3, "explanation": "Reduction division (meiosis I) produces haploid secondary gametes: in oogenesis the primary oocyte divides meiotically to give a secondary oocyte (and a polar body). Primary oocytes and oogonia are diploid precursor stages, while primary spermatocytes are pre-reduction stages in spermatogenesis.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 43, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2024 Q#43 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "official_paper_q44_44", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 44, "subject": "Biology", "topic": "dihybrid cross probability", "question": "What will be the probability of purple and terminal flower in Pea plant in F2 generation, if we cross true breeding purple axial with white terminal?", "options": ["1/16", "3/16", "9/16", "1/2"], "correctIndex": 1, "explanation": "From a cross PP AA × pp aa the F1 are all Pp Aa; in F2, purple (dominant P) occurs with probability 3/4 and terminal position (aa) with probability 1/4. Multiplying independent probabilities gives 3/4 × 1/4 = 3/16 for purple and terminal together.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 44, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "NUMS 2024 Q#44 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2024"}, {"id": "official_paper_q45_45", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 45, "subject": "Biology", "topic": "x linked recessive hemophilia", "question": "A carrier female for hemophilia is married to an affected male. What would be the probable percentage for their sons to be affected?", "options": ["100%", "50%", "25%", "0%"], "correctIndex": 1, "explanation": "A carrier female (X^H X^h) mated with an affected male (X^h Y) will produce sons that inherit their X from the mother and Y from the father; half of the mother’s X chromosomes carry the hemophilia allele, so 50% of sons will be affected. Daughters have different probabilities due to receiving the father’s affected X.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 45, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2024 Q#45 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "official_paper_q46_46", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 46, "subject": "Biology", "topic": "abo blood group genetics", "question": "Which of the following is not related to ABO blood group system?", "options": ["It is an example of multiple alleles", "I^A and I^B are codominant", "I doesn't code for any antigen", "I^O obeys Mendel's laws of inheritance"], "correctIndex": 3, "explanation": "ABO is a classic multiple-allele system with IA and IB codominant and i (IO) producing no antigen. The statement chosen as not related is that IO obeys simple Mendelian inheritance; because the system involves multiple alleles and codominance it does not follow a single simple dominant–recessive Mendelian pattern in all respects, which is why that option is marked as the exception.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 46, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2024 Q#46 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2024"}, {"id": "official_paper_q47_47", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 47, "subject": "Biology", "topic": "androgenic alopecia", "question": "Which is correct for pattern baldness?", "options": ["It is sex linked trait", "Occurs due to hormonal differences between sexes", "Heterozygous male is normal", "Heterozygous female is affected"], "correctIndex": 1, "explanation": "Pattern (androgenic) baldness is driven by hormonal differences - sensitivity to androgens causes miniaturization of hair follicles in genetically susceptible individuals. It is not a simple sex‑linked trait, and the other options describe genotype effects rather than the hormonal basis.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 47, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2024 Q#47 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "official_paper_q48_48", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 48, "subject": "Biology", "topic": "hamstring anatomy", "question": "Which of the following is correct about hamstring muscles?", "options": ["It is an extensor muscle", "Its insertion is on tibia", "Originate from pelvic girdle and top of femur", "Originate from ilium and femur"], "correctIndex": 1, "explanation": "Hamstring muscles (semimembranosus, semitendinosus, biceps femoris) originate on the ischial tuberosity of the pelvis and insert mainly on the tibia (and head of fibula for biceps femoris). That makes option B the correct statement about their insertion.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 48, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "NUMS 2024 Q#48 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2024"}, {"id": "official_paper_q49_49", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 49, "subject": "Biology", "topic": "sarcomere structure in relaxation", "question": "Choose the correct for muscle in relaxed position:", "options": ["Exposed binding sites on actin", "Broad H-zone in sarcomere", "Formation of cross bridges", "Ca2+ released in cytosol"], "correctIndex": 1, "explanation": "In a relaxed skeletal muscle the A bands remain but the overlap between actin and myosin is reduced, so the H‑zone (region of only myosin) is relatively broad. Exposed actin binding sites, Ca2+ release and cross‑bridge formation occur during activation/contraction, not relaxation.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 49, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "NUMS 2024 Q#49 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2024"}, {"id": "official_paper_q50_50", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 50, "subject": "Biology", "topic": "inheritance of acquired traits", "question": "Children of a mason do not inherit strong muscles developed by father due to hard labour. This is an example of:", "options": ["Survival of the fittest", "Over production of offspring", "Not inheriting acquired characters", "Use and disuse of organs"], "correctIndex": 2, "explanation": "The mason’s children not inheriting the father’s developed muscles illustrates that acquired characteristics from use and environment are not inherited - a repudiation of Lamarckian inheritance. This is a classic example that acquired traits are not passed genetically to offspring.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 50, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "NUMS 2024 Q#50 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2024"}, {"id": "official_paper_q51_51", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 51, "subject": "Chemistry", "topic": "stoichiometry limiting reactant", "question": "Ca + S → CaS. If 2.0g of Calcium and 4.0g of Sulphur are available, amount of product formed:", "options": ["4.6g", "1.6g", "2.6g", "3.6g"], "correctIndex": 3, "explanation": "Moles: Ca = 2.0/40 ≈ 0.05 mol, S = 4.0/32 ≈ 0.125 mol; Ca is limiting so 0.05 mol CaS forms. Mass = 0.05×(40+32)=0.05×72 = 3.6 g, so option D is correct.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 51, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "NUMS 2024 Q#51 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2024"}, {"id": "official_paper_q52_52", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 52, "subject": "Chemistry", "topic": "mole calculations", "question": "Select the greatest number of particles in the following:", "options": ["2g of Sodium (atomic mass = 23)", "2g of Hydrogen gas (atomic mass of H = 1)", "2g of Nitrogen gas (atomic mass of N = 14)", "2g of Carbon dioxide gas (C=12, O=16)"], "correctIndex": 1, "explanation": "Number of particles ∝ moles = mass / molar mass. 2 g of H2 (molar mass 2) is 1.0 mol, which is far more particles than the other 2 g samples, so hydrogen gas gives the greatest number of particles.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 52, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2024 Q#52 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "official_paper_q53_53", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 53, "subject": "Chemistry", "topic": "azimuthal quantum number p orbital", "question": "The value of 'l' for 4p orbital is:", "options": ["0", "1", "2", "3"], "correctIndex": 1, "explanation": "For a p orbital the azimuthal quantum number l = 1 regardless of principal quantum number, so for any 4p orbital l = 1. The other l values correspond to s (0), d (2) or f (3) orbitals.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 53, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2024 Q#53 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2024"}, {"id": "official_paper_q54_54", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 54, "subject": "Chemistry", "topic": "electronic configuration counting", "question": "The element having the electronic configuration (Kr) 5s24d8 is:", "options": ["Sr", "Ru", "Pd", "Zr"], "correctIndex": 2, "explanation": "Start from krypton (Z=36), add 5s2 (2 electrons) and 4d8 (8 electrons) giving total Z = 36+2+8 = 46, which is palladium (Pd). So the configuration corresponds to Pd.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 54, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2024 Q#54 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2024"}, {"id": "official_paper_q55_55", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 55, "subject": "Chemistry", "topic": "valid quantum numbers", "question": "Choose the correct quantum numbers:", "options": ["n=3, l=2, m=0, s=+1/2", "n=-3, l=3, m=0, s=-1/2", "n=4, l=3, m=4, s=+1/2", "n=4, l=2, m=4, s=-1/2"], "correctIndex": 0, "explanation": "Quantum numbers must satisfy n>0, 0≤l≤n−1, −l≤m≤+l and s = ±1/2. Option A (n=3,l=2,m=0,s=+1/2) meets all these constraints; the other choices violate one or more rules.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 55, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2024 Q#55 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2024"}, {"id": "official_paper_q56_56", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 56, "subject": "Chemistry", "topic": "charles law temperature volume", "question": "A gas has volume 10dm3 at 10°C. At what temperature is volume reduced to half?", "options": ["283K", "566K", "142K", "373K"], "correctIndex": 2, "explanation": "At constant pressure V ∝ T (in K). Halving the volume halves the absolute temperature: T2 = 0.5×(10°C + 273) = 0.5×283 K ≈ 141.5 K, so 142 K is the closest option.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 56, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2024 Q#56 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "official_paper_q57_57", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 57, "subject": "Chemistry", "topic": "root mean square speed", "question": "The relationship between absolute temperature and velocities of gas molecules is given by:", "options": ["Crms = sqrt(3RT/M)", "PV = nRT", "V = sqrt(2Ek/m)", "PV = 1/3mNc2"], "correctIndex": 0, "explanation": "The root‑mean‑square speed of gas molecules is v_rms = sqrt(3RT/M), which directly relates molecular speeds to absolute temperature (R is the gas constant and M the molar mass). That is the relation given in option A.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 57, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2024 Q#57 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "official_paper_q58_58", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 58, "subject": "Chemistry", "topic": "molecular polarizability size effect", "question": "The maximum polarizability is exhibited in:", "options": ["C6H14", "C3H6", "C5H12", "C2H6"], "correctIndex": 0, "explanation": "Polarizability increases with the number of electrons and molecular size; among the choices the largest molecule (C6H14) has the most easily distorted electron cloud and thus the greatest polarizability.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 58, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2024 Q#58 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "official_paper_q59_59", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 59, "subject": "Chemistry", "topic": "melting behavior of silicates", "question": "Which of the following compound have any characteristic heat of fusion except?", "options": ["NaCl", "Aluminium oxide", "Iron oxide", "Silicates"], "correctIndex": 3, "explanation": "Many silicates form glasses or network structures that do not show a sharp, characteristic heat of fusion (they soften over a range) unlike ionic crystals such as NaCl, Al2O3 or iron oxides which have defined enthalpies of fusion. Therefore silicates are the exception.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 59, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2024 Q#59 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "official_paper_q60_60", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 60, "subject": "Chemistry", "topic": "boiling point pressure dependence", "question": "If external pressure is reduced to half, boiling point of ethanol will be:", "options": ["Greater than 78°C", "Less than 78°C", "Equal to 78°C", "Reduced to half"], "correctIndex": 1, "explanation": "Boiling point decreases when external pressure is reduced because vapor pressure reaches ambient pressure at a lower temperature. So if pressure is halved, ethanol’s boiling point will be less than its normal 78°C.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 60, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2024 Q#60 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "official_paper_q61_61", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 61, "subject": "Chemistry", "topic": "molecular solid iodine structure", "question": "Iodine is a poor conductor of electricity because of:", "options": ["Face centered cubic structure", "Body centered cubic structure", "Tetragonal structure", "Hexagonal structure"], "correctIndex": 2, "explanation": "Solid iodine is a molecular solid with discrete I2 molecules arranged in a tetragonal lattice; it lacks delocalized electrons and so is a poor electrical conductor. The crystal form (tetragonal) and molecular bonding explain its insulating behavior.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 61, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2024 Q#61 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "official_paper_q62_62", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 62, "subject": "Chemistry", "topic": "cscl structure radius ratio", "question": "Predict the shape of CsCl having radius ratio of 0.93:", "options": ["Tetrahedral", "Octahedral", "Body centered cubic", "Hexagonal"], "correctIndex": 2, "explanation": "A radius ratio of ~0.93 corresponds to coordination number 8, which is the CsCl type: a cubic unit cell with one ion at the center and the other at the corners (often described as body‑centered cubic). Hence option C is correct.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 62, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2024 Q#62 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "official_paper_q63_63", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 63, "subject": "Chemistry", "topic": "ksp and solubility", "question": "The solubility of PbS at 25°C is 4.0 × 10−28. Then ionic concentration will be:", "options": ["4x10−14", "2x10−14", "1x10−14", "3.0x10−10"], "correctIndex": 1, "explanation": "For PbS ⇌ Pb2+ + S2−, if Ksp = 4.0×10^−28 and [Pb2+] = [S2−] = s, then s^2 = 4.0×10^−28 so s = 2.0×10^−14 M. Thus the ionic concentrations are 2×10^−14 M.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 63, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "NUMS 2024 Q#63 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2024"}, {"id": "official_paper_q64_64", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 64, "subject": "Chemistry", "topic": "haber process conditions", "question": "What conditions should be applied to minimize the leftover reactants in Ammonia synthesis?", "options": ["200atm, 500°C", "400atm, 200°C", "100atm, 400°C", "200atm, 400°C"], "correctIndex": 3, "explanation": "Ammonia formation is favored by high pressure and relatively low temperature (Le Chatelier), but kinetics require a moderate temperature; the industrial compromise is about 200 atm and ~400°C, which minimizes unreacted starting gases while keeping an acceptable rate.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 64, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2024 Q#64 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "official_paper_q65_65", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 65, "subject": "Chemistry", "topic": "buffer ph henderson hasselbalch", "question": "Select the buffer solution having highest pH:", "options": ["0.1M CH3COOH, 0.01M CH3COO-", "0.1M CH3COOH, 0.05M CH3COO-", "0.1M CH3COOH, 0.10M CH3COO-", "0.1M CH3COOH, 0.15M CH3COO-"], "correctIndex": 3, "explanation": "pH = pKa + log([A−]/[HA]), so the buffer with the largest acetate:acetic‑acid ratio gives the highest pH. The 0.15/0.10 ratio (1.5) in option D is the largest, so it has the highest pH.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 65, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "NUMS 2024 Q#65 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2024"}, {"id": "official_paper_q66_66", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 66, "subject": "Chemistry", "topic": "surface area effect on rate", "question": "Formation of hydrogen gas can be increased by reacting which Zn sample with 1M HCl?", "options": ["1g Zn Rod", "1g Zn Pellets", "1g Zn Ribbon", "1g Zn Powder"], "correctIndex": 3, "explanation": "Reaction rate increases with available surface area for heterogeneous reactions; powdered zinc provides the largest surface area per gram, therefore 1 g of Zn powder will produce hydrogen fastest with 1 M HCl.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 66, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2024 Q#66 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "official_paper_q67_67", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 67, "subject": "Chemistry", "topic": "photochemical zero order reactions", "question": "6CO2 + 6H2O → sunlight → C6H12O6 + 6O2. Predict the order of reaction:", "options": ["2nd", "1st", "Zero", "3rd"], "correctIndex": 2, "explanation": "Photosynthesis driven by light can behave as a zero‑order process with respect to reactant concentrations when the rate is limited by photon flux rather than substrate concentration, so the reaction is treated as zero order under those conditions.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 67, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "NUMS 2024 Q#67 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2024"}, {"id": "official_paper_q68_68", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 68, "subject": "Chemistry", "topic": "mechanism consistent with rate law", "question": "Which mechanism is consistent with rate law Rate = K[NO]2[H2]?", "options": ["2NO + H2 → N2 + H2O2 (slow), H2O2 + H2 → 2H2O (fast)", "NO + H2O → N2 + H2O2 (slow), H2O2 + H2 → 2H2O (fast)", "2NO + 2H2 → N2O + H2 (slow), H2O + H2 → H2O2 (fast)", "NO + NO → N2 + O2 (slow), O2 + H2 → H2O (fast)"], "correctIndex": 0, "explanation": "If the slow (rate‑determining) step is 2NO + H2 → N2 + H2O2, the rate law will be Rate ∝ [NO]^2[H2], matching the given rate expression; the other proposed steps either involve incorrect reactant stoichiometry or place the wrong elementary step as slow.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 68, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "NUMS 2024 Q#68 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2024"}, {"id": "official_paper_q69_69", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 69, "subject": "Chemistry", "topic": "hess law sublimation", "question": "DeltaH° for sublimation of one mole of iodine: H2(g) + I2(g) → 2HI(g) DH = 51.8kJ/mol H2(g) + I2(s) → 2HI(g) DH = -10.5kJ/mol", "options": ["41.3 kJ/mol", "62.3 kJ/mol", "53.5 kJ/mol", "36.5 kJ/mol"], "correctIndex": 1, "explanation": "Using Hess’s law: 51.8 kJ = (−10.5 kJ) + ΔH_sublimation, so ΔH_sublimation = 51.8 + 10.5 = 62.3 kJ mol^−1. Thus option B is correct.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 69, "syllabusUnit": "Unit 4: Chemical Energetics", "pmdcTopic": "Enthalpy Changes, Hess's Law & Standard Heats of Reaction", "textbookCitation": "PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6", "citationString": "NUMS 2024 Q#69 | Unit 4: Chemical Energetics | PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6"}, "year": "2024"}, {"id": "official_paper_q70_70", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 70, "subject": "Chemistry", "topic": "standard enthalpy of formation definition", "question": "Identify standard enthalpy of formation for the following reaction:", "options": ["H2(g) + 1/2 O2(g) → H2O(l)", "CO(g) + 1/2 O2(g) → CO2(g)", "2Al(s) + Fe2O3(s) → Al2O3(s) + 2Fe(s)", "S(s) + 3/2 O2(g) → SO3(g)"], "correctIndex": 0, "explanation": "Standard enthalpy of formation is the enthalpy change for making one mole of a compound from its elements in their standard states; H2(g) + 1/2 O2(g) → H2O(l) fits that definition for formation of one mole of water, so A is the standard formation reaction.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 70, "syllabusUnit": "Unit 4: Chemical Energetics", "pmdcTopic": "Enthalpy Changes, Hess's Law & Standard Heats of Reaction", "textbookCitation": "PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6", "citationString": "NUMS 2024 Q#70 | Unit 4: Chemical Energetics | PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6"}, "year": "2024"}, {"id": "official_paper_q71_71", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 71, "subject": "Chemistry", "topic": "sign conventions heat and work", "question": "Expansion takes place when gas evolves during reaction between carbohydrates and dilute HCl. Predict energy change and work done:", "options": ["w is positive, q is negative", "w is negative, q is positive", "q is positive, no work done", "w is positive, q is positive"], "correctIndex": 1, "explanation": "When a reaction evolves gas and the system expands, work is done by the system on the surroundings so w = −PΔV (negative). If the process absorbs heat (endothermic) then q is positive; the intended answer assigns negative w and positive q.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 71, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2024 Q#71 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "official_paper_q72_72", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 72, "subject": "Chemistry", "topic": "reduction potential and electrode behaviour", "question": "Zn rod acts as cathode when coupled with magnesium electrode because reduction potential of:", "options": ["Zn > Mg", "Zn < Mg", "Zn = Mg", "Zn = 0"], "correctIndex": 0, "explanation": "The electrode with the higher (more positive) reduction potential is reduced and thus acts as the cathode. Since Zn has a higher reduction potential than Mg, the Zn rod is reduced and functions as the cathode when coupled to magnesium.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 72, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "NUMS 2024 Q#72 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2024"}, {"id": "official_paper_q73_73", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 73, "subject": "Chemistry", "topic": "metal displacement reactions", "question": "Placing a rod of iron metal in a solution of CuSO4:", "options": ["Cu will be deposited", "Fe is precipitated out", "Cu and Fe both dissolve", "No reaction taken place"], "correctIndex": 0, "explanation": "Iron is more reducing (has a lower reduction potential) than copper, so Fe atoms oxidize to Fe2+ while Cu2+ is reduced and deposits as metallic copper on the iron rod. Therefore copper will be deposited from CuSO4 solution.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 73, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2024 Q#73 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "official_paper_q74_74", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 74, "subject": "Chemistry", "topic": "covalent radius calculation", "question": "In CH3Cl, bond length of C-Cl is 176.7pm and covalent radius of Cl is 99.4pm. Covalent radius of carbon is:", "options": ["66.3 pm", "276.1 pm", "175.4 pm", "77.3 pm"], "correctIndex": 3, "explanation": "The covalent bond length is approximately the sum of the two covalent radii. Subtracting the Cl radius from the C–Cl bond length gives 176.7 pm − 99.4 pm = 77.3 pm for the covalent radius of carbon.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 74, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "NUMS 2024 Q#74 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2024"}, {"id": "official_paper_q75_75", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 75, "subject": "Chemistry", "topic": "halogen electron affinity trend", "question": "Correct order of decreasing electron affinities of group VII is:", "options": ["F > Cl > Br > I", "Cl > F > Br > I", "F < Cl < Br < I", "Cl < F < Br < I"], "correctIndex": 1, "explanation": "Although fluorine is most electronegative, its electron affinity is lower than chlorine because of strong 2p electron–electron repulsion in the small F atom; chlorine accepts an electron more favourably. Thus the electron affinities decrease as Cl > F > Br > I.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 75, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "NUMS 2024 Q#75 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2024"}, {"id": "official_paper_q76_76", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 76, "subject": "Chemistry", "topic": "single bond dissociation energies", "question": "Predict the highest bond energy of the following single bond:", "options": ["C-H", "C-N", "C-O", "C-C"], "correctIndex": 0, "explanation": "Bond energy increases with bond strength and bond order; among the listed single bonds the C–H bond is the strongest (highest bond energy) compared with typical C–C, C–O and C–N single bonds. Therefore C–H has the highest bond energy here.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 76, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "NUMS 2024 Q#76 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2024"}, {"id": "official_paper_q77_77", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 77, "subject": "Chemistry", "topic": "acid carbonate reaction", "question": "Compound X + Na2CO3 → Compound Y + CO2 + H2O. The compound X is:", "options": ["CH2=CH-CH2-CH3", "CH3CH2CHO", "CH3C(O)OCH3", "CH3CH2COOH"], "correctIndex": 3, "explanation": "Reaction with carbonate producing CO2 and H2O is characteristic of carboxylic acids neutralising carbonates. CH3CH2COOH is the carboxylic acid among the options, so it is compound X.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 77, "syllabusUnit": "Unit 12: Carboxylic Acids & Derivatives", "pmdcTopic": "Acidity of Carboxylic Acids & Acyl Derivatives", "textbookCitation": "PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21", "citationString": "NUMS 2024 Q#77 | Unit 12: Carboxylic Acids & Derivatives | PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21"}, "year": "2024"}, {"id": "official_paper_q78_78", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 78, "subject": "Chemistry", "topic": "iodoform reaction and products", "question": "Compound A + I2 + Na2CO3 → Compound B + RCOONa + NaI + H2O. Identify compound B:", "options": ["Acetone", "Acetic acid", "Acetamide", "Acetic anhydride"], "correctIndex": 0, "explanation": "Substrates with a methyl ketone (or secondary alcohol that gives a methyl ketone on oxidation) undergo the haloform reaction to yield a carboxylate and a carbonyl fragment; acetone is the methyl ketone involved in typical iodoform-type transformations, so acetone is identified as the ketone product in this context.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 78, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2024 Q#78 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "official_paper_q79_79", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 79, "subject": "Chemistry", "topic": "melting points and chain length", "question": "Select the carboxylic acid with highest melting point:", "options": ["Ethanoic acid", "Propanoic acid", "Butanoic acid", "Pentanoic acid"], "correctIndex": 0, "explanation": "Short-chain carboxylic acids form strong hydrogen-bonded dimers and pack efficiently; among the choices acetic acid (ethanoic acid) has the highest melting point. Longer chains disrupt packing and lower the melting point.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 79, "syllabusUnit": "Unit 12: Carboxylic Acids & Derivatives", "pmdcTopic": "Acidity of Carboxylic Acids & Acyl Derivatives", "textbookCitation": "PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21", "citationString": "NUMS 2024 Q#79 | Unit 12: Carboxylic Acids & Derivatives | PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21"}, "year": "2024"}, {"id": "official_paper_q80_80", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 80, "subject": "Chemistry", "topic": "bond order effect on bond length", "question": "Identify the following compound having shortest bond length:", "options": ["Methyl amine", "Formamide", "Formic acid", "Ethanol"], "correctIndex": 2, "explanation": "Formic acid contains a carbonyl C=O double bond, which is significantly shorter than ordinary single bonds present in the other molecules. Therefore formic acid has the shortest bond length among the options due to that C=O bond.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 80, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "NUMS 2024 Q#80 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2024"}, {"id": "official_paper_q81_81", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 81, "subject": "Chemistry", "topic": "ozonolysis products of alkenes", "question": "Identify the alkene which gives only one type of aldehyde upon ozonolysis:", "options": ["1-pentene", "2-methyl propene", "2-butene", "2,3-dimethyl-2-butene"], "correctIndex": 2, "explanation": "Ozonolysis cleaves the C=C to give two carbonyl fragments; a symmetric internal alkene like 2-butene (CH3–CH=CH–CH3) yields two identical acetaldehyde molecules, i.e. only one type of aldehyde. Other alkenes give different carbonyl products.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 81, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "NUMS 2024 Q#81 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2024"}, {"id": "official_paper_q82_82", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 82, "subject": "Chemistry", "topic": "phenol formaldehyde resin formation", "question": "Bakelite is formed upon polymerization of:", "options": ["Phenol + HCHO dilute base", "Phenol + NaOH H2O", "Phenol + H2SO4 H2O", "Phenol + CH3-C(=O)-Cl H2SO4"], "correctIndex": 0, "explanation": "Bakelite is a phenol‑formaldehyde condensation polymer formed by reaction of phenol with formaldehyde under basic (or acidic) catalysis to give a cross‑linked thermoset resin. The option stating phenol + HCHO with dilute base is the correct preparation.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 82, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "NUMS 2024 Q#82 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2024"}, {"id": "official_paper_q83_83", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 83, "subject": "Chemistry", "topic": "steric effects on nucleophilic substitution", "question": "The increasing order of reactivity of alcohols towards nucleophile is:", "options": ["2-methyl-2-pentanol < 3-methyl-2-pentanol < 2-methyl-1-pentanol", "2-methyl-1-pentanol > 3-methyl-2-pentanol > 2-methyl-2-pentanol", "2-methyl-2-pentanol > 3-methyl-2-pentanol > 2-methyl-1-pentanol", "2-methyl-2-pentanol < 2-methyl-1-pentanol < 3-methyl-2-pentanol"], "correctIndex": 0, "explanation": "For nucleophilic (SN2) attack, steric hindrance reduces reactivity, so tertiary alcohols are least reactive and primary alcohols most reactive. Hence the increasing order tertiary < secondary < primary given in option A is correct for SN2-type nucleophilic attack.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 83, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "NUMS 2024 Q#83 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2024"}, {"id": "official_paper_q84_84", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 84, "subject": "Chemistry", "topic": "lucas test reactivity", "question": "The most reactive alcohol towards Lucas reagent is:", "options": ["2-butanol", "2-methyl-1-butanol", "2-methyl-2-butanol", "2,2-dimethyl-1-butanol"], "correctIndex": 2, "explanation": "Lucas reagent distinguishes alcohol classes by rate of substitution; tertiary alcohols react fastest to give immediate turbidity. 2‑Methyl‑2‑butanol is tertiary, so it is the most reactive toward Lucas reagent among the options.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 84, "syllabusUnit": "Unit 10: Alkyl Halides, Alcohols & Phenols", "pmdcTopic": "Nucleophilic Substitution, Elimination Reactions & Phenol Acidity", "textbookCitation": "PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19", "citationString": "NUMS 2024 Q#84 | Unit 10: Alkyl Halides, Alcohols & Phenols | PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19"}, "year": "2024"}, {"id": "official_paper_q85_85", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 85, "subject": "Chemistry", "topic": "electrophilic aromatic substitution activation", "question": "The most readily sulphonated compound is:", "options": ["Benzene", "Chlorobenzene", "Nitrobenzene", "Toluene"], "correctIndex": 3, "explanation": "Toluene has an electron‑donating methyl group that activates the benzene ring toward electrophilic substitution, making sulphonation easier and faster than on benzene, chlorobenzene or nitrobenzene (the latter is strongly deactivating). Therefore toluene is most readily sulphonated.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 85, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "NUMS 2024 Q#85 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2024"}, {"id": "official_paper_q86_86", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 86, "subject": "Chemistry", "topic": "cis trans isomerism in alkenes", "question": "Select the alkene showing geometrical isomerism:", "options": ["3-methyl-1-butene", "Methyl cyclopentane", "2,3-dimethyl-2-butene", "3-methyl-2-pentene"], "correctIndex": 3, "explanation": "Geometrical (cis/trans) isomerism requires each carbon of the double bond to have two different substituents. 3‑Methyl‑2‑pentene meets that requirement and can exist as E/Z isomers, whereas the other choices either have identical substituents on a double-bond carbon or are not alkenes.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 86, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "NUMS 2024 Q#86 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2024"}, {"id": "official_paper_q87_87", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 87, "subject": "Chemistry", "topic": "thermal stability of carbonates", "question": "When a metal carbonate is heated at 100°C, which will readily decompose?", "options": ["BaCO3", "MgCO3", "BeCO3", "SrCO3"], "correctIndex": 2, "explanation": "Beryllium carbonate is the most covalent and least thermally stable among the given alkaline earth carbonates, so it decomposes readily at relatively low temperatures like 100°C. Therefore BeCO3 will decompose first.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 87, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2024 Q#87 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "official_paper_q88_88", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 88, "subject": "Physics", "topic": "angle dependence of work", "question": "At what angle of applied force, work done will be 50%?", "options": ["30°", "60°", "90°", "45°"], "correctIndex": 1, "explanation": "Work done by a force is W = Fd cosθ; 50% of the maximum corresponds to cosθ = 0.5, which gives θ = 60°. Hence the required angle is 60°.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 88, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2024 Q#88 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "official_paper_q89_89", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 89, "subject": "Physics", "topic": "power calculation", "question": "What is the power of electric motor when it performs work of 64 × 106 J in 8 seconds?", "options": ["6 Kilowatts", "7 Kilowatts", "8 Megawatts", "7 Megawatts"], "correctIndex": 2, "explanation": "Power = work/time = (64 × 10^6 J) / 8 s = 8 × 10^6 W, which is 8 megawatts. Thus the motor's power is 8 MW.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 89, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2024 Q#89 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "official_paper_q90_90", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 90, "subject": "Physics", "topic": "momentum and kinetic energy relation", "question": "The relation between K.E and momentum P is given by:", "options": ["K.E = 1/2 P/M", "K.E = 1/2 P/M2", "K.E = 1/2 P2/M2", "K.E = 1/2 P2/M"], "correctIndex": 3, "explanation": "Momentum p = mv, so kinetic energy KE = 1/2 mv^2 can be written in terms of p as KE = p^2/(2m), i.e. KE = (1/2)(p^2/m). That corresponds to the expression given in option D.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 90, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2024 Q#90 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "official_paper_q91_91", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 91, "subject": "Physics", "topic": "energy transformations in projectile motion", "question": "When dolphin leaves the water it has lots of kinetic energy. At its highest point its energy is:", "options": ["Kinetic energy", "Potential energy", "Elastic potential energy", "Neither kinetic nor potential energy"], "correctIndex": 1, "explanation": "At the peak of its jump the dolphin's vertical velocity is zero so kinetic energy is momentarily minimized and the energy is stored as gravitational potential energy. Therefore its energy at the highest point is potential energy.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 91, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2024 Q#91 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "official_paper_q92_92", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 92, "subject": "Physics", "topic": "sign of gravitational potential energy", "question": "The absolute potential energy is given as Ug = -GmMe/R. The negative sign indicates Earth's gravitational field for mass 'm' is:", "options": ["Repulsive", "Less attractive", "Attractive", "More repulsive less attractive"], "correctIndex": 2, "explanation": "Gravitational potential energy defined as Ug = −GmM/R is negative because gravity is an attractive force and the reference (zero) is taken at infinite separation; the negative sign reflects attraction between masses. Thus the Earth's gravitational field is attractive.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 92, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2024 Q#92 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "official_paper_q93_93", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 93, "subject": "Physics", "topic": "velocity in uniform circular motion", "question": "The velocity of an object moving in a circle is:", "options": ["Constant", "Variable", "Zero", "Negative"], "correctIndex": 1, "explanation": "Although the speed (magnitude of velocity) can be constant in circular motion, the direction of the velocity vector is continuously changing, so the velocity (a vector) is not constant but variable. Therefore the velocity is variable.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 93, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2024 Q#93 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "official_paper_q94_94", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 94, "subject": "Physics", "topic": "seatbelt impulse opposite force", "question": "If you stop your car quickly by wearing seat belts, chance of injury is greatly reduced because seat belt applied:", "options": ["Extra force", "Perpendicular force", "Opposite force", "Zero force"], "correctIndex": 2, "explanation": "A seat belt provides a force opposite to the motion of the passenger to decelerate them and reduce relative motion with the car. By applying this opposing force over a short distance/time the belt reduces acceleration and hence the chance of injury.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 94, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2024 Q#94 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "official_paper_q95_95", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 95, "subject": "Physics", "topic": "elastic collision momentum change", "question": "A ball with momentum 8 kg m/s hits a wall and bounces back without losing K.E. Change in momentum is:", "options": ["4 Ns", "-16 Ns", "16 Ns", "8 Ns"], "correctIndex": 2, "explanation": "Momentum is a vector. The ball arrives with +8 kg m/s and rebounds with the same speed, so its final momentum is -8 kg m/s. The change is final minus initial = -8 - (+8) = -16 kg m/s, a magnitude of 16 N s in the opposite direction.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 95, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2024 Q#95 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "official_paper_q96_96", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 96, "subject": "Physics", "topic": "projectile angle h half range", "question": "In projectile motion for which angle maximum height is half of its range?", "options": ["73°", "65°", "63°", "68°"], "correctIndex": 2, "explanation": "Using H = u^2 sin^2θ/(2g) and R = u^2 sin2θ/g, setting H = R/2 gives sin^2θ = sin2θ = 2 sinθ cosθ, so tanθ = 2 and θ = arctan(2) ≈ 63.4°, i.e. about 63°.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 96, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2024 Q#96 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "official_paper_q97_97", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 97, "subject": "Physics", "topic": "angular displacement circular motion", "question": "Sara goes around a circular track of diameter 20m for distance 180m. Angular displacement is:", "options": ["16 radians", "18 radians", "50 radians", "8 radians"], "correctIndex": 1, "explanation": "Angular displacement θ = s/r. Radius = diameter/2 = 10 m, so θ = 180 m / 10 m = 18 radians.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 97, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2024 Q#97 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "official_paper_q98_98", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 98, "subject": "Physics", "topic": "minute hand angular speed", "question": "Angle swept by minute hand in one minute is:", "options": ["6°", "36°", "8°", "20°"], "correctIndex": 0, "explanation": "The minute hand completes 360° in 60 minutes, so in one minute it sweeps 360°/60 = 6°.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 98, "syllabusUnit": "Unit 3: Circular and Rotational Motion", "pmdcTopic": "Centripetal Acceleration, Angular Velocity & Rotational Dynamics", "textbookCitation": "PTB Physics XI Ch 5 (Circular Motion); Federal Physics XI Ch 5", "citationString": "NUMS 2024 Q#98 | Unit 3: Circular and Rotational Motion | PTB Physics XI Ch 5 (Circular Motion); Federal Physics XI Ch 5"}, "year": "2024"}, {"id": "official_paper_q99_99", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 99, "subject": "Physics", "topic": "right hand rule angular direction", "question": "To find the direction of angular displacement, use:", "options": ["Grasp axis of rotation in right hand", "Grasp axis of rotation in left hand", "Put thumb of right hand in direction of circular motion", "Put thumb of left hand in direction of circular motion"], "correctIndex": 0, "explanation": "The right-hand rule for angular vectors: curl the fingers of your right hand in the direction of rotation and the thumb points along the rotation axis giving the sign/direction of angular displacement.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 99, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2024 Q#99 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "official_paper_q100_100", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 100, "subject": "Physics", "topic": "angular velocity from speed", "question": "A particle moves in a circle of radius 10m with speed 20 m/s. Find angular velocity:", "options": ["2 rad/s", "200 rad/s", "20 rad/s", "10 rad/s"], "correctIndex": 0, "explanation": "Angular speed ω = v/r. With v = 20 m/s and r = 10 m, ω = 20/10 = 2 rad/s.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 100, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2024 Q#100 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "official_paper_q101_101", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 101, "subject": "Physics", "topic": "sign convention angular displacement", "question": "For anti-clockwise rotation the angular displacement is:", "options": ["Negative", "Positive", "Null", "Zero"], "correctIndex": 1, "explanation": "By convention anticlockwise rotation is taken as the positive direction for angular displacement, so an anti‑clockwise rotation gives a positive angular displacement.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 101, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2024 Q#101 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "official_paper_q102_102", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 102, "subject": "Physics", "topic": "speed sound material dependence", "question": "Speed of sound in solid is greater than in air because ratio:", "options": ["(√E/ρ) solid < (√E/ρ) air", "(√E/ρ) solid > (√E/ρ) air", "(√E/ρ) solid = (√E/ρ) air", "(√E/ρ) solid ≤ (√E/ρ) air"], "correctIndex": 1, "explanation": "Speed of sound in a medium scales as v = √(E/ρ) where E is the elastic modulus and ρ the density. Solids have a much larger elastic modulus than air, so √(E/ρ) (and thus sound speed) in solids is greater than in air.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 102, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "NUMS 2024 Q#102 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "official_paper_q103_103", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 103, "subject": "Physics", "topic": "spring acceleration max displacement", "question": "Body mass 10kg, spring k=20 N/m, max displacement 20cm. Acceleration is:", "options": ["2.2 ms−2", "4 ms−2", "2 ms−2", "0.4 ms−2"], "correctIndex": 3, "explanation": "Maximum acceleration at maximum displacement is a = F/m = kx/m. With k = 20 N/m, x = 0.2 m and m = 10 kg, a = (20×0.2)/10 = 0.4 m/s².", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 103, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2024 Q#103 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "official_paper_q104_104", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 104, "subject": "Physics", "topic": "sound wavelength frequency", "question": "Normal person hears 20Hz to 20KHz. Maximum wavelength is:", "options": ["17m", "17mm", "17cm", "17km"], "correctIndex": 0, "explanation": "Maximum audible wavelength corresponds to the lowest frequency, 20 Hz. Using v ≈ 340 m/s, λ = v/f = 340/20 = 17 m, so 17 m is the maximum wavelength.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 104, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "NUMS 2024 Q#104 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "official_paper_q105_105", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 105, "subject": "Physics", "topic": "dielectric constant solubility", "question": "NaCl dissolves quickly in water due to:", "options": ["Low εr", "High εr", "εr = 0", "εr = ∞"], "correctIndex": 1, "explanation": "Water’s high relative permittivity (εr) reduces the Coulomb attraction between Na+ and Cl− ions, making it easier for the solvent to separate and stabilize ions; that high εr is why NaCl dissolves readily.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 105, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "NUMS 2024 Q#105 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2024"}, {"id": "official_paper_q106_106", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 106, "subject": "Physics", "topic": "charging time constant asymptote", "question": "A capacitor can be fully charged because time required is:", "options": ["1 time constant", "2 time constant", "4 time constant", "Infinity"], "correctIndex": 3, "explanation": "Charging follows an exponential approach V(t)=Vmax(1−e^{−t/RC}), which only reaches the final voltage exactly as t → ∞, so strictly the time required to be fully charged is infinite.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 106, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "NUMS 2024 Q#106 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2024"}, {"id": "official_paper_q107_107", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 107, "subject": "Physics", "topic": "electric field point charge", "question": "Electric field at 10cm from 2μc point charge is:", "options": ["1.8 C", "180 C", "18 C", "1800 C"], "correctIndex": 3, "explanation": "Electric field magnitude E = kq/r^2. With k ≈ 9×10^9 N·m²/C², q = 2×10^−6 C and r = 0.1 m, E = 9×10^9×2×10^−6/(0.1)^2 ≈ 1.8×10^6 N/C, corresponding to the option listed (option D).", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 107, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "NUMS 2024 Q#107 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2024"}, {"id": "official_paper_q108_108", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 108, "subject": "Physics", "topic": "potential and field between identical charges", "question": "At midpoint P between two +4μc charges. V and E at midpoint P:", "options": ["V=0, E≠0", "V=0, E=0", "V≠0, E≠0", "V≠0, E=0"], "correctIndex": 3, "explanation": "At the midpoint the electric fields from the two equal positive charges are equal in magnitude and opposite in direction so E = 0, but electric potential is a scalar and adds: V = 2kq/r ≠ 0, so V≠0 and E=0.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 108, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2024 Q#108 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "official_paper_q109_109", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 109, "subject": "Physics", "topic": "isochoric heat internal energy", "question": "A process in which all heat energy is used for increasing internal energy is:", "options": ["Isobaric", "Isochoric", "Isothermal", "Adiabatic"], "correctIndex": 1, "explanation": "From the first law ΔQ = ΔU + W; in an isochoric process the volume is constant so W = 0 and all heat added goes into increasing internal energy, ΔQ = ΔU.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 109, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2024 Q#109 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "official_paper_q110_110", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 110, "subject": "Physics", "topic": "capacitor current leads voltage", "question": "Phase shift between voltage and current when AC flows through capacitor is:", "options": ["V leads I by 90°", "I leads V by 90°", "V and I in phase", "V leads I by 45°"], "correctIndex": 1, "explanation": "In a purely capacitive AC circuit the current leads the voltage by 90° because the capacitor’s charging/discharging current is proportional to the rate of change of voltage.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 110, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "NUMS 2024 Q#110 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2024"}, {"id": "official_paper_q111_111", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 111, "subject": "Physics", "topic": "work potential charge", "question": "A particle with charge 1C moves through potential difference 5V. Energy required:", "options": ["5×10−10 J", "8×10−18 J", "8J", "5J"], "correctIndex": 3, "explanation": "Work (energy) required to move charge q through potential difference V is W = qV. For q = 1 C and V = 5 V, W = 1×5 = 5 J.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 111, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2024 Q#111 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "official_paper_q112_112", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 112, "subject": "Physics", "topic": "parallel resistors equivalent", "question": "Equivalent resistance between A and B (three 1Ω resistors in parallel):", "options": ["3/2 Ω", "1/3 Ω", "3 Ω", "2/3 Ω"], "correctIndex": 1, "explanation": "Three equal resistors R in parallel give 1/Req = 1/R + 1/R + 1/R = 3/R, so Req = R/3; with R = 1 Ω, Req = 1/3 Ω.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 112, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "NUMS 2024 Q#112 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2024"}, {"id": "official_paper_q113_113", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 113, "subject": "Physics", "topic": "temperature coefficient semiconductor", "question": "The substance having negative temperature coefficient of resistance is:", "options": ["Insulators", "Conductor", "Semi-conductor", "Alloys"], "correctIndex": 2, "explanation": "Semiconductors have a negative temperature coefficient of resistance: as temperature rises more charge carriers are available, so resistance decreases with increasing temperature.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 113, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "NUMS 2024 Q#113 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2024"}, {"id": "official_paper_q114_114", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 114, "subject": "Physics", "topic": "energy dependence electric field", "question": "If electric field intensity between capacitor plates doubles, energy stored becomes:", "options": ["Double", "One half", "One Fourth", "Quadruple"], "correctIndex": 3, "explanation": "Energy stored in a capacitor U ∝ V^2 and the field E between plates is proportional to V, so if E doubles then V doubles and U increases by V^2 factor (2^2) = 4, i.e. quadruples.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 114, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2024 Q#114 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "official_paper_q115_115", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 115, "subject": "Physics", "topic": "range maximization projectile", "question": "Horizontal range of projectile will be maximum when:", "options": ["Sinθ = 1/2", "Sin2θ = 1", "Sinθ = 0", "Sin2θ = 0"], "correctIndex": 1, "explanation": "Range R ∝ sin2θ, which is maximized when sin2θ = 1 (i.e. 2θ = 90°, θ = 45°), so the horizontal range is maximum when sin2θ = 1.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 115, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2024 Q#115 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "official_paper_q116_116", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 116, "subject": "Physics", "topic": "radian to degree conversion", "question": "How many degrees in 2π/5 radians?", "options": ["80°", "50°", "72°", "20°"], "correctIndex": 2, "explanation": "Convert radians to degrees: (2π/5) rad × (180°/π) = 360°/5 = 72°.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 116, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2024 Q#116 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2024"}, {"id": "official_paper_q117_117", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 117, "subject": "Physics", "topic": "transformer power current", "question": "A transformer uses 220V line and delivers 22A at 1800V. Current drawn from line (100% efficiency)?", "options": ["22A", "180A", "200A", "50A"], "correctIndex": 1, "explanation": "Assuming 100% efficiency input power = output power. Output power = 1800 V × 22 A = 39,600 W, so input current = 39,600 W / 220 V = 180 A.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 117, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2024 Q#117 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "official_paper_q118_118", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 118, "subject": "Physics", "topic": "transformer use in rectifiers", "question": "For rectification, transformer used is:", "options": ["With low input voltage", "With low input resistance", "Step up", "Step down"], "correctIndex": 3, "explanation": "A rectifier typically needs a lower, safer secondary voltage to feed the diodes and load, so a step-down transformer is used before rectification. The transformer reduces the mains voltage to the required AC amplitude which is then converted to DC by the rectifier.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 118, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "NUMS 2024 Q#118 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2024"}, {"id": "official_paper_q119_119", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 119, "subject": "Physics", "topic": "radiation dose units", "question": "One rem is equal to:", "options": ["0.01 Gy / RBE", "0.01 Gy × RBE", "0.01 RBE", "0.01 Gy"], "correctIndex": 1, "explanation": "One rem is the equivalent dose unit defined as the absorbed dose in rad multiplied by a radiation weighting (RBE) factor. Since 1 rad = 0.01 Gy, 1 rem = 0.01 Gy × RBE.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 119, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2024 Q#119 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2024"}, {"id": "official_paper_q120_120", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 120, "subject": "Physics", "topic": "radiation absorbed dose", "question": "rad is equal to:", "options": ["0.01 J/Kg", "0.01 Kg/J", "0.01 J", "0.01 Kg"], "correctIndex": 0, "explanation": "A rad is defined as 0.01 joule of energy absorbed per kilogram of material, so 1 rad = 0.01 J/kg. This follows from 1 Gy = 1 J/kg and 1 rad = 0.01 Gy.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 120, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2024 Q#120 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2024"}, {"id": "official_paper_q121_121", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 121, "subject": "Physics", "topic": "dose energy calculation", "question": "kg man absorbs lethal dose of 200 rem with RBE factor of 10. Energy absorbed is:", "options": ["9J", "8J", "10J", "12J"], "correctIndex": 3, "explanation": "rem = rad × RBE, so rad = rem/RBE = 200/10 = 20 rad. Energy per kg = 20 rad × 0.01 J/kg = 0.2 J/kg, and for a 60 kg person total energy = 0.2 × 60 = 12 J.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 121, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2024 Q#121 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "official_paper_q122_122", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 122, "subject": "Physics", "topic": "somatic vs genetic effects", "question": "Somatic effect causes:", "options": ["Gene deformation", "Chromosomes deformation", "Skin burns", "Eye burns"], "correctIndex": 2, "explanation": "Somatic effects are those that affect the body cells of the exposed individual (not the germline), and common examples include burns and radiation sickness affecting skin and organs. Genetic effects (gene or chromosome deformation) would be classified as effects on reproductive cells.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 122, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2024 Q#122 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2024"}, {"id": "official_paper_q123_123", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 123, "subject": "Physics", "topic": "background radiation dose", "question": "Each person experiences background radiation dose in one year:", "options": ["1mSv", "1mGy", "1Gy", "1Sv"], "correctIndex": 0, "explanation": "A commonly quoted typical annual background (or the regulatory public limit for additional exposure) is about 1 mSv per year. The exam answer uses 1 mSv as the standard single-year background dose figure in this context.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 123, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "NUMS 2024 Q#123 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2024"}, {"id": "official_paper_q124_124", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 124, "subject": "Physics", "topic": "force on current carrying wire", "question": "The wire of mass m carries current I in a uniform magnetic field B at right angles. Force on wire:", "options": ["50 N", "25 N", "10 N", "5 N"], "correctIndex": 0, "explanation": "The magnetic force on a current-carrying wire is F = I L B when the current, length and field are perpendicular. Substituting the problem's given values for I, L and B into F = ILB yields the stated result of 50 N.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 124, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2024 Q#124 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "official_paper_q125_125", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 125, "subject": "English", "topic": "modal auxiliaries", "question": "The plane ought to be taking off in a minute. The underlined word 'ought to' is:", "options": ["Linking verb", "Modal auxiliary", "Helping verb", "Finite verb"], "correctIndex": 1, "explanation": "'Ought to' is a modal auxiliary verb expressing duty or expectation and combines with the base verb to form the verb phrase. It behaves like other modals (can, should, must) rather than a full lexical verb.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 125, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "NUMS 2024 Q#125 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2024"}, {"id": "official_paper_q126_126", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 126, "subject": "English", "topic": "linking verbs", "question": "After heavy rain, the sky grew dark. The underlined verb 'grew' is:", "options": ["Non-Finite", "Transitive", "Di-transitive", "Linking"], "correctIndex": 3, "explanation": "In the sentence 'the sky grew dark', 'grew' links the subject to a subject complement (dark) and functions as a linking verb meaning 'became'. It does not take a direct object, so it is classified as a linking verb here.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 126, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2024 Q#126 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2024"}, {"id": "official_paper_q127_127", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 127, "subject": "English", "topic": "ditransitive verbs", "question": "His courage earned him honour. The underlined verb 'earned' is:", "options": ["Intransitive", "Di-transitive", "Complex transitive", "Linking"], "correctIndex": 1, "explanation": "The verb 'earn' in 'His courage earned him honour' takes two objects: an indirect object ('him') and a direct object ('honour'), so it is ditransitive. That distinguishes it from monotransitive verbs which take only one object.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 127, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2024 Q#127 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2024"}, {"id": "official_paper_q128_128", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 128, "subject": "English", "topic": "ditransitive verbs", "question": "The teacher assigned the students an assignment to be completed during vacation. The underlined verb 'assigned' is:", "options": ["Mono-transitive", "Di-transitive", "Complex transitive", "Intransitive"], "correctIndex": 1, "explanation": "'Assigned' in 'The teacher assigned the students an assignment' takes both an indirect object ('the students') and a direct object ('an assignment'), so it is ditransitive. The structure matches the typical verb + indirect object + direct object pattern.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 128, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2024 Q#128 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2024"}, {"id": "official_paper_q129_129", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 129, "subject": "English", "topic": "comparative adjectives", "question": "Of two evils choose the less. The sentence contains an adjective that is:", "options": ["Comparative", "Positive", "Numeral", "Distributive"], "correctIndex": 0, "explanation": "In 'Of two evils choose the less', 'less' compares two items and therefore functions as a comparative adjective. It expresses comparison between two alternatives rather than the positive form.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 129, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "NUMS 2024 Q#129 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2024"}, {"id": "official_paper_q130_130", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 130, "subject": "English", "topic": "emphasizers", "question": "This is the very thing we want. The underlined word 'very' is a/an:", "options": ["Emphatic pronoun", "Emphasizing adjective", "Reflexive pronoun", "Exclamatory adjective"], "correctIndex": 1, "explanation": "In 'This is the very thing we want', 'very' intensifies and emphasizes the noun phrase 'thing' and is therefore an emphasizing adjective (or intensifier). It modifies the noun to stress exactness or emphasis.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 130, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "NUMS 2024 Q#130 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2024"}, {"id": "official_paper_q131_131", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 131, "subject": "English", "topic": "adjective of quantity", "question": "Don't be in such a hurry. The sentence contains an adjective of:", "options": ["Number", "Distributive", "Quantity", "Demonstrative"], "correctIndex": 2, "explanation": "In 'Don't be in such a hurry', 'such' modifies the noun phrase to indicate degree or extent and is treated as an adjective of quantity/degree in traditional grammar. It describes the extent of the hurry rather than number or distribution.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 131, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "NUMS 2024 Q#131 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2024"}, {"id": "official_paper_q132_132", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 132, "subject": "English", "topic": "past perfect continuous", "question": "Fill in blank with Past Perfect Continuous: He _____ home from work regularly since he joined his office.", "options": ["Had walked", "Had been walking", "Walked", "Has been walking"], "correctIndex": 1, "explanation": "The Past Perfect Continuous ('had been walking') is used for an action that began before a past reference point and continued up to it; 'since he joined' sets the starting point. So 'He had been walking home...' is the correct past perfect continuous form.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 132, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "NUMS 2024 Q#132 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2024"}, {"id": "official_paper_q133_133", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 133, "subject": "English", "topic": "present indefinite", "question": "All desire wealth and some acquire it. The sentence exemplifies _____ tense.", "options": ["Present indefinite", "Past indefinite", "Present perfect", "Simple future"], "correctIndex": 0, "explanation": "'All desire wealth and some acquire it' states general truths or habitual facts and is therefore in the simple present (present indefinite) tense. The verbs are in their base present forms for general statements.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 133, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2024 Q#133 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2024"}, {"id": "official_paper_q134_134", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 134, "subject": "English", "topic": "second conditional", "question": "If I were a doctor, I would serve humanity. The sentence is an example of _____ conditional.", "options": ["Zero", "Type I", "Type II", "Type III"], "correctIndex": 2, "explanation": "The sentence 'If I were a doctor, I would serve humanity' expresses an unreal or hypothetical present situation using 'were' + 'would', which is the Type II conditional. It describes an unlikely or imagined present/future condition and its consequence.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 134, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "NUMS 2024 Q#134 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2024"}, {"id": "official_paper_q135_135", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 135, "subject": "English", "topic": "third conditional", "question": "Choose the sentence which is correctly structured:", "options": ["If we had found him earlier, we could have saved his life.", "If we had found him earlier, we have saved his life.", "If we had found him earlier, we had saved his life.", "If we had found him earlier, we could save his life."], "correctIndex": 0, "explanation": "'If we had found him earlier, we could have saved his life' correctly uses the past perfect in the if-clause and the perfect conditional in the main clause, which is the standard form for past unreal (Type III) conditionals. The structure expresses an unreal past event and its possible past consequence.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 135, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "NUMS 2024 Q#135 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2024"}, {"id": "official_paper_q136_136", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 136, "subject": "English", "topic": "past perfect continuous", "question": "Choose the sentence with correct Past Perfect Continuous usage:", "options": ["He had walked home since joining", "He had been walking home since he joined", "He walked home since joining", "He has been walking home since joining"], "correctIndex": 1, "explanation": "The Past Perfect Continuous is formed with 'had been' + present participle; 'He had been walking home since he joined' correctly shows an action that started earlier and continued up to a past point. Using past simple after 'since' ('since he joined') is acceptable when the joining is a past event.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 136, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "NUMS 2024 Q#136 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2024"}, {"id": "official_paper_q137_137", "paperTitle": "NUMS MDCAT 2024 (Official Paper)", "shortTitle": "NUMS 2024", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 137, "subject": "English", "topic": "present indefinite", "question": "All desire wealth and some _____ it — which tense?", "options": ["Present Indefinite", "Present Continuous", "Present Perfect", "Past Indefinite"], "correctIndex": 0, "explanation": "Like question 145, 'All desire wealth and some _____ it' is a general truth/habit and is expressed in the simple present (present indefinite) tense. The verbs state general facts rather than specific past or progressive actions.", "reference": {"sourcePaper": "NUMS MDCAT 2024 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 137, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2024 Q#137 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2024"}, {"id": "paper_a_q1_1", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 1, "subject": "Biology", "topic": "viral structure", "question": "Example of viruses having a polyhedral capsid that is with 252 capsomeres is:", "options": ["A. Adenovirus", "B. Tobacco Mosaic Virus", "C. Influenza virus", "D. Bacteriophage"], "correctIndex": 0, "explanation": "Adenovirus is a classic example of a virus with a large icosahedral (polyhedral) capsid composed of 252 capsomeres; the other options are either helical (Tobacco mosaic virus) or different morphologies (bacteriophage has a head-tail structure).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 1, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "UHS 2024 Q#1 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2024"}, {"id": "paper_a_q2_2", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 2, "subject": "Biology", "topic": "measles virus", "question": "The causative organism of measles is", "options": ["A. Poxivirus", "B. Parvovirus", "C. Picornovirus", "D. Paramyxovirus"], "correctIndex": 3, "explanation": "Measles is caused by a paramyxovirus (Measles virus), so option D is correct. The other virus families listed cause different diseases and have different genome/structural properties.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 2, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "UHS 2024 Q#2 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2024"}, {"id": "paper_a_q3_3", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 3, "subject": "Biology", "topic": "bacteriophage infection cycle", "question": "In the life cycle of a bacteriophage, the lysozymes are required in which of the following steps of infection process?", "options": ["A. Genome injection", "B. Penetration", "C. Replication", "D. Adsorption"], "correctIndex": 1, "explanation": "Phage lysozymes degrade the bacterial cell wall to allow entry of the phage nucleic acid, so they act during penetration. Adsorption is the initial binding step, genome injection follows penetration but the enzymatic weakening of the cell wall is part of penetration rather than replication.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 3, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "UHS 2024 Q#3 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2024"}, {"id": "paper_a_q4_4", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 4, "subject": "Biology", "topic": "blood borne pathogens", "question": "_______ is transmitted through infected blood and hypodermic syringes.", "options": ["A. HIV", "B. Influenza Virus", "C. Morbilli Virus (Measles)", "D. Vibrio Cholerae (Cholera)"], "correctIndex": 0, "explanation": "HIV is a blood-borne pathogen commonly transmitted via infected blood and contaminated needles. Influenza and measles are primarily respiratory, and Vibrio cholerae is transmitted fecal-orally.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 4, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "UHS 2024 Q#4 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2024"}, {"id": "paper_a_q5_5", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 5, "subject": "Biology", "topic": "calvin cycle", "question": "In Calvin cycle CO2 reacts with RuBP to produce", "options": ["A. 3-PGA", "B. G3P", "C. 6-Carbon unstable intermediate", "D. 1,3 bisphosphglycerate"], "correctIndex": 2, "explanation": "The immediate product of CO2 fixation to RuBP is a short-lived 6-carbon unstable intermediate that quickly splits into two 3-PGA molecules, so option C is the most precise. Saying 3‑PGA (option A) is a downstream result after the unstable intermediate breaks.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 5, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "UHS 2024 Q#5 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2024"}, {"id": "paper_a_q6_6", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 6, "subject": "Biology", "topic": "chlorophyll structure", "question": "Which option is correct about a chlorophyll molecule?", "options": ["A. Chemical formula C55 H70 O6 N4Mg", "B. Porphyrin ring with nitrogen in centre", "C. Methyl group on second pyrrole ring", "D. Aldehyde group on second pyrrole ring"], "correctIndex": 0, "explanation": "The molecular formula C55H70O6N4Mg is that of chlorophyll b. Every chlorophyll is built on a magnesium-centred porphyrin (tetrapyrrole) ring, and this particular formula identifies the chlorophyll b variant.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 6, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "UHS 2024 Q#6 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2024"}, {"id": "paper_a_q7_7", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 7, "subject": "Biology", "topic": "photosynthetic electron transport", "question": "In the journey of electrons from photosystem II to photosystem I plastocyanine is reduced by", "options": ["A. Plastoquinone", "B. Cytochrome complex", "C. P700", "D. Primary electron acceptor of PSI"], "correctIndex": 1, "explanation": "Electrons pass from the cytochrome b6f complex to plastocyanin, which reduces plastocyanin; plastoquinone transfers electrons earlier and P700 is the reaction center of PSI that receives electrons from plastocyanin. Hence the cytochrome complex is correct.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 7, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#7 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q8_8", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 8, "subject": "Biology", "topic": "ferredoxin nadp reductase", "question": "Enzyme NADP reductase is responsible for:", "options": ["A. Reducing NADP+", "B. Oxidizing NADP +", "C. Reducing Ferredoxin", "D. Reducing P700"], "correctIndex": 0, "explanation": "Ferredoxin–NADP+ reductase catalyses the transfer of electrons from reduced ferredoxin to NADP+, producing NADPH, so it reduces NADP+. It does not oxidize NADP+ or reduce P700 directly.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 8, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2024 Q#8 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q9_9", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 9, "subject": "Biology", "topic": "photolysis", "question": "The PS II during light reactions receives electrons from splitting of", "options": ["A. Water", "B. Plastoquinone", "C. Plastocyanin", "D. Ferridoxin"], "correctIndex": 0, "explanation": "Photosystem II obtains electrons from the photolysis (splitting) of water, which releases electrons, protons and oxygen. Plastoquinone and plastocyanin are carriers later in the chain and ferredoxin functions at PSI.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 9, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "UHS 2024 Q#9 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2024"}, {"id": "paper_a_q10_10", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 10, "subject": "Biology", "topic": "monosaccharide general formula", "question": "Mono-saccharides have a general formula represented by", "options": ["A. Cn(H2O)n", "B. C(H2O)n", "C. C2(H2O)n", "D. Cn(H2O)n"], "correctIndex": 0, "explanation": "The general formula of a monosaccharide is Cn(H2O)n — equal numbers of carbon and 'water' units, as in glucose C6(H2O)6. The forms with a single C or a fixed C2 do not represent the general case.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 10, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#10 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q11_11", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 11, "subject": "Biology", "topic": "water content of bone", "question": "What is the percentage of H2O in bone cells?", "options": ["A. 70 %", "B. 20 %", "C. 99 %", "D. 60 %"], "correctIndex": 1, "explanation": "Bone is a hard, heavily mineralised tissue, so its water content is far lower than that of soft tissues — about 20%. The higher figures listed (70% or 99%) describe soft tissues and body fluids, not bone.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 11, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2024 Q#11 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q12_12", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 12, "subject": "Biology", "topic": "lipid esterification", "question": "When glycerol reacts with fatty acid, which type of chemical bond will form?", "options": ["A. Ester Bond", "B. Ether Linkage", "C. Hydrogen Bond", "D. Ionic Bond"], "correctIndex": 0, "explanation": "Ester bonds form between the hydroxyl groups of glycerol and the carboxyl groups of fatty acids during triglyceride formation; ether, hydrogen and ionic bonds are not the covalent linkage produced in this reaction.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 12, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2024 Q#12 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q13_13", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 13, "subject": "Biology", "topic": "polysaccharide synthesis", "question": "Polysaccharides in plants are synthesized by the process of", "options": ["A. Hydrolysis", "B. Oxidation", "C. Condensation", "D. Glycolysis"], "correctIndex": 2, "explanation": "Polysaccharide synthesis is a condensation (dehydration) reaction that links monosaccharide units with glycosidic bonds, releasing water. Hydrolysis and glycolysis break down sugars rather than build them.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 13, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2024 Q#13 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q14_14", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 14, "subject": "Biology", "topic": "protein hydrolysis", "question": "Which of the following process Is involved in breakdown of protein into Amino acids?", "options": ["A. Condensation", "B. Hydrolysis", "C. Glycolysis", "D. Fixation"], "correctIndex": 1, "explanation": "Proteins are degraded to amino acids by hydrolysis, where peptide bonds are cleaved by addition of water. Condensation is the reverse (bond formation), and glycolysis/fixation are unrelated to peptide bond cleavage.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 14, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2024 Q#14 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q15_15", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 15, "subject": "Biology", "topic": "phospholipid structure", "question": "The hydrophilic end of phospholplid molecule is polar because of the presence of", "options": ["A. Glycerol", "B. Amine group", "C. Fatty Acid", "D. Phosphate group"], "correctIndex": 3, "explanation": "The hydrophilic (polar) head of a phospholipid contains a phosphate group (often linked to another polar group), which gives it polarity and affinity for water; fatty acid tails are hydrophobic and glycerol is the backbone rather than the primary polar moiety.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 15, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2024 Q#15 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q16_16", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 16, "subject": "Biology", "topic": "monosaccharide pyranose formation", "question": "Which monosaccharide will from a gluco pyranose ring in solution?", "options": ["Fructose", "Glucose", "Ribose", "Deoxyribose"], "correctIndex": 1, "explanation": "Glucose readily cyclizes to form a stable six-membered (pyranose) ring in solution; fructose forms a furanose ring more commonly, and ribose/deoxyribose are five-carbon sugars that form furanoses rather than pyranoses.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 16, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#16 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q17_17", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 17, "subject": "Biology", "topic": "golgi apparatus function", "question": "Which of the following is the function of Golgi Complex?", "options": ["Intracellular digestion", "Autophagy", "Autolysis", "Processing of cell secretions"], "correctIndex": 3, "explanation": "The Golgi complex modifies, sorts and packages proteins and lipids for secretion or delivery to other organelles, so 'Processing of cell secretions' is correct; intracellular digestion/autolysis are lysosomal functions and autophagy is a degradative process.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 17, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2024 Q#17 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q18_18", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 18, "subject": "Biology", "topic": "nuclear staining chromatin", "question": "The nucleus takes dyes due to the presence of", "options": ["Chromatin", "Lipid", "Metal ions", "Thylakoids"], "correctIndex": 0, "explanation": "Nuclear staining (basophilia) is due to chromatin (DNA and associated proteins) which bind basic dyes; lipids and thylakoids do not account for nuclear dye uptake, and metal ions are not the staining factor here.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 18, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2024 Q#18 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q19_19", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 19, "subject": "Biology", "topic": "glyoxysomes in seeds", "question": "The organelles only found at seeding stage in oil seed plants are", "options": ["Peroxiosomes", "Glyoxisomes", "Microbodies", "Vacuoles"], "correctIndex": 1, "explanation": "Glyoxysomes (a type of microbody) are specialized peroxisomes present in oil-storing seeds that convert fatty acids to carbohydrates during germination; vacuoles and generic peroxisomes are not specific to this seed stage.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 19, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2024 Q#19 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q20_20", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 20, "subject": "Biology", "topic": "posterior pituitary hormones", "question": "Posterior lobe of pituitary produce", "options": ["Antidiuretic Hormone (ADH)", "Thyroid Stimulating Hormone (TSH)", "Adreno Corticufrotic Hormone (ACH)", "Follicle Stimulating Hormone (FSH)"], "correctIndex": 0, "explanation": "The posterior pituitary releases ADH (vasopressin) and oxytocin; TSH, FSH and ACTH (adrenocorticotropic hormone) are secreted by the anterior pituitary.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 20, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "UHS 2024 Q#20 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2024"}, {"id": "paper_a_q21_21", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 21, "subject": "Biology", "topic": "nerve impulse conduction speed", "question": "In human myelinated fibers nerve impulse travels at _____ meters per second.", "options": ["100-120", "130-150", "160-180", "190-210"], "correctIndex": 0, "explanation": "Typical conduction velocities for large myelinated human fibers are around 100–120 m/s; the other listed ranges are higher than common physiological values for peripheral myelinated axons.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 21, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "UHS 2024 Q#21 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2024"}, {"id": "paper_a_q22_22", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 22, "subject": "Biology", "topic": "nissl granules composition", "question": "Nissl's granules are groups of", "options": ["Mesosomes", "Lysosomes", "Ribosomes", "Chromosome"], "correctIndex": 2, "explanation": "Nissl bodies are clusters of rough endoplasmic reticulum and ribosomes in neuron cell bodies, so 'Ribosomes' is the best match; mesosomes are bacterial structures and chromosomes/lysosomes are incorrect here.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 22, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#22 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q23_23", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 23, "subject": "Biology", "topic": "resting membrane permeability", "question": "During non-conducting state, the neuron membrane is permeable to efflux of", "options": ["K+", "Na+", "Ca+", "Cl-"], "correctIndex": 0, "explanation": "At rest the neuronal membrane is primarily permeable to K+ due to open K+ leak channels, producing the resting membrane potential; Na+ and Ca2+ permeability is low at rest and Cl- is not the main efflux ion.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 23, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2024 Q#23 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q24_24", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 24, "subject": "Biology", "topic": "peripheral neurotransmitters", "question": "Which of the following neurotransmitters is lying outside the central nervous system?", "options": ["Acetylcholine", "Endorphins", "Dopamine", "Gamma - aminobutyric acid"], "correctIndex": 0, "explanation": "Acetylcholine is a major neurotransmitter in the peripheral nervous system (e.g., at neuromuscular junctions); endorphins, dopamine and GABA are primarily central neurotransmitters.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 24, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#24 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q25_25", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 25, "subject": "Biology", "topic": "depolarization mechanism", "question": "Depolarization during conduction of nerve impulse is due to", "options": ["Inward movement of Na+", "Inward movement of K+", "Outward movement of K+", "Outward movement of Na+"], "correctIndex": 0, "explanation": "Depolarization results from opening of voltage-gated Na+ channels and the rapid inward Na+ current; inward K+ or outward Na+ are not the mechanisms producing the rising phase of the action potential.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 25, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "UHS 2024 Q#25 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2024"}, {"id": "paper_a_q26_26", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 26, "subject": "Biology", "topic": "autonomic nervous system features", "question": "Which of the following is NOT a feature of Autonomic Nervous System?", "options": ["Regulate response of visceral organs", "Regulate response of skeletal muscles", "Regulate response of glands", "Regulate response of smooth muscles"], "correctIndex": 1, "explanation": "The autonomic nervous system regulates visceral organs, glands and smooth muscle; skeletal muscle is controlled by the somatic nervous system, so option B is not a feature of the ANS.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 26, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#26 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q27_27", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 27, "subject": "Biology", "topic": "taste receptor type", "question": "Taste receptor is an example of", "options": ["Mechano receptors", "Nociceptors", "Photo receptors", "Chemo receptors"], "correctIndex": 3, "explanation": "Taste receptors detect chemicals in food, so they are chemoreceptors; mechanoreceptors detect mechanical stimuli, nociceptors detect pain, and photoreceptors detect light.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 27, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#27 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q28_28", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 28, "subject": "Biology", "topic": "examples of chordates", "question": "Which of the following belongs to chordates", "options": ["Spider", "Earthworm", "Trout Fish", "Star Fish"], "correctIndex": 2, "explanation": "Trout fish are vertebrate chordates (have a notochord/vertebral column); spiders are arthropods, earthworms are annelids and starfish are echinoderms.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 28, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#28 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q29_29", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 29, "subject": "Biology", "topic": "factors affecting enzyme rate", "question": "Which of the following statement is incorrect regarding rate of enzymatic action", "options": ["Increase in enzyme concentration increases the rate", "Increase in enzyme concentration reduces the rate", "All enzymes work at their maximum rate at optimum temperature", "All enzymes work at their maximum rate at optimum pH"], "correctIndex": 1, "explanation": "Statement B is incorrect: increasing enzyme concentration (with substrate in excess) generally increases reaction rate; the other statements are true generalizations about enzyme activity and optimal conditions.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 29, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2024 Q#29 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q30_30", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 30, "subject": "Biology", "topic": "induced fit model", "question": "Induced fit model of enzyme activity suggests that an enzyme", "options": ["Cannot modify its active sites", "Can bind to a single substrate", "Can catalyze related reaction", "Usually belongs to non-regulatory enzyme"], "correctIndex": 2, "explanation": "The induced-fit model says an enzyme active site is flexible and moulds itself around the substrate as it binds, rather than being a rigid lock. Because the site can adjust, the enzyme can accommodate closely related substrates and catalyse related reactions. Option A is wrong because induced fit specifically involves the active site changing shape.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 30, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2024 Q#30 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2024"}, {"id": "paper_a_q31_31", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 31, "subject": "Biology", "topic": "turner syndrome karyotype", "question": "Chromosomal abnormality in Turner syndrome is represented by?", "options": ["XXX", "XYY", "XO", "XXY"], "correctIndex": 2, "explanation": "Turner syndrome is a monosomy of the X chromosome — a single X with no second sex chromosome, written 45,X or XO. XXX, XYY and XXY are the karyotypes of other conditions.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 31, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#31 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q32_32", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 32, "subject": "Biology", "topic": "genetic drift", "question": "The change in frequency of alleles at a locus that occurs by chance is known as:", "options": ["Mutation", "Genetic Drift", "Non Random mating", "Speciation"], "correctIndex": 1, "explanation": "A change in allele frequencies at a locus caused purely by chance is genetic drift. Mutation introduces new alleles, non-random mating alters genotype frequencies, and speciation is the formation of new species — none of which is the random-sampling effect the question describes.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 32, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "UHS 2024 Q#32 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2024"}, {"id": "paper_a_q33_33", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 33, "subject": "Biology", "topic": "vestigial organs", "question": "Identify the correct pair of vestigial organs:", "options": ["Ear Muscles & Vermiform appendix", "Heart & Liver", "Ear Muscles & Liver", "Vermiform appendix & Heart"], "correctIndex": 0, "explanation": "Ear muscles and the vermiform appendix are both classic human vestigial structures — reduced remnants with little or no present function. The heart and liver are fully functional organs, so any pair including them is not a pair of vestigial organs.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 33, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#33 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q34_34", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 34, "subject": "Biology", "topic": "sources of variation", "question": "Which of the following increases variation within a gene pool?", "options": ["Chromosome inversion", "Crossing over", "Gene mutation", "Random fusion of gametes"], "correctIndex": 2, "explanation": "Gene mutation creates entirely new alleles, so it is the ultimate source of new variation in a gene pool. Crossing over and random fusion of gametes only reshuffle alleles that already exist, and chromosome inversion rearranges existing genes rather than creating new ones.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 34, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#34 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q35_35", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 35, "subject": "Biology", "topic": "natural selection facts", "question": "Which of the following statements about natural selection is not true?", "options": ["It affects variations that are heritable", "It is selected by a breeder", "It can improve the adaptation of species", "It is regional in nature"], "correctIndex": 1, "explanation": "The false statement is that it 'is selected by a breeder' — that describes artificial selection, not natural selection. Natural selection acts on heritable variation, can improve a species' adaptation, and varies by region, so those statements are all true.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 35, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "UHS 2024 Q#35 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2024"}, {"id": "paper_a_q36_36", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 36, "subject": "Biology", "topic": "hardy weinberg equation", "question": "The formula calculating the frequency of genotypes and alleles in a population gene pool is known as:", "options": ["Hardy-Weinberg Equation", "Lamarck Equation", "Darwin Equation", "James Hutton Equation"], "correctIndex": 0, "explanation": "The Hardy-Weinberg equation relates allele and genotype frequencies in a population's gene pool. The other named 'equations' are not the standard population-genetics formula.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 36, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "UHS 2024 Q#36 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2024"}, {"id": "paper_a_q37_37", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 37, "subject": "Biology", "topic": "lamarckian theory", "question": "The idea of inheritance of acquired characteristics was presented by:", "options": ["Jean Baptist Lamarck", "Charles Darwin", "Thomas Malthus", "Alfred Wallace"], "correctIndex": 0, "explanation": "Jean-Baptiste Lamarck proposed the inheritance of acquired characteristics — the idea that traits gained during an organism's life could be passed to offspring. Darwin, Malthus and Wallace are linked to other evolutionary ideas, not this one.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 37, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "UHS 2024 Q#37 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2024"}, {"id": "paper_a_q38_38", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 38, "subject": "Biology", "topic": "endosymbiosis theory", "question": "According to endosymbiosis theory, flagella may have derived by the ingestion of prokaryotes similar to", "options": ["Amoeboid prokaryote", "Aerobic bacterium", "Spirochete", "Spirillum"], "correctIndex": 2, "explanation": "Under the endosymbiotic hypothesis for motility, flagella are proposed to have arisen from ingested spirochete-like bacteria, whose whip-like movement suited a flagellar role. The other prokaryotes listed are not the ones classically invoked for flagellar origin.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 38, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#38 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q39_39", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 39, "subject": "Biology", "topic": "insulin action", "question": "Insulin converts glucose into", "options": ["Vitamins", "Minerals", "Lipids", "Cortisone"], "correctIndex": 2, "explanation": "The key shows option C. Insulin promotes lipogenesis (conversion of excess glucose into fatty acids/lipids) as well as glycogen synthesis. It does not convert glucose into vitamins, minerals, or cortisone.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 39, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#39 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q40_40", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 40, "subject": "Biology", "topic": "co2 transport", "question": "About 70% of the carbon dioxide is carried in blood as:", "options": ["Carbonate", "Bicarbonate", "Tricarbonate", "Carbonic anhydrase"], "correctIndex": 1, "explanation": "About 70% of carbon dioxide is carried in the blood as bicarbonate ions (HCO3-) dissolved in the plasma. Carbonic anhydrase is the enzyme that catalyses the conversion of CO2 to bicarbonate, not a transport form of CO2.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 40, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "UHS 2024 Q#40 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2024"}, {"id": "paper_a_q41_41", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 41, "subject": "Biology", "topic": "lung capacity", "question": "Range of normal total lung capacity in humans is", "options": ["5-6 liter", "8-9 liter", "10-11 liter", "12-13 liter"], "correctIndex": 0, "explanation": "The total lung capacity of a healthy adult is about 5-6 litres. The larger values listed lie well outside the normal human range.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 41, "syllabusUnit": "Unit 8: Human Physiology - Gas Exchange", "pmdcTopic": "Mechanisms of Breathing & Blood Gas Regulation", "textbookCitation": "PTB Biology XI Ch 13 (Gaseous Exchange); Federal Biology XI Ch 13", "citationString": "UHS 2024 Q#41 | Unit 8: Human Physiology - Gas Exchange | PTB Biology XI Ch 13 (Gaseous Exchange); Federal Biology XI Ch 13"}, "year": "2024"}, {"id": "paper_a_q42_42", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 42, "subject": "Biology", "topic": "bacterial respiration", "question": "Respiration in Pseudomonas bacteria is", "options": ["Aerobic", "Anaerobic", "Facultative", "Microaerophili"], "correctIndex": 0, "explanation": "Pseudomonas species are typically obligate aerobes — they need oxygen for respiration. They are not generally anaerobic, facultative or microaerophilic.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 42, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "UHS 2024 Q#42 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2024"}, {"id": "paper_a_q43_43", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 43, "subject": "Biology", "topic": "autotrophic nutrition", "question": "Autotrophic mode of nutrition in organism depends upon", "options": ["Saprotrophic mode", "Parasitic mode", "Photosynthesis mode", "Obligate mode"], "correctIndex": 2, "explanation": "Autotrophs make their own organic food, and the autotrophic mode here depends on photosynthesis, which uses light energy to build organic molecules. Saprotrophic and parasitic modes are heterotrophic, relying on food made by others.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 43, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#43 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q44_44", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 44, "subject": "Biology", "topic": "prokaryote features", "question": "Prokaryotic cells lack", "options": ["Mesosomes", "Ribosomes", "Storage bodies", "Membrane bound organelles"], "correctIndex": 3, "explanation": "Prokaryotic cells lack membrane-bound organelles such as mitochondria, endoplasmic reticulum and a true nucleus. They do have ribosomes and can carry storage bodies and mesosome-like folds, so those are not what they lack.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 44, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2024 Q#44 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q45_45", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 45, "subject": "Biology", "topic": "bacterial genome ploidy", "question": "Bacterial genome becomes diploid:", "options": ["After fertilization of gametes", "Before spore formation", "During binary fission", "After binary fission"], "correctIndex": 2, "explanation": "The key lists option C. During certain stages of cell division (replication prior to cytokinesis) a bacterium can transiently have duplicated genomes, so ‘during binary fission’ describes the period when two copies are present. The other options do not correctly describe typical bacterial genome duplication timing.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 45, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "UHS 2024 Q#45 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2024"}, {"id": "paper_a_q46_46", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 46, "subject": "Biology", "topic": "flagella structure", "question": "One of the following is CORRECT regarding flagella?", "options": ["Made up of macrofilaments", "Contains centriole", "Originates from basal bodies", "They are immotile"], "correctIndex": 2, "explanation": "Bacterial and eukaryotic flagella differ, but the statement that is classically correct for many flagella (e.g. eukaryotic) is that they originate from basal bodies (centriole-derived structures). They are not immotile (D is false), flagella are not described as made of \"macrofilaments\" in standard terminology (A is incorrect), and flagella are not the same as centrioles (B is incorrect).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 46, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#46 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q47_47", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 47, "subject": "Biology", "topic": "endospore formation", "question": "Which option is CORRECT about endospore?", "options": ["Has a short dormant period", "Contains moisture for survival", "Metabolically actively", "Endures extreme condition"], "correctIndex": 3, "explanation": "Endospores are specialized dormant forms that endure extreme environmental conditions (D). They are metabolically inactive rather than active (C is wrong), they do not contain moisture to aid survival (they are highly dehydrated, so B is wrong), and their dormancy is long-term not short (A is wrong).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 47, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#47 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q48_48", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 48, "subject": "Biology", "topic": "bacterial growth curve", "question": "Bacteria divide at exponential rate during which growth phase?", "options": ["Lag", "Log", "Stationary", "Decline"], "correctIndex": 1, "explanation": "The logarithmic (log) phase is when bacteria divide at an exponential rate (B). During lag phase cells adapt and do not divide rapidly (A), stationary phase has balanced growth and death rates (C), and decline (death) phase sees numbers fall (D).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 48, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "UHS 2024 Q#48 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2024"}, {"id": "paper_a_q49_49", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 49, "subject": "Biology", "topic": "mesosomes", "question": "Mesosomes are the invagination of bacterial cell structure", "options": ["Cell wall", "Cell membrane", "Plasmid", "Cysts"], "correctIndex": 1, "explanation": "Mesosomes are invaginations of the bacterial cell membrane (B). They are not invaginations of the cell wall (A), nor are they plasmids (circular DNA) (C), and they are unrelated to cyst structures (D).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 49, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2024 Q#49 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q50_50", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 50, "subject": "Biology", "topic": "female reproductive anatomy", "question": "Female reproductive system consists all of the following EXCEPT", "options": ["Ovaries", "Oviduct", "Cervix", "Seminiferous tubules"], "correctIndex": 3, "explanation": "Seminiferous tubules are part of the male reproductive system, so they are the exception (D). Ovaries, oviducts (fallopian tubes), and cervix are normal components of the female reproductive tract (A–C are included).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 50, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#50 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q51_51", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 51, "subject": "Biology", "topic": "parturition hormones", "question": "Which one of the following hormone is responsible for the labor pains in human female at the time of birth of baby?", "options": ["Estrogen", "Progesterone", "Oxytocin", "Corticosteroid"], "correctIndex": 2, "explanation": "Oxytocin stimulates uterine contractions and is the primary hormone responsible for labor pains (C). Estrogen and progesterone modulate pregnancy and labor readiness but do not directly cause the contraction bursts (A,B incorrect), and corticosteroids are not the main drivers of labor pain (D incorrect).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 51, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "UHS 2024 Q#51 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2024"}, {"id": "paper_a_q52_52", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 52, "subject": "Biology", "topic": "sertoli cell secretion", "question": "Fluid secreted by sertoli cells provides liquid medium, protection and nourishment to:", "options": ["Oocyte", "Sperms", "Polar body", "Spermatogonia"], "correctIndex": 1, "explanation": "Sertoli cells in the seminiferous tubules secrete fluid that supports and nourishes developing sperms (B). They do not provide this fluid for oocytes or polar bodies (A,C), and while they support spermatogenesis generally, the secreted fluid specifically aids sperm movement and maturation rather than spermatogonia alone (D is less appropriate).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 52, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2024 Q#52 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q53_53", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 53, "subject": "Biology", "topic": "corpus luteum hormone", "question": "Corpus luteum during female reproductive cycle produces", "options": ["Testosterone", "Follicle stimulating hormone", "Luteinizing Hormone", "Progesterone"], "correctIndex": 3, "explanation": "The corpus luteum primarily secretes progesterone to maintain the uterine lining after ovulation (D). It does not produce FSH or LH (B,C) and is not a major source of testosterone (A).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 53, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "UHS 2024 Q#53 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2024"}, {"id": "paper_a_q54_54", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 54, "subject": "Biology", "topic": "follicular atresia", "question": "Due to the process of follicle atresia:", "options": ["Follicles reach maximum size", "Follicle degenerates", "Graafian follicle ovulates", "Follicle starts to mature"], "correctIndex": 1, "explanation": "Follicular atresia is the degeneration of ovarian follicles that fail to mature to ovulation, so the follicle simply degenerates. The other options describe a follicle reaching maximum size, ovulating, or beginning to mature, which are the opposite of atresia.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 54, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#54 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q55_55", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 55, "subject": "Biology", "topic": "epididymis function", "question": "Main function of the epididymis is to:", "options": ["Transport sperms", "Connect with urethra", "Produce semen", "Hold the process of spermatogenesis"], "correctIndex": 0, "explanation": "The epididymis primarily transports and stores sperm while they mature, so transport sperms is correct (A). It does not connect to the urethra (that is the vas deferens/urethral pathway) (B), it does not produce semen (seminal vesicles/prostate contribute to semen) (C), and spermatogenesis occurs in the testes (seminiferous tubules) rather than being 'held' in the epididymis (D).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 55, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#55 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q56_56", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 56, "subject": "Biology", "topic": "spermatogenesis stages", "question": "Immediate next stage of spermatogonia differentiation is:", "options": ["Secondary spermatocyte", "Spermatids", "Primary spermatocytes", "Sperms"], "correctIndex": 2, "explanation": "In spermatogenesis, spermatogonia first differentiate into primary spermatocytes, which then undergo meiosis to give secondary spermatocytes, then spermatids, and finally mature sperm. So the immediate next stage after spermatogonia is the primary spermatocyte.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 56, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "UHS 2024 Q#56 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2024"}, {"id": "paper_a_q57_57", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 57, "subject": "Biology", "topic": "cranial bones", "question": "Which of the following is included in paired cranial bones?", "options": ["Temporal", "Occipital", "Frontal", "Vomer"], "correctIndex": 0, "explanation": "The temporal bones are paired cranial bones (A). Occipital and frontal bones are single (unpaired) in adult skulls (B,C), and the vomer is an unpaired facial bone (D).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 57, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "UHS 2024 Q#57 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2024"}, {"id": "paper_a_q58_58", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 58, "subject": "Biology", "topic": "autoimmune skeletal disorders", "question": "Which of the following skeletal disorder Is an example of autoimmune disorder?", "options": ["Sciatica", "Spondylosis", "Rheumatoid arthritis", "Rickets"], "correctIndex": 2, "explanation": "Rheumatoid arthritis is an autoimmune disease that primarily affects joints (C). Sciatica and spondylosis are mechanical/degenerative conditions (A,B), and rickets is a metabolic bone disease due to vitamin D deficiency (D).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 58, "syllabusUnit": "Unit 7: Human Physiology - Immunity", "pmdcTopic": "Innate & Adaptive Immunity, Immunoglobulins and Vaccines", "textbookCitation": "PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14", "citationString": "UHS 2024 Q#58 | Unit 7: Human Physiology - Immunity | PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14"}, "year": "2024"}, {"id": "paper_a_q59_59", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 59, "subject": "Biology", "topic": "smooth muscle characteristics", "question": "Which feature is possessed by smooth muscles?", "options": ["Voluntary", "Branched", "Uni-nucleate", "Striated appearance"], "correctIndex": 2, "explanation": "Smooth muscle cells are uninucleate (single nucleus) and non-striated (C). They are involuntary (so A is wrong), they are not branched (B is a feature of cardiac muscle), and they lack the striated appearance seen in skeletal muscle (D is incorrect).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 59, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "UHS 2024 Q#59 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2024"}, {"id": "paper_a_q60_60", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 60, "subject": "Biology", "topic": "lactic acid effects", "question": "The accumulation of 'lactic acid' in the muscles results in", "options": ["Extreme fatigue", "Muscle contraction", "Paralysis", "Convulsion"], "correctIndex": 0, "explanation": "Lactic acid accumulation during anaerobic exercise contributes to muscle fatigue and discomfort (A). It does not directly cause sustained muscle contraction (B), paralysis (C), or convulsions (D).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 60, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "UHS 2024 Q#60 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2024"}, {"id": "paper_a_q61_61", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 61, "subject": "Biology", "topic": "muscle filament composition", "question": "Thick filaments In skeletal muscles are composed of:", "options": ["Actin", "Myosin", "Tropomyosin", "Troponin"], "correctIndex": 1, "explanation": "Thick filaments are primarily composed of myosin (B). Actin forms the thin filaments (A), while tropomyosin and troponin are thin-filament-associated regulatory proteins (C,D).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 61, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "UHS 2024 Q#61 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2024"}, {"id": "paper_a_q62_62", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 62, "subject": "Biology", "topic": "sarcomere location", "question": "Sarcomere is part of myofibril between:", "options": ["Two I bands", "Two A bands", "Two M lines", "Two Z lines"], "correctIndex": 3, "explanation": "A sarcomere is the functional unit of a myofibril and is defined as the region between two adjacent Z lines. The A band and I band lie within the sarcomere, and the M line runs through its centre.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 62, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "UHS 2024 Q#62 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2024"}, {"id": "paper_a_q63_63", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 63, "subject": "Biology", "topic": "medulla oblongata location", "question": "Medulla Oblongata is a part of:", "options": ["Forebrain", "Mid brain", "Hind brain", "Hippocampus"], "correctIndex": 2, "explanation": "The medulla oblongata is part of the hindbrain, where it controls vital reflexes such as breathing and heart rate. The hippocampus is part of the limbic system, not a brain division.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 63, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2024 Q#63 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2024"}, {"id": "paper_a_q64_64", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 64, "subject": "Biology", "topic": "bones of upper limb", "question": "Which of the following is NOT a bone of upper limb?", "options": ["Humerus", "Ulna", "Femur", "Radius"], "correctIndex": 2, "explanation": "The humerus, ulna and radius are all bones of the upper limb. The femur is the thigh bone of the lower limb, so it is the one that does not belong.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 64, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "UHS 2024 Q#64 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2024"}, {"id": "paper_a_q65_65", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 65, "subject": "Biology", "topic": "bone forming cells", "question": "Bone forming cells are", "options": ["Osteoblasts", "Osteocytes", "Osteoclasts", "Osteons"], "correctIndex": 0, "explanation": "Osteoblasts are the bone-forming cells that lay down new bone matrix. Osteocytes are mature bone cells trapped within the matrix, and osteoclasts break bone down.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 65, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2024 Q#65 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2024"}, {"id": "paper_a_q66_66", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 66, "subject": "Biology", "topic": "history of chromosome discovery", "question": "The chromosomes was first observed by;", "options": ["T. H Morgan", "Griffith", "Walther", "Mendel"], "correctIndex": 2, "explanation": "Chromosomes were first observed and described by Walther Flemming during his studies of cell division. Morgan and Mendel worked on inheritance, and Griffith on bacterial transformation.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 66, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "UHS 2024 Q#66 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2024"}, {"id": "paper_a_q67_67", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 67, "subject": "Chemistry", "topic": "mole concepts", "question": "Number of moles in an element is directly proportional to:", "options": ["Mass of an element", "Empirical formula mass", "Molar mass of an element", "Formula mass"], "correctIndex": 0, "explanation": "Since number of moles = mass divided by molar mass, for a given element the number of moles is directly proportional to its mass. Molar mass and formula mass are fixed constants for a substance, not quantities it varies with.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 67, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2024 Q#67 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q68_68", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 68, "subject": "Chemistry", "topic": "isotope analysis mass spectrometry", "question": "The type and relative amount of each isotope in an element can be found by:", "options": ["R spectroscopy", "U. V spectroscopy", "Mass Spectrometry", "N.M.R"], "correctIndex": 2, "explanation": "A mass spectrometer separates ions by their mass-to-charge ratio, so it reveals which isotopes are present in an element and their relative abundance. IR, UV and NMR probe bonds and structure, not isotopic composition.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 68, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "UHS 2024 Q#68 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2024"}, {"id": "paper_a_q69_69", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 69, "subject": "Chemistry", "topic": "atomic mass dependency", "question": "The atomic masses of element depend upon:", "options": ["Atomic number", "Number of electrons", "Number of isopotes & their abundance", "None of the above"], "correctIndex": 2, "explanation": "An element's atomic mass is the weighted average of its isotopes' masses, so it depends on which isotopes exist and their relative abundance. It is not determined by atomic number or the number of electrons.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 69, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "UHS 2024 Q#69 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2024"}, {"id": "paper_a_q70_70", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 70, "subject": "Chemistry", "topic": "atomic mass neon", "question": "No individual atom in the sample of 1 mole of Neon has a mass of 20.18 a.m.u. because it is:", "options": ["Overall mass of an isobar", "It is a fractional mass", "It is molar mass of Ne", "Average atomic mass of Ne"], "correctIndex": 3, "explanation": "No single neon atom weighs 20.18 a.m.u because that value is the average atomic mass of neon, weighted across its isotopes (mainly Ne-20, Ne-21 and Ne-22). Individual atoms have whole-number mass numbers.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 70, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "UHS 2024 Q#70 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2024"}, {"id": "paper_a_q71_71", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 71, "subject": "Chemistry", "topic": "p orbital shape", "question": "The p orbital has", "options": ["2 lobes", "3 lobes", "4 lobes", "5 lobes"], "correctIndex": 0, "explanation": "A p orbital is dumbbell-shaped with two lobes lying on opposite sides of the nucleus. Each of the three p orbitals (px, py, pz) has this same two-lobed shape.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 71, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "UHS 2024 Q#71 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2024"}, {"id": "paper_a_q72_72", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 72, "subject": "Chemistry", "topic": "electronic configuration carbon", "question": "Which of the following electronic configuration is correct for carbon?", "options": ["1s22s2p3", "1s22s2p4", "1s22s2p2", "1s22s2p1"], "correctIndex": 2, "explanation": "Carbon has 6 electrons, which fill as 1s2 2s2 2p2. The other configurations hold the wrong total number of electrons for carbon.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 72, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "UHS 2024 Q#72 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2024"}, {"id": "paper_a_q73_73", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 73, "subject": "Chemistry", "topic": "intermolecular forces ideal gas", "question": "Intermolecular forces between molecules of ideal gas are", "options": ["Strong", "Moderate", "Weak", "Absent"], "correctIndex": 3, "explanation": "An ideal gas is defined as having no intermolecular forces of attraction or repulsion between its molecules. This is one of the central assumptions of the kinetic molecular theory of an ideal gas.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 73, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2024 Q#73 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "paper_a_q74_74", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 74, "subject": "Chemistry", "topic": "ideal gas equation", "question": "The correct ideal gas equation is", "options": ["qV=nRt", "pV=nRt", "gV=nRt", "yV=nRt"], "correctIndex": 1, "explanation": "The ideal gas equation is PV = nRT, relating pressure, volume, number of moles, the gas constant and temperature. The other options replace pressure with meaningless symbols.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 74, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2024 Q#74 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "paper_a_q75_75", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 75, "subject": "Chemistry", "topic": "real gas deviation", "question": "The real gases show deviation from ideal behavior at:", "options": ["Low temperature and low pressure", "High temperature and high pressure", "Low temperature and high pressure", "High temperature and low pressure"], "correctIndex": 2, "explanation": "Real gases deviate most from ideal behaviour at low temperature and high pressure, where the molecules are close together and their intermolecular forces and finite volume can no longer be ignored.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 75, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2024 Q#75 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "paper_a_q76_76", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 76, "subject": "Chemistry", "topic": "boiling point pressure", "question": "In order to boil water at 110°C, external pressure should be", "options": ["200 - 760 torr", "760 - 1200 torr", "665-670 torr", "660-700 torr"], "correctIndex": 1, "explanation": "Water boils when its vapour pressure equals the external pressure. To raise the boiling point above 100 degrees to 110 degrees, the external pressure must be greater than the normal 760 torr, placing it in the 760-1200 torr range.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 76, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "UHS 2024 Q#76 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2024"}, {"id": "paper_a_q77_77", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 77, "subject": "Chemistry", "topic": "hydrogen bonding", "question": "Which one of the following DO NOT have tendency to form hydrogen bonding?", "options": ["Ammonia", "Ethyl alcohol", "Carboxylic acid", "Hydrocarbon"], "correctIndex": 3, "explanation": "Hydrocarbons lack highly electronegative atoms (O, N, F) bonded to hydrogen and so cannot form hydrogen bonds, making option D correct. Ammonia, ethyl alcohol and carboxylic acids all contain N or O–H bonds and readily form hydrogen bonds, so they are incorrect choices.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 77, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2024 Q#77 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "paper_a_q78_78", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 78, "subject": "Chemistry", "topic": "boiling point", "question": "Boiling point of a liquid is a temperature at which:", "options": ["Surface tension is greater than the atmospheric pressure", "Viscosity is less than the atmospheric pressure", "Vapour pressure equals the atmospheric pressure", "Viscosity equals the atmospheric pressure"], "correctIndex": 2, "explanation": "Boiling occurs when a liquid's vapour pressure equals the external (atmospheric) pressure, so option C is correct. The other options confuse different physical properties (surface tension, viscosity) with pressure and are not definitions of boiling point.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 78, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2024 Q#78 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "paper_a_q79_79", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 79, "subject": "Chemistry", "topic": "crystal planes cleavage", "question": "Whenever the crystalline solids are broken they do so along definite planes known as:", "options": ["Cleavage planes", "Refractory planes", "Sagittal planes", "Coronal planes"], "correctIndex": 0, "explanation": "Crystalline solids break along specific crystallographic planes called cleavage planes, so option A is correct. The other terms (refractory, sagittal, coronal) are unrelated to the cleavage phenomenon in crystals.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 79, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2024 Q#79 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "paper_a_q80_80", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 80, "subject": "Chemistry", "topic": "amorphous solids", "question": "One of the following is NOT an example of amorphous solids", "options": ["Plastic", "Glass", "Glucose", "Rubber"], "correctIndex": 2, "explanation": "Glucose is a molecular (crystalline) solid when pure and thus not amorphous, making option C correct. Plastics, glass and rubber are typical examples of amorphous (non-crystalline) solids, so they are incorrect choices.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 80, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2024 Q#80 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "paper_a_q81_81", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 81, "subject": "Chemistry", "topic": "graphite structure", "question": "In graphite the carbon atoms are arranged in which of the following structure?", "options": ["Rhombic", "Hexagonal", "Tetragonal", "Trigonal"], "correctIndex": 1, "explanation": "Graphite has a hexagonal layered structure formed by sheets of sp2-hybridized carbon atoms, so option B is correct. The other crystal systems listed do not describe graphite's arrangement.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 81, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "UHS 2024 Q#81 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2024"}, {"id": "paper_a_q82_82", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 82, "subject": "Chemistry", "topic": "le chatelier principle", "question": "The principle that states that if a stress is applied to a system at equilibrium the system nullify the effect of stress as far as possible is:", "options": ["Haber's", "Le-Chatelier", "Boyle's", "Charles'"], "correctIndex": 1, "explanation": "Le Chatelier's principle states that a system at equilibrium will respond to an imposed stress by shifting to counteract the change, so option B is correct. Haber’s, Boyle’s and Charles’ laws describe different chemical/physical principles and do not state this equilibrium response.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 82, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "UHS 2024 Q#82 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2024"}, {"id": "paper_a_q83_83", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 83, "subject": "Chemistry", "topic": "haber process", "question": "Identify the CORRECT option required for the maximum yield of ammonia by Haber's process:", "options": ["High pressure low temperature continual removal of ammonia", "Low pressure low temperature continual removal of ammonia", "High pressure high temperature continual removal of ammonia", "High pressure low temperature continual addition of ammonia"], "correctIndex": 0, "explanation": "The Haber process favours ammonia formation (exothermic) at low temperature and high pressure; continuously removing ammonia shifts equilibrium to produce more product. Thus option A is correct. High temperature disfavors yield and adding ammonia does not drive further formation.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 83, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2024 Q#83 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q84_84", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 84, "subject": "Chemistry", "topic": "precipitation equilibrium", "question": "Consider the following reaction in equilibrium and tell addition of which chemical will turn the cloudy solution into clear solution?\nBiCl3 + H2O <-> BiOCl + 2HCl", "options": ["BiCl3", "H2O", "BiOCl", "HCl"], "correctIndex": 3, "explanation": "Adding HCl increases the H+ concentration and shifts the equilibrium left, favouring soluble BiCl3 and dissolving the BiOCl precipitate, so option D is correct. Adding BiOCl or water would not dissolve the precipitate, and adding BiCl3 would increase turbidity.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 84, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "UHS 2024 Q#84 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2024"}, {"id": "paper_a_q85_85", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 85, "subject": "Chemistry", "topic": "rate definition", "question": "Identify the correct formula to calculate rate of reaction:", "options": ["Change in concentration of substance ÷ Time taken for the change", "Time taken for the change ÷ Change in concentration of substance", "Time taken for the change ÷ Change in concentration of substance x 100", "Time taken for the change x Change in concentration of substance"], "correctIndex": 0, "explanation": "Reaction rate is defined as the change in concentration of a reactant or product divided by the time over which the change occurs, so option A is correct. The other options invert the ratio or multiply incorrectly and are not the rate definition.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 85, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "UHS 2024 Q#85 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2024"}, {"id": "paper_a_q86_86", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 86, "subject": "Chemistry", "topic": "rate law expression", "question": "Consider the hypothetical equation aA + bB -> cC+dD: Which of the following represents correct rate equation?", "options": ["Rate = k[A][B]", "Rate = k[A]^b[B]^b", "Rate = k[A]^a", "Rate = k[B]^2"], "correctIndex": 1, "explanation": "For an elementary reaction, the rate law follows the stoichiometric coefficients, giving Rate = k[A]^a[B]^b. The other expressions apply only in special cases and are not the correct general form for the reaction aA + bB -> cC + dD.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 86, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "UHS 2024 Q#86 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2024"}, {"id": "paper_a_q87_87", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 87, "subject": "Chemistry", "topic": "reaction order", "question": "If a reaction rate does not change with concentration then it is", "options": ["3rd order", "2nd order", "1st order", "Zero order"], "correctIndex": 3, "explanation": "If the rate is independent of concentration, the reaction is zero order, so option D is correct. First-, second- and third-order reactions show rate dependence on concentration and therefore are not applicable.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 87, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "UHS 2024 Q#87 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2024"}, {"id": "paper_a_q88_88", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 88, "subject": "Chemistry", "topic": "arrhenius equation", "question": "Which of the following is CORRECT Arrhenius equation?", "options": ["K =Ae- Ea/RT", "K =Ae -Ea/RT", "K=Ae - Ea/ST", "K=Ae -Ea/UT"], "correctIndex": 1, "explanation": "The Arrhenius equation is k = A e^(-Ea/RT), linking the rate constant to activation energy and temperature through the gas constant R. The options using 'S' or 'U' in place of RT are wrong, since the denominator must be RT.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 88, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2024 Q#88 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q89_89", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 89, "subject": "Chemistry", "topic": "endothermic enthalpy", "question": "In endothermic reaction, the heat content of the", "options": ["A. Reactants and products is equal", "B. Reactants is more than that of products", "C. Products is more than that of reactants", "D. Reactants & Products will not change"], "correctIndex": 2, "explanation": "In an endothermic reaction heat is absorbed from the surroundings, so the products contain more heat (enthalpy) than the reactants. Option C correctly states this. Options A and D are incorrect because they imply no net heat change, and B is the opposite of what occurs.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 89, "syllabusUnit": "Unit 4: Chemical Energetics", "pmdcTopic": "Enthalpy Changes, Hess's Law & Standard Heats of Reaction", "textbookCitation": "PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6", "citationString": "UHS 2024 Q#89 | Unit 4: Chemical Energetics | PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6"}, "year": "2024"}, {"id": "paper_a_q90_90", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 90, "subject": "Chemistry", "topic": "born haber steps", "question": "All of the following steps are used to calculate the lattice energy in Born-Haber cycle EXCEPT", "options": ["A. Atomizing the metal", "B. Ionizing the metal", "C. Delonlize the metal", "D. Ionlize non metal"], "correctIndex": 2, "explanation": "The Born–Haber cycle uses steps like atomization, ionization, electron affinity, and formation enthalpy; 'Delonlize the metal' is not a real step (it appears to be a misspelling/nonexistent term). Options A, B and D (ionizing/ionize) correspond to legitimate concepts in the cycle (atomization and formation of ions).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 90, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2024 Q#90 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2024"}, {"id": "paper_a_q91_91", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 91, "subject": "Chemistry", "topic": "enthalpy of neutralization", "question": "The enthalpy change when1 Mole of water is formed by the reaction of acid with an alkali under standard conditions is known as:", "options": ["A. Enthalpy of formation", "B. Enthalpy of reaction", "C. Enthalpy of combustion", "D. Enthalpy of neutralization"], "correctIndex": 3, "explanation": "The enthalpy change for formation of 1 mole of water by neutralization of an acid and base is defined as the enthalpy of neutralization. Enthalpy of formation refers to formation from elements; combustion is burning; enthalpy of reaction is general and not the specific neutralization definition.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 91, "syllabusUnit": "Unit 4: Chemical Energetics", "pmdcTopic": "Enthalpy Changes, Hess's Law & Standard Heats of Reaction", "textbookCitation": "PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6", "citationString": "UHS 2024 Q#91 | Unit 4: Chemical Energetics | PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6"}, "year": "2024"}, {"id": "paper_a_q92_92", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 92, "subject": "Chemistry", "topic": "oxidation number", "question": "Oxidation number of 'Mn' in KMnO4 is", "options": ["A. 0", "B. +1", "C. -7", "D. +7"], "correctIndex": 3, "explanation": "In KMnO4, K is +1 and each O is -2 (total -8), so Mn must be +7 to balance (+1 + Mn - 8 = 0). Thus +7 is correct. The other choices do not satisfy the overall neutrality of the compound.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 92, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "UHS 2024 Q#92 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2024"}, {"id": "paper_a_q93_93", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 93, "subject": "Chemistry", "topic": "redox balancing oxidation number method", "question": "Which step is irrelevant with respect to balancing of redox equations by oxidation number method?", "options": ["A. Split the reaction into two half reactions", "B. Assign oxidation number to all the atoms involved in the equation", "C. Identify the element undergoing a change in oxidation number", "D. Equalize the number of electrons lost and gained"], "correctIndex": 0, "explanation": "The oxidation-number method does not require splitting into half-reactions (that is part of the half-reaction method), so option A is irrelevant. Options B, C and D are core steps in the oxidation-number balancing approach.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 93, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "UHS 2024 Q#93 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2024"}, {"id": "paper_a_q94_94", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 94, "subject": "Chemistry", "topic": "electrolytic cell features", "question": "Which of the following is NOT a correct feature of electrolytic cells?", "options": ["A. Reduction occurs at cathode", "B. Oxidation occurs at anode", "C. Alternating current source is connected to electrodes", "D. Electrochemical reaction takes place"], "correctIndex": 2, "explanation": "Electrolytic cells use a direct current source to drive non-spontaneous reactions; an alternating current would reverse polarity and not serve to drive a consistent electrolysis, so C is incorrect. A and B correctly state reduction/oxidation sites, and D is true.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 94, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2024 Q#94 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q95_95", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 95, "subject": "Chemistry", "topic": "coordinate bond", "question": "Which of the following has a coordinate bond?", "options": ["A. NaCl", "B. CaO", "C. NH3BF3", "D. H2O"], "correctIndex": 2, "explanation": "In NH3·BF3 (written NH3BF3), the ammonia donates a lone pair to boron forming a dative (coordinate) bond. NaCl, CaO and H2O primarily involve ionic or covalent bonds without such a donor-acceptor coordinate bond feature.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 95, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "UHS 2024 Q#95 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2024"}, {"id": "paper_a_q96_96", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 96, "subject": "Chemistry", "topic": "vsepr theory", "question": "Which of the following is NOT a feature of Valence Shell Electron Pair Repulsion theory?", "options": ["A. It determines the shape of molecule", "B. Pairs of electrons repel each other", "C. It helps in understanding interaction of medicinal drug molecules", "D. Only lone pairs participate in determining geometry of molecules"], "correctIndex": 3, "explanation": "VSEPR considers both bonding and lone electron pairs in determining molecular geometry; saying only lone pairs participate is false, so D is incorrect. A and B are central to VSEPR, and C is a broader application (not a foundational feature) but is not the clearly incorrect statement like D.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 96, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "UHS 2024 Q#96 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2024"}, {"id": "paper_a_q97_97", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 97, "subject": "Chemistry", "topic": "atomic radius trends", "question": "Which of the following has smallest atomic radius", "options": ["A. Mg", "B. S", "C. P", "D. Na"], "correctIndex": 1, "explanation": "Among the listed elements, sulfur (S) is furthest to the right in the same period as P and has more effective nuclear charge, giving it the smallest atomic radius. Mg and Na are in earlier periods or are metals with larger radii.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 97, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "UHS 2024 Q#97 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2024"}, {"id": "paper_a_q98_98", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 98, "subject": "Chemistry", "topic": "lithium anomalous properties", "question": "The difference of lithium from the other alkall metals is mainly because of:", "options": ["A. Large radius and low charge density", "B. Small radius and low charge density", "C. Large radius and high charge density", "D. Small radius and high charge density"], "correctIndex": 3, "explanation": "Lithium is anomalous among alkali metals due to its very small atomic/ionic radius and correspondingly high charge density, which leads to properties differing from heavier alkalis. Options A–C contradict the small-radius/high-charge-density fact.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 98, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2024 Q#98 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q99_99", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 99, "subject": "Chemistry", "topic": "oxide acid base character", "question": "Which of the following is not Basic in nature", "options": ["A. Aluminum oxide", "B. Magnesium oxide", "C. Potassium oxide", "D. Sodium oxide"], "correctIndex": 0, "explanation": "Aluminum oxide is amphoteric (can behave as acidic or basic), so it is not purely basic, making A correct for this question. MgO, K2O and Na2O are typically basic oxides, so B–D are basic in nature.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 99, "syllabusUnit": "Unit 12: Carboxylic Acids & Derivatives", "pmdcTopic": "Acidity of Carboxylic Acids & Acyl Derivatives", "textbookCitation": "PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21", "citationString": "UHS 2024 Q#99 | Unit 12: Carboxylic Acids & Derivatives | PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21"}, "year": "2024"}, {"id": "paper_a_q100_100", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 100, "subject": "Chemistry", "topic": "solubility trends sulfates", "question": "The solubility of sulphates of alkaline metals generally", "options": ["A. Increase down the group", "B. Decrease down the group", "C. Increase then decrease down the group", "D. Doesn't change down the group"], "correctIndex": 1, "explanation": "For group 2 (alkaline earth) sulfates, solubility generally decreases down the group due to increasing lattice energy relative to hydration energy; the question wording 'alkaline metals' likely refers to these trends and B matches the common trend. The other options do not reflect the typical solubility trend.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 100, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "UHS 2024 Q#100 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2024"}, {"id": "paper_a_q101_101", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 101, "subject": "Chemistry", "topic": "alloys examples", "question": "Which of the following is NOT an Alloy", "options": ["A. Steel", "B. Brass", "C. Bronze", "D. Graphite"], "correctIndex": 3, "explanation": "Steel, brass and bronze are all alloys (iron-carbon, copper-zinc, and copper-tin based respectively). Graphite is a form of elemental carbon, not an alloy, so D is correct. The other choices are classic alloy examples.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 101, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2024 Q#101 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q102_102", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 102, "subject": "Chemistry", "topic": "chromium electronic configuration", "question": "Electronic configuration of chromium (Proton number 24) is:", "options": ["[Ar] 3d4 4s2", "[Ar] 3d5 4s2", "[Ar] 3d5 4s1", "[Ar] 3d6 4s2"], "correctIndex": 2, "explanation": "Chromium exhibits the exceptional configuration [Ar] 3d5 4s1 due to half‑filled d subshell stability. The naive filling [Ar] 3d4 4s2 is not the observed ground-state configuration.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 102, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "UHS 2024 Q#102 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2024"}, {"id": "paper_a_q103_103", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 103, "subject": "Chemistry", "topic": "properties of transition metals", "question": "Which of the following is NOT a property of transition elements?", "options": ["High melting points", "Good conductors of electricity", "Hard metals", "Ions and compounds are colorless"], "correctIndex": 3, "explanation": "Transition metal ions and many of their compounds are typically colored due to d–d electronic transitions; saying they are colorless is incorrect. The other listed properties are characteristic of many transition metals.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 103, "syllabusUnit": "Unit 8: Inorganic Chemistry & Periodicity", "pmdcTopic": "Periodic Trends, Group Chemistry & Transition Elements", "textbookCitation": "PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16", "citationString": "UHS 2024 Q#103 | Unit 8: Inorganic Chemistry & Periodicity | PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16"}, "year": "2024"}, {"id": "paper_a_q104_104", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 104, "subject": "Chemistry", "topic": "geometric isomerism", "question": "Which type of isomerism is displayed by compounds having same structural formula but different position of atoms on both sides of carbon bond?", "options": ["Chain", "Metamerism", "Geometric", "Tautomerism"], "correctIndex": 2, "explanation": "When atoms/groups on the two sides of a carbon–carbon double bond have different positions (e.g., cis/trans), that is geometric (stereoisomerism). Chain and metamerism refer to connectivity isomers; tautomerism involves proton shift and different functional group placement.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 104, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "UHS 2024 Q#104 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2024"}, {"id": "paper_a_q105_105", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 105, "subject": "Chemistry", "topic": "substituent electron donating withdrawing", "question": "Which of the following is an example of substituent group which release electrons to benzene ring :", "options": ["-CN", "-NR3+", "-NH2", "-NO2"], "correctIndex": 2, "explanation": "The –NH2 group is an electron-donating (activating) substituent via resonance and the lone pair on nitrogen, increasing electron density on the ring. –NO2 and –CN are strongly electron-withdrawing; –NR3+ is positively charged and withdraws electron density.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 105, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "UHS 2024 Q#105 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2024"}, {"id": "paper_a_q106_106", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 106, "subject": "Chemistry", "topic": "friedel crafts acylation catalyst", "question": "In Friedel Craft acylation an acyl group is introduced in benzene ring in the presence of catalyst:", "options": ["AlCl3", "H2SO4", "Sunlight", "V2O5"], "correctIndex": 0, "explanation": "Friedel–Crafts acylation is catalyzed by Lewis acids such as AlCl3 which generate the acylium ion. Sulfuric acid, sunlight or V2O5 are not the standard catalysts for this reaction.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 106, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "UHS 2024 Q#106 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2024"}, {"id": "paper_a_q107_107", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 107, "subject": "Chemistry", "topic": "substitution vs elimination", "question": "Identify the correct statement related to substitution and elimination of alkyl halides:", "options": ["Strong bases causes substitution in preference to elimination", "Role of leaving groups in elimination is similar to substitution", "Substitution is favored more than elimination by decreasing solvent polarity", "Decrease in temperature will favor elimination more than substitution"], "correctIndex": 1, "explanation": "The role of leaving groups is important and similar in both substitution and elimination: a better leaving group facilitates both processes. Strong bases generally favor elimination, and lower temperature typically favors substitution over elimination, so those statements are incorrect.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 107, "syllabusUnit": "Unit 10: Alkyl Halides, Alcohols & Phenols", "pmdcTopic": "Nucleophilic Substitution, Elimination Reactions & Phenol Acidity", "textbookCitation": "PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19", "citationString": "UHS 2024 Q#107 | Unit 10: Alkyl Halides, Alcohols & Phenols | PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19"}, "year": "2024"}, {"id": "paper_a_q108_108", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 108, "subject": "Chemistry", "topic": "sn2 mechanism", "question": "Alkyl Halides involving –C–X bond breakage and –C–Nu bond formation simultaneously would follow which one of the following mechanisms", "options": ["SN1", "SN2", "E1", "E2"], "correctIndex": 1, "explanation": "SN2 is a concerted bimolecular nucleophilic substitution where the C–X bond breaks and the C–Nu bond forms simultaneously in a single step. SN1 involves a carbocation intermediate and is not simultaneous.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 108, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "UHS 2024 Q#108 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2024"}, {"id": "paper_a_q109_109", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 109, "subject": "Chemistry", "topic": "general formulas of organic families", "question": "CnH2nO is the general formula of:", "options": ["Ether", "Carboxylic acid", "Ketones", "Carbolic acid"], "correctIndex": 2, "explanation": "The general formula CnH2nO corresponds to simple aldehydes and ketones (e.g., propanal C3H6O, acetone C3H6O). Ethers have formula CnH2n+2O, carboxylic acids CnH2nO2, and 'carbolic acid' (phenol) is aromatic and not described by this general formula.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 109, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2024 Q#109 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2024"}, {"id": "paper_a_q110_110", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 110, "subject": "Chemistry", "topic": "fehling test product", "question": "The blue color of Fehling solution is changed to red when warmed with an aldehyde due to formation of which of the following?", "options": ["NO2", "Cu2O", "AgO", "SO2"], "correctIndex": 1, "explanation": "Fehling's reagent oxidizes aldehydes to carboxylates while reducing Cu(II) to red cuprous oxide (Cu2O), giving the characteristic red precipitate. AgO is associated with Tollens' test, not Fehling's.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 110, "syllabusUnit": "Unit 11: Carbonyl Compounds (Aldehydes & Ketones)", "pmdcTopic": "Carbonyl Chemistry, Addition Reactions & Tests for Carbonyls", "textbookCitation": "PTB Chemistry XII Ch 12 (Aldehydes and Ketones); Federal Chemistry XII Ch 20", "citationString": "UHS 2024 Q#110 | Unit 11: Carbonyl Compounds (Aldehydes & Ketones) | PTB Chemistry XII Ch 12 (Aldehydes and Ketones); Federal Chemistry XII Ch 20"}, "year": "2024"}, {"id": "paper_a_q111_111", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 111, "subject": "Chemistry", "topic": "nucleophilic addition cyanohydrin formation", "question": "Reaction of HCN with formaldehyde is a:", "options": ["Nucleophilic addition reaction", "Nucleophilic substitution reaction", "Electrophilic addition reaction", "Electrophilic substitution reaction"], "correctIndex": 0, "explanation": "HCN adds across the carbonyl group of formaldehyde via nucleophilic attack of CN- at the carbonyl carbon, forming a cyanohydrin; this is a nucleophilic addition, not substitution or electrophilic processes.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 111, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "UHS 2024 Q#111 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2024"}, {"id": "paper_a_q112_112", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 112, "subject": "Chemistry", "topic": "iodoform test", "question": "Which of the following alcohol can give Iodoform reaction?", "options": ["Methanol", "1-Butanol", "1-Propanol", "Ethanol"], "correctIndex": 3, "explanation": "Ethanol (and secondary methyl ketones / alcohols with a CH3CH(OH)– or CH3CH2– structure) gives the iodoform test producing a yellow precipitate of CHI3. Methanol, 1‑butanol and 1‑propanol do not give a positive iodoform test.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 112, "syllabusUnit": "Unit 10: Alkyl Halides, Alcohols & Phenols", "pmdcTopic": "Nucleophilic Substitution, Elimination Reactions & Phenol Acidity", "textbookCitation": "PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19", "citationString": "UHS 2024 Q#112 | Unit 10: Alkyl Halides, Alcohols & Phenols | PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19"}, "year": "2024"}, {"id": "paper_a_q113_113", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 113, "subject": "Chemistry", "topic": "common names", "question": "Common name of 2-hydroxy propanoic acid is:", "options": ["Tartaric acid", "Lactic acid", "Phthalic acid", "Formic acid"], "correctIndex": 1, "explanation": "2-Hydroxypropanoic acid is commonly known as lactic acid. Tartaric and phthalic acids are different dicarboxylic acids; formic acid is methanoic acid.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 113, "syllabusUnit": "Unit 12: Carboxylic Acids & Derivatives", "pmdcTopic": "Acidity of Carboxylic Acids & Acyl Derivatives", "textbookCitation": "PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21", "citationString": "UHS 2024 Q#113 | Unit 12: Carboxylic Acids & Derivatives | PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21"}, "year": "2024"}, {"id": "paper_a_q114_114", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 114, "subject": "Chemistry", "topic": "phenol acidity", "question": "Which of the following is correct regarding phenol", "options": ["Phenol and water are equally acidic", "Phenol is less acidic than carboxylic acid", "Phenol is less acidic than water", "Phenol is less acidic than ethanol"], "correctIndex": 1, "explanation": "Phenol is less acidic than typical carboxylic acids (carboxyl group is stronger acid), so option B is correct. Phenol is more acidic than water and much more acidic than ethanol, so options C and D are incorrect.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 114, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "UHS 2024 Q#114 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2024"}, {"id": "paper_a_q115_115", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 115, "subject": "Chemistry", "topic": "esterification", "question": "When carboxylic acid are heated with alcohol in the presence of sulphuric acid one of the following is formed", "options": ["Amides", "Acyl chloride", "Esters", "Acid Anhydride"], "correctIndex": 2, "explanation": "Heating a carboxylic acid with an alcohol in the presence of concentrated acid (sulphuric acid) is the Fischer esterification reaction, which converts the acid and alcohol into an ester and water. Amides or acyl chlorides are formed by different reagents and conditions.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 115, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "UHS 2024 Q#115 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2024"}, {"id": "paper_a_q116_116", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 116, "subject": "Chemistry", "topic": "amino acids", "question": "Which one of the following is not an amino acid", "options": ["Folic acid", "Glutamic acid", "Glycine", "Lysine"], "correctIndex": 0, "explanation": "Folic acid is a B-vitamin (folate) and is not an amino acid. Glutamic acid, glycine and lysine are examples of amino acids (components of proteins).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 116, "syllabusUnit": "Unit 12: Carboxylic Acids & Derivatives", "pmdcTopic": "Acidity of Carboxylic Acids & Acyl Derivatives", "textbookCitation": "PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21", "citationString": "UHS 2024 Q#116 | Unit 12: Carboxylic Acids & Derivatives | PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21"}, "year": "2024"}, {"id": "paper_a_q117_117", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 117, "subject": "Physics", "topic": "elastic collision energy", "question": "In an elastic collision the total kinetic energy", "options": ["Dissipates after collision", "Increases after the collision", "Reduces after the collision", "Before and after collision remains the same"], "correctIndex": 3, "explanation": "By definition an elastic collision conserves kinetic energy, so the total kinetic energy before and after the collision is the same. Inelastic collisions do not conserve kinetic energy.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 117, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2024 Q#117 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q118_118", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 118, "subject": "Physics", "topic": "instantaneous velocity", "question": "The instantaneous velocity along the curved path is ;", "options": ["Along the tangent", "Perpendicular to the slope", "Parallel to the radius", "Anti-parallel to the radius"], "correctIndex": 0, "explanation": "The instantaneous velocity of a particle moving along a curved path is tangent to the path at that point. It is not radial (parallel to the radius) nor perpendicular to the tangent.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 118, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2024 Q#118 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q119_119", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 119, "subject": "Physics", "topic": "projectile range", "question": "The range of projectile will be maximum if the factor sin2θ becomes", "options": ["Zero", "1", "-1", "2"], "correctIndex": 1, "explanation": "The range of a projectile is proportional to sin(2θ); its maximum value is 1, which occurs when 2θ = 90° (θ = 45°). Values of 0 or -1 give smaller or negative-range conditions.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 119, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2024 Q#119 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q120_120", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 120, "subject": "Physics", "topic": "projectile motion", "question": "The two dimensional motion under constant acceleration due to gravity is called:", "options": ["Circular motion", "Rotational motion", "Projectile motion", "Vibratory motion"], "correctIndex": 2, "explanation": "Two-dimensional motion under the constant acceleration of gravity is the definition of projectile motion (motion of objects under gravity with horizontal and vertical components). Circular and rotational motion are different types of motion with different accelerations.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 120, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2024 Q#120 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q121_121", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 121, "subject": "Physics", "topic": "v t area", "question": "In velocity time graph the area under graph is equal to the:", "options": ["Speed of an object", "Velocity of an object", "Distance covered by object", "Acceleration of an object"], "correctIndex": 2, "explanation": "The area under a velocity–time graph gives displacement (and, if velocity is non-negative, the distance traveled). It is not the instantaneous velocity or acceleration.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 121, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2024 Q#121 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q122_122", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 122, "subject": "Physics", "topic": "newtonian mechanics", "question": "According to Newton's Law of Motion the mass of the object is a quantitative measure of its:", "options": ["Weight", "Inertia", "Speed", "Acceleration"], "correctIndex": 1, "explanation": "By Newtonian mechanics mass measures an object's resistance to acceleration (inertia), so 'Inertia' is correct. Weight is a force dependent on gravity, not the intrinsic mass.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 122, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2024 Q#122 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q123_123", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 123, "subject": "Physics", "topic": "energy units", "question": "1KWh = _________ J?", "options": ["3.6J", "3.6KJ", "3.6 MJ", "3.6 GJ"], "correctIndex": 2, "explanation": "1 kilowatt-hour equals 3.6 × 10^6 joules, i.e. 3.6 MJ, so option C is correct.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 123, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2024 Q#123 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "paper_a_q124_124", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 124, "subject": "Physics", "topic": "non conservative forces", "question": "Which of the following is a non-conservative force?", "options": ["Frictional force", "Electric force", "Elastic spring force", "Gravitational force"], "correctIndex": 0, "explanation": "Friction dissipates mechanical energy as heat and depends on the path taken, so it is non-conservative. Electric, elastic spring and gravitational forces are conservative (assuming electrostatic field).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 124, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2024 Q#124 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q125_125", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 125, "subject": "Physics", "topic": "work definition", "question": "Work done is equal to:", "options": ["Effort x distance", "Effort + distance", "Effort - distance", "Effort ÷distance"], "correctIndex": 0, "explanation": "Work is force (effort) multiplied by displacement (distance) in the direction of the force, so 'Effort x distance' is correct.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 125, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2024 Q#125 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "paper_a_q126_126", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 126, "subject": "Physics", "topic": "work calculation", "question": "When a force of 1N displaces its point of application by 1m in the direction of force, the work done is", "options": ["1 J", "10 J", "0 J", "1"], "correctIndex": 0, "explanation": "Work = force × displacement = 1 N × 1 m = 1 joule; option A is the correctly stated result.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 126, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2024 Q#126 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q127_127", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 127, "subject": "Physics", "topic": "power", "question": "An electric motor is used to lift the weight of 2.0N through a vertical distance of 100 cm in 4 sec. What is the power output of the motor?", "options": ["0.25 W", "0.5 W", "0.75 W", "1 W"], "correctIndex": 1, "explanation": "Work = force × distance = 2.0 N × 1.00 m = 2.0 J. Power = work/time = 2.0 J / 4 s = 0.5 W (option B).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 127, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2024 Q#127 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "paper_a_q128_128", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 128, "subject": "Physics", "topic": "centripetal acceleration", "question": "The centripetal acceleration of an object moving along a circle of radius 'r' with an angular speed 'w' is given by the formula:", "options": ["a = rw^2", "a = r ω", "a = r^2 ω", "A = r^2 ω^2"], "correctIndex": 0, "explanation": "The standard relation is a_c = r ω^2. Option A as printed (a = r w^2) matches this form (ω denoted as w), so it is correct.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 128, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2024 Q#128 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q129_129", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 129, "subject": "Physics", "topic": "angular velocity", "question": "An air craft makes a turn in a horizontal circle of radius100m. It is travelling with a velocity of 250m/sec. The angular velocity of the air craft will be:", "options": ["1.5 rad/sec", "2.5 rad/sec", "3 rad/sec", "3.5 rad/sec"], "correctIndex": 1, "explanation": "Angular velocity ω = v/r = 250 / 100 = 2.5 rad/s, so option B is correct.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 129, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2024 Q#129 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q130_130", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 130, "subject": "Physics", "topic": "centripetal force scaling", "question": "A particle of mass 'm' is moving on a circular path of radius 'r' with velocity 'v', then centripetal force acting on it is F. If the velocity of particle increases by 2 times and radius of circular path increases by 4 times then new centripetal force F' will be;", "options": ["F' = 2 F", "F' = 1/2 F", "F' = 4 F", "F' = F"], "correctIndex": 3, "explanation": "Centripetal force is F = m v^2 / r. Doubling the speed multiplies v^2 by 4, and increasing the radius fourfold divides by 4, so F' = m (4 v^2) / (4 r) = m v^2 / r = F. The force is unchanged.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 130, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2024 Q#130 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q131_131", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 131, "subject": "Physics", "topic": "centripetal force calculation", "question": "A roller coaster is moving with 30 ms-1 on a circular track of radius 30m. the net mass of coaster + passengers is 'm' the centripetal force acting on it is:", "options": ["900m", "m", "450 m", "30m"], "correctIndex": 3, "explanation": "Centripetal force is F = m v^2 / r = m x (30)^2 / 30 = m x 900 / 30 = 30 m. So the centripetal force acting on the coaster and passengers is 30 m.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 131, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2024 Q#131 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q132_132", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 132, "subject": "Physics", "topic": "wave amplitude", "question": "Amplitude in the following figure is given as:", "options": ["2m", "1/2m", "1/4 m", "1m"], "correctIndex": 3, "explanation": "From the plotted wave (distance from equilibrium to peak) the amplitude corresponds to 1 m (option D).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 132, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "UHS 2024 Q#132 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "paper_a_q133_133", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 133, "subject": "Physics", "topic": "nodes in plucked string", "question": "Which one of the following is INCORRECT about the nodes when the string is plucked;", "options": ["Amplitude of vibration is zero", "Do not move along the string", "Produced at the fixed ends of strings", "Distance between consecutive nodes is 1 wavelength"], "correctIndex": 3, "explanation": "The distance between consecutive nodes in a standing wave is half a wavelength, not one full wavelength; therefore option D is incorrect. The other statements describe true properties of nodes (zero amplitude, stationary when the steady standing wave is formed, and they occur at fixed ends for a string with fixed boundaries).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 133, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2024 Q#133 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2024"}, {"id": "paper_a_q134_134", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 134, "subject": "Physics", "topic": "wave terminology", "question": "In transverse waves the portion above the mean level is called:", "options": ["Wave front", "Wave crest", "Wave trough", "Wave length"], "correctIndex": 1, "explanation": "In a transverse wave the portion above the mean level is called the crest. The trough is the portion below the mean level; wavefront and wavelength refer to different concepts.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 134, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "UHS 2024 Q#134 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "paper_a_q135_135", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 135, "subject": "Physics", "topic": "stationary waves", "question": "Which one of the following does not cause stationary waves?", "options": ["Two waves of equal frequency", "Two waves of same speed", "Two waves of unequal amplitude", "Two waves travelling in opposite directions"], "correctIndex": 2, "explanation": "Perfect stationary (standing) waves require two waves of the same frequency, speed and ideally equal amplitude traveling in opposite directions. If the amplitudes are unequal, the resulting pattern will not be a true stationary wave (nodes and antinodes will not be stationary in the ideal sense), so option C does not produce ideal stationary waves.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 135, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "UHS 2024 Q#135 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "paper_a_q136_136", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 136, "subject": "Physics", "topic": "doppler effect", "question": "Select the appropriate Doppler equation when source is approaching the stationary observer where fo is the observed frequency, fs is frequency of source, v is the speed of sound, vs is the speed of source relative to observer", "options": ["fo = v/(v-vs) fs", "fo = v/(v+vs) fs", "fo = v+vs / v fs", "fo = v- vs / v +vs fs"], "correctIndex": 0, "explanation": "For a source moving toward a stationary observer, the observed frequency increases and is given by fo = v/(v - vs) * fs, which is option A. Options B–D correspond to other sign choices or rearrangements and do not describe the approaching-source case correctly.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 136, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "UHS 2024 Q#136 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "paper_a_q137_137", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 137, "subject": "Physics", "topic": "wavelength definition", "question": "The distance between two successive particles which are exactly in the same state of vibration is called", "options": ["Frequency", "Amplitude", "Wavelength", "Time period"], "correctIndex": 2, "explanation": "The distance between successive particles in the same phase of vibration is the wavelength. Frequency, amplitude and time period refer to temporal characteristics or displacement magnitude, not spatial separation between identical-phase points.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 137, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "UHS 2024 Q#137 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "paper_a_q138_138", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 138, "subject": "Physics", "topic": "isothermal process", "question": "During the isothermal process, the temperature", "options": ["remains constant during the initial phase of the process of the process", "remains constant throughout the process", "alters throughout the process", "increases throughout the process"], "correctIndex": 1, "explanation": "An isothermal process, by definition, occurs at constant temperature for the entire process, so option B is correct. Options C and D contradict the definition; option A only states constancy during an initial phase, which is incomplete.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 138, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "UHS 2024 Q#138 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2024"}, {"id": "paper_a_q139_139", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 139, "subject": "Physics", "topic": "adiabatic process", "question": "What is the value of heat energy (Q) in an adiabatic process?", "options": ["+1", "-1", "0", "+2"], "correctIndex": 2, "explanation": "An adiabatic process involves no heat exchange with the surroundings, so the heat transfer Q = 0. The numeric choices appear symbolic; option C corresponds to zero heat transfer.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 139, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2024 Q#139 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "paper_a_q140_140", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 140, "subject": "Physics", "topic": "coulombs law", "question": "The Coulomb's law states", "options": ["Force,between two point charges is inversely proportional to the product of the charges and directly proportional to the square of the distance between them", "Force between two point charges is directly proportional to the product of the charges and inversely proportional to the square of the distance between them", "Force between two point charges is directly proportional to the sum of the charges and inversely proportional to the square of the distance between them", "Force between two point charges is directly proportional to the product of the charges and the square of the distance between them"], "correctIndex": 1, "explanation": "Coulomb's law states that the electrostatic force between two point charges is directly proportional to the product of the charges and inversely proportional to the square of the distance between them, which is option B. The other choices reverse or distort the proportionality.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 140, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "UHS 2024 Q#140 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2024"}, {"id": "paper_a_q141_141", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 141, "subject": "Physics", "topic": "electric potential", "question": "The formula V = W / qo represents", "options": ["Electric intensity", "Electric power", "Electric potential", "Electric field gradient"], "correctIndex": 2, "explanation": "Electric potential V at a point is defined as the work done W per unit positive test charge qo brought from infinity to that point, so V = W/qo is the definition of electric potential (option C).", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 141, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2024 Q#141 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "paper_a_q142_142", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 142, "subject": "Physics", "topic": "capacitance unit", "question": "The S.I unit of capacitance of a capacitor is:", "options": ["Coulomb", "Volt", "Farad", "Ampere"], "correctIndex": 2, "explanation": "The SI unit of capacitance is the farad, defined as one coulomb per volt, so option C is correct. Coulomb, volt and ampere are units of charge, potential and current respectively.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 142, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "UHS 2024 Q#142 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2024"}, {"id": "paper_a_q143_143", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 143, "subject": "Physics", "topic": "electric field between plates", "question": "Electric intensity between two oppositely charge plates in the middle region is_______", "options": ["Non-uniform", "Uniform", "Cannot be predicted", "Variable"], "correctIndex": 1, "explanation": "Between two large, closely spaced, oppositely charged parallel plates, the electric field in the central region is essentially uniform (constant magnitude and direction), so option B is correct. Edge effects near plate boundaries can cause non-uniformities, but the middle region is uniform.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 143, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "UHS 2024 Q#143 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2024"}, {"id": "paper_a_q144_144", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 144, "subject": "Physics", "topic": "electric potential", "question": "Find potential difference in moving 2 C charge which requires 600J of work between two points.", "options": ["1200V", "300V", "150V", "2400V"], "correctIndex": 1, "explanation": "Potential difference (V) equals work done per unit charge: V = W/q. Here V = 600 J / 2 C = 300 V, so the second option is correct.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 144, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2024 Q#144 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "paper_a_q145_145", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 145, "subject": "Physics", "topic": "electric forces", "question": "Which one of the following Is NOT a feature of electric forces?", "options": ["They act on charges", "They act on masses", "They can be attractive", "They can be repulsive"], "correctIndex": 1, "explanation": "Electric forces act on electric charges, not on mass directly. Therefore the statement 'They act on masses' is not a feature of electric forces.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 145, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2024 Q#145 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q146_146", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 146, "subject": "Physics", "topic": "electric current", "question": "A charge of 90 C passes through a wire for 30 seconds. Then the current in the wire will be:", "options": ["3A", "0.3 A", "3 mA", "0.3 mA"], "correctIndex": 0, "explanation": "Electric current I = Q/t. Here I = 90 C / 30 s = 3 A, so the first option is correct.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 146, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "UHS 2024 Q#146 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2024"}, {"id": "paper_a_q147_147", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 147, "subject": "Physics", "topic": "ohms law", "question": "The magnitude of the current in metals is proportional to the potential difference across it as long as temperature of conductor is kept constant is known as:", "options": ["Joule's Law", "Gauss Law", "Ohm's Law", "Ampere's Law"], "correctIndex": 2, "explanation": "Ohm's law states that current is proportional to the potential difference across a conductor at constant temperature (V = IR). Thus 'Ohm's Law' is the correct choice.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 147, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2024 Q#147 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "paper_a_q148_148", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 148, "subject": "Physics", "topic": "resistivity vs dimensions", "question": "When length of copper wire is doubled then resistivity becomes:", "options": ["Double", "Half", "Remains same", "Four times"], "correctIndex": 2, "explanation": "Resistivity is a material property independent of the wire's dimensions. Doubling length does not change resistivity, so 'Remains same' is correct.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 148, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2024 Q#148 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2024"}, {"id": "paper_a_q149_149", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 149, "subject": "Physics", "topic": "resistance temperature dependence", "question": "The resistance of semi-conductor with rise in temperature", "options": ["Increases", "Decreases", "Remain same", "Infinite"], "correctIndex": 1, "explanation": "In semiconductors, increasing temperature generates more charge carriers, so resistance typically decreases with temperature. Therefore 'Decreases' is correct.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 149, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "UHS 2024 Q#149 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2024"}, {"id": "paper_a_q150_150", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 150, "subject": "Physics", "topic": "electrical power", "question": "Volt x Ampere is the measure of;", "options": ["Current", "Volt", "Resistance", "Power"], "correctIndex": 3, "explanation": "Volt × Ampere equals electrical power (P = V×I). Hence 'Power' is the correct answer.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 150, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2024 Q#150 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "paper_a_q151_151", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 151, "subject": "Physics", "topic": "magnetic flux formula", "question": "The formula Φ = B.A represents", "options": ["Electric flux", "Magnetic flux", "Electric flux density", "Gravitational flux"], "correctIndex": 1, "explanation": "Φ = B·A denotes magnetic flux (magnetic field B through area A). So 'Magnetic flux' is correct.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 151, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "UHS 2024 Q#151 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2024"}, {"id": "paper_a_q152_152", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 152, "subject": "Physics", "topic": "magnetic field lines", "question": "Which of the following statement is incorrect for any magnetic field lines?", "options": ["Lines start at north pole and ends at south pole", "Lines never touch or cross each other", "The lines are curved", "Magnetic field is strongest when the lines are farthest"], "correctIndex": 3, "explanation": "Magnetic field strength is greatest where field lines are closest together, not farthest. Thus the fourth statement is incorrect.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 152, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "UHS 2024 Q#152 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2024"}, {"id": "paper_a_q153_153", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 153, "subject": "Physics", "topic": "magnetic flux density unit", "question": "The unit of magnetic flux density is ;", "options": ["Wbm-1", "Wbm", "Wbm-2", "Wb"], "correctIndex": 2, "explanation": "Magnetic flux density (B) has SI unit weber per square metre (Wb m^-2). Option three represents Wb m^-2 and is correct.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 153, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "UHS 2024 Q#153 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2024"}, {"id": "paper_a_q154_154", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 154, "subject": "Physics", "topic": "lenzs law", "question": "The induced current will flow in such a direction so as to oppose the cause that produces it is statement of:", "options": ["Ampere's Law", "Faraday's Law", "Lenz's Law", "Joule's Law"], "correctIndex": 2, "explanation": "Lenz's law states that the direction of induced current opposes the change causing it. Therefore 'Lenz's Law' is the correct choice.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 154, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "UHS 2024 Q#154 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2024"}, {"id": "paper_a_q155_155", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 155, "subject": "Physics", "topic": "ac emf phase", "question": "In an AC generator the emf will be maximum when factor sinωt is equal to", "options": ["Zero", "1", "2", "1 / 2"], "correctIndex": 1, "explanation": "The instantaneous emf in an AC generator is proportional to sin(ωt); it is maximum when sin(ωt) = 1. Thus option two is correct.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 155, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "UHS 2024 Q#155 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2024"}, {"id": "paper_a_q156_156", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 156, "subject": "Physics", "topic": "generators and transformers principle", "question": "Electric generators and transformers are based on the principles of:", "options": ["Coulomb's law", "Faraday's law", "Ampere's law", "Hook's law"], "correctIndex": 1, "explanation": "Generators and transformers operate by electromagnetic induction, described by Faraday's law. Hence 'Faraday's law' is correct.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 156, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "UHS 2024 Q#156 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2024"}, {"id": "paper_a_q157_157", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 157, "subject": "Physics", "topic": "ideal transformer power", "question": "In an ideal transformer:", "options": ["Power input is equal to Power output", "Power input is less than half of the power output", "Power input is greater than Power output", "Power input is more than half of the power output"], "correctIndex": 0, "explanation": "An ideal transformer is lossless, so input electrical power equals output electrical power (neglecting losses). Statements that input is greater or less are false for an ideal (no-loss) device.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 157, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2024 Q#157 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2024"}, {"id": "paper_a_q158_158", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 158, "subject": "Physics", "topic": "rectifier component", "question": "The conversion of A.C into D.C is called rectification and circuit is called rectifier. Which component of electronics acts as a rectifier?", "options": ["Diode", "Transistor", "Transformer", "Inductor"], "correctIndex": 0, "explanation": "A diode allows current to flow preferentially in one direction and is the basic semiconductor device used for rectification. Transistors, transformers and inductors do not by themselves perform the one-way conduction required for rectification.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 158, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "UHS 2024 Q#158 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2024"}, {"id": "paper_a_q159_159", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 159, "subject": "Physics", "topic": "full wave rectification", "question": "Full wave rectification is given by:", "options": ["One diode connected in bridge type arrangements", "Two diodes connected in bridge type arrangements", "Three diodes connected in bridge type arrangement", "Four diodes connected in bridge type arrangements"], "correctIndex": 3, "explanation": "A full-wave bridge rectifier uses four diodes arranged in a bridge so both halves of the AC waveform are converted to DC. One or two diodes cannot form a full bridge; three diodes is not the standard bridge configuration.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 159, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "UHS 2024 Q#159 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "paper_a_q160_160", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 160, "subject": "Physics", "topic": "diode characteristic curve", "question": "A diode characteristic curve is a plot between:", "options": ["Current and time", "Voltage time", "Voltage and current", "Reverse voltage forward voltage"], "correctIndex": 2, "explanation": "The diode I–V (current–voltage) characteristic shows how current varies with applied voltage, so it is a plot of voltage versus current. Plots versus time or the separate phrase 'reverse voltage forward voltage' are not standard descriptor pairs for the characteristic curve.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 160, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "UHS 2024 Q#160 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2024"}, {"id": "paper_a_q161_161", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 161, "subject": "Physics", "topic": "planck constant value", "question": "The value of Planck constant is", "options": ["6.63x10^-34 Js", "6.63x10^34 Js", "6.63x10-34 Js-1", "6.63x10^34 Js-1"], "correctIndex": 0, "explanation": "The accepted value of Planck's constant is approximately 6.63×10^-34 joule-seconds (Js). Options with 10^34 are many orders of magnitude off; the units with s^-1 are incorrect for Planck's constant.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 161, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2024 Q#161 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2024"}, {"id": "paper_a_q162_162", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 162, "subject": "Physics", "topic": "de broglie wavelength", "question": "The de-Broglie wavelength associated with a particle moving at 10^6 m/s and having mass 10^-30 kg", "options": ["6.6x10^-10 m", "1.5x10^9 m", "1.9x10^-5 m", "7.2x10^-8 m"], "correctIndex": 0, "explanation": "λ = h/(mv). Using h ≈ 6.63×10^-34 J·s, m=10^-30 kg, v=10^6 m/s gives λ ≈ 6.63×10^-34 / (10^-24) ≈ 6.63×10^-10 m, matching option A. The other values are many orders of magnitude off.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 162, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "UHS 2024 Q#162 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "paper_a_q163_163", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 163, "subject": "Physics", "topic": "evidence for wave nature of light", "question": "Light propagates through space as a wave is evident by all of the following EXCEPT", "options": ["Interference", "Photoelectric effect", "Diffraction", "Polarization"], "correctIndex": 1, "explanation": "Interference, diffraction and polarization are classical wave phenomena indicative of light's wave nature. The photoelectric effect is explained by the particle (photon) model of light, so it is the exception.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 163, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "UHS 2024 Q#163 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2024"}, {"id": "paper_a_q164_164", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 164, "subject": "Physics", "topic": "hydrogen series uv", "question": "Which series falls in ultra violet region?", "options": ["Lyman", "Brachett", "Pfund", "Paschen"], "correctIndex": 0, "explanation": "The Lyman series (transitions to n=1) lies in the ultraviolet region. Paschen and Pfund are in infrared; 'Brachett' (Brackett) is also infrared.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 164, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2024 Q#164 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2024"}, {"id": "paper_a_q165_165", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 165, "subject": "Physics", "topic": "excitation potential", "question": "The potential through which an electron should be accelerated , so that,on collision it can lift the electron in the atom from its ground state to some higher state is known as", "options": ["Ionization potential", "Excitation potential", "String potential", "Acceleration potential"], "correctIndex": 1, "explanation": "The potential required to raise an atomic electron to a higher bound energy level is the excitation potential. Ionization potential would remove the electron entirely; 'string potential' is not relevant here.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 165, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2024 Q#165 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2024"}, {"id": "paper_a_q166_166", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 166, "subject": "Physics", "topic": "properties of x rays", "question": "Which of the following regarding X Rays is INCORRECT", "options": ["Have higher wavelength than visible light", "They are part of electromagnetic spectrum", "They are highly penetrating in soft body tissues", "They are high energy photons"], "correctIndex": 0, "explanation": "X-rays have much shorter wavelength than visible light, not higher, so statement A is incorrect. The other statements correctly describe X-rays as part of the EM spectrum, highly penetrating, and high-energy photons.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 166, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2024 Q#166 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2024"}, {"id": "paper_a_q167_167", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 167, "subject": "Physics", "topic": "decay constant unit", "question": "The unit of decay constant is ;", "options": ["m", "s", "s-1", "m-1"], "correctIndex": 2, "explanation": "The decay constant has units of inverse time because activity ∝ e^{-λt}; hence its SI unit is s^-1. Options given as length or time themselves are incorrect.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 167, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2024 Q#167 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2024"}, {"id": "paper_a_q168_168", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 168, "subject": "Physics", "topic": "half life formula", "question": "If we have \"No\" number of any radioactive element then after a period of \"n\" half-lives the number of atoms left behind is", "options": ["2^n No", "(½)^n No", "(½ No)^n", "(2No)^n"], "correctIndex": 1, "explanation": "After n half-lives the remaining quantity is No·(1/2)^n. Option A would increase the number; options C and D are not the conventional expression for remaining atoms.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 168, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "UHS 2024 Q#168 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2024"}, {"id": "paper_a_q169_169", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 169, "subject": "Physics", "topic": "somatic effects of radiation", "question": "Which of the following is NOT the Somatic biological effect of radiation?", "options": ["Skin burn", "Loss of hair", "Induction of cancer", "Genes mutation"], "correctIndex": 3, "explanation": "Somatic effects affect the exposed individual (skin burns, hair loss, cancer). Gene mutations affect germ cells and are classified as genetic effects (heritable), not somatic effects.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 169, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2024 Q#169 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2024"}, {"id": "paper_a_q170_170", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 170, "subject": "Physics", "topic": "artificial radioactivity by bombardment", "question": "An artificial radioactive element can be made by bombarding", "options": ["High energy particles on unstable elements", "Low energy particles on unstable elements", "High energy particles on stable elements", "Low energy particles on stable elements"], "correctIndex": 2, "explanation": "Artificial radioisotopes are typically produced by bombarding stable nuclei with high-energy particles (neutrons, protons, alpha particles) to induce nuclear reactions. Bombarding unstable elements is not the usual route to make a new artificial radioactive nuclide.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 170, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "UHS 2024 Q#170 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2024"}, {"id": "paper_a_q171_171", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 171, "subject": "English", "topic": "vocabulary surplus", "question": "What does the word \"SURPLUS\" mean?", "options": ["In excess", "A mathematical term", "Within reach", "Salutation"], "correctIndex": 0, "explanation": "\"Surplus\" means an amount in excess of what is needed or used. The other options do not capture that meaning.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 171, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "UHS 2024 Q#171 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2024"}, {"id": "paper_a_q172_172", "paperTitle": "UHS MDCAT 2024 (Paper A)", "shortTitle": "UHS 2024", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 172, "subject": "English", "topic": "vocabulary ancestor", "question": "What does the word \"ANCESTOR\" mean?", "options": ["Collection of stars", "Branch of astrology", "Forefathers", "Type of receptors"], "correctIndex": 2, "explanation": "\"Ancestor\" refers to a forefather or progenitor. The other choices are unrelated meanings.", "reference": {"sourcePaper": "UHS MDCAT 2024 (Paper A)", "paperCode": "Paper A", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 172, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "UHS 2024 Q#172 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2024"}, {"id": "official_paper_q1_1", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 1, "subject": "Physics", "topic": "isochoric process", "question": "In isochoric process:", "options": ["Pressure is kept constant", "Exchange of heat is zero", "Volume is kept constant", "Temperature is kept constant"], "correctIndex": 2, "explanation": "An isochoric process is defined as one taking place at constant volume. Because volume does not change there is no PV work done, which distinguishes it from isobaric or isothermal processes.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 1, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2023 Q#1 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "official_paper_q2_2", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 2, "subject": "Physics", "topic": "first law energy change", "question": "If 42 J heat is transferred to the system during expansion, what is the change in internal energy when work done is 32 J?", "options": ["74 J", "10 J", "116 J", "106 J"], "correctIndex": 1, "explanation": "Use the first law ΔU = Q − W. With Q = 42 J supplied and W = 32 J done by the system, ΔU = 42 − 32 = 10 J.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 2, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2023 Q#2 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "official_paper_q3_3", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 3, "subject": "Physics", "topic": "first law principle", "question": "The 1st law of thermodynamics is the generalization of the law of conservation of:", "options": ["Mass", "Charge", "Energy", "Momentum"], "correctIndex": 2, "explanation": "The first law of thermodynamics is simply the statement of conservation of energy applied to thermodynamic systems, relating heat and work to change in internal energy.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 3, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "NUMS 2023 Q#3 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2023"}, {"id": "official_paper_q4_4", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 4, "subject": "Physics", "topic": "rc time constant", "question": "While studying charging and discharging of a capacitor, Rc = Resistance × Capacitance is known as:", "options": ["Electrostatic constant", "Time constant", "Dielectric constant", "Proportionality constant"], "correctIndex": 1, "explanation": "For an RC circuit the product τ = R·C is the time constant which sets the exponential charging or discharging timescale of the capacitor. It is therefore called the time constant.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 4, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "NUMS 2023 Q#4 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2023"}, {"id": "official_paper_q5_5", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 5, "subject": "Physics", "topic": "parallel capacitors", "question": "In parallel combination of two capacitors, their equivalent capacitance is equal to:", "options": ["C1 + C2", "1/C1 + 1/C2", "C1C2 / C1 + C2", "2C1C2 / C1 + C2"], "correctIndex": 0, "explanation": "In a parallel connection the potential difference across each capacitor is the same, so their charges add and the equivalent capacitance is C_eq = C1 + C2.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 5, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "NUMS 2023 Q#5 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2023"}, {"id": "official_paper_q6_6", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 6, "subject": "Physics", "topic": "unit of capacitance", "question": "The S.I unit of capacitance of a capacitor is:", "options": ["Coulomb", "Volt", "Farad", "Ampere"], "correctIndex": 2, "explanation": "Capacitance is measured in farads (F), defined as coulomb per volt. Thus the SI unit of capacitance is the farad.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 6, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "NUMS 2023 Q#6 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2023"}, {"id": "official_paper_q7_7", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 7, "subject": "Physics", "topic": "kilowatt hour to joules", "question": "kWh =", "options": ["0.36 × 106 J", "36 × 105 J", "3.6 × 106 J", "0.036 × 105 J"], "correctIndex": 2, "explanation": "1 kW = 1000 J/s and 1 hour = 3600 s, so 1 kWh = 1000 × 3600 J = 3.6 × 10^6 J.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 7, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2023 Q#7 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "official_paper_q8_8", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 8, "subject": "Physics", "topic": "volt ampere power", "question": "Volt × Ampere is the unit of:", "options": ["Current", "Volt", "Resistance", "Power"], "correctIndex": 3, "explanation": "Power in an electrical circuit is P = V·I, so the product of volts and amperes has units of power (watts).", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 8, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2023 Q#8 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "official_paper_q9_9", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 9, "subject": "Physics", "topic": "resistance dependence", "question": "If length of the wire becomes two times to its original value and area becomes one half to its original value, then resistance of the wire becomes:", "options": ["Double", "Four times", "One half", "One forth"], "correctIndex": 1, "explanation": "Resistance R ∝ L/A. Doubling length (×2) and halving cross-sectional area (÷1/2) multiplies R by 2/(1/2) = 4, so the resistance becomes four times larger.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 9, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "NUMS 2023 Q#9 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2023"}, {"id": "official_paper_q10_10", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 10, "subject": "Physics", "topic": "motion in magnetic field parallel entry", "question": "When a charged particle enters the magnetic field parallel, it will:", "options": ["Deflect toward north", "Deflect toward south", "Move straight", "Move in circular path"], "correctIndex": 2, "explanation": "Magnetic force on a charge is q(v × B); if velocity is parallel to the magnetic field the cross product is zero, so no magnetic force acts and the particle continues straight.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 10, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "NUMS 2023 Q#10 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2023"}, {"id": "official_paper_q11_11", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 11, "subject": "Physics", "topic": "magnetic field dimensions", "question": "The dimension of magnetic field strength is same as that of:", "options": ["Magnetic flux", "Magnetic induction", "Work done", "Magnetic force"], "correctIndex": 1, "explanation": "Magnetic field strength and magnetic induction both refer to the same vector quantity B (often called magnetic flux density), so they share the same dimensions and units.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 11, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "NUMS 2023 Q#11 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2023"}, {"id": "official_paper_q12_12", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 12, "subject": "Physics", "topic": "weber unit", "question": "The weber is unit of measure of:", "options": ["Conductance", "Electric current", "Magnetic flux", "Electric flux"], "correctIndex": 2, "explanation": "The weber (Wb) is the SI unit of magnetic flux (or magnetic flux linkage). It measures the amount of magnetic field passing through an area.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 12, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2023 Q#12 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "official_paper_q13_13", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 13, "subject": "Physics", "topic": "lenzs law conservation", "question": "The Lenz's law is also statement of law of conservation of:", "options": ["Charge", "Mass", "Energy", "Pressure"], "correctIndex": 2, "explanation": "Lenz's law gives the direction of induced emf so that the induced effect opposes the change in flux; this opposition ensures no net energy is created, so it is a statement of energy conservation.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 13, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "NUMS 2023 Q#13 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2023"}, {"id": "official_paper_q14_14", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 14, "subject": "Physics", "topic": "fleming right hand rule", "question": "In Fleming's right hand rule, the second finger indicates:", "options": ["Force", "Magnetic field", "Induced current", "Motion"], "correctIndex": 2, "explanation": "In Fleming's right-hand rule (thumb = motion, index = magnetic field, middle = induced current) the middle (second) finger indicates the direction of the induced current. The rule assigns the middle finger to current while the index shows the field.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 14, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2023 Q#14 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "official_paper_q15_15", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 15, "subject": "Physics", "topic": "generator energy conversion", "question": "A current generator is a device that converts:", "options": ["Mechanical energy into electrical energy", "Chemical energy into mechanical energy", "Sound energy into mechanical energy", "Electrical energy into mechanical energy"], "correctIndex": 0, "explanation": "An electrical generator converts mechanical energy (e.g. turbine rotation) into electrical energy by electromagnetic induction, producing an electric current from motion in a magnetic field.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 15, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2023 Q#15 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "official_paper_q16_16", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 16, "subject": "Physics", "topic": "diode rectifier", "question": "A device that converts AC into DC is called:", "options": ["Diode", "Transistor", "Capacitor", "Inductor"], "correctIndex": 0, "explanation": "A diode allows current to flow preferentially in one direction, so it is used to convert alternating current into pulsating direct current; thus a diode acts as a rectifying element.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 16, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "NUMS 2023 Q#16 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2023"}, {"id": "official_paper_q17_17", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 17, "subject": "Physics", "topic": "rectification definition", "question": "The conversion of alternating current into direct current is called:", "options": ["Amplification", "Rectification", "Magnification", "Resolution"], "correctIndex": 1, "explanation": "The technical term for converting alternating current into direct current is rectification; devices that perform this are called rectifiers.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 17, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "NUMS 2023 Q#17 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2023"}, {"id": "official_paper_q18_18", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 18, "subject": "Physics", "topic": "full wave bridge rectifier", "question": "In full wave rectification, ________ diodes are used.", "options": ["1", "2", "3", "4"], "correctIndex": 3, "explanation": "A full-wave bridge rectifier uses four diodes arranged in a bridge to invert the negative half-cycles, so the correct number of diodes required is four.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 18, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "NUMS 2023 Q#18 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2023"}, {"id": "official_paper_q19_19", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 19, "subject": "Physics", "topic": "half life definition", "question": "The time taken for half the number of atoms of radioactive isotopes to disintegrate is called:", "options": ["Average life", "Mean life", "Total life", "Half life"], "correctIndex": 3, "explanation": "Half-life is defined as the time required for half the nuclei in a radioactive sample to decay; it is the standard measure of radioactive decay rate.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 19, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "NUMS 2023 Q#19 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2023"}, {"id": "official_paper_q20_20", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 20, "subject": "Physics", "topic": "half life calculation", "question": "A 32g radioactive element decays and remains 2g after 60 days. What is half-life of this radioactive element?", "options": ["2 days", "6 days", "10 days", "15 days"], "correctIndex": 3, "explanation": "If 32 g reduces to 2 g then (1/2)^n = 2/32 = 1/16, so n = 4 half-lives. Since that took 60 days, one half-life is 60/4 = 15 days.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 20, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "NUMS 2023 Q#20 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2023"}, {"id": "official_paper_q21_21", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 21, "subject": "Physics", "topic": "acceleration direction signs", "question": "If the car is slowing down along negative x axis then acceleration will be along:", "options": ["Positive x Axis", "Negative x Axis", "Positive y Axis", "Negative y Axis"], "correctIndex": 0, "explanation": "If the car is moving along negative x and slowing down, its acceleration must be opposite the velocity (it points toward positive x) because acceleration reduces the speed when directed opposite to velocity.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 21, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2023 Q#21 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "official_paper_q22_22", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 22, "subject": "Physics", "topic": "instantaneous velocity direction", "question": "The instantaneous velocity along the curved path is:", "options": ["Along the tangent", "Perpendicular to the slope", "Parallel to the radius", "Anti-parallel to the radius"], "correctIndex": 0, "explanation": "Instantaneous velocity at a point on a curved path is tangent to the path at that point, since velocity is the time derivative of position and points in the direction of motion.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 22, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2023 Q#22 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "official_paper_q23_23", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 23, "subject": "Physics", "topic": "elastic collision conservation laws", "question": "In perfectly elastic collision:", "options": ["Only momentum is conserved", "Only total energy is conserved", "Only kinetic energy is conserved", "Momentum, kinetic energy and total energy, all are conserved"], "correctIndex": 3, "explanation": "In a perfectly elastic collision both linear momentum and kinetic energy are conserved; total energy is always conserved as well (kinetic plus any other forms), so all listed conservation laws hold.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 23, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2023 Q#23 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "official_paper_q24_24", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 24, "subject": "Physics", "topic": "displacement time slope", "question": "The slope of a displacement-time graph is equal to:", "options": ["Velocity", "Displacement", "Acceleration", "Distance"], "correctIndex": 0, "explanation": "The slope of a displacement–time graph (derivative of displacement with respect to time) is velocity, so the slope directly gives the instantaneous velocity.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 24, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2023 Q#24 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "official_paper_q25_25", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 25, "subject": "Physics", "topic": "projectile range complementary angles", "question": "Range of a projectile on a horizontal plane is same for the following pair of angle:", "options": ["15 & 30", "60 & 20", "75 & 15", "50 & 25"], "correctIndex": 2, "explanation": "Projectile range depends on sin(2θ), so angles whose sum is 90° (complementary) give the same 2θ and therefore the same range; 75° and 15° are complementary and produce equal ranges.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 25, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2023 Q#25 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "official_paper_q26_26", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 26, "subject": "Physics", "topic": "impulse and momentum", "question": "The product of force and time is equal to:", "options": ["Angular momentum", "Force", "Change in momentum", "Velocity"], "correctIndex": 2, "explanation": "Impulse is defined as the product of force and the time over which it acts (FΔt). By Newton’s second law in impulse form this equals the change in momentum (Δp) of the object, so F·t = Δp.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 26, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2023 Q#26 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "official_paper_q27_27", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 27, "subject": "Physics", "topic": "projectile vertical velocity", "question": "At what point during the motion of projectile its vertical component of velocity is zero?", "options": ["Point of projection", "Landing point", "Highest point", "Just before landing"], "correctIndex": 2, "explanation": "In projectile motion the vertical component of velocity decreases under gravity, becomes zero at the highest point, and then reverses direction. Therefore the vertical velocity is zero exactly at the maximum height.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 27, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2023 Q#27 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "official_paper_q28_28", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 28, "subject": "Physics", "topic": "potential energy and work", "question": "A projectile has 1 J of PE. What is the work done in terms of height?", "options": ["1 J", "10 J", "0 J", "0.1 J"], "correctIndex": 2, "explanation": "Potential energy is a state function representing stored energy due to height; if the question refers to work done for no change in height then no work is done (Δy=0 → W=0). Thus having 1 J of PE does not imply work is being done unless there is a displacement in height, so the work in that context is 0 J.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 28, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2023 Q#28 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "official_paper_q29_29", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 29, "subject": "Physics", "topic": "power definition", "question": "Power is dot product of:", "options": ["Force and displacement", "Force and velocity", "Force and time", "Work and time"], "correctIndex": 1, "explanation": "Instantaneous power is the rate of doing work and can be written as the dot product of force and velocity: P = F·v. This follows because power = F·dx/dt = F·v.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 29, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2023 Q#29 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "official_paper_q30_30", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 30, "subject": "Physics", "topic": "work from force displacement graph", "question": "The area under force-displacement graph gives:", "options": ["Displacement", "Power", "Work", "Acceleration"], "correctIndex": 2, "explanation": "Work done by a force over a displacement is the integral of force with respect to displacement. Graphically the area under a force vs. displacement curve equals the work.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 30, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2023 Q#30 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "official_paper_q31_31", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 31, "subject": "Physics", "topic": "kinetic energy velocity dependence", "question": "A body of mass 'm' is moving with velocity 'v'. After a short interval of time its velocity becomes double. How many times its K.E will increase or decrease?", "options": ["2 time increased", "2 time decreased", "4 time increased", "4 time decreased"], "correctIndex": 2, "explanation": "Kinetic energy scales as v^2 (KE = 1/2 mv^2). If the velocity doubles (v → 2v), KE increases by (2^2)=4, so it becomes four times larger.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 31, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2023 Q#31 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "official_paper_q32_32", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 32, "subject": "Physics", "topic": "radian degree conversion", "question": "The relation between radian and degree is:", "options": ["1 rad = 57.3°", "1° = 57.3 rad", "1 rad = 1°", "1° = π rad"], "correctIndex": 0, "explanation": "One radian is the angle subtended by an arc equal to the radius; converting to degrees gives 1 rad = 180/π ≈ 57.2958°, commonly rounded to 57.3°.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 32, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2023 Q#32 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "official_paper_q33_33", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 33, "subject": "Physics", "topic": "centripetal acceleration", "question": "In case of centripetal force the value of instantaneous acceleration is given by:", "options": ["ac = v/r", "ac = v2/r", "ac = vr", "ac = v2r"], "correctIndex": 1, "explanation": "Centripetal (instantaneous) acceleration for motion in a circle at speed v and radius r points toward the center with magnitude a_c = v^2/r. This is the standard relation for uniform circular motion.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 33, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2023 Q#33 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "official_paper_q34_34", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 34, "subject": "Physics", "topic": "rpm to rad per second", "question": "An electric motor turns at 400 revolutions per minute. Its angular velocity in rad/s will be:", "options": ["20π/3", "30π/3", "40π/3", "30π/4"], "correctIndex": 2, "explanation": "400 revolutions per minute = 400/60 = 20/3 revolutions per second. Multiply by 2π rad per revolution: ω = (20/3)·2π = 40π/3 rad/s, which matches the given answer.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 34, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2023 Q#34 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "official_paper_q35_35", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 35, "subject": "Physics", "topic": "rolling motion moments of inertia", "question": "A disc, a hoop and a sphere are rolling down from an inclined plane simultaneously. Which object will reach at the bottom first?", "options": ["Hoop", "Disc", "Sphere", "All at the same time"], "correctIndex": 2, "explanation": "For rolling objects released from rest the translational acceleration depends on their moment of inertia; objects with smaller rotational inertia (relative to MR^2) accelerate faster. A solid sphere (I=2/5MR^2) has the smallest effective inertia among hoop, disc and sphere, so it reaches the bottom first.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 35, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "NUMS 2023 Q#35 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2023"}, {"id": "official_paper_q36_36", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 36, "subject": "Physics", "topic": "centripetal force omega", "question": "The centripetal force formula is:", "options": ["Fc = mω2", "Fc = mrω", "Fc = mrω2", "Fc = mr2ω"], "correctIndex": 2, "explanation": "Using angular speed ω, centripetal force on a mass m at radius r is F_c = m r ω^2 because v = rω and F_c = m v^2/r = m r ω^2. Thus Fc = mrω^2 is the correct expression.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 36, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2023 Q#36 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "official_paper_q37_37", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 37, "subject": "Physics", "topic": "speed of sound pressure dependence", "question": "With increase in pressure, the speed of sound will:", "options": ["Increase", "Decrease", "First increase then decrease", "Remain the same"], "correctIndex": 3, "explanation": "In an ideal gas at fixed temperature and composition the speed of sound depends on temperature (and molecular properties) but not on hydrostatic pressure, so increasing pressure alone (without changing temperature or medium) does not change sound speed. Therefore it remains essentially the same.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 37, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "NUMS 2023 Q#37 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2023"}, {"id": "official_paper_q38_38", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 38, "subject": "Physics", "topic": "wave terminology", "question": "In transverse waves, the portion above the mean level is called:", "options": ["Wave front", "Wave crest", "Wave trough", "Wave length"], "correctIndex": 1, "explanation": "In a transverse wave the crest is the region where the medium is displaced maximum above the equilibrium (mean) level, while the trough is the maximum below. Hence the portion above the mean is called the wave crest.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 38, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "NUMS 2023 Q#38 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2023"}, {"id": "official_paper_q39_39", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 39, "subject": "Physics", "topic": "amplitude definition", "question": "The maximum displacement of particles of a medium, on either side of the mean position of a wave, is called:", "options": ["Wavelength", "Frequency", "Amplitude", "Crest"], "correctIndex": 2, "explanation": "Amplitude is defined as the maximum displacement of particles of the medium from the mean position on either side. It measures the peak displacement and is distinct from wavelength or frequency.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 39, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2023 Q#39 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "official_paper_q40_40", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 40, "subject": "Biology", "topic": "sodium gradient", "question": "Na+ (sodium ions) are nearly ________ times greater in fluid outside the cell than inside:", "options": ["10", "30", "2", "3"], "correctIndex": 0, "explanation": "Typical animal cells maintain a steep Na+ gradient with extracellular Na+ roughly an order of magnitude higher than intracellular (≈10:1), maintained by the Na+/K+ ATPase. So sodium concentration outside is about ten times greater than inside.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 40, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2023 Q#40 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "official_paper_q41_41", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 41, "subject": "Biology", "topic": "oxytocin and labour", "question": "Which hormone induces labour pains?", "options": ["Estrogen", "Oxytocin", "Progesterone", "LH"], "correctIndex": 1, "explanation": "Oxytocin, released from the posterior pituitary, stimulates uterine muscle contractions and is the principal hormone that induces and strengthens labor pains. Estrogen and other hormones modulate sensitivity, but oxytocin is the direct contractile trigger.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 41, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2023 Q#41 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2023"}, {"id": "official_paper_q42_42", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 42, "subject": "Biology", "topic": "adh and osmoregulation", "question": "Hormone secreted in bulk due to decreased water content of blood is:", "options": ["Anti-Diuretic Hormone (ADH)", "Oxytocin", "Glucagon", "Thyroxin"], "correctIndex": 0, "explanation": "A decrease in blood water (increased plasma osmolarity) is sensed by osmoreceptors and causes release of antidiuretic hormone (ADH) from the posterior pituitary. ADH acts on the kidneys to conserve water, so ADH is secreted in bulk under dehydration.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 42, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2023 Q#42 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2023"}, {"id": "official_paper_q43_43", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 43, "subject": "Biology", "topic": "neurotransmitter synthesis location", "question": "The site of production of neurotransmitters is:", "options": ["Postsynaptic neuron", "Presynaptic neuron", "Synaptic cleft", "Dendrite"], "correctIndex": 1, "explanation": "Neurotransmitters are synthesized in the presynaptic neuron (either in the cell body and transported down the axon or locally in the terminal) and packaged into vesicles for release. They are not produced in the synaptic cleft or in the postsynaptic cell.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 43, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2023 Q#43 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "official_paper_q44_44", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 44, "subject": "Biology", "topic": "endorphin production", "question": "Endorphins are produced in:", "options": ["Brain", "Adrenal gland", "Stomach", "Thymus"], "correctIndex": 0, "explanation": "Endorphins are endogenous opioid peptides produced primarily in the central nervous system (brain and pituitary) where they modulate pain and reward. They are not secreted by peripheral organs like thymus or stomach as their main source.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 44, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2023 Q#44 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "official_paper_q45_45", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 45, "subject": "Biology", "topic": "testosterone functions", "question": "The hormone responsible for production of sperm cells and male secondary sexual characteristics is:", "options": ["Estrogen", "Progesterone", "Testosterone", "Thyroxin"], "correctIndex": 2, "explanation": "Testosterone, produced mainly by Leydig cells in the testes, drives spermatogenesis and the development/maintenance of male secondary sexual characteristics, so it is the hormone responsible for both functions.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 45, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2023 Q#45 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "official_paper_q46_46", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 46, "subject": "Biology", "topic": "leydig cell function", "question": "Leydig cells are responsible for:", "options": ["Testosterone production", "FSH production", "Sperm production", "Testosterone inhibition"], "correctIndex": 0, "explanation": "Leydig (interstitial) cells in the testis synthesize and secrete testosterone in response to LH stimulation. They are the primary source of testicular androgen production, not spermatozoa themselves.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 46, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2023 Q#46 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "official_paper_q47_47", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 47, "subject": "Biology", "topic": "fsh stimulation of estrogen", "question": "The estrogen hormone secretion during the oogenesis is stimulated by:", "options": ["Leutinizing Hormone", "Inhibin Hormone", "Follicle Stimulating Hormone", "Testosterone Hormone"], "correctIndex": 2, "explanation": "Follicle-stimulating hormone (FSH) stimulates ovarian follicles and granulosa cells to produce estrogen during oogenesis. FSH-driven follicle development increases estrogen secretion as the follicle matures.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 47, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2023 Q#47 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2023"}, {"id": "official_paper_q48_48", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 48, "subject": "Biology", "topic": "pituitary regulation of menstrual cycle", "question": "Which of the following hormones of the pituitary gland regulate the menstrual cycle?", "options": ["Follicle Stimulating Hormone and estrogen", "Luteinizing hormone and estrogen", "Follicle Stimulating Hormone and Luteinizing hormone", "Estrogen and progesterone"], "correctIndex": 2, "explanation": "The pituitary gonadotropins FSH and LH regulate follicle development, ovulation and corpus luteum function and therefore are the primary pituitary hormones controlling the menstrual cycle. Estrogen and progesterone are ovarian hormones, not pituitary.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 48, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2023 Q#48 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2023"}, {"id": "official_paper_q49_49", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 49, "subject": "Biology", "topic": "y linked inheritance", "question": "Which of the following traits is transmitted directly from an affected father to only his son?", "options": ["Autosomal", "X-linked", "Y-linked", "X-Y linked"], "correctIndex": 2, "explanation": "Y-linked traits are carried on the Y chromosome and thus are transmitted directly from an affected father to all his sons but never to daughters. That pattern (father→only sons) is diagnostic of Y-linked inheritance.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 49, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "NUMS 2023 Q#49 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2023"}, {"id": "official_paper_q50_50", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 50, "subject": "Biology", "topic": "homozygous definition", "question": "When both the alleles of a gene pair are same, the organism is said to be:", "options": ["Heterozygous", "Genotype", "Homozygous", "Phenotype"], "correctIndex": 2, "explanation": "An organism is homozygous at a gene locus when both alleles are the same (either both dominant or both recessive). Heterozygous describes two different alleles, while phenotype/genotype refer to trait expression and genetic constitution respectively.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 50, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "NUMS 2023 Q#50 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2023"}, {"id": "official_paper_q51_51", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 51, "subject": "Biology", "topic": "endosymbiotic theory", "question": "This theory says that 'mitochondria and chloroplasts are, in effect, ancient bacteria which now live inside the larger cells'?", "options": ["Darwin's theory of evolution", "Lamarckism", "Neo-darwinism", "Endosymbiotic theory"], "correctIndex": 3, "explanation": "The endosymbiotic theory proposes that mitochondria and chloroplasts originated as free-living prokaryotes that were engulfed by ancestral eukaryotic cells and became permanent intracellular symbionts. Evidence supporting this includes their double membranes, circular DNA, and bacterial-type ribosomes, which distinguish this idea from Darwinian or Lamarckian theories of evolution.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 51, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2023 Q#51 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "official_paper_q52_52", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 52, "subject": "Biology", "topic": "analogous organs", "question": "The organs which are similar in function but differ in structure are called:", "options": ["Analogous organs", "Homologous organs", "Convergent organs", "Divergent organs"], "correctIndex": 0, "explanation": "Analogous organs perform similar functions but have different structural origins, arising via convergent evolution (for example, wings of insects and wings of birds). Homologous organs, by contrast, have similar structure from a common ancestor even if their functions differ.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 52, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2023 Q#52 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "official_paper_q53_53", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 53, "subject": "Biology", "topic": "antibody effector mechanisms", "question": "Which may NOT be a mode of action of an antibody?", "options": ["Neutralizing an antigen", "Precipitating an antigen", "Secretion of cytokines", "Enhancing phagocytosis"], "correctIndex": 2, "explanation": "Antibodies can neutralize antigens, precipitate or agglutinate them, and opsonize to enhance phagocytosis. They do not themselves secrete cytokines-cytokine production is a function of immune cells such as T cells and macrophages rather than of the antibody molecule.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 53, "syllabusUnit": "Unit 7: Human Physiology - Immunity", "pmdcTopic": "Innate & Adaptive Immunity, Immunoglobulins and Vaccines", "textbookCitation": "PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14", "citationString": "NUMS 2023 Q#53 | Unit 7: Human Physiology - Immunity | PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14"}, "year": "2023"}, {"id": "official_paper_q54_54", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 54, "subject": "Biology", "topic": "pepsinogen activation", "question": "Pepsinogen is converted into its active form pepsin by:", "options": ["Proteolytic enzyme action", "Dissolving in mucus", "Hormonal action", "Hydrochloric acid"], "correctIndex": 3, "explanation": "Pepsinogen is an inactive zymogen secreted by chief cells and is converted to active pepsin by the acidic environment of the stomach, specifically hydrochloric acid produced by parietal cells. Proteolytic enzymes activate some zymogens, but pepsinogen activation in vivo is driven by HCl.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 54, "syllabusUnit": "Unit 5: Human Physiology - Digestion & Nutrition", "pmdcTopic": "Human Digestive System & Absorption Mechanisms", "textbookCitation": "PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12", "citationString": "NUMS 2023 Q#54 | Unit 5: Human Physiology - Digestion & Nutrition | PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12"}, "year": "2023"}, {"id": "official_paper_q55_55", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 55, "subject": "Biology", "topic": "intrinsic factor secretion", "question": "Intrinsic factor is secreted by:", "options": ["Pancreas", "Liver", "Stomach", "Duodenum"], "correctIndex": 2, "explanation": "Intrinsic factor is produced by the parietal cells of the stomach and is essential for vitamin B12 absorption in the ileum. It is not a product of the pancreas, liver, or duodenum.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 55, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2023 Q#55 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "official_paper_q56_56", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 56, "subject": "Biology", "topic": "lymphocytes role", "question": "The cells which play very important role in developing immunity are:", "options": ["Monocytes", "Neutrophils", "Lymphocytes", "Thrombocytes"], "correctIndex": 2, "explanation": "Lymphocytes (B and T cells) are central to adaptive immunity: B cells produce specific antibodies and T cells mediate cell-mediated responses. While monocytes and neutrophils are important in innate defenses, long-term and specific immunity depends on lymphocytes.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 56, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2023 Q#56 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "official_paper_q57_57", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 57, "subject": "Biology", "topic": "carbohydrate digestion oral", "question": "Digestion of which food component starts from oral cavity?", "options": ["Proteins", "Fats", "Carbohydrates", "Vitamins"], "correctIndex": 2, "explanation": "Carbohydrate digestion begins in the oral cavity where salivary amylase (ptyalin) starts breaking starch into smaller sugars. Proteins and fats are not significantly digested in the mouth.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 57, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2023 Q#57 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "official_paper_q58_58", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 58, "subject": "Biology", "topic": "vaccination artificial active immunity", "question": "Vaccination is an example of:", "options": ["Natural passive immunity", "Natural active immunity", "Acquired/Artificial active immunity", "Acquired/Artificial passive immunity"], "correctIndex": 2, "explanation": "Vaccination exposes the immune system to an antigen in a controlled way to stimulate the body's own adaptive immune response and memory formation, which is artificial (man-made) and active (host produces the response). Passive immunity would involve transfer of preformed antibodies.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 58, "syllabusUnit": "Unit 7: Human Physiology - Immunity", "pmdcTopic": "Innate & Adaptive Immunity, Immunoglobulins and Vaccines", "textbookCitation": "PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14", "citationString": "NUMS 2023 Q#58 | Unit 7: Human Physiology - Immunity | PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14"}, "year": "2023"}, {"id": "official_paper_q59_59", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 59, "subject": "Biology", "topic": "aorta origin", "question": "The heart chamber from where aorta originates:", "options": ["Left ventricle", "Right ventricle", "Left atrium", "Right atrium"], "correctIndex": 0, "explanation": "The aorta arises from the left ventricle of the heart, which pumps oxygenated blood into the systemic circulation. The right ventricle pumps to the pulmonary artery, and atria receive blood rather than giving rise to the aorta.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 59, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2023 Q#59 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2023"}, {"id": "official_paper_q60_60", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 60, "subject": "Biology", "topic": "cartilaginous joints", "question": "Pubic symphysis and inter vertebral disc are the example of:", "options": ["Fibrous joints", "Synovial joints", "Cartilaginous joints", "Gliding joints"], "correctIndex": 2, "explanation": "Pubic symphysis and intervertebral discs are examples of cartilaginous joints where bones are joined by cartilage, allowing limited movement and cushioning. They are not fibrous (immovable) or synovial (freely movable with a joint cavity).", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 60, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "NUMS 2023 Q#60 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2023"}, {"id": "official_paper_q61_61", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 61, "subject": "Biology", "topic": "cartilage vascularity", "question": "Cartilage is more difficult to heal than bone because cartilage:", "options": ["Lacks vascular supply", "Lacks mineral deposits in matrix", "Has less number of cells deep down", "Lacks protein in matrix"], "correctIndex": 0, "explanation": "Cartilage heals poorly because it lacks a vascular blood supply, so nutrients and reparative cells cannot rapidly reach damaged areas. Bone is well vascularized, which allows efficient repair and remodeling.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 61, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "NUMS 2023 Q#61 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2023"}, {"id": "official_paper_q62_62", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 62, "subject": "Biology", "topic": "cardiac muscle nuclei", "question": "Which feature is absent from cardiac muscles?", "options": ["Intercalated disc", "Multinucleate cells", "Light and dark bands", "Contractile sarcomeres"], "correctIndex": 1, "explanation": "Cardiac muscle fibers are typically uninucleate (one central nucleus) rather than multinucleate, which is a feature of skeletal muscle fibers. Cardiac muscle does have intercalated discs, striations (light and dark bands), and sarcomeres for contraction.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 62, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2023 Q#62 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2023"}, {"id": "official_paper_q63_63", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 63, "subject": "Biology", "topic": "sarcoplasmic reticulum calcium storage", "question": "Sarcoplasmic reticulum of muscle fibers is mainly responsible for:", "options": ["Calcium storage", "Protein synthesis", "Lipid metabolism", "Storing cell wastes"], "correctIndex": 0, "explanation": "The sarcoplasmic reticulum is a specialized endoplasmic reticulum in muscle cells whose main role is to store and release calcium ions to regulate contraction. It is not primarily involved in protein synthesis or lipid metabolism.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 63, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2023 Q#63 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2023"}, {"id": "official_paper_q64_64", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 64, "subject": "Biology", "topic": "synapse definition", "question": "The junction between two neurons is:", "options": ["Impulse", "Synapse", "Axon", "Cleft"], "correctIndex": 1, "explanation": "The synapse is the specialized junction between two neurons (or a neuron and an effector cell) where nerve impulses are transmitted chemically or electrically. 'Axon' and 'cleft' are parts of the neuronal structure but do not name the junction itself.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 64, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2023 Q#64 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2023"}, {"id": "official_paper_q65_65", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 65, "subject": "Biology", "topic": "steroid hormone example", "question": "Which hormone is chemically a steroid?", "options": ["ADH", "Thyroxin", "Cortisone", "Insulin"], "correctIndex": 2, "explanation": "Cortisone is a steroid hormone derived from cholesterol and has the characteristic four-ring steroid structure, unlike peptide hormones (ADH, insulin) or iodine-containing thyroxine. Therefore cortisone is the correct steroid example.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 65, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2023 Q#65 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2023"}, {"id": "official_paper_q66_66", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 66, "subject": "Biology", "topic": "hypoparathyroidism hypocalcemia", "question": "Under activity of parathyroid glands causes a drop in blood of:", "options": ["Mg2+", "Na+", "K+", "Ca2+"], "correctIndex": 3, "explanation": "Parathyroid hormone raises blood calcium by promoting bone resorption, increasing renal reabsorption of calcium, and activating vitamin D; underactivity of the parathyroids therefore causes hypocalcemia (low Ca2+). It does not primarily control Na+ or K+ levels.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 66, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2023 Q#66 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2023"}, {"id": "official_paper_q67_67", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 67, "subject": "Biology", "topic": "collagen matrix bone cartilage", "question": "Which of the following protein establishes the matrix of bone and cartilage?", "options": ["Elastin", "Keratin", "Collagen", "Histone"], "correctIndex": 2, "explanation": "Collagen is the main fibrous protein that forms the organic matrix of bone and cartilage, providing tensile strength and framework for mineral deposition. Elastin and keratin serve other structural roles and histones are nuclear proteins, so they are not correct here.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 67, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2023 Q#67 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "official_paper_q68_68", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 68, "subject": "Biology", "topic": "non competitive inhibition allosteric", "question": "Non-competitive inhibitors react with enzymes at:", "options": ["Allosteric site", "Active site", "Passive site", "Regulatory site"], "correctIndex": 0, "explanation": "Non-competitive inhibitors bind to an allosteric site distinct from the active site and change the enzyme’s conformation, reducing catalytic activity regardless of substrate concentration. This differs from competitive inhibitors, which occupy the active site itself.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 68, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2023 Q#68 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "official_paper_q69_69", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 69, "subject": "Biology", "topic": "enzyme optimal temperature human", "question": "Most enzymes work the best at the following temperature:", "options": ["30°C", "40°C", "50°C", "20°C"], "correctIndex": 1, "explanation": "Most human enzymes have optimal activity around body temperature; the answer given (40°C) is slightly above normal body temperature but is commonly used as the closest choice on exams to indicate warm, physiologically optimal conditions. Much higher temperatures denature enzymes while much lower temperatures reduce kinetic activity.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 69, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2023 Q#69 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "official_paper_q70_70", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 70, "subject": "Biology", "topic": "enzyme denaturation temperature", "question": "In term of enzyme action, 'maximum temperature' refers to a temperature at which:", "options": ["Enzymes start to denature", "Enzymes start to re-nature", "Enzymes work best", "Enzymes are reactivated"], "correctIndex": 0, "explanation": "The term 'maximum temperature' for enzyme action typically refers to the point above which enzymes begin to lose their tertiary structure and denature, causing activity to fall off sharply. It does not mean enzymes are reactivated or renatured at that temperature.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 70, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2023 Q#70 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "official_paper_q71_71", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 71, "subject": "Biology", "topic": "competitive inhibition", "question": "_______ reduce the enzymes productivity by blocking the substrate from entering into the active site due to similar shapes:", "options": ["Competitive inhibitors", "Non-competitive inhibitors", "Co-enzymes", "Activators"], "correctIndex": 0, "explanation": "Competitive inhibitors resemble the substrate and compete for the enzyme's active site, preventing substrate binding and thereby reducing enzyme activity; increasing substrate concentration can overcome this inhibition. Non-competitive inhibitors bind elsewhere and cannot be outcompeted by substrate.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 71, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2023 Q#71 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "official_paper_q72_72", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 72, "subject": "Biology", "topic": "photosystem i p700 oxidation", "question": "When light falls on P-700, which event is likely to occur?", "options": ["It induces photolysis", "Gains Hydrogen", "Accept electrons", "It is oxidised"], "correctIndex": 3, "explanation": "When light excites P700 (the reaction center chlorophyll of photosystem I), it donates an electron to the electron acceptor chain and thus becomes oxidized. It does not gain hydrogen; rather the electron loss is later replenished by electrons from plastocyanin.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 72, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2023 Q#72 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "official_paper_q73_73", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 73, "subject": "Biology", "topic": "light reaction products for calvin cycle", "question": "Which of the following molecules are released after completion of light reaction and then utilized in the dark reaction of photosynthesis?", "options": ["ATP and NADP+", "ADP and NADP+", "ADP and NADPM", "ATP and NADPH"], "correctIndex": 3, "explanation": "The light reactions produce ATP and reduced NADPH (NADPH) which are then used as energy and reducing power in the Calvin cycle (dark reactions). NADP+ and ADP are the oxidized/adenosine forms before they are reduced or phosphorylated in the light reactions.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 73, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "NUMS 2023 Q#73 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2023"}, {"id": "official_paper_q74_74", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 74, "subject": "Biology", "topic": "light reaction endproducts", "question": "Which are the end products of light reactions of photosynthesis?", "options": ["ATP and NADPH", "ATP and glucose", "Glucose and NADP", "ATP and water"], "correctIndex": 0, "explanation": "The primary end products of the light-dependent reactions are ATP and NADPH, which store energy and reducing equivalents for use in the Calvin cycle; glucose is produced later in the dark reactions. Water is consumed (photolysis) rather than being an end product.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 74, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "NUMS 2023 Q#74 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2023"}, {"id": "official_paper_q75_75", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 75, "subject": "Biology", "topic": "atp synthesis thylakoid", "question": "Synthesis of ATP during photosynthesis takes place at the region:", "options": ["Stroma", "Thylakoid", "Matrix", "Cisternae"], "correctIndex": 1, "explanation": "Photophosphorylation (ATP synthesis) occurs across the thylakoid membrane: protons build up inside the thylakoid lumen and flow back through ATP synthase in the thylakoid membrane to produce ATP. The stroma is the site of the Calvin cycle but the membrane is where the proton gradient is established.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 75, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2023 Q#75 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "official_paper_q76_76", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 76, "subject": "Biology", "topic": "virion definition", "question": "The complete, mature and infectious virus particle is known as:", "options": ["Venome", "Genome", "Virion", "Capsid"], "correctIndex": 2, "explanation": "A virion is the fully assembled, infectious form of a virus particle consisting of the genome enclosed in a capsid (and envelope if present). The other choices name components (genome, capsid) or are not standard terms.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 76, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "NUMS 2023 Q#76 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2023"}, {"id": "official_paper_q77_77", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 77, "subject": "Biology", "topic": "virus obligate parasites", "question": "All viruses are:", "options": ["Autotrophs", "Heterotrophs", "Parasites", "Predators"], "correctIndex": 2, "explanation": "Viruses cannot carry out independent metabolism or reproduce without hijacking a host cell, so they are obligate intracellular parasites. They are not autotrophs, heterotrophs or predators in the usual biological sense.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 77, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "NUMS 2023 Q#77 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2023"}, {"id": "official_paper_q78_78", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 78, "subject": "Biology", "topic": "capsule virulence", "question": "_______ increases the pathogenecity of bacteria:", "options": ["Capsule", "Cell wall", "Slime", "Cell membrane"], "correctIndex": 0, "explanation": "Bacterial capsules (polysaccharide layers) enhance pathogenicity by protecting bacteria from phagocytosis and desiccation and aiding adhesion to host tissues. Cell wall, slime and membrane have roles but the capsule is the classic virulence factor listed here.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 78, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "NUMS 2023 Q#78 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2023"}, {"id": "official_paper_q79_79", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 79, "subject": "Biology", "topic": "mycoplasma smallest bacteria", "question": "The smallest known bacteria belong to the genus:", "options": ["Mycoplasma", "Streptococcus", "Escherichia", "Bacillus"], "correctIndex": 0, "explanation": "Mycoplasma species are among the smallest free-living bacteria and characteristically lack a rigid cell wall, distinguishing them from genera like Escherichia or Bacillus. The other options are larger, walled bacteria.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 79, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "NUMS 2023 Q#79 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2023"}, {"id": "official_paper_q80_80", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 80, "subject": "Biology", "topic": "mesenteric venous drainage", "question": "Mesenteric veins drain the blood from:", "options": ["Liver", "Large intestine", "Stomach", "Gall bladder"], "correctIndex": 1, "explanation": "Mesenteric veins drain blood from the intestines; the inferior mesenteric vein specifically drains the large intestine (colon) into the portal system. The liver receives blood via the portal vein but is not drained by 'mesenteric veins' directly.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 80, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2023 Q#80 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2023"}, {"id": "official_paper_q81_81", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 81, "subject": "Biology", "topic": "secondary cell wall location", "question": "Secondary cell wall in plants is present:", "options": ["Outer to primary cell wall", "In between two primary cell walls", "Between the primary cell wall and plasma membrane", "Inner to plasma membrane"], "correctIndex": 2, "explanation": "In plant cells the secondary cell wall is deposited internal to the primary cell wall, immediately adjacent to the plasma membrane. It is not outside the primary wall or between two primary walls.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 81, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2023 Q#81 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "official_paper_q82_82", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 82, "subject": "Biology", "topic": "peptidoglycan prokaryotes", "question": "What distinguishes Prokaryotic cell wall from Fungal cell wall?", "options": ["Prokaryotic cell wall contains cellulose", "Prokaryotic cell wall contains peptidoglycan", "Prokaryotic cell wall contains cutin", "Prokaryotic cell wall contains silica"], "correctIndex": 1, "explanation": "Prokaryotic (bacterial) cell walls contain peptidoglycan, a polymer of sugars and amino acids; fungal cell walls are made mainly of chitin and glucans. Options like cellulose or silica are not characteristic of bacterial walls.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 82, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2023 Q#82 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "official_paper_q83_83", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 83, "subject": "Biology", "topic": "chromoplast function", "question": "Pollination is facilitated by:", "options": ["Chloroplast", "Chromoplast", "Leucoplast", "Amyloplast"], "correctIndex": 1, "explanation": "Chromoplasts are plastids that synthesise and store pigments (carotenoids) which give flowers and fruits their colour and thereby attract pollinators, facilitating pollination. Other plastids listed have different functions (chloroplast photosynthesis, leucoplast storage).", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 83, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2023 Q#83 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "official_paper_q84_84", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 84, "subject": "Biology", "topic": "tonoplast definition", "question": "Tonoplast is the membrane separating:", "options": ["Vacuole and Nucleoplasm", "Cytoplasm and Nucleoplasm", "Vacuole and Stroma", "Vacuole and Cytoplasm"], "correctIndex": 3, "explanation": "The tonoplast is the membrane that bounds the central vacuole and separates the vacuolar lumen from the cytoplasm. It does not separate the vacuole from the nucleoplasm or stroma.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 84, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2023 Q#84 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "official_paper_q85_85", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 85, "subject": "Biology", "topic": "centriole microtubule arrangement", "question": "Each centriole is composed of ________ of Microtubules:", "options": ["Seven Triplets", "Eleven Triplets", "Nine Triplets", "Five Triplets"], "correctIndex": 2, "explanation": "Each centriole is typically composed of nine triplets of microtubules arranged in a cylinder (the 9+0 arrangement). The other numeric options are not the standard structural arrangement.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 85, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2023 Q#85 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "official_paper_q86_86", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 86, "subject": "Biology", "topic": "mitochondrial cristae", "question": "The folds of Inner Membrane of mitochondria are called:", "options": ["Cisternae", "Cristae", "Mesosome", "Infolds"], "correctIndex": 1, "explanation": "The infoldings of the inner mitochondrial membrane are called cristae; they increase surface area for oxidative phosphorylation. Cisternae refer to Golgi/ER, and mesosome is an outdated bacterial structure.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 86, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2023 Q#86 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "official_paper_q87_87", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 87, "subject": "Biology", "topic": "membrane hydrophobic core", "question": "According to the fluid mosaic model of cell membrane, which zone is embedded inside?", "options": ["Hydrophobic", "Hydrophilic", "Globular", "Filamentous"], "correctIndex": 0, "explanation": "The fluid mosaic model describes a bilayer with hydrophobic fatty acid tails forming the interior core embedded between hydrophilic head groups, so the hydrophobic zone lies inside the membrane. Proteins may span or sit in this hydrophobic region.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 87, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2023 Q#87 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "official_paper_q88_88", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 88, "subject": "Biology", "topic": "ser functions", "question": "Select the one which is NOT a function of Smooth Endoplasmic Reticulum (SER)?", "options": ["Metabolism of lipids", "Transmission of impulses", "Transport of materials", "Processing of glycoproteins"], "correctIndex": 3, "explanation": "Smooth ER is involved in lipid metabolism, detoxification, and transport but does not process glycoproteins - that is a major function of the rough ER and Golgi apparatus. Transmission of impulses is a cellular function in excitable cells and not a SER-specific role.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 88, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2023 Q#88 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "official_paper_q89_89", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 89, "subject": "Biology", "topic": "membrane channels", "question": "Cell membrane also contains _______ place by active and passive transport:", "options": ["Lipids", "Corner Proteins", "Charged pores", "Carbohydrates"], "correctIndex": 2, "explanation": "Cell membranes contain charged pores or ion channels that permit the passage of ions by passive or active transport mechanisms. While membranes also contain lipids and carbohydrates, the phrase best matches ion-conducting pores.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 89, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2023 Q#89 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "official_paper_q90_90", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 90, "subject": "Biology", "topic": "lysosome function", "question": "_______ are spherical sacs, surrounded by a single membrane and contain hydrolytic enzymes:", "options": ["Mitochondria", "Golgi Bodies", "Lysosomes", "Chloroplast"], "correctIndex": 2, "explanation": "Lysosomes are single-membrane-bounded spherical organelles filled with hydrolytic enzymes for intracellular digestion and recycling. Mitochondria and chloroplasts have different structures and functions.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 90, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2023 Q#90 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "official_paper_q91_91", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 91, "subject": "Biology", "topic": "proteins abundance", "question": "Most abundant organic compound in mammalian cells are:", "options": ["Water", "Lipids", "Carbohydrates", "Proteins"], "correctIndex": 3, "explanation": "Among organic macromolecules in mammalian cells, proteins are the most abundant by mass and perform diverse structural and enzymatic roles. Water is the most abundant molecule overall but is not an organic compound.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 91, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2023 Q#91 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "official_paper_q92_92", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 92, "subject": "Biology", "topic": "water heat capacity", "question": "Thermal stability of organisms in the environment is because of which characteristic of water?", "options": ["Solvent property", "Heat capacity", "Ionization", "Protection"], "correctIndex": 1, "explanation": "Water's high specific heat capacity stabilises temperature changes in organisms and environments, buffering thermal fluctuations. Solvent property and ionization are important features, but thermal stability specifically arises from heat capacity.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 92, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2023 Q#92 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "official_paper_q93_93", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 93, "subject": "Biology", "topic": "lipids energy density", "question": "C-H bonds in lipids are important:", "options": ["As insulating material", "Providing more energy", "As exoskeleton", "As cuticle of leaves"], "correctIndex": 1, "explanation": "C–H bonds in lipids store a lot of chemical energy; oxidation of these bonds yields more energy per gram than carbohydrates, which is why lipids are energy-dense. The other options describe structural or insulating roles but do not explain the energetic importance.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 93, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2023 Q#93 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "official_paper_q94_94", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 94, "subject": "Biology", "topic": "monosaccharide sweetness", "question": "These carbohydrates are sweetest among all carbohydrates:", "options": ["Monosaccharides", "Disaccharides", "Oligosaccharides", "Polysaccharides"], "correctIndex": 0, "explanation": "Monosaccharides (like glucose, fructose) are the simplest sugars and taste the sweetest per unit because disaccharides and polysaccharides must be hydrolysed and are less sweet. Oligo- and polysaccharides are larger and less sweet.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 94, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2023 Q#94 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "official_paper_q95_95", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 95, "subject": "English", "topic": "present perfect continuous", "question": "I ________ English for five years.", "options": ["Study", "Am Studying", "Have been studying", "studies"], "correctIndex": 2, "explanation": "The sentence refers to an action that began in the past and continues to the present, which calls for the present perfect continuous tense 'have been studying.' Simple present or present continuous are not appropriate for this time frame.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 95, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "NUMS 2023 Q#95 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2023"}, {"id": "official_paper_q96_96", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 96, "subject": "English", "topic": "subject verb agreement stative", "question": "The soup ________ good", "options": ["Taste", "Tastes", "Is tasting", "Has taste"], "correctIndex": 1, "explanation": "When describing a sensory state or general truth about the soup, the stative verb takes the third-person singular form 'tastes.' 'Is tasting' would be used for a temporary action but is uncommon here.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 96, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2023 Q#96 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2023"}, {"id": "official_paper_q97_97", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 97, "subject": "English", "topic": "first conditional start", "question": "Unless we _________ now, we cannot be on time", "options": ["Start", "Will start", "Do not start", "Are starting"], "correctIndex": 0, "explanation": "After 'unless' we use the present simple for a real conditional referring to the future: 'Unless we start now, we cannot be on time.' 'Will start' is not used immediately after 'unless' in this structure.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 97, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "NUMS 2023 Q#97 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2023"}, {"id": "official_paper_q98_98", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 98, "subject": "English", "topic": "comparative expression all other", "question": "Daud is better than _________ of the college.", "options": ["All teachers", "Any teachers", "All other teachers", "Any teacher"], "correctIndex": 2, "explanation": "When comparing one person to the rest of a group, English uses 'all other' to exclude the subject: 'Daud is better than all other teachers of the college.' The other options are grammatically incorrect in this comparative context.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 98, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "NUMS 2023 Q#98 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2023"}, {"id": "official_paper_q99_99", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 99, "subject": "English", "topic": "preposition collocations abide by", "question": "Abide ________ the traffic laws for smooth and safe flow of traffic.", "options": ["On", "With", "By", "To"], "correctIndex": 2, "explanation": "The correct collocation is 'abide by the law(s),' meaning to follow or comply with rules. 'Abide on/with/to' are not standard in this collocation.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 99, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2023 Q#99 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2023"}, {"id": "official_paper_q100_100", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 100, "subject": "English", "topic": "prefer preposition to", "question": "He prefers death ________ dishonor.", "options": ["Over", "On", "Upon", "To"], "correctIndex": 3, "explanation": "The verb 'prefer' is followed by 'to' when expressing a choice between two alternatives: 'He prefers death to dishonor.' 'Over' is sometimes used in other constructions but 'prefer X to Y' is idiomatic here.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 100, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2023 Q#100 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2023"}, {"id": "official_paper_q101_101", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 101, "subject": "English", "topic": "vocabulary surplus", "question": "What does the word 'SURPLUS' mean?", "options": ["In excess", "A mathematical term", "Within reach", "Salutation"], "correctIndex": 0, "explanation": "“Surplus” means an amount that is over and above what is needed, i.e. in excess. The other options (mathematical term, within reach, salutation) do not convey extra quantity.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 101, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "NUMS 2023 Q#101 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2023"}, {"id": "official_paper_q102_102", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 102, "subject": "English", "topic": "vocabulary spill", "question": "What does the word 'SPILL' mean?", "options": ["Coil", "Deliver", "Spoil", "Spread"], "correctIndex": 3, "explanation": "One meaning of “spill” is to cause something to spread or flow out (e.g. spill liquid that spreads). The distractors (coil, deliver, spoil) do not match the common sense of spreading or overflowing.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 102, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "NUMS 2023 Q#102 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2023"}, {"id": "official_paper_q103_103", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 103, "subject": "English", "topic": "vocabulary curious", "question": "What does the word 'CURIOUS' mean?", "options": ["Keen", "Careful", "Quest", "Cruel"], "correctIndex": 0, "explanation": "“Curious” in this context means eager to know or keenly interested. The other options (careful, quest, cruel) are different meanings or unrelated words.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 103, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "NUMS 2023 Q#103 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2023"}, {"id": "official_paper_q104_104", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 104, "subject": "English", "topic": "punctuation colon use", "question": "Pick the sentence with correct punctuation:", "options": ["He had one motto \"serving humanity.\"", "He, had one motto, serving humanity.", "He had one motto; serving humanity.", "He had one motto: serving humanity."], "correctIndex": 3, "explanation": "A colon introduces an explanation or phrase that follows a complete clause, so ‘He had one motto: serving humanity.’ is correct. The other options either misuse commas/semicolons or misplace quotation marks.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 104, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "NUMS 2023 Q#104 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2023"}, {"id": "official_paper_q105_105", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 105, "subject": "English", "topic": "spelling colleague", "question": "Pick the word with correct spelling:", "options": ["Collique", "Colleague", "Collegue", "Co-leageu"], "correctIndex": 1, "explanation": "‘Colleague’ is the correct standard spelling for a workmate. The other spellings are incorrect variants that do not follow English orthography.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 105, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "NUMS 2023 Q#105 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2023"}, {"id": "official_paper_q106_106", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 106, "subject": "English", "topic": "spelling acquaintance", "question": "Pick the word with correct spelling:", "options": ["Acquaintance", "Equatance", "Equantence", "Equentense"], "correctIndex": 0, "explanation": "‘Acquaintance’ is the correct spelling for someone you know slightly. The other choices are misspellings that alter the correct letter sequence.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 106, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "NUMS 2023 Q#106 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2023"}, {"id": "official_paper_q107_107", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 107, "subject": "English", "topic": "spelling priority", "question": "Pick the word with correct spelling:", "options": ["Prayority", "Priarity", "Prioarily", "Priority"], "correctIndex": 3, "explanation": "‘Priority’ is the correct spelling of the word meaning something of primary importance. The other options are incorrect attempts that do not match standard spelling.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 107, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "NUMS 2023 Q#107 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2023"}, {"id": "official_paper_q108_108", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 108, "subject": "English", "topic": "punctuation semicolon in quotations", "question": "Pick the sentence with correct punctuation:", "options": ["\"He did his best that was all anyone could do in any job\".", "He did his best, that was all anyone could do in any job.", "\"He did his best: that was all anyone could do in any job\".", "\"He did his best; that was all anyone could do in any job\"."], "correctIndex": 3, "explanation": "The sentence contains two independent clauses joined with a semicolon inside the quotation marks, so: “He did his best; that was all anyone could do in any job.” is correct. The other options either omit needed punctuation or place punctuation incorrectly.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 108, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "NUMS 2023 Q#108 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2023"}, {"id": "official_paper_q109_109", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 109, "subject": "English", "topic": "question word order", "question": "Pick the correct option:", "options": ["How has the chair leg broken?", "How has the leg of the chair broken?", "How the leg of the chair has broken?", "How the chair's leg is broken?"], "correctIndex": 1, "explanation": "Correct question word order for a present perfect passive construction places the auxiliary before the subject: ‘How has the leg of the chair broken?’ is the grammatically correct option. The other options either misplace auxiliaries or use incorrect tense/form.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 109, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "NUMS 2023 Q#109 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2023"}, {"id": "official_paper_q110_110", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 110, "subject": "Chemistry", "topic": "vapor pressure dependence", "question": "Vapor pressure is independent of which factor?", "options": ["Temperature", "Intermolecular forces", "Density of liquid", "Surface area of liquid"], "correctIndex": 3, "explanation": "Vapor pressure depends on temperature and intermolecular forces but not on the surface area of the liquid; increasing surface area only changes the rate to equilibrium, not the equilibrium vapor pressure. Density of the liquid can correlate with vapor pressure via intermolecular forces, so surface area is the independent factor listed.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 110, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2023 Q#110 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "official_paper_q111_111", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 111, "subject": "Chemistry", "topic": "boiling point intermolecular forces", "question": "The boiling point of ether is less as compared to alcohols and phenols due to:", "options": ["Functional group", "Intermolecular forces", "Nature of alkyl groups", "Isomerism"], "correctIndex": 1, "explanation": "Ethers lack the strong hydrogen bonding that alcohols and phenols can form, so their intermolecular forces are weaker and boiling points are lower. Functional group identity and hydrogen-bonding capacity (a subset of intermolecular forces) explain the difference rather than isomerism or alkyl nature alone.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 111, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2023 Q#111 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "official_paper_q112_112", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 112, "subject": "Chemistry", "topic": "hydrogen bonding ice fusion", "question": "When 2 ice cubes are pressed over each other they unite to form one cube due to:", "options": ["Dipole dipole attraction", "Covalent attraction", "Van Der Waal's forces", "H-bonding"], "correctIndex": 3, "explanation": "When two ice cubes are pressed together, the pressure locally melts the surfaces and hydrogen bonds reform across the interface, causing them to fuse; this behavior is characteristic of H-bonded solids like ice. Van der Waals or dipole–dipole forces are not the primary cause in ice’s cohesion.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 112, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2023 Q#112 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "official_paper_q113_113", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 113, "subject": "Chemistry", "topic": "ionic crystal structure nacl", "question": "Which statement correctly describes the structure of sodium chloride crystal?", "options": ["Each sodium ion is surrounded by six chloride ions and each chloride ions surrounded by six sodium ions", "The crystal is face centered cubic structure", "Each sodium ion is surrounded by 3 chloride ions and each chloride ion surrounded by 3 sodium ions", "Inter molecular forces are present between two oppositely charges ions"], "correctIndex": 0, "explanation": "Sodium chloride has the rocksalt structure where each Na+ is octahedrally coordinated by six Cl− and vice versa, so statement A correctly describes the coordination. While the lattice is an fcc array of one ion type with the other in octahedral sites (making B partially descriptive), A directly states the coordination numbers and is the best choice.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 113, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2023 Q#113 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "official_paper_q114_114", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 114, "subject": "Chemistry", "topic": "lattice energy trend", "question": "The greater Lattice energy is shown by:", "options": ["NaCl", "NaBr", "NaI", "NaF"], "correctIndex": 3, "explanation": "Lattice energy increases with greater ionic charge and smaller ionic radius; among the halides of sodium, fluoride (F−) is the smallest anion so NaF has the largest lattice energy. Larger anions (Cl−, Br−, I−) give progressively lower lattice energies.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 114, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2023 Q#114 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "official_paper_q115_115", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 115, "subject": "Chemistry", "topic": "thermal conductivity metals", "question": "Thermal conductivity of metals is due to:", "options": ["Layered structure of metals", "Freely moving electrons", "Loosely held metal atoms", "Vibrational movement of metals"], "correctIndex": 1, "explanation": "Metals conduct heat well primarily because of their delocalized, freely moving conduction electrons that transport thermal energy efficiently. Layered structure or vibrational motion of atoms (phonons) play lesser roles compared with electronic conduction in metals.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 115, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2023 Q#115 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "official_paper_q116_116", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 116, "subject": "Chemistry", "topic": "haber process pressure effect", "question": "The high pressure of 200 atm in Haber's process is used for:", "options": ["Better yield", "Lower yield", "Lower rate", "Cost decrease"], "correctIndex": 0, "explanation": "Haber process uses high pressure to shift the equilibrium toward ammonia (fewer gas molecules) according to Le Chatelier’s principle, improving yield. Although high pressure increases cost and engineering difficulty, its primary purpose in the process is to obtain better ammonia yield.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 116, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2023 Q#116 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "official_paper_q117_117", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 117, "subject": "Chemistry", "topic": "catalyst equilibrium attainment", "question": "By which of the following factors equilibrium state is attained earlier?", "options": ["Temperature", "Pressure", "Concentration", "Catalyst"], "correctIndex": 3, "explanation": "A catalyst speeds both the forward and reverse reactions by lowering the activation energy, so the system reaches equilibrium faster though the equilibrium position is unchanged. Temperature, pressure, and concentration change the equilibrium position but do not inherently make it be reached sooner in the same way a catalyst does.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 117, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "NUMS 2023 Q#117 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2023"}, {"id": "official_paper_q118_118", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 118, "subject": "Chemistry", "topic": "temperature effect on rate q10 rule", "question": "When temperature of reacting gases is raised by 10 K, the reaction rate will increase to:", "options": ["Double", "Three times", "Four times", "Five times"], "correctIndex": 0, "explanation": "A common rule of thumb (Q10) is that many reaction rates approximately double for a 10 K (or 10 °C) increase in temperature, so the rate roughly doubles. The exact factor depends on activation energy, but 'double' is the standard approximate answer here.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 118, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2023 Q#118 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "official_paper_q119_119", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 119, "subject": "Chemistry", "topic": "activation energy definition", "question": "The minimum amount of energy required by the colliding particles for effective collisions is called:", "options": ["Activation energy", "Lattice energy", "Bond energy", "Hydration energy"], "correctIndex": 0, "explanation": "Activation energy is the minimum energy colliding particles must have for a successful (effective) collision leading to reaction. Lattice, bond, and hydration energies are different types of energetic quantities and do not describe this collision threshold.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 119, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "NUMS 2023 Q#119 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2023"}, {"id": "official_paper_q120_120", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 120, "subject": "Chemistry", "topic": "state functions vs path functions", "question": "Which of the following is not a state function?", "options": ["Pressure (P)", "Work (W)", "Volume (V)", "Temperature (T)"], "correctIndex": 1, "explanation": "State functions depend only on the state of the system (P, V, T are state functions), while work depends on the path taken during a process and is therefore not a state function. This distinction is fundamental in thermodynamics.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 120, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2023 Q#120 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "official_paper_q121_121", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 121, "subject": "Chemistry", "topic": "lattice energy definition", "question": "Equation represents which energy change? Mg2+(g) + O2−(g) → MgO(s)", "options": ["Atomization", "Neutralization", "Lattice energy", "Solution"], "correctIndex": 2, "explanation": "The equation forming MgO(s) from gaseous ions corresponds to the lattice energy, the energy released when gaseous ions combine to form an ionic solid. Atomization and solution are different processes, and neutralization refers to acid–base reactions, so lattice energy is the correct label.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 121, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2023 Q#121 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "official_paper_q122_122", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 122, "subject": "Chemistry", "topic": "overall order reaction no plus o3", "question": "When nitric oxide reacts with ozone, the order of reaction will be:", "options": ["2nd", "3rd", "1st", "Zero"], "correctIndex": 0, "explanation": "The elementary reaction NO + O3 → products is bimolecular, involving two reactant molecules in a single step, so its overall order is second order (first order in each reactant). Therefore 2nd order is correct for this simple elementary process.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 122, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "NUMS 2023 Q#122 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2023"}, {"id": "official_paper_q123_123", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 123, "subject": "Chemistry", "topic": "electrolysis reduction site", "question": "During electrolysis, reduction always occurs at the:", "options": ["Anode", "Cathode", "SHE", "Salt bridge"], "correctIndex": 1, "explanation": "Reduction (gain of electrons) always occurs at the cathode during electrolysis, while oxidation occurs at the anode. Salt bridges and the Standard Hydrogen Electrode (SHE) are not the universal sites for reduction in an electrolytic cell.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 123, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "NUMS 2023 Q#123 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2023"}, {"id": "official_paper_q124_124", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 124, "subject": "Chemistry", "topic": "electronegativity fluorine trend", "question": "The reason of highest electronegativity value of Fluorine is:", "options": ["Complete outermost shell", "Ability to form negative ion", "Existence as diatomic molecule", "Smaller size and higher nuclear charge in the respective period"], "correctIndex": 3, "explanation": "Fluorine’s highest electronegativity is due to its very small atomic radius and relatively high effective nuclear charge in its period, which strongly attracts bonding electrons. Other choices (complete shell, diatomic existence, ability to form negative ion) do not explain the periodic trend quantitatively.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 124, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2023 Q#124 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "official_paper_q125_125", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 125, "subject": "Chemistry", "topic": "vsepr shape prediction", "question": "Valance shell electron pair repulsion theory explains:", "options": ["Bond Energy", "Bond Length", "Shapes and Bond Energy", "Shapes"], "correctIndex": 3, "explanation": "VSEPR theory (Valence Shell Electron Pair Repulsion) explains molecular shapes by assuming electron pairs repel and adopt arrangements that minimize repulsion, so it is specifically a model for predicting shapes. It does not primarily focus on bond energy or bond length.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 125, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "NUMS 2023 Q#125 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2023"}, {"id": "official_paper_q126_126", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 126, "subject": "Chemistry", "topic": "hybridization orbital geometry", "question": "Which of the following has sp3 hybridization?", "options": ["BF3", "C2H4", "BeCl2", "CH4"], "correctIndex": 3, "explanation": "In CH4 the central carbon forms four sigma bonds and adopts sp3 hybridization giving a tetrahedral geometry. BF3 is sp2, C2H4 carbons are sp2, and BeCl2 is linear with sp hybridization.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 126, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2023 Q#126 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2023"}, {"id": "official_paper_q127_127", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 127, "subject": "Chemistry", "topic": "bond length factors", "question": "The factor which is not affecting bond length is:", "options": ["Pressure of multiple bonds", "Nature of hybridization present", "Difference in electronegativity between the two bonded atoms", "Ionization energies of the two bonded atoms"], "correctIndex": 3, "explanation": "Bond length is influenced by bond order (single/double/triple), the hybridization state of the atoms and the electronegativity difference between bonded atoms. Ionization energies are atomic properties not directly determining the internuclear distance in a bonded pair, so they do not generally affect bond length.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 127, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "NUMS 2023 Q#127 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2023"}, {"id": "official_paper_q128_128", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 128, "subject": "Chemistry", "topic": "mechanical properties of metals", "question": "Which of the following substance is malleable and ductile?", "options": ["Sodium chloride", "Copper sulphate", "Mercury", "Aluminum"], "correctIndex": 3, "explanation": "Malleability and ductility are metallic properties caused by non-directional metallic bonding and ability of atoms to slide past each other; aluminium is a typical malleable, ductile metal. Ionic compounds (e.g. NaCl, CuSO4) are brittle and mercury is a liquid at room temperature, so it is not malleable/ductile in the usual sense.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 128, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2023 Q#128 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "official_paper_q129_129", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 129, "subject": "Chemistry", "topic": "crystal structure of sodium", "question": "Co-ordination number of Na is:", "options": ["10", "9", "8", "12"], "correctIndex": 2, "explanation": "Metallic sodium crystallizes in a body-centred cubic (bcc) lattice where each atom has eight nearest neighbours, so the coordination number is 8. The NaCl structure would give CN = 6, but here the context is elemental sodium.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 129, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2023 Q#129 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "official_paper_q130_130", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 130, "subject": "Chemistry", "topic": "catalytic cracking", "question": "The cracking method used to obtain better quality gasoline is:", "options": ["Thermal", "Catalytic", "Steam", "Radiations"], "correctIndex": 1, "explanation": "Catalytic cracking is used industrially to break heavy hydrocarbons into lighter, branched and aromatic hydrocarbons that improve gasoline quality (higher octane) and is favoured over thermal cracking for gasoline production. Thermal cracking requires higher temperatures and gives more alkenes and less desirable fractions.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 130, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2023 Q#130 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "official_paper_q131_131", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 131, "subject": "Chemistry", "topic": "homocyclic compounds classification", "question": "Homocyclic organic compounds are sub divided into two types namely:", "options": ["Alicyclic and Aromatic", "Open chain and branched chain", "Aromatic and non-aromatic", "Antiaromatic and antialicyclic"], "correctIndex": 0, "explanation": "Homocyclic compounds are ring systems made only of carbon atoms and are commonly classified into alicyclic (non-aromatic saturated or unsaturated rings) and aromatic (conjugated cyclic systems obeying aromaticity rules). This distinction separates simple carbon rings from those with aromatic stabilization.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 131, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2023 Q#131 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "official_paper_q132_132", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 132, "subject": "Chemistry", "topic": "friedel crafts acylation", "question": "Acetophenone can be formed by which of the following reaction of benzene?", "options": ["Alkylation", "Acylation", "Halogenation", "Nitration"], "correctIndex": 1, "explanation": "Acetophenone (a phenyl methyl ketone) is formed by acylation of benzene (Friedel–Crafts acylation) which introduces an acyl group onto the ring. Alkylation would give an alkylbenzene, halogenation adds halogen, and nitration introduces a nitro group.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 132, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "NUMS 2023 Q#132 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2023"}, {"id": "official_paper_q133_133", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 133, "subject": "Chemistry", "topic": "cycloalkane general formula", "question": "Generic formula of cycloalkane is:", "options": ["CnH2n+2", "CnH2n", "CnH2n−1", "CnCH2n−2"], "correctIndex": 1, "explanation": "Cycloalkanes have the general formula CnH2n because forming a ring removes two hydrogen atoms compared with the corresponding open-chain alkane (CnH2n+2).", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 133, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "NUMS 2023 Q#133 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2023"}, {"id": "official_paper_q134_134", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 134, "subject": "Chemistry", "topic": "lucas test", "question": "Which of the following reactions differentiates alcohol from phenol?", "options": ["Lucas test", "Halogenations", "Nitration", "Iodoform test"], "correctIndex": 0, "explanation": "The Lucas test (ZnCl2/HCl) converts tertiary (and to a lesser extent secondary) alcohols into alkyl chlorides rapidly, giving turbidity; phenols do not give the same positive Lucas reaction. Therefore the Lucas test can distinguish many alcohols from phenols which do not react under these conditions.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 134, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "NUMS 2023 Q#134 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2023"}, {"id": "official_paper_q135_135", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 135, "subject": "Chemistry", "topic": "reactivity for c o bond cleavage", "question": "The order of reactivity of alcohol when C-O bond breaks is:", "options": ["Tertiary alcohol > secondary alcohol > Primary alcohol", "Secondary alcohol > primary alcohol > tertiary alcohol", "Primary alcohol > secondary alcohol > tertiary alcohol", "Tertiary alcohol > primary alcohol > secondary alcohol"], "correctIndex": 0, "explanation": "When C–O bond cleavage proceeds by an SN1 pathway the rate depends on carbocation stability: tertiary carbocations are most stable, then secondary, then primary, so tertiary alcohols react fastest, then secondary, then primary. This gives the order tertiary > secondary > primary.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 135, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "NUMS 2023 Q#135 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2023"}, {"id": "official_paper_q136_136", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 136, "subject": "Chemistry", "topic": "general formula of ketones", "question": "CnH2nO is the general formula of:", "options": ["Ether", "Carboxylic acid", "Ketones", "Carbolic acid"], "correctIndex": 2, "explanation": "Acyclic saturated ketones are typically represented by the formula CnH2nO. Note that ethers can be isomeric and share the same molecular formula in many cases, but ketones are commonly listed with this general formula in basic organic nomenclature.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 136, "syllabusUnit": "Unit 11: Carbonyl Compounds (Aldehydes & Ketones)", "pmdcTopic": "Carbonyl Chemistry, Addition Reactions & Tests for Carbonyls", "textbookCitation": "PTB Chemistry XII Ch 12 (Aldehydes and Ketones); Federal Chemistry XII Ch 20", "citationString": "NUMS 2023 Q#136 | Unit 11: Carbonyl Compounds (Aldehydes & Ketones) | PTB Chemistry XII Ch 12 (Aldehydes and Ketones); Federal Chemistry XII Ch 20"}, "year": "2023"}, {"id": "official_paper_q137_137", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 137, "subject": "Chemistry", "topic": "reduction of carbonyl compounds", "question": "Catalytic reduction of aldehyde & Ketone forms:", "options": ["Alcohol", "Carboxylic acid", "Alkane", "Aldehyde"], "correctIndex": 0, "explanation": "Catalytic hydrogenation of aldehydes and ketones reduces the carbonyl group (C=O) to the corresponding alcohol (primary from aldehyde, secondary from ketone). Carboxylic acids and alkanes are not the direct products of simple catalytic reduction of carbonyls.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 137, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "NUMS 2023 Q#137 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2023"}, {"id": "official_paper_q138_138", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 138, "subject": "Chemistry", "topic": "esterification", "question": "Which of the following reacts with Carboxylic Acid to form Ester?", "options": ["Aldehyde", "Alkyl Halide", "Ketones", "Alcohol"], "correctIndex": 3, "explanation": "Carboxylic acids react with alcohols in a condensation (Fischer esterification) to form esters and water under acid catalysis. Aldehydes, ketones and alkyl halides do not directly give esters in this simple condensation.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 138, "syllabusUnit": "Unit 12: Carboxylic Acids & Derivatives", "pmdcTopic": "Acidity of Carboxylic Acids & Acyl Derivatives", "textbookCitation": "PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21", "citationString": "NUMS 2023 Q#138 | Unit 12: Carboxylic Acids & Derivatives | PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21"}, "year": "2023"}, {"id": "official_paper_q139_139", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 139, "subject": "Chemistry", "topic": "nitrile hydrolysis", "question": "Hydrolysis of Nitriles produces:", "options": ["Carboxylic acid", "Aldehydes", "Ketones", "Esters"], "correctIndex": 0, "explanation": "Hydrolysis of a nitrile (RCN) proceeds through an amide intermediate and ultimately yields the corresponding carboxylic acid (RCO2H) under acidic or strongly basic conditions. It does not give aldehydes or ketones as the final product under standard hydrolysis.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 139, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2023 Q#139 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "official_paper_q140_140", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 140, "subject": "Chemistry", "topic": "stoichiometry percent composition", "question": "What is the mass of sulphur in 24.5 g of H2SO4?", "options": ["32 g", "24 g", "16 g", "8 g"], "correctIndex": 3, "explanation": "Molar mass of H2SO4 is 98 g·mol−1 and sulfur accounts for 32 g per 98 g. So in 24.5 g the sulfur mass is 24.5 × (32/98) = 8 g.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 140, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "NUMS 2023 Q#140 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2023"}, {"id": "official_paper_q141_141", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 141, "subject": "Chemistry", "topic": "stoichiometric calculation mole ratios", "question": "From the equation (N2 + 3H2 → 2NH3), how many moles of NH3 are produced from 2.5 moles of N2?", "options": ["2.5 moles", "2 moles", "5 moles", "7.5 moles"], "correctIndex": 2, "explanation": "From N2 + 3H2 → 2NH3 the mole ratio N2:NH3 is 1:2, so 2.5 moles of N2 produce 2 × 2.5 = 5.0 moles of NH3.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 141, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2023 Q#141 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "official_paper_q142_142", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 142, "subject": "Chemistry", "topic": "photon energy frequency", "question": "The amount of energy associated with quantum of radiation is directly proportional to:", "options": ["Photon", "Wavelength", "Frequency", "Velocity"], "correctIndex": 2, "explanation": "The energy of a photon (quantum of radiation) is given by E = hν, so it is directly proportional to the radiation frequency ν. It is inversely related to wavelength, not directly proportional to it.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 142, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2023 Q#142 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2023"}, {"id": "official_paper_q143_143", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 143, "subject": "Chemistry", "topic": "magnetic quantum number count", "question": "If value of azimuthal quantum number is 2 then total values of magnetic quantum number will be:", "options": ["03", "05", "07", "10"], "correctIndex": 1, "explanation": "For azimuthal quantum number l = 2 the magnetic quantum number ml can take values −2, −1, 0, +1, +2, giving 2l + 1 = 5 possible ml values.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 143, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2023 Q#143 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2023"}, {"id": "official_paper_q144_144", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 144, "subject": "Chemistry", "topic": "f orbital degeneracy", "question": "Total number of directions of f-orbitals in space are:", "options": ["05", "03", "07", "06"], "correctIndex": 2, "explanation": "For f orbitals l = 3, so the magnetic quantum number ml runs from −3 to +3 giving 2l + 1 = 7 distinct orientations (seven f orbitals).", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 144, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2023 Q#144 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2023"}, {"id": "official_paper_q145_145", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 145, "subject": "Chemistry", "topic": "origin of quantum numbers", "question": "Which of the following quantum number is not obtained from Schrodinger Wave equation?", "options": ["Principal Quantum Number", "Spin Quantum Number", "Azimuthal Quantum Number", "Magnetic Quantum Number"], "correctIndex": 1, "explanation": "The Schrödinger equation yields the principal (n), azimuthal (l) and magnetic (ml) quantum numbers; the electron spin quantum number (ms) is not derived from that equation but introduced separately to account for electron spin.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 145, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2023 Q#145 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2023"}, {"id": "official_paper_q146_146", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 146, "subject": "Chemistry", "topic": "hunds rule", "question": "The electronic configuration for degenerate orbitals is explained by:", "options": ["Aufbau Principle", "n + l rule", "Hund's rule", "Pauli exclusion principle"], "correctIndex": 2, "explanation": "Hund's rule governs the filling of degenerate orbitals by stating that electrons occupy degenerate orbitals singly with parallel spins to maximize total spin before pairing. This explains the observed electronic configurations in degenerate subshells.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 146, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2023 Q#146 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2023"}, {"id": "official_paper_q147_147", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 147, "subject": "Chemistry", "topic": "kinetic molecular theory", "question": "The idea that molecules in gases are in constant movement is called:", "options": ["Kinetic theory of gases", "Crystal field theory", "Molecular orbital theory", "Transition state theory"], "correctIndex": 0, "explanation": "The kinetic theory of gases models gases as a large number of small particles in constant, random motion; this explains macroscopic gas laws and properties. The other listed theories refer to different areas of chemistry/physics.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 147, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2023 Q#147 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "official_paper_q148_148", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 148, "subject": "Chemistry", "topic": "pressure units", "question": "The SI unit for pressure is:", "options": ["mm of Hg", "Pascal", "Bar", "Torr"], "correctIndex": 1, "explanation": "The SI unit of pressure is the pascal (Pa), defined as one newton per square metre (N·m−2). Units like mmHg, bar and Torr are non-SI pressure units.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 148, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2023 Q#148 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "official_paper_q149_149", "paperTitle": "NUMS MDCAT 2023 (Official Paper)", "shortTitle": "NUMS 2023", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 149, "subject": "Chemistry", "topic": "ideal gas law temperature volume", "question": "If both temperature and volume of gas are doubled, the pressure:", "options": ["Cannot be predicted", "Is reduced to 1⁄2", "Remains unchanged", "Is doubled"], "correctIndex": 2, "explanation": "From the ideal gas law P = nRT/V, if T is doubled and V is doubled then P = nR(2T)/(2V) = nRT/V, so the pressure remains unchanged. Therefore P stays the same.", "reference": {"sourcePaper": "NUMS MDCAT 2023 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 149, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2023 Q#149 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "paper_q1_1", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 1, "subject": "Biology", "topic": "chloroplast thylakoid structure", "question": "Each granum consists of_________thylakoids:", "options": ["40-60", "25-50", "50-70", "100-200"], "correctIndex": 1, "explanation": "A granum is a stack of thylakoid membranes in chloroplasts; typical counts per granum are in the tens. The key figure given on the paper is 25–50 thylakoids, so option B is correct; the other choices give unrealistically low or very high counts for a single granum.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 1, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2023 Q#1 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q2_2", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 2, "subject": "Biology", "topic": "chromosome termini telomeres", "question": "The terminal ends of chromosomes are called:", "options": ["Satellite", "Kinetochore", "Nucleolar organizers", "Telomeres"], "correctIndex": 3, "explanation": "Chromosome ends are capped by telomeres which protect chromosomal DNA from degradation. Satellites, kinetochores and nucleolar organizers are different chromosome-associated structures with other functions.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 2, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "SZABMU 2023 Q#2 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2023"}, {"id": "paper_q3_3", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 3, "subject": "Biology", "topic": "golgi in secretory cells", "question": "Which organelles would be more abundant in a secretory cell than non-secretory cells?", "options": ["Lysosomes", "Golgi complex", "Vacuoles", "Centrioles"], "correctIndex": 1, "explanation": "Secretory cells need extensive processing and packaging of proteins and lipids, functions carried out by the Golgi complex, so Golgi apparatus is more abundant. Lysosomes and centrioles are not specifically increased for secretion; vacuoles are more typical of plant cells.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 3, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2023 Q#3 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q4_4", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 4, "subject": "Biology", "topic": "nucleolus during mitosis", "question": "The structure which disappears during cell division is:", "options": ["Vacuole", "Lysosome", "Nucleolus", "Endoplasmic reticulum"], "correctIndex": 2, "explanation": "The nucleolus breaks down during mitosis as ribosomal RNA synthesis halts and the chromatin condenses. Vacuoles, lysosomes and ER remain present (though ER changes conformation) and do not characteristically disappear.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 4, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2023 Q#4 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q5_5", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 5, "subject": "Biology", "topic": "atp synthase location", "question": "The enzyme ATP synthase is located on the membrane of:", "options": ["Nucleus", "Mitochondria", "Lysosome", "Vacuole"], "correctIndex": 1, "explanation": "ATP synthase is an enzyme complex embedded in the inner mitochondrial membrane (and in chloroplast thylakoid membranes) where it synthesizes ATP using a proton gradient. It is not located on the nucleus, lysosome or vacuole membranes.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 5, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2023 Q#5 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q6_6", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 6, "subject": "Biology", "topic": "lysosome function", "question": "Intracellular digestion of food is done by the organelle:", "options": ["Vacuole", "Lysosome", "Golgi apparatus", "Ribosome"], "correctIndex": 1, "explanation": "Lysosomes contain hydrolytic enzymes that digest macromolecules inside the cell, performing intracellular digestion. Vacuoles may store material, Golgi modifies and sorts proteins, and ribosomes synthesize proteins.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 6, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2023 Q#6 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q7_7", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 7, "subject": "Biology", "topic": "axon diameter and myelination", "question": "Which axon would transmit an action potential most rapidly?", "options": ["1mm diameter neuron lacking myelin", "1mm diameter neuron with myelin", "2mm diameter neuron lacking myelin", "2mm diameter neuron with myelin"], "correctIndex": 3, "explanation": "Conduction velocity increases with both axon diameter and myelination; a larger diameter myelinated axon conducts fastest. Thus the 2 mm myelinated neuron transmits signals more rapidly than smaller or unmyelinated options.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 7, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "SZABMU 2023 Q#7 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2023"}, {"id": "paper_q8_8", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 8, "subject": "Biology", "topic": "vasopressin classification", "question": "Vasopressin is an example of:", "options": ["Steroid hormone", "Catecholamine", "Peptide hormone", "Glycoprotein"], "correctIndex": 2, "explanation": "Vasopressin (antidiuretic hormone) is a small peptide hormone composed of amino acids. It is not a steroid, catecholamine or glycoprotein.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 8, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2023 Q#8 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q9_9", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 9, "subject": "Biology", "topic": "hypothalamus functions", "question": "Which function is not controlled by hypothalamus?", "options": ["Regulate hunger", "Regulate sleep", "Regulate water balance", "Storing long time memories"], "correctIndex": 3, "explanation": "The hypothalamus regulates hunger, sleep-wake cycles and water balance via hormonal and autonomic control. Long‑term memory storage is primarily a function of cortical and hippocampal structures, not the hypothalamus.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 9, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2023 Q#9 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q10_10", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 10, "subject": "Biology", "topic": "posterior pituitary hormones", "question": "Posterior lobe of pituitary gland produces:", "options": ["Oxytocin", "Thyroid Stimulating Hormone (TSH)", "Adreno Corticotropic Hormone (ACTH)", "Follicle Stimulating Hormone (FSH)"], "correctIndex": 0, "explanation": "The posterior pituitary releases hormones like oxytocin (produced in the hypothalamus and secreted by the posterior lobe). TSH, ACTH and FSH are anterior pituitary hormones.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 10, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "SZABMU 2023 Q#10 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2023"}, {"id": "paper_q11_11", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 11, "subject": "Biology", "topic": "neurotransmitter definition", "question": "In neurons, the message istransmitted across synapse in the form of chemical messenger called:", "options": ["Communication", "Neurotransmitter", "Nerve impulse", "Noci receptors"], "correctIndex": 1, "explanation": "Chemical transmission across synapses occurs via neurotransmitters released from the presynaptic neuron. 'Nerve impulse' refers to the electrical signal, while the other options are not the correct term for the chemical messenger.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 11, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "SZABMU 2023 Q#11 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2023"}, {"id": "paper_q12_12", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 12, "subject": "Biology", "topic": "synapse definition", "question": "Microscopic gap between the two neurons is called:", "options": ["Synapsis", "Synapse", "Collapse", "Synaptic knob"], "correctIndex": 1, "explanation": "The microscopic gap across which neurotransmitters travel is called the synapse. 'Synapsis' is a different term (chromosome pairing), 'synaptic knob' is a presynaptic structure and 'collapse' is unrelated.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 12, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "SZABMU 2023 Q#12 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2023"}, {"id": "paper_q13_13", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 13, "subject": "Biology", "topic": "reflex arc sensory neuron location", "question": "In a reflex arc, the cell body of sensory neuron is located in:", "options": ["Ventral root ganglion", "Gray matter of spinal cord", "White matter of spinal cord", "Dorsal root ganglion"], "correctIndex": 3, "explanation": "Sensory neuron cell bodies in spinal reflex arcs reside in the dorsal root (spinal) ganglia located just outside the spinal cord. Ventral roots carry motor fibers; gray and white matter are spinal cord tissues, not the ganglion location.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 13, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2023 Q#13 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q14_14", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 14, "subject": "Biology", "topic": "amygdala emotion", "question": "The feelings and emotions of love and hate are controlled by:", "options": ["Amygdalae", "Hippocampus", "Thalamus", "Hypothalamus"], "correctIndex": 0, "explanation": "The amygdalae are key limbic structures involved in processing emotions such as fear and affection. The hippocampus is mainly involved in memory, and the thalamus/hypothalamus have other regulatory roles.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 14, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2023 Q#14 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q15_15", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 15, "subject": "Biology", "topic": "amoeba locomotion", "question": "Which of the following is TRUE about Amoebae?", "options": ["They have flagella", "They are multicellular", "They do not cause any disease in humans", "They move by forming specialized cytoplasmic projections called pseudopodia"], "correctIndex": 3, "explanation": "Amoebae move using pseudopodia - temporary cytoplasmic extensions. They do not have flagella (in typical amoebae), are unicellular, and some amoebae can cause disease in humans.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 15, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2023 Q#15 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q16_16", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 16, "subject": "Biology", "topic": "negative feedback in animals", "question": "Negative feedback mechanism is the characteristic of which class?", "options": ["Class Fish", "Class Amphibia", "Class Reptilia", "Class Mammalia"], "correctIndex": 3, "explanation": "Advanced thermoregulatory and endocrine negative feedback mechanisms are characteristic of mammals, which maintain internal constancy. Other classes have less sophisticated homeostatic control compared with mammals.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 16, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2023 Q#16 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q17_17", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 17, "subject": "Biology", "topic": "active site", "question": "The catalytic activity of an enzyme is restricted to its small portion:", "options": ["Active site", "Passive site", "Allosteric site", "Regulation site"], "correctIndex": 0, "explanation": "Enzymes catalyze reactions at their active site, a specific small region that binds substrate and performs catalysis. Allosteric sites regulate activity but are not where the primary catalysis occurs.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 17, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2023 Q#17 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q18_18", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 18, "subject": "Biology", "topic": "trypsin optimum ph", "question": "The maximum enzymatic activity of trypsin is shown at:", "options": ["pH 2", "pH 4", "pH 6", "pH 8"], "correctIndex": 3, "explanation": "Trypsin is a pancreatic protease that functions optimally in alkaline conditions around pH 8. Very acidic pH values (e.g., pH 2) are optimal for pepsin, not trypsin.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 18, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2023 Q#18 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q19_19", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 19, "subject": "Biology", "topic": "enzyme optimum temperature", "question": "Most enzyme have an optimum temperature of around:", "options": ["30 O C", "40 O C", "50 O C", "20 O C"], "correctIndex": 1, "explanation": "Many enzymes in warm‑blooded organisms have temperature optima near normal body temperature; the key here lists 40°C as the typical optimum. Lower or much higher temperatures generally reduce activity by slowing kinetics or causing denaturation.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 19, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2023 Q#19 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q20_20", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 20, "subject": "Biology", "topic": "activation energy", "question": "Enzyme work by lowering the of the reaction they catalyze:", "options": ["Kinetic energy", "Activation energy", "Heat energy", "Potential energy"], "correctIndex": 1, "explanation": "Enzymes accelerate reactions by lowering the activation energy barrier, allowing reactions to proceed faster at given conditions. They do not change the kinetic or potential energy of reactants in the general sense.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 20, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2023 Q#20 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q21_21", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 21, "subject": "Biology", "topic": "maximum temperature definition", "question": "In terms of enzyme action, maximum temperature refers to a temperature at which:", "options": ["Enzyme start to denature", "Enzyme start to re-nature", "Enzyme work best", "Enzyme are reactivated"], "correctIndex": 0, "explanation": "The maximum temperature for enzyme activity usually denotes the point beyond which enzyme structure becomes unstable and denaturation begins, causing activity to drop. 'Work best' refers to optimum temperature, which is lower than the denaturation threshold.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 21, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2023 Q#21 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q22_22", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 22, "subject": "Biology", "topic": "competitive inhibition", "question": "_____ reduces the enzyme activity by blocking the substrate from entering the active site due to similar shapes:", "options": ["Competitive inhibitors", "Non-competitive inhibitors", "Co-enzymes", "Activators"], "correctIndex": 0, "explanation": "Competitive inhibitors resemble the substrate and compete for binding at the enzyme's active site, decreasing activity. Non-competitive inhibitors bind elsewhere and change enzyme function, while coenzymes and activators facilitate activity.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 22, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2023 Q#22 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q23_23", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 23, "subject": "Biology", "topic": "darwin natural selection", "question": "He presented the theory of origin of species by means of natural selection:", "options": ["Lamarck", "Linnaeus", "Hardy-Weinberg", "Darwin"], "correctIndex": 3, "explanation": "Charles Darwin proposed that species evolve by natural selection, described in 'On the Origin of Species'. Lamarck proposed a different (inheritance of acquired traits) theory, and Linnaeus and Hardy-Weinberg are associated with classification and population genetics respectively.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 23, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "SZABMU 2023 Q#23 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2023"}, {"id": "paper_q24_24", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 24, "subject": "Biology", "topic": "fossil record prokaryotes", "question": "Among the oldest known fossils comes the:", "options": ["Prokaryotes", "Amphibians", "Reptiles", "Fishes"], "correctIndex": 0, "explanation": "The earliest fossils are microbial (prokaryotic) stromatolites and similar forms dating back billions of years; complex animals like amphibians, reptiles and fishes appear much later in the fossil record.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 24, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "SZABMU 2023 Q#24 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2023"}, {"id": "paper_q25_25", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 25, "subject": "Biology", "topic": "cck function", "question": "What is the contribution of hormone cholecystokinin?", "options": ["Facilitates bile release from gall bladder", "Mucus release from stomach", "Production of bile from liver", "Gastric juice release from stomach"], "correctIndex": 0, "explanation": "Cholecystokinin (CCK) stimulates gallbladder contraction and bile release into the small intestine to aid fat digestion. It does not stimulate mucus secretion, bile synthesis by the liver, or gastric juice release.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 25, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "SZABMU 2023 Q#25 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2023"}, {"id": "paper_q26_26", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 26, "subject": "Biology", "topic": "bile composition", "question": "Which of the following is not a component of bile?", "options": ["Digestive enzymes", "Salts", "Mucus", "Lecithin"], "correctIndex": 0, "explanation": "Bile contains bile salts, phospholipids (e.g., lecithin) and mucus-like substances but not digestive enzymes (those are secreted by the pancreas). Therefore 'digestive enzymes' is not a component of bile.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 26, "syllabusUnit": "Unit 5: Human Physiology - Digestion & Nutrition", "pmdcTopic": "Human Digestive System & Absorption Mechanisms", "textbookCitation": "PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12", "citationString": "SZABMU 2023 Q#26 | Unit 5: Human Physiology - Digestion & Nutrition | PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12"}, "year": "2023"}, {"id": "paper_q27_27", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 27, "subject": "Biology", "topic": "where protein digestion begins", "question": "The first chemical digestion of proteins takes place in the:", "options": ["Mouth", "Esophagus", "Stomach", "Intestine"], "correctIndex": 2, "explanation": "Protein chemical digestion begins in the stomach where pepsin (activated from pepsinogen by HCl) cleaves peptide bonds. The mouth and esophagus perform mechanical processing and the intestine continues chemical digestion with pancreatic enzymes.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 27, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2023 Q#27 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q28_28", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 28, "subject": "Biology", "topic": "cardiac cycle duration", "question": "Select the duration of cardiac cycle:", "options": ["0.6 sec", "0.4 sec", "0.7sec", "0.8 sec"], "correctIndex": 3, "explanation": "A normal resting human cardiac cycle is approximately 0.8 seconds (corresponding to a heart rate of ~75 bpm). The other durations correspond to higher or lower heart rates.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 28, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SZABMU 2023 Q#28 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2023"}, {"id": "paper_q29_29", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 29, "subject": "Biology", "topic": "stimulation of parietal and chief cells", "question": "Select the hormone which increases the activity of parietal and chief cells:", "options": ["Cholecystokinin", "Secretin", "Gastrin", "Acetylcholine"], "correctIndex": 2, "explanation": "The stem asks for a hormone, and gastrin is the hormone that stimulates the parietal cells to secrete acid and the chief cells to secrete pepsinogen. Acetylcholine also stimulates these cells but is a neurotransmitter, not a hormone; secretin and cholecystokinin act mainly on the pancreas and gallbladder.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 29, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2023 Q#29 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q30_30", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 30, "subject": "Biology", "topic": "symplast pathway", "question": "The pathways of water transport in which water moves through plasmodesmata is:", "options": ["Apoplast", "Symplast", "Vacuolar", "Ascent of sap"], "correctIndex": 1, "explanation": "The symplast pathway moves water through the cytoplasm of cells interconnected by plasmodesmata. The apoplast route moves via cell walls, and the vacuolar pathway passes through vacuoles; 'ascent of sap' is a broader term for upward water movement.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 30, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2023 Q#30 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q31_31", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 31, "subject": "Biology", "topic": "trypsinogen activation", "question": "Enzyme trypsinogen is activated by:", "options": ["HCL", "Pepsin", "Enterokinase", "Erypsin"], "correctIndex": 2, "explanation": "Trypsinogen, the inactive zymogen from the pancreas, is activated to trypsin by enterokinase (enteropeptidase) in the small intestine. HCl activates pepsinogen in the stomach; 'erypsin' is not the activating enzyme here.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 31, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2023 Q#31 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q32_32", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 32, "subject": "Biology", "topic": "emulsification by bile salts", "question": "Emulsification of large fat globules is facilitated by:", "options": ["Lipase", "Bile salts", "Trypsin", "Chymotrypsin"], "correctIndex": 1, "explanation": "Bile salts have amphipathic properties that break large fat globules into smaller droplets (emulsification), increasing surface area for lipase action. Lipase digests fats but does not emulsify them; trypsin and chymotrypsin are proteases.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 32, "syllabusUnit": "Unit 5: Human Physiology - Digestion & Nutrition", "pmdcTopic": "Human Digestive System & Absorption Mechanisms", "textbookCitation": "PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12", "citationString": "SZABMU 2023 Q#32 | Unit 5: Human Physiology - Digestion & Nutrition | PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12"}, "year": "2023"}, {"id": "paper_q33_33", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 33, "subject": "Biology", "topic": "mediastinum definition", "question": "The area between the two lungs is called:", "options": ["Periosteum", "Infundibulum", "Mediastinum", "Hilum"], "correctIndex": 2, "explanation": "The mediastinum is the central thoracic compartment between the lungs containing the heart, great vessels, trachea and esophagus. Periosteum is a bone covering, infundibulum is a funnel-like structure, and the hilum is the lung root.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 33, "syllabusUnit": "Unit 8: Human Physiology - Gas Exchange", "pmdcTopic": "Mechanisms of Breathing & Blood Gas Regulation", "textbookCitation": "PTB Biology XI Ch 13 (Gaseous Exchange); Federal Biology XI Ch 13", "citationString": "SZABMU 2023 Q#33 | Unit 8: Human Physiology - Gas Exchange | PTB Biology XI Ch 13 (Gaseous Exchange); Federal Biology XI Ch 13"}, "year": "2023"}, {"id": "paper_q34_34", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 34, "subject": "Biology", "topic": "left atrium venous return", "question": "In human heart, the left atrium receives:", "options": ["The Superior Vena Cava", "The Inferior Vena Cava", "The Coronary Sinus", "The four Pulmonary Veins"], "correctIndex": 3, "explanation": "The left atrium receives oxygenated blood from the lungs via the four pulmonary veins. The superior and inferior vena cavae and coronary sinus drain into the right atrium.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 34, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SZABMU 2023 Q#34 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2023"}, {"id": "paper_q35_35", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 35, "subject": "Biology", "topic": "virus parasitic nature", "question": "All viruses are:", "options": ["Autotrophs", "Heterotrophs", "Parasites", "Predators"], "correctIndex": 2, "explanation": "Viruses are obligate intracellular parasites that require host cellular machinery to replicate; they are not autotrophs, heterotrophs (terms used for organisms that feed), or predators.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 35, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "SZABMU 2023 Q#35 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2023"}, {"id": "paper_q36_36", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 36, "subject": "Biology", "topic": "bloodborne transmission hiv", "question": "Which of the following is transmitted through infected blood and hypothermal syringes?", "options": ["HIV", "Influenza Virus", "Morbilli Virus (Measles)", "Vibrio Virus (Cholera)"], "correctIndex": 0, "explanation": "HIV is commonly transmitted via infected blood and contaminated syringes. Influenza and measles are primarily respiratory-transmitted viruses, and cholera is a bacterial disease transmitted via contaminated water or food.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 36, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "SZABMU 2023 Q#36 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2023"}, {"id": "paper_q37_37", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 37, "subject": "Biology", "topic": "calvin cycle", "question": "Light independent phase of photosynthesis involves:", "options": ["Formation of energy rich carbohydrates", "Hydrolysis of water", "ATP generation", "Production of reducing molecules"], "correctIndex": 0, "explanation": "The light‑independent reactions (Calvin cycle) fix CO2 to produce energy-rich carbohydrates (e.g., triose phosphates). Hydrolysis of water, ATP and reducing equivalents generation occur in the light-dependent reactions.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 37, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "SZABMU 2023 Q#37 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2023"}, {"id": "paper_q38_38", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 38, "subject": "Biology", "topic": "chlorophyll magnesium", "question": "The element whose electrons are excited during light reaction of photosynthesis is:", "options": ["Carbon", "Hydrogen", "Magnesium", "Nitrogen"], "correctIndex": 2, "explanation": "Chlorophyll contains a central magnesium ion in the porphyrin ring; the pigment's electrons are excited during the light reactions. Carbon, hydrogen and nitrogen are present in biomolecules but magnesium is the key atom in chlorophyll's light-absorbing center.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 38, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "SZABMU 2023 Q#38 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2023"}, {"id": "paper_q39_39", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 39, "subject": "Biology", "topic": "fibrous proteins collagen", "question": "Select an example of fibrous protein:", "options": ["Enzymes", "Collagen", "Hemoglobin", "Hormones"], "correctIndex": 1, "explanation": "Collagen is a structural fibrous protein providing tensile strength in connective tissues. Enzymes and hormones are generally globular proteins; hemoglobin is a globular transport protein.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 39, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2023 Q#39 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q40_40", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 40, "subject": "Biology", "topic": "protein functions", "question": "Which function is NOT performed by proteins?", "options": ["Providing structural support to cell", "Catalyzing biochemical reactions", "Transporting materials across cell membrane", "Providing insulation against heat loss"], "correctIndex": 3, "explanation": "Proteins serve structural, catalytic and transport roles, but insulating against heat loss is primarily a function of adipose tissue (lipids) rather than proteins. Thus providing insulation is not a typical protein function.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 40, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2023 Q#40 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q41_41", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 41, "subject": "Biology", "topic": "triglyceride formation", "question": "Three hydrophobic fatty acid tails and a glycerol molecule join to form a:", "options": ["Monoglyceride", "Diglyceride", "Triglyceride", "Phospholipid"], "correctIndex": 2, "explanation": "A triglyceride consists of three fatty acid chains esterified to one glycerol molecule. Monoglycerides and diglycerides have one or two fatty acids; phospholipids have two fatty acids plus a phosphate-containing head group.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 41, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2023 Q#41 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q42_42", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 42, "subject": "Biology", "topic": "chemical energy c h bonds", "question": "Which bond is the potential source of chemical energy for cellular activities?", "options": ["C=O", "C-H", "C-R", "C-N"], "correctIndex": 1, "explanation": "C–H bonds are high-energy bonds in organic molecules and their oxidation releases energy cells can capture (e.g., in respiration). Other bonds can be important chemically, but C–H bonds are particularly central as energy sources.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 42, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2023 Q#42 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q43_43", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 43, "subject": "Biology", "topic": "water specific heat", "question": "Which property of water enables it to act as temperature stabilizer in living organisms?", "options": ["High polarity", "Being non polar", "High specific heat capacity", "High heat of vaporization"], "correctIndex": 2, "explanation": "Water's high specific heat capacity means it absorbs or releases relatively large amounts of heat with only small temperature change, buffering organisms against rapid thermal shifts. While polarity and heat of vaporization are important properties, specific heat is the stabilizing factor here.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 43, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2023 Q#43 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q44_44", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 44, "subject": "Biology", "topic": "membrane components", "question": "Which molecules do not contribute to the formation of biological membranes?", "options": ["Glycoproteins", "Glycolipids", "Phospholipids", "Nucleoproteins"], "correctIndex": 3, "explanation": "Biological membranes are composed of phospholipids, proteins (including glycoproteins) and glycolipids; nucleoproteins (DNA/RNA associated proteins) are not membrane components. Therefore nucleoproteins do not contribute to membrane structure.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 44, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2023 Q#44 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q45_45", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 45, "subject": "Biology", "topic": "sweetness of carbohydrates", "question": "Which of the following carbohydrates are sweetest among all?", "options": ["Monosaccharides", "Disaccharides", "Oligosaccharides", "Polysaccharides"], "correctIndex": 0, "explanation": "Simple sugars (monosaccharides like glucose and fructose) are the sweetest carbohydrate forms per unit, whereas polysaccharides are largely tasteless. Disaccharides are sweet but generally less so than some monosaccharides (e.g., fructose).", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 45, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2023 Q#45 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q46_46", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 46, "subject": "Biology", "topic": "lysosomes", "question": "Which organelles of animal cells are called suicidal bags?", "options": ["Peroxisomes", "Glyoxisomes", "Lysosomes", "Food Vacuoles"], "correctIndex": 2, "explanation": "Lysosomes contain hydrolytic enzymes that digest cellular components and, when released in large amounts, can lead to cell death - hence they are called 'suicidal bags'. Peroxisomes and glyoxisomes have different metabolic roles, and food vacuoles store ingested material rather than causing self-destruction.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 46, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2023 Q#46 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q47_47", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 47, "subject": "Biology", "topic": "fungal cell wall chitin", "question": "Chemically, cell wall of fungi is made up of:", "options": ["Cellulose", "Lignin", "Chitin", "Murein"], "correctIndex": 2, "explanation": "Fungal cell walls are primarily composed of chitin, a polymer of N-acetylglucosamine. Cellulose is typical of plant cell walls and murein (peptidoglycan) is found in bacterial cell walls.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 47, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2023 Q#47 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q48_48", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 48, "subject": "Biology", "topic": "golgi apparatus and neurotransmitters", "question": "The organelle which provides neurotransmitters in the nervous pathway is:", "options": ["Glyoxisome", "Peroxisome", "Golgi apparatus", "Endoplasmic reticulum"], "correctIndex": 2, "explanation": "The Golgi apparatus processes and packages proteins and secretory vesicles, including those carrying neurotransmitters for synaptic release. Peroxisomes and glyoxisomes are involved in metabolic reactions rather than packaging neurotransmitters.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 48, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2023 Q#48 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q49_49", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 49, "subject": "Biology", "topic": "mitochondrial cristae", "question": "The inner membrane of the mitochondria is folded to form finger like:", "options": ["Cisternae", "Cristae", "Chromatin", "Chloroplast"], "correctIndex": 1, "explanation": "The inner mitochondrial membrane folds into cristae, which increase surface area for electron transport and ATP production. Cisternae refer to flattened sacs of the Golgi or ER; chromatin and chloroplast are unrelated structures.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 49, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2023 Q#49 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q50_50", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 50, "subject": "Biology", "topic": "adenylate cyclase", "question": "Adenylate cyclase, in the cell membrane acts as:", "options": ["Channel protein", "Carrier protein", "Enzyme", "Receptor"], "correctIndex": 2, "explanation": "Adenylate (adenylyl) cyclase is an enzyme embedded in the cell membrane that converts ATP to cyclic AMP, a second messenger. It is not primarily a channel or carrier protein, though it is linked to receptor-mediated signaling.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 50, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2023 Q#50 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q51_51", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 51, "subject": "Biology", "topic": "cell inclusions", "question": "Glycogen, lipid droplets form the most important_________of the cell.", "options": ["Cell organelles", "Cell inclusions", "Cytoplasmic matrix", "Non membranous organelles"], "correctIndex": 1, "explanation": "Glycogen and lipid droplets are stored substances within the cytoplasm and are classified as cell inclusions rather than membrane-bound organelles. They are not the cytoplasmic matrix itself nor general non-membranous organelles.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 51, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2023 Q#51 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q52_52", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 52, "subject": "Biology", "topic": "vaccination classification", "question": "Vaccination is an example of:", "options": ["Natural passive immunity", "Natural active immunity", "Acquired/Artificial active immunity", "Acquired/Artificial passive immunity"], "correctIndex": 2, "explanation": "Vaccination introduces an antigen to stimulate the recipient's own immune system to produce a protective response, which is acquired (artificial) active immunity. Passive immunity would involve transfer of antibodies rather than immunization.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 52, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2023 Q#52 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q53_53", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 53, "subject": "Biology", "topic": "lymphatic system components", "question": "Lymphatic system contains all of the following organs / structures except:", "options": ["Lymphoid masses", "Lymph vessels", "Spleen", "Lungs"], "correctIndex": 3, "explanation": "The lymphatic system includes lymphoid masses (e.g., tonsils), lymph vessels, and the spleen, but not the lungs, which belong to the respiratory system. Thus lungs are the correct exception.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 53, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SZABMU 2023 Q#53 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2023"}, {"id": "paper_q54_54", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 54, "subject": "Biology", "topic": "peptidoglycan in bacterial cell wall", "question": "The unique macro-molecule in the bacterial cell wall is:", "options": ["Polysaccharides", "Proteins", "Peptidoglycan", "Cholesterol"], "correctIndex": 2, "explanation": "Bacterial cell walls characteristically contain peptidoglycan (murein), a mesh of sugar and peptide chains unique to bacteria. Cholesterol is a eukaryotic membrane component and the other choices are not the defining bacterial wall polymer.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 54, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2023 Q#54 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q55_55", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 55, "subject": "Biology", "topic": "transduction", "question": "Transfer of genetic material from one bacterium to another through a third party usually bacteriophage is called:", "options": ["Conjugation", "Transformation", "Transduction", "Transportation"], "correctIndex": 2, "explanation": "Transduction is the process in which bacteriophages carry bacterial DNA from one host to another, mediating horizontal gene transfer. Conjugation involves direct cell-to-cell transfer and transformation involves uptake of free DNA.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 55, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "SZABMU 2023 Q#55 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2023"}, {"id": "paper_q56_56", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 56, "subject": "Biology", "topic": "methods to control bacteria", "question": "All of the following are physical methods to control bacteria except:", "options": ["Sterilization", "Boiling", "Radiation", "Antiseptics"], "correctIndex": 3, "explanation": "Antiseptics are chemical agents applied to living tissues and therefore are not physical methods; sterilization, boiling, and radiation are physical means for bacterial control. The question asks for the exception, so antiseptics is correct.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 56, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "SZABMU 2023 Q#56 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2023"}, {"id": "paper_q57_57", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 57, "subject": "Biology", "topic": "vaccines and immunity", "question": "Which of the following helps in developing immunity against germs?", "options": ["Radiotherapy", "Chemotherapy", "Vaccines", "Antibiotics"], "correctIndex": 2, "explanation": "Vaccines stimulate the immune system to develop protective immunity against pathogens. Radiotherapy and chemotherapy are treatments for cancer and antibiotics treat bacterial infections but do not develop active immunity.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 57, "syllabusUnit": "Unit 7: Human Physiology - Immunity", "pmdcTopic": "Innate & Adaptive Immunity, Immunoglobulins and Vaccines", "textbookCitation": "PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14", "citationString": "SZABMU 2023 Q#57 | Unit 7: Human Physiology - Immunity | PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14"}, "year": "2023"}, {"id": "paper_q58_58", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 58, "subject": "Biology", "topic": "zygote transport time", "question": "After fertilization, zygote takes________for its journey from fallopian tube to uterus:", "options": ["6-7 days", "3-6 days", "10-12 days", "12-15 days"], "correctIndex": 0, "explanation": "The zygote (morula/blastocyst) typically travels from the fallopian tube into the uterus in about 6–7 days after fertilization, allowing implantation to occur around that time. Shorter or longer intervals listed are not the standard timing.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 58, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "SZABMU 2023 Q#58 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2023"}, {"id": "paper_q59_59", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 59, "subject": "Biology", "topic": "temperature for spermatogenesis", "question": "The best temperature forspermatogenesis is:", "options": ["37 O C", "30 O C", "32 O C", "35 O C"], "correctIndex": 3, "explanation": "Spermatogenesis in humans requires a scrotal temperature slightly lower than core body temperature; the optimal temperature is around 35°C, which is why testes are externalized in the scrotum. Higher core temperature (37°C) is less favorable.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 59, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "SZABMU 2023 Q#59 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2023"}, {"id": "paper_q60_60", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 60, "subject": "Biology", "topic": "fsh function in females", "question": "In human females, FSH stimulates:", "options": ["Follicle development", "Ovulation", "Embryo implantation", "Menstruation"], "correctIndex": 0, "explanation": "Follicle-stimulating hormone (FSH) promotes growth and maturation of ovarian follicles in females. Ovulation is primarily triggered by the LH surge; implantation and menstruation are downstream events not directly stimulated by FSH.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 60, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2023 Q#60 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q61_61", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 61, "subject": "Biology", "topic": "leydig cells", "question": "Leydig cells in testes are responsible for:", "options": ["Testosterone production", "FSH production", "Sperm production", "Testosterone inhibition"], "correctIndex": 0, "explanation": "Leydig (interstitial) cells synthesize and secrete testosterone under LH stimulation, which supports spermatogenesis. FSH acts on Sertoli cells to support sperm production; Leydig cells do not produce FSH.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 61, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "SZABMU 2023 Q#61 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q62_62", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 62, "subject": "Biology", "topic": "muscle contraction atp", "question": "The muscle contraction involve the breakdown of cross bridges of active myosin filaments due to the following process:", "options": ["ATP is oxidized", "ATP is reduced", "ATP is hydrolyzed", "ATP is synthesized"], "correctIndex": 2, "explanation": "ATP hydrolysis provides the energy for myosin head detachment and resetting during the cross-bridge cycle in muscle contraction. This is a hydrolysis step, not oxidation/reduction or synthesis in that immediate context.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 62, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2023 Q#62 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q63_63", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 63, "subject": "Biology", "topic": "osteoarthritis definition", "question": "________ is the inflammation of joints:", "options": ["Osteoarthritis", "Osteoporosis", "Arteriosclerosis", "Osteosclerosis"], "correctIndex": 0, "explanation": "Osteoarthritis is a degenerative joint disease characterized by breakdown of cartilage and joint inflammation. The other terms refer to bone thinning (osteoporosis), arterial hardening (arteriosclerosis), and abnormal bone hardening (osteosclerosis).", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 63, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "SZABMU 2023 Q#63 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2023"}, {"id": "paper_q64_64", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 64, "subject": "Biology", "topic": "tetany and calcium", "question": "Tetany is caused by ________ in blood.", "options": ["Low Ca++", "High Ca++", "Low Mg++", "High Mg++"], "correctIndex": 0, "explanation": "Tetany (muscle spasms and cramps) commonly occurs with hypocalcemia (low blood calcium), which increases neuronal excitability. Hypercalcemia or magnesium disturbances produce different clinical features.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 64, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "SZABMU 2023 Q#64 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2023"}, {"id": "paper_q65_65", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 65, "subject": "Biology", "topic": "myoglobin function", "question": "What is the function of myoglobin?", "options": ["Store oxygen", "Store CO2", "Transport oxygen", "Transport CO2"], "correctIndex": 0, "explanation": "Myoglobin acts as an oxygen storage molecule in muscle cells, binding O2 and releasing it during periods of high demand. Hemoglobin is the primary transporter of oxygen in the blood.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 65, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2023 Q#65 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q66_66", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 66, "subject": "Biology", "topic": "synovial joint", "question": "A joint in which ends of bones are covered with hyaline cartilage and held together by surrounding tube like capsule of dense fibrous tissue:", "options": ["Cartilaginous Joint", "Synovial Joint", "Fibrous Joint", "Immoveable Joint"], "correctIndex": 1, "explanation": "A synovial joint has articulating bone ends covered with hyaline cartilage and enclosed in a fibrous capsule with a synovial membrane. Cartilaginous and fibrous joints have different structural arrangements.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 66, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "SZABMU 2023 Q#66 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2023"}, {"id": "paper_q67_67", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 67, "subject": "Biology", "topic": "linked genes", "question": "These are the genes which tend to be inherited together and do not assort independently:", "options": ["Linked genes", "Dependent genes", "Recombinant genes", "Independent genes"], "correctIndex": 0, "explanation": "Linked genes are located close together on the same chromosome and tend to be inherited together because crossing-over between them is infrequent. Recombinant or independent genes assort according to different principles.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 67, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2023 Q#67 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q68_68", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 68, "subject": "Biology", "topic": "mendelian dominance", "question": "Mendelian inheritance follows which form of dominance relation?", "options": ["Complete dominance", "Incomplete dominance", "Co-dominance", "Multiple allelic dominance"], "correctIndex": 0, "explanation": "Classic Mendelian inheritance is described by complete dominance, where one allele masks the expression of another in a heterozygote. Incomplete and co-dominance are non-Mendelian or modified inheritance patterns.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 68, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "SZABMU 2023 Q#68 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2023"}, {"id": "paper_q69_69", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 69, "subject": "Physics", "topic": "units of kinetic energy", "question": "The unit of kinetic energy is same as that of:", "options": ["Work", "Power / Time", "Time / Power", "Work / Time"], "correctIndex": 0, "explanation": "Kinetic energy and work have the same SI unit (joule). Power is energy per time, so options involving power/time are not equivalent to energy units.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 69, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SZABMU 2023 Q#69 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q70_70", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 70, "subject": "Physics", "topic": "centripetal force source", "question": "Which one provides centripetal force in a circular motion of a body?", "options": ["Vertical component of weight", "Horizontal component of weight", "Weight of the body", "Force of friction"], "correctIndex": 3, "explanation": "For a body moving in a circle on a level surface, the centripetal force pointing toward the centre is supplied by friction — for example, between a car's tyres and the road. Weight acts vertically downward and cannot by itself provide the horizontal centripetal force.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 70, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2023 Q#70 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q71_71", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 71, "subject": "Physics", "topic": "radians per degree", "question": "How many radians are in one degree?", "options": ["0.0174 rad", "0.174 rad", "1.745 rad", "0.00174 rad"], "correctIndex": 0, "explanation": "One degree equals π/180 radians ≈ 0.0174533 rad, rounded here to 0.0174 rad. The other values are orders of magnitude off.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 71, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "SZABMU 2023 Q#71 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "paper_q72_72", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 72, "subject": "Physics", "topic": "rpm to radians per second", "question": "Which one of the following is the angular velocity of an electric motor if it rotates at 400 rpm?", "options": ["51.2 rad/s", "41.9 rad/s", "45.2 rad/s", "38.5 rad/s"], "correctIndex": 1, "explanation": "Angular velocity ω = 2π × (rpm)/60. For 400 rpm, ω = 2π × (400/60) ≈ 41.8879 rad/s, which matches 41.9 rad/s. The other answers are not consistent with that calculation.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 72, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2023 Q#72 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q73_73", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 73, "subject": "Physics", "topic": "tension at top of vertical circle", "question": "The tension is string at top of vertical circle is:", "options": ["Zero", "mg", "2mg", "3mg"], "correctIndex": 0, "explanation": "At the minimal speed required to maintain contact at the top of a vertical circle, the tension can be zero because gravity alone provides the required centripetal force (mv^2/r = mg). For higher speeds, tension would be positive.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 73, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "SZABMU 2023 Q#73 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "paper_q74_74", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 74, "subject": "Physics", "topic": "centripetal force expressions", "question": "The centripetal force in terms of angular velocity is given by:", "options": ["F c = m r ω", "F c = m r ω^2", "F c = m r α^2", "F c = m r α"], "correctIndex": 1, "explanation": "Centripetal force is F = m r ω^2 when expressed using angular velocity ω. Expressions involving α (angular acceleration) are not the correct formula for centripetal force.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 74, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2023 Q#74 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q75_75", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 75, "subject": "Physics", "topic": "earth rotation angular speed", "question": "Which one of the following is angular speed in radian per hour for daily rotation of our earth?", "options": ["2 π", "4 π", "π /6", "π /12"], "correctIndex": 3, "explanation": "The Earth completes one full rotation of 2 pi radians in 24 hours, so its angular speed is 2 pi / 24 = pi/12 radians per hour.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 75, "syllabusUnit": "Unit 3: Circular and Rotational Motion", "pmdcTopic": "Centripetal Acceleration, Angular Velocity & Rotational Dynamics", "textbookCitation": "PTB Physics XI Ch 5 (Circular Motion); Federal Physics XI Ch 5", "citationString": "SZABMU 2023 Q#75 | Unit 3: Circular and Rotational Motion | PTB Physics XI Ch 5 (Circular Motion); Federal Physics XI Ch 5"}, "year": "2023"}, {"id": "paper_q76_76", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 76, "subject": "Physics", "topic": "wavelength definition", "question": "Wavelength of wave is defined as:", "options": ["Distance between two consecutive crests", "Distance between two alternate crest", "Distance between two alternate trough", "Distance between two crest and two trough"], "correctIndex": 0, "explanation": "Wavelength is the spatial distance between two consecutive crests (or equivalently two consecutive troughs) of a wave. The other options describe incorrect or ambiguous intervals.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 76, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "SZABMU 2023 Q#76 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2023"}, {"id": "paper_q77_77", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 77, "subject": "Physics", "topic": "factors affecting speed of sound", "question": "Which of the following factor does not affect the speed of sound in air?", "options": ["Pressure", "Density", "Temperature", "Medium"], "correctIndex": 0, "explanation": "At a fixed temperature the speed of sound in air does not change with pressure: for an ideal gas, pressure and density change together so their ratio stays constant. Speed of sound does depend on temperature and on the medium, so pressure is the factor that does not affect it.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 77, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "SZABMU 2023 Q#77 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2023"}, {"id": "paper_q78_78", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 78, "subject": "Physics", "topic": "amplitude definition", "question": "Maximum displacement of particles form it mean position is called:", "options": ["Frequency", "Amplitude", "Wavelength", "Crest"], "correctIndex": 1, "explanation": "Amplitude is the maximum displacement of particles from their mean (equilibrium) position in a wave. Frequency measures cycles per time, wavelength is spatial period, and crest is a high point.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 78, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2023 Q#78 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q79_79", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 79, "subject": "Physics", "topic": "ultrasonic frequency threshold", "question": "The ultrasonic waves have frequency higher than:", "options": ["20 Hz", "20 KHz", "200 Hz", "2000 KHz"], "correctIndex": 1, "explanation": "Ultrasound is defined as sound with frequency above the audible range for humans, typically above about 20 kHz. The other frequency choices are within or far beyond typical ultrasonic ranges.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 79, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "SZABMU 2023 Q#79 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2023"}, {"id": "paper_q80_80", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 80, "subject": "Physics", "topic": "speed of sound temperature coefficient", "question": "The increase in the speed of sound for each degree rise above 0o C is:", "options": ["0.61 m/s", "0.51 m/s", "0.41 m/s", "0.31 m/s"], "correctIndex": 0, "explanation": "A common approximation is that speed of sound in air increases by about 0.6 m/s per °C; the listed option 0.61 m/s matches that empirical value. The other values are significantly different from the standard coefficient.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 80, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "SZABMU 2023 Q#80 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2023"}, {"id": "paper_q81_81", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 81, "subject": "Physics", "topic": "periodic waves definition", "question": "Continuous, regular and rhythmic disturbance in a medium resulting periodic vibration of a source causes________in the medium:", "options": ["Complex waves", "Stationary waves", "Electromagnetic waves", "Periodic waves"], "correctIndex": 3, "explanation": "A continuous, regular rhythmic disturbance that repeats over time produces periodic waves in the medium. Stationary and complex waves are specific phenomena and electromagnetic waves are a different category (do not require a medium).", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 81, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "SZABMU 2023 Q#81 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2023"}, {"id": "paper_q82_82", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 82, "subject": "Physics", "topic": "isochoric process", "question": "The thermodynamic process during which volume of the system remains constant is called:", "options": ["Isothermal", "Isobaric", "Isochoric", "Adiabatic"], "correctIndex": 2, "explanation": "An isochoric (or isovolumetric) process occurs at constant volume. Isothermal is constant temperature, isobaric is constant pressure, and adiabatic is without heat exchange.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 82, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "SZABMU 2023 Q#82 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "paper_q83_83", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 83, "subject": "Physics", "topic": "boyles law condition", "question": "The conditions for application of Boyle’s law holds good in:", "options": ["Adiabatic process", "Isothermal process", "Isobaric process", "Isochoric process"], "correctIndex": 1, "explanation": "Boyle's law (PV = constant) applies to ideal gases undergoing isothermal (constant temperature) changes. In adiabatic processes temperature changes, so Boyle's law does not directly apply.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 83, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "SZABMU 2023 Q#83 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "paper_q84_84", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 84, "subject": "Physics", "topic": "internal energy isothermal", "question": "The internal energy of a system during an isothermal process:", "options": ["Decreases", "Increases", "Becomes zero", "Remains constant"], "correctIndex": 3, "explanation": "For an ideal gas, internal energy depends only on temperature; during an isothermal process the temperature is constant, so internal energy remains constant. The other choices contradict that principle.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 84, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SZABMU 2023 Q#84 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q85_85", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 85, "subject": "Physics", "topic": "gausss law", "question": "Electric intensity due to charge distributions are calculated using which following law?", "options": ["Ohm’s law", "Faraday’s law", "Gauss’s law", "Ampere’s law"], "correctIndex": 2, "explanation": "Gauss's law relates electric flux through a closed surface to the enclosed charge and is commonly used to calculate electric fields from symmetric charge distributions. Ohm's and Faraday's laws refer to different phenomena.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 85, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "SZABMU 2023 Q#85 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2023"}, {"id": "paper_q86_86", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 86, "subject": "Physics", "topic": "capacitance dependence", "question": "The capacitance of capacitor does not depend on:", "options": ["Area of plates", "Medium", "Distance between plates", "Thickness of plates"], "correctIndex": 3, "explanation": "Ideal parallel-plate capacitance depends on plate area, dielectric (medium) and separation distance; plate thickness (assuming conductors) does not affect capacitance significantly and so is not a factor in the ideal formula.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 86, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "SZABMU 2023 Q#86 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2023"}, {"id": "paper_q87_87", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 87, "subject": "Physics", "topic": "unit of potential difference", "question": "The SI unit of potential difference is:", "options": ["Volt", "Coulomb", "Watt", "eV"], "correctIndex": 0, "explanation": "The SI unit of electric potential difference (voltage) is the volt. Coulomb is unit of charge, watt is unit of power, and eV is an energy unit (electronvolt), not an SI base unit for potential difference.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 87, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SZABMU 2023 Q#87 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q88_88", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 88, "subject": "Physics", "topic": "electric potential definition", "question": "Electric potential is defined as:", "options": ["Work per unit charge", "Force per unit charge", "Power per unit charge", "Force"], "correctIndex": 0, "explanation": "Electric potential at a point is defined as the work done per unit positive test charge to bring it from infinity to that point. Force per unit charge is electric field (not potential).", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 88, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SZABMU 2023 Q#88 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q89_89", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 89, "subject": "Physics", "topic": "ohm metre unit of resistivity", "question": "Ohm meter us the unit of:", "options": ["Resistance", "Resistivity", "Conductance", "conductivity"], "correctIndex": 1, "explanation": "Ohm-metre (Ω·m) is the SI unit of resistivity (a material property). Resistance has unit ohm (Ω); conductance and conductivity have different units.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 89, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "SZABMU 2023 Q#89 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2023"}, {"id": "paper_q90_90", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 90, "subject": "Physics", "topic": "electronvolt joule conversion", "question": "1eV is equal to:", "options": ["1.602 x 10-19 J", "16.02 x 10-19 J", "1620 J", "162.0 x 10-19 J"], "correctIndex": 0, "explanation": "One electronvolt (eV) equals the kinetic energy gained by an electron accelerated through a potential difference of one volt, which equals 1.602 × 10^-19 joules. The other numerical options are incorrect representations of this value.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 90, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "SZABMU 2023 Q#90 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "paper_q91_91", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 91, "subject": "Physics", "topic": "electrical resistance", "question": "The total resistance of wire isinversely proportional to:", "options": ["Length", "Area", "Temperature", "Time"], "correctIndex": 1, "explanation": "Resistance of a uniform wire is directly proportional to its length and inversely proportional to its cross‑sectional area (R = ρL/A). Therefore the correct inverse dependence is on area; the other options are not the inverse relation.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 91, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "SZABMU 2023 Q#91 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2023"}, {"id": "paper_q92_92", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 92, "subject": "Physics", "topic": "energy units", "question": "Kilowatt hour is a unit of:", "options": ["Energy", "Energy x time", "Power", "(power)(energy)"], "correctIndex": 0, "explanation": "A kilowatt‑hour (kWh) is a unit of energy (power × time). It measures the amount of energy consumed by a 1 kW load running for one hour, so it is not a unit of power or power×energy.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 92, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SZABMU 2023 Q#92 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q93_93", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 93, "subject": "Physics", "topic": "magnetic force angle", "question": "The force exerted on charged particle will be maximum when it enters the magnetic field at:", "options": ["60O", "90O", "0O", "45O"], "correctIndex": 1, "explanation": "Magnetic force on a moving charge is F = qvB sinθ, maximized when sinθ = 1 i.e. θ = 90°. At 0° there is no magnetic force; other angles give intermediate values.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 93, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2023 Q#93 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q94_94", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 94, "subject": "Physics", "topic": "motion in magnetic field", "question": "When a charged particle enters the magnetic field parallel then it will:", "options": ["Deflect toward north", "Deflect toward south", "Move straight", "Move in circular path"], "correctIndex": 2, "explanation": "If velocity is parallel to the magnetic field (θ = 0°) the magnetic force qv×B = 0, so the particle continues straight. Deflection or circular motion requires a perpendicular component to B.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 94, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "SZABMU 2023 Q#94 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2023"}, {"id": "paper_q95_95", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 95, "subject": "Physics", "topic": "elastic collision energy conservation", "question": "Two balls collide each other, it has been observed that the collision is elastic. Which statement is advocates the observation?", "options": ["K.E before collision = K.E after collision", "Momentum before collision = Momentum after collision", "K.E before collision ≠ K.E after collision", "Momentum before collision ≠ Momentum after collision"], "correctIndex": 0, "explanation": "In an elastic collision kinetic energy is conserved (K.E before = K.E after). Momentum is also conserved in all isolated collisions, but conservation of kinetic energy specifically indicates an elastic collision.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 95, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2023 Q#95 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q96_96", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 96, "subject": "Physics", "topic": "acceleration definition", "question": "The gradient of velocity time is equal to:", "options": ["Distance", "Force", "Acceleration", "Speed"], "correctIndex": 2, "explanation": "The slope (gradient) of a velocity–time graph gives acceleration (change of velocity per unit time). It is not distance, force or speed.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 96, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2023 Q#96 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q97_97", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 97, "subject": "Physics", "topic": "projectile range angle complementary", "question": "At what pair of angles for a projectile, the ranges are equal?", "options": ["20O, 60O", "60O, 30O", "40O, 60O", "25O, 55O"], "correctIndex": 1, "explanation": "Projectile ranges are equal for complementary angles that add to 90° (e.g., 60° and 30°). Options that do not add to 90° will give different ranges.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 97, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2023 Q#97 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q98_98", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 98, "subject": "Physics", "topic": "relative velocity", "question": "Two car traveling on straight road in opposite direction with speed 70 kmh-1 and 60 kmh-1, their relative velocity will be:", "options": ["10 kmh-1", "130 kmh-1", "65 kmh-1", "5 kmh-1"], "correctIndex": 1, "explanation": "When two objects move in opposite directions, relative speed is the sum of magnitudes: 70 + 60 = 130 km/h. The other choices are incorrect combinations.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 98, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2023 Q#98 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q99_99", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 99, "subject": "Physics", "topic": "elastic collision equal masses", "question": "Two bodies having same mass undergo elastic collision then their velocities after collision will be:", "options": ["v1' = 0 v2' = v1", "v1' = v2 v2' = 0", "v1' = v1 v2' = v2", "v1' = v2 v2' = v1"], "correctIndex": 3, "explanation": "For an elastic head‑on collision of equal masses, they exchange velocities: v1' = v2 and v2' = v1. The other listed outcomes do not match this well‑known result.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 99, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2023 Q#99 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q100_100", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 100, "subject": "Physics", "topic": "projectile angle equality of height and range", "question": "The angle of projection of a projectile for which its maximum height and horizontal range are equal is:", "options": ["86O", "46 O", "66 O", "76 O"], "correctIndex": 3, "explanation": "This is a specific projectile problem solved by equating H and R expressions; the printed answer is 76°. The other angles do not satisfy the equality.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 100, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2023 Q#100 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q101_101", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 101, "subject": "Physics", "topic": "distance time slope", "question": "Slope of distance time graph can never be:", "options": ["Positive", "Negative", "Constant", "Zero"], "correctIndex": 1, "explanation": "Distance (not displacement) is a scalar and cannot decrease with time, so the slope (speed) of a distance–time graph cannot be negative. It can be positive, zero or constant.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 101, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "SZABMU 2023 Q#101 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "paper_q102_102", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 102, "subject": "Physics", "topic": "projectile velocity components", "question": "At highest point in a projectile motion, the velocity will be:", "options": ["Vx = 0 Vy = 0", "Vx = 0 Vy = constant", "Vx = constant Vy = constant", "Vx = constant Vy = 0"], "correctIndex": 3, "explanation": "At the peak the vertical component Vy = 0 while the horizontal component Vx remains constant (neglecting air resistance). So Vx = constant, Vy = 0 is correct.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 102, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2023 Q#102 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q103_103", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 103, "subject": "Physics", "topic": "power unit british", "question": "The unit of power in British engineering system is:", "options": ["Horse power", "Watt", "Js-1", "Js"], "correctIndex": 0, "explanation": "The traditional British engineering unit for power is horsepower. Watt (J/s) is the SI unit; Js and Js-1 are not the standard British unit.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 103, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SZABMU 2023 Q#103 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q104_104", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 104, "subject": "Physics", "topic": "work sign", "question": "Work done will be negative if the angle between force and displacement is:", "options": ["0 O", "45 O", "60 O", "180 O"], "correctIndex": 3, "explanation": "Work = F·s·cosθ; it is negative when cosθ is negative, which occurs for θ = 180°, i.e. force opposite to displacement. Smaller acute angles give positive work.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 104, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2023 Q#104 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q105_105", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 105, "subject": "Physics", "topic": "unit watt", "question": "Nms-1 = :", "options": ["1 Kilo watt hour", "1 J.s", "1 watt", "1 J.s-2"], "correctIndex": 2, "explanation": "1 N·m·s^-1 equals 1 J·s^-1, which is 1 watt. The other units are not equal to J·s^-1.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 105, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "SZABMU 2023 Q#105 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "paper_q106_106", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 106, "subject": "Physics", "topic": "work against friction", "question": "In inter-conversion of energy, the work done against the friction is:", "options": ["f + h", "f - h", "fh", "f / h"], "correctIndex": 2, "explanation": "The printed answer indicates the work term is represented as the product f·h (friction force times distance). Other algebraic combinations shown do not represent work as force×distance.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 106, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "SZABMU 2023 Q#106 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q107_107", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 107, "subject": "Physics", "topic": "kinetic energy change", "question": "A car of mass 800 Kg accelerates from 20m-1 to 30ms-1, the increase in K.E is:", "options": ["2 J", "200 KJ", "200 J", "2 KJ"], "correctIndex": 1, "explanation": "ΔKE = 0.5·m·(v^2−u^2) = 0.5·800·(900−400) = 400·500 = 200000 J = 200 kJ. The other numeric choices are incorrect by orders of magnitude.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 107, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SZABMU 2023 Q#107 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q108_108", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 108, "subject": "Physics", "topic": "fleming right hand rule", "question": "In Fleming’s right hand rule the middle finger indicates:", "options": ["Force", "Magnetic field", "Induced current", "Volt"], "correctIndex": 2, "explanation": "In Fleming’s right‑hand rule (for generators) the thumb = motion/force, index = magnetic field, middle finger = induced current. So the middle finger denotes induced current.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 108, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "SZABMU 2023 Q#108 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "paper_q109_109", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 109, "subject": "Physics", "topic": "transformer principle", "question": "Transformer works on the principle of:", "options": ["Lenz’s Law", "Faraday’s Law", "Mutual Induction", "Ampere’s Law"], "correctIndex": 2, "explanation": "A transformer operates by mutual induction between coils: a changing current in the primary induces a changing flux and hence an emf in the secondary. While Faraday’s law underlies induction, the direct principle named for transformers is mutual induction.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 109, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SZABMU 2023 Q#109 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q110_110", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 110, "subject": "Physics", "topic": "transformer efficiency", "question": "The efficiency of transformer is:", "options": ["60 %", "70 %", "80 %", "90 %"], "correctIndex": 3, "explanation": "Transformers are typically highly efficient devices; the printed answer indicates about 90% efficiency, higher than the other listed percentages.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 110, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SZABMU 2023 Q#110 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q111_111", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 111, "subject": "Physics", "topic": "lenz law conservation", "question": "Lenz’s law is also a statement of law of conservation of:", "options": ["Charge", "Energy", "Momentum", "Mass"], "correctIndex": 1, "explanation": "Lenz’s law ensures the induced emf opposes the change causing it, which enforces conservation of energy by preventing spontaneous creation of energy. It is not a statement about charge, momentum or mass.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 111, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "SZABMU 2023 Q#111 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2023"}, {"id": "paper_q112_112", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 112, "subject": "Physics", "topic": "rectification half wave", "question": "A process in which only one half of alternating current is converted into direct current is called:", "options": ["Full wave rectification", "Amplification", "Half wave rectification", "Magnification"], "correctIndex": 2, "explanation": "Converting only one half‑cycle of AC into DC is half‑wave rectification. Full‑wave rectification uses both half cycles; the other terms are unrelated.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 112, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "SZABMU 2023 Q#112 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2023"}, {"id": "paper_q113_113", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 113, "subject": "Physics", "topic": "rectifier efficiency", "question": "Efficiency of full wave rectifier circuit is almost________than half wave rectifier circuit:", "options": ["Four times", "Same as", "Sixteen times", "Double"], "correctIndex": 3, "explanation": "A full‑wave rectifier uses both halves of the input waveform and therefore has roughly double the efficiency compared with a half‑wave rectifier; the other factors are incorrect comparisons.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 113, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SZABMU 2023 Q#113 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q114_114", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 114, "subject": "Physics", "topic": "diode as rectifier", "question": "The conversion of alternating current into direct current is called rectification and circuit is called rectifier. Which component of electronics acts as a rectifier?", "options": ["Diode", "Transistor", "Transformer", "Inductor"], "correctIndex": 0, "explanation": "A diode allows current flow primarily in one direction and is the elementary component used as a rectifier. Transistors, transformers and inductors do not by themselves perform single‑component rectification.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 114, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "SZABMU 2023 Q#114 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2023"}, {"id": "paper_q115_115", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 115, "subject": "Physics", "topic": "red light photography", "question": "Red light is used in photographic dark room because of:", "options": ["More frequency, less wavelength", "Less frequency, less wavelength", "Less frequency, more wavelength", "More frequency, more wavelength"], "correctIndex": 2, "explanation": "Red light has lower frequency and longer wavelength compared with other visible light; many photographic papers are not sensitive to red wavelengths, so red light is used in darkrooms.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 115, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "SZABMU 2023 Q#115 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "paper_q116_116", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 116, "subject": "Physics", "topic": "photon energy wavelength", "question": "Which photons carries the most energy?", "options": ["Blue", "Violet", "Red", "Green"], "correctIndex": 1, "explanation": "Photon energy is proportional to frequency; violet light has the highest frequency among the listed colors, so violet photons carry the most energy.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 116, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "SZABMU 2023 Q#116 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q117_117", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 117, "subject": "Physics", "topic": "hydrogen series uv", "question": "Which one of the following series lies in the ultraviolet region?", "options": ["Balmer series", "Paschen series", "Lyman series", "Bracket series"], "correctIndex": 2, "explanation": "The Lyman series of hydrogen involves transitions to n=1 and lies in the ultraviolet region. Balmer is visible, Paschen and Brackett are in the infrared.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 117, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "SZABMU 2023 Q#117 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "paper_q118_118", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 118, "subject": "Physics", "topic": "x ray photon wavelength", "question": "Which x-ray photon will have longest wavelength?", "options": ["Kα", "Kβ", "Kγ", "Mα"], "correctIndex": 0, "explanation": "Within the K-series, the K-alpha transition has the smallest energy gap, and lower photon energy means longer wavelength. So K-alpha X-rays have the longest wavelength of the K-series options here.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 118, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "SZABMU 2023 Q#118 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2023"}, {"id": "paper_q119_119", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 119, "subject": "Physics", "topic": "iodine half life", "question": "The half-life of Iodine – 31 is:", "options": ["10 days", "8 days", "45 days", "60 days"], "correctIndex": 1, "explanation": "The printed answer indicates a half‑life of 8 days for Iodine‑31. The other durations do not match the given value.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 119, "syllabusUnit": "Unit 12: Atomic and Nuclear Physics", "pmdcTopic": "Bohr Model, Radioactivity & Nuclear Reactions", "textbookCitation": "PTB Physics XII Ch 20 (Atomic Spectra) & Ch 21 (Nuclear Physics); Federal Physics XII Ch 18-19", "citationString": "SZABMU 2023 Q#119 | Unit 12: Atomic and Nuclear Physics | PTB Physics XII Ch 20 (Atomic Spectra) & Ch 21 (Nuclear Physics); Federal Physics XII Ch 18-19"}, "year": "2023"}, {"id": "paper_q120_120", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 120, "subject": "Physics", "topic": "carbon half life decay", "question": "The half-life of carbon is 5730 years. How much carbon will left after 22920 years?", "options": ["1/32nd", "1/16th", "1/64th", "1/4th"], "correctIndex": 1, "explanation": "22920 years is four half‑lives (22920/5730 = 4), so remaining fraction = (1/2)^4 = 1/16. The other fractions correspond to different numbers of half‑lives.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 120, "syllabusUnit": "Unit 12: Atomic and Nuclear Physics", "pmdcTopic": "Bohr Model, Radioactivity & Nuclear Reactions", "textbookCitation": "PTB Physics XII Ch 20 (Atomic Spectra) & Ch 21 (Nuclear Physics); Federal Physics XII Ch 18-19", "citationString": "SZABMU 2023 Q#120 | Unit 12: Atomic and Nuclear Physics | PTB Physics XII Ch 20 (Atomic Spectra) & Ch 21 (Nuclear Physics); Federal Physics XII Ch 18-19"}, "year": "2023"}, {"id": "paper_q121_121", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 121, "subject": "Physics", "topic": "radiation effects somatic", "question": "Skin burns, loss of hair, drop in the white blood cells etc. are examples of:", "options": ["Somatic effect", "Genetic effect", "Metabolism effect", "Mutation effect"], "correctIndex": 0, "explanation": "These are direct effects observed in the exposed individual (somatic effects) of radiation. Genetic effects would affect offspring; the other options are not correct classifications.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 121, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "SZABMU 2023 Q#121 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "paper_q122_122", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 122, "subject": "Logical Reasoning", "topic": "reading comprehension sufi missionaries", "question": "Read the given passage and the following statements below. Then choose the option, basing your answer only on the information provided.\nThe Early Medieval period (642-1219 CE) witnessed the spread of Islam in a region which is now known as Pakistan. During this period, Sufi missionaries played a pivotal role in converting a majority of the regional Buddhist population to Islam.\nStatements:\nI. Islam was spread in Pakistan region during the Early Medieval period.\nII. Sufi missionaries converted a lot of people to Islam during this time by force.\nIII. It can be said that the Sufis were responsible for Pakistan ultimately become an Islamic country.", "options": ["Only I is correct.", "Only I and II are correct.", "I, II and III all are correct.", "Only I and III are correct."], "correctIndex": 0, "explanation": "The passage states that Islam spread in that period and that Sufis played a pivotal role, so I is supported. II asserts conversion by force which is not stated, and III is a broad causal claim beyond the passage, so only I is certainly correct from the given text.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 122, "syllabusUnit": "Deductive & Analytical Reasoning", "pmdcTopic": "Premise Analysis & Logical Syllogisms", "textbookCitation": "PMDC MDCAT Logical Reasoning Guide (Deductions & Assumptions)", "citationString": "SZABMU 2023 Q#122 | Deductive & Analytical Reasoning | PMDC MDCAT Logical Reasoning Guide (Deductions & Assumptions)"}, "year": "2023"}, {"id": "paper_q123_123", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 123, "subject": "Logical Reasoning", "topic": "number properties prime divisible", "question": "Read the following and choose the correct answer:\n“X, Y and Z are three whole numbers less than 24 but greater than 11. X is the smallest prime number. Y is the largest number divisible by 3. Z is the samallest number divisible by 11”?", "options": ["X is 13, Y is 24, Z is 11.", "X is 13, Y is 21, Z is 22.", "X is 11, Y is 21, Z is 11.", "X is 11, Y is 24, Z is 22."], "correctIndex": 1, "explanation": "Numbers are >11 and <24. Smallest prime greater than 11 is 13; largest number <24 divisible by 3 is 21; smallest number >11 divisible by 11 is 22. Therefore option with 13,21,22 is correct.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 123, "syllabusUnit": "Pattern Recognition & Sequences", "pmdcTopic": "Numerical & Pattern Sequence Reasoning", "textbookCitation": "PMDC MDCAT Logical Reasoning Framework", "citationString": "SZABMU 2023 Q#123 | Pattern Recognition & Sequences | PMDC MDCAT Logical Reasoning Framework"}, "year": "2023"}, {"id": "paper_q124_124", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 124, "subject": "Logical Reasoning", "topic": "tax increase business closure", "question": "I. The government has increased the taxes on all bussinesses in pakistan.\nII. Many small businesses will have to close their operations in pakistan.]", "options": ["Statement I is the cause and statement II is its effect.", "Statement II is the cause and statement I is its effect.", "Both the statements I and II are independent causes.", "Both the statements I and II are effects of independent causes."], "correctIndex": 0, "explanation": "An increase in taxes (I) plausibly causes small businesses to close (II); thus I is the cause and II the effect. The other options invert or disconnect the causal relation.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 124, "syllabusUnit": "Critical Thinking & Problem Solving", "pmdcTopic": "Analytical Deduction and Argument Evaluation", "textbookCitation": "PMDC MDCAT Logical Reasoning Syllabus", "citationString": "SZABMU 2023 Q#124 | Critical Thinking & Problem Solving | PMDC MDCAT Logical Reasoning Syllabus"}, "year": "2023"}, {"id": "paper_q125_125", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 125, "subject": "Logical Reasoning", "topic": "battery low actions", "question": "Read the following statement, assuming everything in it to be true. Then decide which of the given suggested courses of action logically follow and are pursuing.\nStatement:\nMy laptop’s battery is low and needs to be charged.\nCourses of Action:\nI. Stop using the laptop to save power.\nII. Get a new fully charged battery and replace it with my old one.", "options": ["I.", "II.", "Both I and II.", "Neither I nor II."], "correctIndex": 3, "explanation": "Neither course is necessarily required: stopping use may be impractical and replacing the battery is not the only remedy (recharging suffices). Thus neither action logically follows as mandatory from the statement.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 125, "syllabusUnit": "Deductive & Analytical Reasoning", "pmdcTopic": "Premise Analysis & Logical Syllogisms", "textbookCitation": "PMDC MDCAT Logical Reasoning Guide (Deductions & Assumptions)", "citationString": "SZABMU 2023 Q#125 | Deductive & Analytical Reasoning | PMDC MDCAT Logical Reasoning Guide (Deductions & Assumptions)"}, "year": "2023"}, {"id": "paper_q126_126", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 126, "subject": "Logical Reasoning", "topic": "syllogism tools hammers trash", "question": "All hammers are tools. Some tools are useless things. All useless things are trash.\nWhich of the following conclusions are NECESSARILY TRUE given only in information above?\nConclusions:\nI. Some hammers are trash.\nII. Some tools are trash.\nIII. All useless things are tools.", "options": ["I and III.", "I and II.", "II and III.", "II"], "correctIndex": 3, "explanation": "From 'Some tools are useless things' and 'All useless things are trash' we can deduce that some tools are trash (II). We cannot conclude any hammer is among those useless tools, so I is not necessary. III is given in the premises (all useless things are trash), but it states useless things are tools which is not given; therefore only II is necessarily true.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 126, "syllabusUnit": "Deductive & Analytical Reasoning", "pmdcTopic": "Premise Analysis & Logical Syllogisms", "textbookCitation": "PMDC MDCAT Logical Reasoning Guide (Deductions & Assumptions)", "citationString": "SZABMU 2023 Q#126 | Deductive & Analytical Reasoning | PMDC MDCAT Logical Reasoning Guide (Deductions & Assumptions)"}, "year": "2023"}, {"id": "paper_q127_127", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 127, "subject": "Chemistry", "topic": "iodine crystal type", "question": "The molecules of iodine (I2) form the:", "options": ["Molecular crystals", "Covalent crystals", "Ionic crystals", "Metallic crystals"], "correctIndex": 0, "explanation": "I2 is composed of neutral molecules held together in the solid by weak intermolecular forces, so it forms molecular crystals. The other crystal types involve networks, ions, or metallic bonding, which do not describe solid iodine.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 127, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SZABMU 2023 Q#127 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "paper_q128_128", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 128, "subject": "Chemistry", "topic": "ice fusion adhesion", "question": "When two ice cubes are pressed over each other, they unite to form one cube due to:", "options": ["Dipole dipole attraction", "Covalent attraction", "Van Der Waal's forces", "H - bonding"], "correctIndex": 3, "explanation": "The temporary melting and re‑freezing at the contact surface is governed by weak intermolecular forces (van der Waals) and hydrogen bonding; the printed answer indicated van der Waals forces as the unifying cause rather than covalent bonds.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 128, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2023 Q#128 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q129_129", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 129, "subject": "Chemistry", "topic": "le chatelier product removal", "question": "For the chemical reaction:\nN2(g) + 3H2(g) ⇌ 2NH3(g) + Heat\nWe can get maximize the yield of NH3:", "options": ["By increasing the temperature", "By decreasing the pressure", "By increasing the volume of the reaction vessel", "By continuous withdrawal of ammonia after intervals"], "correctIndex": 3, "explanation": "Removing product (NH3) shifts the equilibrium to the right (Le Chatelier's principle), increasing yield. Increasing temperature would shift an exothermic reaction left; decreasing pressure or increasing volume disfavors formation of fewer‑mole side.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 129, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "SZABMU 2023 Q#129 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2023"}, {"id": "paper_q130_130", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 130, "subject": "Chemistry", "topic": "haber process pressure", "question": "The high pressure of 200 atm in Haber’s process is used for:", "options": ["Better yield", "Lower yield", "Lower rate", "Cost decrease"], "correctIndex": 0, "explanation": "The Haber process produces fewer gas moles on the product side; high pressure shifts equilibrium toward products, improving yield. The other options are contrary to the intended effect.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 130, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2023 Q#130 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q131_131", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 131, "subject": "Chemistry", "topic": "equilibrium attainment catalyst", "question": "By which of the following factors equilibrim state is attained earlier?", "options": ["Temperature", "Pressure", "Concentration", "Catalyst"], "correctIndex": 3, "explanation": "A catalyst speeds up both forward and reverse reactions equally, allowing the system to reach equilibrium faster without changing equilibrium composition. The other factors change equilibrium position rather than simply the rate to reach it.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 131, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "SZABMU 2023 Q#131 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2023"}, {"id": "paper_q132_132", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 132, "subject": "Chemistry", "topic": "buffer uses", "question": "Which of the following is not the use of Buffer solution?", "options": ["Used for the caliberation of pH meters", "Used to preserve biologicalspecimen", "Maintain the pH of the human blood", "Predict the concentration of a substance"], "correctIndex": 3, "explanation": "Buffers are used to maintain pH and for pH meter calibration and specimen preservation; they are not used to 'predict the concentration' of an arbitrary substance, so that option is not a buffer use.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 132, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "SZABMU 2023 Q#132 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2023"}, {"id": "paper_q133_133", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 133, "subject": "Chemistry", "topic": "activated complex properties", "question": "What is incorrect about activated complex?", "options": ["It is a high energy specie", "It is a stable specie", "It is an unstable specie", "Potentia energy is maximum at activated complex stage"], "correctIndex": 1, "explanation": "The activated complex (transition state) is a high‑energy, unstable species where potential energy is maximum; it is not stable. Thus saying it is a stable species is incorrect, while the other statements are true.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 133, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2023 Q#133 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q134_134", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 134, "subject": "Chemistry", "topic": "units of rate constant", "question": "The unit of rate constants is the same as the rate of reaction in which of the following order of reaction?", "options": ["Zero", "First", "Second", "Third"], "correctIndex": 0, "explanation": "For a zero-order reaction the rate has units of concentration/time, and the rate constant k has the same units, so the unit of k is the same as the rate. For higher orders k carries different units to make the rate have concentration/time units.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 134, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "SZABMU 2023 Q#134 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2023"}, {"id": "paper_q135_135", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 135, "subject": "Chemistry", "topic": "first order rate dependence", "question": "If a reaction is first order with respectd to a reactant then the rate will be__________if the concentration of reactant is doubled:", "options": ["Doubled", "Halved", "One fourth", "Quadrupled"], "correctIndex": 0, "explanation": "In a first-order dependence rate ∝ [A], so doubling the concentration doubles the rate. The other options describe different order relationships (e.g. second-order would quadruple).", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 135, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "SZABMU 2023 Q#135 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2023"}, {"id": "paper_q136_136", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 136, "subject": "Chemistry", "topic": "first law", "question": "The correct equation for the first law of thermodynamics is:", "options": ["∆E = q + w", "∆E = w - q", "∆E = ∆q - p∆v", "∆E = ∆q + p∆v"], "correctIndex": 0, "explanation": "The first law states the change in internal energy ∆E equals heat added to the system q plus work done on the system w. The other forms are either sign-inverted or mix terms incorrectly.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 136, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2023 Q#136 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q137_137", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 137, "subject": "Chemistry", "topic": "calorie conversion", "question": "One calorie is equal to:", "options": ["4.18 KJ", "4.18 J", "0.418 KJ mole-1", "0.418 KJ"], "correctIndex": 1, "explanation": "By definition one (small) calorie ≈ 4.18 joules. The other numeric options either have the wrong unit scale or incorrect per-mole labeling.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 137, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2023 Q#137 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q138_138", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 138, "subject": "Chemistry", "topic": "enthalpy", "question": "The thermal energy at constan pressure is called:", "options": ["Enthalpy", "Internal energy", "Heat capacity", "Work done"], "correctIndex": 0, "explanation": "Enthalpy (H) is the thermodynamic quantity representing thermal energy at constant pressure (H = E + pV). Internal energy is the total energy, while heat capacity and work are different properties.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 138, "syllabusUnit": "Unit 4: Chemical Energetics", "pmdcTopic": "Enthalpy Changes, Hess's Law & Standard Heats of Reaction", "textbookCitation": "PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6", "citationString": "SZABMU 2023 Q#138 | Unit 4: Chemical Energetics | PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6"}, "year": "2023"}, {"id": "paper_q139_139", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 139, "subject": "Chemistry", "topic": "standard electrode potential", "question": "Which statement correctly describes the term Standard Electrode Potential?", "options": ["It is the electrode potential determined at room temperature and pressure", "It is the electrode potential determined under standard conditions using StandardHydrogen Electrode as the other electrode", "It is the electrode potential of an element and its solution compared to a standard value", "It is the potential which is measured when two half cells are connected together"], "correctIndex": 1, "explanation": "Standard electrode potentials are measured under standard conditions (1 M, 1 bar, 25°C) with the standard hydrogen electrode as the reference. The other options are either incomplete or imprecise descriptions.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 139, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "SZABMU 2023 Q#139 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2023"}, {"id": "paper_q140_140", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 140, "subject": "Chemistry", "topic": "oxidation number", "question": "Oxidation number of an element in free state is:", "options": ["Negative", "Positive", "Zero", "±1"], "correctIndex": 2, "explanation": "An element in its uncombined (free) state has oxidation number zero. Other values apply when the element is in compounds or ions.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 140, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "SZABMU 2023 Q#140 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2023"}, {"id": "paper_q141_141", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 141, "subject": "Chemistry", "topic": "electrochemistry definition", "question": "The branch of science which deals with the conversion of electrical energy to chemical\nenergy and vice versa is called:", "options": ["Electrochemistry", "Thermochemistry", "Stereochemistry", "Biochemistry"], "correctIndex": 0, "explanation": "Electrochemistry studies interconversion of electrical and chemical energy (e.g., batteries, electrolysis). The other branches address different topics.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 141, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "SZABMU 2023 Q#141 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2023"}, {"id": "paper_q142_142", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 142, "subject": "Chemistry", "topic": "electronegativity difference", "question": "Which of the following has greatest difference of electronegativity?", "options": ["HF", "HCl", "HBr", "HI"], "correctIndex": 0, "explanation": "Fluorine is the most electronegative element, so HF has the largest electronegativity difference among the listed hydrogen halides. The others decrease down the group.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 142, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2023 Q#142 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q143_143", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 143, "subject": "Chemistry", "topic": "ionization energy trend", "question": "Ionization energy decreases down the group because:", "options": ["Shielding remains constant", "Atomic radius remains constant", "Proton number increases", "Atomic radius increases"], "correctIndex": 3, "explanation": "Ionization energy falls down a group because atomic radius increases and outer electrons are farther from the nucleus and more shielded, making them easier to remove. The other choices are incorrect descriptions of the trend.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 143, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2023 Q#143 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q144_144", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 144, "subject": "Chemistry", "topic": "hybridization in ethane", "question": "Carbon atoms in ethane are hybridized:", "options": ["Sp3", "Sp2", "Sp", "Sp3d"], "correctIndex": 0, "explanation": "In ethane each carbon forms four single (σ) bonds and is therefore sp3-hybridized. sp2 and sp correspond to unsaturated carbons with double or triple bonds.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 144, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "SZABMU 2023 Q#144 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2023"}, {"id": "paper_q145_145", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 145, "subject": "Chemistry", "topic": "bonding in zinc", "question": "The type of bonding in Zinc is:", "options": ["Ionic", "Covalent", "Dative", "Metallic"], "correctIndex": 3, "explanation": "Zinc is a metal and exhibits metallic bonding, characterized by a lattice of positive ions surrounded by a sea of delocalized electrons. Ionic, covalent or dative bonding are not the primary bonding type in elemental zinc.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 145, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "SZABMU 2023 Q#145 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2023"}, {"id": "paper_q146_146", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 146, "subject": "Chemistry", "topic": "semiconductors", "question": "Which of the following is semiconductor?", "options": ["Al", "Si", "P", "Mg"], "correctIndex": 1, "explanation": "Silicon (Si) is a well-known semiconductor used in electronic devices. Aluminum and magnesium are metals, phosphorus is a nonmetal but not a conventional semiconductor like Si.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 146, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2023 Q#146 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q147_147", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 147, "subject": "Chemistry", "topic": "group 2 trends", "question": "Which of the following property decreases in Group 2 as we go down the group?", "options": ["Shielding", "Atomic radius", "Proton number", "Ionization energy"], "correctIndex": 3, "explanation": "Ionization energy decreases down Group 2 because outer electrons are farther from the nucleus and more shielded, making them easier to remove. Shielding and proton number actually increase and atomic radius increases rather than decreases.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 147, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2023 Q#147 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q148_148", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 148, "subject": "Chemistry", "topic": "alkali metal oxides", "question": "Which of the following alkali metal can form normal oxides as well as peroxides?", "options": ["Na", "K", "Li", "Cs"], "correctIndex": 0, "explanation": "Sodium reacts with oxygen to form both the normal oxide (Na2O) and, with excess oxygen, the peroxide (Na2O2). Lithium forms essentially only the normal oxide, so sodium is the alkali metal that gives both.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 148, "syllabusUnit": "Unit 8: Inorganic Chemistry & Periodicity", "pmdcTopic": "Periodic Trends, Group Chemistry & Transition Elements", "textbookCitation": "PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16", "citationString": "SZABMU 2023 Q#148 | Unit 8: Inorganic Chemistry & Periodicity | PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16"}, "year": "2023"}, {"id": "paper_q149_149", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 149, "subject": "Chemistry", "topic": "variable valency", "question": "The transition element which doesn’t show variable valency:", "options": ["Cu", "Sc", "Zn", "Cr"], "correctIndex": 2, "explanation": "Zn commonly exhibits a +2 oxidation state and shows little variable valency because it has a filled d10 configuration. Other transition elements listed (Cu, Cr, Sc) show multiple oxidation states.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 149, "syllabusUnit": "Unit 8: Inorganic Chemistry & Periodicity", "pmdcTopic": "Periodic Trends, Group Chemistry & Transition Elements", "textbookCitation": "PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16", "citationString": "SZABMU 2023 Q#149 | Unit 8: Inorganic Chemistry & Periodicity | PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16"}, "year": "2023"}, {"id": "paper_q150_150", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 150, "subject": "Chemistry", "topic": "binding energy trend", "question": "The binding energy of transition metals increases upto group:", "options": ["II B", "IV B", "III B", "VI B"], "correctIndex": 3, "explanation": "The binding (cohesive) energy of the transition metals rises across the series as more d-electrons take part in metal-metal bonding, reaching a maximum around group VI B, where the number of bonding electrons is greatest, before falling again.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 150, "syllabusUnit": "Unit 8: Inorganic Chemistry & Periodicity", "pmdcTopic": "Periodic Trends, Group Chemistry & Transition Elements", "textbookCitation": "PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16", "citationString": "SZABMU 2023 Q#150 | Unit 8: Inorganic Chemistry & Periodicity | PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16"}, "year": "2023"}, {"id": "paper_q151_151", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 151, "subject": "Chemistry", "topic": "homocyclic classification", "question": "Homo-cyclic organic compounds are sub divided into two groups namely:", "options": ["Alicyclic and Aromatic", "Open chain and branched chain", "Aromatic and non-aromatic", "Anti-aromatic"], "correctIndex": 0, "explanation": "Homocyclic compounds (rings made only of carbon atoms) are classified into alicyclic (non-aromatic cycloalkanes) and aromatic (stable conjugated ring systems). The other pairings are not the standard subdivision for homocyclic compounds.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 151, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2023 Q#151 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q152_152", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 152, "subject": "Chemistry", "topic": "tautomerism", "question": "The type of isomerism arising due to shifting of proton fron one atom to another in\nthe same molecule is:", "options": ["Chain isomerism", "Metamerism", "Tautomerism", "Postion isomerism"], "correctIndex": 2, "explanation": "Tautomerism involves intramolecular proton transfer leading to isomers (e.g., keto-enol tautomers). The other isomerism types involve different connectivity or functional group arrangements.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 152, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2023 Q#152 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q153_153", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 153, "subject": "Chemistry", "topic": "hybridization alkanes", "question": "In alkanes, each Carbon has hybridization:", "options": ["Sp3", "Sp", "Sp2", "dsp"], "correctIndex": 0, "explanation": "Alkane carbons form four single bonds and are sp3-hybridized. sp2 and sp correspond to double and triple bonded carbons, respectively.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 153, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "SZABMU 2023 Q#153 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2023"}, {"id": "paper_q154_154", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 154, "subject": "Chemistry", "topic": "stoichiometry nh3 synthesis", "question": "For the reaction given below:\nN2 + 3H2 ⇌ 2NH3\nHow many moles N2 are required for synthesis of 4 moles of NH3?", "options": ["4 moles of N2", "2 moles of N2", "3 moles of N2", "4.5 moles"], "correctIndex": 1, "explanation": "Stoichiometry: 1 mol N2 produces 2 mol NH3, so to make 4 mol NH3 you need 2 mol N2. The other quantities do not satisfy the reaction stoichiometry.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 154, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2023 Q#154 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q155_155", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 155, "subject": "Chemistry", "topic": "stoichiometry aluminium", "question": "Al reacts with O2 according to the following reaction:\n4Al + 3O2 ⟶ 2Al2O3\n27g of Al will react with how much of O2?", "options": ["8 g", "16 g", "24 g", "32 g"], "correctIndex": 2, "explanation": "Molar mass Al ≈ 27 g mol−1; 4 mol Al (108 g) react with 3 mol O2 (96 g), so 27 g Al (1 mol) reacts with 24 g O2 (3/4 of 96 g). Thus 24 g O2 is required.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 155, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2023 Q#155 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q156_156", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 156, "subject": "Chemistry", "topic": "mole definition", "question": "One mole of a substance is the amount of that substance that has the same number of\nparticles (atom, ions or molecules) as there are atoms in exactly:", "options": ["1.008 g of hydrogen gas (H2)", "16 g of oxygen gas (O2)", "12 g of carbon-12 isotopes", "12 g of magnesium"], "correctIndex": 2, "explanation": "By definition a mole contains as many particles as there are atoms in exactly 12 g of carbon-12. The other masses refer to different elements or are incorrect references.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 156, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2023 Q#156 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q157_157", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 157, "subject": "Chemistry", "topic": "quantum numbers", "question": "Principle quantum number is represented by the symbol:", "options": ["m", "n", "s", "l"], "correctIndex": 1, "explanation": "The principal quantum number is denoted by n. The symbols l and m (or ml) denote angular momentum and magnetic quantum numbers, and s refers to spin.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 157, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "SZABMU 2023 Q#157 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2023"}, {"id": "paper_q158_158", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 158, "subject": "Chemistry", "topic": "azimuthal quantum number", "question": "Shape of the sub shell is explained by which quantum number:", "options": ["Principal quantum number", "Azimuthal quantum number", "Magnetic quantum number", "Spin quantum number"], "correctIndex": 1, "explanation": "The azimuthal (angular momentum) quantum number l determines the shape of orbitals (s, p, d, f). Principal n sets energy/size, ml sets orientation, and spin is electron spin.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 158, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "SZABMU 2023 Q#158 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2023"}, {"id": "paper_q159_159", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 159, "subject": "Chemistry", "topic": "hunds rule", "question": "The electronic configuration for degenerated orbitals is explained by:", "options": ["Aufbau Principle", "𝑛 + 𝑙 rule", "Hund’s rule", "Pauli exclusion principle"], "correctIndex": 2, "explanation": "Hund's rule governs electron distribution among degenerate orbitals: maximize unpaired electrons with parallel spins. Aufbau and n+l rules address energy ordering; Pauli principle limits spin pairing.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 159, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "SZABMU 2023 Q#159 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2023"}, {"id": "paper_q160_160", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 160, "subject": "Chemistry", "topic": "pauli exclusion", "question": "Maximum number of electrons which can be placed in one orbital is:", "options": ["1", "2", "3", "4"], "correctIndex": 1, "explanation": "An orbital can hold a maximum of two electrons with opposite spins according to the Pauli exclusion principle. The other numbers are not permitted for a single orbital.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 160, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "SZABMU 2023 Q#160 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2023"}, {"id": "paper_q161_161", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 161, "subject": "Chemistry", "topic": "gas mixture behavior", "question": "Air is a mixture of gases. The molecules of air do notsettle down due to:", "options": ["Different molar mass", "Non polar nature of gases", "Presence of dust particles in air", "Elastic collision of gas molecules"], "correctIndex": 3, "explanation": "Gas molecules undergo frequent elastic collisions and have high kinetic energy, so they remain dispersed rather than settling. Differences in molar mass alone don't cause settling in a well-mixed gas.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 161, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SZABMU 2023 Q#161 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "paper_q162_162", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 162, "subject": "Chemistry", "topic": "elastic collisions", "question": "Collision shown by gases involve the following:", "options": ["No energy change", "No pressure change", "Small energy change", "Large energy change"], "correctIndex": 0, "explanation": "Ideal gas collisions are elastic, meaning kinetic energy is conserved during collisions (no net energy change). The other choices describe non-elastic or unrelated effects.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 162, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SZABMU 2023 Q#162 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "paper_q163_163", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 163, "subject": "Chemistry", "topic": "charles law", "question": "According to Charles law volume of gas reduces to zero at:", "options": ["-12 O C", "0 O C", "-273.15 O C", "-210 O C"], "correctIndex": 2, "explanation": "Charles's law extrapolated to zero volume gives absolute zero at -273.15°C (0 K). The other temperatures are not the physical zero-volume extrapolation point.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 163, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SZABMU 2023 Q#163 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "paper_q164_164", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 164, "subject": "Chemistry", "topic": "hydrogen bonding", "question": "The strongest hydrogen bond is present in:", "options": ["H2S", "HF", "H2O", "NH3"], "correctIndex": 1, "explanation": "A hydrogen bond is strongest when hydrogen is bonded to the most electronegative atom. Fluorine is the most electronegative element, so the individual hydrogen bond in HF is the strongest of these. Water forms a more extensive H-bond network, but each of its bonds is weaker than the one in HF.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 164, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "SZABMU 2023 Q#164 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "paper_q165_165", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 165, "subject": "Chemistry", "topic": "surface tension", "question": "Which of the following has highest surface tension?", "options": ["Benzene", "Alcohols", "Ether", "Water"], "correctIndex": 3, "explanation": "Water has very strong hydrogen bonding at the surface, giving it the highest surface tension among the listed liquids. Nonpolar solvents like benzene and ether have much lower surface tension.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 165, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2023 Q#165 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q166_166", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 166, "subject": "Chemistry", "topic": "boiling point hydrocarbons", "question": "Which of the following has highest boiling point?", "options": ["C4H10", "C6H14", "C10H22", "C2H6"], "correctIndex": 2, "explanation": "Boiling point increases with molecular size and surface area among alkanes; C10H22 (decane) is the largest listed and thus has the highest boiling point. Smaller alkanes have lower boiling points.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 166, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "SZABMU 2023 Q#166 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2023"}, {"id": "paper_q167_167", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 167, "subject": "Chemistry", "topic": "ice density", "question": "Ice floats on the surface of water due to:", "options": ["Larger bond length", "Cubic structure of ice", "Weak intermolecular forces", "Empty spaces in the structure of ice"], "correctIndex": 3, "explanation": "Ice has an open crystalline structure with cavities (hydrogen-bonded network) that makes it less dense than liquid water, so it floats. The other choices do not correctly explain the lower density of ice.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 167, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "SZABMU 2023 Q#167 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q168_168", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 168, "subject": "Chemistry", "topic": "oxidation of aromatics", "question": "Which of the following is not oxidized by any oxidizing agent?", "options": ["Benzene", "Toulene", "Ethylbenzene", "Xylene"], "correctIndex": 0, "explanation": "Benzene's aromatic ring is relatively resistant to oxidation under conditions that oxidize alkyl-substituted benzenes; toluene, ethylbenzene and xylenes can be oxidized at their alkyl side chains. The key lists benzene as not being oxidized.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 168, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "SZABMU 2023 Q#168 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2023"}, {"id": "paper_q169_169", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 169, "subject": "Chemistry", "topic": "reactivity order", "question": "The correct order of reactivity of hydrocarbons is:", "options": ["Alkanes ˃ Alkynes ˃ Alkenes", "Alkenes ˃ Alkanes ˃ Alkynes", "Alkynes ˃ Alkenes ˃ Alkanes", "Alkenes ˃ Alkynes ˃ Alkanes"], "correctIndex": 3, "explanation": "Alkenes are generally the most reactive of these hydrocarbons because their accessible pi bond readily undergoes addition; alkynes are next, and alkanes, held together by strong sigma bonds only, are the least reactive. This gives the order alkenes > alkynes > alkanes.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 169, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "SZABMU 2023 Q#169 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2023"}, {"id": "paper_q170_170", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 170, "subject": "Chemistry", "topic": "halogen acid reactivity", "question": "Reactivity of order of halogen acid is:", "options": ["HF ˃ HCl ˃ HBr ˃ HI", "HBr ˃ HCl ˃ HI", "HCl ˃ HBr ˃ HI ˃ HF", "HI ˃ HBr ˃ HCl ˃ HF"], "correctIndex": 3, "explanation": "The acidity of hydrogen halides increases down the group (bond strength decreases), so HI is strongest and HF weakest; the key lists HI > HBr > HCl > HF as the correct order.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 170, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "SZABMU 2023 Q#170 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2023"}, {"id": "paper_q171_171", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 171, "subject": "Chemistry", "topic": "alkyl halides definition", "question": "Alkyl halides are also known as Halogen derivatives of:", "options": ["Alkanes", "Alkenes", "Alkynes", "Alcohols"], "correctIndex": 0, "explanation": "Alkyl halides are derived from alkanes by replacing a hydrogen with a halogen; thus they are halogen derivatives of alkanes. The other choices describe different parent functional groups.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 171, "syllabusUnit": "Unit 10: Alkyl Halides, Alcohols & Phenols", "pmdcTopic": "Nucleophilic Substitution, Elimination Reactions & Phenol Acidity", "textbookCitation": "PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19", "citationString": "SZABMU 2023 Q#171 | Unit 10: Alkyl Halides, Alcohols & Phenols | PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19"}, "year": "2023"}, {"id": "paper_q172_172", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 172, "subject": "Chemistry", "topic": "grignard reagent", "question": "Grignard reagent is formed when alkyl halide reacts in the presence of halogen with:", "options": ["Calcium", "Potassium", "Sodium", "Magnesium"], "correctIndex": 3, "explanation": "Grignard reagents (R–MgX) are prepared by reacting alkyl or aryl halides with magnesium metal in dry ether. Other metals listed do not produce Grignard reagents under the standard preparation.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 172, "syllabusUnit": "Unit 10: Alkyl Halides, Alcohols & Phenols", "pmdcTopic": "Nucleophilic Substitution, Elimination Reactions & Phenol Acidity", "textbookCitation": "PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19", "citationString": "SZABMU 2023 Q#172 | Unit 10: Alkyl Halides, Alcohols & Phenols | PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19"}, "year": "2023"}, {"id": "paper_q173_173", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 173, "subject": "Chemistry", "topic": "phenol reactivity", "question": "Phenols are very reactive towards:", "options": ["Oxidizing agent", "Reducing agent", "Dehydrating agent", "Hygroscopic agent"], "correctIndex": 0, "explanation": "Phenols are readily oxidized under suitable conditions (forming quinones, etc.), so they are reactive towards oxidizing agents. The other options are not the primary typical reactivity being referenced.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 173, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "SZABMU 2023 Q#173 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2023"}, {"id": "paper_q174_174", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 174, "subject": "Chemistry", "topic": "functional group", "question": "Both alcohols and phenols contain:", "options": ["– OH group", "– COOH group", "– CH2 group", "– CHO group"], "correctIndex": 0, "explanation": "Both alcohols and phenols possess the hydroxyl (–OH) functional group; carboxyl (–COOH) and aldehyde (–CHO) groups are different functional groups.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 174, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "SZABMU 2023 Q#174 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2023"}, {"id": "paper_q175_175", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 175, "subject": "Chemistry", "topic": "acidity order", "question": "Select the correct order of relative acidic strength of phenol, alcohol, water, and\ncarboxylic acid:", "options": ["Carboxylic acid ˃ water ˃ phenol ˃ alcohol", "Carboxylic acid ˃ phenol ˃ water ˃ alcohol", "Carboxylic acid ˃ alcohol ˃ phenol ˃ water", "Carboxylic acid ˃ water ˃ alcohol ˃ phenol"], "correctIndex": 1, "explanation": "Carboxylic acids are strongest, followed by phenols (resonance-stabilized conjugate base), then water, with alcohols least acidic. Option B matches that established acidity order.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 175, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "SZABMU 2023 Q#175 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2023"}, {"id": "paper_q176_176", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 176, "subject": "Chemistry", "topic": "esterification", "question": "Carboxylic acid reacts with Alcohol to form:", "options": ["Ester", "Aldehyde", "Ketone", "Alkyl Halide"], "correctIndex": 0, "explanation": "Reaction between a carboxylic acid and an alcohol (typically with acid catalyst) yields an ester (Fischer esterification). The other products come from different reaction types.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 176, "syllabusUnit": "Unit 10: Alkyl Halides, Alcohols & Phenols", "pmdcTopic": "Nucleophilic Substitution, Elimination Reactions & Phenol Acidity", "textbookCitation": "PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19", "citationString": "SZABMU 2023 Q#176 | Unit 10: Alkyl Halides, Alcohols & Phenols | PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19"}, "year": "2023"}, {"id": "paper_q177_177", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 177, "subject": "Chemistry", "topic": "catalytic reduction", "question": "Catalytic reduction of Aldehyde & Ketone forms:", "options": ["Alcohol", "Carboxylic acid", "Alkane", "Aldehyde"], "correctIndex": 0, "explanation": "Catalytic hydrogenation of aldehydes and ketones reduces the carbonyl to the corresponding alcohol. Oxidation would give acids, and complete reduction to alkanes is less common under standard catalytic conditions.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 177, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "SZABMU 2023 Q#177 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2023"}, {"id": "paper_q178_178", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 178, "subject": "Chemistry", "topic": "cannizzaro reaction", "question": "When Aldehyde reacts with 50% NaOH, this reaction is called as:", "options": ["2, 4 – DNPH reaction", "Aldol condensation reaction", "Clemmensen reaction", "Cannizarros’s reaction"], "correctIndex": 3, "explanation": "The Cannizzaro reaction is the base-induced disproportionation of non-enolizable aldehydes (in concentrated base) to give an alcohol and a carboxylate. The other named reactions are different transformations.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 178, "syllabusUnit": "Unit 11: Carbonyl Compounds (Aldehydes & Ketones)", "pmdcTopic": "Carbonyl Chemistry, Addition Reactions & Tests for Carbonyls", "textbookCitation": "PTB Chemistry XII Ch 12 (Aldehydes and Ketones); Federal Chemistry XII Ch 20", "citationString": "SZABMU 2023 Q#178 | Unit 11: Carbonyl Compounds (Aldehydes & Ketones) | PTB Chemistry XII Ch 12 (Aldehydes and Ketones); Federal Chemistry XII Ch 20"}, "year": "2023"}, {"id": "paper_q179_179", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 179, "subject": "Biology", "topic": "thyroxin classification", "question": "Based on function, thyroxin can be classified as:", "options": ["Hormonal protein", "Structural protein", "Transprt protein", "Genetic protein"], "correctIndex": 0, "explanation": "Classified by its function, thyroxine acts as a hormone, so among these choices the hormonal role is the correct classification. (Strictly, thyroxine is an iodinated amino-acid derivative rather than a true protein, but of the options given only the hormonal function describes it.)", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 179, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "SZABMU 2023 Q#179 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q180_180", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 180, "subject": "Biology", "topic": "definition of enzyme", "question": "Enzyme is a natural substance that:", "options": ["Increases the rate of chemical reaction", "Decreases the rate of chemical reaction", "Has no effect on the rate of chemical reaction", "Stops the chemical reaction"], "correctIndex": 0, "explanation": "An enzyme is a biological catalyst that speeds up (increases) the rate of chemical reactions without being consumed. The other options contradict the catalytic role of enzymes or describe effects that are not characteristic of enzymes.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 180, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "SZABMU 2023 Q#180 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q181_181", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 181, "subject": "English", "topic": "word meaning ritual", "question": "The word ‘RITUAL’ means:", "options": ["Original", "Religion", "Routine", "Custom"], "correctIndex": 3, "explanation": "A 'ritual' is a customary ceremony or established practice, so 'Custom' is the best match. 'Routine' is close but less precise (routine implies regularity rather than ceremonial or traditional practice); 'Original' and 'Religion' are not definitions of 'ritual'.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 181, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "SZABMU 2023 Q#181 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2023"}, {"id": "paper_q182_182", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 182, "subject": "English", "topic": "spelling renaissance", "question": "Choose the correct spelling:", "options": ["Renessance", "Renaissance", "Renaisance", "Reniassance"], "correctIndex": 1, "explanation": "The correct spelling of the term referring to the cultural movement is 'Renaissance'. The other options show common misspellings with incorrect letter order or missing letters.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 182, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "SZABMU 2023 Q#182 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2023"}, {"id": "paper_q183_183", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 183, "subject": "English", "topic": "spelling expedient", "question": "Choose the correct spelling:", "options": ["Expident", "Expedent", "Expedient", "Expediant"], "correctIndex": 2, "explanation": "'Expedient' is the correct spelling meaning suitable or advantageous. The other choices are incorrect spellings and do not represent the accepted form of the word.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 183, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "SZABMU 2023 Q#183 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2023"}, {"id": "paper_q184_184", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 184, "subject": "English", "topic": "prepositions guilty of", "question": "Choose correct option from the following:\nFinally the accused was found guilty the crime.", "options": ["From", "Of", "For", "To"], "correctIndex": 1, "explanation": "The fixed phrase is 'guilty of the crime', so the preposition 'Of' correctly completes the sentence. 'For', 'From', and 'To' do not form the standard collocation with 'guilty' in this context.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 184, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "SZABMU 2023 Q#184 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2023"}, {"id": "paper_q185_185", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 185, "subject": "English", "topic": "spelling deficiency", "question": "Choose the correct spelling:", "options": ["Defficiency", "Daficiency", "Deficiency", "Defeciency"], "correctIndex": 2, "explanation": "'Deficiency' is the correct spelling; the other options contain incorrect letter sequences or doubled letters and are misspellings.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 185, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "SZABMU 2023 Q#185 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2023"}, {"id": "paper_q186_186", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 186, "subject": "English", "topic": "vocabulary havoc", "question": "Hundreds of years old palace could not withstand the of heavy rain:", "options": ["Aftermath", "Havoc", "Annoyance", "Massacre"], "correctIndex": 1, "explanation": "'Havoc' (widespread destruction or damage) correctly fits the context of a palace unable to withstand heavy rain. 'Aftermath' refers to consequences after an event, 'Annoyance' is the wrong semantic field, and 'Massacre' is unrelated.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 186, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "SZABMU 2023 Q#186 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2023"}, {"id": "paper_q187_187", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 187, "subject": "English", "topic": "verb choice inspect", "question": "He began to the heap of corns very carefully.", "options": ["Assess", "Inspect", "Analyze", "Evaluate"], "correctIndex": 1, "explanation": "In the context of looking over a heap of corns carefully, 'inspect' (to examine closely) is the most appropriate verb. 'Assess' and 'evaluate' imply judging value, and 'analyze' suggests detailed breakdown; 'inspect' best matches the simple act of close examination.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 187, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "SZABMU 2023 Q#187 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2023"}, {"id": "paper_q188_188", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 188, "subject": "English", "topic": "sentence types exclamatory", "question": "How cold the night is! Which kind of sentence is it?", "options": ["Interrogative", "Declarative", "Exclamatory", "Imperative"], "correctIndex": 2, "explanation": "The sentence expresses strong feeling and ends with an exclamation mark, so it is 'Exclamatory'. It is not asking a question (interrogative), stating a neutral fact (declarative), or giving a command (imperative).", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 188, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "SZABMU 2023 Q#188 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2023"}, {"id": "paper_q189_189", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 189, "subject": "English", "topic": "sentence punctuation and structure", "question": "Identify the errors in the sentence to choose the correct option from below:", "options": ["Tennis gives you plenty of exercise it develops quickness of eye, and limb. It calls your brain your thinking power into action.", "Tennis gives you plenti off exercise, it develops quickness of eye, limb. It calls your brain, your thinking power intoo action.", "Tennis gives you plenty of exercise, It develops quickness of eye, limb. It calls your brane, your thinking power over action.", "Tennis gives you plenty of exercise; It develops quickness of eye and limb. It callsyour brain, your thinking power into action."], "correctIndex": 3, "explanation": "Option D matches the version the paper marks as correct: it uses a semicolon to link the two main clauses and lists 'eye and limb' together; although it contains a spacing error 'callsyour', the keyed option is D. The other choices contain more serious errors (misspellings, incorrect punctuation or nonsensical wording).", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 189, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "SZABMU 2023 Q#189 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2023"}, {"id": "paper_q190_190", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 190, "subject": "English", "topic": "subject verb agreement", "question": "It good players who bring good name to a country.", "options": ["Was", "Were", "Is", "Are"], "correctIndex": 2, "explanation": "The sentence uses the cleft structure 'It is ... who ...', which takes the singular verb 'is' regardless of what follows. So 'It is good players who bring good name to a country' is correct.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 190, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "SZABMU 2023 Q#190 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2023"}, {"id": "paper_q191_191", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 191, "subject": "English", "topic": "modal verb usage", "question": "I don’t think I be able to go.", "options": ["Can", "Should", "Shall", "must"], "correctIndex": 2, "explanation": "'Shall' correctly completes 'I don't think I shall be able to go', the standard way to express future inability. 'Can' would refer to present ability, 'should' to advice, and 'must' to obligation, none of which fit the intended meaning.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 191, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "SZABMU 2023 Q#191 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2023"}, {"id": "paper_q192_192", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 192, "subject": "English", "topic": "subject verb agreement ethics", "question": "Ethics important for a peaceful and loving society.", "options": ["Have", "Has", "Are", "Is"], "correctIndex": 3, "explanation": "'Ethics' is treated as a singular subject here (a field or principle), so it takes the singular verb 'is': 'Ethics is important for a peaceful and loving society.'", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 192, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "SZABMU 2023 Q#192 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2023"}, {"id": "paper_q193_193", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 193, "subject": "English", "topic": "present perfect continuous", "question": "Engineers working on a new project for the last three days.", "options": ["Are", "Has been", "Have been", "Ought to be"], "correctIndex": 2, "explanation": "The correct form to indicate an action continuing up to the present is 'have been' (Engineers have been working...). 'Are' lacks the duration aspect, 'has been' is singular and doesn't agree with 'Engineers', and 'ought to be' changes the meaning entirely.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 193, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "SZABMU 2023 Q#193 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2023"}, {"id": "paper_q194_194", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 194, "subject": "English", "topic": "word meaning credentials", "question": "The word ‘CREDENTIALS’ means:", "options": ["Trust", "Qualifications", "Credits", "Beliefs"], "correctIndex": 1, "explanation": "'Credentials' commonly refers to qualifications, certificates, or evidence of suitability, so 'Qualifications' is the correct meaning. The other options do not capture the standard sense of credentials.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 194, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "SZABMU 2023 Q#194 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2023"}, {"id": "paper_q195_195", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 195, "subject": "English", "topic": "comma and conjunction errors", "question": "Identify the errors and choose the correct option:", "options": ["The wind blew, the rain fell, and the lightening flashed.", "The wind blue the rain fell, and the lightening flashed.", "The wind blew, the rain fell and le lightening flashed.", "The wind blew the rain fell, and the lightening Flashed."], "correctIndex": 0, "explanation": "Option A is the correctly punctuated and spelled sentence in the list: 'The wind blew, the rain fell, and the lightening flashed.' The other options contain spelling or punctuation errors (e.g., 'blue' instead of 'blew', missing comma/word errors, or incorrect capitalization).", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 195, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "SZABMU 2023 Q#195 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2023"}, {"id": "paper_q196_196", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 196, "subject": "English", "topic": "phrasal verb collocation", "question": "Choose the correct option:\nNegotiations between the two sides have .", "options": ["Broken off", "Broken down", "Broken up", "Broken in"], "correctIndex": 1, "explanation": "'Broken down' is the correct phrasal verb: negotiations that have 'broken down' have collapsed or failed. 'Broken off' means abruptly stopped, 'broken up' means dispersed, and 'broken in' does not fit this context.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 196, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "SZABMU 2023 Q#196 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2023"}, {"id": "paper_q197_197", "paperTitle": "SZABMU MDCAT 2023 (Paper)", "shortTitle": "SZABMU 2023", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "questionNumber": 197, "subject": "English", "topic": "sentence correction", "question": "Choose the correct sentence:", "options": ["Your voice was recognized by me at once.", "All her boats has been lost in the storm.", "A committee of five were appointed.", "The crowd were very big."], "correctIndex": 0, "explanation": "Option A is grammatically correct and coherent: passive voice 'Your voice was recognized by me at once.' The other options contain errors: B has incorrect verb agreement ('has' with plural 'boats'), C uses plural verb with a collective noun where singular is preferred, and D uses 'were' with 'crowd' where 'was' would usually be correct.", "reference": {"sourcePaper": "SZABMU MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "Shaheed Zulfiqar Ali Bhutto Medical University", "province": "Islamabad / Federal / AJK", "originalQuestionNumber": 197, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "SZABMU 2023 Q#197 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2023"}, {"id": "paper_q1_1", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 1, "subject": "Biology", "topic": "definition of bacteriophage", "question": "What does the term bacteriophage refer to?", "options": ["A virus that infects bacteria", "A bacterium that infects virus", "A virus which behaves as bacteria", "Combination of Bacterium & Virion"], "correctIndex": 0, "explanation": "Bacteriophage literally means 'bacteria eater' and refers to viruses that infect bacteria. The other choices describe incorrect relationships or are nonsensical combinations.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 1, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "UHS 2023 Q#1 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2023"}, {"id": "paper_q2_2", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 2, "subject": "Biology", "topic": "viral genome types", "question": "What of the following virus contains single stranded DNA?", "options": ["Adeno virus", "Herpes virus", "Parvo virus", "Pox virus"], "correctIndex": 2, "explanation": "Parvoviruses are small single-stranded DNA viruses. Adenoviruses and herpesviruses have double-stranded DNA, and poxviruses are large dsDNA viruses.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 2, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2023 Q#2 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q3_3", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 3, "subject": "Biology", "topic": "bacteriophage morphology", "question": "How may tail fibrils are attached to the end plate of a bacteriophage?", "options": ["2", "4", "6", "8"], "correctIndex": 2, "explanation": "Typical tailed bacteriophages such as T4 have six tail fibers attached to the baseplate. The other numbers do not match the common morphology of these phages.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 3, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "UHS 2023 Q#3 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2023"}, {"id": "paper_q4_4", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 4, "subject": "Biology", "topic": "retroviral enzymes", "question": "The enzymes integrase, protease and reverse transcriptase are found in which virus?", "options": ["Hepatitis A virus", "Herpes virus", "Influenza virus", "Human immunodeficiency virus"], "correctIndex": 3, "explanation": "Integrase, protease and reverse transcriptase are hallmark enzymes of retroviruses such as HIV. The other viruses listed are not retroviruses and do not contain that enzyme set.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 4, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2023 Q#4 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q5_5", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 5, "subject": "Biology", "topic": "fermentation products", "question": "What is the end product of glucose by yeast in anaerobic respiration?", "options": ["Ethanol and oxygen", "Ethanol and water", "Ethanol and CO2", "Lactic acid and CO2"], "correctIndex": 2, "explanation": "Yeast ferment glucose anaerobically to ethanol and carbon dioxide. Lactic acid fermentation occurs in some other organisms, and ethanol plus oxygen or water are incorrect product pairs.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 5, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "UHS 2023 Q#5 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2023"}, {"id": "paper_q6_6", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 6, "subject": "Biology", "topic": "electron transport chain", "question": "Each carrier in Electron Transport Chain is first ______ and then ______.", "options": ["Broken-down, Regenerate", "Generated, Broken-down", "Oxidized, Reduced", "Reduced, Oxidized"], "correctIndex": 3, "explanation": "In the electron transport chain carriers receive electrons (are reduced) and then donate them to the next carrier (are oxidized). Thus the correct sequence is \"reduced, oxidized.\"", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 6, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#6 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q7_7", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 7, "subject": "Biology", "topic": "electron transport chain function", "question": "Electron transport chain explains:", "options": ["Photophosphorylation", "Z-Scheme", "Photolysis", "Mechanism of ATP synthesis"], "correctIndex": 3, "explanation": "The electron transport chain is the primary mechanism by which the proton gradient is used to drive ATP synthesis (oxidative phosphorylation). Photophosphorylation and photolysis are specific to photosynthesis, and the Z-scheme is a photosynthetic electron flow model.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 7, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#7 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q8_8", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 8, "subject": "Biology", "topic": "chlorophyll pigments", "question": "What is the colour of Chlorophyll-b molecule?", "options": ["Blueish green", "Yellowish green", "Dark Green", "Reddish green"], "correctIndex": 1, "explanation": "Chlorophyll b absorbs light in the blue and red-orange regions and reflects yellow-green wavelengths, so it appears yellowish-green. The other options describe colours not characteristic of chlorophyll b.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 8, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "UHS 2023 Q#8 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2023"}, {"id": "paper_q9_9", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 9, "subject": "Biology", "topic": "starch hydrolysis", "question": "Upon initial hydrolysis starch yields:", "options": ["Maltose", "Glucose", "Sucrose", "Mannose"], "correctIndex": 0, "explanation": "Enzymatic hydrolysis of starch (e.g., by amylase) initially produces maltose, a disaccharide of glucose. Free glucose is produced later after further hydrolysis; sucrose and mannose are not primary products of starch hydrolysis.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 9, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#9 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q10_10", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 10, "subject": "Biology", "topic": "water content of bone cells", "question": "Human Bone cells contain. ........% of water?", "options": ["20", "40", "85", "90"], "correctIndex": 0, "explanation": "Bone tissue contains relatively little water compared with soft tissues; cortical bone water content is around 20%. The higher percentages are typical of soft tissues, not bone.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 10, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2023 Q#10 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q11_11", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 11, "subject": "Biology", "topic": "protein tertiary structure", "question": "Unique three-dimensional shape of the fully folded polypeptide, constitutes:", "options": ["Primary structure of protein", "Secondary structure of protein", "Tertiary structure of protein", "Quaternary structure of protein"], "correctIndex": 2, "explanation": "The unique three-dimensional folding of a single polypeptide chain is its tertiary structure. Primary and secondary structures describe sequence and local folding, while quaternary refers to assembly of multiple polypeptide subunits.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 11, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2023 Q#11 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q12_12", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 12, "subject": "Biology", "topic": "fatty acid carbon number", "question": "Butyric acid is a ________ carbon fatty acid.", "options": ["6", "2", "4", "8"], "correctIndex": 2, "explanation": "Butyric acid (butanoic acid) has four carbon atoms in its chain, so it is a C4 fatty acid. The other numbers do not correspond to butyric acid's carbon count.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 12, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#12 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q13_13", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 13, "subject": "Biology", "topic": "conjugated molecules", "question": "Which of the following is a conjugated molecule?", "options": ["Protein", "Lipid", "Glycoproteins", "Vitamins"], "correctIndex": 2, "explanation": "Glycoproteins are conjugated molecules composed of a protein covalently linked to carbohydrate chains. Plain proteins and lipids are not conjugated in this sense, and 'vitamins' is a broad category not specifically a conjugated molecule.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 13, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#13 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q14_14", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 14, "subject": "Biology", "topic": "hydrolysis vs condensation", "question": "Hydrolysis process is a reverse of -------------------- process.", "options": ["Photolysis", "Condensation", "Deduction", "Convection"], "correctIndex": 1, "explanation": "Hydrolysis breaks bonds by the addition of water, which is the reverse of condensation (dehydration synthesis) where water is removed to form bonds. The other listed processes are unrelated chemical opposites.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 14, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#14 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q15_15", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 15, "subject": "Biology", "topic": "proteins function in cell", "question": "Proteins are the main ---------- of the cell?", "options": ["Physiological components", "Functional components", "Structural components", "Biological components"], "correctIndex": 1, "explanation": "Proteins perform most of the cell's functions (enzymes, transporters, receptors), so they are considered the main functional components. While some proteins have structural roles, 'functional components' best captures their primary cellular role.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 15, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2023 Q#15 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q16_16", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 16, "subject": "Biology", "topic": "mesosomes in prokaryotes", "question": "Structure formed by invagination of plasma membrane and involved in cell division and DNA replication of prokaryotic cell:", "options": ["Lysosomes", "Mesosomes", "Golgi bodies", "Phragmoplasts"], "correctIndex": 1, "explanation": "Mesosomes are infoldings of the prokaryotic plasma membrane historically associated with roles in DNA replication and cell division. Lysosomes and Golgi bodies are eukaryotic organelles; phragmoplasts are involved in plant cell cytokinesis.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 16, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2023 Q#16 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q17_17", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 17, "subject": "Biology", "topic": "single membrane organelles", "question": "Which of the following are single membranous organelles?", "options": ["Mitochondria and ribosomes", "Cytosol, mitochondria and ribosomes", "Golgi bodies, Lysosome and ER", "Golgi bodies, lysosome and mitochondria"], "correctIndex": 2, "explanation": "Golgi bodies, lysosomes and endoplasmic reticulum are single-membrane-bound organelles. Mitochondria have a double membrane and ribosomes are not membrane-bound, so options listing those are incorrect.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 17, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2023 Q#17 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q18_18", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 18, "subject": "Biology", "topic": "active transport", "question": "Movement of molecules against the concentration gradient is?", "options": ["Passive transport", "Active transport", "Facilitated diffusion", "Filtration"], "correctIndex": 1, "explanation": "Movement against a concentration gradient requires energy input and is termed active transport. Passive transport and facilitated diffusion move substances down their concentration gradients, and filtration is movement under pressure differences.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 18, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#18 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q19_19", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 19, "subject": "Biology", "topic": "lysosomes autophagy", "question": "The digestive vacuoles and autophagosomes are also known as?", "options": ["Phagocytosis", "Primary lysosome and autophagy", "Secondary lysosome", "Peroxisome"], "correctIndex": 2, "explanation": "Digestive vacuoles and autophagosomes become digestive structures by fusion with lysosomes, forming secondary (digestive) lysosomes. 'Phagocytosis' is a process, primary lysosomes are initial enzyme-containing vesicles, and peroxisomes are different organelles involved in oxidation reactions.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 19, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2023 Q#19 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q20_20", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 20, "subject": "Biology", "topic": "bacterial cell wall", "question": "The cell wall of Bacteria is made up of:", "options": ["Chitin", "Murein", "Cellulose", "Hemicellulose"], "correctIndex": 1, "explanation": "Bacterial cell walls are composed of peptidoglycan, also called murein. Chitin is found in fungal cell walls and arthropod exoskeletons; cellulose and hemicellulose are plant cell wall components.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 20, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2023 Q#20 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q21_21", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 21, "subject": "Biology", "topic": "shared cell features", "question": "Which one is common in both prokaryotic and eukaryotic cells?", "options": ["Cytoplasmic streaming movement", "Ribosome", "Binary fission", "Nuclear envelope"], "correctIndex": 1, "explanation": "Ribosomes are present in both prokaryotes and eukaryotes as the machinery for protein synthesis. Cytoplasmic streaming and nuclear envelopes are eukaryotic features; binary fission is a mode of cell division typical of prokaryotes.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 21, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2023 Q#21 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q22_22", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 22, "subject": "Biology", "topic": "neuron structure", "question": "There is no clear difference between dendrites and axons in sensory neurons, except:", "options": ["Thickness", "Length", "Terminal portions", "None of the above"], "correctIndex": 1, "explanation": "In sensory (unipolar or pseudounipolar) neurons the processes can appear similar, but axons are generally much longer than dendrites, making length the distinguishing feature. Thickness and terminal portions are not the principal distinguishing characteristics cited here.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 22, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "UHS 2023 Q#22 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2023"}, {"id": "paper_q23_23", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 23, "subject": "Biology", "topic": "neurotransmitters", "question": "The neurotransmitter active outside the CNS (Central Nervous System) is:", "options": ["Acetylcholine", "Dopamine", "Glutamate", "Serotonin"], "correctIndex": 0, "explanation": "Acetylcholine acts at neuromuscular junctions and in the peripheral nervous system. Dopamine, glutamate and serotonin are primarily central nervous system neurotransmitters.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 23, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#23 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q24_24", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 24, "subject": "Biology", "topic": "hormones and behaviour", "question": "A hormone that plays a major role in social bonding, childbirth, milk ejection and sexual reproduction is:", "options": ["Estrogen", "Oxytocin", "Prolactin", "Secretin"], "correctIndex": 1, "explanation": "Oxytocin is well known for roles in childbirth (uterine contractions), milk ejection, and social bonding. Estrogen and prolactin have different primary roles; secretin is a gastrointestinal hormone.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 24, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "UHS 2023 Q#24 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2023"}, {"id": "paper_q25_25", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 25, "subject": "Biology", "topic": "placental hormones", "question": "Hormone produced by placenta is:", "options": ["Follicle-Stimulating Hormone (FSH)", "Luteinizing Hormone (LH)", "Progesterone", "Testosterone"], "correctIndex": 2, "explanation": "The placenta synthesizes progesterone to support pregnancy. FSH and LH are pituitary gonadotropins and testosterone is primarily produced by testes (and to a lesser extent adrenal glands).", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 25, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "UHS 2023 Q#25 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2023"}, {"id": "paper_q26_26", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 26, "subject": "Biology", "topic": "meninges", "question": "The middle layer of meninges is:", "options": ["Arachnoid mater", "Pia mater", "Dura mater", "Cranium"], "correctIndex": 0, "explanation": "The three meninges from outer to inner are dura mater (outer), arachnoid mater (middle), and pia mater (inner). The cranium is the skull bone, not a meningeal layer.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 26, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#26 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q27_27", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 27, "subject": "Biology", "topic": "cerebellum function", "question": "The part of brain which guides smooth and accurate motions and maintains body position is:", "options": ["Cerebrum", "Cerebellum", "Pons", "Medulla"], "correctIndex": 1, "explanation": "The cerebellum coordinates fine motor control, balance and posture. The cerebrum handles higher functions, while pons and medulla have other brainstem roles.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 27, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "UHS 2023 Q#27 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2023"}, {"id": "paper_q28_28", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 28, "subject": "Biology", "topic": "echinoderm water vascular system", "question": "Water vascular system or ambulacral system is a unique and complex system specially present in?", "options": ["Sponges", "Arthropods", "Echinoderms", "Fishes"], "correctIndex": 2, "explanation": "The water vascular (ambulacral) system is characteristic of echinoderms (sea stars, sea urchins) and is used for locomotion and feeding. Sponges and arthropods lack this system; fishes are vertebrates and do not have it.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 28, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#28 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q29_29", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 29, "subject": "Biology", "topic": "phylum nematoda", "question": "Round worms belong to which phylum?", "options": ["Annelida", "Coelenterata", "Nematoda", "Platyhelminthes"], "correctIndex": 2, "explanation": "Roundworms belong to the phylum Nematoda. Annelida are segmented worms, Platyhelminthes are flatworms, and Coelenterata (Cnidaria) include jellyfish and corals.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 29, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#29 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q30_30", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 30, "subject": "Biology", "topic": "silverfish taxonomy", "question": "Silver fish is a/an?", "options": ["Insect", "Mollusc", "Jawless fish", "Cartilaginous fish"], "correctIndex": 0, "explanation": "The silverfish (order Zygentoma) is an insect. It is not a mollusc or a fish (jawless or cartilaginous).", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 30, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#30 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q31_31", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 31, "subject": "Biology", "topic": "tissue occurrence", "question": "Tissue are not found in the following animal?", "options": ["Flat worms", "Sponges", "Cnidarians", "Round worms"], "correctIndex": 1, "explanation": "Sponges (Porifera) lack true tissues and are organized at the cellular level. Flatworms, cnidarians and roundworms possess organized tissues.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 31, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#31 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q32_32", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 32, "subject": "Biology", "topic": "enzyme stabilization of transition state", "question": "Enzymes lower the activation energy by stabilizing the transition state of a metabolic reaction due to?", "options": ["Changing conditions within the active site", "Changing conditions within the protein framework", "Rearranging the fatty acids in active site", "Distorting the molecules in the allosteric site"], "correctIndex": 0, "explanation": "Enzymes provide an active-site environment that stabilizes the transition state and lowers activation energy. This is achieved by specific interactions at the active site rather than rearranging fatty acids or acting at an allosteric site in the ways described.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 32, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2023 Q#32 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q33_33", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 33, "subject": "Biology", "topic": "competitive inhibition", "question": "Competitive inhibitors compete with?", "options": ["Enzyme", "Substrate", "Product", "Coenzyme"], "correctIndex": 1, "explanation": "Competitive inhibitors bind the enzyme's active site and thus compete directly with the substrate for that site. They do not compete with the product or coenzyme.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 33, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2023 Q#33 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q34_34", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 34, "subject": "Biology", "topic": "non competitive inhibition", "question": "Non-competitive inhibitor molecules have:", "options": ["A similar structure to the normal substrate molecule", "A quite different structure from the substrate molecule", "A different conformation but fit into the active site", "A similar conformation but does not fit into the active site"], "correctIndex": 1, "explanation": "Non-competitive inhibitors typically have structures different from the substrate and bind at sites other than the active site, altering enzyme activity without directly competing for substrate binding. They are not required to mimic substrate structure.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 34, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2023 Q#34 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q35_35", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 35, "subject": "Biology", "topic": "metal ion cofactors", "question": "Zinc ion is attached at the active site of the enzyme carboxypeptidase. The zinc ion functions as", "options": ["A coenzyme molecule", "An activator", "An inhibitor molecule", "Controller of Allosteric site"], "correctIndex": 1, "explanation": "Zinc acts as a metal cofactor/activator in many metalloproteases like carboxypeptidase, participating in catalysis. It is not a coenzyme (which is organic) nor an inhibitor or allosteric controller in this context.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 35, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2023 Q#35 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q36_36", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 36, "subject": "Biology", "topic": "optimal environmental pH", "question": "What is the best physiological pH for optimum functioning for most of the cellular enzymes of human?", "options": ["2-3 pH", "3-5 pH", "6-8 pH", "8-10 pH"], "correctIndex": 2, "explanation": "Most human cellular enzymes function optimally around neutral pH, approximately 6–8. Extremely acidic or alkaline pH ranges denature many enzymes and are not physiologically optimal.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 36, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2023 Q#36 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q37_37", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 37, "subject": "Biology", "topic": "acquired traits", "question": "Adaptations that an organism acquires by its own actions during its life span without modifying its genome are:", "options": ["Heritable", "Non-heritable", "Can be made heritable through some modification", "Sometimes heritable and other times non-heritable"], "correctIndex": 1, "explanation": "Traits acquired during an individual's lifetime (Lamarckian-type acquired characteristics) are not inherited through changes in the genome and are therefore non-heritable. True heritable adaptations involve genetic change across generations.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 37, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#37 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q38_38", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 38, "subject": "Biology", "topic": "geographical barriers", "question": "For evolutionary process to occur, which of the following is NOT a geographical barrier?", "options": ["Ocean", "River", "Mountains", "Atmosphere"], "correctIndex": 3, "explanation": "Oceans, rivers and mountains can all act as physical geographic barriers that limit gene flow; the atmosphere is not a geographic barrier that separates populations in the same way.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 38, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "UHS 2023 Q#38 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2023"}, {"id": "paper_q39_39", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 39, "subject": "Biology", "topic": "biogenetic law", "question": "According to the Biogenetic Law of Ernst Haeckel:", "options": ["There is survival of the fittest", "There is use and disuse of organs", "Phylogeny recapitulates ontogeny", "Ontogeny recapitulates phylogeny"], "correctIndex": 3, "explanation": "Haeckel's biogenetic law is commonly summarized as 'ontogeny recapitulates phylogeny' - the development of the individual mirrors the evolutionary history of the species. The other statements describe different evolutionary or erroneous ideas.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 39, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#39 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q40_40", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 40, "subject": "Biology", "topic": "galapagos species", "question": "The animal species on Galapagos resemble species living on the:", "options": ["Northern Europe", "Great Britain", "North American mainland", "South American mainland"], "correctIndex": 3, "explanation": "Darwin noted that Galapagos fauna most closely resemble those from the nearby South American mainland due to colonization and subsequent divergence. The other regions listed are geographically and biogeographically distant from the Galapagos.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 40, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#40 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q41_41", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 41, "subject": "Biology", "topic": "hepatic portal vein", "question": "Digested food from intestine is carried to the liver by?", "options": ["Hepatic artery", "Hepatic vein", "Hepatic portal vein", "Hepatic portal artery"], "correctIndex": 2, "explanation": "Nutrients absorbed from the intestine are transported to the liver via the hepatic portal vein. The hepatic artery supplies oxygenated blood, while the hepatic vein carries blood away from the liver.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 41, "syllabusUnit": "Unit 5: Human Physiology - Digestion & Nutrition", "pmdcTopic": "Human Digestive System & Absorption Mechanisms", "textbookCitation": "PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12", "citationString": "UHS 2023 Q#41 | Unit 5: Human Physiology - Digestion & Nutrition | PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12"}, "year": "2023"}, {"id": "paper_q42_42", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 42, "subject": "Biology", "topic": "antibody production", "question": "---------- proteins are produced by WBCs in response to -------- and provide immunity?", "options": ["Antibiotics, antigen", "Antibodies, RBC", "Globulin, histamine", "Antibodies, antigen"], "correctIndex": 3, "explanation": "White blood cells produce antibodies in response to antigens; antibodies bind specific antigens to neutralize or mark them for destruction. The other pairings are incorrect (antibiotics are drugs; antibodies are not produced in response to RBC).", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 42, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2023 Q#42 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q43_43", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 43, "subject": "Biology", "topic": "lymphatic drainage", "question": "The lymphatic vessels of the body empty the lymph into blood stream at ?", "options": ["Abdominal vein", "Jugular vein", "Subclavian vein", "Bile duct"], "correctIndex": 2, "explanation": "Lymphatic ducts drain into the venous system at the subclavian veins (usually at the junction with the internal jugular). The bile duct is unrelated and the abdominal or jugular veins alone are not the typical drainage point named.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 43, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "UHS 2023 Q#43 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2023"}, {"id": "paper_q44_44", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 44, "subject": "Biology", "topic": "capillary flow regulation", "question": "Flow of blood in the capillaries is adjusted by?", "options": ["Heart directly", "Pre-capillary sphincters", "Meta-arteriole", "Valves"], "correctIndex": 1, "explanation": "Pre-capillary sphincters regulate blood flow into capillary beds by contracting or relaxing, altering perfusion. The heart controls overall flow, meta-arterioles are conduits, and valves are in veins, not capillary-level regulators.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 44, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "UHS 2023 Q#44 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2023"}, {"id": "paper_q45_45", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 45, "subject": "Biology", "topic": "osmotic pressure", "question": "The pressure exerted by a solution separated by a semipermeable membrane from pure water is_______?", "options": ["Osmotic Pressure", "Soil potential", "Solute Potential", "Solvent potential"], "correctIndex": 0, "explanation": "The pressure required to prevent net solvent flow across a semipermeable membrane is osmotic pressure. Soil potential and solute/solvent potential are related concepts but osmotic pressure is the correct term here.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 45, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2023 Q#45 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q46_46", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 46, "subject": "Biology", "topic": "anaerobic respiration effects", "question": "Which of the following is NOT a consequence of anaerobic respiration in humans muscles cells?", "options": ["Cramps", "High consumption of energy", "Pain", "Tiredness"], "correctIndex": 1, "explanation": "Anaerobic respiration yields much less ATP than aerobic respiration, so it does not involve high energy consumption; in fact it is less efficient. Cramps, pain and tiredness are common consequences of anaerobic metabolism and lactic acid buildup.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 46, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2023 Q#46 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q47_47", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 47, "subject": "Biology", "topic": "respiratory surface properties", "question": "The respiratory surfaces exhibit following characteristic?", "options": ["It must be permeable", "It must be thick for low diffusion", "It should be non-vascularized", "It should have low ventilation mechanism"], "correctIndex": 0, "explanation": "Respiratory surfaces must be permeable and very thin to allow rapid gas diffusion. Being thick or non-vascularized or having low ventilation would impede efficient gas exchange.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 47, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#47 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q48_48", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 48, "subject": "Biology", "topic": "prokaryote examples", "question": "Which of the following is a prokaryote?", "options": ["Protista", "E.coli", "Amoeba", "Fungi"], "correctIndex": 1, "explanation": "Escherichia coli is a bacterium and therefore a prokaryote (no membrane-bound nucleus). Protists, amoebae and fungi are eukaryotic organisms with true nuclei.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 48, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#48 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q49_49", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 49, "subject": "Biology", "topic": "gram negative cell wall layers", "question": "Number of layers present in Gram-negative bacterial cell wall :", "options": ["one", "two", "three", "four"], "correctIndex": 1, "explanation": "Gram-negative bacteria characteristically have two main layers associated with the cell envelope: an inner cytoplasmic (plasma) membrane and an outer membrane with a thin peptidoglycan layer in between. That makes \"two\" the correct count; the other choices (one, three, four) do not describe the typical Gram‑negative envelope structure.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 49, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2023 Q#49 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q50_50", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 50, "subject": "Biology", "topic": "sarcina formation cocci", "question": "The division of cocci in three planes form Sarcina, which is a cube of ------------ Cocci?", "options": ["02", "04", "08", "16"], "correctIndex": 2, "explanation": "Sarcinae are formed when cocci divide in three perpendicular planes giving packets of 2×2×2 cells, i.e. 8 cells. The other numbers (2, 4, 16) describe other arrangements (pairs, tetrads, larger packets) but not the classic Sarcina cube of eight.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 50, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#50 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q51_51", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 51, "subject": "Biology", "topic": "nitrifying bacteria classification", "question": "Nitrifying bacteria are the examples of:", "options": ["Heterotrophic bacteria", "Chemosynthetic bacteria", "Saprophytic bacteria", "Parasitic bacteria"], "correctIndex": 1, "explanation": "Nitrifying bacteria obtain energy by oxidizing inorganic nitrogen compounds (e.g., ammonia to nitrite, nitrite to nitrate) rather than from organic matter; this chemolithotrophic metabolism falls under chemosynthesis. They are not heterotrophs (which use organic carbon for energy), saprophytes (decomposers of organic matter), or parasites.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 51, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "UHS 2023 Q#51 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2023"}, {"id": "paper_q52_52", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 52, "subject": "Biology", "topic": "testis lobule count", "question": "Each human testis is divided into:", "options": ["50-100 lobules", "150-200 lobules", "200-300 lobules", "250-300 lobules"], "correctIndex": 2, "explanation": "Each human testis is typically subdivided into roughly 200–300 lobules by septa, so the 200–300 range is the best answer. The other ranges are either too small (50–100, 150–200) or an overlapping narrower range (250–300) that is less commonly given as the standard description.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 52, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "UHS 2023 Q#52 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2023"}, {"id": "paper_q53_53", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 53, "subject": "Biology", "topic": "testosterone producing cells", "question": "Which cells in the human males are responsible for the release of testosterone?", "options": ["Pituitary Gland", "Hypothalamus", "Sertoli cells", "Leydig cells or interstitial cells"], "correctIndex": 3, "explanation": "Leydig (interstitial) cells in the testes synthesize and secrete testosterone in response to LH stimulation. The pituitary and hypothalamus regulate this process hormonally but do not produce testosterone, and Sertoli cells support spermatogenesis rather than producing testosterone.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 53, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "UHS 2023 Q#53 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2023"}, {"id": "paper_q54_54", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 54, "subject": "Biology", "topic": "site of implantation", "question": "Fertilized ovum is implanted and undergoes further development in the:", "options": ["Ovary", "Uterus", "Oviduct", "Cervix"], "correctIndex": 1, "explanation": "After fertilization (usually in the oviduct), the embryo travels to and implants in the endometrium of the uterus where further development occurs. The ovary is the site of ovulation, the oviduct is the usual site of fertilization, and the cervix is the lower uterine outlet and not the normal implantation site.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 54, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#54 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q55_55", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 55, "subject": "Biology", "topic": "lh peak", "question": "Level of luteinizing hormone (LH) is maximum in blood during which stage of menstrual cycle?", "options": ["Menstrual stage", "Proliferative stage", "Ovulation stage", "Secretory stage"], "correctIndex": 2, "explanation": "LH surges immediately before and during ovulation, triggering release of the secondary oocyte. The other stages do not feature the LH peak.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 55, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "UHS 2023 Q#55 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2023"}, {"id": "paper_q56_56", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 56, "subject": "Biology", "topic": "syphilis transmission", "question": "Major source of transmission of syphilis is:", "options": ["Blood transfusion", "Insect bite", "Contaminated water", "Sexual contact"], "correctIndex": 3, "explanation": "Syphilis (Treponema pallidum) is primarily sexually transmitted through contact with infectious lesions. Although blood transfusion transmission is possible historically, sexual contact is the main route.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 56, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#56 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q57_57", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 57, "subject": "Biology", "topic": "cartilage false statement", "question": "What is FALSE about cartilage?", "options": ["There are many blood vessels in cartilage", "It is a form of connective tissue", "It covers ends of the bones at joints", "It is much softer than bone"], "correctIndex": 0, "explanation": "Cartilage is avascular (lacks blood vessels) and receives nutrients by diffusion, so the statement that there are many blood vessels is false. The other statements correctly describe cartilage's nature and function.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 57, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "UHS 2023 Q#57 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2023"}, {"id": "paper_q58_58", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 58, "subject": "Biology", "topic": "creatine phosphate", "question": "Which of the following is a muscle component that act as store for energy?", "options": ["ATP", "Creatine-PO4", "Myoglobin", "Creatinine-PO4"], "correctIndex": 1, "explanation": "Creatine phosphate (creatine-PO4) serves as a rapid reserve of high-energy phosphate in muscle to regenerate ATP during short bursts of activity. ATP is the immediate energy carrier, myoglobin stores oxygen, and creatinine-PO4 is not an energy-storage molecule.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 58, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "UHS 2023 Q#58 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2023"}, {"id": "paper_q59_59", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 59, "subject": "Biology", "topic": "muscle composition", "question": "Which of the following is NOT found in skeletal muscle fibers in human?", "options": ["Multiple nuclei", "Multiple mitochondria", "Large amount of myoglobin", "Large amount of hemoglobin"], "correctIndex": 3, "explanation": "Skeletal muscle fibers contain multiple nuclei, many mitochondria and myoglobin to store oxygen; hemoglobin is found in red blood cells, not inside muscle fibers.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 59, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "UHS 2023 Q#59 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2023"}, {"id": "paper_q60_60", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 60, "subject": "Biology", "topic": "hinge joint", "question": "Hinge joint is present between which of the following bones?", "options": ["Humerus and radio-ulna", "Femur and pectoral girdle", "Femur and acetabulum", "Humerus and pectoral girdle"], "correctIndex": 0, "explanation": "The elbow joint between the humerus and the radius/ulna (radio-ulna) is a hinge joint permitting flexion and extension. The other pairings refer to ball-and-socket or shoulder girdle relationships.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 60, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "UHS 2023 Q#60 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2023"}, {"id": "paper_q61_61", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 61, "subject": "Biology", "topic": "rh incompatibility", "question": "What happens when a Rh -ve woman, married to a Rh +ve man conceives a child who is Rh +ve?", "options": ["Maternal-foetal incompatibility", "Paternal-foetal incompatibility", "Cancer of fetus", "Death of mother"], "correctIndex": 0, "explanation": "When an Rh-negative mother carries an Rh-positive fetus, maternal antibodies can form against fetal red cell antigens leading to maternal–fetal (foetal) incompatibility and hemolytic disease of the newborn. The other options are not the typical consequence.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 61, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#61 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q62_62", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 62, "subject": "Biology", "topic": "genes", "question": "DNA stores biological information in discrete units termed as:", "options": ["Genes", "Phenotypes", "Karyotypes", "Cells"], "correctIndex": 0, "explanation": "Genes are discrete units of hereditary information encoded in DNA. Phenotypes are observable traits, karyotypes are chromosome sets, and cells are biological units, not the discrete informational unit in DNA.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 62, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2023 Q#62 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q63_63", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 63, "subject": "Biology", "topic": "drosophila sex linkage", "question": "To study sex linkages in Drosophila, Morgan mated white eyed males with wild type red eyed females. What will be the phenotype of offspring?", "options": ["All red eyed males and females", "Red eyed females and white eyed males", "White eyed females and red eyed males", "All white eyed females and males"], "correctIndex": 0, "explanation": "White eye is an X-linked recessive trait. Crossing white-eyed males (XwY) with red-eyed homozygous females (X+X+) yields X+Xw females (red-eyed) and X+Y males (red-eyed), so all offspring are red-eyed.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 63, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "UHS 2023 Q#63 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2023"}, {"id": "paper_q64_64", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 64, "subject": "Biology", "topic": "x linked dominant", "question": "Which one of the following is X Linked Dominant disorder?", "options": ["Haemophilia", "Color blindness", "Hypophosphatemic rickets", "Hypertrichosis"], "correctIndex": 2, "explanation": "Hypophosphatemic rickets is classically inherited as an X-linked dominant condition. Haemophilia and color blindness are X-linked recessive; hypertrichosis is not the typical X-linked dominant example here.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 64, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "UHS 2023 Q#64 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2023"}, {"id": "paper_q65_65", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 65, "subject": "Biology", "topic": "pedigree analysis", "question": "Mode of inheritance in humans can be traced through:", "options": ["Experimental Mating", "Chi Square Chart", "Pedigree Analysis", "Probability Analysis"], "correctIndex": 2, "explanation": "Pedigree analysis traces inheritance patterns through family histories to determine the mode of inheritance in humans; experimental mating is not feasible in humans.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 65, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "UHS 2023 Q#65 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2023"}, {"id": "paper_q66_66", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 66, "subject": "Chemistry", "topic": "amu definition", "question": "One a. m .u stands for", "options": ["An atom of C - 12", "1/12th of a carbon", "1/12th of H", "1 atom of all the elements"], "correctIndex": 1, "explanation": "One atomic mass unit (amu) is defined as one twelfth of the mass of a carbon-12 atom. It is not an entire carbon atom or hydrogen fraction except the defined 1/12th of C-12.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 66, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2023 Q#66 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q67_67", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 67, "subject": "Chemistry", "topic": "empirical formula", "question": "A compound of sodium oxide has 74.2 % sodium and 25.8% of Oxygen. The empirical formula of the compound is?", "options": ["NaO", "NaO2", "Na2O", "Na2O2"], "correctIndex": 2, "explanation": "Converting percentages to mole ratio gives Na: 74.2/23 ≈3.226 and O: 25.8/16 ≈1.612, which simplifies to a 2:1 ratio of Na:O, so the empirical formula is Na2O.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 67, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "UHS 2023 Q#67 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2023"}, {"id": "paper_q68_68", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 68, "subject": "Chemistry", "topic": "oxidation of secondary alcohols", "question": "grams of 2-propanol were mixed with excess acidified K2Cr2O7 and boiled under reflux for 20 minutes. The organic product was then collected by distillation. The yield of product was 75.0%. What is the mass of product produced?", "options": ["1.74g", "21.75g", "2.74g", "29.9 g"], "correctIndex": 1, "explanation": "2-Propanol (60.1 g/mol) oxidizes to acetone (58.08 g/mol). 30 g corresponds to ≈0.499 mol, theoretical acetone mass ≈0.499×58.08 ≈28.99 g; at 75% yield the product mass ≈0.75×28.99 ≈21.74 g (≈21.75 g).", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 68, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "UHS 2023 Q#68 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2023"}, {"id": "paper_q69_69", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 69, "subject": "Chemistry", "topic": "schrodinger equation", "question": "According to which scientist, the probability of finding an electron at a certain position is possible?", "options": ["Bohr's", "De-Broglie", "Hund's", "Schrodinger"], "correctIndex": 3, "explanation": "Schrödinger's wave mechanics introduced the wavefunction whose squared magnitude gives the probability density of finding an electron at a given position. Bohr, de Broglie and Hund contributed other foundational ideas but not this probability interpretation.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 69, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2023 Q#69 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q70_70", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 70, "subject": "Chemistry", "topic": "canal rays", "question": "Which gas in the discharge tube produces lightest canal ray particles?", "options": ["Ar", "He", "H2", "Ne"], "correctIndex": 2, "explanation": "Canal rays are positive ions produced in discharge tubes; the lightest positive ions come from hydrogen gas (H2), producing H+ (proton) which is lighter than ions from He, Ne or Ar.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 70, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2023 Q#70 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "paper_q71_71", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 71, "subject": "Chemistry", "topic": "electronic configuration", "question": "Which element has the ground state electronic configuration of 1s2, 2s2, 2p6, 3s2, 3p6?", "options": ["Ar", "Cl", "Na", "S"], "correctIndex": 0, "explanation": "The configuration 1s2 2s2 2p6 3s2 3p6 corresponds to argon (atomic number 18). Chlorine, sodium and sulfur have different electron counts.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 71, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "UHS 2023 Q#71 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2023"}, {"id": "paper_q72_72", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 72, "subject": "Chemistry", "topic": "unpaired electrons", "question": "What is the proton (atomic number) of an element that has four unpaired electrons in its ground state?", "options": ["6", "14", "22", "26"], "correctIndex": 3, "explanation": "An element with four unpaired electrons in the ground state corresponds to a d6 high-spin configuration (e.g., iron, Z=26, with 3d6 in many cases gives four unpaired electrons). The other atomic numbers do not match a 4-unpaired-electron ground-state in this context.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 72, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "UHS 2023 Q#72 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2023"}, {"id": "paper_q73_73", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 73, "subject": "Chemistry", "topic": "partial pressure", "question": "A gaseous mixture contains 9.6% NH3, 22.6% N2 and 67.8% H2 gases. If the total pressure is 50 atm, then the partial pressure of H2 is", "options": ["67.8 x100 / 50", "50 x 100 / 100", "67.8 x 50 / 100", "67.8 + 50 / 100"], "correctIndex": 2, "explanation": "Partial pressure equals the mole (or volume) fraction times total pressure. For H2: (67.8/100)×50 atm = 67.8×50/100, so option c is correct.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 73, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2023 Q#73 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "paper_q74_74", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 74, "subject": "Chemistry", "topic": "gas constant", "question": "If we want to raise the temperature of one mole of an ideal gas by one kelvin, we have to provide how much amount of energy?", "options": ["0.0821 joules", "8.314 dm3·atm", "0.0821 kJ", "0.0821 dm3·atm"], "correctIndex": 3, "explanation": "The gas constant R equals 0.0821 dm3·atm·mol⁻¹·K⁻¹, which is numerically 8.314 J·mol⁻¹·K⁻¹. Expressed in dm3·atm units the value is 0.0821 dm3·atm per mole per kelvin, matching option d.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 74, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2023 Q#74 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "paper_q75_75", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 75, "subject": "Chemistry", "topic": "kinetic theory", "question": "The process of heat flow between hotter and colder gases remains continued until all the molecules have equal", "options": ["Average translational kinetic energy", "Average rotational kinetic energy", "Average translational potential energy", "Average vibrational kinetic energy"], "correctIndex": 0, "explanation": "Heat flow between gases continues until thermal equilibrium is reached, which means the average translational kinetic energy (related to temperature) of the molecules becomes equal. Translational kinetic energy is the relevant measure of temperature.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 75, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2023 Q#75 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "paper_q76_76", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 76, "subject": "Chemistry", "topic": "dipole dipole effects", "question": "In liquid, with the change in dipole-dipole forces, there is a change in some physical properties. Select the property which is not affected by the strength of dipole-dipole forces?", "options": ["boiling point", "heat of vaporization", "heat of sublimation", "moles"], "correctIndex": 3, "explanation": "Dipole–dipole interactions influence properties like boiling point, heat of vaporization and sublimation, but the number of moles (an amount of substance) is independent of intermolecular force strength.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 76, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2023 Q#76 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "paper_q77_77", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 77, "subject": "Chemistry", "topic": "vapor pressure", "question": "Which of the following factor does not affect the magnitude of vapor pressure?", "options": ["amount of liquid", "size of molecule", "temperature of liquid", "intermolecular forces"], "correctIndex": 0, "explanation": "Provided some liquid is present, the equilibrium vapor pressure is independent of the total amount of liquid. Vapor pressure depends strongly on temperature, intermolecular forces and molecular properties.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 77, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2023 Q#77 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q78_78", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 78, "subject": "Chemistry", "topic": "unit cell", "question": "A small building block which belongs to whole information about crystal structure is called?", "options": ["Cell", "Unit Cell", "Crystal lattice", "Crystal unit"], "correctIndex": 1, "explanation": "The unit cell is the smallest repeating building block that contains all the information needed to generate the entire crystal lattice. A 'cell' or 'crystal unit' are vague terms and the 'crystal lattice' is the extended array produced by repeating the unit cell.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 78, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2023 Q#78 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "paper_q79_79", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 79, "subject": "Chemistry", "topic": "atomic solids", "question": "Which type of solid is called as atomic solid?", "options": ["Covalent solids", "Ionic solids", "Metallic solids", "Molecular solids"], "correctIndex": 2, "explanation": "Atomic solids are solids whose lattice sites are occupied by atoms rather than molecules or ions - this describes metallic solids. Covalent and molecular solids involve directional bonding or discrete molecules, and ionic solids are composed of ions.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 79, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "UHS 2023 Q#79 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2023"}, {"id": "paper_q80_80", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 80, "subject": "Chemistry", "topic": "common ion effect", "question": "The decrease in solubility of the salt in a solution that already contains an ion common to that salt is known as:", "options": ["Le Chatelier's principle", "Solubility Product", "Common ion effect", "Ksp"], "correctIndex": 2, "explanation": "When a solution already contains an ion in common with a slightly soluble salt, the equilibrium shifts to reduce solubility - this phenomenon is the common ion effect. Le Chatelier's principle explains the behavior but the specific term is 'common ion effect'; 'Ksp' is the solubility product constant.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 80, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "UHS 2023 Q#80 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2023"}, {"id": "paper_q81_81", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 81, "subject": "Chemistry", "topic": "solubility product", "question": "The precipitation occurs if the ionic concentration is:", "options": ["Less than ksp", "More than ksp", "Equal to ksp", "Present in any amount"], "correctIndex": 1, "explanation": "Precipitation begins when the ionic product exceeds the solubility product (Ksp). If it's equal, the system is at saturation; less than Ksp is undersaturated.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 81, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "UHS 2023 Q#81 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2023"}, {"id": "paper_q82_82", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 82, "subject": "Chemistry", "topic": "le chatelier principle", "question": "One can estimate the direction in which equilibrium will shift with the help of:", "options": ["Le Chatelier's principle", "Law of mass action", "Mess's law", "Law of heat of formation"], "correctIndex": 0, "explanation": "Le Chatelier's principle predicts how an equilibrium shifts when conditions (concentration, pressure, temperature) are changed. The law of mass action gives the equilibrium expression but not the directional response to disturbances.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 82, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "UHS 2023 Q#82 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2023"}, {"id": "paper_q83_83", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 83, "subject": "Chemistry", "topic": "rate law order", "question": "What is the overall order of this rate equation? Rate =k[H3][NO2]2", "options": ["1", "2", "3", "4"], "correctIndex": 2, "explanation": "Overall order is the sum of the exponents in the rate law: 1 (for [H3]) + 2 (for [NO2]) = 3. Orders 1, 2, 4 would correspond to different exponent sums.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 83, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "UHS 2023 Q#83 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2023"}, {"id": "paper_q84_84", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 84, "subject": "Chemistry", "topic": "homogeneous vs heterogeneous catalysis", "question": "The catalysis in which the catalyst and the reactants are in the same phase is known?", "options": ["Heterogeneous catalyst", "Homogeneous catalyst", "Slow", "Fast"], "correctIndex": 1, "explanation": "When catalyst and reactants are in the same phase (typically all in solution or all gaseous), the catalysis is termed homogeneous. Heterogeneous catalysts are in a different phase than the reactants.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 84, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "UHS 2023 Q#84 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2023"}, {"id": "paper_q85_85", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 85, "subject": "Chemistry", "topic": "born haber cycle", "question": "Born-Haber cycle is used to determine the Lattice energy of ionic compounds. It is the application of", "options": ["Henry's law", "Le - Chatleir's Principle", "Hess's law", "Common ion effect"], "correctIndex": 2, "explanation": "The Born–Haber cycle uses Hess's law to combine several enthalpy steps into the lattice energy. It is not an application of Henry's law or the common ion effect; Le Chatelier's principle is unrelated.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 85, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2023 Q#85 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "paper_q86_86", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 86, "subject": "Chemistry", "topic": "state functions", "question": "Which of the following term is state function?", "options": ["freezing", "decomposition", "sublimation", "enthalpy"], "correctIndex": 3, "explanation": "Enthalpy is a thermodynamic state function (depends only on initial and final states). Processes like freezing, decomposition and sublimation describe changes or transitions rather than state functions themselves.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 86, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2023 Q#86 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q87_87", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 87, "subject": "Chemistry", "topic": "electrochemical cells", "question": "An electrochemical cell is based upon which reaction?", "options": ["Acid-base reaction", "Redox reaction", "Nuclear reaction", "Neutralization reaction"], "correctIndex": 1, "explanation": "Electrochemical cells convert chemical energy to electrical energy (or vice versa) via oxidation–reduction (redox) reactions. Acid–base and neutralization reactions are not the fundamental basis for electrochemical cell operation.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 87, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2023 Q#87 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q88_88", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 88, "subject": "Chemistry", "topic": "oxidation numbers", "question": "In which of the following, oxygen shows fractional oxidation number?", "options": ["OF2", "Na2O2", "KO2", "Cl2O7"], "correctIndex": 2, "explanation": "In superoxides like KO2 each O has an average oxidation state of −1/2 (fractional). In OF2 oxygen is +2, in peroxides (Na2O2) oxygen is −1 (integral), and in Cl2O7 oxygen is −2.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 88, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "UHS 2023 Q#88 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2023"}, {"id": "paper_q89_89", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 89, "subject": "Chemistry", "topic": "atomic size periodic trend", "question": "Which of the following element has smaller size?", "options": ["Na", "K", "Al", "Li"], "correctIndex": 2, "explanation": "Aluminum (Al) lies further right in the same or higher period than the alkali metals shown, so it has a higher effective nuclear charge and a smaller atomic radius than Na, K, or Li.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 89, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "UHS 2023 Q#89 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2023"}, {"id": "paper_q90_90", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 90, "subject": "Chemistry", "topic": "ionic character", "question": "Among LiCl, BeCl2, NaCl, CsCl, the compounds with the greatest and the least ionic character respectively are:", "options": ["LiCl and CsCl", "NaCl and LiCl", "CsCl and NaCl", "CsCl and BeCl2"], "correctIndex": 3, "explanation": "CsCl is the most ionic among the choices due to the large electropositive cesium; BeCl2 is the least ionic because the small, highly charged Be2+ strongly polarizes the anion, increasing covalent character.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 90, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2023 Q#90 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q91_91", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 91, "subject": "Chemistry", "topic": "oxidation reduction", "question": "Which statement describes the conversion of magnesium atoms to magnesium ions for ionic bond formation with chlorine?", "options": ["The change is reduction, because there has been a gain of electrons", "The change is oxidation, because there has been a loss of electrons", "The change is reduction, because there has been a loss of electrons", "The change is oxidation, because there has been a gain of electrons"], "correctIndex": 1, "explanation": "Mg → Mg2+ involves loss of electrons, which is oxidation. Options claiming reduction or gain of electrons are incorrect for this conversion.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 91, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "UHS 2023 Q#91 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2023"}, {"id": "paper_q92_92", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 92, "subject": "Chemistry", "topic": "molecular geometry", "question": "AB4 Type with no Lone Pairs geometry enables to form which shape of molecule?", "options": ["Trigonal", "Regular tetrahedron", "Regular octahedron", "Regular pyramidal"], "correctIndex": 1, "explanation": "An AB4 molecule with no lone pairs on the central atom adopts a regular tetrahedral geometry. Trigonal or octahedral geometries correspond to different coordination numbers; pyramidal implies a lone pair.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 92, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "UHS 2023 Q#92 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2023"}, {"id": "paper_q93_93", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 93, "subject": "Chemistry", "topic": "aluminum chloride dimerization", "question": "Why dimer of Aluminum chloride is formed", "options": ["Aluminum is electron rich", "Aluminum is having lone pair of electron", "Aluminum donates lone pair to form bridge", "Aluminum forms coordinate bonds with chlorine to complete its octet"], "correctIndex": 3, "explanation": "AlCl3 is electron-deficient (Al has an incomplete octet) and forms Al2Cl6 where Al accepts electron density from chloride to form coordinate (bridge) bonds, completing its octet. The other options misstate the electron situation.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 93, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2023 Q#93 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q94_94", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 94, "subject": "Chemistry", "topic": "group properties", "question": "Which group of the periodic table contain non-metals, metalloids and metals.", "options": ["I B", "VII A", "IV A", "VI A"], "correctIndex": 2, "explanation": "Group IV A (group 14) contains carbon (non-metal), silicon (metalloid), and tin/lead (metals), so it includes all three types. The other groups listed are less diverse in that way.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 94, "syllabusUnit": "Unit 8: Inorganic Chemistry & Periodicity", "pmdcTopic": "Periodic Trends, Group Chemistry & Transition Elements", "textbookCitation": "PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16", "citationString": "UHS 2023 Q#94 | Unit 8: Inorganic Chemistry & Periodicity | PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16"}, "year": "2023"}, {"id": "paper_q95_95", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 95, "subject": "Chemistry", "topic": "solubility rules", "question": "Which of the following sulfate compound is insoluble in water ?", "options": ["BeSO4", "BaSO4", "MgSO4", "CaSO4"], "correctIndex": 1, "explanation": "Barium sulfate (BaSO4) is essentially insoluble in water and is a classic precipitate in qualitative analysis. BeSO4, MgSO4 and CaSO4 are significantly more soluble.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 95, "syllabusUnit": "Unit 13: Macromolecules & Industrial Chemistry", "pmdcTopic": "Synthetic & Natural Polymers, Amino Acids and Proteins", "textbookCitation": "PTB Chemistry XII Ch 14 (Macromolecules); Federal Chemistry XII Ch 22", "citationString": "UHS 2023 Q#95 | Unit 13: Macromolecules & Industrial Chemistry | PTB Chemistry XII Ch 14 (Macromolecules); Federal Chemistry XII Ch 22"}, "year": "2023"}, {"id": "paper_q96_96", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 96, "subject": "Chemistry", "topic": "coordination geometry", "question": "Which of the following complex show a tetrahedral geometry?", "options": ["[Fe(CO)5]", "[Cu(CN)4]-2", "[Au(Cl)4]-", "[Pt(NH3)4]+2"], "correctIndex": 1, "explanation": "Four-coordinate Cu(I) cyanide complexes often adopt a tetrahedral geometry, while [Fe(CO)5] is trigonal bipyramidal, [AuCl4]- and [Pt(NH3)4]2+ are typically square planar.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 96, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "UHS 2023 Q#96 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2023"}, {"id": "paper_q97_97", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 97, "subject": "Chemistry", "topic": "d orbital electron configurations", "question": "In which pair one has all Unpaired d orbitals while other have all paired d orbitals ?", "options": ["Cu and Zn", "Cr and Fe", "Cr and Zn", "Mn and Co"], "correctIndex": 2, "explanation": "Chromium (Cr) has a d5 configuration in its ground state, so its d orbitals are all singly occupied (unpaired). Zinc (Zn) has a d10 configuration with all d electrons paired. Therefore Cr and Zn match the statement.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 97, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "UHS 2023 Q#97 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2023"}, {"id": "paper_q98_98", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 98, "subject": "Chemistry", "topic": "hybridization of carbon", "question": "In which of the following functional groups, the carbon atom is sp hybridized?", "options": ["-CHO", "-COOH", "-CN", "-COOR"], "correctIndex": 2, "explanation": "The carbon in a nitrile (-CN) is involved in a carbon–nitrogen triple bond and is sp-hybridized. The other listed functional groups have sp2 or sp3 carbon atoms.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 98, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "UHS 2023 Q#98 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2023"}, {"id": "paper_q99_99", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 99, "subject": "Chemistry", "topic": "thiols nomenclature", "question": "The compounds containing R-SH functional group are known as:", "options": ["Alcohols", "Thio-alcohols", "Thio-ether", "Nitrile"], "correctIndex": 1, "explanation": "R–SH functional groups are commonly called thiols (sometimes called thio-alcohols). Alcohols are R–OH, thio-ethers are R–S–R, and nitriles are R–C≡N.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 99, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2023 Q#99 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q100_100", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 100, "subject": "Chemistry", "topic": "constitutional isomers", "question": "What is the number of isomers of a hydrocarbon having a molecular formula, C4H8?", "options": ["2", "3", "4", "5"], "correctIndex": 3, "explanation": "C4H8 has five structural (constitutional) isomers: 1-butene, 2-butene, 2-methylpropene (isobutene), cyclobutane and methylcyclopropane. Counting these gives five distinct isomers.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 100, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "UHS 2023 Q#100 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2023"}, {"id": "paper_q101_101", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 101, "subject": "Chemistry", "topic": "friedel crafts alkylation", "question": "Alkylbenzene is formed when benzene is treated with an alkyl halide in the presence of anhydrous aluminum chloride. Identify the type of reaction.", "options": ["Halogenation", "Friedel-Crafts acylation reaction", "Friedel-Crafts alkylation reaction", "Sulphonation"], "correctIndex": 2, "explanation": "The reaction of benzene with an alkyl halide using AlCl3 is the Friedel–Crafts alkylation, which introduces an alkyl group onto the aromatic ring. Acylation uses acyl halides, not alkyl halides.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 101, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "UHS 2023 Q#101 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2023"}, {"id": "paper_q102_102", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 102, "subject": "Chemistry", "topic": "aromatic conjugation", "question": "Three alternate single and double bonds in benzene are called?", "options": ["Conjugate bonds", "Coordinate covalent bonds", "Fixed bonds", "Ionic bonds"], "correctIndex": 0, "explanation": "Benzene's alternating single and double bonds form a conjugated system; these are described as conjugate bonds. The other options are not appropriate descriptions for benzene's bonding.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 102, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "UHS 2023 Q#102 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2023"}, {"id": "paper_q103_103", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 103, "subject": "Chemistry", "topic": "acidity of hydrocarbons", "question": "Which of the following compound is more acidic?", "options": ["Alkane", "Alkene", "Alkyne", "Cycloalkane"], "correctIndex": 2, "explanation": "Terminal alkynes have an sp-hybridized carbon bearing the acidic hydrogen; sp-hybridized carbons hold electron density closer to nucleus making the proton more acidic than in alkenes or alkanes. Thus alkynes are the most acidic of the listed choices.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 103, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "UHS 2023 Q#103 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2023"}, {"id": "paper_q104_104", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 104, "subject": "Chemistry", "topic": "free radical mechanism", "question": "Consider the chlorination of methane, the attack of chlorine free radical on methane form methyl free radical occurs in ?", "options": ["Initiation step", "Propagation step", "Termination step", "Last step"], "correctIndex": 1, "explanation": "Hydrogen abstraction by a chlorine radical from methane, producing a methyl radical and HCl, is a propagation step: it consumes and regenerates radicals, allowing the chain reaction to continue.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 104, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2023 Q#104 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q105_105", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 105, "subject": "Chemistry", "topic": "electron counting in aromatics", "question": "The ratio of sigma to pi electrons in benzene is?", "options": ["1:3", "3:1", "4:1", "1:4"], "correctIndex": 2, "explanation": "Benzene has 6 C–H sigma bonds (12 electrons) and 6 C–C sigma bonds (12 electrons) giving 24 sigma electrons total, and 6 π electrons; the sigma:pi electron ratio is 24:6 = 4:1.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 105, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "UHS 2023 Q#105 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2023"}, {"id": "paper_q106_106", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 106, "subject": "Chemistry", "topic": "carbocation stability", "question": "When halogen is removed from an alkyl halide a carbocation is formed, identify the most reactive carbocation", "options": ["Primary carbocation", "Secondary carbocation", "Tertiary carbocation", "Methyl carbocation"], "correctIndex": 2, "explanation": "Tertiary carbocations are the most stabilized by electron-donating alkyl groups via hyperconjugation and inductive effects, so they are the most stable and thus the most reactive in reactions that proceed via carbocation intermediates (e.g., SN1).", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 106, "syllabusUnit": "Unit 10: Alkyl Halides, Alcohols & Phenols", "pmdcTopic": "Nucleophilic Substitution, Elimination Reactions & Phenol Acidity", "textbookCitation": "PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19", "citationString": "UHS 2023 Q#106 | Unit 10: Alkyl Halides, Alcohols & Phenols | PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19"}, "year": "2023"}, {"id": "paper_q107_107", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 107, "subject": "Chemistry", "topic": "freon uses", "question": "Freon is commonly known as ?", "options": ["Refrigerant", "A solvent", "Insecticides", "A fire extinguisher"], "correctIndex": 0, "explanation": "Freon is a trade name for a class of chlorofluorocarbon refrigerants commonly used in refrigeration and air-conditioning systems.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 107, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2023 Q#107 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q108_108", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 108, "subject": "Chemistry", "topic": "classification of alkyl halides", "question": "Neopentylchloride belongs to which class of alkyl halides?", "options": ["Primary alkyl halides", "Secondary alkyl halides", "Tertiary alkyl halides", "Quaternary alkyl halides"], "correctIndex": 0, "explanation": "Neopentyl chloride has the halogen on a primary carbon (–CH2– group) even though it is sterically hindered; therefore it is classified as a primary alkyl halide.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 108, "syllabusUnit": "Unit 10: Alkyl Halides, Alcohols & Phenols", "pmdcTopic": "Nucleophilic Substitution, Elimination Reactions & Phenol Acidity", "textbookCitation": "PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19", "citationString": "UHS 2023 Q#108 | Unit 10: Alkyl Halides, Alcohols & Phenols | PTB Chemistry XII Ch 10 & 11; Federal Chemistry XII Ch 19"}, "year": "2023"}, {"id": "paper_q109_109", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 109, "subject": "Chemistry", "topic": "common names", "question": "What is the common name of 1,2,3-propanetriol?", "options": ["Butyl alcohol", "Glycol", "Glycerol", "Propyl alcohol"], "correctIndex": 2, "explanation": "1,2,3-Propanetriol is commonly known as glycerol (glycerin). 'Glycol' usually refers to diols such as ethylene glycol.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 109, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2023 Q#109 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q110_110", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 110, "subject": "Chemistry", "topic": "phenol formaldehyde reaction", "question": "When Phenol reacts with formaldehyde, which of the following product is produced?", "options": ["Adduct", "Hydronium ion", "Oxonium ion", "Phenoxide ion"], "correctIndex": 0, "explanation": "Phenol reacts with formaldehyde to form electrophilic addition products (phenol–formaldehyde adducts), which can polymerize to form phenolic resins. It is typically described as formation of an adduct.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 110, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "UHS 2023 Q#110 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2023"}, {"id": "paper_q111_111", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 111, "subject": "Chemistry", "topic": "naming functional groups", "question": "Which of the following is the correct name of CH3CH2CH2COCH2CHO?", "options": ["3-oxo hexanal", "3-one hexanal", "3-oxo hexanol", "3- keto hexanol"], "correctIndex": 0, "explanation": "Numbering from the aldehyde carbon, the ketone group is at C‑3, so the correct locant/prefix for a ketone alongside an aldehyde is '3-oxo' giving '3-oxohexanal'. The options referring to 'hexanol' would imply an alcohol, which is incorrect.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 111, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2023 Q#111 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q112_112", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 112, "subject": "Chemistry", "topic": "organic identification tests", "question": "Which of the following is also called silver mirror test?", "options": ["Benedict's solution test", "Fehling's solution test", "Iodoform test", "Tollen's reagent test"], "correctIndex": 3, "explanation": "The silver mirror test refers to Tollen's reagent, which oxidizes aldehydes to carboxylates and produces a silver mirror on the reaction vessel; the other tests are different qualitative tests.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 112, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "UHS 2023 Q#112 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2023"}, {"id": "paper_q113_113", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 113, "subject": "Chemistry", "topic": "effect of substituents on acidity", "question": "Which among the following have least pH?", "options": ["CH3CH2COOH", "CH2ClCH2COOH", "CH3CHCl2 COOH", "CH3CH2CH2COOH"], "correctIndex": 2, "explanation": "Electron-withdrawing halogen substituents increase the acidity of carboxylic acids. A dichloro-substituted acid (CH3CHCl2COOH) is the most strongly electron-withdrawing among the choices, so it will have the lowest pH (most acidic).", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 113, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "UHS 2023 Q#113 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2023"}, {"id": "paper_q114_114", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 114, "subject": "Chemistry", "topic": "naming with multiple functional groups", "question": "If carboxylic acid and ketone groups C=O are present in a chain then final name will be given as", "options": ["oxo, oic acid", "one, oic acid", "Both 1 and 2", "None of these"], "correctIndex": 0, "explanation": "When both a carboxylic acid and a ketone are present, the carboxyl has priority and the ketone is indicated by the prefix 'oxo-' rather than the suffix '-one'; hence 'oxo, oic acid' is the correct convention.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 114, "syllabusUnit": "Unit 11: Carbonyl Compounds (Aldehydes & Ketones)", "pmdcTopic": "Carbonyl Chemistry, Addition Reactions & Tests for Carbonyls", "textbookCitation": "PTB Chemistry XII Ch 12 (Aldehydes and Ketones); Federal Chemistry XII Ch 20", "citationString": "UHS 2023 Q#114 | Unit 11: Carbonyl Compounds (Aldehydes & Ketones) | PTB Chemistry XII Ch 12 (Aldehydes and Ketones); Federal Chemistry XII Ch 20"}, "year": "2023"}, {"id": "paper_q115_115", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 115, "subject": "Chemistry", "topic": "melting points and hydrogen bonding", "question": "When carboxylic acids and dicarboxylic acids have similar molecular weights, how do their melting points compare?", "options": ["Carboxylic acids have greater melting points", "Dicarboxylic acids have greater melting points", "Both acids have similar melting points", "No any consistent trends exits"], "correctIndex": 1, "explanation": "Dicarboxylic acids can form more extensive intermolecular hydrogen bonding networks than monocarboxylic acids of similar weight, so they generally show higher melting points.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 115, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "UHS 2023 Q#115 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2023"}, {"id": "paper_q116_116", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 116, "subject": "Biology", "topic": "enzyme activity in digestive tract", "question": "When food reaches stomach, the action of which of the following come to an end due to acidic PH?", "options": ["Lipases", "Amylase", "Maltase", "Hydrolases"], "correctIndex": 1, "explanation": "Salivary amylase (a carbohydrate-digesting enzyme) is inactivated by the acidic pH of the stomach, so starch digestion by amylase effectively stops once food reaches the stomach.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 116, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2023 Q#116 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q117_117", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 117, "subject": "Biology", "topic": "plasma proteins", "question": "Which of the following proteins acts as carrier of copper in blood plasma?", "options": ["Hemoglobin", "Glycoprotein", "Ceruloplasmin", "Histone"], "correctIndex": 2, "explanation": "Ceruloplasmin is the major copper-carrying protein in blood plasma. Hemoglobin carries oxygen, histones are nuclear proteins, and 'glycoprotein' is a general class rather than the specific copper carrier.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 117, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "UHS 2023 Q#117 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2023"}, {"id": "paper_q118_118", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 118, "subject": "Physics", "topic": "velocity time graph", "question": "What is the shape of velocity-time graph for constant acceleration?", "options": ["Parabola line", "Straight line", "Incline curve", "Decline curve"], "correctIndex": 1, "explanation": "With constant acceleration, velocity changes linearly with time, so the velocity–time graph is a straight line whose slope equals the acceleration.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 118, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2023 Q#118 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q119_119", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 119, "subject": "Physics", "topic": "definition of variable velocity", "question": "Which of the following is the correct definition of variable velocity?", "options": ["Unequal distances are covered in equal intervals of time", "Equal displacements are made in unequal intervals of time", "Unequal displacements are made in equal intervals of time", "Equal displacements are made in equal intervals of time"], "correctIndex": 2, "explanation": "Variable velocity means the displacement per equal time interval is not constant; thus unequal displacements occur in equal intervals of time. The wording using 'displacements' (vector quantity) is the correct expression.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 119, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2023 Q#119 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q120_120", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 120, "subject": "Physics", "topic": "projectile motion", "question": "A stone thrown horizontally from the top of a tall building follows a path that is:", "options": ["Circular", "Made of two straight line segments", "Hyperbolic", "Parabolic"], "correctIndex": 3, "explanation": "A projectile launched horizontally moves under constant horizontal velocity and constant vertical acceleration due to gravity, producing a parabolic trajectory.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 120, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2023 Q#120 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q121_121", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 121, "subject": "Physics", "topic": "newtons third law", "question": "Which of the following is incorrect?", "options": ["Reaction force on a body is always balanced by the action force", "Reaction and action forces are always equal", "Action and reaction forces never act on the same body", "Newton's Third Law is always valid in all situations"], "correctIndex": 0, "explanation": "The statement in option (a) is incorrect because action and reaction forces act on different bodies and therefore do not form a balancing pair on the same body. The other statements correctly describe Newton's third law principles.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 121, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2023 Q#121 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q122_122", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 122, "subject": "Physics", "topic": "dynamics and tension", "question": "A fireman wants to slide down a rope. The breaking load of the rope is 3/4 th of the weight of the man. With what acceleration should the fire man slide down? ( Acceleration due to gravity is 'g')", "options": ["g", "g/4", "3g/4", "0"], "correctIndex": 1, "explanation": "Let T be the rope tension; breaking load T_break = (3/4)mg. For downward acceleration a, T = m(g - a). Setting T = (3/4)mg gives g - a = 3/4 g, so a = g/4.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 122, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2023 Q#122 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q123_123", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 123, "subject": "Physics", "topic": "terminal velocity", "question": "When a heavy coin falls a short distance towards the ground it does not reach terminal velocity. Why is this so?", "options": ["The coin has not hit the ground", "The weight of coin is equal to air resistance", "The weight of coin increases as air resistance increases", "The weight of coin is more than air resistance"], "correctIndex": 0, "explanation": "Terminal velocity is reached only after the object has fallen long enough for air resistance to grow and balance weight. If the coin falls only a short distance, it has not had time to reach that steady terminal speed.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 123, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2023 Q#123 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q124_124", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 124, "subject": "Physics", "topic": "energy consumption", "question": "The consumption of energy by a 60 W bulb in 2 s is:", "options": ["120 J", "60 J", "30 J", "0.02 J"], "correctIndex": 0, "explanation": "Energy consumed = power × time = 60 W × 2 s = 120 joules.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 124, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2023 Q#124 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q125_125", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 125, "subject": "Physics", "topic": "spring potential energy", "question": "A long spring, when stretched by a distance x, has potential energy V. On increasing the stretching to nx, the potential energy of the spring will be:", "options": ["nV", "V/n", "n^2 V", "V/n^2"], "correctIndex": 2, "explanation": "Spring potential energy is (1/2)kx^2. If extension is multiplied by n, energy scales as x^2, so the new energy is n^2 times the original: n^2 V.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 125, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2023 Q#125 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q126_126", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 126, "subject": "Physics", "topic": "pole vault energy", "question": "Ignoring details associated with friction, extra forces exerted by arm and leg muscles, and other factors, we can consider a pole vault as the conversion of an athlete's running kinetic energy to gravitational potential energy. If an athlete is to lift his body 5 m during a vault, what speed must he have when he plants his pole?", "options": ["5 m/s", "10 m/s", "15 m/s", "20 m/s"], "correctIndex": 1, "explanation": "Using 1/2 mv^2 = mgh, v = sqrt(2gh). With g ≈ 10 m/s^2 and h = 5 m, v ≈ sqrt(100) ≈ 10 m/s, so about 10 m/s is required.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 126, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2023 Q#126 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q127_127", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 127, "subject": "Physics", "topic": "force impulse kinetic energy", "question": "A particle of mass m at rest is acted upon by a force P for time t. Its kinetic energy after time t is:", "options": ["(P^2 t^2)/m", "(P^2 t^2)/2m", "(P^2 t^2)/3m", "(P^2 t^2)/4m"], "correctIndex": 1, "explanation": "Acceleration a = P/m, final velocity v = a t = (P t)/m, so KE = 1/2 m v^2 = 1/2 m (P^2 t^2/m^2) = (P^2 t^2)/(2m).", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 127, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2023 Q#127 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q128_128", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 128, "subject": "Physics", "topic": "radians to revolutions", "question": "The number of revolutions in 3π radians is:", "options": ["1/60", "3/2", "2", "6"], "correctIndex": 1, "explanation": "One revolution = 2π radians, so 3π radians equals 3π / (2π) = 3/2 revolutions.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 128, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2023 Q#128 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "paper_q129_129", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 129, "subject": "Physics", "topic": "angular speed period", "question": "If a flywheel is rotating at 3.0 rad/s, the time it takes to complete one revolution is about", "options": ["0.67 s", "1.0 s", "1.3 s", "2.1 s"], "correctIndex": 3, "explanation": "Period T = 2π/ω = 2π/3.0 ≈ 2.094 s, which rounds to about 2.1 s.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 129, "syllabusUnit": "Unit 3: Circular and Rotational Motion", "pmdcTopic": "Centripetal Acceleration, Angular Velocity & Rotational Dynamics", "textbookCitation": "PTB Physics XI Ch 5 (Circular Motion); Federal Physics XI Ch 5", "citationString": "UHS 2023 Q#129 | Unit 3: Circular and Rotational Motion | PTB Physics XI Ch 5 (Circular Motion); Federal Physics XI Ch 5"}, "year": "2023"}, {"id": "paper_q130_130", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 130, "subject": "Physics", "topic": "minimum speed top of circle", "question": "A fighter plane is moving in a vertical circle of radius r. Its minimum velocity at the highest point of the circle will be ?", "options": ["√3gr", "√2gr", "√gr", "√(gr/2)"], "correctIndex": 2, "explanation": "At the top, the minimum speed occurs when the normal force is zero, so centripetal requirement v^2/r = g, hence v = √(g r).", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 130, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2023 Q#130 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q131_131", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 131, "subject": "Physics", "topic": "amplitude effects", "question": "Which of the following increase by increasing amplitude?", "options": ["Wavelength", "Frequently", "Zero", "Loudness"], "correctIndex": 3, "explanation": "Amplitude of a sound wave is related to its loudness (intensity ∝ amplitude^2). Frequency and wavelength are independent of amplitude.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 131, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2023 Q#131 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "paper_q132_132", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 132, "subject": "Physics", "topic": "doppler moving source", "question": "An airplane travels at a speed of 0.5v where v is the speed of sound. The airplane approaches a stationary observer. The frequency of sound emitted by the aircraft is 200 Hz. Which frequency does the observer hear?", "options": ["400 HZ", "100 HZ", "120 Hz", "180 Hz"], "correctIndex": 0, "explanation": "For a source approaching at vs = 0.5v, Doppler shift gives f' = f * v/(v - vs) = 200 * v/(v - 0.5v) = 200 * (1/0.5) = 400 Hz.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 132, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "UHS 2023 Q#132 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2023"}, {"id": "paper_q133_133", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 133, "subject": "Physics", "topic": "redshift galaxy motion", "question": "If the wavelength of light coming from a galaxy shifts towards the red end of spectrum, then galaxy is:", "options": ["Approaching Earth", "Receding the Earth", "Stationary", "Approaching Earth or is stationary"], "correctIndex": 1, "explanation": "A redshift means wavelengths are stretched, which indicates the source is moving away from the observer (receding), by the Doppler effect for light.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 133, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "UHS 2023 Q#133 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2023"}, {"id": "paper_q134_134", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 134, "subject": "Physics", "topic": "definition wavelength", "question": "The shortest distance between any two points in phase on a wave is called:", "options": ["Displacement", "Amplitude", "Wavelength", "Frequency"], "correctIndex": 2, "explanation": "Two points in phase are separated by an integer multiple of the wavelength; the smallest non-zero separation is one wavelength.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 134, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "UHS 2023 Q#134 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2023"}, {"id": "paper_q135_135", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 135, "subject": "Physics", "topic": "oscillations without resistance", "question": "When will the oscillations stop in the absence of resistive forces?", "options": ["Never", "After 10 minutes", "In 10 minutes", "Immediately"], "correctIndex": 0, "explanation": "Without resistive (damping) forces, an ideal oscillator perpetually exchanges energy between kinetic and potential forms and does not lose energy, so oscillations continue indefinitely.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 135, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2023 Q#135 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q136_136", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 136, "subject": "Physics", "topic": "mechanical wave generation", "question": "The mechanical waves are not generated by:", "options": ["Electric and magnetic fields", "Coil of springs", "Ropes", "Water"], "correctIndex": 0, "explanation": "Mechanical waves require a material medium; electric and magnetic fields produce electromagnetic waves, not mechanical waves in a medium.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 136, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "UHS 2023 Q#136 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2023"}, {"id": "paper_q137_137", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 137, "subject": "Physics", "topic": "mass effect on frequency", "question": "Reducing mass M of a suspending body to one fourth will change the frequency of oscillation to", "options": ["One fourth", "Double", "Quadrupule", "Half"], "correctIndex": 1, "explanation": "For a mass–spring oscillator frequency f ∝ 1/√m. If m → m/4 then f → f × √(4) = 2f, i.e., the frequency doubles.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 137, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "UHS 2023 Q#137 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2023"}, {"id": "paper_q138_138", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 138, "subject": "Physics", "topic": "nonrelativistic doppler light", "question": "A distant star is receding from the Earth with a speed of 1.40 x 10^7 m/s. It emits light of frequency 4.57 x 10^14 Hz. The speed of light is 3.0 x 10^8 m/s. The Doppler effect formula can be used with light waves. What will be the frequency of this light when detected on Earth?", "options": ["2.04 x 10^13 Hz", "4.37 x 10^14 Hz", "4.57 x 10^14 Hz", "4.79 x 10^14 Hz"], "correctIndex": 1, "explanation": "For v ≪ c and receding source, f' ≈ f(1 - v/c). Here v/c ≈ 0.0467, so f' ≈ 4.57×10^14 × 0.9533 ≈ 4.37×10^14 Hz (a small redshift).", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 138, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "UHS 2023 Q#138 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2023"}, {"id": "paper_q139_139", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 139, "subject": "Physics", "topic": "definition thermodynamics", "question": "Thermodynamics is that branch of Physics in which we study", "options": ["relations between heat and mechanical energies", "relations between heat and ionization energies", "relations between chemical and mechanical energies", "relations between kinetic and potential energies"], "correctIndex": 0, "explanation": "Thermodynamics deals with heat, work, and the relation between thermal and mechanical forms of energy, including laws governing energy transfer and conversion.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 139, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "UHS 2023 Q#139 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2023"}, {"id": "paper_q140_140", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 140, "subject": "Physics", "topic": "isothermal process pv", "question": "When a gas is compressed isothermally, the product of its pressure and volume during the process is:", "options": ["not constant", "constant", "zero", "proportional to entropy"], "correctIndex": 1, "explanation": "For an ideal gas at constant temperature (isothermal), PV = constant (Boyle's law).", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 140, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "UHS 2023 Q#140 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2023"}, {"id": "paper_q141_141", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 141, "subject": "Physics", "topic": "isobaric temperature volume", "question": "Temperature of given mass of a gas is changed from 150°C to 300°C during an isobaric process, volume of the gas will become:", "options": ["Half", "Double", "Remain same", "Less than double"], "correctIndex": 3, "explanation": "Under isobaric conditions V ∝ T (absolute). Converting to kelvin: T1 = 423 K, T2 = 573 K, so V increases by 573/423 ≈ 1.35, which is less than double.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 141, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "UHS 2023 Q#141 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2023"}, {"id": "paper_q142_142", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 142, "subject": "Physics", "topic": "capacitor energy redistribution", "question": "A capacitor is charged with a battery and energy stored is U. After disconnecting battery another capacitor of same capacity is connected in parallel to the first capacitor. Then energy stored in each capacitor is", "options": ["U/2", "U/4", "4U", "2U"], "correctIndex": 0, "explanation": "Connecting an identical uncharged capacitor in parallel halves the voltage across each (V→V/2), so total energy halves and is equally shared; energy on each becomes U/2.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 142, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2023 Q#142 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q143_143", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 143, "subject": "Physics", "topic": "potential difference work charge", "question": "What is the potential difference between two points in an electric field if it takes 600 J of energy to move a charge of 2 C between these two points?", "options": ["1200 J", "800 J", "300 J", "0 J"], "correctIndex": 2, "explanation": "Potential difference V = work/charge = 600 J / 2 C = 300 V. The unit is volts (J/C).", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 143, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2023 Q#143 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q144_144", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 144, "subject": "Physics", "topic": "limitations of gauss law", "question": "Gauss law cannot be used to find which of the following quantity?", "options": ["Electric field intensity", "Electric flux density", "Charge", "Permittivity"], "correctIndex": 3, "explanation": "Gauss's law relates electric flux to enclosed charge and can determine field or flux in symmetric situations; permittivity is a material property and is not obtained from Gauss's law itself.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 144, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "UHS 2023 Q#144 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2023"}, {"id": "paper_q145_145", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 145, "subject": "Physics", "topic": "comparison gravitational electrostatic", "question": "Which one of the following statements is true?", "options": ["electrostatic force obeys inverse square law while gravitational force does not", "both gravitational force and electrostatic force are repulsive in nature", "gravitational force is much weaker than electrostatic force", "Both electrostatic force and gravitational force don't obey inverse square law"], "correctIndex": 2, "explanation": "Both forces obey inverse-square laws, but the gravitational force is enormously weaker than electrostatic force between elementary charges; gravitational is always attractive while electrostatic can be repulsive or attractive.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 145, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2023 Q#145 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "paper_q146_146", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 146, "subject": "Physics", "topic": "coulomb constant dependence", "question": "The Coulomb's constant k depends upon:", "options": ["nature of medium", "system of units", "types of charge", "nature of medium and system of units"], "correctIndex": 3, "explanation": "k = 1/(4πϵ) depends on the medium's permittivity (nature of medium) and its numerical value also depends on the chosen system of units.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 146, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "UHS 2023 Q#146 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2023"}, {"id": "paper_q147_147", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 147, "subject": "Physics", "topic": "motion in uniform electric field", "question": "A charged particle is moving in a uniform electric field. For the motion of the particle due to the field, which quantity has a constant non-zero value?", "options": ["acceleration", "displacement", "rate of change of acceleration", "velocity"], "correctIndex": 0, "explanation": "A uniform electric field exerts a constant force on a charged particle, producing a constant acceleration (F = qE ⇒ a = qE/m). Velocity changes linearly but is not constant.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 147, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "UHS 2023 Q#147 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2023"}, {"id": "paper_q148_148", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 148, "subject": "Physics", "topic": "capacitor energy scaling with charge", "question": "A capacitor of capacitance 'C' has a charge 'Q' and stored energy is 'w'. If the charge is increases to '2Q'. The stored energy will be:", "options": ["2W", "4W", "W/4", "W/2"], "correctIndex": 1, "explanation": "Energy stored in a capacitor is (1/2)Q^2/C, so doubling Q increases energy by factor four: W' = 4W.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 148, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2023 Q#148 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q149_149", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 149, "subject": "Physics", "topic": "closed switch potential drop", "question": "How much potential drop exist across closed switch?", "options": ["0 V", "1V", "2V", "3V"], "correctIndex": 0, "explanation": "An ideal closed (shorted) switch has negligible resistance, so the potential difference across it is effectively 0 V.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 149, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2023 Q#149 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q150_150", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 150, "subject": "Physics", "topic": "simple circuit current", "question": "A 3 V battery is connected in series with ammeter and 2 ohm resistance after short circuiting circuiting. What will be the reading of ammeter?", "options": ["1 A", "1.5 A", "5 A", "6 A"], "correctIndex": 1, "explanation": "Assuming the only effective resistance is 2 Ω, current = V/R = 3 V / 2 Ω = 1.5 A, so the ammeter reads 1.5 A.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 150, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "UHS 2023 Q#150 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2023"}, {"id": "paper_q151_151", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 151, "subject": "Physics", "topic": "resistance dependence", "question": "The resistance of a conductor does not depend on which of the following?", "options": ["area", "resistivity", "length", "mass"], "correctIndex": 3, "explanation": "Resistance depends on length, cross-sectional area and material resistivity; it is not directly a function of the conductor's mass.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 151, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "UHS 2023 Q#151 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2023"}, {"id": "paper_q152_152", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 152, "subject": "Physics", "topic": "kirchhoff rule correctness", "question": "Which of the following statement is NOT CORRECT about Kirchhoff's rule?", "options": ["Kirchhoff's current rule based upon the law of conservation of charge", "Wheatstone bridge is an application of Kirchhoff's rule", "Kirchhoff's rules are more suitable in AC circuits", "Kirchhoff's voltage rule based upon the law of conservation of energy"], "correctIndex": 2, "explanation": "Kirchhoff's laws apply to both DC and AC circuit analysis (in their appropriate form); the statement that they are more suitable in AC circuits is incorrect.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 152, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "UHS 2023 Q#152 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2023"}, {"id": "paper_q153_153", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 153, "subject": "Physics", "topic": "temperature coefficient", "question": "What do the substances whose resistance decreases with increase in temperature have?", "options": ["high temperature coefficient", "negative temperature coefficient", "positive temperature coefficient", "zero temperature coefficient"], "correctIndex": 1, "explanation": "Materials whose resistance falls as temperature rises have a negative temperature coefficient (NTC), typical of semiconductors or thermistors.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 153, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "UHS 2023 Q#153 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2023"}, {"id": "paper_q154_154", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 154, "subject": "Physics", "topic": "power delivered to load with internal resistance", "question": "A low voltage supply with an e.m.f. of 20 V and an internal resistance of 1.5 ohms is used to supply power to a heater of resistance 6.5 ohms in a fish tank. What is the power supplied to the water in the fish tank?", "options": ["41 W", "50 W", "53 W", "62 W"], "correctIndex": 0, "explanation": "Total series resistance = 6.5 + 1.5 = 8.0 Ω, current I = 20/8 = 2.5 A. Power in heater = I^2 R = (2.5)^2 × 6.5 = 40.625 W ≈ 41 W.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 154, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2023 Q#154 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q155_155", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 155, "subject": "Physics", "topic": "magnetic vs electric force effect on velocity", "question": "Electric forces change the magnitude and direction of velocity while magnetic forces change_____________ of velocity", "options": ["Only Magnitude", "Only direction", "Magnitude and direction", "Neither magnitude nor direction"], "correctIndex": 1, "explanation": "Magnetic forces act perpendicular to velocity and do no work, so they change only the direction of velocity (not its magnitude). Electric forces can change both magnitude and direction.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 155, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2023 Q#155 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q156_156", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 156, "subject": "Physics", "topic": "magnetic flux shape", "question": "Which surface has greater magnetic flux in same magnetic field, each has an area 1 m^2.", "options": ["a. Circular", "b. Rectangular", "c. Square", "d. Flux is independent of shape"], "correctIndex": 3, "explanation": "Magnetic flux through a surface is Φ = B·A·cosθ and depends on the magnetic field and the area (and orientation), not the shape. If all surfaces have the same area and orientation in the same field, the flux is the same, so shape is irrelevant.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 156, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "UHS 2023 Q#156 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2023"}, {"id": "paper_q157_157", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 157, "subject": "Physics", "topic": "source of magnetic field", "question": "The source of magnetic field is:", "options": ["a. An isolated magnetic pole", "b. Static electric charge", "c. Nonmagnetic substance", "d. Current loop"], "correctIndex": 3, "explanation": "Magnetic fields are produced by moving charges or currents; a current loop is a common source. Isolated magnetic monopoles (an isolated magnetic pole) have not been observed, and a static electric charge does not produce a magnetic field.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 157, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "UHS 2023 Q#157 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2023"}, {"id": "paper_q158_158", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 158, "subject": "Physics", "topic": "motional emf", "question": "One meter long copper rod is moving with speed 20 m/sec in the magnetic field of strength 0.6 tesla. What is the value of induced emf ?", "options": ["a. 10 v", "b. 12 v", "c. 14 v", "d. 16 v"], "correctIndex": 1, "explanation": "The motional emf across a rod moving perpendicular to a magnetic field is E = Bℓv. Substituting B=0.6 T, ℓ=1 m, v=20 m/s gives E = 0.6×1×20 = 12 V.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 158, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "UHS 2023 Q#158 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2023"}, {"id": "paper_q159_159", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 159, "subject": "Physics", "topic": "units of delta flux", "question": "The unit of Δφ/Δt can be written as ?", "options": ["a. NmA^-2s^-1", "b. NmAs^-1", "c. NmA^-1s^-1", "d. NmA^-2s1"], "correctIndex": 2, "explanation": "ΔΦ/Δt has units of Weber per second, which equals volt. A volt can be expressed as N·m·A^-1·s^-1, so the option with NmA^-1s^-1 is the correct unit representation.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 159, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2023 Q#159 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "paper_q160_160", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 160, "subject": "Physics", "topic": "levitation principle", "question": "Working principal of magnetic levitation train is according to ?", "options": ["a. Faraday law", "b. Max planks law", "c. Ohm law", "d. Lenz law"], "correctIndex": 3, "explanation": "Magnetic levitation relies on induced currents that produce magnetic forces opposing the change (and supporting the train); this behavior is described by Lenz's law, which gives the direction of induced currents such that they oppose the change causing them.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 160, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2023 Q#160 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q161_161", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 161, "subject": "Physics", "topic": "induced emf hoop", "question": "A copper hoop is held in a vertical east-west plane in a uniform magnetic field whose field lines run along the north-south direction. The largest induced emf is produced when the hoop is ?", "options": ["a. Rotated about a north-south axis", "b. Rotated about an east-west axis", "c. Moved rapidly, without rotation, toward the east", "d. Moved rapidly, without rotation, toward the south"], "correctIndex": 1, "explanation": "With the hoop plane normal initially aligned with the field, rotating about the east-west axis changes the angle between the loop normal and the field and thus changes flux most effectively. Rotation about the north–south axis leaves the angle (and flux) unchanged; simple translation in a uniform field does not change flux.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 161, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "UHS 2023 Q#161 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2023"}, {"id": "paper_q162_162", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 162, "subject": "Physics", "topic": "transformer connections", "question": "In transformer, there is no ______ connection between the two coils but they are ______ linked ?", "options": ["a. Magnetic, electrically", "b. Electrical, magnetically", "c. Magnetic, magnetically", "d. Electrical, optically"], "correctIndex": 1, "explanation": "Transformer primary and secondary coils are not electrically connected (no direct conduction between them) but are magnetically linked through the shared changing magnetic flux in the core. Hence there is no electrical connection but they are magnetically linked.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 162, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "UHS 2023 Q#162 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2023"}, {"id": "paper_q163_163", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 163, "subject": "Physics", "topic": "semiconductor behaviour at 0k", "question": "When the temperature of semiconductor suddenly drops to zero kelvin, then a semiconductor acts as:", "options": ["a. Conductor", "b. Semi-conductor", "c. Super conductor", "d. Insulator"], "correctIndex": 3, "explanation": "At 0 K intrinsic semiconductors have no thermally excited charge carriers, so they cannot conduct and behave like insulators. They are not superconductors, which is a different phenomenon occurring in certain materials at low temperatures.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 163, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "UHS 2023 Q#163 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2023"}, {"id": "paper_q164_164", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 164, "subject": "Physics", "topic": "de broglie wavelength", "question": "If electron, proton, neutron, and alpha particle have same velocity, which of them has the shortest wavelength?", "options": ["a. Electron", "b. Proton", "c. Neutron", "d. Alpha particle"], "correctIndex": 3, "explanation": "De Broglie wavelength λ = h/p = h/(mv). For a given velocity v, the particle with the largest mass m has the largest momentum and thus the shortest wavelength. The alpha particle (~4 times nucleon mass) is heaviest, so it has the shortest wavelength.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 164, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2023 Q#164 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q165_165", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 165, "subject": "Physics", "topic": "photoelectric effect", "question": "The process of ejection of loosely bound electrons from a certain photo sensitive surface by absorption of photon is called:", "options": ["a. Compton effect", "b. Photoelectric effect", "c. Pair production", "d. Black body radiation"], "correctIndex": 1, "explanation": "Ejection of electrons from a material due to absorption of photons is the photoelectric effect. Compton effect involves scattering of photons with wavelength change; pair production creates particle–antiparticle pairs at high photon energies.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 165, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "UHS 2023 Q#165 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2023"}, {"id": "paper_q166_166", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 166, "subject": "Physics", "topic": "stopping potential", "question": "In a photoelectric effect experiment, the stopping potential is:", "options": ["a. The kinetic energy of the most energetic electron ejected", "b. The potential energy of the most energetic electron ejected", "c. The photon energy", "d. The electric potential that causes the electron current to vanish"], "correctIndex": 3, "explanation": "The stopping potential is the (retarding) electric potential required to reduce the photoelectric current to zero; its value is such that eV_stop equals the maximum kinetic energy of the emitted electrons.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 166, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2023 Q#166 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q167_167", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 167, "subject": "Physics", "topic": "hydrogen line series", "question": "The line spectrum of hydrogen atom contains the spectral lines in the region of:", "options": ["a. ultraviolet", "b. infrared", "c. visible", "d. all of these"], "correctIndex": 3, "explanation": "Hydrogen has multiple line series: Lyman (ultraviolet), Balmer (visible), Paschen (infrared), etc. Therefore its spectral lines appear across ultraviolet, visible, and infrared regions.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 167, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2023 Q#167 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "paper_q168_168", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 168, "subject": "Physics", "topic": "bohr orbit velocity", "question": "The speed of electron in the first Bohr orbit is:", "options": ["a. 2.19 x 10^6 ms^-1", "b. 2.19 x 10^-6 ms^-1", "c. 2.19x 10^4 ms^-1", "d. 2.19 x 10^-4 ms^-1"], "correctIndex": 0, "explanation": "In the Bohr model the electron speed in the ground (n=1) orbit of hydrogen is approximately 2.19×10^6 m/s. The other options differ by orders of magnitude and are not the known Bohr speed.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 168, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "UHS 2023 Q#168 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2023"}, {"id": "paper_q169_169", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 169, "subject": "Physics", "topic": "radiation dose energy", "question": "A low energy neutron has RBE factor of 10. How much energy is absorbed by a man of mass 80 Kg if the value of equivalent dose is 400 rem?", "options": ["a. 16 J", "b. 32 J", "c. 48 J", "d. 64 J"], "correctIndex": 1, "explanation": "Equivalent dose (rem) = absorbed dose (rad) × quality factor. Absorbed dose = 400 rem / 10 = 40 rad = 0.4 Gy. 1 Gy = 1 J/kg, so energy absorbed = 0.4 J/kg × 80 kg = 32 J.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 169, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "UHS 2023 Q#169 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2023"}, {"id": "paper_q170_170", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 170, "subject": "Physics", "topic": "beta decay", "question": "It has been observed that Thorium (_90^234)Th is transformed into Protactinium (_91^234)Pa after the emission of ______________ particle:", "options": ["a. Alpha", "b. Beta", "c. Gamma", "d. Alpha, Beta, Gamma"], "correctIndex": 1, "explanation": "The mass number remains 234 while the atomic number increases by one (90→91), which corresponds to beta (β−) decay where a neutron converts to a proton, increasing Z by one without changing A.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 170, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "UHS 2023 Q#170 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2023"}, {"id": "paper_q171_171", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 171, "subject": "Physics", "topic": "decay constant", "question": "The half-life of Strontium (Sr) is 8.70 hours. Its decay constant is:", "options": ["a. 0.000022 s", "b. 45000 /s", "c. 0.000022 / s", "d. 0.000032 / s"], "correctIndex": 2, "explanation": "Decay constant λ = ln2 / t1/2. With t1/2 = 8.70 h = 31320 s, λ ≈ 0.693/31320 ≈ 2.21×10^-5 s^-1 (≈0.000022 s^-1). The option giving 0.000022 / s is the correctly expressed value.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 171, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "UHS 2023 Q#171 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2023"}, {"id": "paper_q172_172", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 172, "subject": "English", "topic": "synonym capricious", "question": "Synonym of the word \"Capricious\" is:", "options": ["a. Fickle", "b. Predictable", "c. Uniform", "d. Invariable"], "correctIndex": 0, "explanation": "Capricious means given to sudden changes of mood or behavior, unpredictable - 'fickle' matches this meaning. The other choices imply steadiness or predictability, which are opposites.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 172, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "UHS 2023 Q#172 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2023"}, {"id": "paper_q173_173", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 173, "subject": "English", "topic": "vocabulary diseases", "question": "Diseases like diabetes are supposed to be taken seriously or they can be ............ Which of the following words will fill in the blank most appropriately?", "options": ["a. Cursing", "b. Healthy", "c. Fatal", "d. Impersonating"], "correctIndex": 2, "explanation": "If diseases are not taken seriously they can lead to severe outcomes; 'fatal' appropriately conveys that they can cause death. The other options are not contextually appropriate.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 173, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "UHS 2023 Q#173 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2023"}, {"id": "paper_q174_174", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 174, "subject": "English", "topic": "antonym abandonment", "question": "Choose the most appropriate antonym for \"abandonment\":", "options": ["a. cessation", "b. stoppage", "c. halt", "d. extension"], "correctIndex": 3, "explanation": "'Abandonment' implies giving up or discontinuing; antonyms should indicate continuation. Of the choices, 'extension' conveys continuation or prolongation, making it the best antonym here; the others mean stopping.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 174, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "UHS 2023 Q#174 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2023"}, {"id": "paper_q175_175", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 175, "subject": "English", "topic": "past perfect passive", "question": "Fill in the blank with the correct word. The shepherd ploughed this mountain with cattle the first time it ....... ever ploughed.", "options": ["a. was", "b. was been", "c. had", "d. had been"], "correctIndex": 3, "explanation": "The correct passive perfect construction is 'had been ploughed' to indicate that prior to the shepherd's action the mountain had never been ploughed. Thus 'had been' fits grammatically and temporally.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 175, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "UHS 2023 Q#175 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2023"}, {"id": "paper_q176_176", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 176, "subject": "English", "topic": "grammar needs only read", "question": "To give one some idea of Rabies' horrors, one ........ only read such descriptions as the following: spasms, restlessness, shudders at the least breath of air, an ardent thirst, convulsive movements, and fits of furious rage.", "options": ["a. needs", "b. need", "c. needed", "d. has needed"], "correctIndex": 0, "explanation": "The impersonal construction 'one needs only read' is idiomatic and grammatically correct in present tense. 'Needs' agrees with the singular indefinite pronoun 'one'.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 176, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "UHS 2023 Q#176 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2023"}, {"id": "paper_q177_177", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 177, "subject": "English", "topic": "future perfect continuous", "question": "By 2030, people .............. been reading the works of Charles Dickens for more than 190 years.", "options": ["a. had", "b. will", "c. have", "d. will have"], "correctIndex": 3, "explanation": "The sentence requires the future perfect construction 'will have been reading' to indicate a period extending up to a future time. The provided blank should be filled by 'will have' to form that tense.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 177, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "UHS 2023 Q#177 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2023"}, {"id": "paper_q178_178", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 178, "subject": "English", "topic": "sentence correction", "question": "Choose the most suitable/appropriate sentence out of the following:", "options": ["a. Penny did not let me to get my book.", "b. Penny was not leaving me to get my book.", "c. Penny did not let me get my book.", "d. Penny had not left me get my book."], "correctIndex": 2, "explanation": "The correct idiomatic construction is 'did not let me get' (no 'to' after 'let'). Option c is grammatically correct; the others contain incorrect infinitive usage or awkward tense.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 178, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "UHS 2023 Q#178 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2023"}, {"id": "paper_q179_179", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 179, "subject": "English", "topic": "comma use in lists", "question": "Which one of the following is correct?", "options": ["a. We visited, Istanbul, Turkey, and Kowloon, Hong Kong last summer.", "b. We visited: Istanbul, Turkey, and Kowloon, Hong Kong last summer.", "c. We visited Istanbul, Turkey, Kowloon, Hong Kong last summer.", "d. We visited Istanbul, Turkey, and Kowloon, Hong Kong last summer."], "correctIndex": 3, "explanation": "Option d correctly lists two places with their localities and uses a comma before the conjunction 'and' in a standard list format. Other options misuse punctuation (unnecessary comma after 'visited' or missing conjunction).", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 179, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "UHS 2023 Q#179 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2023"}, {"id": "paper_q180_180", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 180, "subject": "English", "topic": "spelling persuade", "question": "Which of the following sentences is correct?", "options": ["a. How could Sarah perswad her mum to stay out later?", "b. How could Sarah persuade her mum to stay out later?", "c. How could Sarah persuad her mum to stay out later?", "d. How could Sarah parsuade her mum to stay out later?"], "correctIndex": 1, "explanation": "Option b uses the correct verb 'persuade' and proper grammar. The other choices contain misspellings or incorrect verb forms.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 180, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "UHS 2023 Q#180 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2023"}, {"id": "paper_q181_181", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 181, "subject": "English", "topic": "articles with instruments", "question": "Choose the sentence with the correct use of article.", "options": ["a. Natasha can play a piano and a violin.", "b. Natasha can play the piano and the violin.", "c. Natasha can play the piano and a violin.", "d. Natasha can play piano and violin."], "correctIndex": 1, "explanation": "When referring to musical instruments in a general sense, English convention uses the definite article: 'play the piano.' Option b correctly applies this to both instruments.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 181, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "UHS 2023 Q#181 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2023"}, {"id": "paper_q182_182", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 182, "subject": "English", "topic": "prepositions distribute", "question": "Distribute the handouts ______ the candidates. The correct preposition to be filled in is:", "options": ["a. into", "b. among", "c. in", "d. on"], "correctIndex": 1, "explanation": "'Among' is used when distributing something to members of a group. 'Into' would suggest placing inside something, while 'in' and 'on' are not appropriate for distribution to people.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 182, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "UHS 2023 Q#182 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2023"}, {"id": "paper_q183_183", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 183, "subject": "English", "topic": "sentence correction", "question": "Choose the correct sentence:", "options": ["These scissors are very sharp", "This scissors is very sharp", "This scissor is very sharp", "These scissor are very sharp"], "correctIndex": 0, "explanation": "\"Scissors\" is a plural noun that takes a plural verb (are). Options b–d use incorrect agreement or the nonstandard singular form \"scissor,\" so option a is the grammatically correct sentence.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 183, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "UHS 2023 Q#183 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2023"}, {"id": "paper_q184_184", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 184, "subject": "English", "topic": "sentence correction", "question": "Identify the sentence, out of the following, that is error free:", "options": ["I do not enjoy being laughed at by other people", "I did not enjoy laughing by other people", "I am not enjoying laughing by other people", "I do not enjoying being laughed at by other people"], "correctIndex": 0, "explanation": "Option a correctly uses the verb \"enjoy\" followed by the gerund phrase \"being laughed at by other people.\" The other choices misuse verb forms or the gerund/participle (e.g., \"laughing by other people\" is ungrammatical, and \"do not enjoying\" mixes auxiliary and -ing form incorrectly).", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 184, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "UHS 2023 Q#184 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2023"}, {"id": "paper_q185_185", "paperTitle": "UHS MDCAT 2023 (Paper)", "shortTitle": "UHS 2023", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "questionNumber": 185, "subject": "English", "topic": "adjective participle usage", "question": "Choose the sentence that is grammatically correct.", "options": ["We agreed that the play was rather boring so we felt bored", "We agreed that the play was rather bored so we felt boring", "We agreed that the play was rather bore so we felt bores", "We agreed that the play was rather bores so we felt bored"], "correctIndex": 0, "explanation": "Option a uses \"boring\" (describing the play) and \"bored\" (describing people's feelings) correctly. The other options either swap the participial/adjective forms incorrectly or use nonstandard forms like \"bore\"/\"bores,\" making them ungrammatical.", "reference": {"sourcePaper": "UHS MDCAT 2023 (Paper)", "paperCode": "Paper", "authority": "University of Health Sciences Lahore (Punjab)", "province": "Punjab", "originalQuestionNumber": 185, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "UHS 2023 Q#185 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2023"}, {"id": "official_paper_q1_1", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 1, "subject": "Biology", "topic": "organelle abundance in secretory cells", "question": "Which organelle would be more abundant in the se-cretory cell than the non-secretory cell:", "options": ["Lysosome", "Golgi complex", "Vacuole", "Centrioles"], "correctIndex": 1, "explanation": "Secretory cells produce and package large amounts of materials for export, so the Golgi complex (which modifies, sorts and packages secretory products) is more abundant. Lysosomes, vacuoles and centrioles do not perform the specialized packaging/secretory role of the Golgi.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 1, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2022 Q#1 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2022"}, {"id": "official_paper_q2_2", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 2, "subject": "Biology", "topic": "structure disappearing during cell division", "question": "The structure which disappeared during cell division is:", "options": ["Vacuole", "Lysosome", "Nucleus", "Endoplasmic reticulum"], "correctIndex": 2, "explanation": "During mitosis the nuclear envelope breaks down and the nucleus is not visible as an intact structure, so the nucleus is described as 'disappearing'. Vacuoles, lysosomes and ER remain as cellular components and do not vanish in the same way.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 2, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2022 Q#2 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2022"}, {"id": "official_paper_q3_3", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 3, "subject": "Biology", "topic": "atp synthase location", "question": "The enzyme ATP synthase is located on the mem-brane of the organelle:", "options": ["Nucleus", "Mitochondria", "Lysosome", "Vacuole"], "correctIndex": 1, "explanation": "ATP synthase is located in the inner membrane of mitochondria where it produces ATP during oxidative phosphorylation. It is not a feature of the nuclear membrane, lysosomes or vacuoles.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 3, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2022 Q#3 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2022"}, {"id": "official_paper_q4_4", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 4, "subject": "Biology", "topic": "lysosome structure and function", "question": "------ are spherical sacs surrounded by a single membrane and containing hydrolytic enzymes:", "options": ["Mitochondria", "Golgi bodies", "Lysosome", "Chloroplast"], "correctIndex": 2, "explanation": "Lysosomes are membrane-bound spherical vesicles containing hydrolytic (digestive) enzymes. Mitochondria and chloroplasts have different internal structures and Golgi bodies are flattened sacs involved in processing and packaging, not hydrolytic digestion.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 4, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2022 Q#4 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2022"}, {"id": "official_paper_q5_5", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 5, "subject": "Biology", "topic": "chromosome coiling state", "question": "Except during nuclear division, the nucleus has the chromosome in a loosely coiled state known as:", "options": ["Genes", "Ribosomes", "DNA", "Chromatin"], "correctIndex": 3, "explanation": "Chromosomes exist as loosely coiled chromatin when the cell is not dividing, allowing transcription and replication. 'Genes' and 'DNA' are related terms but the structural state is specifically called chromatin; ribosomes are unrelated organelles.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 5, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2022 Q#5 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2022"}, {"id": "official_paper_q6_6", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 6, "subject": "Biology", "topic": "nucleolus product", "question": "Within the nucleus ------ are made by the nucleolus:", "options": ["Ribosomes", "mRNA", "Protein", "Enzymes"], "correctIndex": 0, "explanation": "The nucleolus is the site of ribosomal RNA synthesis and ribosome assembly, so ribosomes (or rRNA and ribosomal subunits) are produced there. It does not synthesize mRNA, general proteins or enzymes directly.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 6, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2022 Q#6 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2022"}, {"id": "official_paper_q7_7", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 7, "subject": "Biology", "topic": "cell wall permeability", "question": "Which of the following is correct for the cell wall:", "options": ["Semi-permeable", "Differentially permeable", "Permeable", "Not permeable"], "correctIndex": 2, "explanation": "The cell wall (especially plant cell wall) is generally permeable to water and many solutes; it does not act as a selectively permeable membrane like the plasma membrane. 'Permeable' best matches the printed options.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 7, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2022 Q#7 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2022"}, {"id": "official_paper_q8_8", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 8, "subject": "Biology", "topic": "membrane structures for transport", "question": "Cell membrane also contain through which movement of materials take place by active and passive transport:", "options": ["Lipid", "Corner", "Charge pores", "Carbohydrates"], "correctIndex": 2, "explanation": "The cell membrane contains channel/charge pores (channels and carrier proteins) through which substances move by active and passive transport. Lipids and carbohydrates are membrane components but do not themselves form transport pores; 'Corner' appears to be a misprint.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 8, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2022 Q#8 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2022"}, {"id": "official_paper_q9_9", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 9, "subject": "Biology", "topic": "membrane fluidity", "question": "The part of plasma membrane controls the fluidity of the membrane:", "options": ["Glycoprotein", "Carrier protein", "Lipid", "Carbohydrates"], "correctIndex": 2, "explanation": "Lipids, particularly cholesterol and the fatty acid composition of phospholipids, control membrane fluidity. Glycoproteins and carrier proteins have other roles, while carbohydrates are usually surface markers.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 9, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2022 Q#9 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2022"}, {"id": "official_paper_q10_10", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 10, "subject": "Biology", "topic": "polysome attachment control", "question": "A group of ribosomes attached to mRNA is known as a polysome and the attachment is controlled by:", "options": ["Na+ ions", "Mg++ ions", "Ca++ ions", "K+ ions"], "correctIndex": 1, "explanation": "Magnesium ions (Mg2+) are important for ribosome stability and assembly, helping ribosomes attach to mRNA. Sodium, potassium and calcium are important ions but do not specifically control polysome attachment.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 10, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2022 Q#10 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2022"}, {"id": "official_paper_q11_11", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 11, "subject": "Biology", "topic": "reflex definition", "question": "An automatic, involuntary response to any change, external or internal is called:", "options": ["Reflex", "Instinct", "Taxis", "Tropism"], "correctIndex": 0, "explanation": "A reflex is an automatic, involuntary response to a stimulus. Instincts are innate behaviours, taxis is directed movement, and tropism refers to growth responses in plants.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 11, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2022 Q#11 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2022"}, {"id": "official_paper_q12_12", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 12, "subject": "Biology", "topic": "resting membrane potential value", "question": "Resting membrane potential measures:", "options": ["-70 mv", "-70 Volt", "70 mv", "-90 mv"], "correctIndex": 0, "explanation": "Typical neuronal resting membrane potential is about -70 millivolts (mV). The other numeric options are either wrong units or incorrect magnitude.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 12, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2022 Q#12 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2022"}, {"id": "official_paper_q13_13", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 13, "subject": "Biology", "topic": "touch receptors", "question": "Touch receptors are", "options": ["Paccinian's corpuscles", "Olfactory receptors", "Miessner's corpuscles", "Nociceptors"], "correctIndex": 2, "explanation": "Meissner's (Miessner's) corpuscles are tactile receptors responsible for light touch. Pacinian corpuscles detect pressure/vibration, olfactory receptors detect smell, and nociceptors detect pain.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 13, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2022 Q#13 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2022"}, {"id": "official_paper_q14_14", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 14, "subject": "Biology", "topic": "large intestine functions", "question": "Which one is NOT a function of the large intestine:", "options": ["Absorption of electrolytes", "Absorption of water", "Production of vitamins", "Absorption of amino acids"], "correctIndex": 3, "explanation": "The large intestine absorbs water and electrolytes and hosts bacteria that produce certain vitamins; it does not absorb amino acids significantly (protein digestion and amino acid absorption occur mainly in the small intestine).", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 14, "syllabusUnit": "Unit 5: Human Physiology - Digestion & Nutrition", "pmdcTopic": "Human Digestive System & Absorption Mechanisms", "textbookCitation": "PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12", "citationString": "NUMS 2022 Q#14 | Unit 5: Human Physiology - Digestion & Nutrition | PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12"}, "year": "2022"}, {"id": "official_paper_q15_15", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 15, "subject": "Biology", "topic": "shared structures digestive respiratory", "question": "The following part is common in both the digestive system and respiratory systems of human beings", "options": ["Trachea", "Pharynx", "Larynx", "Oesophagus"], "correctIndex": 1, "explanation": "The pharynx is a shared passage for both air (respiratory) and food (digestive) pathways; the trachea and oesophagus are separate tubes for air and food respectively, and the larynx is part of the airway only.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 15, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2022 Q#15 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2022"}, {"id": "official_paper_q16_16", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 16, "subject": "Biology", "topic": "heart rate regulation", "question": "Heartbeat is normally regulated by:", "options": ["Purkinje fibers", "AV bundle", "Sinoatrial node", "Bundle of His"], "correctIndex": 2, "explanation": "The sinoatrial (SA) node is the heart's primary pacemaker that initiates the electrical impulse; Purkinje fibers, AV bundle and Bundle of His conduct impulses but do not normally set the heart rate.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 16, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2022 Q#16 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2022"}, {"id": "official_paper_q17_17", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 17, "subject": "Biology", "topic": "active immunization", "question": "The method which helps in developing immunity against bacteria is:", "options": ["Radiotherapy", "Chemotherapy", "Vaccination", "Antibiotics"], "correctIndex": 2, "explanation": "Vaccination stimulates the immune system to develop protective immunity against specific bacteria; antibiotics treat infections but do not develop long-term immunity, and radiotherapy/chemotherapy are not immunization methods.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 17, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "NUMS 2022 Q#17 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2022"}, {"id": "official_paper_q18_18", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 18, "subject": "Biology", "topic": "menstrual cycle corpus luteum", "question": "During the menstrual cycle, after the female gamete is released from the ovary is ovulation, the remains of the follicle secrets:", "options": ["Progesterone", "FSH", "LH", "Testosterone"], "correctIndex": 0, "explanation": "After ovulation the follicle remnant (the corpus luteum) secretes progesterone to prepare and maintain the uterine lining; FSH and LH are pituitary hormones and testosterone is not secreted by the ovarian follicle.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 18, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "NUMS 2022 Q#18 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2022"}, {"id": "official_paper_q19_19", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 19, "subject": "Biology", "topic": "regulation of spermatogenesis", "question": "In the male reproductive system, the hormone involved in the regulation of the rate of spermatogenesis is called:", "options": ["Luteinizing hormone", "Follicle-stimulating hormone", "Testosterone", "Inhibin"], "correctIndex": 3, "explanation": "Inhibin, produced by Sertoli cells, provides negative feedback on FSH and helps regulate the rate of spermatogenesis; FSH and testosterone stimulate spermatogenesis rather than acting as the primary regulating feedback signal.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 19, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2022 Q#19 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2022"}, {"id": "official_paper_q20_20", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 20, "subject": "Biology", "topic": "female reproductive anatomy", "question": "Cervix is the part of:", "options": ["Vagina", "Oviduct", "Uterus", "Ovary"], "correctIndex": 2, "explanation": "The cervix is the lower, narrow part of the uterus that opens into the vagina; it is not part of the oviduct (fallopian tube) or the ovary.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 20, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2022 Q#20 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2022"}, {"id": "official_paper_q21_21", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 21, "subject": "Biology", "topic": "cartilage types", "question": "Which of the following is most abundant in human body:", "options": ["Fibrous", "Hyaline", "Elastic", "Flexible"], "correctIndex": 1, "explanation": "Hyaline cartilage is the most abundant type of cartilage in the human body (found on articular surfaces, the nose, trachea, and embryonic skeleton); fibrous and elastic cartilage are less widespread.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 21, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "NUMS 2022 Q#21 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2022"}, {"id": "official_paper_q22_22", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 22, "subject": "Biology", "topic": "joints sutures", "question": "Which of the following is an example of a joint called suture:", "options": ["Intervertebral disc", "Skull bone", "Costal cartilage", "Pubic symphysis"], "correctIndex": 1, "explanation": "Sutures are immovable fibrous joints between skull bones, so the skull bone is the correct example; intervertebral discs and pubic symphysis are different joint types and costal cartilage connects ribs to sternum.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 22, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "NUMS 2022 Q#22 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2022"}, {"id": "official_paper_q23_23", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 23, "subject": "Biology", "topic": "muscle contraction", "question": "Which event does not occur during muscle contraction:", "options": ["I-band shorten", "A-band shortens", "H-zone disappear", "Z-lines move closer"], "correctIndex": 1, "explanation": "During sarcomere shortening the I-band and H-zone decrease and Z-lines move closer, but the A-band (the length of the thick filaments) remains essentially constant and does not shorten.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 23, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "NUMS 2022 Q#23 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2022"}, {"id": "official_paper_q24_24", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 24, "subject": "Biology", "topic": "muscle types", "question": "Smooth muscles are long and spindle-shaped with nucleus ---- per cell:", "options": ["One", "Two", "Three", "Many"], "correctIndex": 0, "explanation": "Smooth muscle cells are spindle-shaped and typically contain a single central nucleus per cell, unlike skeletal muscle which is multinucleated.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 24, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2022 Q#24 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2022"}, {"id": "official_paper_q25_25", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 25, "subject": "Biology", "topic": "blood groups", "question": "Blood group which is known as a universal donor is:", "options": ["A+ve", "O+ve", "AB+ve", "O-ve"], "correctIndex": 3, "explanation": "O negative blood lacks A, B and Rh antigens and is therefore considered the universal donor for transfusion into recipients of unknown blood type.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 25, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "NUMS 2022 Q#25 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2022"}, {"id": "official_paper_q26_26", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 26, "subject": "Biology", "topic": "viral characteristics", "question": "Which one can be considered as living characteristic of a virus:", "options": ["Can be crystallized", "No cellular respiration", "Mutate their genetic", "Lack biosynthetic machinery"], "correctIndex": 2, "explanation": "Viruses can evolve and mutate their genetic material, which is a characteristic associated with life; the other options (can be crystallized, lack biosynthetic machinery, no cellular respiration) are features that support their acellular/non-living classification.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 26, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "NUMS 2022 Q#26 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2022"}, {"id": "official_paper_q27_27", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 27, "subject": "Biology", "topic": "species definition", "question": "A group of organisms with similar morphology and physiology, which can breed together to produce fertile offspring is called:", "options": ["Species", "Domain", "Kingdom", "diversity"], "correctIndex": 0, "explanation": "A species is commonly defined as a group of organisms that can interbreed and produce fertile offspring; domain and kingdom are higher taxonomic ranks and 'diversity' is not a taxon.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 27, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2022 Q#27 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2022"}, {"id": "official_paper_q28_28", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 28, "subject": "Biology", "topic": "atp yield prokaryotes", "question": "oxygen is available, the complete breakdown of glucose produces ----- ATP molecules in prokaryotes:", "options": ["20", "36", "38", "40"], "correctIndex": 2, "explanation": "Under classical textbook accounting prokaryotes can generate about 38 ATP per fully oxidized glucose because prokaryotes do not use ATP to transport reducing equivalents into mitochondria (unlike eukaryotes).", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 28, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2022 Q#28 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2022"}, {"id": "official_paper_q29_29", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 29, "subject": "Biology", "topic": "light dependent reactions", "question": "What are the products of light dependent reactions of photosynthesis?:", "options": ["ATP, RuBP and reduced NAD", "ATP, oxygen and reduced NADP", "GP, oxygen and reduced NAD", "GP reduced NADP and RuBP"], "correctIndex": 1, "explanation": "Light-dependent reactions produce ATP, molecular oxygen (from water photolysis), and reduce NADP+ to NADPH (reduced NADP), which are then used in the Calvin cycle.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 29, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "NUMS 2022 Q#29 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2022"}, {"id": "official_paper_q30_30", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 30, "subject": "Biology", "topic": "photosynthesis co2 role", "question": "During photosynthesis, CO2 works as:", "options": ["Proton donor", "electron donor", "proton acceptor", "source of O2"], "correctIndex": 2, "explanation": "CO2 is reduced during the light-independent reactions (Calvin cycle) by gain of electrons and protons, so it functions as an acceptor (here listed as proton acceptor). It is not a source of O2 nor an electron/proton donor.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 30, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "NUMS 2022 Q#30 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2022"}, {"id": "official_paper_q31_31", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 31, "subject": "Biology", "topic": "calvin cycle end product", "question": "End product of Calvin cycle is:", "options": ["3-phosphoglycerate", "1,3-biphosphoglycerate", "Glyceraldehyde-3-phosphate", "Glucose"], "correctIndex": 2, "explanation": "The principal stable 3-carbon product of the Calvin cycle is glyceraldehyde-3-phosphate (G3P). While 3-phosphoglycerate and 1,3-bisphosphoglycerate are intermediates, glucose is formed later by condensation of triose phosphates.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 31, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "NUMS 2022 Q#31 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2022"}, {"id": "official_paper_q32_32", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 32, "subject": "Biology", "topic": "protein containing molecules", "question": "Which of the following molecule contains amino acid?:", "options": ["Cellulose", "Collagen", "Sucrose", "Ascorbic acid"], "correctIndex": 1, "explanation": "Collagen is a protein composed of amino acids (not a carbohydrate or vitamin). Cellulose and sucrose are carbohydrates, and ascorbic acid is vitamin C, not built from amino acids.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 32, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2022 Q#32 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2022"}, {"id": "official_paper_q33_33", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 33, "subject": "Biology", "topic": "hydrolysis addition", "question": "Hydrolysis is the breakdown of polymer into its monomers by the addition of:", "options": ["Hydroxyl group", "Hydrogen", "Water", "Nitrogen"], "correctIndex": 2, "explanation": "Hydrolysis reactions cleave bonds by addition of water (H2O). The water molecule provides H and OH to the two fragments; it is not simply addition of hydrogen or nitrogen.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 33, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2022 Q#33 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2022"}, {"id": "official_paper_q34_34", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 34, "subject": "Biology", "topic": "non carbohydrate identification", "question": "Which of the following is not a carbohydrate:", "options": ["Glucose (C6H12O6)", "Sucrose (C12H22O11)", "Rhamnose (C6H12O5)", "Lactic acid (C2H4O2)"], "correctIndex": 3, "explanation": "Lactic acid is an organic acid (a product of anaerobic metabolism), not a carbohydrate. Glucose, sucrose and rhamnose are carbohydrates (monosaccharide/disaccharide structures).", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 34, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2022 Q#34 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2022"}, {"id": "official_paper_q35_35", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 35, "subject": "Biology", "topic": "water high heat vaporization", "question": "Due to its high heat of vaporization water plays important role in living organism as:", "options": ["Being an excellent solvent", "Cooling agent", "Membrane stabilizer", "Thermal shock resistor"], "correctIndex": 1, "explanation": "Because water requires a lot of heat to vaporize, evaporative loss (sweating/transpiration) removes significant heat and acts as an effective cooling mechanism. While water is also a good solvent, the high heat of vaporization specifically explains cooling.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 35, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2022 Q#35 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2022"}, {"id": "official_paper_q36_36", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 36, "subject": "Biology", "topic": "membrane composition", "question": "Which molecules do not contribute to the formation of biological membranes?", "options": ["Glycoproteins", "Lipids", "Phospholipids", "Nucleoproteins"], "correctIndex": 3, "explanation": "Biological membranes are composed mainly of phospholipids, other lipids and membrane proteins (including glycoproteins). Nucleoproteins (protein–nucleic acid complexes) are not membrane components.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 36, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2022 Q#36 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2022"}, {"id": "official_paper_q37_37", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 37, "subject": "Biology", "topic": "disaccharide hydrolysis", "question": "Which of the following molecules would yield glucose and fructose on hydrolysis?", "options": ["Starch", "Maltose", "Sucrose", "Lactose"], "correctIndex": 2, "explanation": "Sucrose hydrolyzes to one glucose and one fructose molecule. Maltose yields two glucose molecules, lactose yields glucose and galactose, and starch yields many glucose units.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 37, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "NUMS 2022 Q#37 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2022"}, {"id": "official_paper_q38_38", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 38, "subject": "Biology", "topic": "chromosome termini", "question": "The terminal ends of the chromosomes are called:", "options": ["Satellite", "Kinetochore", "Nucleolar organizer", "Telomere"], "correctIndex": 3, "explanation": "Telomeres are specialized repetitive DNA sequences at chromosome ends that protect them. Kinetochores are protein structures where spindle fibers attach; satellites and nucleolar organizers are different chromosomal regions.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 38, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "NUMS 2022 Q#38 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2022"}, {"id": "official_paper_q39_39", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 39, "subject": "Biology", "topic": "synapse gap", "question": "The gap between neurons at a synapse is:", "options": ["Synaptic knob", "Synaptic cleft", "Synaptic delay", "Synaptic vesicle"], "correctIndex": 1, "explanation": "The synaptic cleft is the small extracellular space separating the presynaptic and postsynaptic membranes. Synaptic knob and vesicles are presynaptic structures, and synaptic delay refers to transmission time.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 39, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2022 Q#39 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2022"}, {"id": "official_paper_q40_40", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 40, "subject": "Biology", "topic": "thermoregulation hypothalamus", "question": "The part of the brain which controls the body temperature in human beings is called:", "options": ["Thalamus", "Hypothalamus", "Pones", "Cerebellum"], "correctIndex": 1, "explanation": "The hypothalamus contains the body's thermoregulatory center and maintains body temperature. The thalamus and cerebellum have other roles; 'Pones' (pons) is part of the brainstem unrelated to primary temperature control.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 40, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2022 Q#40 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2022"}, {"id": "official_paper_q41_41", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 41, "subject": "Biology", "topic": "neuron structure axon", "question": "A long extension of a nerve cell is called:", "options": ["Axon", "Auxin", "Schwann cell", "Dendrites"], "correctIndex": 0, "explanation": "An axon is the long projection that transmits impulses away from a neuron's cell body. Dendrites are generally shorter and receive signals; Schwann cells are glial cells, and auxin is a plant hormone (included as a distractor).", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 41, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2022 Q#41 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2022"}, {"id": "official_paper_q42_42", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 42, "subject": "Biology", "topic": "steroid hormone", "question": "Which is a steroid hormone?", "options": ["Cortisone", "Adrenaline", "Insulin", "Thyroxin"], "correctIndex": 0, "explanation": "Cortisone is a steroid hormone derived from cholesterol. Adrenaline is an amine (catecholamine), insulin is a peptide hormone, and thyroxin is an iodinated amino-acid derivative.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 42, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2022 Q#42 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2022"}, {"id": "official_paper_q43_43", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 43, "subject": "Biology", "topic": "neurotransmitters", "question": "The molecules responsible for conveying messages from one neuron to the next are called:", "options": ["Hormones", "Activators", "Neurotransmitters", "Enzymes"], "correctIndex": 2, "explanation": "Neurotransmitters are chemical messengers released at synapses to transmit signals to adjacent neurons. Hormones act systemically, activators/enzymes are different functional classes.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 43, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "NUMS 2022 Q#43 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2022"}, {"id": "official_paper_q44_44", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 44, "subject": "Biology", "topic": "enzymes alkaline ph", "question": "Which enzyme works in alkaline pH?", "options": ["Pepsin", "Sucrose", "Enterokinase", "Pancreatic lipase"], "correctIndex": 3, "explanation": "Pancreatic lipase operates in the small intestine where the pH is alkaline. Pepsin functions in the acidic stomach; 'Sucrose' is not an enzyme, and enterokinase (enteropeptidase) also acts in the intestine but the classical alkaline enzyme listed is pancreatic lipase.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 44, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2022 Q#44 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2022"}, {"id": "official_paper_q45_45", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 45, "subject": "Biology", "topic": "enzyme temperature terms", "question": "Considering enzyme action minimum temperature is the term used when:", "options": ["Enzymes start denaturing", "Enzyme becomes hyperactive", "Enzyme work at their best", "Inactive enzyme getting reactivated"], "correctIndex": 3, "explanation": "The minimum temperature for enzyme action is the lowest temperature at which the enzyme becomes active. Below it the enzyme is inactive; as the temperature rises to this point, the previously inactive enzyme is reactivated, which is what the term describes.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 45, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2022 Q#45 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2022"}, {"id": "official_paper_q46_46", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 46, "subject": "Biology", "topic": "non competitive inhibition", "question": "Which option is correct about non-competitive inhibition:", "options": ["Malonate act as inhibitor", "Enzyme shape distorted", "Competition for active site", "Inactive enzyme getting reactivated"], "correctIndex": 1, "explanation": "Non-competitive inhibitors bind at an allosteric site (not the active site) and change the enzyme's conformation, reducing activity - this matches “Enzyme shape distorted.” \"Competition for active site\" describes competitive inhibition, and the other options are not general descriptions of non-competitive inhibition.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 46, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2022 Q#46 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2022"}, {"id": "official_paper_q47_47", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 47, "subject": "Biology", "topic": "gut enzyme after bread", "question": "Which type of enzyme would be most active in your gut after eating the loaf of bread?", "options": ["Amylase", "Erypsin", "Lactase", "Carboxypeptidase"], "correctIndex": 0, "explanation": "Bread is rich in starch, and amylase digests starch into smaller sugars; trypsin (printed as \"Erypsin\") and carboxypeptidase act on proteins, while lactase acts on lactose (milk sugar).", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 47, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "NUMS 2022 Q#47 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2022"}, {"id": "official_paper_q48_48", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 48, "subject": "Biology", "topic": "natural selection", "question": "He presented the theory of \"origin of species by means of natural selection\":", "options": ["Lamark", "Linnaeus", "Hardy- Weinberg", "Darwin"], "correctIndex": 3, "explanation": "Charles Darwin proposed the theory of evolution by natural selection in 'On the Origin of Species.' Lamarck proposed inheritance of acquired characteristics, Linnaeus developed taxonomy, and Hardy-Weinberg describes genetic equilibrium.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 48, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "NUMS 2022 Q#48 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2022"}, {"id": "official_paper_q49_49", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 49, "subject": "Biology", "topic": "antibody modes of action", "question": "Which is not a mode of action of an antibody?", "options": ["Precipitating an antigen", "Neutralizing an antigen", "Secreting cytokines", "Enhancing phagocytosis"], "correctIndex": 2, "explanation": "Antibodies precipitate antigens, neutralize toxins/viruses, and opsonize to enhance phagocytosis. Antibodies themselves do not secrete cytokines; cytokine secretion is a function of immune cells.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 49, "syllabusUnit": "Unit 7: Human Physiology - Immunity", "pmdcTopic": "Innate & Adaptive Immunity, Immunoglobulins and Vaccines", "textbookCitation": "PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14", "citationString": "NUMS 2022 Q#49 | Unit 7: Human Physiology - Immunity | PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14"}, "year": "2022"}, {"id": "official_paper_q50_50", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 50, "subject": "Biology", "topic": "magnesium and chlorophyll", "question": "Magnesium is an important nutrient in plants for the formation of:", "options": ["Proteins", "Lipids", "Chlorophylls", "Enzymes"], "correctIndex": 2, "explanation": "Magnesium is the central atom in the chlorophyll molecule and is essential for chlorophyll biosynthesis; while Mg is a cofactor for some enzymes, its defining role in plants is in chlorophyll.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 50, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "NUMS 2022 Q#50 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2022"}, {"id": "official_paper_q51_51", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 51, "subject": "Biology", "topic": "respiratory cartilage", "question": "Which of the following parts of the respiratory system has no cartilage?", "options": ["Larynx", "Trachea", "Bronchioles", "Bronchi"], "correctIndex": 2, "explanation": "Bronchioles are small airways that lack cartilaginous support and instead rely on smooth muscle; the trachea, larynx, and bronchi contain cartilage.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 51, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "NUMS 2022 Q#51 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2022"}, {"id": "official_paper_q52_52", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 52, "subject": "Biology", "topic": "gastric mucosal cells", "question": "Enzymatic portion of the gastric juices secreted by which mucosal cells?", "options": ["Oxyntic cells", "Chief cells", "Mucus cells", "Endocrine cells"], "correctIndex": 1, "explanation": "Chief cells (also called zymogenic cells) secrete pepsinogen, the enzymatic precursor in gastric juice. Oxyntic (parietal) cells secrete acid, mucus cells secrete mucus, and endocrine cells produce hormones.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 52, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "NUMS 2022 Q#52 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2022"}, {"id": "official_paper_q53_53", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 53, "subject": "Physics", "topic": "wavelength definition", "question": "The horizontal distance travelled by wave during one complete cycle is called", "options": ["Frequency", "Wavelength", "Amplitude", "Time period"], "correctIndex": 1, "explanation": "The spatial length of one complete wave cycle is the wavelength. Frequency and time period are temporal properties, and amplitude is the wave's maximum displacement.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 53, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "NUMS 2022 Q#53 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2022"}, {"id": "official_paper_q54_54", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 54, "subject": "Physics", "topic": "shm period mass", "question": "If the period of oscillation of man (M) suspended from a spring is 1s, then the period of 16M will be:", "options": ["1s", "2s", "3s", "4s"], "correctIndex": 3, "explanation": "For a mass-spring system, period T is proportional to sqrt(m). If mass increases by factor 16, period increases by sqrt(16)=4, so the period becomes 4 s.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 54, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "NUMS 2022 Q#54 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2022"}, {"id": "official_paper_q55_55", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 55, "subject": "Physics", "topic": "loudness intensity", "question": "Loudness of the sound is directly rotated to:", "options": ["Intensity of sound", "Frequency of sound", "Wavelength of sound", "Pitch of sound"], "correctIndex": 0, "explanation": "Loudness (perceived volume) is directly related to sound intensity (energy per unit area). Frequency and pitch relate to tone, and wavelength is inversely related to frequency.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 55, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "NUMS 2022 Q#55 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2022"}, {"id": "official_paper_q56_56", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 56, "subject": "Physics", "topic": "speed of sound temperature coefficient", "question": "The increase in the speed of sound in air for each degree rise above 0°C is:", "options": ["0.40 m/s", "0.51 m/s", "0.81 m/s", "0.61 m/s"], "correctIndex": 3, "explanation": "The speed of sound in air increases by about 0.6 m/s per 1 °C increase in temperature, so 0.61 m/s is the closest listed value.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 56, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "NUMS 2022 Q#56 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2022"}, {"id": "official_paper_q57_57", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 57, "subject": "Physics", "topic": "first law", "question": "First law of thermodynamics is based on:", "options": ["Law of conservation of momentum", "Law of conservation of mass", "Law of conservation of charge", "Law of conservation of energy"], "correctIndex": 3, "explanation": "The first law of thermodynamics is the principle of conservation of energy applied to thermodynamic systems: energy added equals work done plus change in internal energy.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 57, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "NUMS 2022 Q#57 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2022"}, {"id": "official_paper_q58_58", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 58, "subject": "Physics", "topic": "isobaric process", "question": "The thermodynamic process during which the pressure is kept constant is called:", "options": ["Isochoric process", "Adiabatic proms", "Isobaric proem", "Isothermal proem"], "correctIndex": 2, "explanation": "A process at constant pressure is called an isobaric process (option printed as \"Isobaric proem\"). Isochoric is constant volume, adiabatic has no heat transfer, and isothermal is constant temperature.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 58, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2022 Q#58 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2022"}, {"id": "official_paper_q59_59", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 59, "subject": "Physics", "topic": "capacitor energy", "question": "Energy stored in a capacitor is given by:", "options": ["E = ½ cv^2", "E.2 cv^2", "E . cv^2", "E = 2 cv^2"], "correctIndex": 0, "explanation": "The energy stored in a capacitor is (1/2) C V^2. The other forms shown are nonstandard or incorrect algebraic variants.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 59, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2022 Q#59 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2022"}, {"id": "official_paper_q60_60", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 60, "subject": "Physics", "topic": "electric field intensity", "question": "Electric field intensity is:", "options": ["Force per unit mass", "Force per unit tesla", "Force per unit charge", "Force per unit watt"], "correctIndex": 2, "explanation": "Electric field intensity (electric field) is defined as force per unit charge (E = F/q). The other ratios correspond to different physical quantities and are not definitions of electric field.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 60, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "NUMS 2022 Q#60 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2022"}, {"id": "official_paper_q61_61", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 61, "subject": "Physics", "topic": "capacitance", "question": "It stores electrical potential energy:", "options": ["Capacitor", "Conductor", "Inductor", "Generator"], "correctIndex": 0, "explanation": "A capacitor stores electrical potential energy in the electric field between its plates. Conductors, inductors and generators do not primarily store energy as electric potential in the same way a capacitor does.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 61, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2022 Q#61 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2022"}, {"id": "official_paper_q62_62", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 62, "subject": "Physics", "topic": "ohms law", "question": "A magnitude of the current in metals is proportional to the applied voltage as long as temperature of conductor is kept constant. It is statement of:", "options": ["Joule's law", "Gauss's law", "Ohm, law", "Ampere's law"], "correctIndex": 2, "explanation": "Ohm's law states that current through a conductor is proportional to the applied voltage when temperature is constant. Joule's, Gauss's and Ampere's laws describe different electrical phenomena.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 62, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "NUMS 2022 Q#62 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2022"}, {"id": "official_paper_q63_63", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 63, "subject": "Physics", "topic": "resistance temperature", "question": "The resistance of pure metal increases with:", "options": ["Increase in temperature", "Increase in pressure", "Decrease in temperature", "Decrease in pressure"], "correctIndex": 0, "explanation": "In pure metals resistance typically increases with temperature because lattice vibrations scatter conduction electrons more. Changes in pressure are not the primary factor for the usual temperature dependence of metallic resistance.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 63, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "NUMS 2022 Q#63 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2022"}, {"id": "official_paper_q64_64", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 64, "subject": "Physics", "topic": "magnetic field current", "question": "The magnetic field inside the current carrying wire varies", "options": ["inversely with r", "inversely with r^2", "directly with r", "Directly with r^2"], "correctIndex": 0, "explanation": "For a long straight current-carrying wire the magnetic field magnitude outside the conductor varies as 1/r (inversely with distance r). The 1/r^2 dependence or direct proportionality would not match the known Biot–Savart/Ampère result.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 64, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "NUMS 2022 Q#64 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2022"}, {"id": "official_paper_q65_65", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 65, "subject": "Physics", "topic": "magnetic flux", "question": "Magnetic flux is maximum when Angle between magnetic field and vector area is:", "options": ["0°", "90°", "30°", "45°"], "correctIndex": 0, "explanation": "Magnetic flux is Φ = B·A·cosθ, so it is maximal when θ = 0° (field parallel to area vector), giving cosθ = 1. At 90° the flux is zero.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 65, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "NUMS 2022 Q#65 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2022"}, {"id": "official_paper_q66_66", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 66, "subject": "Physics", "topic": "lenzs law", "question": "Lenz's law is based on the law of conservation of:", "options": ["Mass", "Energy", "Charge", "Momentum"], "correctIndex": 1, "explanation": "Lenz's law determines the direction of induced current such that the induced effects oppose the change in magnetic flux, ensuring conservation of energy. It is not directly a law about mass, charge or momentum.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 66, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "NUMS 2022 Q#66 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2022"}, {"id": "official_paper_q67_67", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 67, "subject": "Physics", "topic": "flemings right hand rule", "question": "In Fleming's right hand rule, the thumb indicates", "options": ["Force", "Magnetic field", "Induced current", "Electric field"], "correctIndex": 0, "explanation": "Fleming's right-hand rule (for generators) assigns the thumb to motion/force, the first finger to magnetic field, and the second finger to induced current. The other options correspond to the other fingers or are unrelated.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 67, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2022 Q#67 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2022"}, {"id": "official_paper_q68_68", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 68, "subject": "Physics", "topic": "transformer principle", "question": "Transformer works on the principle of:", "options": ["Half wave rectification", "Self-Induction", "Mutual Induction", "Full wave rectification"], "correctIndex": 2, "explanation": "Transformers transfer energy between coils via mutual induction (a changing current in the primary induces a voltage in the secondary). Rectification terms refer to converting AC to DC and are not relevant to transformer operation.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 68, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2022 Q#68 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2022"}, {"id": "official_paper_q69_69", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 69, "subject": "Physics", "topic": "rectifier device", "question": "A device that converts AC into DC is called:", "options": ["Diode", "Transistor", "Capacitor", "Inductor"], "correctIndex": 0, "explanation": "A diode is the basic semiconductor device used for rectification, allowing current more easily in one direction and thus converting AC to DC. Transistors, capacitors and inductors have different primary functions.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 69, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "NUMS 2022 Q#69 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2022"}, {"id": "official_paper_q70_70", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 70, "subject": "Physics", "topic": "rectification definition", "question": "The conversion of alternating current into direct current is called:", "options": ["Amplification", "Rectification", "Magnification", "Resolution"], "correctIndex": 1, "explanation": "Converting AC to DC is known as rectification. Amplification and magnification refer to increasing signal amplitude, and resolution is unrelated.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 70, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "NUMS 2022 Q#70 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2022"}, {"id": "official_paper_q71_71", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 71, "subject": "Physics", "topic": "radiation dose unit", "question": "1 Gy is equal to:", "options": ["1 Jkg", "1 JKg-1", "1 J-1Kg", "J-1Kg-1"], "correctIndex": 0, "explanation": "The gray (Gy) is defined as 1 joule of absorbed radiation energy per kilogram of matter (1 J/kg). The option as printed that corresponds to this unit is the first one.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 71, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2022 Q#71 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2022"}, {"id": "official_paper_q72_72", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 72, "subject": "Physics", "topic": "half life calculation", "question": "A 32g radioactive element decays and remains 2g after 60 days. What is the half-life of radioactive element?", "options": ["2 days", "6 days", "10 days", "15 days"], "correctIndex": 3, "explanation": "32 g to 2 g is a reduction by a factor of 16, which is 2^4, so four half-lives elapsed in 60 days. Half-life = 60 / 4 = 15 days. The option '15 days' is therefore correct.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 72, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "NUMS 2022 Q#72 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2022"}, {"id": "official_paper_q73_73", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 73, "subject": "Physics", "topic": "elastic collision", "question": "An elastic collision is the one in which:", "options": ["Kinetic energy and momentum is conserved", "Kinetic energy is conserved but total energy is not con-served", "Momentum is conserved but kinetic energy is not con-served", "Both kinetic energy and momentum are not conserved"], "correctIndex": 0, "explanation": "In an elastic collision both kinetic energy and momentum are conserved. The other choices contradict the defining conservation properties of an elastic collision.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 73, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2022 Q#73 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2022"}, {"id": "official_paper_q74_74", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 74, "subject": "Physics", "topic": "acceleration definition", "question": "The time rate of change of velocity is called:", "options": ["Force", "Acceleration", "Power", "Energy"], "correctIndex": 1, "explanation": "Acceleration is defined as the time rate of change of velocity. Force, power and energy have different definitions and are not the rate of change of velocity.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 74, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2022 Q#74 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2022"}, {"id": "official_paper_q75_75", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 75, "subject": "Physics", "topic": "projectile range angle", "question": "In projectile motion, the rage of projectile will be maximum at an angle of:", "options": ["30 degrees", "45 degrees", "60 degrees", "90 degrees"], "correctIndex": 1, "explanation": "For projectile motion on level ground (neglecting air resistance) the maximum range occurs at 45 degrees launch angle. The printed word 'rage' is a typographical error for 'range'.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 75, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2022 Q#75 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2022"}, {"id": "official_paper_q76_76", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 76, "subject": "Physics", "topic": "newtons third law", "question": "Which of the following is NOT TRUE?", "options": ["Action and reaction have same nature", "Action and reaction have same line of action", "Action and reaction never act on same body", "Action and reaction can cancel each other"], "correctIndex": 3, "explanation": "Action-reaction force pairs act on different bodies, so they cannot cancel each other (they might be equal and opposite but act on different objects). Thus the statement that they can cancel is not true; the other statements reflect properties of Newton's third law.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 76, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2022 Q#76 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2022"}, {"id": "official_paper_q77_77", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 77, "subject": "Physics", "topic": "relative velocity", "question": "Two buses moving at 100 km/h and 80 km/h respectively cross each other while moving in opposite direction. Velocity of one bus relative to other bus is:", "options": ["100 km/h", "20 km/h", "80 km/h", "180 km/h"], "correctIndex": 3, "explanation": "When two objects move in opposite directions their relative speed is the sum of their speeds: 100 + 80 = 180 km/h. The other numeric options are either the individual speeds or their difference.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 77, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2022 Q#77 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2022"}, {"id": "official_paper_q78_78", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 78, "subject": "Physics", "topic": "projectile range angles", "question": "Which of the following pair of angles have same rang for a projectile?", "options": ["10° and 20°", "75° and 15°", "45° and 60°", "0° and 30°"], "correctIndex": 1, "explanation": "Projectile ranges are equal for launch angles that add to 90° (complementary angles). 75° + 15° = 90°, so that pair gives the same range; the other pairs do not sum to 90°.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 78, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2022 Q#78 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2022"}, {"id": "official_paper_q79_79", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 79, "subject": "Physics", "topic": "projectile equal height range", "question": "The angle of projection of a projectile for which its maximum height and horizontal range are equal is:", "options": ["45°", "90°", "0°", "70°"], "correctIndex": 3, "explanation": "Equating H = R leads to a value of θ given by tan θ = 4 (θ ≈ 76°). Among the provided choices the closest available angle is 70°, so that is the intended answer in the question's options.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 79, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2022 Q#79 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2022"}, {"id": "official_paper_q80_80", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 80, "subject": "Physics", "topic": "explosion conservation law", "question": "The explosion of explosive material is application of:", "options": ["Law of conservation of energy", "Law of conservation of mass", "Law of conservation of momentum", "Newton's third law of motion"], "correctIndex": 2, "explanation": "In an explosion, internal forces can convert chemical energy to kinetic energy, but the total linear momentum of the isolated system is conserved. Thus conservation of momentum is the applicable law here.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 80, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2022 Q#80 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2022"}, {"id": "official_paper_q81_81", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 81, "subject": "Physics", "topic": "power units", "question": "1hp is equal to:", "options": ["476 watts", "647 watts", "746 watts", "487 watts"], "correctIndex": 2, "explanation": "One mechanical horsepower is defined as 746 watts. The other numeric options are incorrect conversions.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 81, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2022 Q#81 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2022"}, {"id": "official_paper_q82_82", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 82, "subject": "Physics", "topic": "power definition", "question": "The product of force and velocity is equal to:", "options": ["Kinetic energy", "Potential energy", "Power", "Work done"], "correctIndex": 2, "explanation": "Power is the rate of doing work; for a constant force causing motion at velocity v, instantaneous power = F · v. The other choices are different physical quantities.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 82, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2022 Q#82 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2022"}, {"id": "official_paper_q83_83", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 83, "subject": "Physics", "topic": "energy units", "question": "One kilowatt-hour is equal to:", "options": ["36 MJ", "3.6 MJ", "36 KJ", "3.6 KJ"], "correctIndex": 1, "explanation": "1 kWh = 1000 W × 3600 s = 3,600,000 J = 3.6 MJ. The other options are off by factors of 10 or 1000.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 83, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2022 Q#83 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2022"}, {"id": "official_paper_q84_84", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 84, "subject": "Physics", "topic": "gravitational potential work", "question": "The amount of work done in moving a body at certain point in a gravitational field to a position of zero potential such that the body is never accelerated is called:", "options": ["Kinetic energy", "Potential energy", "Gravitational potential energy", "Absolute potential energy"], "correctIndex": 2, "explanation": "Work done to move a mass slowly (without acceleration) in a gravitational field to a chosen zero-potential reference is stored as gravitational potential energy. 'Potential energy' is general; the stem specifies the gravitational case.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 84, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2022 Q#84 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2022"}, {"id": "official_paper_q85_85", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 85, "subject": "Physics", "topic": "kinetic energy scaling", "question": "If the speed of a body is doubled, its kinetic energy becomes:", "options": ["Mv²", "2mv²", "½ mv²", "4mv²"], "correctIndex": 3, "explanation": "Kinetic energy is (1/2)mv², so if v → 2v then KE scales as v² and becomes 4 times the original: option '4mv²' corresponds to that 4× scaling (given the printed option form).", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 85, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2022 Q#85 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2022"}, {"id": "official_paper_q86_86", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 86, "subject": "Physics", "topic": "power conversion", "question": "An electric motor of power 2hp is installed in an industrial unit. Its power is:", "options": ["1500 w", "742 w", "148 w", "1492 w"], "correctIndex": 3, "explanation": "1 hp ≈ 746 W, so 2 hp ≈ 2 × 746 = 1,492 W. The other numerical choices are far from the correct conversion.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 86, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "NUMS 2022 Q#86 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2022"}, {"id": "official_paper_q87_87", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 87, "subject": "Physics", "topic": "radian degree conversion", "question": "radian =", "options": ["5.7°", "73.5°", "57.3°", "37.5°"], "correctIndex": 2, "explanation": "1 radian equals 180/π degrees ≈ 57.2958°, so the closest choice provided is 57.3°.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 87, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "NUMS 2022 Q#87 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2022"}, {"id": "official_paper_q88_88", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 88, "subject": "Physics", "topic": "orbital velocity", "question": "The minimum required velocity to put a satellite into the orbit is called:", "options": ["Terminal velocity", "Escape velocity", "Critical velocity", "Average velocity"], "correctIndex": 1, "explanation": "Among the options given, 'escape velocity' is the term referring to the speed related to overcoming gravitational attraction; although strictly the required speed to place an object in a stable orbit is the orbital (first cosmic) velocity, 'escape velocity' is the closest match among the provided choices.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 88, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2022 Q#88 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2022"}, {"id": "official_paper_q89_89", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 89, "subject": "Physics", "topic": "angular velocity", "question": "A rotating wheel coincides 12 rev in 4s. find the average angular velocity in rad/sec:", "options": ["24.6 rad/s", "16.8 rad/s", "10.4 rad/s", "18.8 rad/s"], "correctIndex": 3, "explanation": "12 revolutions in 4 s = 3 rev/s. Angular speed = 3 × 2π = 6π ≈ 18.85 rad/s, so 18.8 rad/s is the correct choice.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 89, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2022 Q#89 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2022"}, {"id": "official_paper_q90_90", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 90, "subject": "Physics", "topic": "centripetal acceleration", "question": "When an object experience circular motion, the direction of centripetal acceleration is:", "options": ["Towards center", "Along tangent", "Along the direction of motion", "Opposite of the direction of motion"], "correctIndex": 0, "explanation": "Centripetal acceleration always points radially inward toward the centre of the circular path. It is not tangential or along the direction of instantaneous motion (which is tangent).", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 90, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "NUMS 2022 Q#90 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2022"}, {"id": "official_paper_q91_91", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 91, "subject": "Physics", "topic": "crest wave optics", "question": "Crest of a wave acts as:", "options": ["Concave lens", "Convex lens", "Convex mirror", "Plane mirror"], "correctIndex": 2, "explanation": "A crest is a convex-shaped surface that tends to diverge wavelets produced there, analogous to the behaviour of a convex mirror (which causes divergence). Concave/plane optical elements behave differently.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 91, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "NUMS 2022 Q#91 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2022"}, {"id": "official_paper_q92_92", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 92, "subject": "Physics", "topic": "speed of sound dependence", "question": "The speed of sound in air does not depend on:", "options": ["Density of medium", "Pressure", "Temperature", "Moisture"], "correctIndex": 1, "explanation": "For an ideal gas the speed of sound at a given temperature depends mainly on temperature (and gas composition/humidity) and is effectively independent of pressure when temperature is held fixed. Therefore 'Pressure' is the best choice among the options.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 92, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "NUMS 2022 Q#92 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2022"}, {"id": "official_paper_q93_93", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 93, "subject": "English", "topic": "punctuation and clauses", "question": "Choose the correct option: He had no worries his pension was adequate and there was a little money saved up besides.", "options": ["He had no worries his pension was adequate and there was a little money saved up besides.", "He had no worries, his pension was adequate and there was a little money saved up besides.", "He had no worries; his pension was adequate, and there was a little money saved up besides.", "He had no worries; his pension was adequate and there was a little money saved up besides."], "correctIndex": 3, "explanation": "The two parts — 'He had no worries' and 'his pension was adequate and there was a little money saved up besides' — are both independent clauses, so joining them with only a comma (option b) is a comma splice. A semicolon correctly links them, making option D the grammatically correct version.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 93, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "NUMS 2022 Q#93 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2022"}, {"id": "official_paper_q94_94", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 94, "subject": "English", "topic": "error identification pronouns and relative clauses", "question": "Identify the errors and choose the correct option: There's mr. Hashim whom they say is the best portrait painter in the town", "options": ["There's mr. Hashim whom they say is the best portrait painter in the town.", "There's Mr. Hashim who they say is the best portrait painter in the town.", "Theres' Mr. Hashim which they say is the portrait painter in the town.", "There's Mr. Hashim who they say is best portrait painter in the town."], "correctIndex": 1, "explanation": "Option (b) is correct because the relative pronoun 'who' is used for people as the subject of a clause, and 'Mr.' should be capitalized. Option (a) wrongly uses 'whom' (object form) and has lowercase 'mr.'; (c) uses incorrect punctuation and 'which' for a person; (d) omits the article 'the' before 'best portrait painter'.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 94, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2022 Q#94 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2022"}, {"id": "official_paper_q95_95", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 95, "subject": "English", "topic": "subject verb agreement", "question": "A full description of car accidents ______ reported.", "options": ["Are", "Have been", "Was", "Were"], "correctIndex": 2, "explanation": "Option (c) 'Was' is correct because the singular noun phrase 'A full description' takes a singular verb in the passive construction 'was reported.' Options (a) and (d) are plural verbs that do not agree, and (b) 'Have been' is plural/compound and does not match the singular subject.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 95, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2022 Q#95 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2022"}, {"id": "official_paper_q96_96", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 96, "subject": "English", "topic": "present perfect vs simple", "question": "Ahmad ______ me for a long time.", "options": ["Know", "Have known", "Knows", "Knew"], "correctIndex": 2, "explanation": "'Ahmad knows me' uses the simple present for an ongoing state. The phrase 'for a long time' would ideally take the present perfect 'has known', but the perfect option offered ('have known') does not agree with the singular subject 'Ahmad', so 'knows' is the best fit among the choices.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 96, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "NUMS 2022 Q#96 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2022"}, {"id": "official_paper_q97_97", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 97, "subject": "English", "topic": "vocabulary context meaning", "question": "He is appreciated for being ambidextrous. The underlined word means:", "options": ["Active and skillful", "Uses skills and wisdom", "Uses both hands for same skills", "Remains to the point"], "correctIndex": 2, "explanation": "Option (c) is correct: 'ambidextrous' literally means able to use both hands equally well. The other choices do not convey this meaning: (a) and (b) are related to skill but not specifically two-handed ability, and (d) is unrelated.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 97, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "NUMS 2022 Q#97 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2022"}, {"id": "official_paper_q98_98", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 98, "subject": "English", "topic": "vocabulary context meaning", "question": "He visited the ghettos for the first time. The underlined word means:", "options": ["Clean area", "Under privileged area", "Privileged area", "Modernly constructed"], "correctIndex": 1, "explanation": "Option (b) 'Under privileged area' correctly captures the meaning of 'ghettos' as socially and economically deprived areas. The other options are incorrect: (a) and (d) describe positive attributes, and (c) is the opposite.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 98, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "NUMS 2022 Q#98 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2022"}, {"id": "official_paper_q99_99", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 99, "subject": "English", "topic": "noun collocations", "question": "My friend has a fine ______ of old stamps.", "options": ["Group", "Bridge", "Band", "Collection"], "correctIndex": 3, "explanation": "Option (d) 'Collection' is the correct collocation for a set of stamps. 'Group', 'Bridge' and 'Band' are not standard collocations for stamps.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 99, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "NUMS 2022 Q#99 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2022"}, {"id": "official_paper_q100_100", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 100, "subject": "English", "topic": "agreement and structure", "question": "Choose the correct option:", "options": ["Every one of the prisons are full.", "Every one of the prisons had full.", "Every one of the prisons have full.", "Every one of the prisons is full."], "correctIndex": 3, "explanation": "Option (d) is grammatically correct: 'Every one' is a singular pronoun and takes the singular verb 'is'. Options (a) and (c) use plural verbs, and (b) is ungrammatical ('had full' is incorrect usage).", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 100, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "NUMS 2022 Q#100 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2022"}, {"id": "official_paper_q101_101", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 101, "subject": "English", "topic": "verb forms and tenses", "question": "The head master ______ to speak to you.", "options": ["Wants", "is wanting", "was wanting", "Want"], "correctIndex": 0, "explanation": "Option (a) 'Wants' is the correct simple present form for a stative verb in this context. 'Is wanting' (b) is not standard for stative verbs, (c) 'was wanting' changes tense unnecessarily, and (d) 'Want' is a non-matching base form.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 101, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2022 Q#101 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2022"}, {"id": "official_paper_q102_102", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 102, "subject": "English", "topic": "subject verb agreement", "question": "Knowledge and wisdom _____ no time for connection.", "options": ["Has", "Have", "Had", "Are"], "correctIndex": 1, "explanation": "Option (b) 'Have' is correct because 'knowledge and wisdom' are two nouns joined by 'and' and typically take a plural verb. Options (a) and (c) are singular past/present forms that don't agree with the compound subject; (d) 'Are' is a copular verb but does not fit the collocation used here.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 102, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2022 Q#102 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2022"}, {"id": "official_paper_q103_103", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 103, "subject": "English", "topic": "subject verb agreement", "question": "Each of three boys _____ to ride.", "options": ["Loves", "Love", "Are loving", "Have loved"], "correctIndex": 0, "explanation": "Option (a) 'Loves' is correct because 'Each' is a singular distributive pronoun and requires a singular verb. 'Love' (b) is plural and incorrect; (c) is progressive and odd for this stative preference; (d) changes the meaning to a perfect tense.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 103, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "NUMS 2022 Q#103 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2022"}, {"id": "official_paper_q104_104", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 104, "subject": "English", "topic": "sentence structure", "question": "Choose the correctly structured sentence.", "options": ["Mr. Shan, with his family together goes to England", "Mr. Shan, together with his family, goes to England.", "Mr. Shan, together with his family, go to England.", "Mr. Shan, with his family, go to England together."], "correctIndex": 1, "explanation": "Option (b) is correctly punctuated and uses the singular verb 'goes' to agree with the singular subject 'Mr. Shan'; the parenthetical phrase 'together with his family' is set off by commas. Options (c) and (d) use 'go' which does not agree with the singular subject, and (a) lacks the comma needed to set off the parenthetical phrase.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 104, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "NUMS 2022 Q#104 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2022"}, {"id": "official_paper_q105_105", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 105, "subject": "English", "topic": "error identification capitalization and agreement", "question": "Identify the errors and choose the correct option. The english man thinks that he and his country are the best.", "options": ["The english man thinks that he and his country are the best.", "The English man think that he and his country are the best.", "The English man thinks that he and his country are the best", "The English man think that he and his country are best."], "correctIndex": 2, "explanation": "Option C is correct: it capitalises the proper adjective 'English' and uses the singular verb 'thinks' to agree with the singular subject 'The English man'. Option A leaves 'english' uncapitalised, while B and D use the plural 'think', which does not agree with a singular subject.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 105, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "NUMS 2022 Q#105 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2022"}, {"id": "official_paper_q106_106", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 106, "subject": "English", "topic": "spelling", "question": "Pick the word with correct spelling.", "options": ["Mercenery", "Mersanary", "Mercenary", "Mersenary"], "correctIndex": 2, "explanation": "Option (c) 'Mercenary' is the correct spelling. The other choices are incorrect variants of the word.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 106, "syllabusUnit": "Vocabulary in Context", "pmdcTopic": "Contextual Meaning, Synonyms and Antonyms", "textbookCitation": "PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)", "citationString": "NUMS 2022 Q#106 | Vocabulary in Context | PMDC MDCAT English Syllabus (Vocabulary & High-Frequency Academic Words)"}, "year": "2022"}, {"id": "official_paper_q107_107", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 107, "subject": "Chemistry", "topic": "covalent vs ionic bonding", "question": "Which of the following molecule is covalent in nature?", "options": ["NaCl", "MgCl2", "AlCl3", "KCl"], "correctIndex": 2, "explanation": "AlCl3 shows significant covalent character due to the high polarizing power of the small, highly charged Al3+ ion which polarizes the electron cloud of chloride; the other listed compounds are predominantly ionic salts.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 107, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "NUMS 2022 Q#107 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2022"}, {"id": "official_paper_q108_108", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 108, "subject": "Chemistry", "topic": "reactivity trends alkali metals", "question": "Which of the following property increases down the group in alkali metals?", "options": ["Ionization energy", "Reactivity", "Electron affinity", "Electronegativity"], "correctIndex": 1, "explanation": "Reactivity of alkali metals increases down the group because the outer electron is further from the nucleus and more easily lost; ionization energy, electron affinity and electronegativity generally decrease down the group.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 108, "syllabusUnit": "Unit 8: Inorganic Chemistry & Periodicity", "pmdcTopic": "Periodic Trends, Group Chemistry & Transition Elements", "textbookCitation": "PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16", "citationString": "NUMS 2022 Q#108 | Unit 8: Inorganic Chemistry & Periodicity | PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16"}, "year": "2022"}, {"id": "official_paper_q109_109", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 109, "subject": "Chemistry", "topic": "solubility alkaline earth metals", "question": "The solubility of alkaline earth metal:", "options": ["Decreases down the group", "Increases down the group", "Remains constant throughout the group", "First increases then decreases down the group"], "correctIndex": 1, "explanation": "For many common salts (for example, the hydroxides) of the alkaline earth metals, solubility increases down the group because lattice energies decrease while hydration energies change less dramatically, making lower members more soluble.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 109, "syllabusUnit": "Unit 8: Inorganic Chemistry & Periodicity", "pmdcTopic": "Periodic Trends, Group Chemistry & Transition Elements", "textbookCitation": "PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16", "citationString": "NUMS 2022 Q#109 | Unit 8: Inorganic Chemistry & Periodicity | PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16"}, "year": "2022"}, {"id": "official_paper_q110_110", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 110, "subject": "Chemistry", "topic": "geometric isomerism alkenes", "question": "Geometric isomerism is exhibited by:", "options": ["Alcohol", "Ethers", "Alkynes", "Alkenes"], "correctIndex": 3, "explanation": "Geometric (cis–trans) isomerism requires restricted rotation about a double bond and different substituents on the double-bonded carbons; alkenes meet these requirements while alcohols, ethers and alkynes do not in the same way.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 110, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "NUMS 2022 Q#110 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2022"}, {"id": "official_paper_q111_111", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 111, "subject": "Chemistry", "topic": "conversion phenol to benzene", "question": "Benzene can be formed from phenol in which of the following reactions?", "options": ["Reduction with hydrogen in the presence of Ni", "Reduction with zinc", "Reduction with alkali", "Reduction with acids"], "correctIndex": 1, "explanation": "Reduction of phenol to benzene is classically achieved using metal reductions such as zinc; catalytic hydrogenation (H2/Ni) typically hydrogenates the aromatic ring to cyclohexane derivatives rather than simply removing the hydroxyl to give benzene.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 111, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "NUMS 2022 Q#111 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2022"}, {"id": "official_paper_q112_112", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 112, "subject": "Chemistry", "topic": "lucas test", "question": "Lucas test is used for the identification of:", "options": ["Alkyl halides", "Alcohols", "Alkene", "Carboxylic acids"], "correctIndex": 1, "explanation": "The Lucas test distinguishes primary, secondary and tertiary alcohols by their reactivity with ZnCl2/HCl (forming alkyl chlorides); it is specifically an identification test for alcohols.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 112, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2022 Q#112 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2022"}, {"id": "official_paper_q113_113", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 113, "subject": "Chemistry", "topic": "phenol physical properties", "question": "Phenol has following characteristics and physical properties:", "options": ["colorless crystalline solid", "colorless crystalline deliquescent solid", "Colorless amorphous solid", "Colorless amorphous deliquescent solid"], "correctIndex": 1, "explanation": "Phenol is typically a colorless crystalline solid that can absorb moisture from the air (deliquescent under certain conditions) due to its ability to hydrogen-bond with water.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 113, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "NUMS 2022 Q#113 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2022"}, {"id": "official_paper_q114_114", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 114, "subject": "Chemistry", "topic": "ketone identification tests", "question": "The identification test for Ketone is:", "options": ["Benedict's Solution Test", "Tehling's Solution Test", "Sodium Nitro Prusside Test", "Town's Test"], "correctIndex": 2, "explanation": "Sodium nitroprusside gives a characteristic test for certain ketone bodies (e.g., acetoacetate); Tollen's (printed here as Tehling's) and Benedict's tests are for aldehydes/reducing sugars, not general ketones.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 114, "syllabusUnit": "Unit 11: Carbonyl Compounds (Aldehydes & Ketones)", "pmdcTopic": "Carbonyl Chemistry, Addition Reactions & Tests for Carbonyls", "textbookCitation": "PTB Chemistry XII Ch 12 (Aldehydes and Ketones); Federal Chemistry XII Ch 20", "citationString": "NUMS 2022 Q#114 | Unit 11: Carbonyl Compounds (Aldehydes & Ketones) | PTB Chemistry XII Ch 12 (Aldehydes and Ketones); Federal Chemistry XII Ch 20"}, "year": "2022"}, {"id": "official_paper_q115_115", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 115, "subject": "Chemistry", "topic": "carboxylic acid solubility", "question": "Carboxylic acids are water soluble because they:", "options": ["Are more reactive", "Have hydrogen bonding", "Have low melting point", "Have high density"], "correctIndex": 1, "explanation": "Carboxylic acids can form hydrogen bonds with water (both as donors and acceptors), which increases their solubility compared with nonpolar compounds of similar molar mass.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 115, "syllabusUnit": "Unit 12: Carboxylic Acids & Derivatives", "pmdcTopic": "Acidity of Carboxylic Acids & Acyl Derivatives", "textbookCitation": "PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21", "citationString": "NUMS 2022 Q#115 | Unit 12: Carboxylic Acids & Derivatives | PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21"}, "year": "2022"}, {"id": "official_paper_q116_116", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 116, "subject": "Chemistry", "topic": "ideal gas equation", "question": "Which of the following represents equation for ideal gas?", "options": ["PV=nRT", "PT=nRv", "P=nRT", "T=npv/R"], "correctIndex": 0, "explanation": "The ideal gas law is PV = nRT, relating pressure, volume, amount (moles), and temperature with the gas constant R; the other forms as printed are incorrect rearrangements or contain typographical errors.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 116, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2022 Q#116 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2022"}, {"id": "official_paper_q117_117", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 117, "subject": "Chemistry", "topic": "gas conditions", "question": "How should the condition be changed to prevent the value of a given gas from expanding when its mass is increased?", "options": ["Temperature is lowered & pressure is increased", "Temperature is increased & pressure is lowered", "Temperature & pressure both are lowered", "Temperature & pressure both are increased"], "correctIndex": 0, "explanation": "To counteract expansion due to increased mass (which tends to increase pressure/volume), lowering temperature (reducing kinetic energy) and increasing external pressure will oppose expansion and help keep volume from increasing.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 117, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2022 Q#117 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2022"}, {"id": "official_paper_q118_118", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 118, "subject": "Chemistry", "topic": "gas law variables", "question": "Which variable mentioned in ideal gas is assumed to be constant in other gas laws?", "options": ["Volume", "Temperature", "Pressure", "Number of moles"], "correctIndex": 3, "explanation": "Many of the simple gas laws (Boyle's, Charles's, Gay-Lussac's) are derived assuming the amount of gas (number of moles, n) is constant; those laws then relate two of the other variables while holding n fixed.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 118, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2022 Q#118 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2022"}, {"id": "official_paper_q119_119", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 119, "subject": "Chemistry", "topic": "evaporation rate", "question": "Which of the following molecules will show a higher rate of evaporation?", "options": ["Acetone", "Ethanol", "Water", "Ethylene glycol"], "correctIndex": 0, "explanation": "Acetone has relatively weak intermolecular forces (low hydrogen bonding) and a high vapor pressure, so it evaporates faster than ethanol, water, or ethylene glycol which have stronger hydrogen bonding.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 119, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "NUMS 2022 Q#119 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2022"}, {"id": "official_paper_q120_120", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 120, "subject": "Chemistry", "topic": "specific heat water", "question": "Specific heat of water is:", "options": ["4.18 J/g/°C", "9.82 J/g/°C", "6.04 J/g/°C", "8.47 J/g/°C"], "correctIndex": 0, "explanation": "The specific heat capacity of liquid water is approximately 4.18 J g−1 °C−1 (or 1 cal g−1 °C−1), which is the standard accepted value.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 120, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2022 Q#120 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2022"}, {"id": "official_paper_q121_121", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 121, "subject": "Chemistry", "topic": "solubility polarity", "question": "Which of the following statement explains solubility of ionic substance in water?", "options": ["Water molar mass is 18.02", "Water forms dative bonding", "Water molecule is polar", "Water has high density"], "correctIndex": 2, "explanation": "Polar water molecules stabilize separated ions through ion-dipole interactions, so the polarity of water explains ionic solubility. The other options (molar mass, dative bonding, density) do not directly account for dissolving ionic lattices.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 121, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2022 Q#121 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2022"}, {"id": "official_paper_q122_122", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 122, "subject": "Chemistry", "topic": "diamond structure", "question": "Nature of diamond as solid is:", "options": ["Covalent", "Ionic", "Molecular", "Metallic"], "correctIndex": 0, "explanation": "Diamond is a network solid where each carbon atom is covalently bonded to four others in a giant lattice, so it is covalent. It is not ionic, molecular, or metallic.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 122, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "NUMS 2022 Q#122 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2022"}, {"id": "official_paper_q123_123", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 123, "subject": "Chemistry", "topic": "carbon allotropes", "question": "Which one of the following is as light as a feather and as strong as iron?", "options": ["Graphite", "Graphene", "Mercury", "Diamond"], "correctIndex": 1, "explanation": "Graphene is a single layer of carbon atoms with exceptional strength and very low mass, matching the description. Graphite (many layers) and diamond are strong but not described as 'as light as a feather'; mercury is a liquid metal and irrelevant.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 123, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2022 Q#123 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2022"}, {"id": "official_paper_q124_124", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 124, "subject": "Chemistry", "topic": "blood ph", "question": "The pH of human blood is:", "options": ["7.35 to 7.45", "8.35 to 8.45", "6.35 to 7.45", "5.57 to 6.57"], "correctIndex": 0, "explanation": "Normal human arterial blood pH is tightly regulated around 7.35–7.45. The other ranges are either too alkaline or too acidic to represent normal blood pH.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 124, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "NUMS 2022 Q#124 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2022"}, {"id": "official_paper_q125_125", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 125, "subject": "Chemistry", "topic": "atomic number", "question": "Proton number of 23Na11 is:", "options": ["23", "11", "12", "34"], "correctIndex": 1, "explanation": "The subscript (11) in 23Na11 is the atomic (proton) number, so there are 11 protons. 23 is the mass number, 12 would be neutrons if 23 is mass number (23−11), and 34 is unrelated.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 125, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2022 Q#125 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2022"}, {"id": "official_paper_q126_126", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 126, "subject": "Chemistry", "topic": "mole concept", "question": "One mole of ethanol and one mole of ethane have an equal:", "options": ["Mass", "Number of atoms", "Number of electrons", "Number of molecules"], "correctIndex": 3, "explanation": "One mole by definition contains the same number of molecules (Avogadro's number) regardless of the substance. Their masses, atoms per molecule, and electrons differ between ethanol and ethane.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 126, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2022 Q#126 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2022"}, {"id": "official_paper_q127_127", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 127, "subject": "Chemistry", "topic": "empirical formula", "question": "The 1' step involved in the determination of Empirical Formula of chemical compound is:", "options": ["Finding number of gram atoms of each element", "Percentage composition of each element", "Atomic ratio of each element", "Multiplication of atomic ratio with whole number"], "correctIndex": 1, "explanation": "Determining percentage composition (mass percent of each element) is the typical first step; from percentages you convert to gram amounts then to mole ratios. The other steps follow from percentage data.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 127, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "NUMS 2022 Q#127 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2022"}, {"id": "official_paper_q128_128", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 128, "subject": "Chemistry", "topic": "stoichiometry", "question": "The number of moles of CO2 which contains 16 g of oxygen is:", "options": ["0.25", "0.5", "1", "2"], "correctIndex": 1, "explanation": "One mole of CO2 has two oxygen atoms (32 g oxygen). 16 g oxygen is half that amount, so 0.5 mol CO2. The other numeric choices are not equal to 0.5.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 128, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2022 Q#128 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2022"}, {"id": "official_paper_q129_129", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 129, "subject": "Chemistry", "topic": "percentage composition", "question": "Percentage composition of mass in CO2, is:", "options": ["30.45% Carbon & 69.54% Oxygen", "24.22% Carbon & 75.78% Oxygen", "27.37% Carbon & 72.72% Oxygen", "41.68% Carbon & 58.12% Oxygen"], "correctIndex": 2, "explanation": "CO2 has mass fractions: C = 12/44 ≈ 27.27% and O = 32/44 ≈ 72.73%, so option showing ~27.37% C and ~72.72% O is the closest/correct choice. The other percentages do not match the 12:32 mass ratio.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 129, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2022 Q#129 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2022"}, {"id": "official_paper_q130_130", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 130, "subject": "Chemistry", "topic": "orbital capacity", "question": "Maximum electrons that can be placed in p subshell are:", "options": ["2", "6", "10", "14"], "correctIndex": 1, "explanation": "A p subshell has three orbitals (m = −1,0,+1), each holding two electrons, so maximum 6 electrons. 2, 10, and 14 correspond to s, d+f ranges and are incorrect for a p subshell.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 130, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2022 Q#130 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2022"}, {"id": "official_paper_q131_131", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 131, "subject": "Chemistry", "topic": "orbital energy", "question": "Apply n+l rule and calculate which of the following orbital has maximum energy?", "options": ["4s", "2p", "2d", "3s"], "correctIndex": 0, "explanation": "Using n+l, 4s and 2d both give n+l = 4, but among equal n+l the orbital with higher n has higher energy, so 4s has the maximum energy here. 2p and 3s have lower n+l values.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 131, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2022 Q#131 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2022"}, {"id": "official_paper_q132_132", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 132, "subject": "Chemistry", "topic": "subatomic particles", "question": "The mass of electron is:", "options": ["1836 times more than mass of proton", "1836 times less than mass of proton", "1836 times more than mass of neutron", "1836 times more than mass of hydrogen atom"], "correctIndex": 1, "explanation": "An electron's mass is about 1/1836 that of a proton, so it is 1836 times less than a proton. The other statements (electron more massive than proton/neutron/hydrogen atom) are incorrect.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 132, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2022 Q#132 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2022"}, {"id": "official_paper_q133_133", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 133, "subject": "Chemistry", "topic": "quantum numbers", "question": "The shape of an orbital is determined by which quantum number?", "options": ["n", "l", "m", "s"], "correctIndex": 1, "explanation": "The azimuthal quantum number l (subshell) determines orbital shape (s, p, d, f). n sets size/energy level, m sets orientation, and s is spin.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 133, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2022 Q#133 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2022"}, {"id": "official_paper_q134_134", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 134, "subject": "Chemistry", "topic": "electronic configuration", "question": "The electronic configuration for degenerate orbitals is explained by:", "options": ["Aufbau Principle", "n+l Rule", "Hund's Rule", "Paul's Exclusion Principle"], "correctIndex": 2, "explanation": "Hund's Rule explains how electrons occupy degenerate orbitals singly with parallel spins before pairing. Aufbau and n+l deal with orbital filling order, and Pauli's exclusion limits identical quantum states.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 134, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "NUMS 2022 Q#134 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2022"}, {"id": "official_paper_q135_135", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 135, "subject": "Chemistry", "topic": "saturated solution", "question": "Which term describes a solution in which dissolved solute is in equilibrium with undissolved solute?", "options": ["Dilute", "Saturated", "Unsaturated", "Supersaturated"], "correctIndex": 1, "explanation": "A saturated solution is at equilibrium between dissolved and undissolved solute. Dilute, unsaturated, and supersaturated describe other concentration states that are not equilibrium with undissolved solid in the same way.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 135, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "NUMS 2022 Q#135 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2022"}, {"id": "official_paper_q136_136", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 136, "subject": "Chemistry", "topic": "factors affecting rate", "question": "Rate of any reaction depends upon:", "options": ["Temperature", "Concentration", "Pressure", "Rate constant"], "correctIndex": 0, "explanation": "Temperature is a fundamental factor affecting reaction rates (it affects kinetic energy and collision frequency). While concentration and pressure can also affect rates in many cases, temperature is the single most general factor listed.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 136, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "NUMS 2022 Q#136 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2022"}, {"id": "official_paper_q137_137", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 137, "subject": "Chemistry", "topic": "rate reaction misconceptions", "question": "What is \"NOT TRUE\" about rate of a reaction?", "options": ["Concentration of reactants does not affect the rate of a reaction", "Surface area of reactants affects rate of reaction", "Concentration affects rate of reaction", "Catalyst affects rate of a reaction"], "correctIndex": 0, "explanation": "Statement (a) is false because concentration does affect reaction rate; increasing reactant concentration usually increases collision frequency and rate. The other statements are true influences on rate.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 137, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "NUMS 2022 Q#137 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2022"}, {"id": "official_paper_q138_138", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 138, "subject": "Chemistry", "topic": "combustion enthalpy", "question": "Enthalpy change of combustion is exothermic because:", "options": ["Energy released in bond breaking is greater", "Energy released in bond making is greater", "Energy absorbed in bond breaking is greater", "Energy absorbed in bond making is greater"], "correctIndex": 1, "explanation": "Combustion is exothermic because the energy released when new (product) bonds form exceeds the energy required to break reactant bonds. The other options misstate the relative bond energy changes.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 138, "syllabusUnit": "Unit 4: Chemical Energetics", "pmdcTopic": "Enthalpy Changes, Hess's Law & Standard Heats of Reaction", "textbookCitation": "PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6", "citationString": "NUMS 2022 Q#138 | Unit 4: Chemical Energetics | PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6"}, "year": "2022"}, {"id": "official_paper_q139_139", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 139, "subject": "Chemistry", "topic": "calorie joule conversion", "question": "One Calorie is equivalent to:", "options": ["4.184 J", "4.184 kJ", "0.4184 J", "0.4184 kJ"], "correctIndex": 0, "explanation": "The large (food) calorie (technically kilocalorie) is 4184 J, but the small calorie (1 cal) equals 4.184 J. Among the provided options, 4.184 J is correct for one (small) calorie.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 139, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2022 Q#139 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2022"}, {"id": "official_paper_q140_140", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 140, "subject": "Chemistry", "topic": "standard hydrogen electrode", "question": "Potential of Standard Hydrogen Electrode (SHE) is arbitrarily taken as:", "options": ["10", "+1", "-1", "Zero"], "correctIndex": 3, "explanation": "By convention the potential of the SHE is defined as 0 volts (zero). The numerical choices 10, +1, and -1 are not the standard convention.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 140, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2022 Q#140 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2022"}, {"id": "official_paper_q141_141", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 141, "subject": "Chemistry", "topic": "electrolysis reduction site", "question": "During electrolysis, reduction always occurs at:", "options": ["Anode", "Cathode", "SHE", "Salt bridge"], "correctIndex": 1, "explanation": "Reduction (gain of electrons) always occurs at the cathode in electrochemical cells; oxidation occurs at the anode. SHE and salt bridge are not sites of reduction in a general electrolysis cell.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 141, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "NUMS 2022 Q#141 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2022"}, {"id": "official_paper_q142_142", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 142, "subject": "Chemistry", "topic": "hybridization ethene", "question": "Type of hybridization of carbon in Ethene (H2C=CH2) is:", "options": ["Sp3", "sp2", "Sp", "dsp2"], "correctIndex": 1, "explanation": "In ethene each carbon is bonded to three groups (one double bond and two single bonds) and is sp2 hybridized. sp3 is for four single bonds, sp for triple bonds, and dsp2 is not applicable here.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 142, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "NUMS 2022 Q#142 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2022"}, {"id": "official_paper_q143_143", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 143, "subject": "Chemistry", "topic": "molecular polarity", "question": "Which of the following molecule is polar?", "options": ["CCl4", "AlCl3", "CO2", "HCl"], "correctIndex": 3, "explanation": "HCl is a polar diatomic molecule due to differing electronegativities. CCl4 and CO2 are symmetric and nonpolar overall, and AlCl3 is trigonal planar and overall nonpolar in the molecular form.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 143, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2022 Q#143 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2022"}, {"id": "official_paper_q144_144", "paperTitle": "NUMS MDCAT 2022 (Official Paper)", "shortTitle": "NUMS 2022", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "questionNumber": 144, "subject": "Chemistry", "topic": "electron affinity trend", "question": "Electron affinity decreases down the group because:", "options": ["Proton number increases", "Atomic radius increases", "Shielding decrease", "Rate constant"], "correctIndex": 1, "explanation": "Electron affinity generally decreases down a group because added electrons are farther from the nucleus (larger atomic radius) and are less strongly attracted. 'Proton number increases' is true down a group but offset by increased shielding; the other options are not correct explanations.", "reference": {"sourcePaper": "NUMS MDCAT 2022 (Official Paper)", "paperCode": "Official Paper", "authority": "National University of Medical Sciences", "province": "NUMS / Army Medical College", "originalQuestionNumber": 144, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "NUMS 2022 Q#144 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2022"}, {"id": "paper_q1_1", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 1, "subject": "Physics", "topic": "centripetal force", "question": "If during circular motion, tangential velocity of a body becomes double then centripetal force becomes:", "options": ["Double", "One half", "Four times", "One fourth"], "correctIndex": 2, "explanation": "Centripetal force varies as v^2 (Fc = mv^2/r). Doubling the tangential speed multiplies Fc by 2^2 = 4, so the force becomes four times. Answers like 'double' or 'one half' ignore the square dependence on velocity.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 1, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "PMC 2020 Q#1 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2020"}, {"id": "paper_q2_2", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 2, "subject": "Physics", "topic": "displacement vs distance", "question": "Under what condition an object will have zero displacement but non zero distance?", "options": ["Linear motion", "Circular motion", "Random motion", "Osciallation"], "correctIndex": 1, "explanation": "In circular motion, after one full revolution the object returns to its starting point so displacement (vector from start to end) is zero while the distance travelled is the circumference (non-zero). Linear or random motion need not return to the start.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 2, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "PMC 2020 Q#2 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2020"}, {"id": "paper_q3_3", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 3, "subject": "Physics", "topic": "longitudinal waves", "question": "Which one of the following properties is not exhibited by the longitudinal waves?", "options": ["Interference", "Reflection", "Diffraction", "Polarization"], "correctIndex": 3, "explanation": "Polarization is a property of transverse waves (it involves orientation of oscillations). Longitudinal waves (oscillations parallel to propagation) can show interference, reflection and diffraction but not polarization.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 3, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "PMC 2020 Q#3 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2020"}, {"id": "paper_q4_4", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 4, "subject": "Physics", "topic": "speed of sound", "question": "The speed of sound in air is 332m/s. the speed of sound at 22oC will be:", "options": ["345.2 m/s", "340 m/s", "350 m/s", "330 m/s"], "correctIndex": 0, "explanation": "Speed of sound in air increases roughly by 0.6 m/s per °C from 0°C; V = 332 + 0.6×22 = 332 + 13.2 = 345.2 m/s. This gives option 345.2 m/s.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 4, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "PMC 2020 Q#4 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2020"}, {"id": "paper_q5_5", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 5, "subject": "Physics", "topic": "doppler effect", "question": "Astronomers calculate speed of dstant stars and galaxies using which of the following phenomena?", "options": ["Beats", "Interference", "Super position principle", "Doppler effect"], "correctIndex": 3, "explanation": "The Doppler effect shifts spectral lines depending on radial velocity of astronomical objects; this shift is used to measure their speed. Beats and basic interference are not used for large-scale radial velocity measurements.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 5, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "PMC 2020 Q#5 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2020"}, {"id": "paper_q6_6", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 6, "subject": "Physics", "topic": "wave speed", "question": "In a ripple tank, 40 waves pass through a certain point in 1 second. If the wavelength of the wave is 5 cm, then speed of the wave is:", "options": ["0.5 ms-1", "1 ms-1", "1.5 ms-1", "2 ms-1"], "correctIndex": 3, "explanation": "Wave speed v = fλ. Here f = 40 s⁻1 and λ = 0.05 m, so v = 40×0.05 = 2 m/s. The other choices are obtained from incorrect arithmetic or unit conversion.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 6, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "PMC 2020 Q#6 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2020"}, {"id": "paper_q7_7", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 7, "subject": "Physics", "topic": "thermodynamic processes", "question": "In which process the entire of heat supplie to the gas is converted to the internal energy of the gas?", "options": ["Isochoric process", "Isoharic process", "Isothermal process", "Adiabatic process"], "correctIndex": 0, "explanation": "In an isochoric (constant-volume) process no work is done (ΔV = 0), so any heat supplied changes only internal energy (ΔQ = ΔU). In isothermal ΔU = 0, and in adiabatic ΔQ = 0.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 7, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "PMC 2020 Q#7 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2020"}, {"id": "paper_q8_8", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 8, "subject": "Physics", "topic": "isothermal process", "question": "The internal energy of a system during an isothermal process:", "options": ["Decrease", "Increase", "Becomes zero", "Remain constant"], "correctIndex": 3, "explanation": "For an ideal gas in an isothermal process the temperature is constant, and internal energy depends only on temperature, so internal energy remains constant. It neither increases nor decreases.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 8, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "PMC 2020 Q#8 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2020"}, {"id": "paper_q9_9", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 9, "subject": "Physics", "topic": "electric potential", "question": "If the potential at a point which is 1m from a charge is 1 volt, them the potential at a pont which is 2m from the same charge will be:", "options": ["2v", "1v", "0.5v", "3v"], "correctIndex": 2, "explanation": "Electric potential V due to point charge varies as 1/r (V = kQ/r). Doubling the distance halves the potential, so 1 V → 0.5 V at 2 m.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 9, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "PMC 2020 Q#9 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2020"}, {"id": "paper_q10_10", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 10, "subject": "Physics", "topic": "dielectrics", "question": "The values of electric intensity will due to the presence of dielectric medium:", "options": ["Increase", "Decrease", "Increase exponentially", "Remain same"], "correctIndex": 1, "explanation": "A dielectric reduces the effective electric field (electric intensity) within a capacitor for the same free charge because bound charges oppose the field; thus the field/PD is reduced if charge is held constant.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 10, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "PMC 2020 Q#10 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2020"}, {"id": "paper_q11_11", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 11, "subject": "Physics", "topic": "distance time graph", "question": "The slope of distance – time graph will always be:", "options": ["Negatice", "Positive", "Zero", "Maximum"], "correctIndex": 1, "explanation": "Distance is a scalar and cannot decrease with time, so the slope (speed) on a distance–time graph is non-negative; typically it's positive unless the object is at rest (zero). 'Negative' is not physically meaningful for distance.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 11, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "PMC 2020 Q#11 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2020"}, {"id": "paper_q12_12", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 12, "subject": "Physics", "topic": "free fall", "question": "If we drop an object, its initial velocity is zero. How far will it fall in time ‘t’?", "options": ["9.8 t2", "4.9 t2", "0.49 t2", "98 t2"], "correctIndex": 1, "explanation": "For an object dropped from rest, distance fallen is s = 1/2 g t^2. With g = 9.8 m/s^2 that is s = 4.9 t^2, so the object falls 4.9t^2 metres in time t.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 12, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "PMC 2020 Q#12 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2020"}, {"id": "paper_q13_13", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 13, "subject": "Physics", "topic": "units and dimensions", "question": "The newton-second is unit of:", "options": ["Work", "Power", "Impulse", "Momentum"], "correctIndex": 2, "explanation": "The newton-second (N s) is the unit of impulse, since impulse = force x time. Momentum has the equivalent units kg m/s, but the unit written as newton-second names impulse.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 13, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "PMC 2020 Q#13 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2020"}, {"id": "paper_q14_14", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 14, "subject": "Physics", "topic": "simple pendulum energy", "question": "What is the speed of 2.9 kg metallic b ob at mean position of a simple pendulum, when release from its extreme position 0.5 m high? (g = 10m-2\n)", "options": ["3.16 ms-1", "10 ms-1", "100 ms-1", "50 ms-1"], "correctIndex": 0, "explanation": "Potential energy at the extreme mgh = 2.9×10×0.5 ≈ 14.5 J is converted to kinetic energy ½mv^2 at mean position; solving ½mv^2 = mgh gives v = sqrt(2gh) ≈ sqrt(2×10×0.5)=sqrt(10)≈3.16 m/s, which matches option a.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 14, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "PMC 2020 Q#14 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2020"}, {"id": "paper_q15_15", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 15, "subject": "Physics", "topic": "kinetic energy dependence", "question": "When the speed of your car is halved, by what factor does its kinetic energy decreases?", "options": ["½", "¼", "1/8", "1/6"], "correctIndex": 1, "explanation": "Kinetic energy is proportional to v^2. If v becomes v/2, KE scales by (1/2)^2 = 1/4, so kinetic energy decreases to one quarter of its original value.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 15, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "PMC 2020 Q#15 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2020"}, {"id": "paper_q16_16", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 16, "subject": "Physics", "topic": "non conservative forces", "question": "Which one of the following force in non conservative force?", "options": ["Frictional force", "Gravitational force", "Electric force", "Elastic spring force"], "correctIndex": 0, "explanation": "Friction is path-dependent and dissipates mechanical energy as heat, so it is non-conservative. Gravitational, electric, and ideal elastic spring forces are conservative (they have potential energies).", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 16, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "PMC 2020 Q#16 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2020"}, {"id": "paper_q17_17", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 17, "subject": "Physics", "topic": "conservation of angular momentum", "question": "The earth rotates on its axis once a day. Suppose, by dome process the earth contracts so that its radius is only half as large as at present, then how long the earth will take to complete its rotation?", "options": ["24 hours", "18 hours", "6 hours", "12 hours"], "correctIndex": 2, "explanation": "Conservation of angular momentum (Iω = constant). If radius is halved, moment of inertia for a sphere scales with R^2 so I' = I/4, hence ω' = 4ω and period T' = T/4. With T = 24 h, T' = 6 h.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 17, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "PMC 2020 Q#17 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2020"}, {"id": "paper_q18_18", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 18, "subject": "Physics", "topic": "angle conversion", "question": "radian is equal to:", "options": ["57.1o", "57.2", "57.3’’", "57.4o"], "correctIndex": 2, "explanation": "360° = 2π radians, so 1 rad ≈ 360/(2π) ≈ 57.2958°, commonly rounded to 57.3°. The paper's printed option that corresponds to this value is the third choice.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 18, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "PMC 2020 Q#18 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2020"}, {"id": "paper_q19_19", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 19, "subject": "Physics", "topic": "power transmission", "question": "In transmission from grid station, power losses are maximized by:", "options": ["Increasing current", "Decreasing current", "Increasing resistance", "Increasing voltage"], "correctIndex": 0, "explanation": "Power loss in transmission is I^2R; increasing current increases losses. To minimize losses, transmission uses high voltage to reduce current. Thus 'increasing current' maximizes losses.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 19, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "PMC 2020 Q#19 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2020"}, {"id": "paper_q20_20", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 20, "subject": "Physics", "topic": "mains frequency", "question": "The domestic electricity supply has a frequency of:", "options": ["150 Hz", "100 Hz", "50 Hz", "25 Hz"], "correctIndex": 2, "explanation": "In many countries including Pakistan the mains (domestic) AC frequency is 50 Hz, so that is the correct choice here.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 20, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "PMC 2020 Q#20 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2020"}, {"id": "paper_q21_21", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 21, "subject": "Physics", "topic": "diode terminology", "question": "PIV stands for:", "options": ["Positive inverse charge", "Power integrated voltage", "Peak inverse voltage", "Peak integrated voltage"], "correctIndex": 2, "explanation": "PIV means Peak Inverse Voltage - the maximum reverse voltage a diode can withstand without breakdown. The other options are not standard diode terminology.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 21, "syllabusUnit": "Unit 10: Electronics & Semiconductors", "pmdcTopic": "Semiconductor Physics, Diodes & Rectification", "textbookCitation": "PTB Physics XII Ch 18 (Dawn of Modern Physics / Electronics); Federal Physics XII Ch 16", "citationString": "PMC 2020 Q#21 | Unit 10: Electronics & Semiconductors | PTB Physics XII Ch 18 (Dawn of Modern Physics / Electronics); Federal Physics XII Ch 16"}, "year": "2020"}, {"id": "paper_q22_22", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 22, "subject": "Physics", "topic": "de broglie wavelength", "question": "The wavelength associated with an electron is of the order of:", "options": ["Visible light", "X-rays", "Radio waves", "Infraref"], "correctIndex": 1, "explanation": "Electrons accelerated to typical laboratory energies have de Broglie wavelengths on the order of X-ray wavelengths (angstroms to tenths of an angstrom), much shorter than visible light and far shorter than radio waves.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 22, "syllabusUnit": "Unit 4: Oscillations and Waves", "pmdcTopic": "Simple Harmonic Motion, Wave Properties & Doppler Effect", "textbookCitation": "PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8", "citationString": "PMC 2020 Q#22 | Unit 4: Oscillations and Waves | PTB Physics XI Ch 7 (Oscillations) & Ch 8 (Waves); Federal Physics XI Ch 7-8"}, "year": "2020"}, {"id": "paper_q23_23", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 23, "subject": "Physics", "topic": "photon energy", "question": "Which photon carries the most energy?", "options": ["Blue", "Violet", "Red", "Green"], "correctIndex": 1, "explanation": "Photon energy E = hf and frequency increases as wavelength decreases. Violet light has the shortest wavelength among the options, hence the highest frequency and most energy.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 23, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "PMC 2020 Q#23 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2020"}, {"id": "paper_q24_24", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 24, "subject": "Physics", "topic": "hydrogen spectra", "question": "Which one of the following series lies in the ultraviolet region?", "options": ["Balmer series", "Pascher series", "Lyman series", "Bracaket series"], "correctIndex": 2, "explanation": "The Lyman series corresponds to electronic transitions to n=1 in hydrogen and emits photons in the ultraviolet. The Balmer series is visible; Paschen and Brackett are infrared.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 24, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "PMC 2020 Q#24 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2020"}, {"id": "paper_q25_25", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 25, "subject": "Physics", "topic": "x vs gamma", "question": "The main difference between X-rays and γ rays is:", "options": ["Frequency", "Wave length", "Energy", "Origin"], "correctIndex": 3, "explanation": "Although X-rays and γ-rays can overlap in energy, the primary distinction is origin: X-rays arise from electron transitions or deceleration of electrons, while γ-rays originate from nuclear transitions.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 25, "syllabusUnit": "Unit 12: Atomic and Nuclear Physics", "pmdcTopic": "Bohr Model, Radioactivity & Nuclear Reactions", "textbookCitation": "PTB Physics XII Ch 20 (Atomic Spectra) & Ch 21 (Nuclear Physics); Federal Physics XII Ch 18-19", "citationString": "PMC 2020 Q#25 | Unit 12: Atomic and Nuclear Physics | PTB Physics XII Ch 20 (Atomic Spectra) & Ch 21 (Nuclear Physics); Federal Physics XII Ch 18-19"}, "year": "2020"}, {"id": "paper_q26_26", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 26, "subject": "Physics", "topic": "half life", "question": "There are initially 400 atoms in a radioactive sample. What of atoms after 3 half-life?", "options": ["400", "200", "50", "25"], "correctIndex": 2, "explanation": "Each half-life halves the remaining atoms: 400 → 200 (1st) → 100 (2nd) → 50 (3rd). So 50 atoms remain after three half-lives.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 26, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "PMC 2020 Q#26 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2020"}, {"id": "paper_q27_27", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 27, "subject": "Physics", "topic": "radioisotopes in medicine", "question": "Which using radiation theraphy, cancerous thyroid is treated with radioisotope:", "options": ["Carbon", "235 uranium", "Thorium", "Iodine-131"], "correctIndex": 3, "explanation": "Radioactive iodine-131 is used therapeutically to ablate thyroid tissue because the thyroid selectively uptakes iodine; the other isotopes listed are not used for thyroid radiotherapy.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 27, "syllabusUnit": "Unit: General Physics Principles", "pmdcTopic": "Physical Quantities, Measurements & Mechanics", "textbookCitation": "PTB Physics XI/XII; PMDC MDCAT Physics Framework", "citationString": "PMC 2020 Q#27 | Unit: General Physics Principles | PTB Physics XI/XII; PMDC MDCAT Physics Framework"}, "year": "2020"}, {"id": "paper_q28_28", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 28, "subject": "Physics", "topic": "capacitors", "question": "In capacitors, energy is stored in the form of:", "options": ["Gravitational energy", "Kinetic energy", "Electric intensity", "Magnetic induction"], "correctIndex": 2, "explanation": "A capacitor stores electrical potential energy in the electric field between its plates (often described here as electric intensity). Inductors store energy in magnetic fields, not capacitors.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 28, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "PMC 2020 Q#28 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2020"}, {"id": "paper_q29_29", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 29, "subject": "Physics", "topic": "rc time constant", "question": "Ohm time’s farad is equivalent to:", "options": ["Time", "Charge", "Distance", "Capacitor"], "correctIndex": 0, "explanation": "Resistance (ohm) × capacitance (farad) has units of seconds and represents the RC time constant, so the correct equivalence is a unit of time.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 29, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "PMC 2020 Q#29 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2020"}, {"id": "paper_q30_30", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 30, "subject": "Physics", "topic": "kilowatt hour", "question": "One kilowatt-hours is commonly termed as one commercial uniq of electric energy which is equal to:", "options": ["3.6 x 105 J", "3.6 x 106 J", "3.6 x 104 J", "3.6 x 103 J"], "correctIndex": 1, "explanation": "1 kW·h = 1000 W × 3600 s = 3.6×10^6 J. The paper labels the 3.6×10^6 J option as correct.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 30, "syllabusUnit": "Unit 2: Work, Energy and Power", "pmdcTopic": "Work-Energy Theorem, Conservative Forces & Power", "textbookCitation": "PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4", "citationString": "PMC 2020 Q#30 | Unit 2: Work, Energy and Power | PTB Physics XI Ch 4 (Work and Energy); Federal Physics XI Ch 4"}, "year": "2020"}, {"id": "paper_q31_31", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 31, "subject": "Physics", "topic": "resistance and geometry", "question": "When a wire is compressed and its radius becomes 2R then its resistance will be:", "options": ["16R", "4R", "1/16R", "1/4R"], "correctIndex": 2, "explanation": "If radius doubles the cross-sectional area increases by 4, and to keep volume constant the length becomes one quarter; resistance R ∝ L/A so R' = R·(1/4)/(4) = R/16, hence 1/16 R.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 31, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "PMC 2020 Q#31 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2020"}, {"id": "paper_q32_32", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 32, "subject": "Physics", "topic": "ohmic behavior", "question": "One of the following is an ohmicdevie:", "options": ["Filament bulb", "Semiconductor diode", "Transistor", "Copper wire"], "correctIndex": 3, "explanation": "An ohmic device shows a linear V–I relationship; metals like copper approximate Ohm's law across a wide range, while filament bulbs and semiconductor devices are typically non-ohmic.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 32, "syllabusUnit": "Unit 7: Current Electricity", "pmdcTopic": "Ohm's Law, Kirchhoff's Rules & Circuit Analysis", "textbookCitation": "PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12", "citationString": "PMC 2020 Q#32 | Unit 7: Current Electricity | PTB Physics XII Ch 13 (Current Electricity); Federal Physics XII Ch 12"}, "year": "2020"}, {"id": "paper_q33_33", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 33, "subject": "Physics", "topic": "resistance temperature dependence", "question": "The change is resistance of metallic conductor at temperature below 0oC is:", "options": ["Non linear", "Curve", "Linear", "Curvilinear"], "correctIndex": 2, "explanation": "For typical metallic conductors the resistance varies approximately linearly with temperature over a broad range, so the resistance vs. temperature relationship is treated as linear.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 33, "syllabusUnit": "Unit 5: Thermodynamics", "pmdcTopic": "First Law of Thermodynamics, Heat Engines & Gas Processes", "textbookCitation": "PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10", "citationString": "PMC 2020 Q#33 | Unit 5: Thermodynamics | PTB Physics XI Ch 11 (Heat and Thermodynamics); Federal Physics XI Ch 10"}, "year": "2020"}, {"id": "paper_q34_34", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 34, "subject": "Physics", "topic": "parallel wires", "question": "When current are flowing through two long parallel wires in same direction electric field between them is:", "options": ["Strong", "Weak", "Remains constant", "Infinite"], "correctIndex": 2, "explanation": "The paper's explanation states the electric field in the region between the wires is essentially the same (unchanged) while the magnetic fields may interact. Thus the intended answer is that the electric field 'remains constant.'", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 34, "syllabusUnit": "Unit 6: Electrostatics", "pmdcTopic": "Coulomb's Law, Electric Fields & Capacitors", "textbookCitation": "PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11", "citationString": "PMC 2020 Q#34 | Unit 6: Electrostatics | PTB Physics XII Ch 12 (Electrostatics); Federal Physics XII Ch 11"}, "year": "2020"}, {"id": "paper_q35_35", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 35, "subject": "Physics", "topic": "magnetic flux", "question": "Magnetic flux is maximum when angle between magnetic field and vector area is:", "options": ["0", "90o", "180o", "45o"], "correctIndex": 0, "explanation": "Magnetic flux Φ = B·A·cosθ is maximal when cosθ = 1, i.e., θ = 0° (field parallel to the area normal). At 90° the flux is zero.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 35, "syllabusUnit": "Unit 8: Electromagnetism", "pmdcTopic": "Magnetic Fields, Force on Charged Particles & Magnetic Flux", "textbookCitation": "PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13", "citationString": "PMC 2020 Q#35 | Unit 8: Electromagnetism | PTB Physics XII Ch 14 (Electromagnetism); Federal Physics XII Ch 13"}, "year": "2020"}, {"id": "paper_q36_36", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 36, "subject": "Physics", "topic": "transformer", "question": "Transformer is device which steps up or steps down the input:", "options": ["Current", "Voltage", "Energy", "Power"], "correctIndex": 1, "explanation": "Transformers are used to change (step up or step down) AC voltage between primary and secondary coils; the power (neglecting losses) is approximately conserved so transformers do not generate energy.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 36, "syllabusUnit": "Unit 9: Electromagnetic Induction & AC Circuits", "pmdcTopic": "Faraday's Law, Lenz's Law, Transformers & AC Fundamentals", "textbookCitation": "PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15", "citationString": "PMC 2020 Q#36 | Unit 9: Electromagnetic Induction & AC Circuits | PTB Physics XII Ch 15 (Electromagnetic Induction) & Ch 16 (AC); Federal Physics XII Ch 14-15"}, "year": "2020"}, {"id": "paper_q37_37", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 37, "subject": "Physics", "topic": "faradays law", "question": "If a stationary bar magnet is places near a coil at rest so maximum lines of force passes through the coil, the galvanometer shows:", "options": ["Maximum current", "Minimum current", "No current", "Intermediate value of current"], "correctIndex": 2, "explanation": "Faraday's law requires a change in magnetic flux to induce current. If the magnet and coil are stationary with constant flux, there is no induced emf and the galvanometer reads zero (no current).", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 37, "syllabusUnit": "Unit 1: Force and Motion", "pmdcTopic": "Newton's Laws, Momentum Conservation & Projectile Motion", "textbookCitation": "PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3", "citationString": "PMC 2020 Q#37 | Unit 1: Force and Motion | PTB Physics XI Ch 3 (Motion and Force); Federal Physics XI Ch 3"}, "year": "2020"}, {"id": "paper_q38_38", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 38, "subject": "Chemistry", "topic": "sn2 mechanism", "question": "Alkyl halides involving –C –X bond breakage and –C –Nu bond formation simultaneously would follow the mechanism", "options": ["SN1", "SN2", "E1", "E2"], "correctIndex": 1, "explanation": "An SN2 mechanism is a concerted one-step substitution where the nucleophile bonds as the leaving group departs, so C–X breaking and C–Nu formation occur simultaneously. SN1 is stepwise via a carbocation.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 38, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "PMC 2020 Q#38 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2020"}, {"id": "paper_q39_39", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 39, "subject": "Chemistry", "topic": "phenol nomenclature", "question": "Phenol is known as:", "options": ["Carpolic acid", "Carbonylic acid", "Carbolic acid", "Carbolylic acid"], "correctIndex": 2, "explanation": "The common historical name for phenol is 'carbolic acid'. The other spellings are incorrect variants and not the standard common name.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 39, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "PMC 2020 Q#39 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2020"}, {"id": "paper_q40_40", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 40, "subject": "Chemistry", "topic": "phenol acidity", "question": "Phenol is more acidic than alcohols because of the following reason:", "options": ["Delocalization of negative charge in the OH group", "Delocalization of positive charge on the carbon atom in ring", "Delicalization of negative charge in the ring", "Delocalization of positive charge on the OH group"], "correctIndex": 2, "explanation": "When phenol loses H+ the phenoxide ion is stabilized by resonance delocalization of the negative charge into the aromatic ring, increasing acidity compared with typical alcohols whose conjugate bases lack this delocalization.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 40, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "PMC 2020 Q#40 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2020"}, {"id": "paper_q41_41", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 41, "subject": "Chemistry", "topic": "purification of carbonyls", "question": "which of the following reagent is use to separate and purify carbonyl and non- carbonyl compounds?", "options": ["HCN", "BrMgCH3", "NaHSO3", "H2O"], "correctIndex": 2, "explanation": "Sodium bisulfite (NaHSO3) forms a water-soluble adduct with many aldehydes/ketones, allowing separation from non-carbonyl compounds. The other reagents are not routinely used for this selective separation.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 41, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "PMC 2020 Q#41 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2020"}, {"id": "paper_q42_42", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 42, "subject": "Chemistry", "topic": "hydrolysis of acyl chlorides", "question": "Hydrolysis of acyl chloride results in the formation of:", "options": ["Acid anhydride", "Carboxylic acid", "Amides", "Esters"], "correctIndex": 1, "explanation": "Hydrolysis of an acyl chloride (RCOCl) with water replaces the chloride with a hydroxyl group to give the corresponding carboxylic acid (RCOOH). Acyl chlorides are more reactive toward hydrolysis than anhydrides, esters or amides, so formation of the acid is expected.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 42, "syllabusUnit": "Unit 12: Carboxylic Acids & Derivatives", "pmdcTopic": "Acidity of Carboxylic Acids & Acyl Derivatives", "textbookCitation": "PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21", "citationString": "PMC 2020 Q#42 | Unit 12: Carboxylic Acids & Derivatives | PTB Chemistry XII Ch 13 (Carboxylic Acids); Federal Chemistry XII Ch 21"}, "year": "2020"}, {"id": "paper_q43_43", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 43, "subject": "Chemistry", "topic": "relative reactivity of derivatives", "question": "The exact reactivity order for carboxylic acid derivatives is:", "options": ["Anhydride >acylchloride> ester", "Ester > anhydride >acylchloride", "Amide >acylchloride> ester", "Acychloride> anhydride > Ester"], "correctIndex": 3, "explanation": "Acyl chlorides are generally the most reactive carboxylic derivatives because chloride is an excellent leaving group, followed by anhydrides and then esters and amides. Option (d) (despite the typographical error) lists acyl chloride > anhydride > ester, matching the expected reactivity order.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 43, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "PMC 2020 Q#43 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2020"}, {"id": "paper_q44_44", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 44, "subject": "Chemistry", "topic": "classification of proteins", "question": "Based on the physio – chemical properties, proteins may be classified into the following types:", "options": ["Simple proteins", "Compound proteins", "Derived proteins", "All of the above"], "correctIndex": 3, "explanation": "Proteins are classified by physico-chemical properties into simple proteins (yield only amino acids on hydrolysis), compound (conjugated) proteins and derived proteins (modified derivatives). Therefore all three categories are included.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 44, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "PMC 2020 Q#44 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2020"}, {"id": "paper_q45_45", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 45, "subject": "Chemistry", "topic": "thyroxin classification", "question": "Based on function, thyroxin can be classified as:", "options": ["Hormonal protein", "Structural protein", "Transport protein", "Genetic protein"], "correctIndex": 0, "explanation": "Thyroxine (thyroxine/T4) is a hormone produced by the thyroid gland and functions as an endocrine regulator. Functionally it is classified as a hormone rather than a structural, transport or genetic protein.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 45, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "PMC 2020 Q#45 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2020"}, {"id": "paper_q46_46", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 46, "subject": "Chemistry", "topic": "l asparaginase therapeutic use", "question": "L-Asparaginase enzyme has been used for the treatment of:", "options": ["Jaundice", "Blood cancer", "Rickets", "Heat disease"], "correctIndex": 1, "explanation": "L-asparaginase depletes asparagine and is used as a chemotherapy agent, especially in acute lymphoblastic leukemia (a blood cancer). It is not used to treat jaundice, rickets or heart disease.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 46, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "PMC 2020 Q#46 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2020"}, {"id": "paper_q47_47", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 47, "subject": "Chemistry", "topic": "oxides of alkali metals", "question": "Potassium, Rubidium, Cesium react with oxygen to form which types of oxides?", "options": ["Peroxide", "Superoxide", "Suboxide", "Normal oxide"], "correctIndex": 1, "explanation": "The heavier alkali metals (K, Rb, Cs) readily form superoxides (MO2) when burned in excess oxygen; lighter alkali metals favor oxide or peroxide formation. Thus superoxide is the correct type for these elements.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 47, "syllabusUnit": "Unit 8: Inorganic Chemistry & Periodicity", "pmdcTopic": "Periodic Trends, Group Chemistry & Transition Elements", "textbookCitation": "PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16", "citationString": "PMC 2020 Q#47 | Unit 8: Inorganic Chemistry & Periodicity | PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16"}, "year": "2020"}, {"id": "paper_q48_48", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 48, "subject": "Chemistry", "topic": "magnesium nitrides", "question": "Magnesium reacts with nitrogen to form:", "options": ["Mg2N2", "Mg3N2", "MgN2", "MgN"], "correctIndex": 1, "explanation": "Magnesium nitride has the formula Mg3N2 (each nitride ion N3− pairs with three Mg2+ cations to give Mg3N2), so option (b) is correct.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 48, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "PMC 2020 Q#48 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2020"}, {"id": "paper_q49_49", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 49, "subject": "Chemistry", "topic": "physical properties", "question": "Densities of alkali metals are low due to:", "options": ["Weak intermolecular forces", "Large atomic volume", "Smaller size", ".ns1 configuration"], "correctIndex": 1, "explanation": "Alkali metals have low densities largely because of their large atomic/atomic-volume and low packing efficiency; the single valence electron (ns1) also contributes to low metallic bonding strength, but the principal factor listed is large atomic volume.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 49, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "PMC 2020 Q#49 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2020"}, {"id": "paper_q50_50", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 50, "subject": "Chemistry", "topic": "paramagnetism", "question": "In 3rd series of transition elements, paramagnetic behavior is maximum for Mn+2 and:", "options": ["Cr3+", "Ti3+", "V3+", "Zn+2"], "correctIndex": 0, "explanation": "Among the listed ions, Cr3+ has the greatest number of unpaired electrons (d3) compared with Ti3+ (d1), V3+ (d2) and Zn2+ (d10, diamagnetic). Combined with Mn2+ (d5), Cr3+ gives the largest paramagnetic response among the choices.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 50, "syllabusUnit": "Unit 8: Inorganic Chemistry & Periodicity", "pmdcTopic": "Periodic Trends, Group Chemistry & Transition Elements", "textbookCitation": "PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16", "citationString": "PMC 2020 Q#50 | Unit 8: Inorganic Chemistry & Periodicity | PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16"}, "year": "2020"}, {"id": "paper_q51_51", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 51, "subject": "Chemistry", "topic": "chromium configuration", "question": "Electronic configuration of chromium (proton number 24) is:", "options": ["[Ar] 3d4 4S2", "[Ar} 3d5 4S2", "[Ar] 3d5 4S1", "[Ar] 3d6 4S2"], "correctIndex": 2, "explanation": "Chromium exhibits the anomalous configuration [Ar] 3d5 4s1 (a half-filled d-subshell offers extra stability), so option (c) is correct.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 51, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "PMC 2020 Q#51 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2020"}, {"id": "paper_q52_52", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 52, "subject": "Chemistry", "topic": "variable valency", "question": "The transition element which does not show variable valencyos:", "options": ["Cu", "Sc", "Zn", "Cr"], "correctIndex": 2, "explanation": "Zinc predominantly shows a +2 oxidation state (filled d10 configuration) and does not commonly exhibit variable valency like many other transition elements, so Zn is the correct choice.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 52, "syllabusUnit": "Unit 8: Inorganic Chemistry & Periodicity", "pmdcTopic": "Periodic Trends, Group Chemistry & Transition Elements", "textbookCitation": "PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16", "citationString": "PMC 2020 Q#52 | Unit 8: Inorganic Chemistry & Periodicity | PTB Chemistry XII Ch 1-6 (Inorganic Chemistry); Federal Chemistry XII Ch 13-16"}, "year": "2020"}, {"id": "paper_q53_53", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 53, "subject": "Chemistry", "topic": "arenes", "question": "Select the organic compound which belongs to Arene family;", "options": ["CH2=CH2", "CH3-o-CH3", "CH3□ NH2", "C6H6"], "correctIndex": 3, "explanation": "Arenes are aromatic hydrocarbons such as benzene; C6H6 (benzene) is the prototypical arene. The other options are ethene, an ether and an amine respectively.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 53, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "PMC 2020 Q#53 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2020"}, {"id": "paper_q54_54", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 54, "subject": "Chemistry", "topic": "functional group isomerism", "question": "The type of isomerism existing in a compound of molecular formula C2H60 is:", "options": ["Functional group", "Position", "Chain", "Metamerism"], "correctIndex": 0, "explanation": "The formula appears to be C2H6O (ethanol and dimethyl ether are constitutional isomers). That pair are functional group isomers (alcohol vs ether), so functional group isomerism is correct.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 54, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "PMC 2020 Q#54 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2020"}, {"id": "paper_q55_55", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 55, "subject": "Chemistry", "topic": "cycloalkane formula", "question": "Generic formula of cycloalkane is?", "options": ["CnH2n+2", "CnH2n", "CnH2n+1", "CnH2n-2"], "correctIndex": 1, "explanation": "Cycloalkanes have the general formula CnH2n (each ring removes two hydrogens compared with the corresponding alkane), so option (b) is correct.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 55, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "PMC 2020 Q#55 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2020"}, {"id": "paper_q56_56", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 56, "subject": "Chemistry", "topic": "sulphonation of benzene", "question": "Electrophile in sulphonation of benzene is:", "options": ["HSO4-", "H2SO4", "SO3", "HSO3-"], "correctIndex": 2, "explanation": "The active electrophile in sulfonation is sulfur trioxide (SO3) or the equivalent SO3·H+ species generated from concentrated sulfuric acid; SO3 is the electrophilic species that attacks the aromatic ring.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 56, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "PMC 2020 Q#56 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2020"}, {"id": "paper_q57_57", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 57, "subject": "Chemistry", "topic": "formation of acetophenone", "question": "Acetophenoe can be formed by which of the following reaction of benzene?", "options": ["Alkylation", "Acylation", "Halogenation", "Nitration"], "correctIndex": 1, "explanation": "Acetophenone (phenyl methyl ketone) is formed by Friedel–Crafts acylation of benzene with an acetyl chloride or acylium ion, so acylation is the correct reaction type.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 57, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "PMC 2020 Q#57 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2020"}, {"id": "paper_q58_58", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 58, "subject": "Chemistry", "topic": "alkane hybridization", "question": "In alkanes, each carbon has hybridization:", "options": ["Sp3", "Sp", "SP2", "Dsp"], "correctIndex": 0, "explanation": "In alkanes every carbon is tetrahedral and uses sp3 hybrid orbitals to form four sigma bonds, so sp3 is correct.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 58, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "PMC 2020 Q#58 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2020"}, {"id": "paper_q59_59", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 59, "subject": "Chemistry", "topic": "activating deactivating groups", "question": "When CH3 is attached with the benzene ring, it makes the ring:", "options": ["Good Electrophile", "Good nucleophile", "Resonance hybrid", "Extraordinary stable"], "correctIndex": 1, "explanation": "A methyl substituent is electron-donating by hyperconjugation, increasing electron density of the ring and making it a better nucleophile toward electrophiles (i.e., the ring is activated for electrophilic substitution).", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 59, "syllabusUnit": "Unit 9: Hydrocarbons & Aromatic Chemistry", "pmdcTopic": "Aliphatic Hydrocarbons, Benzene Structure & Electrophilic Substitution", "textbookCitation": "PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18", "citationString": "PMC 2020 Q#59 | Unit 9: Hydrocarbons & Aromatic Chemistry | PTB Chemistry XII Ch 7-9 (Organic Compounds & Hydrocarbons); Federal Chemistry XII Ch 17-18"}, "year": "2020"}, {"id": "paper_q60_60", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 60, "subject": "Chemistry", "topic": "kp vs kc", "question": "Which of the following reaction has greater Kp than Kc (kp>Kc)", "options": ["2NO + Cl2 = 2NOCi", "2SO2 + O2 = 2SO3", "2NOCi = 2No + Cl2", "N2 + 3H2 = 2NH3"], "correctIndex": 2, "explanation": "Kp and Kc are related by Kp = Kc (RT)^{Δn}. Reaction (c) has Δn = +1 (more moles of gas in products than reactants), so Kp = Kc(RT)^{+1} and Kp > Kc under typical conditions.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 60, "syllabusUnit": "Unit 5: Chemical Equilibrium", "pmdcTopic": "Equilibrium Constant, Le Chatelier's Principle & Buffer Solutions", "textbookCitation": "PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7", "citationString": "PMC 2020 Q#60 | Unit 5: Chemical Equilibrium | PTB Chemistry XI Ch 8 (Chemical Equilibrium); Federal Chemistry XI Ch 7"}, "year": "2020"}, {"id": "paper_q61_61", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 61, "subject": "Chemistry", "topic": "haber process", "question": "The equation N2g + 3H2g = 2NH3, represents:", "options": ["Contact process", "Haber’s process", "Solvay process", "Avagadro’s law"], "correctIndex": 1, "explanation": "The synthesis of ammonia from nitrogen and hydrogen (N2 + 3H2 ⇌ 2NH3) is the Haber process (Haber–Bosch), so option (b) is correct.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 61, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "PMC 2020 Q#61 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2020"}, {"id": "paper_q62_62", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 62, "subject": "Chemistry", "topic": "units of rate constant", "question": "The unit of the rate constant is the same as that of the rate of reaction in:", "options": ["Zero order reaction", "First order reaction", "Second order reaction", "Third order reaction"], "correctIndex": 0, "explanation": "For a zero-order reaction the rate has units of concentration/time and the rate constant k likewise has units of concentration/time, so their units are the same in zero-order kinetics.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 62, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "PMC 2020 Q#62 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2020"}, {"id": "paper_q63_63", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 63, "subject": "Chemistry", "topic": "definition of kinetics", "question": "The study of rates of chemical reactions and the factors that affect the rates of chemical reactions is known as:", "options": ["Thermodynamics", "Stoichiometry", "Electrochemistry", "Chemical kinetics"], "correctIndex": 3, "explanation": "Chemical kinetics is the branch of chemistry that deals with reaction rates and the factors that influence them, so option (d) is the correct definition.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 63, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "PMC 2020 Q#63 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2020"}, {"id": "paper_q64_64", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 64, "subject": "Chemistry", "topic": "reaction order determination", "question": "For the reaction A(g) -> products, when the concentration of A(g) doubles, the rate of reaction increases four fold, which means it is:", "options": ["Negative order reaction", "First order reaction", "Zero order reaction", "Second order reaction"], "correctIndex": 3, "explanation": "If doubling [A] causes the rate to increase by a factor of four, the rate ∝ [A]^2, indicating a second-order reaction with respect to A.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 64, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "PMC 2020 Q#64 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2020"}, {"id": "paper_q65_65", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 65, "subject": "Chemistry", "topic": "negative order reactions", "question": "For which of the following order of the reaction, rate of reaction in inversely proportional to the concentration reaction?", "options": ["1st order reaction", "2nd order reaction", "Negative order of reaction", "Zero order of reaction"], "correctIndex": 2, "explanation": "In a negative-order reaction, the rate decreases as reactant concentration increases; thus the rate is inversely proportional to concentration for negative orders.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 65, "syllabusUnit": "Unit 6: Reaction Kinetics", "pmdcTopic": "Reaction Rates, Rate Equations & Catalysis", "textbookCitation": "PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9", "citationString": "PMC 2020 Q#65 | Unit 6: Reaction Kinetics | PTB Chemistry XI Ch 11 (Reaction Kinetics); Federal Chemistry XI Ch 9"}, "year": "2020"}, {"id": "paper_q66_66", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 66, "subject": "Chemistry", "topic": "enthalpy definition", "question": "The thermal energy at constant pressure is called:", "options": ["Enthalpy", "Internal energy", "Heat capacity", "Work done"], "correctIndex": 0, "explanation": "Enthalpy (H) is the thermodynamic quantity representing the heat content at constant pressure; it accounts for internal energy plus the pressure–volume work term.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 66, "syllabusUnit": "Unit 4: Chemical Energetics", "pmdcTopic": "Enthalpy Changes, Hess's Law & Standard Heats of Reaction", "textbookCitation": "PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6", "citationString": "PMC 2020 Q#66 | Unit 4: Chemical Energetics | PTB Chemistry XI Ch 7 (Thermochemistry); Federal Chemistry XI Ch 6"}, "year": "2020"}, {"id": "paper_q67_67", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 67, "subject": "Chemistry", "topic": "lattice energies", "question": "Born-Haber cycle is used to determine the lattice energies of:", "options": ["Molecular solids", "Metallic solids", "Ionic solids", "Covalent solids"], "correctIndex": 2, "explanation": "The Born–Haber cycle is a thermochemical cycle used to evaluate lattice energies of ionic solids by relating formation enthalpies and ionization/atomization steps, so ionic solids are the target.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 67, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "PMC 2020 Q#67 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2020"}, {"id": "paper_q68_68", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 68, "subject": "Chemistry", "topic": "thiosulfate oxidation state", "question": "The oxidation state of ‘S’ in the (S2O3)\n-2\nis:", "options": ["+4", "+6", "-2", "+2"], "correctIndex": 3, "explanation": "In thiosulfate S2O3^2− the average oxidation state of the two sulfur atoms is +2 (total for two S atoms is +4). The two sulfurs are not equivalent (one is more oxidized and one is reduced), but the average value is +2.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 68, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "PMC 2020 Q#68 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2020"}, {"id": "paper_q69_69", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 69, "subject": "Chemistry", "topic": "halogen oxidation numbers", "question": "The common oxidation number of halogens is:", "options": ["-1", "+1", "-2", "0"], "correctIndex": 0, "explanation": "Halogens typically exhibit a −1 oxidation state in many compounds (e.g., Cl−, Br−, I−) when bonded to elements less electronegative than themselves.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 69, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "PMC 2020 Q#69 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2020"}, {"id": "paper_q70_70", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 70, "subject": "Chemistry", "topic": "oxidation number change", "question": "During oxidation process, oxidation number of an element:", "options": ["Decreases", "Increases", "Remains constant", "Both A&B"], "correctIndex": 1, "explanation": "Oxidation involves loss of electrons and corresponds to an increase in the oxidation number of the element; reduction is the opposite (decrease).", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 70, "syllabusUnit": "Unit 7: Electrochemistry", "pmdcTopic": "Electrochemical Cells, Electrode Potentials & Nernst Concepts", "textbookCitation": "PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10", "citationString": "PMC 2020 Q#70 | Unit 7: Electrochemistry | PTB Chemistry XI Ch 10 (Electrochemistry); Federal Chemistry XI Ch 10"}, "year": "2020"}, {"id": "paper_q71_71", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 71, "subject": "Chemistry", "topic": "electronegativity", "question": "Which of the following has the height value of electronegativity?", "options": ["1", "Br", "Cl", "F"], "correctIndex": 3, "explanation": "Fluorine has the highest electronegativity of all elements (Pauling scale), so F is the correct choice.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 71, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "PMC 2020 Q#71 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2020"}, {"id": "paper_q72_72", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 72, "subject": "Chemistry", "topic": "s character", "question": "Which of the following hybrid orbitals has maximum ‘S’ –character?>", "options": ["Sp3 – hybrid orbital", "Sp2 – hybrid orbital", "Sp – hybrid orbital", "Dsp2 – hybrid orbital"], "correctIndex": 2, "explanation": "An sp hybrid orbital has 50% s-character (the highest among the listed hybrids); sp2 has 33% and sp3 has 25% s-character, so sp is the maximum.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 72, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "PMC 2020 Q#72 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2020"}, {"id": "paper_q73_73", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 73, "subject": "Chemistry", "topic": "first ionization energy", "question": "The first ionization energy is maximum for:", "options": ["Na", "Mg", "Al", "K"], "correctIndex": 1, "explanation": "Among the given elements, magnesium has the highest first ionization energy (it requires more energy to remove the first electron) compared with sodium, aluminum and potassium.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 73, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "PMC 2020 Q#73 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2020"}, {"id": "paper_q74_74", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 74, "subject": "Chemistry", "topic": "percent yield", "question": "The efficiency of chemical reaction cay be expressed as:", "options": ["Theoretical yield", "Actual yield", "%yield", "Maximum yield"], "correctIndex": 2, "explanation": "Reaction efficiency is commonly expressed as percent yield (% yield) which compares actual (experimental) yield to theoretical maximum yield and expresses the ratio as a percentage.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 74, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "PMC 2020 Q#74 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2020"}, {"id": "paper_q75_75", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 75, "subject": "Chemistry", "topic": "moles and atoms", "question": "In a vessel, 10g N2, 10g H and 10g O2 are present. Which one will have least number of atoms?", "options": ["H2", "N2", "O2", "Both H2 & N2"], "correctIndex": 2, "explanation": "Converting to moles: 10 g N2 = 10/28 ≈ 0.357 mol (atoms ≈0.714 mol), 10 g H2 = 10/2 = 5 mol (atoms =10 mol), 10 g O2 = 10/32 ≈0.3125 mol (atoms ≈0.625 mol). Thus O2 contributes the least number of atoms.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 75, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "PMC 2020 Q#75 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2020"}, {"id": "paper_q76_76", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 76, "subject": "Chemistry", "topic": "glucose", "question": "The empirical formula of Glucose C6H12O6 is:", "options": ["C6H12O16", "CHO", "CH2O", "CH2O2"], "correctIndex": 2, "explanation": "Glucose (C6H12O6) reduces to the simplest whole-number ratio CH2O (divide subscripts by 6), so CH2O is the empirical formula.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 76, "syllabusUnit": "Unit 3: Chemical Bonding", "pmdcTopic": "VSEPR Theory, Orbital Hybridization & Bond Polarity", "textbookCitation": "PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5", "citationString": "PMC 2020 Q#76 | Unit 3: Chemical Bonding | PTB Chemistry XI Ch 6 (Chemical Bonding); Federal Chemistry XI Ch 5"}, "year": "2020"}, {"id": "paper_q77_77", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 77, "subject": "Chemistry", "topic": "relation n and l", "question": "The relationship between quantum number n and I is:", "options": ["N = 1-1", "I = n-2", "I = n-1", "N = 1-2"], "correctIndex": 2, "explanation": "The azimuthal quantum number l (here shown as I) ranges from 0 to n−1 for a given principal quantum number n, so l = n−1 is the maximum allowed value; the relationship in option (c) is the standard one.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 77, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "PMC 2020 Q#77 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2020"}, {"id": "paper_q78_78", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 78, "subject": "Chemistry", "topic": "2p quantum numbers", "question": "Quantum number values for ‘2p’ orbitals are:", "options": ["N=2, I=1", "N=1, I=2", "N=1, I=0", "N=2, I=0"], "correctIndex": 0, "explanation": "For 2p orbitals the principal quantum number n = 2 and the azimuthal quantum number l = 1 (p-orbital), so option (a) is correct.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 78, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "PMC 2020 Q#78 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2020"}, {"id": "paper_q79_79", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 79, "subject": "Chemistry", "topic": "s orbital electron count", "question": "Which pair has 1 electron in it’s ‘s’ orbital?", "options": ["Li, Fe", "Na & Cr", "K &Mn", "H & He"], "correctIndex": 1, "explanation": "Sodium (Na) has one valence s-electron (3s1) and chromium (Cr) has a 4s1 configuration (anomalous configuration), so both have one electron in an s orbital, making option (b) correct.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 79, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "PMC 2020 Q#79 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2020"}, {"id": "paper_q80_80", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 80, "subject": "Chemistry", "topic": "density dependence", "question": "According to the general gas equation density of an ideal gas depends upon:", "options": ["Pressure", "Temperature", "Molar mass of the gas", "All of the above"], "correctIndex": 3, "explanation": "From the ideal gas law (ρ = PM/RT), gas density depends on pressure (P), temperature (T) and molar mass (M), so all three factors affect density.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 80, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "PMC 2020 Q#80 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2020"}, {"id": "paper_q81_81", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 81, "subject": "Chemistry", "topic": "polarity and vaporization", "question": "CO2 and SO2 both are tri-atomic molecules but heat of vaporization of SO2 is greater than that of CO2 due to:", "options": ["High electronegativity of S", "Greater size of SO2", "SO2 is polar and CO2 is non-polar", "SO2 is more acidic than CO2"], "correctIndex": 2, "explanation": "SO2 is a polar molecule (bent geometry) and exhibits stronger intermolecular attractions (dipole–dipole) than linear, nonpolar CO2; stronger intermolecular forces lead to higher heat of vaporization for SO2.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 81, "syllabusUnit": "Unit 1: Atomic Structure", "pmdcTopic": "Quantum Numbers, Electronic Configuration & Spectral Lines", "textbookCitation": "PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2", "citationString": "PMC 2020 Q#81 | Unit 1: Atomic Structure | PTB Chemistry XI Ch 5 (Atomic Structure); Federal Chemistry XI Ch 2"}, "year": "2020"}, {"id": "paper_q82_82", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 82, "subject": "Chemistry", "topic": "relative vapour pressures", "question": "Which of the following has the lowest vapour pressure at 20oC?", "options": ["Diethyl ether", "Chloroform", "Carbon tetrachloride", "Water"], "correctIndex": 3, "explanation": "At 20°C water has a much lower vapor pressure than volatile organic solvents like diethyl ether, chloroform or carbon tetrachloride, so water exhibits the lowest vapor pressure among the choices.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 82, "syllabusUnit": "Unit: Fundamental Concepts of Chemistry", "pmdcTopic": "Stoichiometry & Chemical Principles", "textbookCitation": "PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus", "citationString": "PMC 2020 Q#82 | Unit: Fundamental Concepts of Chemistry | PTB Chemistry XI/XII; PMDC MDCAT Chemistry Syllabus"}, "year": "2020"}, {"id": "paper_q83_83", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 83, "subject": "Chemistry", "topic": "lattice energy nomenclature", "question": "The lattice energy is also called as:", "options": ["Enegy of affinity", "Bond energy", "Crystal energy", "Potential energy"], "correctIndex": 2, "explanation": "Lattice energy is often referred to as crystal energy (the energy released when gaseous ions combine to form an ionic solid), so 'crystal energy' is the corresponding term.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 83, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "PMC 2020 Q#83 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2020"}, {"id": "paper_q84_84", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 84, "subject": "Chemistry", "topic": "kp and kc relation", "question": "For a gaseous phase reaction, when number of moles of reactants and products are equal:", "options": ["The values of Kp and Kc are different", "The values of Kp is greater than Kc", "The values of Kc is greater than Kp", "The values of Kp and KC are the same"], "correctIndex": 3, "explanation": "When Δn (difference in moles of gaseous products and reactants) is zero, Kp = Kc because the (RT)^{Δn} factor equals 1; thus the equilibrium constants have the same numerical value.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 84, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "PMC 2020 Q#84 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2020"}, {"id": "paper_q85_85", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 85, "subject": "Chemistry", "topic": "common ion effect example", "question": "Purification of table salt (NaCl) by passing HCI gas through its saturated aqueous solution is an example of:", "options": ["Lawa of mass action", "Hess’s law", "Common ion effect", "Henry’s law"], "correctIndex": 2, "explanation": "Introducing HCl (which supplies the common ion Cl−) shifts equilibria and reduces the solubility of NaCl (common-ion effect), leading to precipitation/purification of the salt.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 85, "syllabusUnit": "Unit 2: States of Matter", "pmdcTopic": "Gas Laws, Intermolecular Forces & Solid Crystal Structures", "textbookCitation": "PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4", "citationString": "PMC 2020 Q#85 | Unit 2: States of Matter | PTB Chemistry XI Ch 3 (Gases) & Ch 4 (Liquids & Solids); Federal Chemistry XI Ch 3-4"}, "year": "2020"}, {"id": "paper_q86_86", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 86, "subject": "English", "topic": "prepositions and preference", "question": "We prefer fruits_____ sweets", "options": ["To", "On", "Over", "From"], "correctIndex": 0, "explanation": "The verb 'prefer' is followed by 'to' when comparing two alternatives: 'prefer X to Y'. The other prepositions ('on', 'over', 'from') are not used in this comparative structure.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 86, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "PMC 2020 Q#86 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2020"}, {"id": "paper_q87_87", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 87, "subject": "English", "topic": "spelling", "question": "Choose the correct spelling", "options": ["Exantuated", "Axantuated", "Accenchuated", "Accentuated"], "correctIndex": 3, "explanation": "'Accentuated' is the correct spelling. The other options are misspellings that deviate from the standard form.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 87, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "PMC 2020 Q#87 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2020"}, {"id": "paper_q88_88", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 88, "subject": "English", "topic": "spelling", "question": "Choose the correct spelling", "options": ["Cotioned", "Cautioned", "Causchuned", "Coschuned"], "correctIndex": 1, "explanation": "'Cautioned' is the correct English spelling meaning 'warned'. The other choices are incorrect spellings.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 88, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "PMC 2020 Q#88 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2020"}, {"id": "paper_q89_89", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 89, "subject": "English", "topic": "verb forms", "question": "The Headmaster____ to speed to you", "options": ["Wants", "Is wanting", "Was wanting", "Want"], "correctIndex": 0, "explanation": "Present simple 'wants' is the normal choice for a stative verb (the Headmaster wants to speak). 'Is wanting' and 'was wanting' are non-standard here, and 'want' (base form) is ungrammatical without an auxiliary.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 89, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "PMC 2020 Q#89 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2020"}, {"id": "paper_q90_90", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 90, "subject": "English", "topic": "subject verb agreement", "question": "Choose the correct option:\nKnowledge and wisdom____ no time for connection", "options": ["Has", "Have", "Had", "Are"], "correctIndex": 1, "explanation": "With two nouns joined by 'and' the verb is plural, so 'have' is correct. 'Has' would be singular, and 'had'/ 'are' do not fit the present-tense sense of the sentence.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 90, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "PMC 2020 Q#90 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2020"}, {"id": "paper_q91_91", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 91, "subject": "English", "topic": "formal letters", "question": "Identify the erros and choose the correct option:\nI hope this letters finds in the best of your spirits", "options": ["I hope this letter will find you in good of high spirits", "I hope this letter finds you in best of your spirit", "I hope letter finds you in the best of spirits", "I hope the letter found you in greatest of spirite"], "correctIndex": 2, "explanation": "Option 3 (as printed) is the closest to the standard polite letter opening. The ideal sentence would be 'I hope this letter finds you in the best of spirits.' The other choices contain more serious grammatical or lexical errors.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 91, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "PMC 2020 Q#91 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2020"}, {"id": "paper_q92_92", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 92, "subject": "English", "topic": "articles", "question": "Fill in the blank with appropriate article as required. ___ Umbrella is of no avail \nagainst a thunderstorm", "options": ["The", "A", "An", "No article required"], "correctIndex": 2, "explanation": "When referring to an umbrella as a singular countable noun in general sense, 'An umbrella is of no avail against a thunderstorm' is correct. 'A' before a vowel sound would be incorrect; 'the' or no article do not convey the intended general meaning.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 92, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "PMC 2020 Q#92 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2020"}, {"id": "paper_q93_93", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 93, "subject": "English", "topic": "subjunctive and wishes", "question": "Choose the correct sentence", "options": ["I wish I have been a millionare", "I wish I am beaing a millionaire", "I wish I were a millionaire", "I wish I was millionaire"], "correctIndex": 2, "explanation": "The subjunctive form 'I wish I were a millionaire' is the standard grammatical construction expressing an unreal present situation. The other options are grammatically incorrect or misspelled.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 93, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "PMC 2020 Q#93 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2020"}, {"id": "paper_q94_94", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 94, "subject": "English", "topic": "comparisons", "question": "Pick the correct option", "options": ["No start is brighter than the moon", "No star is more bright than the moon", "No start is brighter then the moon", "No star is brighter than moon"], "correctIndex": 3, "explanation": "Option 4 most closely matches the standard comparative structure 'No star is brighter than [the] moon' (the printed option omits 'the'). Other choices contain spelling ('start') or grammatical ('then' instead of 'than') errors or less idiomatic phrasing.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 94, "syllabusUnit": "Comprehension & Language Skills", "pmdcTopic": "English Language Proficiency & Error Identification", "textbookCitation": "PMDC MDCAT English Curriculum", "citationString": "PMC 2020 Q#94 | Comprehension & Language Skills | PMDC MDCAT English Curriculum"}, "year": "2020"}, {"id": "paper_q95_95", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 95, "subject": "English", "topic": "conditional sentences", "question": "Choose the correctly structured sentence.", "options": ["Had he lived in England he would miss his family", "Had he lived in England, he would have missed his family", "Had he lives in England he had missed his family", "Had he live in England he will missed his family"], "correctIndex": 1, "explanation": "Option 2 is the correct third conditional (past unreal): 'Had he lived..., he would have missed...' The other options contain incorrect verb forms or tenses.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 95, "syllabusUnit": "Sentence Structure & Error Detection", "pmdcTopic": "Sentence Correction, Modifiers and Parallelism", "textbookCitation": "PMDC MDCAT English Guidelines (Sentence Structure & Syntax)", "citationString": "PMC 2020 Q#95 | Sentence Structure & Error Detection | PMDC MDCAT English Guidelines (Sentence Structure & Syntax)"}, "year": "2020"}, {"id": "paper_q96_96", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 96, "subject": "English", "topic": "tense identification", "question": "She always carried un umbrella. The sentence indicates___tense.", "options": ["Present tense", "Past simple", "Past perfect", "Present perfect"], "correctIndex": 1, "explanation": "The verb 'carried' is past simple, so the sentence indicates past simple tense. (Note: 'un' in the printed stem is a typographical error for 'an'.)", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 96, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "PMC 2020 Q#96 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2020"}, {"id": "paper_q97_97", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 97, "subject": "English", "topic": "perfect tenses", "question": "Ahmed____ me for a long time", "options": ["Know", "Have known", "Knows", "Knew"], "correctIndex": 1, "explanation": "The present perfect is correct for an action continuing up to the present: 'Ahmed has known me for a long time.' Among the given choices, 'have known' (printed) is the closest representation of that tense (assuming 'has' intended with 'Ahmed').", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 97, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "PMC 2020 Q#97 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2020"}, {"id": "paper_q98_98", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 98, "subject": "English", "topic": "subject verb agreement", "question": "Choose the correct option:", "options": ["He and I was playing", "He and I were playing", "He and I were being playing", "He and I was being playing"], "correctIndex": 1, "explanation": "With a compound subject 'He and I' the correct past tense plural is 'were playing.' The other choices use incorrect auxiliary forms.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 98, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "PMC 2020 Q#98 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2020"}, {"id": "paper_q99_99", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 99, "subject": "English", "topic": "subject verb agreement", "question": "Choose the correct option:", "options": ["Every one of the prisons are full", "Every one of the prisons had full", "Every one of the prisons have full", "Every one of the prisons is full"], "correctIndex": 3, "explanation": "'Every one of the prisons' is treated as singular, so the verb should be singular: 'is full.' The other options have incorrect verb forms or tense.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 99, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "PMC 2020 Q#99 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2020"}, {"id": "paper_q100_100", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 100, "subject": "English", "topic": "subject verb agreement and passive", "question": "Not only the parents but also their son ___ for interview", "options": ["Has called", "Have called", "Have been called", "Has been called"], "correctIndex": 3, "explanation": "With 'not only... but also' the verb agrees with the nearer subject ('son'), so a singular passive 'has been called' is appropriate. The other options either use wrong number agreement or wrong voice.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 100, "syllabusUnit": "Grammatical Rules & Mechanics", "pmdcTopic": "Subject-Verb Agreement, Prepositions and Tense Consistency", "textbookCitation": "Standard High School English Grammar (Wren & Martin / Federal English)", "citationString": "PMC 2020 Q#100 | Grammatical Rules & Mechanics | Standard High School English Grammar (Wren & Martin / Federal English)"}, "year": "2020"}, {"id": "paper_q101_101", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 101, "subject": "Biology", "topic": "temperature regulation", "question": "When the temperature of the body surrounding rises, baby responds by", "options": ["Vasoconstriction", "Vasodilation", "Shivering", "Raising body hairs"], "correctIndex": 1, "explanation": "When the surrounding temperature rises, vasodilation increases blood flow to the skin to promote heat loss. Vasoconstriction and shivering generate or conserve heat, so they occur when it's cold.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 101, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#101 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q102_102", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 102, "subject": "Biology", "topic": "urine concentration", "question": "The excretion of hypertonic urine in humans is associated best with the", "options": ["Glomerular capsule", "Proximal convoluted tubule", "Loop of henle", "Distal convoluted tubule"], "correctIndex": 2, "explanation": "The loop of Henle establishes the medullary osmotic gradient that enables the kidney to produce hypertonic (concentrated) urine. Other segments have different roles (filtration, reabsorption).", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 102, "syllabusUnit": "Unit 9: Homeostasis & Excretion", "pmdcTopic": "Osmoregulation, Excretory System & Kidney Hormones", "textbookCitation": "PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1", "citationString": "PMC 2020 Q#102 | Unit 9: Homeostasis & Excretion | PTB Biology XII Ch 15 (Homeostasis); Federal / Sindh Biology XII Ch 1"}, "year": "2020"}, {"id": "paper_q103_103", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 103, "subject": "Biology", "topic": "thermoregulation", "question": "In humans, the temperature regulation control conter is located in", "options": ["Kidneys", "Brain", "Lungs", "Liver"], "correctIndex": 1, "explanation": "The hypothalamus in the brain is the central control for body temperature regulation. The kidneys, lungs and liver are not the primary temperature control centers.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 103, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#103 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q104_104", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 104, "subject": "Biology", "topic": "liver functions", "question": "As an excretory organ, liver", "options": ["Detoxifies many chemical poisions", "Produces ammonia for excretion by the kidneys", "Produces uring and uric nitrogen of amino acids", "All of the above"], "correctIndex": 3, "explanation": "The liver detoxifies chemicals and converts nitrogenous wastes (ammonia) into forms like urea for excretion by kidneys; thus all listed functions are associated with hepatic excretory/metabolic roles.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 104, "syllabusUnit": "Unit 5: Human Physiology - Digestion & Nutrition", "pmdcTopic": "Human Digestive System & Absorption Mechanisms", "textbookCitation": "PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12", "citationString": "PMC 2020 Q#104 | Unit 5: Human Physiology - Digestion & Nutrition | PTB Biology XI Ch 12 (Nutrition); Federal / Sindh Biology XI Ch 12"}, "year": "2020"}, {"id": "paper_q105_105", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 105, "subject": "Biology", "topic": "hormonal control of sodium", "question": "The active uptake of sodium in the ascending limb or thick loop of henle is \npromoted by the action of", "options": ["Aldosterone", "Thyroxine", "ADH", "Cortisone"], "correctIndex": 0, "explanation": "Aldosterone increases sodium reabsorption in nephron segments, promoting active Na+ uptake. ADH primarily affects water permeability, while thyroxine and cortisone do not directly mediate this process.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 105, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#105 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q106_106", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 106, "subject": "Biology", "topic": "muscle types", "question": "Which of the following muscles are considered as ‘Voluntary Muscles’?", "options": ["Smooth muscles", "Crdiac muscles", "Skeletal muscles", "Glandular muscles"], "correctIndex": 2, "explanation": "Skeletal muscles are under conscious (voluntary) control. Smooth and cardiac muscles are involuntary, and 'glandular muscles' is not a standard muscle classification.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 106, "syllabusUnit": "Unit 11: Support and Movement", "pmdcTopic": "Skeletal System, Sliding Filament Model & Muscle Physiology", "textbookCitation": "PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2", "citationString": "PMC 2020 Q#106 | Unit 11: Support and Movement | PTB Biology XII Ch 16 (Support & Movement); Federal Biology XII Ch 2"}, "year": "2020"}, {"id": "paper_q107_107", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 107, "subject": "Biology", "topic": "cardiac muscle", "question": "Which one of the following ‘myoenic’ types of muscle?", "options": ["Glandular muscles", "Cardiac muscles", "Skeletal muscles", "Smooth muscles"], "correctIndex": 1, "explanation": "'Myoenic' refers to muscle that can generate its own rhythm (myogenic). Cardiac muscle is myogenic, as the heart's pacemaker cells initiate contractions without external nerve stimulation.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 107, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "PMC 2020 Q#107 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2020"}, {"id": "paper_q108_108", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 108, "subject": "Biology", "topic": "muscle fiber terminology", "question": "What do we call the cell surface membrane of a muscle fiber?", "options": ["Sarcolemma", "Plasma membrane", "Sarcoplasm", "Myofibrils"], "correctIndex": 0, "explanation": "The sarcolemma is the specialized cell membrane of a muscle fiber. 'Sarcoplasm' is the cytoplasm, and 'myofibrils' are contractile elements inside the cell.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 108, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "PMC 2020 Q#108 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2020"}, {"id": "paper_q109_109", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 109, "subject": "Biology", "topic": "neurotransmitters", "question": "Which of the following neurotransmitters function, both as \nneurotransmitter and hormones, decreasing our perception of pain?", "options": ["Epinephrine", "Serotonin", "Dopamine", "Endorphins"], "correctIndex": 3, "explanation": "Endorphins act as neurotransmitters and neurohormones and are natural analgesics that reduce pain perception. The other listed substances have different primary roles.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 109, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "PMC 2020 Q#109 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2020"}, {"id": "paper_q110_110", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 110, "subject": "Biology", "topic": "feedback mechanisms", "question": "Which body function is controlled through positive feedback mechanism?", "options": ["Labor contractions", "Body temperature", "Insuliln production", "Thyroxin release"], "correctIndex": 0, "explanation": "Labor contractions are amplified by positive feedback (oxytocin increases contractions that cause more oxytocin release). Body temperature and hormone releases are typically regulated by negative feedback.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 110, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#110 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q111_111", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 111, "subject": "Biology", "topic": "neuron structure", "question": "Which of the following is common to all neurons?", "options": ["A cell which contains a nucleus", "A thick myelin heath", "Presence of node of Ranvier", "Presence of Schwann cells"], "correctIndex": 0, "explanation": "All neurons are cells that contain a nucleus. Not all neurons have myelin, nodes of Ranvier, or Schwann cells (those are specific to myelinated peripheral neurons).", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 111, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "PMC 2020 Q#111 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2020"}, {"id": "paper_q112_112", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 112, "subject": "Biology", "topic": "neuron structure", "question": "Neurons are cells adopted for the rapid transmission of electrical impulses. \nTo do this, they have long thin process called:", "options": ["Axons", "Dendrited", "Myelin sheath", "Schwann cells"], "correctIndex": 0, "explanation": "Axons are the long thin processes that transmit electrical impulses away from the neuron's cell body. Dendrites receive signals; myelin sheath and Schwann cells are supporting structures.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 112, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "PMC 2020 Q#112 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2020"}, {"id": "paper_q113_113", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 113, "subject": "Biology", "topic": "synapse", "question": "___ is a junction between two neurons or between a motor neuron and a \nmuscle cell", "options": ["Impulse", "Synapse", "Axon", "Cleft"], "correctIndex": 1, "explanation": "A synapse is the junction where a nerve impulse is transmitted from one neuron to another or from a neuron to an effector cell. 'Cleft' refers to the synaptic cleft but is not the junction term itself.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 113, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "PMC 2020 Q#113 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2020"}, {"id": "paper_q114_114", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 114, "subject": "Biology", "topic": "menstrual cycle", "question": "Which of the following represents the changes that occur in the ovary and \nthe uterus approximately every 28 days involving evolution with the breakdown \nand loss of the linning of the uterus", "options": ["Ovulation", "Menstrual cycle", "Uterine cycle", "Embryo formation"], "correctIndex": 1, "explanation": "The menstrual cycle broadly describes the recurring ovarian and uterine changes, including the breakdown and loss of the uterine lining. The uterine cycle refers specifically to uterine changes, but 'menstrual cycle' is the common term covering both ovarian and uterine events.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 114, "syllabusUnit": "Unit 12: Reproduction and Development", "pmdcTopic": "Human Reproductive System & Gametogenesis", "textbookCitation": "PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)", "citationString": "PMC 2020 Q#114 | Unit 12: Reproduction and Development | PTB Biology XII Ch 18 (Reproduction) & Ch 19 (Growth & Development)"}, "year": "2020"}, {"id": "paper_q115_115", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 115, "subject": "Biology", "topic": "sexually transmitted infections", "question": "Which of the following disease is sexually transmitted?", "options": ["Tuberculosis", "AIDs", "Dengue fever", "Cholera"], "correctIndex": 1, "explanation": "AIDS (caused by HIV) is transmitted sexually among other routes. Tuberculosis, dengue and cholera are not primarily sexually transmitted diseases.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 115, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#115 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q116_116", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 116, "subject": "Biology", "topic": "pituitary hormones", "question": "Which of the following hormones of the pituitary gland regulate the \nmenstrual cycle?", "options": ["Follicle stimulating bormone and estrogen", "Luteinizing hormone and estrogen", "Follicle stimumating hormone and luteinizing hormone", "Estrogen and progesterone"], "correctIndex": 2, "explanation": "The pituitary hormones FSH and LH (option 3 as printed) regulate ovarian function and the menstrual cycle. Estrogen and progesterone are ovarian hormones, not pituitary hormones.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 116, "syllabusUnit": "Unit 10: Nervous & Chemical Coordination", "pmdcTopic": "Nervous System, Neurotransmitters & Endocrine Glands", "textbookCitation": "PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3", "citationString": "PMC 2020 Q#116 | Unit 10: Nervous & Chemical Coordination | PTB Biology XII Ch 17 (Nervous & Chemical Coordination); Federal Biology XII Ch 3"}, "year": "2020"}, {"id": "paper_q117_117", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 117, "subject": "Biology", "topic": "sex linked inheritance", "question": "Which traits ar most likely to affect men than women?", "options": ["X linked recessive", "X linked dominant", "Autosomal dominant", "Autosomal recessive"], "correctIndex": 0, "explanation": "X-linked recessive traits affect males more often because males have a single X chromosome, so a single recessive allele on that X will produce the phenotype. Autosomal traits affect sexes more equally.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 117, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "PMC 2020 Q#117 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2020"}, {"id": "paper_q118_118", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 118, "subject": "Biology", "topic": "modes of inheritance", "question": "Alleles both have an effect on the phenotype heterozygotic organism", "options": ["Dominant", "Recessive", "Multiple", "Co-dominant"], "correctIndex": 3, "explanation": "Co-dominance is when both alleles in a heterozygote are expressed and both affect the phenotype. Dominant/recessive refers to one allele masking another.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 118, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "PMC 2020 Q#118 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2020"}, {"id": "paper_q119_119", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 119, "subject": "Biology", "topic": "homozygosity and heterozygosity", "question": "When both the allele of a genes are same, the organism is said to be:", "options": ["Heterozygous", "Genotype", "Homozygous", "Phenotype"], "correctIndex": 2, "explanation": "An organism with two identical alleles for a gene is homozygous. Heterozygous means the alleles differ; genotype/phenotype are different concepts.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 119, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "PMC 2020 Q#119 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2020"}, {"id": "paper_q120_120", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 120, "subject": "Biology", "topic": "cell wall presence", "question": "In which type of cell. Cell wall is not present?", "options": ["Plant cells", "Fungal cells", "Bacterial cells", "Liver cells"], "correctIndex": 3, "explanation": "Liver cells are animal cells which lack a cell wall. Plant, fungal and many bacterial cells have cell walls (though composition differs).", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 120, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "PMC 2020 Q#120 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2020"}, {"id": "paper_q121_121", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 121, "subject": "Biology", "topic": "ribosome size", "question": "70S size ribosomes are found in the cells of", "options": ["Algae", "Protozoans", "Fungi", "Bacteria"], "correctIndex": 3, "explanation": "70S ribosomes are characteristic of prokaryotes such as bacteria. Eukaryotic cells (algae, protozoa, fungi) have 80S ribosomes in the cytoplasm.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 121, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "PMC 2020 Q#121 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2020"}, {"id": "paper_q122_122", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 122, "subject": "Biology", "topic": "fluid mosaic model", "question": "According to the fluid mosaic model of cell membrane, which zone is \nembedded inside?", "options": ["Hydrophobic", "Globular", "Hydrophilic", "Filamentous"], "correctIndex": 0, "explanation": "The interior of the lipid bilayer is hydrophobic (fatty-acid tails), and membrane proteins are embedded in this hydrophobic zone. Hydrophilic regions face aqueous environments.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 122, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "PMC 2020 Q#122 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2020"}, {"id": "paper_q123_123", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 123, "subject": "Biology", "topic": "tonoplast", "question": "The membrane separating the vacuole from cytoplasm is called", "options": ["Cristae", "Cisternae", "Tonoplast", "Vacuolar membrane"], "correctIndex": 2, "explanation": "The membrane surrounding the vacuole is called the tonoplast. 'Vacuolar membrane' is a synonym, but 'tonoplast' is the standard term; cristae and cisternae refer to mitochondria and Golgi/ER structures respectively.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 123, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "PMC 2020 Q#123 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2020"}, {"id": "paper_q124_124", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 124, "subject": "Biology", "topic": "smooth er functions", "question": "Select the one which is not a function of smooth endoplasmic retidulum \n(SER)?", "options": ["Metabolism of lipids", "Transmission of impulses", "Transport of materails", "Processing og glycoproteins"], "correctIndex": 1, "explanation": "The SER is involved in lipid metabolism and transport, and the RER (not SER) is more involved in processing glycoproteins. 'Transmission of impulses' is not a function of the SER.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 124, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "PMC 2020 Q#124 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2020"}, {"id": "paper_q125_125", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 125, "subject": "Biology", "topic": "cell wall synthesis", "question": "Which of the following organelles are involves in the synthesis of plant cell \nwall?", "options": ["Endoplasmic reticulum", "Golgi complex", "Lysosomes", "Peroxisomes"], "correctIndex": 1, "explanation": "The Golgi apparatus synthesizes and secretes polysaccharides and cell-wall components in plant cells. ER supplies materials but the Golgi packages and directs cell wall constituents.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 125, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "PMC 2020 Q#125 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2020"}, {"id": "paper_q126_126", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 126, "subject": "Biology", "topic": "membrane integrity", "question": "Which property of water helps to maintain the integrity of cell \nmembrances?", "options": ["Specific heat capacity", "Hydrogen bonding", "Cohesion and adhesion", "Hydrophobic exclusion"], "correctIndex": 3, "explanation": "Hydrophobic exclusion (the hydrophobic effect) drives the formation and stability of lipid bilayers, maintaining membrane integrity. While hydrogen bonding and cohesion are important for other water properties, the hydrophobic effect is central to membrane structure.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 126, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "PMC 2020 Q#126 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2020"}, {"id": "paper_q127_127", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 127, "subject": "Biology", "topic": "solvent properties", "question": "Water act as universal solvent because of", "options": ["Heat of vaporization", "Hydrogen bonding", "High polarity", "Cohesion and adhesion"], "correctIndex": 2, "explanation": "Water's polarity allows it to surround and dissolve many ionic and polar substances, making it a versatile solvent. Hydrogen bonding contributes but polarity is the fundamental reason.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 127, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#127 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q128_128", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 128, "subject": "Biology", "topic": "energy content", "question": "Lipids store double amount of energy as compared to carbohydrtes \nbecause of", "options": ["High proportion of oxygen", "High C-O ratio", "Low proportion of carbon", "High proportion of C-H"], "correctIndex": 3, "explanation": "Lipids have many C–H bonds, which are energy-rich; oxidation of these bonds releases more energy than oxidation of carbohydrates, which have a higher oxygen content.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 128, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "PMC 2020 Q#128 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2020"}, {"id": "paper_q129_129", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 129, "subject": "Biology", "topic": "fatty acids", "question": "Which of the following is an unsaturated fatty acid?", "options": ["Oleic acid", "Palmitic acid", "Butyric acid", "Acetic acid"], "correctIndex": 0, "explanation": "Oleic acid is a monounsaturated fatty acid (contains a C=C double bond). Palmitic and butyric acids are saturated, and acetic acid is a short-chain carboxylic acid, not an unsaturated fatty acid.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 129, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#129 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q130_130", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 130, "subject": "Biology", "topic": "nad", "question": "NAD is an example of", "options": ["Mononucleotide", "Dinucleotide", "Tri nucleotide", "Tetra cucleotide"], "correctIndex": 1, "explanation": "NAD (nicotinamide adenine dinucleotide) consists of two nucleotides joined together, so it is a dinucleotide. The other choices (mono/tri/tetra) do not describe NAD's two-nucleotide structure.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 130, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#130 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q131_131", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 131, "subject": "Biology", "topic": "enzyme conditions", "question": "Most enzymes have and optimum temperature of around", "options": ["30oC", "40oC", "50oC", "20oC"], "correctIndex": 1, "explanation": "Most enzymes in warm-blooded organisms have an optimum near normal body temperature (~37°C), so option 40°C (noting the parenthetical) is the closest. Much lower or higher temperatures reduce enzyme activity or denature the protein.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 131, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "PMC 2020 Q#131 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2020"}, {"id": "paper_q132_132", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 132, "subject": "Biology", "topic": "enzyme catalysis", "question": "Enzymes work by lowering the ___ of the reactions that catalyze", "options": ["Kinetic energy", "Activation energy", "Heat energy", "Potential energy"], "correctIndex": 1, "explanation": "Enzymes catalyze reactions by lowering the activation energy barrier, making reactions proceed faster. They do not change kinetic, heat, or potential energy in the way implied by the other options.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 132, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "PMC 2020 Q#132 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2020"}, {"id": "paper_q133_133", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 133, "subject": "Biology", "topic": "calvin cycle", "question": "First stable compound during calvin cycle is", "options": ["3-phosphoglycerate", "Glyceraldehyde 3-phosphatse", "1,3 bisphosphoglyceratae", "Ribulose biphosphate"], "correctIndex": 0, "explanation": "In the Calvin cycle, the first stable product after CO2 fixation by Rubisco is 3-phosphoglycerate (3-PGA). Ribulose bisphosphate is the CO2 acceptor, not the first stable product; the other named compounds are later intermediates or misspellings.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 133, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "PMC 2020 Q#133 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2020"}, {"id": "paper_q134_134", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 134, "subject": "Biology", "topic": "ribulose", "question": "What is the function of ribulose?", "options": ["Intermediate in photosynthesis", "Respirator fuel", "Intermediate in cellular respiration", "Component of DNA and RNA"], "correctIndex": 0, "explanation": "Ribulose (e.g., ribulose-1,5-bisphosphate) acts as an intermediate and CO2 acceptor in the Calvin cycle of photosynthesis. It is not primarily a respiratory fuel nor a structural component of nucleic acids in the sense implied by the other options.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 134, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#134 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q135_135", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 135, "subject": "Biology", "topic": "pyruvate", "question": "Which of the following process does not need pyruvic acid as a substrate?", "options": ["Alcohol dermentation", "Calvin cycle", "Aerobic respiration", "Lactic acid dermentation"], "correctIndex": 1, "explanation": "The Calvin cycle is part of photosynthesis and does not use pyruvate as a substrate. Alcohol fermentation, lactic acid fermentation, and aerobic respiration all involve pyruvate as a key intermediate.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 135, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#135 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q136_136", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 136, "subject": "Biology", "topic": "electron transport chain", "question": "Which of the following is a copper containing protein in electron transport chain?", "options": ["Plastoquinone", "Cytochrome-C", "Plastocyanin", "Ferrodoxin"], "correctIndex": 2, "explanation": "Plastocyanin is a copper-containing electron carrier in the photosynthetic electron transport chain. Plastoquinone and ferredoxin are not copper proteins; cytochrome c contains heme iron rather than copper.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 136, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "PMC 2020 Q#136 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2020"}, {"id": "paper_q137_137", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 137, "subject": "Biology", "topic": "electron transport chain", "question": "In electron transport chain, ATP synthesis takes place when electron moves from", "options": ["Primary electron acceptor (PEA) to plastoquinone", "Plastoquinone (Pq) to cytochromes", "Cytochromes to plastocyanin", "Plastocyanin (Pc) to photosystem 1 (PS-I)"], "correctIndex": 1, "explanation": "The transfer of electrons from plastoquinone to the cytochrome b6f complex is associated with proton pumping across the thylakoid membrane, generating the proton gradient that drives ATP synthesis. Later transfers (e.g., cytochromes to plastocyanin) are less directly linked to proton translocation.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 137, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "PMC 2020 Q#137 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2020"}, {"id": "paper_q138_138", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 138, "subject": "Biology", "topic": "mendelian genetics", "question": "“law of independent assortment” states", "options": ["The each pari of alleles assort independent of other pairs of alleles during gamete formation", "That allele fo each pair of constrasting trait have unequal probability to assort with the alleles of other pairs", "That that coexisting alleles for each trait segregate (separate) from each other at meiosis so that each gamete receives only one of the two alleles", "That pertain to inheritance of single trait (monohybrid cross)"], "correctIndex": 0, "explanation": "Mendel's law of independent assortment states that alleles of different genes assort independently during gamete formation, so option (a) matches the law. Option (c) describes segregation (separation of alleles at a single locus) rather than independent assortment between loci.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 138, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "PMC 2020 Q#138 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2020"}, {"id": "paper_q139_139", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 139, "subject": "Biology", "topic": "basic terms", "question": "Phenotype is", "options": ["The genetic complement ie the genes in an individual for a particulartrait", "Partner of gene pair", "The form of appearance of a trait", "The position of a gene on the chromosome"], "correctIndex": 2, "explanation": "Phenotype refers to the observable characteristics or appearance resulting from genotype and environment, so option (c) is correct. Option (a) describes genotype.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 139, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#139 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q140_140", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 140, "subject": "Biology", "topic": "dominance", "question": "In complete dominance", "options": ["Differendt alleles of a gene are both expressesed in heterozygous condition", "One alleles (R) is completely dominant over the other (r) and the presence of recessive allele is functionally hidden the heterozygote (Rr) has the same sound phenotype (RR) heterozygote", "The phenotype of the heterozygote is intermediate between phenotypes of the homozygotes", "Gene mutation may produce many different alleles of a gene"], "correctIndex": 1, "explanation": "Complete dominance means the dominant allele masks the recessive allele in a heterozygote, so the heterozygote has the same phenotype as the homozygous dominant (option b). Option (c) describes incomplete (partial) dominance.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 140, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#140 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q141_141", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 141, "subject": "Biology", "topic": "nucleic acids", "question": "Which one of the following is found both messgenger RNA an DNA of a mammalian cell?", "options": ["Double helical structure", "Ribose sugar", "Thymine", "Sugar- phosphate backbone"], "correctIndex": 3, "explanation": "Both DNA and mRNA have a sugar-phosphate backbone. DNA has deoxyribose and is typically double helical (mRNA is single-stranded and uses ribose); thymine is in DNA but uracil replaces thymine in RNA.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 141, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "PMC 2020 Q#141 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2020"}, {"id": "paper_q142_142", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 142, "subject": "Biology", "topic": "germ line vs somatic", "question": "The cells in our body are all genetically identical apart from the", "options": ["Somatic cells", "Reproductive cells", "Muscle fibers", "White blood cells"], "correctIndex": 1, "explanation": "Most body (somatic) cells share the same genome; reproductive cells (gametes) differ because they are haploid and result from meiosis. The other listed somatic cell types are genetically similar to other somatic cells.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 142, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "PMC 2020 Q#142 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2020"}, {"id": "paper_q143_143", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 143, "subject": "Biology", "topic": "transcription", "question": "Transcription is the process in which an RNA copy of the DNA sequence and coding the gene is produced with help of an enzyme called:", "options": ["DNA polymerases", "RNA polymerase", "DNA transcriptase", "RNA trnscriptase"], "correctIndex": 1, "explanation": "RNA polymerase synthesizes RNA from a DNA template during transcription. DNA polymerases synthesize DNA, so option (a) is incorrect.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 143, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "PMC 2020 Q#143 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2020"}, {"id": "paper_q144_144", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 144, "subject": "Biology", "topic": "karyotype", "question": "Th particular array of chromosomes that an individual prossess is called its", "options": ["Genotype", "Phenotype", "Karyotype", "Allele"], "correctIndex": 2, "explanation": "A karyotype is the complete set or arrangement of chromosomes in an individual. Genotype refers to the genetic makeup at gene level, not the chromosomal array.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 144, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "PMC 2020 Q#144 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2020"}, {"id": "paper_q145_145", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 145, "subject": "Biology", "topic": "meiosis", "question": "During meiosis, the homologous chromosomes comes together and form pairs this process is called", "options": ["Linkage", "Synapsis", "Pairing", "Crossing over"], "correctIndex": 1, "explanation": "Synapsis is the pairing of homologous chromosomes during prophase I of meiosis. Crossing over is the exchange of segments between paired homologues, not the pairing process itself.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 145, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "PMC 2020 Q#145 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2020"}, {"id": "paper_q146_146", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 146, "subject": "Biology", "topic": "dna replication", "question": "At what phase the DNA content of a cell is doubled?", "options": ["Prophase", "Interphase", "Anaphase", "Telophase"], "correctIndex": 1, "explanation": "DNA replication occurs during the S phase of interphase, so the DNA content is doubled during interphase. The other listed phases are mitotic stages after replication.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 146, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "PMC 2020 Q#146 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2020"}, {"id": "paper_q147_147", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 147, "subject": "Biology", "topic": "transcription", "question": "Which statement correctly describes transcription of DNA?", "options": ["It produces aminon acids", "It produces messenger RNA", "It results in increased DNA synthesis", "It is a semi conservative process"], "correctIndex": 1, "explanation": "Transcription produces messenger RNA (mRNA) from a DNA template. It does not directly produce amino acids (translation does) nor is it DNA replication (semi-conservative).", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 147, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "PMC 2020 Q#147 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2020"}, {"id": "paper_q148_148", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 148, "subject": "Biology", "topic": "endosymbiont theory", "question": "This theory says that “mitochondria and chloroplast area in effect ancient bacteria which now live inside the large cells”", "options": ["Darwin’s theory of evolution", "Lamarckism", "Neo-darwinsm", "Endosymbiont theory"], "correctIndex": 3, "explanation": "The endosymbiont theory proposes that mitochondria and chloroplasts originated from free-living bacteria that became incorporated into ancestral eukaryotic cells. The other options are general evolutionary theories that do not state this origin.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 148, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "PMC 2020 Q#148 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2020"}, {"id": "paper_q149_149", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 149, "subject": "Biology", "topic": "analogous vs homologous", "question": "The organs which are similar but differ in structure are called", "options": ["Analogous organs", "Homologous organs", "Convergent evolution", "Divergent evolution"], "correctIndex": 0, "explanation": "Analogous organs have similar functions but different structural origins (e.g., wings of insects vs birds). Homologous organs share structural origin even if function differs.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 149, "syllabusUnit": "Unit 14: Evolution", "pmdcTopic": "Theories of Evolution, Natural Selection & Genetic Equilibrium", "textbookCitation": "PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8", "citationString": "PMC 2020 Q#149 | Unit 14: Evolution | PTB Biology XII Ch 24 (Evolution); Federal Biology XII Ch 8"}, "year": "2020"}, {"id": "paper_q150_150", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 150, "subject": "Biology", "topic": "natural selection", "question": "____ occurs because natural selection gives some alleles a batter chance of survival than others", "options": ["Fitness", "Evolution", "Crossing over", "Artificial selection"], "correctIndex": 1, "explanation": "Evolution is the change in allele frequencies over time driven by mechanisms such as natural selection, which favors some alleles. Fitness is a measure of reproductive success but not the process named here.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 150, "syllabusUnit": "Unit 13: Genetics & Molecular Biology", "pmdcTopic": "Mendelian & Non-Mendelian Genetics, DNA Structure & Linkage", "textbookCitation": "PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6", "citationString": "PMC 2020 Q#150 | Unit 13: Genetics & Molecular Biology | PTB Biology XII Ch 20 (Chromosomes & DNA) & Ch 22 (Inheritance); Federal Biology XII Ch 5-6"}, "year": "2020"}, {"id": "paper_q151_151", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 151, "subject": "Biology", "topic": "recombinant dna", "question": "The DNA that has been altered and which now contains length of nucleotides from two different organisms is called a", "options": ["Plasmid", "Combined DNA", "Vector", "Recombinant DNA"], "correctIndex": 3, "explanation": "Recombinant DNA refers to DNA molecules formed by joining genetic material from different sources. Plasmids and vectors can carry recombinant DNA but are not the general term for the altered DNA itself.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 151, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "PMC 2020 Q#151 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2020"}, {"id": "paper_q152_152", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 152, "subject": "Biology", "topic": "pcr", "question": "It is a method for rapid production of a very large number of copies of a particular fragment of DNA", "options": ["Gel electrophoresis", "Polymerase chain reaction", "DNA extraction", "Recombination"], "correctIndex": 1, "explanation": "The polymerase chain reaction (PCR) exponentially amplifies a specific DNA fragment, producing large numbers of copies. Gel electrophoresis separates fragments and is not an amplification method.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 152, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "PMC 2020 Q#152 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2020"}, {"id": "paper_q153_153", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 153, "subject": "Biology", "topic": "dna ligase", "question": "What is the effect of DNA ligase?", "options": ["DNA is broken up at specific sits", "DNA fragments are joined together", "DNA replication occurs", "DNA transcription occurs"], "correctIndex": 1, "explanation": "DNA ligase catalyzes the joining of DNA fragments by forming phosphodiester bonds, such as linking Okazaki fragments or sealing recombinant DNA. It does not break DNA or directly perform replication/transcription.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 153, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "PMC 2020 Q#153 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2020"}, {"id": "paper_q154_154", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 154, "subject": "Biology", "topic": "rDNA tools", "question": "Which of the following is the components/ tools of recombinant DNA technology?", "options": ["Gene of interest", "Molecular scissors", "Molecular glue and expression system", "All of the above"], "correctIndex": 3, "explanation": "Recombinant DNA technology requires a gene of interest, restriction enzymes ('molecular scissors'), ligases ('molecular glue'), and expression systems; thus all listed components are involved.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 154, "syllabusUnit": "Unit 2: Biological Molecules & Enzymes", "pmdcTopic": "Macromolecules, Enzyme Kinetics and Mechanisms", "textbookCitation": "PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3", "citationString": "PMC 2020 Q#154 | Unit 2: Biological Molecules & Enzymes | PTB Biology XI Ch 2 (Biological Molecules) & Ch 3 (Enzymes); Federal Biology XI Ch 2-3"}, "year": "2020"}, {"id": "paper_q155_155", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 155, "subject": "Biology", "topic": "gel electrophoresis", "question": "Gel electrophoresis is a technique", "options": ["Employed by forensic scientists to assist in the identification of the individuals by their respective type of DNA", "Collect all the genes found in one complete set of chromosomes", "Is a technique to separate different size fragment of charge bearing polymers (proteins, RNA or DNA)", "Grows single cells of a group of cells in a glass ware on artificial medium under aseptic conditions"], "correctIndex": 2, "explanation": "Gel electrophoresis separates charged molecules (DNA, RNA, proteins) by size and charge, so option (c) correctly describes the technique. While forensic scientists use it (option a), (c) is the general technical definition.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 155, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#155 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q156_156", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 156, "subject": "Biology", "topic": "transgenic organisms", "question": "Transgenic organisms", "options": ["Havae a foreigh gene inserted into them", "Have an important role in the large scale production of medicinal products", "Are considered beneficial to humans", "All of the above"], "correctIndex": 3, "explanation": "Transgenic organisms contain foreign genes and are used in biotechnology for production of therapeutics and other benefits, so all statements are true; hence option (d) is correct.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 156, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#156 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q157_157", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 157, "subject": "Biology", "topic": "pcr reagents", "question": "Which of the following is not necessary for PCR to occur?", "options": ["dATP", "primers", "DNA fragments", "Ribonucleotides"], "correctIndex": 3, "explanation": "PCR requires deoxyribonucleotides (dATP, dTTP, etc.), primers, and a DNA template; ribonucleotides (RNA building blocks) are not required. Thus ribonucleotides are not necessary.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 157, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#157 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q158_158", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 158, "subject": "Biology", "topic": "glycolysis", "question": "The end product of glycolysis in acrobic respiration is", "options": ["Ethanol and carbon dioxide", "Lactate", "Pyruvate", "Acetyl CoA"], "correctIndex": 2, "explanation": "Glycolysis converts glucose to pyruvate under aerobic conditions; pyruvate is then further processed (e.g., to acetyl-CoA). Ethanol and lactate are products of anaerobic pathways.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 158, "syllabusUnit": "Unit 3: Bioenergetics", "pmdcTopic": "Photosynthesis, Cellular Respiration & ATP Synthesis", "textbookCitation": "PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11", "citationString": "PMC 2020 Q#158 | Unit 3: Bioenergetics | PTB Biology XI Ch 11 (Bioenergetics); Federal / KPK Biology XI Ch 11"}, "year": "2020"}, {"id": "paper_q159_159", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 159, "subject": "Biology", "topic": "viruses", "question": "Which of the following is not related enveloped virus?", "options": ["They survive for a short time", "Their envelop is sensitive to sunlight", "They are tolerant to antidotes", "Envelop is derived from host"], "correctIndex": 2, "explanation": "Enveloped viruses are generally fragile in the environment and have envelopes derived from host membranes; they are not 'tolerant to antidotes' (option 3 is nonsensical/incorrect). Options 1,2,4 are related properties.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 159, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "PMC 2020 Q#159 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2020"}, {"id": "paper_q160_160", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 160, "subject": "Biology", "topic": "aids", "question": "Numerous opportunistic diseases might attack a persone suffering from which of the following disease?", "options": ["Measles", "Influenza", "Hepatitits A", "AIDS"], "correctIndex": 3, "explanation": "AIDS leads to severe immune deficiency, making patients susceptible to many opportunistic infections. The other diseases listed do not typically cause the same broad immune compromise.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 160, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#160 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q161_161", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 161, "subject": "Biology", "topic": "virion", "question": "The complete, mature and infection virus particle is known as", "options": ["Venome", "Genome", "Virion", "Capsid"], "correctIndex": 2, "explanation": "A virion is a complete, infectious virus particle. The capsid is the protein shell only, and genome is the nucleic acid component; 'venome' is not a correct term here.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 161, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "PMC 2020 Q#161 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2020"}, {"id": "paper_q162_162", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 162, "subject": "Biology", "topic": "hiv", "question": "Which of the following is not TRUE about Human Immunodeficiency virus ( HIV)?", "options": ["It is retrovirus", "It is surrounded by an envelop", "It does not cause AIDS", "It causes the deficiency of the human immune system"], "correctIndex": 2, "explanation": "Statements (a), (b), and (d) are true about HIV; statement (c) 'It does not cause AIDS' is false. HIV is a retrovirus with an envelope and causes immune deficiency leading to AIDS.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 162, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "PMC 2020 Q#162 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2020"}, {"id": "paper_q163_163", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 163, "subject": "Biology", "topic": "sterilization methods", "question": "Select a method which cause the oxidation of constituent of a bacterial cell", "options": ["Steam", "Filtration", "Dry heat", "Radiation"], "correctIndex": 2, "explanation": "Dry heat sterilization acts by oxidation of cellular components (combustion/oxidation), while moist heat (steam) coagulates proteins. Filtration removes organisms and radiation damages nucleic acids.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 163, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "PMC 2020 Q#163 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2020"}, {"id": "paper_q164_164", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 164, "subject": "Biology", "topic": "bacterial structure", "question": "Which of the following is TRUE about the structure if typical bacterium?", "options": ["It has a cell wall", "It has cytoplasm", "It has genetic material", "All of the above"], "correctIndex": 3, "explanation": "Typical bacteria possess a cell wall, cytoplasm, and genetic material (usually a circular chromosome), so all statements apply and option (d) is correct.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 164, "syllabusUnit": "Unit 4: Acellular Life & Prokaryotes", "pmdcTopic": "Viruses, Retroviruses, Bacterial Structure and Pathogenicity", "textbookCitation": "PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6", "citationString": "PMC 2020 Q#164 | Unit 4: Acellular Life & Prokaryotes | PTB Biology XI Ch 5 (Variety of Life) & Ch 6 (Kingdom Monera); Federal Biology XI Ch 5-6"}, "year": "2020"}, {"id": "paper_q165_165", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 165, "subject": "Biology", "topic": "red algae", "question": "Red algae do not contribute towards", "options": ["Making coral reefs", "Forming limestone deposits", "Making fertilizers", "Forming chalk deposits"], "correctIndex": 3, "explanation": "Red algae (coralline algae) contribute to coral reef formation and limestone deposits and have uses as fertilizers/soil conditioners; chalk deposits are typically formed from coccolithophores (not red algae), so option (d) is the best choice.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 165, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#165 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q166_166", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 166, "subject": "Biology", "topic": "amoeba", "question": "Which of the following is true about amoeba?", "options": ["They havae flagella", "They are multicellular", "They do not cause any disease in humans", "They move by forming specialized cytoplasmic projections called pseudopodia"], "correctIndex": 3, "explanation": "Amoebae move using pseudopodia (cytoplasmic projections). They are unicellular and some amoebae can cause human disease; they do not typically have flagella.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 166, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#166 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q167_167", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 167, "subject": "Biology", "topic": "taxis", "question": "The directional movement toward or away from the stimulus is called", "options": ["Tropism", "Orientation", "Taxis", "Non orientation"], "correctIndex": 2, "explanation": "Taxis refers to directional movement of an organism toward or away from a stimulus. Tropism is a directional growth response in plants rather than movement of whole organisms.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 167, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#167 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q168_168", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 168, "subject": "Biology", "topic": "thylakoid", "question": "Photophosphorylation takes place in the ____ of the chloroplasts", "options": ["Stroma", "Granum", "Inner membrane", "Outer membrane"], "correctIndex": 1, "explanation": "Photophosphorylation occurs in the thylakoid membranes stacked as grana (granum) where the light reactions generate a proton gradient for ATP synthesis. The stroma is the site of the Calvin cycle.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 168, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "PMC 2020 Q#168 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2020"}, {"id": "paper_q169_169", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 169, "subject": "Biology", "topic": "anamniotes", "question": "Select an anamniote from the following", "options": ["Snake", "Frog", "Parrot", "Crocodile"], "correctIndex": 1, "explanation": "Anamniotes (e.g., amphibians like frogs) do not produce an amniotic egg; reptiles and birds (snakes, crocodiles, parrots) are amniotes. Therefore frog (option b) is the anamniote.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 169, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#169 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q170_170", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 170, "subject": "Biology", "topic": "water transport", "question": "In roots the apoplast pathway of water is disrupted when water reaches", "options": ["Plasmodesmata", "Cortex", "Endodermis", "Pith"], "correctIndex": 2, "explanation": "The Casparian strip in the endodermis blocks the apoplast pathway, forcing water into the symplast for regulated uptake; thus the apoplast pathway is disrupted at the endodermis.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 170, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#170 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}, {"id": "paper_q171_171", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 171, "subject": "Biology", "topic": "heart structure", "question": "Regarding structure of human heart chordae tendinea are present in", "options": ["Atria", "Pulmonary valvea", "Ventricles", "Aortic valve"], "correctIndex": 2, "explanation": "Chordae tendineae attach to atrioventricular (mitral and tricuspid) valves and papillary muscles found in the ventricles, preventing valve prolapse during ventricular contraction.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 171, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "PMC 2020 Q#171 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2020"}, {"id": "paper_q172_172", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 172, "subject": "Biology", "topic": "cardiovascular system", "question": "The only vein in human body carrying oxygenated blood is", "options": ["Femoral", "Pulmonary", "Renal", "Iliac"], "correctIndex": 1, "explanation": "Pulmonary veins carry oxygenated blood from the lungs to the left atrium; systemic veins like femoral, renal, iliac carry deoxygenated blood back to the heart.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 172, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "PMC 2020 Q#172 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2020"}, {"id": "paper_q173_173", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 173, "subject": "Biology", "topic": "lymphocytes", "question": "The cells which play very important in developing immunity are", "options": ["Monocytes", "Neutrophils", "Lymphocytes", "Thrombocytes"], "correctIndex": 2, "explanation": "Lymphocytes (B and T cells) are central to adaptive immunity and the development of specific immune responses; neutrophils and monocytes are innate immune cells, and thrombocytes (platelets) are involved in clotting.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 173, "syllabusUnit": "Unit 1: Cell Structure and Function", "pmdcTopic": "Cell Structure, Organelles & Endomembrane System", "textbookCitation": "PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4", "citationString": "PMC 2020 Q#173 | Unit 1: Cell Structure and Function | PTB Biology XI Ch 4 (The Cell); Federal / Sindh Biology Book I Ch 1-4"}, "year": "2020"}, {"id": "paper_q174_174", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 174, "subject": "Biology", "topic": "blood pressure", "question": "Which of the following blood vessels have the highest pressure of blood?", "options": ["Aorta", "Pulmonary arteries", "Pulmonary veins", "Vena cava"], "correctIndex": 0, "explanation": "The aorta, as the main systemic artery leaving the left ventricle, experiences the highest blood pressure. Pulmonary vessels and the vena cava have much lower pressures.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 174, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "PMC 2020 Q#174 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2020"}, {"id": "paper_q175_175", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 175, "subject": "Biology", "topic": "autoimmunity", "question": "Autoimmune disease act at the principle of", "options": ["Self against antigens", "Antigens against self", "Self against self", "Antigens self-dstroyed"], "correctIndex": 2, "explanation": "Autoimmune diseases result from immune responses against the body's own tissues-'self against self'-making option (c) correct. The other phrasings are incorrect descriptions.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 175, "syllabusUnit": "Unit 7: Human Physiology - Immunity", "pmdcTopic": "Innate & Adaptive Immunity, Immunoglobulins and Vaccines", "textbookCitation": "PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14", "citationString": "PMC 2020 Q#175 | Unit 7: Human Physiology - Immunity | PTB Biology XI Ch 14 (Immunity Section); Federal Biology XI Ch 14"}, "year": "2020"}, {"id": "paper_q176_176", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 176, "subject": "Biology", "topic": "heart chambers", "question": "In human heart, the left atrium receives", "options": ["The superior Vena Cava", "The inferior Vena Cava", "The coronary sinus", "The four pulmonary veins"], "correctIndex": 3, "explanation": "The left atrium receives oxygenated blood from the lungs via the four pulmonary veins. The vena cavae and coronary sinus drain into the right atrium, not the left.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 176, "syllabusUnit": "Unit 6: Human Physiology - Circulation & Transport", "pmdcTopic": "Cardiovascular System, Blood Vessels and Cardiac Cycle", "textbookCitation": "PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14", "citationString": "PMC 2020 Q#176 | Unit 6: Human Physiology - Circulation & Transport | PTB Biology XI Ch 14 (Transport); Federal Biology XI Ch 14"}, "year": "2020"}, {"id": "paper_q177_177", "paperTitle": "PMC MDCAT 2020 (Paper)", "shortTitle": "PMC 2020", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "questionNumber": 177, "subject": "Biology", "topic": "antibodies", "question": "Antibodies are manufactured in", "options": ["T lymphocytes", "Red blood cells", "Platelets", "B lymphocytes"], "correctIndex": 3, "explanation": "Antibodies (immunoglobulins) are produced by B lymphocytes (specifically plasma cells derived from B cells). T lymphocytes help regulate responses but do not secrete antibodies.", "reference": {"sourcePaper": "PMC MDCAT 2020 (Paper)", "paperCode": "Paper", "authority": "Pakistan Medical Commission", "province": "National", "originalQuestionNumber": 177, "syllabusUnit": "Unit: General Biology & Biotechnology", "pmdcTopic": "Biological Principles & Practical Applications", "textbookCitation": "PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines", "citationString": "PMC 2020 Q#177 | Unit: General Biology & Biotechnology | PTB Biology XI/XII Relevant Sections; PMDC MDCAT Biology Guidelines"}, "year": "2020"}];
